\section{Proofs of Main Results}

For a matrix $M\in\mathbb{R}^{n\times n}$,
let $\bar{\rho}(M)$ denote its \emph{spectral radius}, the largest of the magnitudes of its $n$ eigenvalues. Let $\lVert M \rVert$ denote its \emph{spectral norm}, its largest singular value. When $M$ is positive semi-definite, then $\rho_n(M)=\bar{\rho}(M) = ||M||$.

\subsection{Assumptions with General Weighting Matrix}
\label{subsubsec:pw.ass}

For the clarity of graphical interpretations of the Assumptions, theoretical results are given for the leading case $W=W_{a+b}$ and $W_{b}$ only in the paper. The proofs in this Appendix are for a general weighting matrix under Assumptions~\ref{ass:graph.connect.1} and \ref{ass:graph.connect.2} below. We first show that Assumptions~\ref{ass:graph.connect.1} and \ref{ass:graph.connect.2} are implied by Assumptions \ref{ass:graph.connect.1.full} -- \ref{ass:graph.connect.2.c} when $W=W_{a+b}$ and $W=W_{b} $. Subsequently, we prove Theorem~\ref{thm:pw} under Assumption~\ref{ass:graph.connect.1} and prove Lemma~\ref{lm:unif.convg}, Theorem~\ref{thm:main}, and Corollary \ref{cor:reg} under Assumptions~\ref{ass:graph.connect.1} and \ref{ass:graph.connect.2}, while keeping Assumptions~\ref{ass:reg.cond} and \ref{ass.degree} throughout.


\begin{assumption}
	\emph{(i).}\label{ass:graph.connect.1}
	$(r+c)\cdot \bar{\rho}^2(W^{1/2}L^-W^{1/2}) = o(1)$, \newline
	\emph{(ii).}
	$ (r+c)\cdot \bar{\rho}(W) \le M$ for some finite $M$, \newline
	\emph{(iii).} $ \epsilon <  (r+c)\cdot\bar{\rho}(W^{1/2}L^-W^{1/2})$ for some $\epsilon>0$.
\end{assumption}


\begin{assumption}
	\label{ass:graph.connect.2}
	\emph{(i).} 	$(r+c) \cdot \tr( [W^{1/2}L^- W^{1/2}]^2 )= O(1)$, \newline
	\emph{(ii).} $(r+c)^{-1}\cdot\tr([L^\dagger]^{\epsilon} )= O(1)$ for some $\epsilon>0$.
\end{assumption}




\begin{lemma} \emph{(i).} \label{Lemma: A- eig1}
	Assumption~\ref{ass:graph.connect.1} is implied by Assumption~\ref{ass:graph.connect.1.full} when $W=W_{a+b}$; and  by Assumption~\ref{ass.degree} and \ref{ass:graph.connect.1.b} when $W=W_{b}$. \newline \emph{(ii).} Assumption~\ref{ass:graph.connect.2} is implied by Assumptions~\ref{ass:graph.connect.1.full} and \ref{ass:graph.connect.2.a} when $W=W_{a+b}$; and
	by Assumptions~\ref{ass:graph.connect.1.b}, \ref{ass:graph.connect.2.a},  \ref{ass:graph.connect.2.b}, and \ref{ass:graph.connect.2.c} when $W=W_{b}$.
\end{lemma}

\begin{remark}
	Because $W$ builds in the normalization, such as $1/(r+c)$ for $W_{a+b}$ and $1/c$ for $W_{b}$, Assumption~\ref{ass:graph.connect.1}(ii) simply requires the standard condition that the selection matrix taking the parameter of interest out of $\bs{\theta}$ has bounded eigenvalues.  Similarly, because $W$ builds in the normalization, Assumption~\ref{ass:graph.connect.1}(iii) essentially requires a finite upper bound for the eigenvalues of $L$ (or the selected counterpart of $L$). If we drop Assumption~\ref{ass:graph.connect.1}(iii), the convergence rate in Theorem~\ref{thm:pw} changes from $\delta_{r,c}^2$ to $\delta_{r,c}$, however, the pointwise convergence still holds and the uniform convergence and asymptotic optimality in Lemma~\ref{lm:unif.convg} and Theorem \ref{thm:main} are unaffected.

\end{remark}

%\begin{remark}
%	Assumption~\ref{ass:graph.connect.1}(iii) simply requires that the parameter of interest, as represented by the selection matrix, is of asymptotically non-negligible size. This assumption is however not essential for our results, and can be removed at the expense of changing the rate in Theorem~\ref{thm:pw} from $\delta_{r,c}^2$ to $\delta_{r,c}$. The only proof modification corresponding to this change will be in \eqref{eq:UC1.pf.1}. 
%\end{remark}

\begin{remark}
	The trace condition in Assumption~\ref{ass:graph.connect.2} allows the number of unbounded eigenvalues of $W^{1/2}L^{-}W^{1/2}$ to go to infinity as $r,c \rightarrow \infty$. Assumptions~\ref{ass:graph.connect.2.a} and \ref{ass:graph.connect.2.b} only allow for an bounded number of small eigenvalues of $L$ and $L_{2,\perp}$ such that this trace condition is implied by that on the largest eigenvalues in Assumption~\ref{ass:graph.connect.1}. We can maintain Assumption ~\ref{ass:graph.connect.2} by letting the number of unbounded eigenvalues grow slowly and tightening the rate condition in Assumption ~\ref{ass:graph.connect.1}.
\end{remark}


\begin{proof}[Proof of Lemma \ref{Lemma: A- eig1}]
	We first study the case 
	$W= W_{a+b}=\frac{1}{r+c}I_{r+c}$. In this case, 
	\begin{equation}\label{gencond1}
		(r+c)\cdot\bar{\rho}^2(W^{1/2}L^-W^{1/2})
		=\frac{1}{r+c}\bar{\rho}^2(\mathcal{R}L^{\dagger}\mathcal{R}')
		\le M\frac{1}{(r+c)\cdot\rho_2^2(L)}
	\end{equation} 
	for some finite $M$ following $||\mathcal{R}||^2\le M$, see \eqref{eq:I1}, and the smallest non-zero eigenvalue of $L$, denoted by $\rho_2(L)$, is the largest eigenvalue of the Moore-Penrose generalized inverse $L^{\dagger}$. This verifies Assumption~\ref{ass:graph.connect.1}(i).
	Assumption~\ref{ass:graph.connect.1}(ii) holds because
	$(r+c)\bar{\rho}(W) = 1$.
	Assumption~\ref{ass:graph.connect.1}(iii) holds because $(r+c)\bar{\rho}(W^{1/2}L^-W^{1/2}) = \bar{\rho}(L^-)$ which is of the same order as $1/\rho_2(L)$, and $\rho_2(L)$ is bounded %from above by $\bar{d}<\infty$, the maximum diagonal entry of $L$, which is finite in the asymptotic analysis by
	under Assumption~\ref{ass.degree}.

	Assumption 	\ref{ass:graph.connect.2}(i) is implied by Assumption~\ref{ass:graph.connect.1.full} and Assumption~\ref{ass:graph.connect.2.a}, i.e., the number of diverging eigenvalues of $L^{\dagger}$ is finite. 
	Assumption \ref{ass:graph.connect.2}(ii) holds with $\epsilon=2$ under Assumption~\ref{ass:graph.connect.1.full} and Assumption~\ref{ass:graph.connect.2.a}.

	Next, we consider $W= W_b$, i.e., we are interested in the estimation of $\bs{\beta}$. In this case,
	\begin{equation}
		W^{1/2}L^-W^{1/2}
		=\frac{1}{c}
		\begin{bmatrix}
			0_{r\times r} & 0_{r\times c} \\
			0_{c\times r} & [\mathcal{R}L^\dagger \mathcal{R}']_{2}
		\end{bmatrix}
		=\frac{1}{c}
		\begin{bmatrix}
			0_{r\times r} & 0_{r\times c} \\
			0_{c\times r} & M_c[L_{2,\perp}]^\dagger M_c 
		\end{bmatrix},
		\label{eq:partition}
	\end{equation}
	where $ [\mathcal{R}L^\dagger \mathcal{R}']_{2}=M_c[L_{2,\perp}]^\dagger M_c$ follows from Lemma~\ref{lm:equalities}. Because the demeaning matrix $M_c$ has bounded eigenvalues, we know 
	\begin{equation} \label{eq: verifyB2}
		(r+c)\cdot\bar{\rho}^2(W^{1/2}L^-W^{1/2})
		\le M \frac{1}{c\cdot\rho_2^2(L_{2,\perp})},
	\end{equation}
	for some finite $M$, which shows that Assumption~\ref{ass:graph.connect.1}(i) is implied by Assumption~\ref{ass:graph.connect.1.b}. 
	Assumption~\ref{ass:graph.connect.1}(ii) holds because
	$(r+c)\bar{\rho}(W) = (r+c)/r=O(1)$ by Assumption~\ref{ass.degree}.
	Assumption~\ref{ass:graph.connect.1}(iii) holds because by the same arguments as in \eqref{eq: verifyB2},  $(r+c)\bar{\rho}(W^{1/2}L^-W^{1/2})$ is of the same order as $1/\rho_2(L_{2,\perp})$, and $\rho_2(L_{2,\perp})$ is bounded under Assumption~\ref{ass.degree}. %from above by $\bar{d}$. 

	Assumption 	\ref{ass:graph.connect.2}(i) is implied by Assumption~\ref{ass:graph.connect.1.b} and Assumption~\ref{ass:graph.connect.2.b}, i.e., the number of diverging eigenvalues of $L_{2,\perp}^{\dagger}$ is finite. 
	Assumption \ref{ass:graph.connect.2}(ii) follows from Assumptions~\ref{ass:graph.connect.2.a} and \ref{ass:graph.connect.2.c}, i.e., for the full graph, the number of diverging eigenvalues of $L^{\dagger}$ is finite and its largest eigenvalue satisfy the rate condition in \ref{ass:graph.connect.2.c}.
\end{proof}



\subsection{Proof of Pointwise Convergence}

\begin{proof}[Proof of Theorem \ref{thm:pw}] Theorem~\ref{thm:pw} follows immediately from Lemma~\ref{lm:decomp}, Lemma~\ref{lm:UC1}, and the Cauchy-Schwarz inequality. 
\end{proof}		


Without loss of generality, we set $\sigma^2=1$ in the proof.
To analyze the difference between $l_w(\hat{\bs{\theta}}(\bs{\lambda}),\bs{\theta})$ and $\text{URE}(\bs{\lambda})$,  define 
\begin{align}
	\mathcal{D}_1 (\bs{\lambda}) &= [\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}]^\prime W [\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}] -
	\tr[WL^- ] , \ \ 
	\mathcal{D}_2 (\bs{\lambda}) = (S \bs{v})^\prime W [\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}],
	\nonumber \\
	\mathcal{D}_3 (\bs{\lambda})&= [S\bs{\theta}]^\prime W [\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}], \ \ 
	\mathcal{D}_4 (\bs{\lambda}) = [S_1(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})]^\prime W [\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}]
	- \tr[S_1L ^- W ].
\end{align}

\begin{lemma}[Decomposition of L -- URE]
	\label{lm:decomp}
	$l_w(\hat{\bs{\theta}}(\bs{\lambda}),\bs{\theta})-\text{URE}(\bs{\lambda})$ can be written as 
	\begin{equation*}
		\begin{aligned}
			l_w(\hat{\bs{\theta}}(\bs{\lambda}),\bs{\theta})-\text{URE}(\bs{\lambda})		
			=  -\mathcal{D}_1(\bs{\lambda}) +2 \mathcal{D}_2(\bs{\lambda})-2\mathcal{D}_3(\bs{\lambda}) +2 \mathcal{D}_4(\bs{\lambda}).
		\end{aligned}
	\end{equation*}
\end{lemma}



Define 
$
\delta_{r,c}^{-1}= (r+c)^{1/2} \cdot\bar{\rho}(W^{1/2}L^-W^{1/2}),
$ where $\delta_{r,c}^{-1}=o(1)$ under Assumption~\ref{ass:graph.connect.1}.
By \eqref{gencond1} and \eqref{eq:partition}, $\delta_{r,c}$ defined here is equivalent to those in the main paper with the multiplication of a constant bounded from above and below, because $r$ and $c$ are of the same asymptotic order under Assumption~\ref{ass.degree}. Because $\delta_{r,c}$  only appears as an asymptotic order in all results, we can ignore such a difference in the definition.



\begin{lemma}
	\label{lm:UC1}
	Suppose Assumptions~\ref{ass:reg.cond}, \ref{ass.degree}, and \ref{ass:graph.connect.1} hold. For $k=1, 2, 3, 4$, we have
	$\sup_{\bs{\lambda}\in\mathcal{J}}
	\mathbb{E}_{\bs{\theta}, B}
	\left[	\mathcal{D}_k ^2(\bs{\lambda}) \right]
	= O\left(
	\delta_{r,c}^{-2}
	\right).
	$
\end{lemma} 	


The following auxiliary results in Lemma \ref{lm:pw.equalities} are used in the proof of Lemma \ref{lm:UC1}.
\begin{lemma}

	\label{lm:pw.equalities}

	%			\tr[(B L^-\mathcal{R}_b^\prime\mathcal{R}_b L^-B^\prime)^2] 
	%			&=
	%			\tr[(B_\perp^\prime B_\perp)^-(B_\perp^\prime B_\perp)^-]
	%			\label{eq:E7} \\



	\noindent \emph{(a)}. 
	$	\hat{\bs{\theta}}^{\emph{ls}}-\bs{\theta} 
	=
	\mathcal{R} L^-B^\prime \bs{U}.
	$
	\label{eq:E8}
	%			\\
	%			(B_\perp^\prime B_\perp)^\dagger
	%			&=
	%			\begin{bmatrix}
