		%				0_{c\times r} & (B_{2,\perp}^\prime B_{2,\perp})^\dagger
		%			\end{bmatrix}
	%			\label{eq:E9} 


	\noindent \emph{(b).} $\text{For generic matrix $A$, }\mathbb{V}[\bs{U}^\prime A \bs{U}]
	\leq
	(\mathbb{E}[u_{it}^4] + 2\sigma^2\sqrt{\mathbb{E}[u_{it}^4] - \sigma^4})\tr[A'A]$.

	\noindent	\emph{(c)}.	$S_1 = \mathcal{R}B^\dagger G B,
	\text{ where } G:= B\Lambda^{*-1}B'[B\Lambda^{*-1}B' + I]^{-1},$ and $|| G || 
	\leq 1.$


\end{lemma}

\begin{proof}[Proof of Lemma \ref{lm:UC1}]
	Because $\mathcal{D}_1$ does not depend on $\bs{\lambda}$, we have
	\begin{equation}
		\begin{aligned}[b]
			\mathbb{E}_{\bs{\theta}, B}
			\left[	\mathcal{D}_1 ^2(\bs{\lambda}) \right]&= \mathbb{E}_{\bs{\theta}, B}
			\left[	\left(
			[\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}]^\prime W
			[\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}]
			-\tr[W L^-]
			\right)^2 \right]\\
			&=_{(1)}
			\mathbb{V}_{\bs{\theta}, B}
			\left[
			[\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}]^\prime W [\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}]
			\right]
			=_{(2)}
			\mathbb{V}_{\bs{\theta}, B}
			\left[\bs{U}^\prime B L^- W  L^- B^\prime \bs{U} \right]\\
			&\leq_{(3)}
			M
			\tr[L^- W L^- W] 
			\leq_{(4)}
			M\cdot 
			(r+c) \cdot\bar{\rho}^2(W^{1/2}L^-W^{1/2})= O\left(
			\delta_{r,c}^{-2}
			\right),
		\end{aligned}
	\end{equation}
	where $=_{(1)}$ uses the fact that the second moment of a mean-zero variable is its variance; the equality $=_{(2)}$ uses Lemma \ref{lm:pw.equalities}(a);  the inequality $\leq_{(3)}$ uses Lemma \ref{lm:pw.equalities}(b), and $\leq_{(4)}$ uses
	for $V_1\in\mathbb{R}^{n\times n}$ and psd $V_2\in\mathbb{R}^{n\times n}$, 
	$\left|\tr[V_1V_2] \right|\leq \lVert V \rVert\tr[V_2]$, an inequality used repeatedly below.


	Since $S+S_1 = \mathcal{R}$, we have
	\begin{equation}
		\mathcal{D}_2(\bs{\lambda}) =(S \bs{v})^\prime W \left[\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}\right] 
		= \bs{v}^\prime W \left[\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}\right]- 
		(S_1 \bs{v})^\prime W \left[\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}\right],
	\end{equation}
	where the first term on the right hand side satisfies
		\begin{align}\label{eq:UC1.pf.1} 
			\mathbb{E}_{\bs{\theta}, B}
			\left[
			\left(\bs{v}^\prime W [\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}]
			\right)^2\right] 
			&=_{(1)}
			\mathbb{V}_{\bs{\theta}, B}
			\left[
			\bs{v}^\prime W [\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}]
			\right] 
			=
			\bs{v}' W L^- W \bs{v} \nonumber\\
			&\leq_{(2)}
			\bs{v}^\prime W \bs{v} 
			\cdot 
			\bar{\rho}(W^{1/2}L^-W^{1/2}) 
			 \leq_{(3)} r\bar{\mu}^2  \bar{\rho}(W) \cdot \bar{\rho}(W^{1/2}L^-W^{1/2}) \nonumber\\
			&\leq_{(4)}  M \cdot \delta_{r,c}^{-2} \frac{1}{(r+c)\bar{\rho}(W^{1/2}L^-W^{1/2})} 
			=_{(5)} O(\delta_{r,c}^{-2}),
		\end{align}		
	where $=_{(1)}$ uses the fact that the second moment of a mean-zero variable is its variance,  $\leq_{(2)}$ uses 
	$\left|\bs{x}^\prime V \bs{x} \right|
	\leq \bs{x}^\prime \bs{x} \cdot \lVert V \rVert$, an inequality used repeatedly in the proofs, $\leq_{(3)}$ uses that $||v||^2 \le r \bar{\mu}^2$, $=_{(4)}$ follows from $r\bar{\rho}(W)=O(1)$ by Assumption~\ref{ass:graph.connect.1}(ii) and $=_{(5)}$ follows from Assumption~\ref{ass:graph.connect.1}(iii).
	The second term satisfies
	\begin{equation}
		\begin{aligned}[b]
			&\hspace{1.5em}
			\mathbb{E}_{\bs{\theta}, B}
			\left[	\left(
			(S_1\bs{v})^\prime W \left[\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}\right]
			\right)^2\right] 
			=_{(1)}
			\mathbb{V}_{\bs{\theta}, B}
			\left[
			(S_1\bs{v})^\prime W \left[\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}\right]
			\right] 
			=
			(S_1 \bs{v})^\prime 
			W L^- W 
			(S_1 \bs{v}) \\
			&=_{(2)}
			\bs{v}'
			B' G B^{\dagger'} \mathcal{R}' WL^-W \mathcal{R}  B^\dagger G B 
			\bs{v} 
			\leq
			||G||^2 ||B||^2 
			||\bs{v}||^2 \bar{\rho}(B^{\dagger'} \mathcal{R}' WL^-W \mathcal{R}  B^\dagger) \\
			&\leq_{(3)}
			M\cdot
			r \cdot \bar{\rho}(B^{\dagger'} \mathcal{R}' WL^-W \mathcal{R}  B^\dagger)
			= M \cdot
			r \cdot \bar{\rho}^2(W^{1/2} L^- W^{1/2})=O\left(
			\delta_{r,c}^{-2}
			\right),
		\end{aligned} \label{A.31}
	\end{equation}
	where  $=_{(1)}$ uses the fact that the second moment of a mean-zero random variable is its variance, $=_{(2)}$ uses Lemma \ref{lm:pw.equalities}(c), $\leq_{(3)}$ holds for a finite constant $M$ using $||B||$ is bounded by Assumption~\ref{ass.degree}, $||G||\le 1$ by Lemma \ref{lm:pw.equalities}(d), $||v||^2 \le r \bar{\mu}^2$, and the final $	\delta_{r,c}^{-2}$ terms follows from $r/c$ is bounded from above and below by Assumption~\ref{ass.degree}.
	%\eqref{eq:I2} and \eqref{eq:I9}.


	The proof for $\mathcal{D}_3(\bs{\lambda})$ follows through the same argument as that for 
	$\mathcal{D}_2$ with $v$ replaced by $\theta$, $||v||^2 \le r \bar{\mu}^2$ replaced with $||\theta||^2 \le (r+c) M$  for some constant $M$ by Assumption~\ref{ass:reg.cond}.

	To study $\mathcal{D}_4$, we have
	\begin{align}
		&\hspace{1.5em} 
		\mathbb{E}_{\bs{\theta}, B}
		\left[	\mathcal{D}_4 ^2 (\bs{\lambda})\right]=\mathbb{E}_{\bs{\theta}, B}
		\left[
		\left(
		[S_1(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})]^\prime W [\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}]
		-\tr[S_1 L^- W]
		\right)\right]^2  \nonumber \\
		&=\mathbb{V}_{\bs{\theta}, B}
		\left[
		[S_1(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})]^\prime W [\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}] \right] \nonumber 
		=_{(1)}
		\mathbb{V}_{\bs{\theta}, B}
		\left[
		[\mathcal{R}L^- B'\bs{U}]^\prime(S_1^\prime W)
		[\mathcal{R}L^- B'\bs{U}] \right] \nonumber\\
		&\leq_{(2)}
		M \cdot
		\tr\left[
		\left( BL^- S_1'WL^-B' \right)'\left( BL^- S_1'WL^-B' \right)
		\right] 
		=
		M \cdot
		\tr\left[
		WS_1L^-S_1'WL^- \right] \nonumber \\
		&=_{(3)}
		M \cdot
		\tr\left[
		W \mathcal{R} B^\dagger G B L^- B' G B^{\dagger'} \mathcal{R}' W L^-\right] 
		\leq
		M
		\cdot 
		|| G B L^- B' G ||
		\tr\left[
		B^{\dagger'}\mathcal{R}' WL^-W \mathcal{R} B^{\dagger} \right] \nonumber \\
		&\leq_{(4)}
		M
		\cdot 
		\tr\left[
		(W^{1/2} L^- W^{1/2})^2 \right] 
		\leq
		M
		\cdot 
		(r+c) \cdot \bar{\rho}^2(W^{1/2} L^- W^{1/2}) = O\left(
		\delta_{r,c}^{-2}
		\right),
	\end{align}
	where $=_{(1)}$ follows from Lemma 	\ref{lm:pw.equalities}(a), $\leq_{(2)}$ follows from Lemma \ref{lm:pw.equalities}(b),  $=_{(3)}$ follows from Lemma  \ref{lm:pw.equalities}(c), and $\leq_{(4)}$ follows from Lemma  \ref{lm:pw.equalities}(c), $BL^- B'$ being a projection matrix, and $\mathcal{R}B^{\dagger} B^{\dagger'}\mathcal{R}' =\mathcal{R}L^{\dagger}\mathcal{R}'=L^{-}$.
\end{proof}



\subsection{Proof of Uniform Convergence and Asymptotic Optimality}

\begin{proof}[Proof of Theorem \ref{thm:main}]
	We first show that asymptotic optimality follows immediately from the uniform convergence in Lemma~\ref{lm:unif.convg}. To see this, note that
	\begin{equation}
		\begin{aligned}
			& \hspace{1.5em} \mathbb{E}_{\bs{\theta},B}
			\left[
			l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\text{ure}}),\bs{\theta}) 
			\geq
			l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\text{ol}}),\bs{\theta}) 
			+
			\epsilon
			\right] \\
			& = 
			\mathbb{E}_{\bs{\theta},B}
			\left[
			l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\text{ure}}),\bs{\theta}) 
			- \text{URE}(\bs{\lambda}^{\text{ure}})
			\geq
			l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\text{ol}}),\bs{\theta}) 
			- \text{URE}(\bs{\lambda}^{\text{ure}})
			+
			\epsilon
			\right] \\
			& \leq _{(1)}
			\mathbb{E}_{\bs{\theta},B}
			\left[
			l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\text{ure}}),\bs{\theta}) 
			- \text{URE}(\bs{\lambda}^{\text{ure}})
			\geq
			l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\text{ol}}),\bs{\theta}) 
			- \text{URE}(\bs{\lambda}^{\text{ol}})
			+
			\epsilon
			\right] 
			\rightarrow _{(2)} 0.
		\end{aligned}
	\end{equation}
	where $\leq_{(1)}$ follows by $\text{URE}(\bs{\lambda}^{\text{ure}})\leq \text{URE}(\bs{\lambda}^{\text{ol}})$, because $\bs{\lambda}^{\text{ure}}$ minimize the URE by definition, and $\rightarrow_{(2)}$ follow from Lemma \ref{lm:unif.convg}.
\end{proof}






To prove uniform convergence, we first present a reparameterization  $(\tilde{\lambda}_a,\tilde{\lambda}_b)$ of $(\lambda_a,\lambda_b)$ such that 	$\tilde{\bs{\lambda}}:=(\mu,\tilde{\lambda}_a,\tilde{\lambda}_b,\phi)$ has a bounded parameter space. 
For constants $k,n>0$, define
\begin{equation}
	\begin{aligned}[b]
		\lambda_a^{-1} = [\tilde{\lambda}_a^{-n} -1]^k, \quad
		\lambda_b^{-1} = [\tilde{\lambda}_b^{-n} -1]^k.
	\end{aligned}
	\label{eq:tilde.lambda}
\end{equation}
%	The parameterized value $\tilde{\lambda}_a\in(0,1)$ is strictly increasing in $\lambda_a\in(0,\infty)$, and similarly for $\tilde{\lambda}_b$. Recall that $\mathcal{J}$, or $\tilde{\mathcal{J}}$, imposes that $|\phi|<\bar{\phi}$ for some positive $\bar{\phi}<1$. 
%	which we state explicitly in Section~\ref{subsec:bd.deriv}. 
The parameters $\tilde{\lambda}_a\in (0,1)$ and $\tilde{\lambda}_b \in (0,1)$ are strictly increasing bijective functions of $\lambda_a$ and $\lambda_b$, respectively. 
The constant $k,n>0$ are chosen such that  $[2(n+1)]^{-1}=\epsilon$, for some $\epsilon>0$ that satisfies Assumption~\ref{ass:graph.connect.2}, and $k=2(n+1)/n$. This implies that  $\epsilon=(kn)^{-1}$. 



\begin{lemma}[Stochastic Equicontinuity]
	\label{lm:stoequi_bypiece}

	Suppose Assumptions~\ref{ass:reg.cond}, \ref{ass.degree}, \ref{ass:graph.connect.1} and \ref{ass:graph.connect.2} hold. Then, for $k=2,3,4$ and $x \in \{\mu,\tilde{\lambda}_a,\tilde{\lambda}_b,\phi\}$,	
	$
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
		\left|
		\frac{\partial}{\partial x}\mathcal{D}_k(\bs{\tilde{\lambda}})
		\right|
		=O_p(1) .\quad 
	$
\end{lemma}


\begin{proof}[Proof of Lemma~\ref{lm:unif.convg}]
	Because $\tilde{\bs{\lambda}}$ is a bijective reparameterize of $\bs{\lambda}$, following Lemma~\ref{lm:decomp}, it is sufficient to show the uniform convergence of $\textstyle\sup_{\tilde{\bs{\lambda}}\in \tilde{\mathcal{J}}}
	\left|
	\mathcal{D}_k(\bs{\tilde{\lambda}})
	\right| 
	=
	o_p(1)$ for $k=2,3,4$, and  $\mathcal{D}_1(\bs{\tilde{\lambda}})=o_p(1).$ The latter follows from Lemma~\ref{lm:UC1} because it does not depend on $\bs{\tilde{\lambda}}$. 

	The uniform convergence of $\mathcal{D}_k$ for $k=2,3,4$ follows from (i) their pointwise convergence implied by Lemma~\ref{lm:UC1}, (ii) the parameter space is bounded, and (iii) stochastic equicontinuity in Lemma~\ref{lm:stoequi_bypiece}, following Theorem 1 of \cite{Andrews1992}.
\end{proof}




Below we focus on the proof of the stochastic continuity condition in Lemma~\ref{lm:stoequi_bypiece}. The following notation is needed to set up the proof. Define any power of $L$ (or $  L^\dagger$) with the eigendecomposition of $L$. Define 
\begin{eqnarray}\label{eq:s1V.check}
	V_\lambda:=L^{1/2}  [L+\Lambda^*]^{-1}  L^{1/2+\epsilon},
\end{eqnarray}
where 
$\epsilon>0$ and $\epsilon^{-1}$ is a given large positive even number. 
% satisfies Assumption~\ref{ass:graph.connect.2}(ii).
Eventually, a critical ingredient in the proof of stochastic equicontinuity is to show that the following holds for $V_\lambda$.



\begin{lemma}
	\label{lm:bd.deriv}

	Suppose Assumptions~\ref{ass:reg.cond}, \ref{ass.degree}, \ref{ass:graph.connect.1} and \ref{ass:graph.connect.2} hold. Then, for $x \in \{\tilde{\lambda}_a,\tilde{\lambda}_b,\phi\}$,
	$\textstyle\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}} 
	\Vert \frac{\partial V_\lambda}{\partial x}\Vert = O(1)$.


\end{lemma}


\begin{lemma} \label{lm: Vdefine}
	$S_1 = \mathcal{R}  [L^\dagger]^{1/2} \cdot   V_\lambda \cdot L^{1/2-\epsilon}$.
\end{lemma}


\begin{proof}[Proof of Lemma~\ref{lm:stoequi_bypiece}]
	Define a positive semi-definite matrix $W_{\mathcal{R}}:=\mathcal{R}'W\mathcal{R}$.
	Note that $\tr [(W_\mathcal{R}^{1/2} L^\dagger
	W_\mathcal{R}^{1/2})^2]=\tr [(W^{1/2} L^{-}
	W^{1/2})^2]$, which is $O(1)$ by Assumption~\ref{ass:graph.connect.2}. 

	We first consider $\mathcal{D}_2(\bs{\tilde{\lambda}})$. By setting $\epsilon=1/2$ in the definition of $V_\lambda$, we have
	\begin{align}
		\mathcal{D}_2(\bs{\tilde{\lambda}}) =&	(Sv)' W (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})
		= 
		v'W (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})
		-v'S_1' W (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}) \nonumber\\
		=&_{(1)}
		v'W (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})
		-v' {V}_\lambda'   [L^\dagger]^{1/2} W_{\mathcal{R}} (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}) ,\label{eq:Sbeta_0}
	\end{align}
	where $=_{(1)}$ follows from Lemma~\ref{lm: Vdefine} and 
	$\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta} = \mathcal{R}( \hat{\bs{\theta}}^{\text{ls}}-\bs{\theta} )$ since both $ \hat{\bs{\theta}}^{\text{ls}}$ and $\bs{\theta}$ satisfy the normalization implied by $\mathcal{R}$. Note that in \eqref{eq:Sbeta_0}, $V_{\lambda}$ is the only part that depends on $x \in \{\tilde{\lambda}_a,\tilde{\lambda}_b,\phi\}$. We have
	\begin{align}		
		& 	\hspace{1.5em} \mathbb{E}_{\bs{\theta},B}\left[
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
		\left|
		\frac{\partial}{\partial x}\mathcal{D}_2(\bs{\tilde{\lambda}})
		\right|
		\right] \nonumber 
		= 
		\mathbb{E}_{\bs{\theta},B}\left[
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
		\left|
		v'\frac{\partial {V}_\lambda'}{\partial x}    [L^\dagger]^{1/2} W_{\mathcal{R}} (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})
		\right|
		\right]  \nonumber \\
		& \le 
		\mathbb{E}_{\bs{\theta},B}\left[
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
		\Vert v\Vert
		\Vert
		\frac{\partial {V}_{\lambda}}{\partial x}
		\Vert
		\Vert
		[L^\dagger]^{1/2}W_{\mathcal{R}}(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})
		\Vert\right] \nonumber\\
		& \le 
		\left(\frac{1}{r^{1/2}}  \sup_{\tilde{\lambda}\in\tilde{\mathcal{J}}}
		\Vert v \Vert\right)
		\left(\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
		\Vert\frac{\partial {V}_{\lambda}}{\partial x}\Vert\right)
		\left( r \cdot \mathbb{E}_{\bs{\theta},B}\left[\Vert 
		[L^\dagger]^{1/2}W_{\mathcal{R}}(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})\Vert^{2}\right]\right)^{1/2}, 	\label{eq:Sbeta_1}
	\end{align}
	where we apply the Cauchy-Schwarz inequality and use the fact that
	$\hat{\bs{\theta}}^{\text{ls}}$ is the only term that is stochastic and it does
	not depend on $\tilde{\lambda}$.
	The first term in \eqref{eq:Sbeta_1} is $O(1)$ because $\mu \le \overline{\mu}$. The second term in \eqref{eq:Sbeta_1} is $O(1)$ by Lemma~\ref{lm:bd.deriv}. To see the third term in \eqref{eq:Sbeta_1} is also $O(1)$, note that 
	\begin{align}
		r\cdot 
		\mathbb{E}_{\bs{\theta},B}\left[\Vert  [L^\dagger]^{1/2}W_{\mathcal{R}}(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})\Vert^{2}\right]\nonumber 
		= & r\cdot
		\mathbb{E}_{\bs{\theta},B}\left[\tr\left((\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})'W_{\mathcal{R}}  L^\dagger W_{\mathcal{R}}(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})\right)\right]\nonumber \\
		=&_{(1)}  r\cdot
		\tr\left(W_{\mathcal{R}} L^\dagger W_{\mathcal{R}} L^\dagger \right)
		=r\cdot \tr( [W_{\mathcal{R}}^{1/2}L^\dagger W_{\mathcal{R}}^{1/2}]^2 ), \label{eq:Sbeta_13}
	\end{align}
	where $=_{(1)}$ uses $\mathbb{V}(\hat{\bs{\theta}}^{\text{ls}})=  L^{-}=\mathcal{R}L^\dagger\mathcal{R}'$ and \eqref{eq:Sbeta_13} is $O(1)$ by Assumptions~\ref{ass.degree} and \ref{ass:graph.connect.2}.
	Among all the terms, 
	$(Sv)' W(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})$ is the only one that depends
	on $\mu$. 
	We have
	\begin{equation}
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
		\left|\frac{\partial}{\partial\mu}(Sv)'W(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})
		\right|
		=
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
		\left|(Sd_{r})' W(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})\right|,
	\end{equation}
	where $d_{r}=(1_{r}',0_{c}')'$ and the right hand side is $o_p(1)$ by the same arguments used to show $\sup_{\tilde{\bs{\lambda}}\in \tilde{\mathcal{J}}}
	\left|
	\mathcal{D}_2(\bs{\tilde{\lambda}})
	\right| 
	=
	o_p(1)$ with $\mu$ in $\mathcal{D}_2(\bs{\tilde{\lambda}})$ replaced by $1$.
	The result for $\mathcal{D}_3(\bs{\tilde{\lambda}})$ follows the same arguments as for $\mathcal{D}_2(\bs{\tilde{\lambda}})$ under $\tfrac{1}{r+c}\bs{\theta}'\bs{\theta} = O(1)$ by Assumption~\ref{ass:reg.cond}.


	Next, we consider $\mathcal{D}_4(\bs{\tilde{\lambda}})$. We first show the stochastic equicontinuity of 
	$(S_1(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}))' W (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})$ in $x\in\{\tilde{\lambda}_a,\tilde{\lambda}_b,\phi\}$.
	Using the definition of $V_{\lambda}$, we have
	\begin{align}
		& \hspace{1.5em} \mathbb{E}_{\bs{\theta},B}\left[
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
		\left|
		\frac{\partial}{\partial x}
		\left(S_1(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})\right)' W (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})
		\right|\right]\nonumber \\
		& = 
		\mathbb{E} _{\bs{\theta},B}\left[
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
		\left|
		\left( \frac{\partial V_\lambda}{\partial x} L^{1/2-\epsilon} (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})\right)' [L^\dagger]^{1/2}W_{\mathcal{R}}(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})
		\right|\right]\nonumber \\
		& \le  \sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}} \Vert 
		\frac{\partial {V}_\lambda}{\partial x} \Vert
		\left(
		\mathbb{E} _{\bs{\theta},B}\left[ \Vert 
		L^{1/2-\epsilon}(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})
		\Vert^2 \right]
		\right)^{1/2}
		\left(
		\mathbb{E} _{\bs{\theta},B}\left[\Vert [L^\dagger]^{1/2}W_{\mathcal{R}} (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}) \Vert^2 \right]
		\right)^{1/2}
		\nonumber \\
		& = 
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}} \Vert 
		\frac{\partial {V}_\lambda}{\partial x} \Vert \cdot  
		\left[
		\tr([L^\dagger]^{2\epsilon}) 
		\right]^{1/2}
		\left[
		\tr( W_{\mathcal{R}}L^\dagger W_{\mathcal{R}} L^\dagger )
		\right]^{1/2}
		\nonumber \\
		&	=  
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
		\Vert 
		\frac{\partial {V}_\lambda}{\partial x} \Vert  \cdot  
		\left[
		\frac{1}{r+c} \tr( [L^\dagger]^{2\epsilon})
		\right]^{1/2} 
		\left[
		(r+c) \cdot\tr( [W_{\mathcal{R}}^{1/2}L^\dagger W_{\mathcal{R}}^{1/2}]^2 )
		\right]^{1/2},
		%\label{eq:STB_1}
	\end{align}
	where the three items in the last equality are all $O(1)$ by Lemma~\ref{lm:bd.deriv} and Assumption~\ref{ass:graph.connect.2}.  

	Finally, we consider the equicontinuity of $\tr(S_1  L^{-}W)$
	in $x\in\{\tilde{\lambda}_a,\tilde{\lambda}_b,\phi\}$.
	Note that this item does not depend on $\mu$.
	Using $B\mathcal{R}=B$, we can write $\tr(S_{1}  L^{-}W)=\tr(S_{1} L^\dagger \mathcal{R}'W),$ and
	\begin{align}
		& \hspace{2em} \sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
		\left|
		\frac{\partial}{\partial x}\tr(S_{1}  L^\dagger \mathcal{R}'W)
		\right| 
		 =  _{(1)} 
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
		\left|
		\frac{\partial}{\partial x}
		\tr\left(
		\mathcal{R} [L^\dagger]^{1/2} \cdot V_\lambda \cdot [L^\dagger]^{1/2+\epsilon}   \mathcal{R}' W
		\right) 
		\right|
		\nonumber \\
		& =  _{(2)} 
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
		\left|
		\tr\left(
		W_{\mathcal{R}}^{1/2}   
		[L^\dagger]^{1/2} \frac{\partial V_\lambda }{\partial x} \cdot [L^\dagger]^{1/2+\epsilon}  
		W_{\mathcal{R}}^{1/2}
		\right) 
		\right|
		\nonumber \\
		& \le_{(3)} 
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
		\left(
		\tr\left[
		\frac{\partial V_\lambda '}{\partial x}
		[L^\dagger]^{2\epsilon}
		\frac{\partial V_\lambda }{\partial x}
		\right]
		\right)^{1/2} 
		\cdot 
		\left(
		\tr\left[
		(W_\mathcal{R}^{1/2} L^\dagger
		W_\mathcal{R}^{1/2})^2
		\right]
		\right)^{1/2} \nonumber \\
		& \leq 
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}} ||\frac{\partial V_\lambda }{\partial x}||\cdot 
		\left( 
		\frac{1}{r+c}
		\tr
		[L^\dagger]^{2\epsilon}
		\right)^{1/2} 
		\cdot 
		\left(
		(r+c)
		\tr [(W_\mathcal{R}^{1/2} L^\dagger
		W_\mathcal{R}^{1/2})^2]
		\right)^{1/2}, \label{eq:S_11} 
	\end{align}
	where the first term in \eqref{eq:S_11} is $O(1)$ by Lemma~\ref{lm:bd.deriv} and the last two terms are $O(1)$ by  Assumption~\ref{ass:graph.connect.2}. 
\end{proof}

