\begin{lemma} \label{lm: LS defn}
	The LS estimator is uniquely defined as $\hat{\bs{\theta}}^{\text{ls}} =  L^- B^\prime \bs{Y}$ under the normalization.
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lm: LS defn}]
	We can show that $ L^-$ is a generalized inverse of $L$, i.e., $LL^{-}L=L$ using the definition of $L^{-}=\mathcal{R}L^{\dagger}\mathcal{R}'$, $B\mathcal{R}=B$, and $LL^\dagger L = L$ for the Moore-Penrose inverse.  Thus, $\hat{\bs{\theta}}^{\text{ls}}=  L^-B^\prime \bs{Y}$ is a LS estimate. It satisfies the normalization $\bs{1}^\prime \bs{\beta}=0$ too since $\mathcal{R}$ appears on the left-hand side in $\hat{\bs{\theta}}^{\text{ls}}$. 

	We now turn to the uniqueness. Any least-squares estimate  $\check{\bs{\theta}}^{\text{ls}}$ can be characterized as 
	$
	\check{\bs{\theta}}^{\text{ls}} = \hat{\bs{\theta}}^{\text{ls}} +  [I-  L^-L]\bs{w} 
	$
	for some $\bs{w}\in\mathbb{R}^{r+c}$. Thus if $\check{\bs{\theta}}^{\text{ls}}$ is a LS estimate also satisfying the normalization $\bs{1}^\prime \bs{\beta}=0$, then	
	%\begin{aligned}[b]
	$	\check{\bs{\theta}}^{\text{ls}}
	=_{(1)}
	\mathcal{R}\check{\bs{\theta}}^{\text{ls}} 
	=
	\mathcal{R}\hat{\bs{\theta}}^{\text{ls}} 
	+
	[\mathcal{R} - \mathcal{R} L^-L]\bs{w} 
	=_{(2)}
	\hat{\bs{\theta}}^{\text{ls}} 
	+
	[\mathcal{R} - \mathcal{R}]\bs{w} 
	=
	\hat{\bs{\theta}}^{\text{ls}},$
	%	\end{aligned}
%\end{equation}
where $=_{(1)}$ follows from the fact that $\check{\bs{\theta}}^{\text{ls}}$ satisfies the normalization $\bs{1}^\prime \bs{\beta}=0$ and $=_{(2)}$ follows from $	\mathcal{R}
=
\mathcal{R} L^-L $, see \eqref{eq:E6}.
\end{proof}

\begin{lemma} \label{lm:pstm}
The posterior mean is $	\hat{\bs{\theta}}(\bs{\lambda}) :=
S_1\hat{\bs{\theta}}^{\text{ls}} + 
S \bs{v}$.
\end{lemma}
\begin{proof}[Proof of Lemma~\ref{lm:pstm}]
The model 
$\bs{Y}\mid B,\bs{\theta} \sim N(B\bs{\theta},I)$ 
together with the prior 
$\bs{\theta} \mid B \sim N(\bs{v},\Lambda^{*-1})$ 
can be written as 
\begin{equation}
	\begin{bmatrix}
		\bs{Y} \\ \bs{\theta}
	\end{bmatrix}
	\bigg| B\sim 
	\mathcal{N}\left(
	\begin{bmatrix}
		B\bs{v} \\ \bs{v}
	\end{bmatrix}, 
	\begin{bmatrix}
		B\Lambda^{*-1}B^\prime + I & B \Lambda^{*-1} \\
		\Lambda^{*-1}B^\prime & \Lambda^{*-1}
	\end{bmatrix}
	\right).
\end{equation}
Using the formula for the conditional distribution of joint normal distributions together with the linearity of expectation give us the expression for  $\hat{\bs{\theta}}:=\mathbb{E}\left[\mathcal{R}\bs{\theta}\mid B,\bs{Y}\right]$ as
\begin{equation}
	\begin{aligned}
		&\hspace{1.5em}\mathcal{R}\mathbb{E}[\bs{\theta}\mid B,\bs{Y}]\\
		&=
		\mathcal{R}\left\{\bs{v}
		+
		\Lambda^{*-1}B^\prime[B\Lambda^* B^\prime + I]^{-1}[\bs{Y}-B\bs{v}]\right\}\\
		&=_{(1)}
		\mathcal{R}
		\left\{\bs{v}
		+
		[L + \Lambda^*]^{-1} B^\prime[\bs{Y}-B\bs{v}]\right\}
		=
		\mathcal{R}
		\left\{\bs{v} - [L + \Lambda^*]^{-1} L\bs{v} 
		+ 
		[L + \Lambda^*]^{-1} B^\prime\bs{Y}\right\} \\
		%				&=_{(2)}
		%				\mathcal{R}\bs{v} - S_1\bs{v} 
		%				+ 
		%				\mathcal{R}
		%				\left\{
		%				[L + \Lambda^*]^{-1} L B^\dagger \bs{Y}\right\} \\
		%				&=_{(3)}
		%				S\bs{v} 
		%				+ 
		%				\mathcal{R}
		%				\left\{[L + \Lambda^*]^{-1} L  L^\dagger B^\prime \bs{Y}\right\} \\
		%				&=_{(4)}
		%				S\bs{v} 
		%				+ 
		%				\mathcal{R}
		%				\left\{[L + \Lambda^*]^{-1} L \mathcal{R}  L^\dagger \mathcal{R}^\prime B^\prime \bs{Y}\right\} \\
		&=_{(2)}
		S\bs{v} 
		+ 
		\mathcal{R}
		\left\{[L + \Lambda^*]^{-1} L  L^- B^\prime \bs{Y}\right\} 
		=_{(3)}
		S\bs{v} 
		+ 
		S_1 \hat{\bs{\theta}}^{\text{ls}},
	\end{aligned} \label{postmean}
\end{equation}
where $=_{(1)}$ follows from
$D^{-1}C(A-BDC)^{-1} = (D-CA^{-1}B)^{-1}CA^{-1}$
for conformal matrices,  $=_{(2)}$ follows by defining $S_1:=\mathcal{R}[L + \Lambda^*]^{-1}L$, $S_1+S = \mathcal{R}$, and $LL^{-}B'=B'$  using the property that $LL^{-}$ is a projection matrix onto the column space of $L$ and $B'$ belongs to the column space of $L$, 
%		of Moore-Penrose inverse $B^\prime = L B^\dagger$, $=_{(3)}$ follows from the property of Moore-Penrose inverse $B^\dagger =  L^\dagger B^\prime$, $=_{(4)}$ follows from \eqref{eq:E3}, $=_{(5)}$ follows from definition of $ L^- = \mathcal{R} L^\dagger \mathcal{R}^\prime$ 
and $=_{(3)}$ follows from definition of $\hat{\bs{\theta}}^{\text{ls}} =  L^- B^\prime \bs{Y}$.
\end{proof}

