Consider the LS estimate of the error variance in 
\eqref{eq:sigma_est}. The following Lemma shows that it is unbiased and consistent.


\begin{lemma} \label{lm:LSvar}
	\emph{(a).}	$\mathbb{E}_{\bs{\theta},B}[	 \hat{\sigma}^2] =  \sigma^2$.

	\noindent \emph{(b).} Suppose $rT-(r+c-1) \rightarrow \infty$
	as $r,c \rightarrow \infty$,  then $\hat{\sigma}^2 \rightarrow_p \sigma^2.$
\end{lemma}

\begin{proof}[Proof of Lemma \ref{lm:LSvar}]
	Define a constant
	\begin{align}
		\kappa = \frac{rT}{rT-(r+c-1)}.
	\end{align}
	For part (a), plugging $\bs{Y}=B\bs{\theta}+\bs{U}$, we have
	$
	\hat{\sigma}^2
	=\frac{\kappa}{rT}\bs{U}'\bs{U}-\frac{\kappa}{rT}\bs{U}'B(B'B)^{-}B'\bs{U},
	$
	where 
	\begin{align}
		\frac{1}{rT}\mathbb{E}_{\bs{\theta},B}[\bs{U}'\bs{U}] &= \sigma^2, \nonumber\\
		\frac{1}{rT}\mathbb{E}_{\bs{\theta},B}\left[\bs{U}'B(B'B)^{-}B'\bs{U}\right]
		&=_{(1)}\frac{ \sigma^2}{rT}\tr[B(B'B)^{-}B'] 
		=_{(2)}\frac{\sigma^2\cdot (r+c-1)}{rT},
	\end{align}
	where $=_{(1)}$ follows from $\mathbb{E}_{\bs{\theta},B}[\bs{U}\bs{U}']=\sigma^2 I_{rT}$, and $=_{(2)}$ follows from the assumption that $r+c\le rT$ and $L=B'B$ has one $0$ eigenvalue. Therefore, we have
	$\mathbb{E}_{\bs{\theta},B}[	 \hat{\sigma}^2] =  \sigma^2$. 

	For part (b), by applying  Lemma \ref{lm:pw.equalities}(b), we have
	\begin{align}
		\mathbb{V}_{\bs{\theta},B} \left[\frac{\kappa}{rT}\bs{U}'\bs{U}\right]&\le\frac{M}{(rT-(r+c-1)^2}\tr[I_{rT}]=o(1), \nonumber\\
		\mathbb{V}_{\bs{\theta},B}\left[\frac{\kappa}{rT}\bs{U}'B(B'B)^{-}B'\bs{U}\right]&\le\frac{M}{(rT-(r+c-1))^2}\tr[B(B'B)^{-}B']=_{(1)}o(1),
	\end{align}
	for some finite $M$,
	where $=_{(1)}$ holds because the eigenvalues of the projection matrix $B(B'B)^{-}B'$ is no larger than $1$. 
\end{proof}



The following lemma shows that the impact of the estimated coefficient is negligible uniformly over the hyperparameter. It is the key result to deliver asymptotic optimality with the estimated coefficient in Corollary~\ref{cor:reg}.
\begin{lemma}[Estimated Regressor Coefficient]
\label{lm:UC.reg}
Suppose Assumptions~\ref{ass:reg.cond}, \ref{ass.degree}, \ref{ass:graph.connect.1}, \ref{ass:graph.connect.2}, and  \ref{ass:reg.condreg} hold. Then,
\begin{align*}
	\sup_{\bs{\lambda}\in\mathcal{J}} 
	\left|
	l_w(\hat{\bs{\theta}}(\bs{\lambda}),\bs{\theta}) - 
	l_w(\tilde{\bs{\theta}}(\bs{\lambda}),\bs{\theta})
	\right|
	&\rightarrow_p 0,\label{eq:UC.reg.1}\\
	\sup_{\bs{\lambda}\in\mathcal{J}} 
	\left|
	\text{URE}(\bs{\lambda}) - 
	\widetilde{\text{URE}}(\bs{\lambda})
	\right|
	&\rightarrow_p 0.
	%\label{eq:UC.reg.2}
\end{align*}
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lm:UC.reg}]
We only detail the proof of the result for the loss, as the corresponding result for the URE 
%\eqref{eq:UC.reg.1}, as \eqref{eq:UC.reg.2} 
can be established using similar arguments. 
\begin{equation}
	\begin{aligned}[b]
		&l_w(\hat{\bs{\theta}}(\bs{\lambda}),\bs{\theta}) - 
		l_w(\tilde{\bs{\theta}}(\bs{\lambda}),\bs{\theta}) \\
		&=
		\left[S_1\hat{\bs{\theta}}^{\text{ls}}+S\bs{v}- \bs{\theta}\right]' W \left[S_1\hat{\bs{\theta}}^{\text{ls}}+S\bs{v} - \bs{\theta}\right]
		-
		\left[S_1\tilde{\bs{\theta}}^{\text{ls}}+S\bs{v} - \bs{\theta}\right]' W \left[S_1\tilde{\bs{\theta}}^{\text{ls}}+S\bs{v} - \bs{\theta}\right] \\
		&=
		\left[S_1\left( \hat{\bs{\theta}}^{\text{ls}}-\tilde{\bs{\theta}}^{\text{ls}}\right)\right]^\prime W
		\left[S_1\left( \hat{\bs{\theta}}^{\text{ls}}+\tilde{\bs{\theta}}^{\text{ls}}\right)
		+2S\bs{v} - 2\bs{\theta}\right] \\
		&=_{(1)}
		\left[
		S_1B^-X\left( \tilde{\bs{\gamma}}-\bs{\gamma}\right)
		\right]' W \left[
		S_1B^-X\left( \bs{\gamma}-\tilde{\bs{\gamma}}\right)
		+2\left(S_1\hat{\bs{\theta}}^{\text{ls}} + S\bs{v} - \bs{\theta}\right)
		\right]
		\\
		&=
		\left[
		S_1B^-X\left( \tilde{\bs{\gamma}}-\bs{\gamma}\right)
		\right]' W_{\mathcal{R}} \left[
		S_1B^-X\left( \bs{\gamma}-\tilde{\bs{\gamma}}\right)
		+2S_1\left(\hat{\bs{\theta}}^{\text{ls}} - \bs{\theta}\right)
		+2S\left(\bs{v}-\bs{\theta}\right)
		\right]
	\end{aligned}
\end{equation}
where $B^- = RB^\dagger$ and $=_{(1)}$ is due to
\begin{equation}
	\hat{\bs{\theta}}^{\text{ls}}-\tilde{\bs{\theta}}^{\text{ls}} = B^-[\bs{Y}^*-X\bs{\gamma}] - B^-[\bs{Y}^*-X\tilde{\bs{\gamma}}] = B^-X[\tilde{\bs{\gamma}}-\bs{\gamma}].
\end{equation}
Furthermore, by defining $\tilde{V}_\lambda:= L^{1/2+\epsilon}[L+\Lambda^*]^{-1} L^{1/2} $ in a similar logic as we did for $V_\lambda$ in \eqref{eq:s1V.check}, we have
\begin{equation}
	W_{\mathcal{R}}^{1/2} S_1B^-X(\tilde{\bs{\gamma}}-\bs{\gamma})
	=
	W_{\mathcal{R}}^{1/2} [L^\dagger]^{1/2+\epsilon} \cdot 
	\tilde{V}_\lambda \cdot
	L^{1/2}B^\dagger \cdot 
	\mathcal{R} X(\tilde{\bs{\gamma}}-\bs{\gamma}),
	\label{eq:UC.reg.3}
\end{equation}
where the first term is $o(1)$ under Assumption~\ref{ass:graph.connect.1} with $\epsilon=1/2$ for the case $W=W_{a+b}$ and $W=W_{b}$ following \eqref{gencond1} and \eqref{eq:partition}, respectively, and the (derivative of) the second term is handled in a similar fashion\footnote{See in particular Remarks~\ref{rmk:deriv.v} and \ref{rmk:deriv.v.1}; they apply in an almost identical fashion to $\tilde{V}_\lambda$ as to $V_\lambda$.} as $V_\lambda$ in Section~\ref{subsec:bd.deriv}. The third term of \eqref{eq:UC.reg.3} has norm less than one because $L^{1/2}B^\dagger B^{\dagger'} L^{1/2}=L^{1/2}L^\dagger L^{1/2} $ is a projection matrix. Finally the fourth term of \eqref{eq:UC.reg.3} is $O_p(1)$ by $\lVert \mathcal{R} \rVert
\leq 	
M$ and Assumption~\ref{ass:reg.condreg}.
Using arguments analogous to those in the proof of Lemma~\ref{lm:stoequi_bypiece}, we have $S_1(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})$ and $S(\bs{v}-\bs{\theta})$ are uniformly $O_p(1)$.
\end{proof}

\begin{proof}[Proof of Corollary \ref{cor:reg}]


First note that 
\begin{equation}
	\begin{aligned}[b]
		&l_w(\tilde{\bs{\theta}}(\bs{\lambda}^{\widetilde{\text{ure}}}),\bs{\theta}) - l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\text{ol}}),\bs{\theta})
		\\
		&=
		\underbrace{l_w(\tilde{\bs{\theta}}(\bs{\lambda}^{\widetilde{\text{ure}}}),\bs{\theta}) - l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\widetilde{\text{ure}}}),\bs{\theta}) }_{\text{(I)}}
		+
		\underbrace{l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\widetilde{\text{ure}}}),\bs{\theta}) - l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\text{ol}}),\bs{\theta})}_{\text{(II)}}
	\end{aligned}
\end{equation}
and term (I) is $o_p(1)$ by Lemma \ref{lm:UC.reg}. Furthermore, term (II) can be bound as follows
\begin{equation}
	\begin{aligned}[b]
		0 
		&\leq 
		l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\widetilde{\text{ure}}}),\bs{\theta}) - l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\text{ol}}),\bs{\theta}) \\
		&=
		\underbrace{ l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\widetilde{\text{ure}}}),\bs{\theta}) - \text{URE}(\bs{\lambda}^{\widetilde{\text{ure}}})}_{\text{(III)}}
		+
		\underbrace{\text{URE}(\bs{\lambda}^{\widetilde{\text{ure}}}) - \text{URE}(\bs{\lambda}^{\text{ure}})}_{\text{(IV)}}
		\\
		&+
		\underbrace{\text{URE}(\bs{\lambda}^{\text{ure}}) - l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\text{ure}}),\bs{\theta})}_{\text{(V)}} 
		+
		\underbrace{l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\text{ure}}),\bs{\theta}) - l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\text{ol}}),\bs{\theta})}_{\text{(VI)}}
	\end{aligned}
\end{equation}
Note that terms (III) and (V) are $o_p(1)$ by Lemma \ref{lm:unif.convg}, and term (VI) is $o_p(1)$ by Theorem \ref{thm:main}. 
Furthermore, term (IV) can be bound as follows
\begin{equation}
	\begin{aligned}[b]
		0 
		&\leq 
		\text{URE}(\bs{\lambda}^{\widetilde{\text{ure}}}) - \text{URE}(\bs{\lambda}^{\text{ure}}) \\
		&=
		\text{URE}(\bs{\lambda}^{\widetilde{\text{ure}}}) - \widetilde{\text{URE}}(\bs{\lambda}^{\widetilde{\text{ure}}}) 
		+
		\widetilde{\text{URE}}(\bs{\lambda}^{\widetilde{\text{ure}}}) - \text{URE}(\bs{\lambda}^{\text{ure}}) \\
		&\leq_{(1)}
		\underbrace{\text{URE}(\bs{\lambda}^{\widetilde{\text{ure}}}) - \widetilde{\text{URE}}(\bs{\lambda}^{\widetilde{\text{ure}}})}_{\text{(VII)}} 
		+
		\underbrace{\widetilde{\text{URE}}(\bs{\lambda}^{\text{ure}}) - \text{URE}(\bs{\lambda}^{\text{ure}})}_{\text{(VIII)}}
	\end{aligned}
\end{equation}
where $\leq_{(1)}$ follows because $\widetilde{\text{URE}}(\bs{\lambda}^{\widetilde{\text{ure}}})\leq\widetilde{\text{URE}}(\bs{\lambda}^{\text{ure}})$ by definition of URE minimization. Furthermore, terms (VII) and (VIII) are $o_p(1)$ by Lemma \ref{lm:UC.reg}.

Thus, we have term $0\leq\text{(II)}\leq\text{(III)}+\text{(V)}+\text{(VI)}+\text{(VII)}+\text{(VIII)} = o_p(1)$ and, therefore,
\begin{equation}
	\begin{aligned}[b]
		l_w(\tilde{\bs{\theta}}(\bs{\lambda}^{\widetilde{\text{ure}}}),\bs{\theta}) - l_w(\hat{\bs{\theta}}(\bs{\lambda}^{\text{ol}}),\bs{\theta})
		=
		\text{(I)}
		+
		\text{(II)}
		= o_p(1) + o_p(1)=o_p(1).
	\end{aligned}
\end{equation}
\end{proof}

\begin{proof}[Proof of Lemmas~\ref{lm:1way}]
We first introduce some additional definitions for this proof. Define 
\begin{equation}
	\begin{aligned}[b]
