such that 
\begin{equation}
	\begin{aligned}
		S_0(\bs{\lambda})& := [L + \Lambda]^{-1}\Lambda
		\\
		&=
		\begin{bmatrix}
			[\lambda_a + B_1^\prime M_{2,\lambda_b} B_1]^{-1} \lambda_a &
			-D_{1,\lambda_a}^{-1} B_1^\prime B_2
			[\lambda_b + B_2^\prime M_{1,\lambda_a} B_2]^{-1} \lambda_b
			\\
			-[\lambda_b + B_2^\prime M_{1,\lambda_a} B_2]^{-1}
