\begin{proof}[Proof of Lemma \ref{lm:1way.2}]


Continuing from the above proof, when $\lambda_a= 0$ and $\lambda_b \ne 0$, we have 
\begin{equation}
	\begin{aligned}
		S_0(\bs{\lambda})
		& =
		\begin{bmatrix}
			0_{r\times r} & 
			- (B_1'B_1)^{-1} B_1'B_2 [\lambda_b + L_{2,\perp}]^{-1}\lambda_b \\
			0_{c\times r} & 
			[\lambda_b + L_{2,\perp}]^{-1} \lambda_b
		\end{bmatrix}
	\end{aligned}
\end{equation}
where $L_{2,\perp} := B_2' M_1 B_2$ is the Laplacian matrix of the unipartite graph after projecting out the $\bs{\alpha}$-dimension of the bipartite graph. 
In this case, our estimator $\hat{\bs{\theta}}(\bs{\lambda})=\mathcal{R}[\hat{\bs{\theta}}^{\text{ls}}-S_0(\bs{\lambda})\hat{\bs{\theta}}^{\text{ls}}]$ satisfies
\begin{equation}
	\begin{aligned}[b]
		\hat{\bs{\theta}}(\bs{\lambda})
		& =
		\mathcal{R}
		\begin{bmatrix}
			\hat{\bs{\alpha}}^{\text{ls}}
			\\
			\hat{\bs{\beta}}^{\text{ls}}
		\end{bmatrix}
		-
		\mathcal{R}
		\begin{bmatrix}
			-(B_1'B_1)^{-1} B_1'B_2 [\lambda_b + L_{2,\perp}]^{-1}\lambda_b \hat{\bs{\beta}}^{\text{ls}}
			\\ 
			[\lambda_b+L_{2,\perp}]^{-1}\lambda_b \hat{\bs{\beta}}^{\text{ls}}
		\end{bmatrix}
		\\
		& =
		\mathcal{R}
		\begin{bmatrix}
			\hat{\bs{\alpha}}^{\text{ls}} +
			(B_1'B_1)^{-1} B_1'B_2 [\lambda_b + L_{2,\perp}]^{-1}\lambda_b \hat{\bs{\beta}}^{ls}
			\\
			[\lambda_b+L_{2,\perp}]^{-1}L_{2,\perp} \hat{\bs{\beta}}^{\text{ls}}
		\end{bmatrix}. 
	\end{aligned}
\end{equation}
\end{proof}



