\begin{proof}[Proof of Lemma \ref{lm:decomp}]
	Using the relation $S+S_1=\mathcal{R}$, one can write $l_w(\hat{\bs{\theta}},\bs{\theta}) - \text{URE}(\bs{\lambda})$ as 
	\begin{equation}
		\label{eq:decomp1}
		\begin{aligned}
			& \hspace{1.3em} l_w(\hat{\bs{\theta}},\bs{\theta}) - \text{URE}(\bs{\lambda})
			= 
			\left[\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}-S\hat{\bs{\theta}}^{\text{ls}}+S\bs{v}\right]^\prime W 
			\left[\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}-S\hat{\bs{\theta}}^{\text{ls}}+S\bs{v}\right]
			\\  & - 
			\left\{
			\tr\left[2S_1 L^- W - WL^- \right]
			+ (\hat{\bs{\theta}}^{\text{ls}} -\bs{v})'S'WS(\hat{\bs{\theta}}^{\text{ls}} -\bs{v}) \right \} \\
			&=
			[\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}]^\prime W[\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}] 
			-2(S\hat{\bs{\theta}}^{\text{ls}})^\prime W (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})+2(S \bs{v})^\prime W[\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}]\\
			& -
			2\tr[S_1L^- W ] +\tr[WL^- ], 
		\end{aligned}
	\end{equation}
	where the second term in the last equality satisfies
	\begin{equation}
		\label{eq:decomp2}
		\begin{aligned}
			&(S\hat{\bs{\theta}}^{\text{ls}})^\prime W(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})
			=
			(S(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}))^\prime W (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})
			+(S\bs{\theta})^\prime W (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}) \\
			&=
			(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})^\prime W (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})
			-(S_1(\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}))^\prime W (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta})
			+(S\bs{\theta})^\prime W (\hat{\bs{\theta}}^{\text{ls}}-\bs{\theta}). 
		\end{aligned}
	\end{equation}
	Substituting \eqref{eq:decomp2} into \eqref{eq:decomp1} and we have the desired expression.
\end{proof}

