			R L^\dagger L \cdot \Lambda^{*-1} B' [B\Lambda^{*-1}B' + I]^{-1} B \\ 
			&=
			R L^\dagger B' \cdot B\Lambda^{*-1} B' [B\Lambda^{*-1}B' + I]^{-1} B 
			=_{(3)} R B^\dagger G B,
		\end{aligned}
	\end{equation}
	where $=_{(1)}$ follows from $\mathcal{R}
	=
	\mathcal{R} L^-L $, see Lemma \eqref{eq:E6}, $=_{(2)}$ follows from $B\mathcal{R}=B$, see Lemma \eqref{eq:E3} and 
	$D^{-1}C(A-BDC)^{-1} =(D-CA^{-1}B)^{-1}CA^{-1}$
	for conformal matrices, and $=_{(3)}$ follows from property of the Moore-Penrose inverse.

	Since $G + [B\Lambda^{*-1}B' + I]^{-1} = I$, we have 
	$
			||G||
			=
			|| I - [B\Lambda^{*-1}B' + I]^{-1} || 
			\leq_{(1)} 1,
$
	where $\leq_{(1)}$ holds because the eigenvalues of the positive semidefinite $B\Lambda^{*-1}B' + I$ are no smaller than $1$, and hence the eigenvalues of its inverse are no greater than $1$.
\end{proof}	

\begin{proof}[Proof of Lemma \ref{lm: Vdefine}]

	We have
	$S_1 = _{(1)}  \mathcal{R}[L+\Lambda^*]^{-1}L 
	=_{(2)}  \mathcal{R}  L^{-}L[L+\Lambda^*]^{-1}L
	=_{(3)}  \newline \mathcal{R}  L^\dagger L[L+\Lambda^*]^{-1}L
	=_{(4)}  \mathcal{R}  [L^\dagger]^{1/2} \cdot   V_\lambda \cdot L^{1/2-\epsilon}$,
