\begin{proof}[Proof of Lemma 	\ref{lm:bd.deriv}]
	Our objective is to bound 
	\begin{align}
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}} }
		\lVert \frac{\partial V_\lambda}{\partial x} \rVert
		&=
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}} }
		\lVert 
		L^{1/2+\epsilon}
		\frac{\partial}{\partial x}
		[L + \Lambda^*]^{-1} L^{1/2}
		\rVert
		\label{eq:deriv.bound}
	\end{align}
	for
	$x\in\{\tilde{\lambda}_a,\tilde{\lambda}_b,\phi\}$, where $\epsilon^{-1}$ is a given large positive even number. For presentation simplicity, we first define
	\begin{align}
		\check{V}_\lambda:&=L^{\epsilon}  [L+\Lambda^*]^{-1}  L, \text{ such that } \nonumber\\
		V_\lambda:&=L^{1/2}  [L+\Lambda^*]^{-1}  L^{1/2+\epsilon}=L^{1/2-\epsilon}\check{V}_\lambda [L^\dagger]^{1/2-\epsilon},
		\label{eq:deriv.bound.v}
	\end{align} 
	We first show how to bound 
	\begin{align}
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}} }
		\lVert \frac{\partial \check{V}_\lambda}{\partial x} \rVert
		&=
		\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}} }
		\lVert 
		L^{\epsilon}
		\frac{\partial}{\partial x}
		[L + \Lambda^*]^{-1} L
		\rVert,
		\label{eq:deriv.bound2}
	\end{align}
	and then discuss how to bound $\textstyle\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}} }
	\lVert \frac{\partial V_\lambda}{\partial x} \rVert$.

	We start with the derivative of $\check{V}_\lambda$ w.r.t. $\tilde{\lambda}_a$. The steps for derivative w.r.t. $\tilde{\lambda}_b$ are obviously symmetric, whereas those for the derivative w.r.t. $\phi$ are elaborated in Remarks~\ref{rmk:deriv.phi} and \ref{rmk:deriv.phi.1}. Finally, the steps for the derivatives of $V_\lambda$ w.r.t. $(\tilde{\lambda}_a,\tilde{\lambda}_b,\phi)$ are elaborated in Remarks~\ref{rmk:deriv.v} and \ref{rmk:deriv.v.1}. 



	The rest of the proof proceeds as follows:
	We first writes the derivative of \eqref{eq:deriv.bound2} explicitly, which the subsequent sections utilize in bounding \eqref{eq:deriv.bound2} in different regimes. We first takes the regime where both $\lambda_a,\lambda_b\leq1$, then takes the regimes where at least one of $\lambda_a,\lambda_b$ is greater than 1.

	%Section~\ref{subsubsec:take.deriv} writes the derivative of \eqref{eq:deriv.bound} explicitly, which the subsequent sections utilize in bounding \eqref{eq:deriv.bound} in different regimes: Section~\ref{subsubsec:small.a.small.b} takes the regime where both $\lambda_a,\lambda_b\leq1$, and Section~\ref{subsubsec:remainingcases} takes the regimes where at least one of $\lambda_a,\lambda_b$ is greater than 1.

	\textbf{Step 1. Take Derivative.} 
	%\subsubsection{Taking derivative}
	%\label{subsubsec:take.deriv}
	Note that
	\begin{equation}
		\frac{\partial}{\partial \tilde{\lambda}_a}
		L^\epsilon
		[L + \Lambda^*]^{-1} L
		=
		\frac{\partial}{\partial \lambda_a^{1/2}}
		L^\epsilon
		[L + \Lambda^*]^{-1} L
		\cdot
		\frac{\partial\lambda_a^{1/2}}{\partial \tilde{\lambda_a}}.
		\label{eq:deriv.main}
	\end{equation}
	Following Lemma~\ref{lm:take.deriv},
	\begin{align}
		\frac{\partial\lambda_a^{1/2}}{\partial\tilde{\lambda}_a}
		=&
		\frac{\partial\lambda_a^{1/2}}{\partial\lambda_a^{-1}} \cdot
		\frac{\partial\lambda_a^{-1}}{\partial\tilde{\lambda}_a}
		=
		\frac{kn}{2}
		\left[1+\lambda_a^{\frac{1}{k}}\right]^{\frac{n+1}{n}}
		\lambda_a^{\frac{1}{2}-\frac{1}{kn}}
		=_{(1)}
		\frac{1}{2\epsilon}
		\left[1+\lambda_a^{\frac{1}{k}}\right]^{\frac{k}{2}}
		\lambda_a^{\frac{1}{2}-\epsilon}
		,
		\label{eq:deriv.lambda.tilde}
	\end{align}
	where $=_{(1)}$ follows from our choice of $(n,k)$ such that $\epsilon=(kn)^{-1}$.

	Let $\Lambda_a$ be a diagonal matrix with $1$ on the first $r$ diagonals and zero everywhere else. Then we have 
	\begin{equation}
		\begin{aligned}[b]
			&\frac{\partial}{\partial \lambda_a^{1/2}}
			L^\epsilon
			[L + \Lambda^*]^{-1} L
			=
			L^\epsilon
			[L + \Lambda^*]^{-1}
			\left\{
			\Lambda_a
			[-\phi\mathcal{A}+I]\Lambda^{1/2}
			+
			\Lambda^{1/2}[-\phi\mathcal{A}+I]\Lambda_a
			\right\}
			[L + \Lambda^*]^{-1}
			L
			\\
			=&
			L^\epsilon
			[L + \Lambda^*]^{-1}
			\cdot
			\begin{bmatrix}
				2\lambda_a^{1/2} & -\phi\lambda_b^{1/2}\mathcal{A}_{12} \\
				-\phi\lambda_b^{1/2}\mathcal{A}_{21} & 0
			\end{bmatrix}
			\cdot
			[L + \Lambda^*]^{-1}
			L.
		\end{aligned}
		\label{eq:deriv}
	\end{equation}
	This implies that bounding \eqref{eq:deriv.bound2} is equivalent to bounding\footnote{Any power of $[L+\Lambda^*]^{-1}$ may be defined using its eigendecomposition.} 
	\begin{align}
		L^\epsilon
		[L + \Lambda^*]^{-\epsilon}
		\cdot 
		[L + \Lambda^*]^{-(1-\epsilon)}
		\begin{bmatrix}
			\lambda_a^{1/2} & 0 \\
			-\phi\lambda_b^{1/2}\mathcal{A}_{21} & 0
		\end{bmatrix}
		\frac{\partial\lambda_a^{1/2}}{\partial\tilde{\lambda}_a} 
		\cdot
		[L + \Lambda^*]^{-1}
		L.
		\label{eq:deriv.1}
	\end{align}
	We can show that the term that replace $-\phi\lambda_b^{1/2}\mathcal{A}_{21}$ with $-\phi\lambda_b^{1/2}\mathcal{A}_{12}$ in the symmetric diagonal position can be bounded by the same arguments.
	%	As we shall see, the term in \eqref{eq:deriv} associated with
	%	\begin{equation}
		%		\begin{bmatrix}
			%			\lambda_a^{1/2} & -\phi\lambda_b^{1/2}\mathcal{A}_{12} \\
			%			0 & 0
			%		\end{bmatrix}
		%	\end{equation}
	%	will be bounded using identical arguments, and so we have ignored it to keep our subsequent arguments compact. 

	\textbf{Step 2. Study the case with small $\lambda_a$ and small $\lambda_b$.}
	%\subsubsection{Small $\lambda_a$ and small $\lambda_b$}
	%\label{subsubsec:small.a.small.b}
	In this section, we assume that we are in the regime where $\lambda_a,\lambda_b\leq 1$. Recall that our goal is to uniformly bound \eqref{eq:deriv.1}, and that from \eqref{eq:deriv.lambda.tilde}
	\begin{equation}
		\frac{\partial\lambda_a^{1/2}}{\partial\tilde{\lambda}_a}
		=
		\frac{1}{2\epsilon}
		\left[1+\lambda_a^{\frac{1}{k}}\right]^{\frac{k}{2}}
		\cdot
		\lambda_a^{\frac{1}{2}-\epsilon} = O(\lambda_a^{\frac{1}{2}-\epsilon} ),
	\end{equation}
	because $\lambda_a\leq1$. As such, our task reduces to bounding
	\begin{equation}
		L^\epsilon
		[L + \Lambda^*]^{-\epsilon}
		\cdot 
		[L + \Lambda^*]^{-(1-\epsilon)}
		\begin{bmatrix}
			\lambda_a^{1-\epsilon} & 0 \\
			-\phi\lambda_a^{1/2-\epsilon}\lambda_b^{1/2}\mathcal{A}_{21} & 0
		\end{bmatrix}
		\cdot
		[L + \Lambda^*]^{-1}
		L.
		\label{eq:deriv.small.a.1}
	\end{equation}
	We will bound each of the three terms in  \eqref{eq:deriv.small.a.1}.

	The first term in \eqref{eq:deriv.small.a.1} is bounded following Lemma~\ref{lm:deriv.bound.lower} because $\epsilon^{-1}$ is an even number by construction.

	To bound the norm of the third term in \eqref{eq:deriv.small.a.1} is equivalent to bounding the norm of $[L + \Lambda^*]^{-1}\Lambda^*$. Because $||\phi\mathcal{A}_{21}||=O(1)$, this follows from
	\begin{equation}
		\begin{aligned}[b]
			||[L + \Lambda^*]^{-1}|| \cdot ||\Lambda^*||
			\leq& 
			|| [L+\Lambda^*]^{-1} || 
			\cdot 
			|| \lambda_a + \lambda_a^{1/2}\lambda_b^{1/2} ||
		\end{aligned}
		\label{eq:deriv.small.a.2.1}
	\end{equation}
	which is indeed bounded, because for instance
	\begin{equation}
		\begin{aligned}[b]
			[L+\Lambda^*]^{-1} \lambda_a 
			&=[L+\Lambda^*]^{-1} \lambda_a 
			\left[\left\{\lambda_a>\lambda_b\right\} + \left\{\lambda_b>\lambda_a\right\} \right]
			\\
			&=_{(1)} 
			O(\lambda_a^{-1}) \lambda_a \left\{\lambda_a>\lambda_b\right\}
			+
			O(\lambda_b^{-1}) \lambda_b \frac{\lambda_a}{\lambda_b} \left\{\lambda_b>\lambda_a\right\}
			= O(1) + O(1),
		\end{aligned}
		\label{eq:deriv.small.a.2.2}
	\end{equation}
	where $=_{(1)}$ follows from Lemma~\ref{lm:deriv.bound}.

	Now we bound the norm of the second term in \eqref{eq:deriv.small.a.1}, which is achieved by bounding
	\begin{align}
		&\left([L + \Lambda^*]^{-1}\right)^{1-\epsilon}
		(\lambda_a^{1-\epsilon}+ \lambda_a^{1/2-\epsilon}\lambda_b^{1/2})
		\nonumber\\
		=&
		\left([L + \Lambda^*]^{-1} \cdot\lambda_a\right)^{1-\epsilon}
		+
		\left([L + \Lambda^*]^{-1} \cdot\lambda_a\right)^{1/2-\epsilon}
		\left([L + \Lambda^*]^{-1} \cdot\lambda_b\right)^{1/2}
		\label{eq:deriv.small.a.3}
	\end{align}
	which is indeed bounded by steps identical to \eqref{eq:deriv.small.a.2.2}.

	\begin{remark}[Bounding the derivative of $\phi$]
		\label{rmk:deriv.phi}
		The steps for bounding 
		\begin{equation*}
			\sup_{\tilde{\bs{\lambda}}\in\tilde{\mathcal{J}}}
			\lVert 
			L^\epsilon
			\frac{\partial}{\partial \phi}
			[L + \Lambda^*]^{-1} L
			\rVert
		\end{equation*}
		is similar to the arguments above: our task is reduced to bounding,  similar to \eqref{eq:deriv.1} and \eqref{eq:deriv.small.a.1}, 
		\begin{equation}
			L^\epsilon
			[L + \Lambda^*]^{-\epsilon}
			\cdot 
			[L + \Lambda^*]^{-(1-\epsilon)}
			\cdot
			\begin{bmatrix}
				0 & 0 \\
				-\lambda_a^{1/2}\lambda_b^{1/2}\mathcal{A}_{21} & 0
			\end{bmatrix}
			\cdot
			[L + \Lambda^*]^{-1}
			L,
		\end{equation}
		which is achieved by bounding 
		$
		[L + \Lambda^*]^{-1}
		\lambda_a^{1/2}\lambda_b^{1/2}
		\cdot
		[L + \Lambda^*]^{-1}
		L.
		$
		This is further reduced to bounding the following items,
		$
		[L + \Lambda^*]^{-1}\lambda_a,
		\quad 
		[L + \Lambda^*]^{-1}\lambda_b,
		\quad 
		[L + \Lambda^*]^{-1} L,
		$
		all of which are exactly the terms studied previously. 
		\qed
	\end{remark}

