	\begin{remark}[Bounding of $V_\lambda$]
		\label{rmk:deriv.v}
		Recall that from \eqref{eq:deriv.bound.v}
		\begin{equation}
			\frac{\partial}{\partial \tilde{\lambda}_a} V_\lambda
			=
			L^{1/2-\epsilon} \cdot
			\frac{\partial}{\partial \tilde{\lambda}_a} \check{V}_\lambda \cdot 
			[L^\dagger]^{1/2-\epsilon},
			\label{eq:deriv.v.0}
		\end{equation} 
		so that bounding $\tfrac{\partial}{\partial \tilde{\lambda}_a} V_\lambda$ in this regime only requires a different factorization of the terms from the workings above. To elaborate: recall that $\tfrac{\partial}{\partial \tilde{\lambda}_a} \check{V}_\lambda$ is bounded by \eqref{eq:deriv.small.a.1}, and thus substituting out $\tfrac{\partial}{\partial \tilde{\lambda}_a} \check{V}_\lambda$ from \eqref{eq:deriv.v.0} using \eqref{eq:deriv.small.a.1} reveals that bounding $\tfrac{\partial}{\partial \tilde{\lambda}_a} V_\lambda$ is equivalent to bounding
		\begin{equation}
			\begin{aligned}[b]
				L^{\frac{1}{2}}
				[L + \Lambda^*]^{-\frac{1}{2}}
				\cdot 
				[L + \Lambda^*]^{-\frac{1}{2}}
				\begin{bmatrix}
					\lambda_a^{1-\epsilon} & 0 \\
					-\phi\lambda_a^{1/2-\epsilon} \lambda_b^{1/2}\mathcal{A}_{21} & 0
				\end{bmatrix}
				[L + \Lambda^*]^{-(\frac{1}{2}-\epsilon)} 
				\cdot
				[L + \Lambda^*]^{-(\frac{1}{2}+\epsilon)}
				L^{\frac{1}{2}+\epsilon},
			\end{aligned}
			\label{eq:deriv.v.1}
		\end{equation}
		where the first and third terms are bounded by Lemma~\ref{lm:deriv.bound.lower} -- this step for the first term is straightforward whereas the third term deserves more elaboration:  
		\begin{equation}
			\begin{aligned}[b]
				&|| L^{\frac{1}{2}+\epsilon}
				[L + \Lambda^*]^{-(\frac{1}{2}+\epsilon)} ||^2
				=
				\bar{\rho}( L^{\frac{1}{2}+\epsilon}[L + \Lambda^*]^{-(1+2\epsilon)}L^{\frac{1}{2}+\epsilon}) 
				=
				\bar{\rho}( L[L + \Lambda^*]^{-1} \cdot [L + \Lambda^*]^{-2\epsilon}L^{2\epsilon}) \\
				\leq&
				|| L[L + \Lambda^*]^{-1} \cdot [L + \Lambda^*]^{-2\epsilon}L^{2\epsilon} || 
				\leq
				|| L[L + \Lambda^*]^{-1} || \cdot || [L + \Lambda^*]^{-2\epsilon}L^{2\epsilon} || \\
				=&_{(1)}
				|| I - \Lambda^*[L + \Lambda^*]^{-1} || \cdot || [L + \Lambda^*]^{-2\epsilon}L^{2\epsilon} || ,
			\end{aligned}
		\end{equation}
		where the first term of $=_{(1)}$ is bounded as in \eqref{eq:deriv.small.a.2.2}, and the second term of $=_{(1)}$ is bounded by Lemma~\ref{lm:deriv.bound.lower} because $\tfrac{1}{2}\epsilon^{-1}$ is an even number by construction. 

		Finally the middle term of \eqref{eq:deriv.v.1} is bound by 
		$
		[L + \Lambda^*]^{-\frac{1}{2}}
		\cdot
		(\lambda_a^{1-\epsilon}+ \lambda_a^{1/2-\epsilon}\lambda_b^{1/2})
		\cdot
		[L + \Lambda^*]^{-(\frac{1}{2}-\epsilon)},
		$
		which is bounded once we bound the following terms
		$
		[L + \Lambda^*]^{-(\frac{1}{2}-\epsilon)}\lambda_a^{\frac{1}{2}-\epsilon}
		,\quad
		[L + \Lambda^*]^{-\frac{1}{2}}\lambda_a^{\frac{1}{2}}
		,\quad
		[L + \Lambda^*]^{-\frac{1}{2}}\lambda_b^{\frac{1}{2}}
		$.
		These steps are identical to \eqref{eq:deriv.small.a.3}.
		\qed
	\end{remark}

