	\textbf{Step 3. Study the case where at least one of $\lambda_a,\lambda_b$ is large.}
	%\begin{remark}[Definitions of $V$ and $\bar{V}$ matrices]
	%	\label{rmk:def.1}
	We will now define several matrices for notational compactness. Let $V:=L + \Lambda^*$. Also let $\bar{\Lambda}:= \Lambda^{1/2} ( -|\phi|I + I ) \Lambda^{1/2}$ which is a diagonal matrix, and lastly $\bar{V}:= L + \bar{\Lambda}$. Note that
	\begin{equation}
		\begin{aligned}[b]
			V_1 =& B_1^\prime B_1 + \lambda_a, \qquad
			& \bar{V}_1 =& B_1^\prime B_1 + \lambda_a(1-|\phi|),
			\\
			V_{12} =& B_1^\prime B_2 - \phi\lambda_a^{1/2}\lambda_b^{1/2}\mathcal{A}_{12}, \qquad
			& \bar{V}_{12} =& B_1^\prime B_2,
			\\
			V_2 =& B_2^\prime B_2 + \lambda_b, \qquad
			& \bar{V}_2 =& B_2^\prime B_2 + \lambda_b(1-|\phi|).
		\end{aligned}
	\end{equation}
	%	\qed
	%\end{remark}

	%\begin{remark}[Notation]
	%	\label{rmk:notation.2}
	For a generic matrix $M$, we use $[M^{-1}]_{1}$, $[M^{-1}]_{12}$, and $[M^{-1}]_{2}$ to denote the top left, top right, and bottom right blocks of the matrix inverse $M^{-1}$ respectively. On the other hand, we use $M_{1}^{-1}$, $M_{2}^{-1}$ to denote the inverses of the top left and bottom right blocks of the matrix $M$ respectively.
	%	\qed
	%\end{remark}

	We now work in the regime where at least one of $\lambda_a,\lambda_b$ is greater than 1.
	Recall our goal is to uniformly bound \eqref{eq:deriv.bound2}, which reduces to bounding \eqref{eq:deriv.1}.
	Because the norm of $L$ is bounded, and recalling \eqref{eq:deriv.lambda.tilde}, our goal thus further reduces to bounding the norm of
	\begin{align}
		&[L + \Lambda^*]^{-1}
		\cdot
		\begin{bmatrix}
			\lambda_a^{1/2} & 0 \\
			-\phi\lambda_b^{1/2}\mathcal{A}_{21} & 0
		\end{bmatrix}
		\cdot 
		[1+\lambda_a^{\frac{1}{k}}]^{\frac{k}{2}}
		\lambda_a^{\frac{1}{2}-\epsilon}
		\cdot
		[L + \Lambda^*]^{-1}
		\nonumber
		\\
		=&
		\begin{bmatrix}
			[V^{-1}]_{1} & [V^{-1}]_{12} \\
			[V^{-1}]_{21} & [V^{-1}]_{2}
		\end{bmatrix}
		\cdot
		\begin{bmatrix}
			\lambda_a^{1-\epsilon} & 0 \\
			-\phi\lambda_a^{1/2-\epsilon}\lambda_b^{1/2}\mathcal{A}_{21} & 0
		\end{bmatrix}
		\cdot 
		\begin{bmatrix}
			[1+\lambda_a^{\frac{1}{k}}]^{\frac{k}{2}}& 0 \\
			0 & 0
		\end{bmatrix}
		\cdot
		\begin{bmatrix}
			[V^{-1}]_{1} & [V^{-1}]_{12} \\
			[V^{-1}]_{21} & [V^{-1}]_{2}
		\end{bmatrix} 
		\nonumber
		\\
		=&
		\begin{bmatrix}
			[V^{-1}]_{1}\lambda_a^{1-\epsilon} - [V^{-1}]_{12}\mathcal{A}_{21}\phi\lambda_a^{1/2-\epsilon}\lambda_b^{1/2}  
			& 
			0
			\\
			[V^{-1}]_{21}\lambda_a^{1-\epsilon} - [V^{-1}]_{2}\mathcal{A}_{21}\phi\lambda_a^{1/2-\epsilon}\lambda_b^{1/2}  
			&
			0
		\end{bmatrix}
		\cdot 
		\begin{bmatrix}
			O(1+\lambda_a^{1/2}) & 0 \\
			0 & 0
		\end{bmatrix}
		\begin{bmatrix}
			[V^{-1}]_{1} & [V^{-1}]_{12} \\
			[V^{-1}]_{21} & [V^{-1}]_{2}
		\end{bmatrix}.
		\label{eq:remainingcases.1} 
	\end{align}
	First, we take the top-left block of the left matrix in \eqref{eq:remainingcases.1}. First note that from Lemma~\ref{lm:deriv.bound.non.small}, $[V^{-1}]_{1}\lambda_a^{1-\epsilon} = O(1)$.
	Second note that
	\begin{align}
		[V^{-1}]_{12} \lambda_a^{1/2-\epsilon} \lambda_b^{1/2}
		=_{(1)}& 
		O(1\wedge\lambda_a^{-1}) \lambda_a^{1-\epsilon}
		\cdot
		O(\lambda_a^{1/2}\lambda_b^{1/2}) \frac{1}{\lambda_a^{1/2}\lambda_b^{1/2}}
		\cdot
		O(1\wedge\lambda_b^{-1}) \lambda_b 
		=
		O(1),
	\end{align}
	where $=_{(1)}$ follows from the third equation of Lemma~\ref{lm:deriv.bound.non.small}.

	Next, we take the bottom-left block of the left matrix in \eqref{eq:remainingcases.1}. Note that 
	\begin{equation}
		\begin{aligned}
			&[V^{-1}]_{21} \lambda_a^{1-\epsilon} - [V^{-1}]_{2} \mathcal{A}_{21} \phi\lambda_a^{1/2-\epsilon}\lambda_b^{1/2}
			=
			\left([V^{-1}]_{21} \lambda_a^{1/2} - [V^{-1}]_{2} \mathcal{A}_{21} \phi\lambda_b^{1/2}\right)\cdot \lambda_a^{1/2-\epsilon}
			\\
			=&_{(1)}
			-[V^{-1}]_{2}
			\left[B_2'B_1 \lambda_a^{1/2} + \phi\lambda_b^{1/2}\mathcal{A}_{21}B_1'B_1\right] V_1^{-1} 
			\cdot \lambda_a^{1/2-\epsilon} \\
			=&
			-[V^{-1}]_{2} 
			\left[B_2'B_1 \cdot V_1^{-1}\lambda_a^{1-\epsilon} + \lambda_b^{1/2} \cdot \phi\mathcal{A}_{21}B_1'B_1 \cdot V_1^{-1}\lambda_a^{1/2-\epsilon} \right]
			\\
			=&_{(2)}
			O(1\wedge\lambda_b^{-1})\left[ O(1) + \lambda_b^{1/2}\cdot O(1)\right]
			=
			O(1),
		\end{aligned}
	\end{equation}
	where $=_{(1)}$ follows from the second equation of Lemma~\ref{lm:factor}, and $=_{(2)}$ follows from Lemma~\ref{lm:deriv.bound.non.small}.

	Finally, we take the right matrix (product) of \eqref{eq:remainingcases.1}. Note that $[V^{-1}]_{1} O(1+\lambda_a^{1/2})=O(1)$ by Lemma~\ref{lm:deriv.bound.non.small}, and
	\begin{align}
		[V^{-1}]_{12} O(1+\lambda_a^{1/2})
		=_{(1)} 
		O(1\wedge \lambda_a^{-1}) O(\lambda_a^{1/2}+\lambda_a) O(\lambda_b^{1/2}) O(1\wedge \lambda_b^{-1})
		=O(1),
	\end{align} 
	where again $=_{(1)}$ follows from Lemma~\ref{lm:deriv.bound.non.small}.


	\begin{remark}[Bounding derivative wrt $\phi$]
		\label{rmk:deriv.phi.1}Replace the derivative with respect to (wrt) $\tilde{\lambda}_a$ with the derivative wrt $\phi$,
		our goal is now bounding 
		%(see the first line of \eqref{eq:remainingcases.1}, where we replace the derivative wrt $\tilde{\lambda}_a$ with the derivative wrt $\phi$, and ignore the $-\mathcal{A}_{21}$ term because it is bounded in norm and eventually drops out of the calculations)
		\begin{align*}
			&[L + \Lambda^*]^{-1}
			\cdot
			\begin{bmatrix}
				0 & 0 \\
				\lambda_a^{1/2}\lambda_b^{1/2} & 0
			\end{bmatrix}
			\cdot
			[L + \Lambda^*]^{-1}
			=
			[L + \Lambda^*]^{-1}
			\begin{bmatrix}
				0 & 0 \\
				\lambda_b^{1/2} & 0
			\end{bmatrix}
			\cdot
			\begin{bmatrix}
				\lambda_a^{1/2} & 0 \\
				0 & 0
			\end{bmatrix}
			[L + \Lambda^*]^{-1},
		\end{align*}
		which is achieved by bounding 
		$
		[V^{-1}]_{12}\lambda_b^{1/2},
		\quad
		[V^{-1}]_{2}\lambda_b^{1/2},
		\quad
		[V^{-1}]_{1}\lambda_a^{1/2},
		\quad
		[V^{-1}]_{12}\lambda_a^{1/2}
		$
		using Lemma~\ref{lm:deriv.bound.non.small}.
		\qed
	\end{remark}


	\begin{remark}[Bounding of $V_\lambda$]
		\label{rmk:deriv.v.1}
		Since any positive power of $L$ is bounded in norm, there is no change in the workings for bounding $V_\lambda$ in this regime.
		%; see discussion prior to \eqref{eq:remainingcases.1}.
		\qed
	\end{remark}
	This completes the proof of Lemma~\ref{lm:bd.deriv}.
\end{proof}

