Below we present some results used in the proof of Lemma~\ref{lm:bd.deriv}.

\begin{lemma}[Bounding in small $\lambda$ regime]
	\label{lm:deriv.bound}
	Suppose that $\lambda_a,\lambda_b\leq1$. \newline Then $[L+\Lambda^*]^{-1}=O(\lambda_a^{-1} \wedge \lambda_b^{-1})$.
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lm:deriv.bound}]
	We first write 
	\begin{equation}
		\begin{aligned}[b]
			[L + \Lambda^*]^{-1} 
			=
			&\begin{bmatrix}
				[V^{-1}]_1
				&
				[V^{-1}]_{12}
				\\
				[V^{-1}]_{21}
				&
				[V^{-1}]_2
			\end{bmatrix}.
		\end{aligned}
	\end{equation}
	We now show that $[V^{-1}]_1=O(\lambda_a^{-1}\wedge\lambda_b^{-1})$. First 
	$|| [V^{-1}]_1 || \leq || [\bar{V}^{-1}]_1 || $ 
	by Lemma~\ref{lm:submat}, and $[\bar{V}^{-1}]_1 = O(\lambda_a^{-1})$ 
	holds because $[\bar{V}^{-1}]_1\lambda_a \preceq I$; see Lemma~\ref{lm:blk.inv.1}. Similarly, $[V^{-1}]_1 = O(\lambda_b^{-1})$ because $||[V^{-1}]_1|| \leq || [\bar{V}^{-1}]_1 || $, and
	$
	[\bar{V}^{-1}]_1 
	=_{(1)}
	\bar{V}_1^{-1}
	+
	\bar{V}_1^{-1}
	\bar{V}_{12}
	[\bar{V}^{-1}]_2 \bar{V}_1^{-1}
	$
	where $=_{(1)}$ follows from \eqref{eq:blk.inv.1.2} of Lemma~\ref{lm:blk.inv.1}, and note that $[\bar{V}^{-1}]_2\lambda_b \preceq I$, whereas $\bar{V}_1^{-1}$ and $\bar{V}_{12}$ are both $O(1)$.
	An analogous argument holds for $[V^{-1}]_2$. It also holds for $[V^{-1}]_{12}$ because $[V^{-1}]_{12} = -V_1^{-1} V_{12} [V^{-1}]_2$, by applying  Lemma~\ref{lm:blk.inv.2} and using both $V_1^{-1}$ and $V_{12}$ are $O(1)$. 
\end{proof}


\begin{lemma}[Bounding in non-small $\lambda$ regime]
	\label{lm:deriv.bound.non.small}
	Suppose that at least one of $\lambda_a,\lambda_b$ is greater than one. Then we have
	\begin{align*}
		[V^{-1}]_1 = O(1\wedge \lambda_a^{-1}), 
		[V^{-1}]_2 = O(1\wedge \lambda_b^{-1}), \ \ 
		[V^{-1}]_{12} = O(1\wedge\lambda_a^{-1}) \ \ O(\lambda_a^{1/2}\lambda_b^{1/2}) O(1\wedge\lambda_b^{-1}).
	\end{align*}
\end{lemma}

\begin{proof}[Proof of Lemma \ref{lm:deriv.bound.non.small}]
	To show the first equation, note that $|| [V^{-1}]_1 || \leq ||[\bar{V}^{-1}]_1||$ by Lemma~\ref{lm:submat}. When $\lambda_a$ is greater than 1,  $[\bar{V}^{-1}]_1\lambda_a\preceq I$. When $\lambda_a$ is small, we have that $[\bar{V}^{-1}]_1$ is itself $O(1)$ because
	$
	[\bar{V}^{-1}]_1 
	=_{(1)}
	\bar{V}_1^{-1}
	+
	\bar{V}_1^{-1}
	\bar{V}_{12}
	[\bar{V}^{-1}]_2 \bar{V}_{21} \bar{V}_1^{-1},
	$
	where $=_{(1)}$ follows from \eqref{eq:blk.inv.1.2} of Lemma~\ref{lm:blk.inv.1}, and $[\bar{V}^{-1}]_2=O(1)$ because, in this regime, $\lambda_a\leq1$ implies $\lambda_b\geq1$. Note that $\bar{V}_1^{-1}$, $\bar{V}_{12}=B_1^\prime B_2$, and $\bar{V}_{21}$ are all $O(1)$ too.
	The second equation follows by the same argument. 
	For the third equation of the lemma, we have
	\begin{align}
		[V^{-1}]_{12} 
		=_{(1)}& -[V^{-1}]_1 V_{12} V_2^{-1}  
		=_{(2)}
		O(1\wedge\lambda_a^{-1}) O(\lambda_a^{1/2}\lambda_b^{1/2}) O(1\wedge\lambda_b^{-1}),
	\end{align} 
	where $=_{(1)}$ follows from Lemma~\ref{lm:blk.inv.2}, and $=_{(2)}$ follows from the first equation of this lemma.
\end{proof}



\begin{lemma}[Bounding of lower powers]
	\label{lm:deriv.bound.lower}
	Let $n$ be a positive even number.\newline  Then
$
		|| L^{1/n} [L+\Lambda^*]^{-1/n} ||\leq 1.
$
\end{lemma}

\begin{proof}[Proof of Lemma \ref{lm:deriv.bound.lower}] We have
	\begin{align}
		|| L^{1/n} [L+\Lambda^*]^{-1/n}  ||^2
		=&
		\bar{\rho}(L^{1/n} [L+\Lambda^*]^{-2/n} L^{1/n}) 
		\nonumber\\
		=&
		\bar{\rho}(L^{2/n} [L+\Lambda^*]^{-2/n}) 
		\leq_{(1)}
		|| L^{2/n} [L+\Lambda^*]^{-2/n} ||, 
	\end{align}
	where $\leq_{(1)}$ follows from Lemma~\ref{lm:norm.eig}.
	By iterating the argument above enough times, we get that $|| L^{1/n} [L+\Lambda^*]^{-1/n}  ||$ is bounded by some positive finite power of 
	\begin{align}
		\bar{\rho}(L^{1/2} [L+\Lambda^*]^{-1} L^{1/2}) 
		=&
		\bar{\rho}( [L+\Lambda^*]^{-1/2}L [L+\Lambda^*]^{-1/2})
		\leq_{(1)}1,
	\end{align}
	where $\leq_{(1)}$ holds because clearly $L \preceq L+\Lambda^*$ (see Lemma~\ref{lm:pd.var}), and
	\begin{align}
		L \preceq L+\Lambda^* 
		\iff 
		[L+\Lambda^* ]^{-1/2}L[L+\Lambda^* ]^{-1/2} \preceq I.
	\end{align}
	Note that $L+\Lambda^*$ is a positive definite matrix, because $\Lambda^*$ is positive definite -- see Lemma~\ref{lm:pd.var}.
\end{proof}





\begin{lemma}[Factorization]
	\label{lm:factor}
	\begin{equation*}
		[V^{-1}]_{12} \lambda_a^{1/2}
		-
		\mathcal{A}_{12} [V^{-1}]_2  \phi \lambda_b^{1/2}
		=\,
		-V_1^{-1} 
		\left[
		B_1^\prime B_2 \lambda_a^{1/2} 
		+B_1^\prime B_1\phi\lambda_b^{1/2}\mathcal{A}_{12}
		\right] [V^{-1}]_2.
	\end{equation*}
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lm:factor}]
	We have
	\begin{equation}
		\begin{aligned}[b]
			&
			[V^{-1}]_{12} \lambda_a^{1/2}
			-
			\mathcal{A}_{12} [V^{-1}]_2  \phi \lambda_b^{1/2}
			=_{(1)}
			\left[
			-V_1^{-1} V_{12} \lambda_a^{1/2} - \mathcal{A}_{12}\phi\lambda_b^{1/2}
			\right] [V^{-1}]_2
			\\
			=&_{(2)}
			\left[
			-V_1^{-1}  B_1^\prime B_2 \lambda_a^{1/2} 
			+ (\lambda_aV_1^{-1}-I)\phi\lambda_b^{1/2}\mathcal{A}_{12}
			\right] [V^{-1}]_2
			\\
			=&_{(3)}
			\left[
			-V_1^{-1} B_1^\prime B_2 \lambda_a^{1/2} 
			- V_1^{-1}B_1^\prime B_1\phi\lambda_b^{1/2}\mathcal{A}_{12}
			\right] [V^{-1}]_2
			\\
			=&
			-V_1^{-1} 
			\left[
			B_1^\prime B_2 \lambda_a^{1/2} 
			+ B_1^\prime B_1\phi\lambda_b^{1/2}\mathcal{A}_{12}
			\right] [V^{-1}]_2,
		\end{aligned}
	\end{equation}
	where $=_{(1)}$ follows from $[V^{-1}]_{12}=[V^{-1}]_{21}^\prime = -V_1^{-1}V_{12}[V^{-1}]_2$ -- see Lemma~\ref{lm:blk.inv.2}, and note that $V^{-1}$  is symmetric, $=_{(2)}$ follows from definition of $V_{12}$, and $=_{(3)}$ follows from
	$
	V_1^{-1}\lambda_a + V_1^{-1}B_1^\prime B_1= I.
	$
\end{proof}

\begin{lemma}[Submatrix norms]
	\label{lm:submat}
	We have $|| [V^{-1}]_1 || \leq || [\bar{V}^{-1}]_1 ||$ and $|| [V^{-1}]_2 || \leq || [\bar{V}^{-1}]_2 ||$. 
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lm:submat}]
	Note that $V = \bar{V} + \Lambda^{1/2}[|\phi|I-\phi\mathcal{A}]\Lambda^{1/2}$, where $\Lambda^{1/2}[|\phi|I-\phi\mathcal{A}]\Lambda^{1/2}$ is a positive semidefinite matrix, because $|| \mathcal{A} ||\leq1$. This implies that $\bar{V} \preceq V$ and thus $V^{-1}\preceq \bar{V}^{-1}$. Therefore, for every vector $x$, we have $x^\prime V^{-1} x \leq x^\prime \bar{V}^{-1} x$, including the vectors $x$ that have zeros in their lower halves. That is to say, we also have $x_1^\prime [V^{-1}]_1 x_1 \leq x_1^\prime [\bar{V}^{-1}]_1 x_1$ for every vector $x_1$. This implies that $|| [V^{-1}]_1 || \leq || [\bar{V}^{-1}]_1 ||$. The proof for $|| [V^{-1}]_2 || \leq || [\bar{V}^{-1}]_2 ||$ is analogous.
\end{proof}
\begin{lemma}[Block matrix inversion I]
	\label{lm:blk.inv.1}
	The inverse of $\bar{V}=L + \bar{\Lambda}$ takes the form 
	\begin{equation*}
		\begin{aligned}[b]
			&\begin{bmatrix}
				[\bar{V}^{-1}]_{1} & [\bar{V}^{-1}]_{12} \\
				[\bar{V}^{-1}]_{21} & [\bar{V}^{-1}]_{2}
			\end{bmatrix}
			\\
			=&
			\begin{bmatrix}
				\left[\lambda_a[1-|\phi|] + B_1^\prime \bar{M}_2 B_1\right]^{-1}  
				& 
				-\left[\lambda_a[1-|\phi|] + B_1^\prime \bar{M}_2 B_1\right]^{-1}  
				B_1B_2^\prime
				\bar{V}_2^{-1}
				\\
				-\left[\lambda_b[1-|\phi|] + B_2^\prime \bar{M}_1 B_2\right]^{-1}   
				B_2^\prime B_1 \bar{V}_1^{-1}
				&
				\left[\lambda_b[1-|\phi|] + B_2^\prime \bar{M}_1 B_2\right]^{-1}  
			\end{bmatrix}
			\label{eq:blk.inv.1.1}
		\end{aligned}
	\end{equation*}
	where
	\begin{align*}
		\bar{M}_1
		&:=
		I-B_1 (B_1^\prime B_1 + \lambda_a[1-|\phi|])^{-1} B_1^\prime, \\
		\bar{M}_2
		&:= I-B_2 (B_2^\prime B_2 + \lambda_b[1-|\phi|])^{-1} B_2^\prime
	\end{align*}
	are positive semidefinite matrices. 
	Furthermore, 
	\begin{align}
		[\bar{V}^{-1}]_{1}
		&=
		\bar{V}_1^{-1} + 
		\bar{V}_1^{-1} 
		B_1^\prime B_2 [\bar{V}^{-1}]_2 B_2^\prime B_1  \bar{V}_1^{-1},  \nonumber
	\\
		[\bar{V}^{-1}]_{2}
	&	=
		\bar{V}_2^{-1} + 
		\bar{V}_2^{-1} 
		B_2^\prime B_1 [\bar{V}^{-1}]_1 B_1^\prime B_2 \bar{V}_2^{-1}. 
		\label{eq:blk.inv.1.2}
	\end{align}
\end{lemma}
\begin{proof}[Proof of Lemma~\ref{lm:blk.inv.1}]
	First, we show the equivalence in \eqref{eq:blk.inv.1.1} for the top left block, and the remaining blocks of \eqref{eq:blk.inv.1.1}  proceed by the same argument. By applying \eqref{eq:blk.inv.2.1}, we see that 
	\begin{align}
		[\bar{V}^{-1}]_{1}=&
		\left(
		B_1^\prime B_1 + \lambda_a[1-|\phi|] 
		-  
		B_1^\prime B_2
		\left(B_2^\prime B_2 + \lambda_b[1-|\phi|]\right)^{-1} 
		B_2^\prime B_1
		\right)^{-1} 
		\nonumber
		\\
		=&
		\left(
		\lambda_a[1-|\phi|]  
		+  
		B_1^\prime 
		\left[
		I -  
		B_2
		\left(B_2^\prime B_2 + \lambda_b[1-|\phi|]\right)^{-1} 
		B_2^\prime
		\right]
		B_1
		\right)^{-1}
		\nonumber
		\\
		=&_{(1)}
		\left(
		\lambda_a[1-|\phi|]  
		+  
		B_1^\prime 
		\bar{M}_2
		B_1
		\right)^{-1},
		\label{eq:blk.inv.1.3}
	\end{align}
	where $=_{(1)}$ of \eqref{eq:blk.inv.1.3} follow by the definition of $\bar{M}_2$. 

	Second, the equivalence for \eqref{eq:blk.inv.1.2} follows by the first two rows of \eqref{eq:blk.inv.2.2}.
\end{proof}


\begin{lemma}[Norm and eigenvalues]
	\label{lm:norm.eig}
	For any matrix $A$, $||A|| \geq |\rho|$ where $\rho$ is an eigenvalue of $A$.
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lm:norm.eig}]
	This follows because for any matrix $A$ with eigenvalue $\rho$ (and associated eigenvector $v$),
	$||A|| \geq ||Av|| = || \rho v|| = |\rho| ||v|| = |\rho|$, where the inequality follows by the definition of the spectral norm as the supremum of $||Ax||$ over all unit-length vectors $x$.
\end{proof}


\begin{lemma}[Taking derivatives]
	\label{lm:take.deriv}
	\begin{equation}
		\frac{\partial \lambda_a^{1/2}}{\partial\tilde{\lambda}_a}
		=
		\frac{1}{2\epsilon}
		\left[1+\lambda_a^{\frac{1}{k}}\right]^{\frac{k}{2}}
		\lambda_a^{\frac{1}{2}-\epsilon}.
	\end{equation}
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lm:take.deriv}]
	First,
	\begin{equation}
		\frac{\partial\lambda_a^{1/2}}{\partial\lambda_a^{-1}}
		=-\frac{1}{2}\lambda_a^{3/2}.
	\end{equation}
	From \eqref{eq:tilde.lambda},
	\begin{align}
		\frac{\partial \lambda_a^{-1}}{\partial \tilde{\lambda}_a}
		=&
		k[\tilde{\lambda}_a^{-n}-1]^{k-1}[-n]\tilde{\lambda}_a^{-n-1}
		=
		-kn\tilde{\lambda}_a^{-n-1}[\tilde{\lambda}_a^{-n}-1]^{k-1}
		=
		-kn\tilde{\lambda}_a^{-n-1}[\lambda_a^{-1}]^{\tfrac{k-1}{k}}
	\end{align}
	so that
	\begin{align}
		\frac{\partial \lambda_a^{1/2}}{\partial\tilde{\lambda}_a}
		=&
		\frac{kn}{2}\cdot \tilde{\lambda}_a^{-n-1} \cdot
		\lambda_a^{\tfrac{3}{2}-\tfrac{k-1}{k}}
		=
		\frac{kn}{2}\cdot 
		[1+\lambda_a^{\tfrac{1}{k}}]^{\tfrac{n+1}{n}} \cdot
		\lambda_a^{\tfrac{3}{2}-\tfrac{k-1}{k}}
		=
		\frac{kn}{2}\cdot 
		[1+\lambda_a^{\tfrac{1}{k}}]^{\tfrac{n+1}{n}} \cdot
		\lambda_a^{\tfrac{3}{2}-\tfrac{1}{kn}}
		\nonumber\\
		=&_{(1)}
		\frac{kn}{2}\cdot 
		[1+\lambda_a^{\tfrac{1}{k}}]^{\tfrac{k}{2}} \cdot
		\lambda_a^{\tfrac{3}{2}-\epsilon}
	\end{align}
	where $=_{(1)}$ follows from our choice of $(k,n)$ such that $[2(n+1)]^{-1}=\epsilon$, for some $\epsilon>0$ that satisfies Assumption~\ref{ass:graph.connect.2},  $k=2(n+1)/n$, and $\epsilon=(kn)^{-1}$. 
\end{proof}






Below we present some auxiliary Lemmas used in the proofs.




\begin{lemma}[Positive Definiteness of $\Lambda^*$]
	\label{lm:pd.var}
	$\Lambda^*=\Lambda^{1/2}[-\phi\mathcal{A}+I]\Lambda^{1/2}$ is positive definite. 
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lm:pd.var}]
	Keep in mind that $|\phi| <1$. Then to verify that the variance is positive definite, we only need to verify that $\mathcal{A}$ has eigenvalues between -1 and 1. This is true by noting that $\mathcal{A}$ is the normalized adjacency matrix of a graph.
\end{proof}

\begin{lemma}[Interpreting the Precision Matrix]
	\label{lm:norm.precision}
	Suppose $M\in\mathbb{R}^{n\times n}$ is the positive definite precision matrix of a random vector $\bs{X}:=(\bs{X}_{1},\ldots,\bs{X}_n)'\in\mathbb{R}^n$. Then, the partial correlation
	\begin{equation*}
		\text{corr}(\bs{X}_i,\bs{X}_j \mid \bs{X}_{-(i,j)}) = 
		-\frac{M_{ij}}{(M_{ii}M_{jj})^{1/2}}.
	\end{equation*}
	where $\bs{X}_{-(i,j)}$ represents all elements of $\bs{X}$ except for the $i^{th}$ and $j^{th}$ elements. 
\end{lemma}






\begin{lemma}[Results for Computing Conditional Distribution of Normal Vectors]
	\label{lm:norm.cond}
	For a matrix 
	\begin{equation*}
		\Sigma 
		:=
		\begin{bmatrix}
			\Sigma_{1} & \Sigma_{12}\\ 
			\Sigma_{21} & \Sigma_{2}
		\end{bmatrix} = 
		\begin{bmatrix}
			M_{1} & M_{12} \\ 
			M_{21} & M_{2}
		\end{bmatrix}^{-1},
	\end{equation*}
	we have 
	$
	\Sigma_{1} - \Sigma_{12}\Sigma_{2}^{-1}\Sigma_{21}
	= 
	M_{1}^{-1} \text{and} \ \ 
	\Sigma_{12}\Sigma_{2}^{-1}
	=
	-M_{1}^{-1}M_{12}.
	$
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lm:norm.cond}]
	For the first equality, apply Lemma \ref{lm:blk.inv.2}. For the second equality, apply Lemma \ref{lm:blk.inv.2} and 	$D^{-1}C(A-BDC)^{-1}
	=
	(D-CA^{-1}B)^{-1}CA^{-1}$ for conformal matrices.
\end{proof}


\begin{lemma}[Block Matrix Inversion II]
	\label{lm:blk.inv.2}
	Let $M$ denote a generic matrix in this lemma. Then
	for non-singular $M_{1},M_{2}$,
	\begin{align}
		M^{-1} =&\begin{bmatrix}
			[M^{-1}]_{1} & [M^{-1}]_{12}  \\ 
			[M^{-1}]_{21}  & [M^{-1}]_{2}
		\end{bmatrix}
		\nonumber
		\\=
		&\begin{bmatrix}
			(M_{1} - M_{12} M_{2}^{-1} M_{21})^{-1}
			&
			-(M_{1} - M_{12} M_{2}^{-1} M_{21} )^{-1} M_{12} M_{2}^{-1}
			\\
			-(M_{2} - M_{21} M_{1}^{-1} M_{12} )^{-1} M_{21}M_{1}^{-1}
			&
			(M_{2} - M_{21} M_{1}^{-1} M_{12} )^{-1} 
		\end{bmatrix}. 
		\label{eq:blk.inv.2.1}
	\end{align}
	Furthermore, 
	\begin{align}
		(M_{1}-M_{12}M_{2}^{-1}M_{21})^{-1} 
		=& 
		M_{1}^{-1}  
		+
		M_{1}^{-1}  M_{12} (M_{2} - M_{21} M_{1}^{-1} M_{12} )^{-1}  M_{21} M_{1}^{-1}
		\nonumber\\
		(M_{2}-M_{21} M_{1}^{-1}M_{12})^{-1} 
		=& 
		M_{2}^{-1}  
		+
		M_{2}^{-1}  M_{21} (M_{1}-M_{12}M_{2}^{-1}M_{121})^{-1}  M_{12} M_{2}^{-1}
		\nonumber\\
		(M_{1}-M_{12}M_{2}^{-1}M_{21})^{-1}  M_{12} M_{2}^{-1}
		=&
		M_{1}^{-1} M_{12} (M_{2}-M_{21} M_{1}^{-1}M_{12})^{-1} .
		\label{eq:blk.inv.2.2}
	\end{align}
\end{lemma}




\begin{proof}[Proof of Lemma \ref{lm:equalities}]
