			\leq_{(1)}
			2\bar{d}
		\end{aligned}
	\end{equation}
	where $\leq_{(1)}$ follows because $D^{-1/2}LD^{-1/2}$ is the normalized Laplacian of the bipartite graph, and the eigenvalues of a normalized Laplacian lie in the interval $[0,2]$; see e.g. \cite{Jochmans2019}.

