\det\left(I+L\tfrac{1}{\sigma^2}\Sigma\right)^{-1/2} 
=&
\det\left(\Sigma^{-1}\sigma^2+L\right)^{-1/2} 
\det\left(\Sigma\tfrac{1}{\sigma^2}\right)^{-1/2}  \nonumber\\
=& 
\det\left(\Sigma^{-1}\sigma^2+L\right)^{-1/2} 
\det\left(\Sigma^{-1}\sigma^2\right)^{1/2} \\
=&
\det\left(\Gamma+L\right)^{-1/2} 
\det\left(\Gamma\right)^{1/2}, \nonumber\\
\exp\left(
-\tfrac{1}{2}\bs{x}'
\left[
I - (I+L\tfrac{1}{\sigma^2}\Sigma)^{-1}
\right]
\Sigma^{-1} \bs{x}\right)
=&
\exp\left(
-\tfrac{1}{2}\bs{x}'
\left[
I - \sigma^2\Sigma^{-1}(\sigma^2\Sigma^{-1}+L)^{-1}
\right]
\Sigma^{-1} \bs{x}\right) \nonumber\\
=&
\exp\left(
-\tfrac{1}{2\sigma^2}\bs{x}'
\left[
I - \Gamma(\Gamma+L)^{-1}
\right]
\Gamma\bs{x}\right)  \nonumber \\
=&
\exp\left(
-\tfrac{1}{2\sigma^2}
\left[(\Gamma+L)^{-1}L\bs{x}\right]'
\Gamma\bs{x}\right).
\end{align}
In sum, we have 
\begin{align}
&-2\sigma^2 \left[\log f(\bs{Y}) - \log\det(\sigma^2I_n)^{-1/2}\right]
\nonumber \\
=&
\sigma^2\left[\log\det(\Gamma+L) - \log\det(\Gamma) \right]
+ \bs{Y}'\bs{Y} - (B'\bs{Y})'L^\dagger B'\bs{Y}
+ \left[(\Gamma+L)^{-1}L\bs{x}\right]'\Gamma\bs{x}
\nonumber \\
\propto&
\sigma^2\left[\log\det(\Gamma+L) - \log\det(\Gamma) \right]
+ \left[(\Gamma+L)^{-1}L\bs{x}\right]'\Gamma\bs{x},
\end{align}
where we want to minimize the final expression with respect to $\bs{\lambda}$.
The minimizer $\mu^{\text{mle}}$ can be concentrated out by using its first-order condition:
\begin{align}
\mu^{\text{mle}}
=&
\frac{\tilde{\bs{v}}' \left[ L(\Gamma+L)^{-1}\Gamma + \Gamma(\Gamma+L)^{-1}L \right] L^\dagger B'\bs{Y}}{\tilde{\bs{v}}' \left[ L(\Gamma+L)^{-1}\Gamma + \Gamma(\Gamma+L)^{-1}L \right] \tilde{\bs{v}}}
\nonumber \\
=&
\frac{
	\tilde{\bs{v}}' L(\Gamma+L)^{-1}\Gamma L^\dagger B'\bs{Y} + 
	\tilde{\bs{v}}' \Gamma(\Gamma+L)^{-1} B'\bs{Y}
}{
	2\tilde{\bs{v}}' L(\Gamma+L)^{-1}\Gamma \tilde{\bs{v}}
}.
\end{align}


