\section{Definitions and Notations}
\noindent Graph-theoretic Objects:
\begin{align}
	L &:= B'B 
	&
	L_{2\perp} &:= B_{2,\perp}'B_{2,\perp} 
	&
	B_{2,\perp} &:= [I-B_1(B_1^\prime B_1)^{-1}B_1^\prime] B_2
	\nonumber\\
	A &:= L-D
	&
	D & := \text{diag}(L) 
	& 
	\mathcal{A} &:= D^{-1/2} A D^{-1/2} 
	\nonumber\\
