Compared to Theorem~\ref{thm:mainthm}, 
we have following theorem involved in nonzero mixed Gromov-Witten invariants with one point insertion in favor of the author's belief that the existence of nontrivial Gromov–Witten invariants  matters much for counting symplectic fixed points of Hamiltonian diffeomorphisms on a large class of sympectic manifolds. 

\begin{thm}\label{thm:onept}
Let $(M^{2n},\omega)$ be a closed rational symplectic manifold with  minimal symplectic period $p>0$ which admits a nonzero mixed Gromov-Witten invariant of the form:
\[
    {\rm GW}_{0,l+k+1,A}^{\{1,\ldots,l+1\}}(a_1,\ldots,a_l,[pt],b_1,\ldots,b_k)    
\]
where $A\in H_2(M;\mathbb{Z})/{\rm torsion}$, $a_1,\ldots, a_l\in H_{*<2n}(M;\Q)$ with $2\leq l\in\N$, and the classes $b_1,\ldots,b_k$ are rational homology classes of even degree. Then, for each $\varphi\in\ham(M,\omega)$, 
\begin{equation}\label{e:thm1}\#{\rm Fix}(\varphi)\geq\bigg\lceil\frac{pl} {\langle[\omega],A\rangle}\bigg\rceil.\end{equation} 
Assume in addition that for some $2\leq l\in\N$, $(M^{2n},\omega)$ has a  nonzero Gromov-Witten invariant with fixed marked points of the form 
\[
    {\rm GW}_{0,l+1,A}^{\{1,\ldots,l+1\}}(a_1,\ldots,a_l,[pt])    
\]
with $A\in H_2(M;\mathbb{Z})/{\rm torsion}$ and $a_1,\ldots, a_l\in H_{*<2n}(M;\C)$,  
then 
\begin{equation}\label{e:thm2}
\#{\rm Fix}(\varphi)\geq \bigg\lceil \frac{2p}{\max_i\{2n-a_i\}}\cdot\frac{\langle c_1(TM),A\rangle}{\langle[\omega],A\rangle}\bigg\rceil
\end{equation}
for all $\varphi\in\ham(M,\omega)$.



\end{thm}


Inspired by Schwarz's quantum cuplength estimate, a different way for estimating degenerate symplectic fixed points was obtained by the author via introducing the so-called \textit{fundamental quantum factorization}, see~\cite[Definition~23]{Go}. Using the big quantum homolgy ring, one can extend this notion as follows. 

\begin{df}\label{def:qf}
    Let $(M^{2n},\omega)$ be a closed rational symplectic manifold with  minimal symplectic period $p>0$. We say that $M$ has a \textit{principal fundamental quantum factorization} associated to $\zeta\in \oplus_{i=1}^{n-1}H_{2i}(M,\Lambda_0)$ (denoted by PFQF for short)  \textit{of length $l\in\N$ with order $g\in\N$} if there exist $u_1,\ldots,u_l\in H_{*<2n}(M;\C)$ such that
    $$z T^{-gp}[M]+\beta= u_1*_\zeta\cdots *_\zeta u_l$$
    where $0\neq z\in\C$ and $\beta\in H_{*<2n}(M;\Lambda)$.
\end{df}
Since the existence of PFQF yields a nonzero mixed Gromov-Witten invariant with one point insertion, the first assertion of Theorem~\ref{thm:onept} immediately leads to 
\begin{cor}[{\cite[Theorem~9]{Go}}]\label{thm: factorization}
		Let $(M,\omega)$ be  a closed rational symplectic manifold admitting a PFQF of length $l$ with order $g$. Then each $\varphi\in\ham(M,\omega)$ has at least $\lceil \frac{l}{g}\rceil$ fixed points. 
\end{cor}

