\section{Preliminaries}\label{Sec:pre}


\subsection{Starting notations}
The set of spherical symplectic periods of $(M,\omega)$ is denoted by 
\[
\Gamma_\omega=\{\langle [\omega],A\rangle\;|\;A\in\pi_2(M)\}.
\]
We say that a symplectic manifold $(M,\omega)$ is \textit{rational} if there is a number $p>0$ such that 
$\Gamma_\omega=p\cdot \Z$.  

\begin{df}\label{df:Nov}
\begin{enumerate}
    \item[(1)] The Novikov ring associated to $\Gamma_\omega$ is the ring of formal Laurent series given by 
\[
\Lambda=\bigg\{\sum_{i=1}^{\infty}a_iT^{\lambda_i}\;\big|\;a_i\in\C, \;\lambda_i\in\Gamma_\omega,  \;\forall C>0, \;\#\{i\in \N|a_i\neq 0, \lambda_i<C\}<\infty \bigg\}
\]
where $T$ is a formal variable. 
    \item[(2)] The valuation map on $\Lambda$ is the map
    \[
    \nu:\Lambda\to \Gamma_\omega,\quad \nu\big(\sum_{i=1}^{\infty}a_iT^{\lambda_i}\big)=\max\{-\lambda_i\;|\;a_i\neq 0\}.
    \]
\end{enumerate}
\end{df}

Denote 
\[
\Lambda_0:=\bigg\{\sum_ia_iT^{g_i}\in\Lambda\;\big|\;g_i\geq 0\;\forall i\bigg\}.
\]
Note that $\Lambda$ is the field of fractions of the ring $\Lambda_0$. 
We define the map $\exp:\Lambda_0\to \Lambda_0$ by the usual Taylor series
\[
\exp (a)=\sum_{k=1}^{\infty}\frac{a^k}{k!}.
\]
It is not difficult to see that this is a well-defined map. 


\subsection{Non-Archimedean normed vector space}
\begin{df} Let $V$ be a vector space over $\Lambda$, and $\ell:V\to \R\cup\{-\infty\}$ a function. The pair $(V,\ell)$ is called a non-Archimedean normed vector space if 
\begin{itemize}
    \item[(i)] $\ell(0)=-\infty$, and $\ell(c)\in\R$ for all nonzero $c\in V$; 
    \item[(ii)] $\ell(\alpha\cdot c)=\ell(c)+\nu(\alpha)$ for all $\alpha\in \Lambda$ and $c\in V$;
    \item[(iii)] $\ell(c_1+c_2)\leq\max\{\ell(c_1),\ell(c_2)\}$ for all $c_1,c_2\in V$.
\end{itemize}
\end{df}

\begin{rmk}\label{rmk:nonArchi}
There is a symbolic difference between our property (ii) in the above definition and the property (F2) in \cite[Definition~2.2]{UZ} because of the symbolic difference for the valuation map $\nu$. It is shown that the equality in the (iii) holds if $\ell(c_1)\neq\ell(c_2)$, see~\cite[Proposition~2.1]{EP} or~\cite{UZ}. 
\end{rmk}

\begin{df}
A finite-dimensional non-Archimedean
normed vector space $(V,\ell)$ over a Novikov field $\Lambda$ is called an \textit{orthogonalizable $\Lambda$-space} if there exists an orthogonal basis for $C$, meaning that a finite ordered collection $(v_1,\ldots,v_n)$ of elements of $V$ with the property
\[
\ell\big(\sum_{i=1}^n\alpha_iv_i\big)=\max_{1\leq i\leq n}\ell(\alpha_iv_i)
\]
for all $\alpha_1,\ldots, \alpha_n\in\Lambda$.

\end{df}


\begin{df}
Let $(V,\ell)$ be a non-Archimedean normed vector space over a Novikov field $\Lambda$. We say that two subspaces $E$ and $F$ of $V$ are orthogonal if 
\[
\ell(e+f)=\max\big\{\ell(e),\ell(f)\big\}    
\]
for all $e\in E$ and $f\in F$.
\end{df}

Through a non-Archimedean Gram-Schmidt process, one can show that any subspace $U$ of an orthogonalizable $\Lambda$-space $(V,\ell)$ has an orthogonal complement $W$, i.e., $U\oplus W=V$, and $U$ and $W$ are orthogonal, see~\cite[Corollary~2.19]{UZ}. 


Next we record the following standard result, i.e., the singular value decomposition for linear maps between orthogonalizable spaces, which will be used in the proof of Lemma~\ref{clm:alpha}.    

\begin{lem}[{\cite[Theorem~3.5]{UZ}}]\label{lem:orthogonal}
Let $(V,\ell_V)$ and $(W,\ell_W)$ be two orthogonalizable $\Lambda$-spaces. Let $L:V\to W$ be a $\Lambda$-linear map, and $\xi$  a nonzero vector in ${\rm ker}(L)$. Then there is orthogonal bases $(\xi_1,\ldots,\xi_n)$ for $V$ and $(\eta_1,\ldots,\eta_m)$ for $W$ such that the following holds:
\begin{itemize}
 \item $L\xi_i=\eta_i$ for $i=1,\ldots,r$;
\item $\xi_{r+1}=\xi$;
    \item $(\xi_{r+1},\dots,\xi_n)$ is an orthogonal ordered basis for ${\rm ker}(L)$. 
\end{itemize}
\end{lem}




\subsection{Big quantum homology ring}

In this subsection we will review the \textit{big quantum homology} which is closely related to the deformed spectral invarints. 

Given $A\in H_2(M;\Z)$, for homogeneous classes $a_i\in H_*(M;\Z)/{\rm torsion}, i=1\ldots,k$ with $k\geq 3$ which satisfy
\begin{equation}\label{e:Dformula}
\sum_{i=1}^k(2n-{\rm deg}(a_i))=2n+2\langle c_1(TM),A\rangle + 2k-6, 
\end{equation}
we denote ${\rm GW}_{0,k,A}(a_1,\ldots,a_k)$ the Gromov-Witten invariant by counting (in the appropriate virtual sense) the number of  $J$-holomorphic spheres in the class $A$ passing through the submanifolds $N_i$, where $J$ is a generic almost complex structure compactible with $\omega$ and the $N_i$ are generic cycles representing the classes $a_i$, see Ruan and Tian~\cite{RT}, Fukaya and Ono~\cite{FO} and Ruan~\cite{Ru}. We put $\gw_{0,k,A}(a_1,\ldots,a_k)=0$ unless (\ref{e:Dformula}) holds, and define
\[
    {\rm GW}_k(a_1,\ldots,a_k)=\sum_{A\in H_2(M,\Z)} {\rm GW}_{0,k,A}(a_1,\ldots,a_k)T^{\langle [\omega],A\rangle}. 
\]
%By Gromov compactness, 
Then, by Gromov's compactness theorem, one can extend the above definition linearly over $\Lambda$ to a $\Lambda$-module homomorphism 
\[
 {\rm GW}_k:H_*(M;\Lambda)^{\otimes k}\longrightarrow\Lambda.
\]


For each $\zeta\in   \oplus_{i=0}^{n-1}H_{2i}(M;\Lambda_0)$, we define the $\zeta$-deformed 
quantum multiplication on $H_*(M;\Lambda)$ as follows: for any $a,b\in H_*(M;\Lambda)$, the product
\[
*_\zeta: H_*(M;\Lambda)\otimes H_*(M;\Lambda)\to H_*(M;\Lambda)
\]
is given by the formula
\[\langle a*_\zeta b,c\rangle_{\rm PD_M} =\sum_{k=0}^\infty\frac{1}{k!}{\rm GW}_k(a,b,c,\underbrace{\zeta,\ldots,\zeta}_k)\]
for any $c\in H_*(M;\Lambda)$
where $\langle\cdot,\cdot\rangle_{\rm PD_M}$ denotes the Poincare duality. Alternately, one may express this product in terms of a homogeneous basis as follows. Let $\{c_j\}_{j=1}^K$ be a homogeneous basis for $H_*(M;\Q)$ with dual basis $\{c^j\}$, namely, $c_i \circ c^j=\delta_i^j$ where $\circ$ denotes the Poincar\'{e} intersection pairing. Then the product $*_\zeta$ can be obtained by extending linearly from the following formula
\[
a*_\zeta b=\sum_{A\in H_2(M;\Z)}\sum_{k=0}^\infty\frac{1}{k!}\sum_{j=1}^K{\rm GW}_{0,k+3,A} (a,b,c_j,\underbrace{\zeta,\ldots,\zeta}_k)T^{\langle [\omega],A\rangle}c^j.    
\]
It is well-known that the product $*_\zeta$ is associative and graded commutative, see~\cite{KM}. So we obtain a $\Z_2$-graded commutative ring
\[QH_*(M,\omega)_\zeta=\big(H_*(M;\Lambda),*_\zeta\big)\]
which obviously has the fundamental class $[M]$ as its unity, and which is called the \textit{$\zeta$-deformed homology ring} of $(M,\omega)$.


Recall that the mixed Gromov-Witten invariant ${\rm GW}_{0,k,A}^{\{1,\ldots,l\}}(a_1,\ldots,a_l,b_1,\ldots, b_k)$ from Ruan and Tian~\cite{RT} formally counts (with appropriate signs) the tuples $(u,\vec{w})=(u,\{w_j\}_{j=1}^k)$ consisting of a $J$-holomorphic sphere $u:S^2\to M$ representing the class $A$ with $u(z_i)\in\alpha_i$ and $u(w_j)\in \beta_j$ for all $i,j$, where $\{z_i\}_{i=1}^l$ is a tuple of fixed pairwise distinct points on $S^2$ and $w_j\in S^2\setminus\{z_i\}_{i=1}^l$ for all $j$, and each $\alpha_i$ and $\beta_j$ are generic representatives of the classes $a_i$ and $b_j$ respectively. This quantity is zero unless 
\begin{equation}\label{e:mixdim}
\sum_{i=1}^l(2n-\deg(a_i))+\sum_{j=1}^k(2n-\deg(b_j))=2n+2\langle c_1(TM),A\rangle+2k. 
\end{equation}
Using the splitting, multilinearity and symmetry properties of the mixed Gromov-invariants (cf.~\cite{RT} or~\cite[Chapter~11]{MS}), one can see that an $l$-fold  product is then obtained by extending linearly from the formula
\begin{equation}\label{e:expand}
a_1*_\zeta,\ldots,*_\zeta a_l=\sum_{A\in H_2(M;\Z)}\sum_{k=0}^{\infty}\frac{1}{k!}\sum_{j=1}^K{\rm GW}_{0,l+k+1,A}^{I}(a_1\ldots,a_l,c_j,\underbrace{\zeta,\ldots,\zeta}_k)T^{\langle [\omega],A\rangle}c^j    
\end{equation}
where $I=\{1,\ldots,l+1\}$, and  $\{c_j\}_{j=1}^K$ is a homogeneous basis for $H_*(M;\Q)$ with dual basis $\{c^j\}$. 


As a vector space over $\C$, the big quantum homology $H_*(M;\Lambda)$ is isomorphic to $H_*(M;\C)\otimes_\C\Lambda$. And each element $a\in H_*(M;\Lambda)$ can be written as $a=\sum_{g\in\Gamma_\omega}a_gT^g$ with $a_g\in H_*(M;\C)$ and the property that for any $C>0$, 
$$\#\{g\in\Gamma_\omega\;|\;a_g\neq 0, g<C\}<\infty.$$
This latter finiteness condition gives rise to a  valuation function $I_\nu:H_*(M;\Lambda)\to\Gamma_\omega$ defined by
\begin{equation}\label{e:val}
I_\nu(a)=\max\{-g|a_g\neq 0\}. 
\end{equation}
There exists a pairing $\Delta:H_*(M;\Lambda)\times H_*(M;\Lambda)\to \Lambda$ defined by \[
\Delta\bigg(\sum a_gT^g,\sum b_hT^h\bigg)=\sum a_g\circ b_h\cdot T^{g+h}
\]
where $\circ$ stands for the Poincar\'{e} intersection pairing.
It is easy to verify that the pairing is well-defined, and nondegenerate in the sense that $\Delta(a,b)=0$ for all $b$ then $a=0$. Then, by taking  coefficients of the zero-order term in $\Delta(a,b)$ with respect to the formal variant $T$, one can define a $\C$-value nondegenerate paring ${\textstyle\prod}:H_*(M;\Lambda)\times H_*(M;\Lambda)\to \C$ by
\begin{equation}\label{e:pair}
\prod\bigg(\sum a_gT^g,\sum b_hT^h\bigg)=\sum a_g\circ b_{-g} 
\end{equation}
(see~page 1359 in~\cite{Us} or~\cite[Chapter~15]{FOOO}).

\subsubsection{Deformed quantum cuplength}
Schwarz~\cite[Section~2.2]{Sc2} generalized the notion of classical cuplength to small quantum cohomology, called \textit{quantum cuplength}, and employed it to obtain some estimates for the number of 1-periodic solutions of Hamiltonian equations. Now we further generalize this invariant to our deformed quantum homology as follows.  

Given $\zeta\in  \oplus_{i=0}^{n-1}H_{2i}(M;\Lambda_0)$, for homology classes $\alpha_1,\ldots,\alpha_k\in H_*(M;\Lambda)$, using the splitting property of the Gromov invariants,  the $k$-fold big quantum product can be represented as a formal series in $H_*(M;\Lambda)$
\[
\alpha_1*_\zeta\ldots *_\zeta\alpha_k=\sum (\alpha_1*_\zeta\ldots *_\zeta\alpha_k)_g T^g.
\]

\begin{df}\label{df:bcl}
The $\zeta$-deformed quantum cuplength for $g\in\Gamma_\omega$ is defined as
\[
\bcl(g)=\max\big\{k+1\;|\;\exists\;a_i\in H_{*<2n}(M;\C)\;\hbox{such that}\;(a_1*_\zeta\ldots *_\zeta a_k)_g\neq 0\big\}     
\]
if there exist homology classes $a_i\in H_{*<2n}(M;\C)$ such that $(a_1*_\zeta\ldots *_\zeta a_k)_g\neq 0$, and we let $\bcl(g)=0$ if 
$(a_1*_\zeta\ldots *_\zeta a_k)_g=0$ for arbitrary nonzero classes $a_1,\ldots,a_k\in H_*(M;\C)$. 
\end{df}


\begin{rmk}
Obviously, $g>0$ if $\bcl(g)>0$. From the properties of Gromov-Witten invariants (especially, corresponding to the term for which there are no $\zeta$ as inserted classes, and no $J$-holomorphic spheres representing $A=0\in H_*(M;\Z)$ in the relavent Gromov-Witten invariants), one can see that 
\[
a_1*_\zeta\ldots *_\zeta a_k=a_1\cap\ldots \cap a_k+\sum_{0<g\in\Gamma_\omega} b_g T^g
\]
for any $a_1,\ldots,a_k\in H_*(M;\C)$ where $\cap$ stands for the usual homology intersection product. Therefore, the classical cuplength coincides with $\bcl(0)$, and $\bcl(g)=0$ for all $g\in\{\gamma\in\Gamma_\omega|\gamma<0\}$. 

\end{rmk}


\subsubsection{Morse theoretical big quantum homology}

The $\zeta$-deformed quantum ring  $H_*(M;\Lambda)$ has a Morse theoretical interpretation which we describe as follows. Let $\{\beta_i\}_{i=1}^m$ be a basis of $\oplus_{i=0}^{n-2}H_{2i}(M,\Q)$. Thom's theorem~\cite[Th\'{e}or\`{e}me II.29]{Th} implies that one may choose an embedding 
\begin{equation}\label{e:delta}
f_i:\Delta_i\longrightarrow M
\end{equation}
as a representative for each $\beta_i$ (i.e., $f_{i*}[\Delta_i]=\beta_i$), where each $\Delta_i$, $i=1,\ldots, m$, is a smooth closed oriented manifold of dimension $2d(i)$. For simplicity, hereafter we denote
$$\delta(I):=\sum^k_{j=1}(2n-2d(i_j)-2).$$


Given $\zeta\in\oplus_{i=0}^{n-1}H_{2i}(M,\Lambda_0)$, we let $\theta\in \Omega^2(M;\Lambda_0)$ be a closed Novikov-ring valued two-form which is Poincar\'{e} dual to the degree-$(2n-2)$ component of $\zeta$. Then we have
\[
\zeta-{\rm PD_M}[\theta]=\sum_{i=1}^ma_i\beta_i\in \bigoplus_{i=0}^{n-2}H_{2i}(M,\Lambda_0) 
\]
where $a_i\in\Lambda_0$ for all $i\in\{1,\ldots,m\}$. For any $I=(i_1,\ldots,i_k)\in \{1,\ldots, m\}^k$, we set
\[
a_I=a_{i_1}\ldots a_{i_k}. 
\]


Let $f\in C^\infty (M,\R)$ be a Morse function. Given $\zeta\in   \oplus_{i=0}^{n-1}H_{2i}(M;\Lambda_0)$, we choose a generic Riemannian metric $\rho$ on $M$ such that the stable and unstable manifolds $W^s(f),W^u(f)$ for  $x,y\in {\rm Crit}(f)$ transverse both to each other and to the maps $f_i:\Delta_i\to M$. A grading 
\[{\rm ind}_f:{\rm Crit}(f)\longrightarrow \{0,\ldots, 2n\}\]
is given by the Morse index. Denote
\[
\mathcal{M}_{x,y}(f,\rho)=\big\{\gamma\in C^\infty(\R, M)\;\big|\;\dot{\gamma}+{\rm grad}_\rho f(\gamma)=0,\;\gamma(-\infty)=x,\;\gamma(+\infty)=y\big\}. 
\]
Since $\dim \widehat{\mathcal{M}}_{x,y}(f,\rho)={\rm ind}_f(x)-{\rm ind}_f(y)$ and $\widehat{\mathcal{M}}_{x,y}(f,\rho)$ carries a free $\R$-action, if ${\rm ind}_f(x)={\rm ind}_f(y)+1$ then the moduli space 
\[\mathcal{M}_{x,y}(f,\rho)=\widehat{\mathcal{M}}_{x,y}(f,\rho)/\R\]
is a compact 0-dimensional manifold. 
Equipping unstable manifolds with  arbitrary orientations, together with the orientation of $M$, gives rise to orientations on $\widehat{\mathcal{M}}_{x,y}(f,\rho)$, which, compared with the canonical orientation by the flow, assign a sign to every element $[\gamma]\in \mathcal{M}_{x,y}(f,\rho)$ provided that ${\rm ind}_f(x)={\rm ind}_f(y)+1$. Then we obtain a Morse complex
\[
CM_k(f;\Z)=\sum_{\substack{p\in{\rm Crit}(f),\\{\rm ind}_f(p)=k}}\Z \langle p \rangle
\]
with differential \[\partial:CM_{k+1}(f;\Z)\to CM_k(f;\Z), 
\quad
\partial x=\sum_{{\rm ind}_f(x)={\rm ind}_f(y)+1}\sharp_{\rm alg} \mathcal{M}_{x,y}(f,\rho)\cdot y
\]
where $\sharp_{\rm alg} \mathcal{M}_{x,y}(f,\rho)\in\Z$ is the number of the negative gradient flowlines counted with sign. The homology of the complex $(CM(f;\Z),\partial)$ is called  \textit{Morse homology} of $(f,\rho)$ with integer coefficients, naturally isomorphic to the singular homology  $H_*(M;\Z)$. 

We now consider a complex with $\Lambda$-coefficients
\[
CM_*(f;\Lambda)=CM_*(f;\Z)\otimes_{\Z}\Lambda
\]
with differential $\partial^{f}:CM(f;\Lambda)\to CM(f;\Lambda)$ given by $\partial\otimes_{\Z} {\rm id}$. The homology of this complex is independent of the choice of $\rho$, and naturally isomorphic to $H_*(M;\Lambda)$. We denote it by $HM_*(f;\Lambda)$. 


The $\zeta$-deformed  
quantum multiplication on $H_*(M;\Lambda)$ has the following Morse theoretical description. Let $(f,\rho^0), (g,\rho^1), (h,\rho^2)$ be three Morse-Smale pairs as above. 
Let $J$ be an almost complex structure on $M$ which smoothly depends on $z\in\C P^1$. Given $A\in\pi_2(M)$, we consider the space of $J$-holomorphic spheres
\[
\mathcal{M}_A(J)=\{u:\C P^1\to M\;|\;du(z)\circ j=J(z,u(z))du(z),\;[u]=A\}. 
\]
Now we define
\[
\mathcal{M}_k(A,J)=\big\{(u,\vec{z})\in \mathcal{M}_A(J)\times (\C P^1)^k\big\},
\]
and denote by $\overline{\mathcal{M}}_k(A,J)$ the compactification of this space with evaluation maps $ev_i\;(1\leq i\leq k)$ at the $i$-th marked point. For the marked space $(\C P^1,0,-1,\infty)$, each element $(u,\vec{z})$ in $\mathcal{M}_k(A,J)$ carries the natural evaluation maps $ev_0,ev_{-1},ev_\infty$ given by $ev_0(u,\vec{z})=u(0)$, $ev_{-1}(u,\vec{z})=u(-1)$ and $ev_\infty(u,\vec{z})=u(\infty)$. For $p\in\crit (f),q\in\crit (g),r\in\crit(h)$, let $\iota^0:W^u(p)\to M$, $\iota^1:W^u(q)\to M$, $\iota^2:W^s(r)\to M$ denote the inclusion maps. The fiber product
\[
\overline{\mathcal{M}}_k(A,J)_{(ev_0,ev_{-1},ev_\infty,ev_1,\ldots,ev_k)}\times _{(\iota^0,\iota^1,\iota^2,f_{i_1},\ldots,f_{i_k})}W^u(p)\times W^u(q)\times W^s(r)\times \Delta_{i_1}\times\ldots\times \Delta_{i_k}
\]
has a Kuranishi structure (cf.~\cite{FO,FOOO1,FOOO2}) with corners of dimension
$$\ind_f(p)+\ind_g(q)-\ind_h(r)+2\langle c_1(TM),A\rangle-2n-\delta(I).$$ 
Then where the associated multisections are denoted by $\mathsf{s}_{P,I}$, the 
$\zeta$-deformed quantum product
\[*_\zeta^{\rm Morse}:CM_*(f;\Lambda)\times CM_*(g;\Lambda)\longrightarrow CM_*(h;\Lambda)\]
is defined by extending linearly from
$p*_\zeta^{\rm Morse}q$ for $p\in\crit(f)$ and $q\in \crit(g)$ given by 
\[
p*_\zeta^{\rm Morse}q=\sum_{k=0}^\infty
\frac{1}{k!}\sum_{\substack{A\in\pi_2(M),\\r\in\crit(h)}}\sum_{\substack{I\in\{1,\ldots,m\}^k,\\\ind_f(p)+\ind_g(q)-\ind_h(r)=2n+\delta(I)-2c_1(A)}}|\mathsf{s}_{P,I}^{-1}(0)|\exp\big(\int_A\theta\big)a_IT^{\int_A\omega}r
\]%$w^s(h)=W^u(-h)$, CM(-h,\Lambda) is dual Morse complex of CM(h,\Lambda)
where $|\mathsf{s}_{P,I}^{-1}(0)|$ denotes the sum of the rational multiplicities of the points of the zero-dimensional vanishing locus of 
$\mathsf{s}_{P,I}$. On homology level (after identifying the Morse homology with the $\zeta$-deformed homology), the map $*_\zeta^{\rm Morse}$ induces a map from $H_*(M;\Lambda)\otimes H_*(M;\Lambda)$ to $H_*(M;\Lambda)$ by sending $a\otimes b$ to
\[
\sum_{k=0}^\infty\frac{1}{k!}\sum_{j=1}^K\sum_{A\in\pi_2(M)}\sum_{I\in\{1,\ldots,m\}^k}{\rm GW}_{0,k+3,A}(a,b,c_j,a_{i_1}\beta_{i_1},\ldots,a_{i_k}\beta_{i_k})\exp\big(\int_A\theta\big)T^{\int_A\omega}c^j
\]
where$\{c_j\}_{j=1}^K$ is a homogeneous basis for $H_*(M;\Q)$ with dual basis $\{c^j\}$. 
Since $\zeta={\rm PD_M}[\theta]+\sum^m_{i=1}a_i\beta_i$, it follows from the divisor axiom of Gromov-Witten invariants~\cite[Proposition~7.5.7]{MS} that the last formula is 
\[
\sum_{k=0}^\infty\frac{1}{k!}\sum_{j=1}^K\sum_{A\in\pi_2(M)}{\rm GW}_{0,k+3,A}(a,b,c_j,\underbrace{\zeta,\ldots,\zeta}_k)T^{\int_A\omega}c^j
\]
which coincides with the $\zeta$-deformed quantum multiplication $*_\zeta$ on $H_*(M;\Lambda)$. 

 \begin{rmk}
In the construction of big quantum homology ring,  one can avoid using Kuranishi structures by imposing the assumption that $(M,\omega)$ is {\it strongly semipositive} (i.e., for any $A\in\pi_2(M)$ with $2-n\leq\langle c_1(TM),A\rangle<0$ we have $\int_A\omega\leq 0$) and instead follow the constructions of Hofer and
Salamon~\cite{HS}, see~\cite[Section~3.2.2]{Us}. This will not effect our applications in Section~\ref{sect:app} since those examples listed there meet the latter condition. The generalization to all closed symplectic manifolds requires more subtle technical arguments, but less than the technical hurdles overcome in the construction of $A_\infty$–algebras associated to appropriate Lagrangian submanifolds~\cite{FOOO1}, and hence one
could just appeal to that work or~\cite{FOOO2}.

 \end{rmk}



\subsection{Deformed Hamiltonian Floer homology}
Following Usher~\cite{Us} (or cf.~\cite{FOOO}), we review the construction of deformed Hamiltonian Floer homology with additional algebraic structures. 

\subsubsection{Deformed Floer complexes}
Let $\rH=C^\infty(S^1\times M,\R)$. For $H\in\rH$, we denote by $\{\varphi_H^t\}_{t\in[0,1]}$ the Hamiltonian isotopy of $H$ which is given by integrating the time-dependent vector field $X_{H_t}$, where $H_t=H(t,\cdot)$ and $X_{H_t}$ is determined uniquely by $-dH_t=\omega(X_{H_t},\cdot)$. Denote by ${\rm Per}(H)$ the set of contractible $1$-periodic orbits of the Hamiltonian flow of $H$. We say that $H$ is \textit{normalized} if $\int^1_0H_t\omega^n=0$ for all $t\in S^1$.  


We consider the set $\mathcal{L}_{pt}(M)$ of all pairs $(x,\bar{x})$ where $x:S^1\to M$ is a loop and $\bar{x}:D^2\to M$ a disc with $\bar{x}|_{\partial D^2}=x$, called a \textit{capping} of $x$. We denote by $\pi_2(x)$ the set of homotopy classes of such $\bar{x}'s$.  We identify $(x,\bar{x})$ and $(x',\bar{x}')$ if $x=x'$ and $\bar{x}$ is homotopic to $\bar{x}'$ relative to the boundary $x$. 

Given $H\in\rH$, we consider the action functional 
$\ah:\mathcal{L}_{pt}(M)\longrightarrow \R$
given by
\[
\ah(x,\bar{x})=-\int_{D}\bar{x}^*\omega+\int^1_0H(t,x(t))dt.
\]
Let ${\rm Crit}(\ah)$ denote the set of critical points of $\ah$. It is easy to see that 
\[{\rm Crit}(\ah)=\big\{(x,\bar{x})\in\mathcal{L}_{pt}(M)\;\big|\;\dot{x}(t)=X_{H_t}(x(t))\big\}.\]
For each $H\in\rH$, we define the \textit{action spectrum} of $H$ as 
\[
{\rm Spec}(H)=\big\{\ah(x,\bar{x})\;\big|\;(x,\bar{x})\in {\rm Crit}(\ah)\big\}. 
\]
It is shown that the set ${\rm Spec}(H)$ has measure zero in $\R$ for any $H\in\rH$ for arbitrary $(M,\omega)$ by Oh~\cite{Oh} and for aspherical $(M,\omega)$ by Schwarz~\cite{Sc1}, and that for any one-parameter smooth family of normalized periodic Hamiltonians $H^s:S^1\times M\to \R, s\in[0,1]$ with
\[
\varphi_{H^s}^0\equiv id,\quad
\varphi_{H^s}^1\equiv \varphi_{H^0}^1\quad \hbox{for all}\;s\in[0,1], 
\]
we have ${\rm Spec}(H^s)={\rm Spec}(H^0)$, see~\cite[Corollary 10.3]{FOOO}. 

We say that $H$ is \textit{nondegenerate} if for each $p\in{\rm Fix}(\varphi_H^1)$, $1$ is not the eigenvalue of the linearization $d_p\varphi_H^1:T_pM\to T_pM$. Clearly, for a nondegenerate Hamiltonian $H$, the cardinality of the set ${\rm Per}(H)$ of one-periodic solutions of $\dot{x}(t)=X_{H_t}(x(t))$ is finite. In this case, we  have an integer grading 
\[\mu_H:{\rm Crit}(\ah)\longrightarrow\Z\]
induced by the Conley-Zehnder index. More specifically, in this paper, the Conley-Zehnder index is the negative of that in~\cite{CZ}, and has the property that for a $C^2$-small Morse function $f$, each constant Hamiltonian one-periodic orbit $q$ with its constant capping $\bar{q}$ satisfies $\mu_H(q,\bar{q})=n-{\rm ind}_q(f)$, where ${\rm ind}_q(f)$ denotes the Morse index of $f$ at the critical point $q$.  

We introduce an equivalence relation $\sim$ on ${\rm Crit}(\ah)$ such that $(x_1,\bar{x}_1)\sim (x_2,\bar{x}_2)$ if and only if $x_1=x_2$ and  \[\int_{D^2}\bar{x}_1^*\omega=\int_{D^2}\bar{x}_2^*\omega.\] 
Denote by $\mathcal{O}(H)$ the set of such equivalence classes. The equivalence class of $(x,\bar{x})\in{\rm Crit}(\ah)$ is denoted by $[x,\bar{x}]$. Then we have the maps 
\[{\rm Crit}(\ah)\longrightarrow\mathcal{O}(H)\longrightarrow{\rm Per}(H)\]
by $(x,\bar{x})\mapsto [x,\bar{x}]$ and $[x,\bar{x}]\mapsto x$. 

We define the Floer complex $CF_*(H)$ of a nondegenerate Hamiltonian $H\in\rH$ as the set of elements having the formal sum
\begin{equation}\label{e:chain}
\sum_{[x,\bar{x}]\in \mathcal{O}(H)} \alpha_{[x,\bar{x}]}[x,\bar{x}],\; \alpha_{[x,\bar{x}]}\in\C    
\end{equation}
with the property that for any $C>0$, 
\[\#\big\{[x,\bar{x}]|\alpha_{[x,\bar{x}]}\neq 0, \ah([x,\bar{x}])>C\big\}<\infty.\]
The Novikov field $\Lambda$ acts on 
$CF_*(H)$ as follows: for each $\lambda\in \Gamma_\omega$, we pick an arbitrary class $A_\lambda\in\pi_2(M)$ satisfying $\langle [\omega],A_\lambda\rangle=\lambda$ and define the action
\[
\big(\sum a_iT^{\lambda_i}\big)\cdot\big(\sum \beta_{[x,\bar{x}]}[x,\bar{x}]\big)=\sum a_i\beta_{[x,\bar{x}]}[x,\bar{x}\sharp A_{\lambda_i}].
\]
It is easy to verify that this action is well-defined. Consequently, $CF_*(H)$ is a vector space over $\Lambda$ of finite dimension equal to $\sharp{\rm Per}(H)$. More precisely, for each $x\in {\rm Per}(H)$, if we pick a lifting $[x,\bar{x}]\in\mathcal{O}(H)$, then any element $c$ of $CF_*(H)$ is uniquely written as a finite sum 
\begin{equation}\label{e:sum}
c=\sum_{x\in {\rm Per}(H)} a_x[x,\bar{x}],\;a_x\in\Lambda.  
\end{equation}

\begin{df} The filtration function $\ell_H$ on $CF_*(H)$ is defined by
\[
\ell_H(c)=\max\big\{\ah([x,\bar{x}])\;\big|\;\alpha_{[x,\bar{x}]}\neq 0\big\}
\]
for any $c=\sum \alpha_{[x,\bar{x}]}[x,\bar{x}]$ of the form (\ref{e:chain}).
\end{df}

Equivalently, after fixing a lifting $x\to[x,\bar{x}]$ for each $x\in{\rm Per}(H)$, one can define the value of $\ell_H$ at $c$ given in the form (\ref{e:sum}) by
\[\ell_H(c)=\max\{\ah([x,\bar{x}])+\nu(a_x)|a_x\neq 0\}
\]
where $\nu$ is the valuation map on $\Lambda$ (cf.  Definition~$\ref{df:Nov}$(2)). It is easy to verify that  $(CF_*(H),\ell_H)$ is an orthogonalizable $\Lambda$-space. Moreover, $\ell_H$ gives rise to a filtration on $CF_*(H)$ by
\[
CF_*^\lambda(H)=\{c\in CF_*(H)\;|\;\ell_H(c)\leq \lambda\}\quad\hbox{for any}\;\lambda\in\R.
\]


\subsubsection{Gradings}
As a vector space over $\Lambda$, $CF_*(H)$ carries a natural $\Z_2$-grading which we define as follows. 

\[
CF_0(H)=\bigoplus_{\substack{x\in{\rm Per}(H)\\n-\mu_H(x,\bar{x})=0\;{\rm mod}\;2}} \Lambda[x,\bar{x}],
\]
\[
CF_1(H)=\bigoplus_{\substack{x\in{\rm Per}(H)\\n-\mu_H(x,\bar{x})=1\;{\rm mod}\;2}} \Lambda[x,\bar{x}].
\]
Note that the parity of $\mu_H(x,\bar{x})$ depends only on $x\in{\rm Per}(H)$ but not on its capping $\bar{x}$,  since for any two cappings $w$ and $u$ 
of $x$, we have
\[
\mu_H(x,w)-\mu_H(x,u)=2\langle c_1(TM),[w\sharp u']\rangle.
\]
Here $w\sharp u':S^2\to M$ is a $2$-sphere given by gluing $w$ and $u'$ along $x$ where $u'$ is the $u$ with opposite orientation.  
%Clearly, $CF_i(H), i=1,2$ are finite dimensional vector spaces over $\Lambda$, and the restriction of $\ell_H$ to these two spaces gives rise to two non-Archimedean normed vector spaces $(CF_0(H),\ell_H)$ and $(CF_1(H),\ell_H)$ which are orthogonalizable $\Lambda$-spaces. 

\subsubsection{Maslov index of homotopy classes of cylinders}

Let $H_{\pm}\in\rH$ and $x_{\pm}\in{\rm Per}(H_{\pm})$. We denote by $\pi_2(x_-,x_+)$ the set of path components of the space of continuous maps $u:[-\infty,+\infty]\times S^1\to M$ satisfying $u(\{\pm\infty\}\times S^1)=x_\pm$. 

Given $H_i\in\rH$ and $x_i\in{\rm Per}(H_i),i=0,1,2$, there is the natural gluing map
\[
\pi_2(x_0,x_1)\times \pi_2(x_1,x_2)\longrightarrow \pi_2(x_0,x_2)
\]
\[(C_0,C_1)\longmapsto C_0\sharp C_1\]
where $C_0\sharp C_1$ is the equivalence class of a gluing map $w$ of any two representatives $u,v$ of $C_0$ and $C_1$. More precisely, let $u,v:[-\infty,+\infty]\times S^1\to M$ be two continuous maps which represent $C_0$ and $C_1$ respectively, and define $w:[-\infty,+\infty]\times S^1\to M$
by putting 
$w(s,t)=u(-\log (-s),t)$ for $s\leq0$ and 
$w(s,t)=v(\log (s),t)$ for $s\geq 0$.  Here $\log:[0,\infty]\to[-\infty,\infty]$ is an extension of the natural logarithm. 

Similarly, one can define a concatenation map
\[\pi_2(x_0)\times\pi_2(x_0,x_1)\longrightarrow\pi_2(x_1),\quad (\omega,C)\longmapsto \omega\sharp C.\]
For $x_{\pm}\in{\rm Per}(H_{\pm})$, we now use the Conley-Zehnder index to define a map $\mu$ on $\pi_2(x_-,x_+)$ as follows. For $C\in \pi_2(x_-,x_+)$, we pick an arbitrary representative $u:[-\infty,+\infty]\times S^1\to M$ of $C$, and pick any disc $w$ such that $w|_{\partial D^2}=x_-$ (note that $x_-$ is contractible by our assumption). We then glue the negative end of $u$ to the boundary of $w$ along $x_-$ to obtain a disc $w\sharp u:D^2\to M$ with $w\sharp u|_{\partial D^2}=x_+$. Then we define
\[
\mu(C)=\mu_{H_+}(x_+,w\sharp u)-\mu_{H_-}(x_-,w).
\]
Clearly, $\mu(C)$ is independent of the choice of $u$ and $w$, and has the property
\[\mu(C_0\sharp C_1)=\mu(C_0)+\mu(C_1)\quad \hbox{for all}\;  C_0\in \pi_2(x_0,x_1), C_1\in \pi_2(x_1,x_2).\]




\subsubsection{Deformed Floer boundary maps}

\begin{df}
We say that $H\in\rH$ is strongly nondegenerate if for each $p\in{\rm Fix}(\varphi_H^1)$, $1$ is not an eigenvalue of the linearization $d_p\varphi_H^1:T_pM\to T_pM$, and each submanifold $f_i(\Delta_i)$, $i=1,\ldots, m$, does not intersect the set $\{\varphi_H^t(p)|t\in[0,1]\}$.
\end{df}

By the Sard-Smale theorem, one can show that the space of strongly nondegenerate Hamiltonians is residual in $\rH$ in the $C^l$-topology for all $2\leq l\leq\infty$, see~Appendix A in~\cite{Us}.  

Let $J=\{J_t\}_{t\in S^1}$ be an $S^1$-family of $\omega$-compatible almost complex structures on $M$, and $H\in\rH$ a strongly nondegenerate Hamiltonian. Given $x_\pm\in{\rm Per}(H)$, we consider the solution $u:\R\times S^1\to M$ of the Floer equation:
\[
\overline{\partial}_{J,H}u:=\partial_su+J(t,u(s,t))\big(\partial_t u-X_H(t,u(s,t))\big)=0
\]
with the asymptotic boundary condition $u(s,t)=x_\pm(t)$ for $s\to\pm \infty$. Then $u$ extends continuously to a map $u:[-\infty,\infty]\times S^1\to M$ with $u(\pm\infty,t)=x_\pm(t)$, which represents some class $C\in\pi_2(x_-,x_+)$.  We denote by $\widehat{\mathcal{M}}(x_-,x_+,C;H,J)$ the moduli space of such solutions with
\[\int_{\R\times S^1}\big|\partial_s u\big|^2_{J_t}dsdt<\infty\]
where $|\cdot|_{J_t}$ is the norm associated to an $S^1$-family of metrics induced by $J$ for all $t$.  

Consider the product space
\[\widehat{\mathcal{M}}_k(x_-,x_+,C;H,J)=\widehat{\mathcal{M}}(x_-,x_+,C;H,J)\times (\R\times S^1)^k.\]
Note that $\R$ acts on each factor by $s$-translation, we have a quotient
\[\mathcal{M}_k(x_-,x_+,C;H,J)=\widehat{\mathcal{M}}_k(x_-,x_+,C;H,J)/\R.\] 
Using the constructions of Kuranishi structures  from~\cite[Theorem~19.44]{FO}, one can show that the 
compactification of $\mathcal{M}_k(x_-,x_+,C;H,J)$, denoted by $\overline{\mathcal{M}}_k(x_-,x_+,C;H,J)$, admits an oriented Kuranishi structure with corners, see~\cite[Section~3.2.2]{Us}. Futhermore, one has evaluation maps
\[
\operatorname{ev}_1,\ldots, \operatorname{ev}_k:\overline{\mathcal{M}}_k(x_-,x_+,C;H,J)\longrightarrow M
\]
given by evluating at the $i$-th marked point, i.e. $\operatorname{ev}_i([u,z_1,\ldots,z_k])=u(z_i)$ for all $[u,z_1,\ldots,z_k]$ in the dense subset $\mathcal{M}_k(x_-,x_+,C;H,J)$ and  $i\in\{1,\ldots,k\}$. %We remark here that each $ev_i$ is weakly submersive
Given an ordered set $I=(i_1,\ldots,i_k)$ with each $i_j\in\{1,\ldots,m\}$,  we consider the fiber product
\[\widetilde{\mathcal{M}}(x_-,x_+,C;\Delta_I):=\overline{\mathcal{M}}(x_-,x_+,C;H,J)_{\operatorname{ev}_1,\ldots,\operatorname{ev}_k}\times_{f_{i_1},\ldots,f_{i_k}}(\Delta_{i_1}\times\cdots\times \Delta_{i_k}).\]
It follows from~\cite[Appendix A1]{FOOO1} or  \cite[Section~3]{FOOO2} that there is an oriented Kuranishi structure with corners on $\widetilde{\mathcal{M}}(x_-,x_+,C;\Delta_I)$ which has the (virtual) dimension
\[
\dim \widetilde{\mathcal{M}}(x_-,x_+,C;\Delta_I)=\mu(C)-\sum^k_{j=1}(2n-2d(i_j)-2)-1.
\]
%Moreover, the codimension-one stratum of the boundary of $\widetilde{\mathcal{M}}(x_-,x_+,C;\Delta_I)$ consists of the interior of 
When $\mu(C)=\delta(I)+1$, we let $\mathsf{s}_{C,I}$ denote the multisection associated to Kuranishi structure on $\widetilde{\mathcal{M}}(x_-,x_+,C;\Delta_I)$, and denote $|\mathsf{s}_{C,I}^{-1}(0)|$ the sum of the rational multiplicities of the points of the zero-dimensional vanishing locus of 
$\mathsf{s}_{C,I}$. 


Following~\cite[Proposition~3.5]{Us} (see also~\cite[Chapter~6]{FOOO}), we will deform the standard Floer differential by a general homology class $\zeta\in\oplus_{i=0}^{n-1}H_{2i}(M,\Lambda_0)$.   For any $[x_-,\bar{x}_-],[x_+,\bar{x}_+]\in\mathcal{O}(H)$, we denote
\[
\mathsf{n}_{(H,J);k}\big([x_-,\bar{x}_-],[x_+,\bar{x}_+]\big)=\sum_{\substack{C\in \pi_2(x_-,x_+)\\ [x_+,\bar{x}_+]=[x_+,\bar{x}_-\sharp C]}}\sum_{\substack{I\in \{1,\ldots, m\}^k\\ \mu(C)=\delta(I)+1}}\frac{1}{k!}|\mathsf{s}_{C,I}^{-1}(0)|\exp\big(\int_C\theta\big)a_I.
\]
Here $\bar{x}_-\sharp C$ stands for the concatenation of $\bar{x}$ and any representative $u$ of the class $C$. Clearly, the equivalent class $[x_+,\bar{x}_-\sharp C]$ does not depend on the choice of $u$. Now we define the map $\partial_\zeta^{H,J}: CF_*(H)\to CF_*(H)$
by extending $\Lambda$-linearly from
\[
\partial_\zeta^{H,J}[x_-\bar{x}_-]=\sum_{[x_+,\bar{x}_+]\in\mathcal{O}(H)}\sum_{k=0}^\infty \mathsf{n}_{(H,J);k}\big([x_-,\bar{x}_-],[x_+,\bar{x}_+]\big)[x_+,\bar{x}_+].
\]
Then Propositions~3.5 and 3.6 in~\cite{Us} imply the following. 
\begin{prop}
For any $\zeta\in\oplus_{i=0}^{n-1}H_{2i}(M,\Lambda_0)$,  the $\partial_\zeta^{H,J}$ as above is a well-defined endomorphism and satisfies
\[\big(\partial_\zeta^{H,J}\big)^2=0.\]
\end{prop}

With this preparation regarding the complex, now we can define the $\zeta$-\textit{deformed Floer homology} of $(CF_*(H),\partial_\zeta^{H,J})$ as follows. 
\begin{df}
The homology of the complex $(CF_*(H),\partial_\zeta^{H,J})$ is defined by 
\[HF_\zeta(H)=\frac{{\rm ker}\;\partial_\zeta^{H,J} }{{\rm im}\;\partial_\zeta^{H,J}}.\]
\end{df}
It is shown in~\cite[Proposition~3.8]{Us} that for a strongly nondegenerate $H\in\rH$,  $HF_\zeta(H)$ is independent of the choice of the almost complex structure $J$. This is the reason why we suppress the $J$ from the notation of the deformed Floer homology. Note that the differential $\partial_\zeta^{H,J}$  preserves the $\C$-space $CF_*^\lambda(H)$, the corresponding homology is denoted by $HF_\zeta^\lambda(H)$, called \textit{filtered Floer homology} of $H$.



\subsubsection{Pair of pants products}\label{subsec:concatenation}
For any Hamiltonian $H:S^1\times M\to \R$, one can modify $H$ in a standard way such that the associated Hamiltonian isotopy is constant near $[1]\in S^1$, namely, letting  $H'(t,x)=\chi'(t)H(\chi(t),x)$ for some smooth function $\chi:[0,\frac{1}{2}]\to [0,1]$ with the property that $\chi=0$ near $t=0$ and $\chi=1$ near $t=\frac{1}{2}$. In what follows, we always assume that for some small $\epsilon>0$, $H(t,0)\equiv 0$ for $|t|<\epsilon$. Given two such Hamiltonians $H,K$, we define a new Hamiltonian $H*K:S^1\times M\to\R$ by
\begin{equation}\notag
H*K(t,x)=
\begin{cases}
2H(2t,x)&0\leq t\leq 1/2,\\
2K(2t-1,x)&1/2\leq t\leq 1.\\
\end{cases}
\end{equation}

We now assume that $H,K$ and $H*K$ are  strongly nondegenerate Hamiltonians. 
Then there exists a deformed version of pair of pants product 
\[\bar{*}_\zeta^{\rm PP}:CF_*(H)\otimes CF(K)\to CF(H*K)\]
which resembles the construction of the product on Hamiltonian Floer homology in~\cite{PSS} (see also~\cite{Lu}). The precise definition of the product $\bar{*}_\zeta^{\rm PP}$ is not used in this paper, and hence we will not go into details about it. Here we only mention that $\bar{*}_\zeta^{\rm PP}$ is a chain map and restricts to a map
\[\bar{*}_\zeta^{\rm PP}:CF^{\lambda}(H)\otimes CF^{\mu}(K)\to CF^{\lambda+\mu}(H*K)\]
for all $\lambda,\mu\in\R$, which,on homology level, induces the map 
\[*_\zeta^{\rm PP}:HF^{\lambda}(H)\otimes HF^{\mu}(K)\to HF^{\lambda+\mu}(H*K),\]
see~\cite[Proposition~3.11]{Us}. 


\subsection{PSS isomorphisms}\label{sec:pss}

Following~\cite[Proposition~3.3.2]{Us}, we will define a deformed Piunikhin-Salamon-Schwarz isomorphism from the Morse complex $(CM(f;\Lambda),\partial^f)$ to the $\zeta$-deformed Floer complexes $(CF_*(H),\partial_\zeta^{H,J})$. Such kind of isomorphism has been studied in~\cite{PSS,Lu}. 

For a generic Morse-Smale pair $(f,\rho)$ and a strongly nondegenerate Hamiltonian $H$ on $M$, the deformed PSS map 
\[
\psi^{\pss}_\zeta: (CM(f;\Lambda),\partial^f)\longrightarrow (CF_*(H),\partial_\zeta^{H,J})
\]
is defined by emumerating ``spiked discs" with incidence conditions corresponding to $I=(i_1,\ldots,i_k)$ as follows. 

Let $\chi:\R\to [0,1]$ be a smooth cutoff function satisfying $\chi(s)=0$ for $s\leq 0$, $\chi(s)=1$ for $s\geq 1$ and $\chi'(s)\geq 0$ for all $s$. Given an $S^1$-dependent family of almost complex structures $J$, let $\{J_s\}_{s\in[0,1]}$ be a two-parameters family of almost complex structures such that $J_{0,t}=J_0$,  $J_{1,t}=J_t$ and $J_{s,0}=J_0$ for all $s,t\in[0,1]$. Here $J_0$ is a time-independent almost complex structure compatible with $\omega$. We define the $\R\times S^1$-dependent pair $(H_\chi,J_\chi)$ by 
\[
H_\chi(s,t)=\chi(s)H_t,\quad J_\chi(s,t)=J_{\chi(s),t}. 
\]

Given $\gamma\in{\rm Per}(H)$ and $C\in\pi_2(\gamma)$, we choose any disc $u$ representing $C$ and denote $\mu(C)=\mu_H(\gamma,u)$. Let $\mathcal{M}^{\pss}(\gamma)$ denote the space of the solutions $u:\R\times S^1\to M$ of the Floer equation
\begin{equation}\label{e:sfl}
\partial_su+J_\chi\big(\partial_tu-X_{H_\chi}(u)\big)=0
\end{equation}
with asymptotic boundary condition
$u(+\infty,t)=\gamma(t)$ for all $t$ and finite energy
\[
E(u)=\int_{\R\times S^1}\big|\partial_s u\big|^2_{J_\chi}dsdt.
\]
Note that since $H_\chi\equiv0$ and $J_\chi\equiv J_0$ for $s<0$, the equation (\ref{e:sfl}) becomes $J_0$-homomorphic curve on $(-\infty,0)\times S^1$ with finite energy, the removable singularity theorem implies that  $\lim_{s\to-\infty}u(s,t)$ exists and does not depend on $t$. So one can define the map $ev_{-\infty}:\mathcal{M}^{\pss}(\gamma)\to M$ by
\[
\operatorname{ev}_{-\infty}(u)=\lim_{s\to-\infty}u(s,t).
\]
We now define
\[
\mathcal{M}^{\pss}_k(\gamma,C)=\big\{(u,\vec{z})\in\mathcal{M}^{\pss}(\gamma)\times(\R\times S^1)^k\;\big|\;[u]=C\big\}
\]
and write its standard compactification as $\overline{\mathcal{M}}^{\pss}_k(\gamma,C)$ with evaluation maps $ev_i, i\in\{1,\ldots,k\}$ at the $i$-th marked point and the evaluation map $ev_{-\infty}$ by extending the map $ev_{-\infty}$ on $\mathcal{M}^{\pss}(\gamma)$ as above to the compactification. 

Given $p\in\crit(f)$ and $I=(i_1,\ldots,i_k)\in\{1,\ldots,m\}^k$, let $\iota_p:W^u(p)\hookrightarrow M$ denote the inclusion of the unstable manifold of $p$. Consider the fiber product
\[
\mathcal{M}^{\pss}_k(\gamma,C,p;\Delta_I)=\overline{\mathcal{M}}^{\pss}_k(\gamma,C)_{\operatorname{ev}_{-\infty},\operatorname{ev}_1,\ldots,\operatorname{ev}_k}\times_{\iota_p,f_{i_1},\dots,f_{i_k}}\big(W^u(p)\times\Delta_{i_i}\times\cdots\times\Delta_{i_k}\big)
\]
which has a Kuranishi structure with corners of dimension 
\[
\mu(C)+\ind_f(p)-n-\delta(I).
\]
Let $\mathsf{s}_{\pss}$ denote the corresponding multisection. Then the PSS map $$\psi^{\pss}_{\zeta,H}: (CM(f;\Lambda),\partial^f)\longrightarrow (CF_*(H),\partial_\zeta^{H,J})$$
is defined by extending $\Lambda$-linearly from
\[
\psi^{\pss}_{\zeta,H} p=\sum_{k=0}^\infty\frac{1}{k!}\sum_{\substack{\gamma\in{\rm Per}(H),\\C=[u]\in\pi_2(\gamma)}}\sum_{\substack{I\in\{1,\ldots,m\}^k,\\\mu(C)+\ind_f(p)=n+\delta(I)}}|\mathsf{s}_{\pss}^{-1}(0)|\exp\big(\int u^*\theta\big)a_I[\gamma,u].
\]
It is shown in~\cite[Proposition~3.9]{Us} that the deformed PSS map $\psi^{\pss}_{\zeta,H}$ is a chain map which
induces a ring isomorphism (over $\Lambda$)
\[\Psi^{\rm PSS}_{\zeta,H}: HM(f;\Lambda)\longrightarrow HF_\zeta(H).\]
Moreover, this map respects the $\Z_2$-gradings of the respective complexes. Here we remark that the map $\Psi^{\pss}_{\zeta,H}$ is independent of the choice of the function $\chi$, the metric $\rho$ and the almost complex structures $\{J_s\}_{s\in[0,1]}$. 



\section{Spectral invariants}\label{Sec:spec}

\subsection{Minmax critical value selector}
Fix a ground field $\F$. Let $X$ be a closed smooth manifold of positive dimension. We will denote by $H_*(X)$ the singular homology of $X$ with coefficient field $\F$. 
Let $f\in C^\infty(X,\R)$ be a smooth function. For any $\lambda\in\R$, we define $$X^\lambda:=\{x\in X\;|\;f(x)<\lambda\}.$$

To a non-zero singular homology class $a\in H_*(X)\setminus\{0\}$, we associate a  numerical invariant defined by
$$c_{LS}(a,f)=\inf\{\lambda\in\R\;|\;a\in{\rm im}(i^\lambda_*)\},$$
where $i^\lambda_*:H_*(X^\lambda)\to H_*(X)$ is the map induced by the inclusion $i^\lambda:X^\lambda\to X$. 
The function $$c_{LS}:H_*(X)\setminus\{0\}\times C^\infty(X,\R)\to\R$$ is called the \textit{minmax critical value selector} of $f$. The following  properties are well-known from classical Ljusternik-Schnirelman theory; see, e.g.,~\cite{HZ,Cha,CLOT,GG}.%
%Set $c_{LS}(0,f)=-\infty$.


\begin{prop}\label{pp:minmax}
	The minmax critical value selector $c_{LS}$ satisfies the following properties.
\begin{enumerate}
	\item[{\rm 1.}] $c_{LS}(a,f)$ is a critical value of $f$, and $c_{LS}(k a,f)=c_{LS}(a,f)$ for any nonzero $k\in\F$.
	\item[{\rm 2.}]  $c_{LS}(a,f)$ is Lipschitz continuous in $f$ with respect to the $C^{0}$-distance.
	\item[{\rm 3.}] Let $[pt]$ and $[X]$ denote the point class and the fundamental class, respectively. Then
$$c_{LS}([pt],f)=\min f\leq c_{LS}(a,f)\leq\max f= c_{LS}([X],f).$$
	\item[{\rm 4.}] If $b\neq k[X]$ and $c_{LS}(a\cap b,f)= c_{LS}(a,f)$, then the set
     $$\Sigma=\{x\in\crit(f)\;|\;f(x)= c_{LS}(a,f)\}$$ 
     is homologically non-trivial, i.e. for every open neighborhood $V$ of $\Sigma$ the map $i_*:H_k(V)\to H_k(X)$ induced by the inclusion $i:V\hookrightarrow X$ is non-zero for some $k>0$. Clearly, homologically nontrivial sets are infinite sets.
\end{enumerate}

\end{prop}

\subsection{Deformed Hamiltonian spectral invariants}
In this section, we follow the works of  Schwarz~\cite{Sc1} and Oh~\cite{Oh3} to define the spectral invariants and review their properties which will be useful in this paper. 

For $\zeta\in   \oplus_{i=0}^{n-1}H_{2i}(M;\Lambda_0)$
and a strongly non-degenerate Hamiltonian $H\in\rH$, as in the previous section we have the PSS isomorphism 
\[\Psi^{\rm PSS}_{\zeta,H}: H_*(M;\Lambda)\longrightarrow HF_\zeta(H).\]
Given $a\in H_*(M;\Lambda)\setminus\{0\}$, we put
\[
\rho_\zeta(a,H)=\inf\big\{\lambda\;|\;\Psi^{\rm PSS}_{\zeta,H}(a)\in \operatorname{im}( i^\lambda)\big\}
\]
where $i^\lambda:HF_\zeta^\lambda(H)\to HF_\zeta(H)$ is the natural map induced by the inclusion of $CF_*^\lambda(H)$ to $CF_*(H)$. Then $-\infty<\rho_\zeta(a,H)<+\infty$, and 
for any two strongly nondegenerate Hamiltonians $H,K\in \rH$,   $\rho_\zeta(a,\cdot)$ satisfies 
$$\int^1_0\min\limits_M(K_t-H_t)dt\leq \rho_\zeta(a,H)-\rho_\zeta(a,K)\leq \int^1_0\max\limits_M(K_t-H_t)dt.$$ 
This has been proved in~\cite{Us}, see also~Oh~\cite{Oh3} for the undeformed case. Recall that the Hofer norm on the space of continuous functions $H:S^1\times M\to\R$ is given by 
\[
\|H\|=\int^1_0\big(\max_M H(t,x)-\min_M H(t,x)\big)dt
\]
So if $H,K$ are both normalized then we get 
\[|\rho_\zeta(a,H)-\rho_\zeta(a,K)|\leq \|H\|\]
Consequently, one can extend $\rho_\zeta(a,\cdot)$ by continuity to the set of continuous functions $H:S^1\times M\to\R$ such that $H$ is normalized. Note that adding a time-dependent smooth function $c:S^1\to\R$ to $H$ does not change the Hamiltonian flow of $H$ but only shifts the value of $\ah$ at each critical point by the constant $\int^1_0c(t)dt$, so we get
$$\rho_\zeta(a,H+c)=\rho_\zeta(a,H)+\int^1_0c(t)dt.$$ for all nonzero classes $a\in H(M,\Lambda)$. Then one can further extend $\rho_\zeta(a,\cdot)$ to a map on $C^0(S^1\times M,\R)$. The numbers $\rho_\zeta(a,H)$ are called \textit{deformed spectral invariants} of an element $H\in C^0(S^1\times M,\R)$ (if $a=0$, we put $\rho_\zeta(0,H)=-\infty$).  

\begin{prop}[{\cite[Proposition~3.13]{Us} or \cite[Theorem~7.8]{FOOO}}]\label{prop:property}
The deformed spectral invariant $$\rho_\zeta:H_*(M;\Lambda)\times C^\infty(S^1\times M,\R)\to [-\infty,\infty)$$ has the following properties:
\begin{itemize}
    \item[{\rm (P1)}] {\rm Normalization:}  $I_\nu(a)+\int^1_0\min H(t,\cdot)dt\leq \rho_\zeta(a,H)\leq I_\nu(a)+\int^1_0\max H(t,\cdot)dt$ for all $H\in\rH$. In particular, $\rho_\zeta(a,0)=I_\nu(a)$.
    \item[{\rm (P2)}] {\rm Spectrality:} If $H$ is strongly nondegenerate, then there is $c\in CF_*(H)$ such that $[c]=\Psi^{\rm PSS}_{\zeta,H}(a)$ and $\rho_\zeta(a,H)=\ell_H(c)$, and hence $\rho_\zeta(a,H)\in\spec(H)$. If $M$ is rational, for any $H\in\rH$ one also has $\rho_\zeta(a,H)\in\spec(H)$.
    \item[{\rm (P3)}] {\rm Homotopy invariance:} $\rho_\zeta(a,H)=\rho_\zeta(a,K)$, when $\varphi_H=\varphi_K$ in the universal covering of the group of  Hamiltonian diffeomorphisms $\widetilde{{\rm Ham}}(M,\omega)$, and $H,K$ are normalized.
    \item[{\rm (P4)}] {\rm Quantum shift:} $\rho_\zeta(\lambda a,H)=\rho_\zeta(a,H)+\nu(\lambda)$ for all $\lambda\in\Lambda$.
    \item[{\rm (P5)}] {\rm Projective invariance:} $\rho_\zeta(w a,H)=\rho_\zeta(a,H)$ for any $0\neq w\in\C$. 
    \item[{\rm (P6)}] {\rm Triangle inequality:} $\rho_\zeta(a*_\zeta b,H*K)\leq \rho_\zeta(a,H)+\rho_\zeta(a,K)$ for any $H,K\in \rH$. 
    \item[{\rm (P7)}] {\rm Valuation inequality:} 
    $\rho_\zeta(a+b,H)\leq\max\{\rho_\zeta(a,H),\rho_\zeta(b,H)\}$. And if $\rho_\zeta(a,H)\neq\rho_\zeta(b,H)$, then this equality holds. 
    \item[{\rm (P8)}] {\rm Duality:} Set $\overline{H}(t,x)=-H(t,\varphi_H^t(x))$. Then
    \[\rho_\zeta(a,\overline{H})=-\inf\big\{\rho_\zeta(b,H)\;|\;b\in H_*(M;\Lambda),\; {\textstyle\prod}(b,a)\neq 0\big\}.\] 



\end{itemize}

\end{prop}
\begin{rmk}
The properties in Proposition~\ref{prop:property} follow by adapting arguments in the undeformed case, see for instance~\cite{Oh3}. Here we only mention that the spectrality property for a strongly nondegenerate $H$ follows from~\cite[Corollary 1.3]{Us1} straightforwardly, and then for arbitrary $H$ on a rational symplectic manifold follows from~\cite[Lemma~7.2]{Oh2}, and that the second statement in the (P7)  follows from Remark~\ref{rmk:nonArchi}. 
\end{rmk}

\begin{rmk}
If $(M,\omega)$ is strongly semipositive, we do not need any Kuranishi structure in the constructions of the deformed spectral invariants $\rho_\zeta$ and just appeal to~\cite[Section~3.2]{Us} without missing any property listed as above. In this case Proposition~\ref{prop:property} is enough in the following content and for our applications in Section~\ref{sect:app}. However, if one would like to obtain Theorems~\ref{thm:mainthm}-\ref{thm:onept} without the strongly semipositive condition constraint, then one of course will need Kuranishi structures or something similar to deal with multiple covers of spheres of negative Chern number, but at least in principle one could use constructions just at the level of Fukaya and Ono~\cite{FO} rather than~\cite{FOOO1}, see~\cite[Section~3]{Us}.



\end{rmk}


\begin{df}\label{df:zetanorm}
Given $\zeta\in   \oplus_{i=0}^{n-1}H_{2i}(M;\Lambda_0)$, for any $H\in\rH$, we define 
\begin{equation}\notag
\gamma_\zeta(H):= \rho_\zeta([M],H)+\rho_\zeta([M],\overline{H})
\end{equation}
and 
\[
    \gamma_\zeta(\varphi):=\inf\{\gamma_\zeta(H)\;|\;\varphi=\varphi_H^1,\;H\in\rH\}. 
\]
\end{df}
\begin{rmk}
According to the (P1), (P3) and (P6) as above, we see that $\gamma_\zeta$ satisfies
\begin{equation}\label{e:hofer}
0\leq \gamma_\zeta(\varphi)\leq \|\varphi\|:=\inf\{\|H\|\;|\;\varphi=\varphi_H^1,\;H\in\rH\}. 
\end{equation}
In fact, $\gamma_\zeta$ gives rise to  a norm on $\ham(M,\omega)$, called a \textit{$\zeta$-spectral norm}. This can  be proven by straightforwardly adapting arguments that are well-known in the $\zeta=0$ case, see~\cite{Oh3}. Since this fact is not explicitly used in the present paper, we leave its proof to the reader. 
\end{rmk}


Spectral invariants are notoriously difficult to compute in general. However, for a $C^2$-small autonomous Hamiltonian $H:M\to\R$, the deformed Hamiltonian spectral invariants $\rho_\zeta$ of $H$ can be computed in terms of the minmax critical sector $c_{LS}$ for $H$.  

\begin{lem}\label{lem:computation}
Let $H:M\to\R$ be a $C^2$-small smooth function (i.e., the $C^2$-norm $\|H\|_{C^2}$ is sufficiently small). Then $\rho_\zeta(a,H)=c_{LS}(a,H)$ for all $a\in H_*(M,\C)\setminus \{0\}$. 
\end{lem}

\begin{proof}
%The key argument given here is essentially due to Fukaya and Ono~\cite{FO}, we include it for complete.  

First we notice that for a closed manifold $M$ with positive dimension, the set of smooth functions on $M$ is dense in the space of Morse functions in  $C^2$-topology. One may perturb $H$ to a $C^2$-small smooth Morse function in $C^2$-norm, and then further to an autonomous Hamiltonian whose critical points miss the images of the maps $f_i:\Delta_i\to M$ as in (\ref{e:delta}), i.e., a strongly nondegenerate autonomous Hamiltonian $H$. Since $c_{LS}(a,H)$ and $\rho_\zeta(a,H)$ are both Lipschitz continuous in $H$, it suffices to prove the lemma for a $C^2$-small Morse and strongly nondegenerate $H$. 

Since $H$ is a $C^2$-small Morse function, the set ${\rm Per}(H)$ indeed consists of critical points of $H$ (cf. \cite[Section~7]{SZ}). Note that for each $q\in\crit(H)$, the set $\pi_2(q)$ consisting of the homotopy classes of discs with boundary mapping to $q$ is isomorphic to $\pi_2(M)$. Given $A\in\pi_2(M)$, let $A_q\in\pi_2(q)$ be the element corresponding to $A$. According to our convention for Conley-Zehnder index of Hamiltonian periodic orbits, we have $\mu(A_q)=n-\ind_H(q)+2\langle c_1(TM), A\rangle$.  
For $q\in\crit(H)$, we denote by $[q,0]$ the class of  the constant periodic orbit $q$ with constant capping. Clearly, 
\begin{equation}\label{e:value}
\ah([q,0])=H(q).
\end{equation}

Given $q\in\crit(H)$, recall that the PSS map $\psi_{\zeta,H}^{\rm PSS}:CM(H;\Lambda)\to CF_*(H)$ defined as in Section~\ref{sec:pss} is 
\begin{equation}\label{e:psiq}
  \psi^{\pss}_{\zeta,H} q=\sum_{k=0}^\infty\frac{1}{k!}\sum_{\substack{p\in{\rm Crit}(H),\\A\in\pi_2(M)}}\sum_{\substack{I\in\{1,\ldots,m\}^k,\\\ind_f(q)-\ind_f(p)+2c_1(A)=\delta(I)}}|\mathsf{s}_{\pss}^{-1}(0)|\exp\big(\int_A \theta\big)a_I[p,A_p].  
\end{equation}
Here $\mathsf{s}_{\pss}$ is the multisection of the Kuranishi structure with corners on the fiber product $$\mathcal{M}^{\pss}_k(p,A,q;\Delta_I)=\overline{\mathcal{M}}^{\pss}_k(p,A)_{ev_{-\infty},ev_1,\ldots,ev_k}\times_{\iota_q,f_{i_1},\dots,f_{i_k}}\big(W^u(q)\times\Delta_{i_i}\times\cdots\times\Delta_{i_k}\big)$$ 
where $\overline{\mathcal{M}}^{\pss}_k(p,A)$ is the compactification of the space of perturbed holomorphic planes with $k$ marked points representing $A$ and asymptotic to $p$. 

Now we may choose a time-independent almost complex structure $J$ compatible with $\omega$ such that the pair $(H,\rho_J)$ is a Morse-Smale pair where $\rho_J(\cdot,\cdot)=\omega(\cdot,J\cdot)$, see Theorem~8.1 in~\cite{SZ}.  Then we choose the two-parameter family $\{J_s\}_{s\in[0,1]}$ of almost complex structures as in Section~\ref{sec:pss} such that $J_s\equiv J$. In this case, we will show that the corresponding PSS map $$\psi_{\zeta,H}^{\rm PSS}:CM(H;\Lambda)\to CF_*(H)$$ sends $q$ to $[q,0]$. 


A typical element of $\overline{\mathcal{M}}^{\pss}_k(p,A)$ consists of a disc component and possibly some other components, each of which is cylindrical solution to the Floer equation for $H$ or a $J$-holomorphic sphere. 

The space $\mathcal{M}^{\pss}_k(p,A,q;\Delta_I)$ has an extra $S^1$-symmetry by the $S^1$ action of disc, cylinder components of the domain $\R\times S^1$, and by rotating the spherical components. Following Fukaya and Ono~\cite[Mainlemma 22.4]{FO}, we see that the fixed locus $\mathcal{M}^{\pss}_k(p,A,q;\Delta_I)^{S^1}$ of this action is isolated, and away from the fixed locus the action is locally free. So, after taking a quotient by this $S^1$ action, one can construct a Kuranishi structure of dimension $-1$ on the quotient of the complement of the fixed locus and choose a multisection on it which is transversal to $0$. Then we lift this multisection to the complement
$\mathcal{M}^{\pss}_k(p,A,q;\Delta_I)\setminus \mathcal{M}^{\pss}_k(p,A,q;\Delta_I)^{S^1}$ such that the quantity $|\mathsf{s}_{\pss}^{-1}(0)|$ is given by contributions only coming from $\mathcal{M}^{\pss}_k(p,A,q;\Delta_I)^{S^1}$. Note that the $S^1$-action on the spherical components is locally free except those corresponding to a topological trivial sphere, and that 
each element in $\mathcal{M}^{\pss}_k(p,A,q;\Delta_I)^{S^1}$ is
independent of the $S^1$-coordinate, and hence,  a solution $\gamma:[0,\infty)\to M$ of \begin{equation}\label{e:grad}
    \dot{\gamma}(s)=-\chi(s)\; {\rm grad}_{\rho_J} H(\gamma(s))\quad \hbox{with}\;\gamma(0)\in W^u(q;H)
\end{equation} (corresponding to the disc component), and possibly some number of negative gradient flowlines of $H$ (corresponding to the cylindrical components), or constant maps $u:S^2\to M$ with image $\gamma(0)$,   where all subject to suitable incidence conditions. This implies that $A=0$ since the nonspherical components are $S^1$-independent, and that there will be no cylindrical components since their images in $M$ are $1$-dimensional objects which do not satisfy nontrivial incidence conditions. So the only contributions to $\psi_{\zeta,H}^{\rm PSS}(q)$ come from the solutions $\gamma$ of (\ref{e:grad}) with $\gamma(\infty)=p\in \crit(H)$ with incidence conditions, corresponding to the points $\gamma(0)\in W^u(q)\cap W^s(p)$ which meet the cycles $\beta_1^I,\dots,\beta_k^I$. Furthermore, we may ask that these later intersections are mutually transverse to each other and to the $W^u(q)$ and $W^s(p)$, then a dimension counting yields
$$
\ind_H(q)-\ind_H(p)=\dim\big(W^u(q)\cap W^s(p)\big)=\sum_{j=1}^k(2n-2d(i_j)).
$$
Consequently, from the fact that the only terms in (\ref{e:psiq}) corresponding to $A=0$ satisfy $$\ind_H(q)-\ind_H(p)=\delta(I)=\sum_{j=1}^k(2n-2d(i_j))-2k,$$ we deduce that the only contributions to  $\psi_{\zeta,H}^{\rm PSS}(q)$ have $k=0$. So $\ind_H(q)-\ind_H(p)=0$, and hence (\ref{e:psiq}) simplifies to
\[
\psi_{\zeta,H}^{\rm PSS}(q)=\sum_{\substack{p\in\crit(H),\\\ind_H(q)=\ind_H(p)}} n(q,p)\cdot [p,0]
\]
where $n(q,p)$ is the number of points in $W^u(q)\cap W^s(p)$. If $p\neq q$, we must have $n(p,q)=0$, otherwise, there is a $\R$-action on $ W^u(q)\cap W^s(p)$  which contradicts to $\dim(W^u(q)\cap W^s(p))=0$. If $p=q$, then we have $n(q,p)=1$ obviously. Therefore, $\psi_{\zeta,H}^{\rm PSS}$ sends each critical point $q$ of $H$ to $[q,0]$. 
This, together with (\ref{e:value}), yields the desired equality. \end{proof}

Our next lemma gives a property of the  spectral invariant $\rho_\zeta$ coming from the non-Archimedean geometry which is very important in the following content. 
\begin{lem}\label{clm:alpha}
    Let $H\in\rH$. 
    If $\alpha=\lambda [M]+\beta$ with $0\neq\lambda\in\Lambda$ and $\beta\in H_{*<2n}(M;\Lambda)$, then
    \begin{equation}\label{e:alphaspectral}
    \rho_\zeta(\alpha,H)\geq \rho_\zeta([M],H)++\nu(\lambda). 
    \end{equation}
\end{lem}
\begin{proof}
For proving (\ref{e:alphaspectral}), we may assume that $H:S^1\times M\to\R$ is strongly nondegenerate because of the continuity property of $\rho_\zeta(a,H)$ with respect to $H$. By Proposition~\ref{prop:property} (P2), there exists a cycle $c\in CF_*(H)$ such that 
\[
    \rho_\zeta([M],H)=\ell_H(c)\quad\hbox{and}\quad \Psi^{\rm PSS}_{\zeta,H}([M])=[c].
    \]
    Similarly, if $\beta\neq 0$, then we have a cycle $b\in CF_*(H)$ satisfying
    \[\rho_\zeta(\beta,H)=\ell_H(b)
    \quad\hbox{and}\quad \Psi^{\rm PSS}_{\zeta,H}(\beta)=[b].
\]
As an orthogonalizable $\Lambda$-space $(CF_*(H),\ell_H)$, the image of the boundary map $\partial_\zeta^{H,J}$, denoted by  $\im (\partial_\zeta^{H,J})$, is still an orthogonalizable non-Archimedean normed vector space over $\Lambda$. Take a non-Archimedean orthogonal complement $V$ of $\im (\partial_\zeta^{H,J})$ in $CF_*(H)$. Consider now the linear map (over $\Lambda$)
\[\partial_\zeta^{H,J}: V\longrightarrow \im (\partial_\zeta^{H,J}).
\]
Applying Lemma~\ref{lem:orthogonal} to the above map, we see that $CF_*(H)$ has a non-Archimedean orthogonal basis $$(x_0,\ldots,x_k,y_1,\ldots,y_l,z_1,\ldots,z_l)$$ satisfying the following:
\begin{itemize}
    \item $x_0=c$;
        \item the classes $[x_0],\dots,[x_k]$ constitute a basis for $HF_\zeta(H)$;
        \item $\partial_\zeta^{H,J}(y_i)=z_i$ for $i=1,\ldots,l$, and $(z_1,\ldots,z_l)$ is an orthogonal basis for $\im (\partial_\zeta^{H,J})$.
\end{itemize}
Now we take any cycle $a\in CF_*(H)$ such that 
\[[a]=\Psi^{\rm PSS}_{\zeta,H}(\alpha)=\lambda[c]+[b],\]
Then $a-\lambda c-b\in \im (\partial_\zeta^{H,J})$. Note that the coefficient of $[x_0]$ in the linear expansion of vector $[b]$ with respect to the basis $[x_0],\dots,[x_k]$ is zero because, otherwise, the preimage $\beta=(\Psi^{\rm PSS}_{\zeta,H})^{-1}[b]$ would contain a multiple of the fundamental class while by our assumption $\beta\in H_{*<2n}(M;\Lambda)$. So, under the above basis of $CF_*(H)$, one may expand $a$ linearly as 
\[
    a=\lambda c+\sum_{i=1}^kf_ix_i+\sum_{j=1}^lg_jz_j
    \]
    where $f_i,g_j\in\Lambda$ for $i\in\{1,\ldots,k\}, j\in\{1,\ldots,l\}$. By the non-Archimedean orthogonality of $(x_0,\ldots,x_k,y_1,\ldots,y_l,z_1,\ldots,z_l)$, we obtain
    \begin{eqnarray}
    \ell_H(a)=\max\limits_{i,j}\big\{\ell_H(\lambda c),\ell_H(f_ix_i),\ell_H(g_jz_j)\big\}
    \geq\ell_H(\lambda c)
    =\rho_\zeta([M],H)+\nu(\lambda) \notag
    \end{eqnarray}
from which we conclude that $\rho_\zeta(\alpha,H)\geq \rho_\zeta(\lambda [M],H)$.\end{proof}

\begin{prop}\label{prop:duality}
    $\rho_\zeta([pt],\overline{H})=-\rho_\zeta([M],H)$ for any $H\in\rH$. 
\end{prop}
\begin{proof}
We may assume that $H\in\rH$ is strongly nondegenerate due to the continuity property of $\rho_\zeta(a,H)$ with respect to $H$. First, Proposition~\ref{prop:property} (P8) yields
\begin{equation}\notag
\rho_\zeta([pt],\overline{H})=-\inf\big\{\rho_\zeta(\alpha,H)\;\big|\;{\alpha\in H_*(M;\Lambda)\setminus\{0\},\;\textstyle\prod}(\alpha,[pt])\neq 0\big\}. 
\end{equation} 
Next, our goal is to prove that for $\alpha\in H_*(M;\Lambda)$, if ${\textstyle\prod}(\alpha,[pt])\neq 0$, then 
\begin{equation}\label{e:alpha}
    \rho_\zeta(\alpha,H)\geq \rho_\zeta([M],H). 
\end{equation}
Indeed, from the definition of the nondegenerate pair $\textstyle\prod$ (cf. the formular~(\ref{e:pair})), we see that such $\alpha$ must have the following form
    $$\alpha=(w_0+w_1\lambda)[M]+\beta$$ 
where $w_0,w_1\in \C$ with $w_0\neq 0$, $\lambda\in\Lambda$ with $\nu(\lambda)\neq 0$, and $\beta\in H_{*<2n}(M;\Lambda)$. Note that $\rho_\zeta(\lambda[M],H)=\rho_\zeta([M],H)+\nu(\lambda)\neq\rho_\zeta([M],H)$. Hence, by~Proposition~\ref{prop:property} (P5) and (P7), arguing in two cases: (1) $w_1=0$; (2)  $w_1\neq 0$, we obtain
\begin{equation}\label{e:[M]}
\rho_\zeta((w_0+w_1\lambda)[M],H)=\max\big\{\rho_\zeta(w_0[M],H),\rho_\zeta(w_1\lambda[M],H)\big\}\geq \rho_\zeta([M],H).  
\end{equation}
According to Lemma~\ref{clm:alpha}, we see that
\[
\rho_\zeta(\alpha,H)\geq \rho_\zeta((w_0+w_1\lambda)[M],H). 
\]
Combining this with (\ref{e:[M]}), we arrive at~(\ref{e:alpha}). Since one can take $\alpha$ to be $[M]$, we conclude that $\rho_\zeta([pt],\overline{H})=-\rho_\zeta([M],H)$ for strongly nondegenerate $H$, and hence for all $H\in\rH$. \end{proof}


\subsection{Hamiltonian Ljusternik--Schnirelman inequality}


As we mentioned before, as a vector space over $\C$ the big quantum homology $H_*(M;\Lambda)$ is isomorphic to $H_*(M;\C)\otimes_\C\Lambda$. We set 
\[
\widehat{H}_*(M;\Lambda)=H_{*<2n}(M;\C)\otimes_\C\Lambda. 
\]



\begin{thm}\label{thm:LjS}
Let $(M^{2n},\omega)$ be a closed rational symplectic manifold. Let $H\in\rH$, and let $\alpha,\beta\in H_*(M;\Lambda)$ with $\alpha\neq 0$. Then we have
\begin{equation*}
\rho_\zeta(\alpha *_\zeta \beta, H)\leq \rho_\zeta (\alpha,H)+I_\nu(\beta). 
\end{equation*}
Furthermore, if $\beta\in\widehat{H}_*(M,\Lambda)$ is non-zero, then either
\[
\rho_\zeta(\alpha *_\zeta \beta, H)< \rho_\zeta (\alpha,H)+I_\nu(\beta)
\]
or the set ${\rm Fix}(\varphi_H^1)$ is homologically non-trivial in $M$, hence it is an infinite set. 
\end{thm}

Next we postpone the proof of Theorem~\ref{thm:LjS} to the end of this section, and employ this theorem to give the following corollary which will be used in Section~\ref{sec:mainpf}.


\begin{cor}\label{cor:specineq}
Let $(M^{2n},\omega)$ be a closed rational symplectic manifold. Suppose that there exist $k$ homology classes $u_i\in \widehat{H}_{*}(M;\Lambda)$, $i=1,\ldots,k$ and $\beta\in H_*(M;\Lambda)$ such that $\beta*_\zeta u_1*_\zeta\cdots*_\zeta u_k\neq 0$ and $I_\nu(u_i)\leq 0$. Let $H\in\rH$ such that the ${\rm Fix}(\varphi_H^1)$ is a finite set. Then the action functional $\ah$ has $k+1$ critical points $(x_0,\overline{x}_0),\ldots,(x_{k},\overline{x}_{k})$ such that 
\[
    \rho_\zeta(\alpha_k,H)=\ah(x_{k},\overline{x}_{k})<\ldots<\rho_\zeta(\alpha_0,H)=\ah(x_{0},\overline{x}_{0})
\]
where $\alpha_0=\beta$ and $\alpha_i=\alpha_{i-1}*_\zeta u_i$ for $i\in \{1,\ldots,k\}$. 
\end{cor}
%Moreover, the mean index of each critical point $(x_j,\overline{x}_j)$ satisfies \[|\Delta_H(x_j,\overline{x}_j)-\deg(u_k)|\leq n.\]


\begin{proof}
    The condition that $\beta*_\zeta u_1*_\zeta\cdots*_\zeta u_k\neq 0$ implies that each $\alpha_i$ is nonzero.  
    Since ${\rm Fix}(\varphi_H^1)$ is finite and $I_\nu(u_i)\leq 0$ for any $i\in \{1,\ldots,k\}$, by Theorem~\ref{thm:LjS} we obtain immediately 
    \[
        \rho_\zeta(\alpha_i,H)=\rho_\zeta(\alpha_{i-1}*_\zeta u_i,H)<\rho_\zeta(\alpha_{i-1},H)+I_\nu(u_i)\leq \rho_\zeta(\alpha_{i-1},H).         
    \]
So we get
\[
\rho_\zeta(\alpha_k,H)<\ldots< \rho_\zeta(\alpha_0,H). 
\]
Combining this with Proposition~\ref{prop:property} (P2) yields $k+1$ critical points $(x_0,\overline{x}_0),\ldots,(x_{k},\overline{x}_{k})$ of $\ah$ as required. \end{proof}

\noindent\textbf{Proof of Theorem~\ref{thm:LjS}.} 
The argument we will make to show the theorem is an adaption of Howard~\cite{How}, see also~\cite{Sc1,GG,BHS,Go}. The idea of the proof is to use all properties of the spectral invariant $\rho_\zeta$ listed as above. 
First, by Proposition~\ref{prop:property}~(P6),  
\[
\rho_\zeta(\alpha *_\zeta \beta,H*0)\leq \rho_\zeta(\alpha,H)+\rho_\zeta(\beta,0).
\]
This, together with by Proposition~\ref{prop:property}~ (P1) and (P3), implies
\[
\rho_\zeta(\alpha *_\zeta \beta,H*0)\leq \rho_\zeta(\alpha,H)+I_\nu (\beta)
\]
where we have used the fact that $H*0$ and $H$ have the same mean value, that is,  $\int^1_0\int (H*0)_t\omega^n dt=\int^1_0\int H_t\omega^n dt$ and $\varphi_{H*0}^1=\varphi_H^1$ in $\widetilde{{\rm Ham}}(M,\omega)$. 

Next, we prove the second statement. It suffices to show that if $\alpha\in H_*(M;\Lambda)$, $\beta\in \hat{H}(M;\Lambda)$ are two nonzero classes with the property
\begin{equation}\label{e:condition}
\rho_\zeta(\alpha *_\zeta \beta, H)=\rho_\zeta(\alpha,H)+I_\nu(\beta),
\end{equation}
then ${\rm Fix}(\varphi_H^1)$ is homologically  nontrivial in $M$. For this end, we pick any open neighborhood $V$ of ${\rm Fix}(\varphi_H^1)$. We may assume that $M\setminus \overline{V}$ is nonempty since  nothing needs to be proved if ${\rm Fix}(\varphi_H^1)=M$. We shall prove that $\overline{V}$ is homologically nontrivial.  

Pick a $C^2$-small function $f:M\to\R$ such that $f|_{\overline{V}}\equiv 0$ and $f|_{M\setminus \overline{V}}<0$.  We shall prove the following

\begin{clm}\label{clm:spec}
For sufficiently small $\varepsilon>0$, we have 
\[
\rho_\zeta(\alpha *_\zeta \beta, H*\varepsilon f)=\rho_\zeta(\alpha *_\zeta \beta, H). 
\]
\end{clm}
\noindent\textbf{Proof of Claim~\ref{clm:spec}.} Consider now a family of spectral invariants $\rho_\zeta(\alpha *_\zeta \beta, H*s\varepsilon f)$ for $s\in[0,1]$. Here to guarantee that the concatenated Hamiltonians $H*s\varepsilon f$ make sense, one can assume that for some small $\epsilon>0$, $H=f\equiv0$ for $|t|<\epsilon$ by the reparameterization as before (cf. Section~\ref{subsec:concatenation}). Since $\rho_\zeta(\alpha *_\zeta \beta, H)$ is continuous in $H$ in $C^0$-topology and the action spectra $\spec(H*s\varepsilon f)$ have measure zero for all $s$, we only need to prove that for $\varepsilon>0$ small enough, the sets $\spec(H*s\varepsilon f)$ are the same for all $s\in[0,1]$. Note that
\[
{\rm Fix}(\varphi^1_{H*\varepsilon f})={\rm Fix}(\varphi_H^1)
\]
provided that $\varepsilon$ is sufficiently small. In fact, we have $\varphi^1_{H*\varepsilon f}=\varphi^1_{H}\circ \varphi^1_{\varepsilon f}$ and $\varphi^t_{\varepsilon f}|_V\equiv Id$. Clearly,  
${\rm Fix}(\varphi^1_{H*\varepsilon f})\supseteq {\rm Fix}(\varphi_H^1)$. Suppose now that $p\in M$ is a fixed point of $\varphi^1_{H*\varepsilon f}$, and hence $\varphi^1_{\varepsilon f}(p)=\varphi^{-1}_{H}(p)$. Since the set $M\setminus V$ is compact and $q\neq \varphi_H^{-1}(q)$ for any $q\in M\setminus V$ (remind that $V$ contains ${\rm Fix}(\varphi_H^1)$), one may choose $\varepsilon>0$ small enough such that $\varphi_{\varepsilon f}^1(q)=\varphi_f^\varepsilon(q)\neq \varphi_H^{-1}(q)$ for any $q\in M\setminus V$.  Therefore, $p\in V$, and hence $p=\varphi_H^{-1}(p)$. So ${\rm Fix}(\varphi^1_{H*\varepsilon f})\subseteq {\rm Fix}(\varphi_H^1)$. 

We now prove that $\spec(H*\varepsilon f)=\spec(H)$ for any given small $\varepsilon>0$. For each $x\in {\rm Fix}(\varphi_H^1)$, we let $x(t)=\varphi_H^t(x), t\in[0,1]$ and $\overline{x}:D^2\to M$ be a cotinuous disc such that $\overline{x}(e^{2\pi it})=x(t)$. It is easy to see that
\begin{equation}\notag
\varphi_{H*\varepsilon f}^t(x)=
\begin{cases}
x&0\leq t\leq 1/2,\\
\varphi_H^{2t-1}(x)&1/2\leq t\leq 1.\\
\end{cases}
\end{equation}

Corresponding to each critical point $(x,\overline{x})$ of $\ah$, we denote by $x'(t)=\varphi_{H*\varepsilon f}^t(x)$ and let $\overline{x}':D^2\to M$ be a disc given by
\begin{equation}\notag
\overline{x}'(re^{2\pi it})=
\begin{cases}
\overline{x}(r)&(r,t)\in [0,1]\times [0,1/2],\\
\overline{x}(re^{2\pi it})&(r,t)\in [0,1]\times [1/2,1].\\
\end{cases}
\end{equation}
Clearly, on the boundary of this disc, $\overline{x}'$ restricts as the periodic orbit $x'$. So we get a bijection 
$$\mathcal{J}:\crit(\ah)\longrightarrow\crit(\mathcal{A}_{H*\varepsilon f}),\quad (x,\overline{x})\mapsto (x',\overline{x}').$$
A straightforward computation yields $\mathcal{A}_{H*\varepsilon f}(x,\overline{x})=\ah(\mathcal{J}(x',\overline{x}'))$. This will result in $\spec(H*\varepsilon f)=\spec(H)$. Similarly, one can show that 
$\spec(H*s\varepsilon f)=\spec(H)$ for all $s$. This completes the proof of the claim.\qed

Now we are in a position to finish the proof. By our assumption, for $\beta\in\widehat{H}(M;\Lambda)$, 
we may write $\beta=\sum_i\beta_i\otimes k_i$ with $0\neq\beta_i\in H_{*<2n}(M;\C)$ and $k_i\in\Lambda$. By Proposition~\ref{prop:property} (P1), (P4) and (P7),  for given sufficiently small $\varepsilon>0$, the following inequalities hold:
\begin{eqnarray}\label{e:f}
\rho_\zeta (\beta,\varepsilon f)&\leq& \max_i\big\{\rho_\zeta(\beta_i\otimes k_i,\varepsilon f)\big\}\notag\\
&=&\max_i\big\{\rho_\zeta(\beta_i,\varepsilon f)+\nu(k_i)\big\}\notag\\
&\leq&\max_i\big\{\rho_\zeta(\beta_i,\varepsilon f)\big\}+I_\nu(\beta). 
\end{eqnarray}
Then it follows from Proposition~\ref{prop:property} (P6) and Claim~\ref{clm:spec} yields 
\begin{eqnarray}\label{e:H}
\rho_\zeta (\alpha *_\zeta\beta,H)
&=& \rho_\zeta(\alpha *_\zeta\beta,H*\varepsilon f)\notag\\
&\leq&\rho_\zeta(\alpha,H)+\rho_\zeta(\beta,\varepsilon f)\notag\\
&\leq&\rho_\zeta(\alpha,H)+\max_i\big\{\rho_\zeta(\beta_i,\varepsilon f)\big\}+I_\nu(\beta), 
\end{eqnarray}
where in the last inequality we have used (\ref{e:f}). On the one hand, from (\ref{e:H}) we deduce that there exists $i_0\in\N$ such that 
\[
\rho_\zeta(\beta_{i_0},\varepsilon f)\geq \rho_\zeta (\alpha *_\zeta\beta,H)-\rho_\zeta(\alpha,H)-I_\nu(\beta). 
\]
Then, by (\ref{e:condition}) and Lemma~\ref{lem:computation}, we get $$c_{LS}(\beta_{i_0},\varepsilon f)=\rho_\zeta(\beta_{i_0},\varepsilon f)\geq 0.$$ 
On the other hand, it follows from Proposition~\ref{pp:minmax}.3 that
\[
c_{LS}(\beta_{i_0},\varepsilon f)=c_{LS}([M]\cap\beta_{i_0},\varepsilon f)\leq c_{LS}([M],\varepsilon f)=\max \varepsilon f=0.
\]
Consequently, we obtain
\[
c_{LS}([M]\cap\beta_{i_0},\varepsilon f)=c_{LS}([M],\varepsilon f)=0
\]
for some nonzero class $\beta_{i_0}\in H_{*<2n}(M;\Lambda)$. Then by Proposition~\ref{pp:minmax}.4, the zero level set $\overline{V}$ of $f$ is homologically nontrivial. This completes the proof of the second statement. \qed


\section{Nonvanishing Gromov-Witten invariants}\label{sec:gw}

We begin with the following lemma which plays a key role in reproving a remarkable result by Lu~\cite[Corollary~1.19]{Lu1}, namely, bounding Hofer-Zehnder capacity from above in terms of Gromov-Witten invariants. 

\begin{lem}[{\cite[Lemma~4.2]{Us}}]\label{lem:bound}
Let $(M^{2n},\omega)$ be a closed symplectic manifold which admits a nonzero Gromov-Witten invariant of the form:
\[
{\rm GW}_{0,k+3,A}\big([pt],a_0,[pt],a_1,\ldots,a_k\big)
\]
where $A\in H_2(M;\mathbb{Z})/{\rm torsion}$ and $a_0,\ldots,a_k$ are rational homology classes of even degree. Then, there is an open dense set of possible choices of the deformation parameter $\zeta\in\oplus_{i=0}^{n-1}H_{2i}(M;\C)$ and a homology class $ a_0'\in H_{<2n}(M;\Q)$  such that 
\[
[pt]*_\zeta a_0'= \lambda[M]+\beta\quad \hbox{and}\quad \nu(\lambda)\geq-\langle [\omega],A\rangle
\]
where $\lambda\in\Lambda$ and $\beta\in H_{*<2n}(M;\Lambda_0)$. 
\end{lem}


\begin{cor}\label{cor:specbound}
Under the same conditions in~Lemma~\ref{lem:bound}, for any $H\in\rH$, we have
\begin{equation}\label{e:specnorm}
\rho_\zeta([M],H)-\rho_\zeta([pt],H)
\leq \langle [\omega],A\rangle.
\end{equation}
Moreover, the strict inequality holds if the number of elements in $\#{\rm Fix}(\varphi_H^1)$ is finite. 
\end{cor}

\begin{rmk}\label{rmk:zbound}
Combining Theorems~\ref{prop:duality} and Corollary~\ref{cor:specbound}, one finds that under the same conditions in~Lemma~\ref{lem:bound}, it holds that
\[\gamma_\zeta(\varphi)<\langle [\omega],A\rangle\]
for any $\varphi\in\ham(M,\omega)$ with finite $\#{\rm Fix}(\varphi)$.
\end{rmk}


\noindent\textbf{Proof of Corollary~\ref{cor:specbound}.} 
According to Lemma~\ref{lem:bound}, one has $[pt]*_\zeta a_0'= \lambda[M]+\beta$ and $\nu(\lambda)\geq-\langle [\omega],A\rangle$ for some $\zeta\in\oplus_{i=0}^{n-1}H_{2i}(M;\C)$, $ a_0'\in H_{<2n}(M;\Q)$, $\lambda\in\Lambda$ and $\beta\in H_{*<2n}(M;\Lambda)$. We put $\alpha=[pt]*_\zeta a_0'$. It follows from Theorem~\ref{thm:LjS} that if the number of ${\rm Fix}(\varphi_H^1)$ is finite, then 
\begin{equation}\label{e:pt}
    \rho_\zeta(\alpha,H)<\rho_\zeta([pt],H)+I_\nu(a_0')=\rho_\zeta([pt],H). 
\end{equation}
Then, Lemma~\ref{clm:alpha}, together with (\ref{e:pt}), would give
\[\rho_\zeta([M],H)-\langle [\omega],A\rangle\leq \rho_\zeta([M],H)
+\nu(\lambda)\leq\rho_\zeta(\alpha,H)< \rho_\zeta([pt],H), 
\] 
from which we obtain the strict inequality as required.  Hence, for any $H\in\rH$, (\ref{e:specnorm}) follows from this inequality for strongly nondegenerate $H$ and the continuity property of $\rho_\zeta$.
\qed

\begin{lem}\label{lem:mixnon0}
Let $(M^{2n},\omega)$ be a closed symplectic manifold which admits a nonzero mixed Gromov-Witten invariant of the form:
\[
{\rm GW}_{0,l+k+1,A}^{\{1,\ldots,l+1\}}(a,\ldots,a,b_0,\ldots,b_k)    
\]
where $A\in H_2(M;\mathbb{Z})/{\rm torsion}$, the class $a\in H_{*<2n}(M;\Q)$ occurs $l$ times with $l>2n$, and $b_0,\ldots,b_k$ ($0\leq k\in\Z$) are  rational homology classes of even degree and $b_0\in  H_{*<2n}(M;\Q)$. Then there is an open set of possible choice of deformation parameter $\zeta\in\oplus_{i=0}^{n-1}H_{2i}(M;\C)$ such that   
$ (\underbrace{a *_\zeta,\ldots, *_\zeta a}_l)_{\langle[\omega],A\rangle}\neq 0$, and in particular the $l$-fold product of $a$ w.r.t. $*_\zeta$ is nonzero.

\end{lem}

\begin{proof}
The argument what we will do is essentially due to \cite[Lemma~4.2]{Us} (see also~\cite[Lemma~7.1]{Lu1}), and we include it for completeness. Note first that the class $A$ appearing in the mixed Gromov-Witten invariant cannot be zero. Indeed, the fundamental class axiom of Gromov-Witten invariants (cf. \cite[Proposition~7.5.7]{MS}) implies that none of the classes $b_1,\ldots, b_k$ can be $\lambda [M]$ for some $\lambda\in \Q\setminus\{0\}$. Assume now that $A=0$ in $H_2(M;\mathbb{Z})/{\rm torsion}$. Using the dimension formula~(\ref{e:mixdim}), one finds that
\[
 l(2n-\deg(a))+2n-\deg(b_0)+\sum_{j=1}^k(2n-2-\deg(b_j))=2n
\]
contradicting to our assumption that $l>2n$ and $2n-\deg(a)\geq 1$. So $A\neq 0$ in $H_2(M;\mathbb{Z})/{\rm torsion}$.  By the divisor axiom of the mixed Gromov-Witten invariants, one may assume that $b_1,\ldots, b_k\in \oplus_{k=0}^{n-2}H_{2i}(M;\Q)$. 
We now take a homogeneous basis $\xi_1,\ldots,\xi_N$ for the $\Z$-module $\oplus_{i=0}^{n-1} H_{2i}(M;\mathbb{Z})/{\rm torsion}$ such that $\xi_1,\ldots,\xi_s$ is a basis for $H_{2n-2}(M;\mathbb{Z})/{\rm torsion}$ for some $s<N$. Then by the multilinearity and symmetry properties of the Gromov-Witten invariants, we may further assume that our nonzero Gromov-Witten invariant is of the shape
\begin{equation}\label{e:ngw}
{\rm GW}_{0,l+1+\sum_j\alpha_j,A}^{\{1,\ldots,l+1\}}(\underbrace{a,\ldots,a}_l,b_0',\underbrace{\xi_{s+1},\ldots\xi_{s+1}}_{\alpha_{s+1}},\ldots,\underbrace{\xi_{N},\ldots,\xi_{N}}_{\alpha_{N}})    
\end{equation}
for some homogeneous class $b_0'\in \oplus_{i=1}^{n-1}H_{2i}(M;\Q)$ and $\alpha=(\alpha_{s+1},\ldots,\alpha_N)\in\N^{N-s}$ with $\sum_{j=s+1}^N\alpha_j\leq k$. 

For $\vec{x}=(x_1,\ldots,x_s)\in\C^s$ and $\vec{y}=(y_{s+1},\ldots,y_N)\in\C^{N-s}$, we put
\[
\zeta(x,y)=\sum_{i=1}^sx_i\xi_i+\sum_{j=s+1}^Ny_j\xi_j.    
\]
Let us consider the class $ \underbrace{a *_\zeta,\ldots, *_\zeta a}_l$ as a function of $(\vec{x},\vec{y})$. Take a homogeneous basis  $\{c_j\}_{j=1}^K$ for $H_*(M;\Q)$ with dual basis $\{c^j\}_{j=1}^K$ with respect to the Poinc\'{a}re homology intersection pairing $\circ$ such that $c_1=b_0'$. According to the symmetry properties of the Gromov-Witten invariants, after expanding out the formula for $a^{*_\zeta l}$, we see that the coefficient on the class $c^1$ is an expression of the form 
\[
\sum_{g\in\Gamma_\omega}\sum_{\beta=(\beta_{s+1},\ldots,\beta_N)}f_{g,\beta}(\vec{x})y_{s+1}^{\beta_{s+1}}\cdots y_N^{\beta_N}T^g    
\]
where $f_{g,\beta}(\vec{x})$ is a function of $\vec{x}$ which is identically zero for all but finitely many $\beta$ (by the dimension formula~(\ref{e:mixdim})). In particular, for the period $g=\langle [\omega],A\rangle$ and the value $\beta=\alpha$, we obtain
\begin{eqnarray}
\bigg(&\prod\limits_{i=s+1}^N&\big(\alpha_i !\big)\bigg)f_{\langle [\omega],A\rangle,\alpha}(\vec{x})\notag\\&=& \sum_{\stackrel{B\in H_2(M;\mathbb{Z})/{\rm torsion},}{\langle [\omega],B\rangle=\langle [\omega],A\rangle}}\bigg({\rm GW}_{0,l+1+\sum\alpha_j,B}^{\{1,\ldots,l+1\}}(\underbrace{a,\ldots,a}_l,b_0',\underbrace{\xi_{s+1},\ldots\xi_{s+1}}_{\alpha_{s+1}},\ldots,\underbrace{\xi_{N},\ldots,\xi_{N}}_{\alpha_{N}}) \notag\\
&&\hspace{10cm}\times \bigg(\prod_{i=1}^s(e^{x_i})^{\xi_i\cap B}\bigg)
\bigg).
\notag
\end{eqnarray}
We notice that the coefficient on $\prod_{i=1}^s(e^{x_i})^{\xi_i\cap A}$ in the above sum is nonzero because of our assumed nonzero Gromov-Witten~(\ref{e:ngw}).   Now $H_{2n-2}(M;\mathbb{Z})/{\rm torsion}$ has $\{\xi_i\}_{i=1}^s$ as a basis, the map $B\mapsto (\xi_1\circ B,\ldots,\xi_s\circ B)$ is injective. Consequently, the coefficient on $T^{\langle [\omega],A\rangle}c^1$ in the expansion of $a^{*_\zeta l}$ is a polynomial in $e^{x_i}$ and $y_j$ which carries a nonzero coefficient multiplying
\[
\bigg(\prod_{i=1}^s(e^{x_i})^{\xi_i\cap A}\bigg)\prod_{j=s+1}^Ny_j^{\alpha_j}. 
\]
Then it follows from the fact that this polynomial does not vanish identically that there is an open dense set of choices of $(\vec{x},\vec{y})$ at which the coefficient on $T^{\langle [\omega],A\rangle}c^1$ is not zero. This proves that $(\underbrace{a *_{\zeta(\vec{x},\vec{y})},\ldots, *_{\zeta(\vec{x},\vec{y})}a}_l)_{\langle [\omega],A\rangle}\neq 0$ for such  choices of $(\vec{x},\vec{y})$.  
\end{proof}

Before finishing this section, we notice that the argument what we have already done in the proof of Lemma~\ref{lem:mixnon0} can be used to obtain the following 

\begin{lem}\label{lem:kfoldprod}
    Let $(M^{2n},\omega)$ be a closed symplectic manifold which admits a nonzero mixed Gromov-Witten invariant of the form:
    \[
    {\rm GW}_{0,l+k+1,A}^{\{1,\ldots,l+1\}}(a_1,\ldots,a_l,[pt],b_1,\ldots,b_k)    
    \]
    where $A\in H_2(M;\mathbb{Z})/{\rm torsion}$, $a_1,\ldots, a_l\in H_{*<2n}(M;\Q)$ with $2\leq l\in\N$, and the classes $b_1,\ldots,b_k$ are rational homology classes of even degree. Then there is an open set of possible choice of deformation parameter $\zeta\in\oplus_{i=0}^{n-1}H_{2i}(M;\C)$ such that the $l$-fold product $a_1 *_\zeta,\ldots, *_\zeta a_l = \lambda[M]+\beta$ with $\beta\in H_{*<2n}(M;\Lambda_0)$ satisfies $\nu(\lambda)\geq -\langle [\omega],A\rangle$. 
\end{lem}
\noindent\textbf{Sketch of the proof of Lemma~\ref{lem:kfoldprod}.} We first need to show that the class $A$ appearing in our nonzero 
Gromov-Witten invariant is nonzero. 
According to the fundamental class axiom of mixed Gromov-Witten invariants (see~\cite[Proposition~7.5.7]{MS}), none of the classes $b_1,\ldots, b_k$ can be a multiple of the fundamental class.  Then the dimension formula~(\ref{e:mixdim}) yields
\[
 \sum_{i=1}^l(2n-\deg(a_i))+2n+\sum_{j=1}^k(2n-2-\deg(b_j))=2n
\]
contradicting to our assumption that $2n-\deg(a_i)\geq 1$ for all $i$. The remaining argument of the proof is the same as that in Lemma~\ref{lem:mixnon0}, we omit it. \qed



\section{Proof of Theorems~\ref{thm:mainthm}-\ref{thm:onept}}\label{sec:mainpf}
\noindent\textbf{Proof of Theorem~\ref{thm:mainthm}.}  Given $\varphi\in\ham(M,\omega)$, take $H\in\rH$ such that $\varphi=\varphi^1_H$. Without loss of generality, we may assume that the number of elements in ${\rm Fix}(\varphi_H^1)$ is finite, otherwise, nothing needs to be proved.
 Assume that there are $A\in H_2(M;\mathbb{Z})/\hbox{torsion}$ and rational homology classes $a_0,\ldots,a_k$ of even degree such that
\begin{equation}\label{e:gw0}
{\rm GW}_{0,k+3,A}\big([pt],a_0,[pt],a_1\ldots,a_k\big)\neq 0.
\end{equation}

Our proof is divided to two steps:

\noindent\textbf{Step 1.} By the definition of cuplength (cf. Section~\ref{sec:1}) and the Poincar\'{e} duality, there exist $u_i\in H_{<2n}(M,\C)$, $i=1\ldots,k$ such that $u_1\cap\cdots\cap u_k=[pt]$ and $\cl(M)=k+1$.  Take classes $\alpha_0,\dots,\alpha_k$ in $H_*(M;\Lambda)$ given by
\[
\alpha_0=[M]\quad\hbox{and}\quad \alpha_{i}=\alpha_{i-1} *_\zeta u_{i},\;i=1\ldots,k.
\]
We shall prove the strict inequality 
\begin{equation}\label{e:gamma}
    \rho_\zeta(\alpha_0,H)-\rho_\zeta(\alpha_k,H) < \langle [\omega], A \rangle. 
\end{equation}
Note that the big quantum product is a quantum deformation of the homological intersection product in $H_*(M;\C)$. In particular, we have
\[
\alpha_k=[pt]+\hbox{higher-order terms coming from deformation by $J$-holomorphic spheres}
\] 
which implies that each $\alpha_i$ is nonzero, and that ${\textstyle\prod}(\alpha_k,[M])\neq 0$. Thus, it follows from Propositions~\ref{prop:property} (P8) and~\ref{prop:duality} that
\begin{equation}\label{e:alpha_k}
\rho_\zeta(\alpha_k,H)\geq -\rho_\zeta([M],\overline{H})=\rho_\zeta([pt],H).    
\end{equation}
Since $\gw_{0,k+3,A}\big([pt],a_0,[pt],a_1\ldots,a_k\big)\neq 0$ and $\sharp{\rm Fix}(\varphi_H^1)$ is finite, by Corollary~\ref{cor:specbound}, we obtain
\[
\rho_\zeta([M],H)-\rho_\zeta([pt],H)< \langle [\omega], A \rangle.
\]
Combining this with (\ref{e:alpha_k}), we get  (\ref{e:gamma}) as required. 


\noindent\textbf{Step 2.} 
The next goal is to prove that 
\begin{equation}\label{e:fixpts}
\#{\rm Fix}(\varphi)\geq \bigg\lceil \frac{p\cdot {\rm cuplength}(M;\C)}{\langle [\omega], A \rangle} \bigg\rceil.
\end{equation}
According to Corollary~\ref{cor:specineq}, there exist $k+1$ elements $\widetilde{x}_i=(x_i,\overline{x}_i)\in\crit(\ah)$  such that
\begin{equation}\label{e:critvalue}
\rho_\zeta(\alpha_k,H)=\ah(\widetilde{x}_k)<\ldots<\rho_\zeta(\alpha_0,H)=\ah(\widetilde{x}_0).
\end{equation}
Set
\[
\mathcal{E}=\big\{\ah(\widetilde{x}_i)|i=0,\ldots,k\big\},     
\]
and define an equivalent relation on $\mathcal{E}$ as follows: for $a,b\in\mathcal{E}$,  $a\sim b$ if and only if $a-b$ is a symplectic period, i.e., $a-b\in\Gamma_\omega$. Denote by $\widehat{\mathcal{E}}$ the set of such equivalence classes. Then we see that the number $\#\widehat{\mathcal{E}}$ bounds from below the number of Hamiltonian periodic orbits $x_i$ (corresponding to the elements in ${\rm Fix}(\varphi_H^1)$). 

We now estimate $\#\widehat{\mathcal{E}}$. 
Let $l=\langle [\omega], A \rangle/p$ (recall that $p\in\Gamma_\omega$ is the positive generator of $\Gamma_\omega$). According to (\ref{e:gamma}) and (\ref{e:critvalue}), each equivalence class contains at most $l$ elements in $\mathcal{E}$. So we obtain the inequality (\ref{e:fixpts}) as required. 

Finally, since (\ref{e:fixpts}) holds for every nonzero Gromov-Witten invariant of the form (\ref{e:gw0}), we obtain the desired inequality. This completes the proof.\qed



\vspace{1cm}
\noindent\textbf{Proof of Theorem~\ref{thm:Arnold}.}  Take $H\in\rH$ such that $\varphi=\varphi^1_H$. Since $\gamma_\zeta(\varphi_H^1)<p$, the theorem follows from~(\ref{e:alpha_k}) and (\ref{e:critvalue}). The theorem is proved. 
\qed









\vspace{1cm}
\noindent\textbf{Proof of Theorem~\ref{thm:bcl}.}  Assume that $\bcl(g)>0$ for some $g\in\Gamma_\omega$ and $\zeta\in H_*(M,\Lambda_0)$. Set $\bcl(g)=k+1$ and $\varphi=\varphi_H^1$ for some $H\in\rH$. Then there exist homology classes $a_1,\ldots,a_k\in H_{<2n}(M;\C)$ such that 
$(\alpha_1*_\zeta\cdots *_\zeta\alpha_k)_{g}\neq 0$
with $g=\langle [\omega],A\rangle$ for some $A\in H_*(M;\Z)/{\rm torsion}$. 
Hence, 
\[
\alpha_1*_\zeta\cdots *_\zeta\alpha_k=\sum_{h\in\Gamma_\omega} (\alpha_1*_\zeta\cdots *_\zeta\alpha_k)_h T^h\neq 0.
\]
Set $\beta=\alpha_1*_\zeta\cdots *_\zeta\alpha_k$. Then $I_\nu(\beta)\geq -g$.  By Proposition~\ref{prop:property} (P1), we obtain that 
\begin{equation}\label{e:P1}
I_\nu(\beta)+\int^1_0\min H_t dt\leq \rho_\zeta(\beta,H)\quad\hbox{and}\quad \rho_\zeta([M],H)\leq \int^1_0\max H_t dt. 
\end{equation}
According to Corollary~\ref{cor:specineq}, there exist $k+1$ critical points $(x_0,\overline{x}_0),\ldots,(x_{k},\overline{x}_{k})$ of $\ah$ such that 
\[
    \rho_\zeta(\beta,H)=\ah(x_{k},\overline{x}_{k})<\ldots<\rho_\zeta([M],H)=\ah(x_{0},\overline{x}_{0}).
\]
This, together with~(\ref{e:P1}), gives 
\begin{equation}\label{e:actionbd}
-g+\int^1_0\min H_t dt\leq \ah(x_{k},\overline{x}_{k})<\ldots <  \ah(x_{0},\overline{x}_{0})\leq \int^1_0\max H_t dt. 
\end{equation}
Similar to the proof of Theorem~\ref{sec:mainpf} in Step 2, we let $\mathcal{E}=\{\ah(x_{i},\overline{x}_{i})\;|\;i=0,\ldots,k\}$ and consider the set $\widehat{\mathcal{E}}$ of equivalence classes as before. It follows from (\ref{e:actionbd}) that each equivalence class in $\widehat{\mathcal{E}}$ contains at most $$\bigg\lfloor\frac{\|H\|+g}{p}\bigg\rfloor+1$$
elements in $\mathcal{E}$. So we get 
\[
    \#{\rm Fix}(\varphi_H^1)\geq \#\widehat{\mathcal{E}}\geq \bigg\lceil\frac{k+1}{\big[(\|H\|+g)/p\big]+1} \bigg\rceil\geq \bigg\lceil\frac{p(k+1)}{\|H\|+g+p}\bigg\rceil.
\]
Therefore, the desired estimate for symplectic fixed points in the theorem follows from the above inequality immediately. \qed




\vspace{1cm}
\noindent\textbf{Proof of Theorem~\ref{thm:schtype}.} According to Lemma~\ref{lem:mixnon0}, for  each integer $l> 2n$, there exists a class $\zeta_l\in\oplus_{i=0}^{n-1}H_{2i}(M;\C)$ such that $(\underbrace{a *_{\zeta_l},\ldots, *_{\zeta_l}a}_l)_{g_l}\neq 0$ for $g_l=\langle[\omega],A_l\rangle$, and hence ${\rm qcl}_{\zeta_l}(g_l)\geq l+1$.
%\begin{equation}\label{e:a*neq0} \overbrace{a *_{\zeta_l},\ldots, *_{\zeta_l}a} ^l\neq 0.\end{equation} 
Moreover, for each such $l$, by (\ref{e:ngw}), we have the nonzero Gromov-Witten invariant
\begin{equation}\label{e:gwl}
    {\rm GW}_{0,l+1+K,A_l}^{\{1,\ldots,l+1\}}(\underbrace{a,\ldots,a}_l,b^l,\eta_1^l,\ldots,\eta_{K}^l)   
    \end{equation}
for some homogeneous class $b^l\in H_*(M;\Q)$ of even degree, and homogeneous classes $\eta_1^l\ldots,\eta_K^l\in \oplus_{i=0}^{n-2}H_{2i}(M;\Q)$ with $0\leq K=K(l)\leq k(l)$ (corresponding to $K=0$ there are no inserted classes $\eta_i^l$). Then it follows from Theorem~\ref{thm:bcl} that for any $\varphi\in\ham(M,\omega)$, 
\begin{equation}\label{e:l}
\#{\rm Fix}(\varphi)\geq 
    \limsup_l\bigg\lceil \frac{p(l+1)}{p+g_l+\|\varphi\|} \bigg\rceil 
\end{equation}
We now estimate the right hand side of the above inequality. Since the invariant (\ref{e:gwl}) does not vanish, according to the dimension formula~(\ref{e:mixdim}), we obtain 
\begin{equation}\label{e:ldeg}
 l(2n-\deg(a))+2n-\deg(b^l)+\sum_{j=1}^K(2n-\deg(\eta^l_j))=2n+2\langle c_1(TM),A_l\rangle+2K. 
\end{equation}
Note that $2n-\deg(\eta^l_j)\geq 4$ for all $2n< l\in\N$ and all $j\in\{1,\ldots,K(l)\}$. Then (\ref{e:ldeg}) yields
\begin{itemize}
\item[(a)] $\langle c_1(TM),A_l\rangle\to\infty$ as $l\to \infty$,
\item[(b)] $\frac{2}{l}\langle c_1(TM),A_l\rangle\leq 2n-\deg(a)+\frac{1}{\ell}\sum_{j=1}^K(2n-2-\deg(\eta^l_j))-\frac{1}{l}\deg(b^l)$ for all $l$. 
%\item[(b)] $0\leq \sum_{j=1}^K(2n-2-\deg(\eta^l_j))\leq 2c_1(A_l)+2n$ for all $l$
\end{itemize}
If the function $l\mapsto k(l)$ is bounded and so for $K=K(l)$, then the (b) as above implies
\[
\limsup_l  \frac{l}{\langle c_1(TM),A_l\rangle}\geq \frac{2}{2n-\deg(a)}. 
\]
Since $\omega|_{\pi_2(M)}=\lambda c_1|_{\pi_2(M)}\neq 0$ for some $\lambda>0$, we get that $\omega(A_l)\to\infty$ as $l\to\infty$, and $p=\lambda N$. 
Hence, 
\[\small
    \limsup_l \frac{p(l+1)}{p+g_l+\|\varphi\|}\geq \limsup_l \frac{l}{\langle c_1(TM),A_l\rangle}\cdot\frac{\lambda N}{(p+\|\varphi\|)/\langle c_1(TM),A_l\rangle+\lambda}\geq \frac{2N}{2n-\deg(a)}
\]
from which, together with (\ref{e:l}), we obtain the estimate as required. \qed


\vspace{1cm}
\noindent\textbf{Proof of Theorem~\ref{thm:onept}.}
Let $\varphi=\varphi_H^1$ for some $H\in\rH$. The proof of the theorem is divided into two parts.

\noindent (1) Since our symplectic manifold $(M,\omega)$ carries the nonzero mixed Gromov-Witten invariant, by Lemma~\ref{lem:kfoldprod}, there is a class $\zeta\in\oplus_{i=0}^{n-1}H(M;\C)$ such that 
\begin{equation}\label{e:a1al}
    a_1 *_\zeta\cdots *_\zeta a_l = \lambda[M]+\beta
\end{equation} 
with $\beta\in H_{*<2n}(M;\Lambda_0)$ and $\nu(\lambda)\geq -\langle [\omega],A\rangle$. Set $\alpha_0=[M]$ and 
\[
\alpha_j=a_1*_\zeta\cdots *_\zeta a_j,\quad j=1,\ldots, l.    
\]
It follows from Corollary~\ref{cor:specineq} that there exist elements $(x_0,\overline{x}_0),\ldots,(x_{k},\overline{x}_{l})\in\crit(\ah)$ such that 
\begin{equation}\label{e:lactions}
    \rho_\zeta(\alpha_l,H)=\ah(x_{l},\overline{x}_{l})<\ldots<\rho_\zeta(\alpha_0,H)=\ah(x_{0},\overline{x}_{0}).
\end{equation}
According to (\ref{e:a1al}) and Lemma~\ref{clm:alpha}, we have
\[
\rho_\zeta(\alpha_l,H)\geq \rho_\zeta([M],H)+\nu(\lambda)\geq \rho_\zeta([M],H)-\langle [\omega],A \rangle.     
\]
Together with (\ref{e:lactions}), this proves that
\[
\#{\rm Fix}(\varphi^1_H)\geq 1+\bigg\lceil\frac{l+1-\langle [\omega],A \rangle/p-1}{\langle [\omega],A \rangle/p}\bigg\rceil=\bigg\lceil\frac{pl}{\langle [\omega],A \rangle}\bigg\rceil.    
\]
This completes the proof of the estimate (\ref{e:thm1}). 

\noindent (2) According to part (1), for each $l\geq 2$, we have
\begin{equation}\label{e:Al}
    \#{\rm Fix}(\varphi^1_H)\geq \bigg\lceil\frac{pl}{\langle [\omega],A_l \rangle}\bigg\rceil.    
\end{equation}
Next, we estimate the right hand side of the above inequality. The nonvanishing of our sequence of Gromov-Witten invariants implies 
\[
  \sum_{i=1}^l(2n-a_i)+2n=2n+2\langle c_1(TM),A\rangle  
\]
from which we deduce that
\begin{equation}\label{e:c1}
l\cdot\min_i\{2n-a_i\}\leq 2\langle c_1(TM),A\rangle\leq l\cdot \max_i\{2n-a_i\}.  
\end{equation}
Hence, $\langle c_1(TM),A\rangle>0$ because $2n-2a_i\geq 1$ for all $i$ (so the right hand of the inequality (\ref{e:thm2}) is positive).  Combining (\ref{e:Al}) and (\ref{e:c1}) yields the estimate~(\ref{e:thm2}). 
The theorem is proven.\qed

