\begin{spacing}{1}
	We consider an instance of the knapsack problem where for two different items $i$ and $j$, the conditions $v_{i}\ge v_{j}$ and $w_{i}\le w_{j}$ hold for all $i<j$. This instance represents a generalization of the linear function optimization problem with a uniform constraint, as previously explored in\cite{friedrich2017analysis}. Neumann et al.\cite{neumann2018running-time} proved that the time complexity upper bound of (1 + 1) EA for this instance is $O(n^{2}(\ln n+p_{max}))$, where $p_{max}$ is the largest profit of given items. Theorem 3 gives a more general upper bound of EFHT of ($\mu+\lambda)$ EA for this instance. Detailed operations of ($\mu+\lambda$) EA are described as Algorithm 1 \cite{qian2016(mu+lambda)}. 
\end{spacing}


\begin{algorithm}
	\caption{($\mu+\lambda$) EA for the knapsack problem}
	\begin{algorithmic}[1]
		\REQUIRE {Encoding length $n$.}
		\ENSURE {The global optimum $x_{opt}$.}
		\STATE {Initialization: set generation $t$=0, generate a population 
			$X_{0}= \left\{x_{1}, \dots,  x_{\mu}\right\}$ with $\mu$ individuals $x_{i}\in \left\{0, 1\right\}^{n}$, $1\le i\le \mu$, uniformly at random.}
		\WHILE{a global optimum has not been attended}
            \STATE ${X}'=X_{t}$
		\FOR{$i=1$ to $\lambda$}
            \STATE choose a $x$ from $X_{t}$ uniformly at random
            \STATE $x_{temp}=x$
		\STATE ${x}' \leftarrow$ flip each bit of $x$ independently with probability $\frac{1}{n}$
            \IF{$f({x}')>f(x_{t})$ and $x_{temp}\ne x_{t}$} 
            \STATE ${x}' \leftarrow x_{temp}$
            \ENDIF
            \STATE ${X}'\leftarrow {X}'\cup\left\{{x}'\right\}$
		\ENDFOR
		\STATE  delete the $\lambda$ individuals with the lowest fitness value of ${X}'$ uniformly at random
            \STATE $X_{t+1} \leftarrow$ ${X}'$
		\STATE $t \leftarrow t+1$
		\ENDWHILE
            \STATE $x_{opt} \leftarrow$ choose a $x$ from $X_{t}$ with the maximum fitness value 
		\RETURN $x_{opt}$
	\end{algorithmic}
\end{algorithm}



