 % \noindent\textbf{\emph{Case Study II: }}\emph{ Running-time Analysis of ($\mu+\lambda$) EA for the $k$-MAX-SAT problem.}
 \subsection{Case Study II: Expected First Hitting Time Analysis of ($\mu+\lambda$) EA for the $k$-MAX-SAT problem}


Existing running-time analysis studies of the SAT problem have focused on specific instances. For example, Buzdalov and Doerr et al. \cite{buzdalov2017running-time,doerr2015improved} analyzed the running time of EAs for solving random 3-CNF formulas. Sutton et al. \cite{sutton2012parameterized} conducted a running-time analysis of the 2-MAX-SAT problem. We will perform a running-time analysis of the general $k$-MAX-SAT problem to give a more comprehensive view of EAs on this problem.


A $k$-MAX-SAT problem instance is formulated as follows:
\begin{align*}
	l=\left\{(l_{1,1}\vee l_{1,2}\vee \dots l_{1,k}),\dots,(l_{s,1}\vee l_{s,2}\vee \dots l_{s,k})\right\}
\end{align*}
where $s$ denotes the number of clauses, the length of each clause is $k$, and $l_{i,j}$ denote a Boolean variable or its negation. The candidate solutions for the $k$-MAX-SAT instance are represented as binary strings of length $n$. Every bit of the binary string can be interpreted as the state of a Boolean variable $v_{i}$ (i.e., $x_{i}=1$ corresponds to $v_{i}=true$; $x_{i}=0$ corresponds to $v_{i}=false$). Let the function $f(x):\left\{0,1\right\}^{n}\rightarrow \left\{0,1,\dots,s\right\}$ count the clauses in $l$ that are satisfied under the assignment corresponding to $x$. Therefore, the
$k$-MAX-SAT problem is transformed into a pseudo-Boolean function optimization problem.


 Theorem 5 gives the upper bound of EFHT of ($\mu+\lambda$) EA with mutation probability $\frac{1}{2}$ for the $k$-MAX-SAT problem. Detailed operations of ($\mu+\lambda$) EA for the $k$-MAX-SAT problem are described as Algorithm 2 \cite{qian2016(mu+lambda)}. 
\begin{algorithm}
	\caption{($\mu+\lambda$) EA for the $k$-MAX-SAT problem}
	\begin{algorithmic}[1]
		\REQUIRE {Encoding length $n$.}
		\ENSURE {The global optimum $x_{opt}$.}
		\STATE {Initialization: set generation $t$=0, generate a population 
			$X_{0}= \left\{x_{1}, \dots,  x_{\mu}\right\}$ with $\mu$ individuals $x_{i}\in \left\{0, 1\right\}^{n}$, $1\le i\le \mu$, uniformly at random.}
		\WHILE{a global optimum has not been attended}
            \STATE ${X}'=X_{t}$
		\FOR{$i=1$ to $\lambda$}
            \STATE choose a $x$ from $X_{t}$ uniformly at random
		\STATE ${x}' \leftarrow$ flip each bit of $x$ independently with probability $\frac{1}{2}$
            \STATE ${X}'\leftarrow {X}'\cup\left\{{x}'\right\}$
		\ENDFOR
		\STATE  delete the $\lambda$ individuals with the lowest fitness value of ${X}'$ uniformly at random
            \STATE $X_{t+1} \leftarrow$ ${X}'$
		\STATE $t \leftarrow t+1$
		\ENDWHILE
            \STATE $x_{opt} \leftarrow$ choose a $x$ from $X_{t}$ with the maximum fitness value 
		\RETURN $x_{opt}$
	\end{algorithmic}
\end{algorithm}


In the ($\mu+\lambda$) EA, the mutation probability is conventionally set to $\frac{1}{n}$, as described in Algorithm 1. The reason for setting the mutation probability to $\frac{1}{2}$ is to streamline the analysis of expected multiple-gain. With a mutation probability of $\frac{1}{2}$, the probability of any non-best individual mutating into the global optimum is $\frac{N_{opt}}{2^{n}}$. Given that each non-best individual has an equal probability of mutating to the global optimum, Algorithm 2 accepts any offspring individuals ${x}'$ generated by the non-best individuals if $f({x}')<f(x_{t})$.

\textbf{\emph{Theorem 5: }}{Let $Y_{t}=f(x_{opt})-f(x_{t})$ and $T_{0}=min\left\{t\ge 0:Y_{t}=0\right\}$, the average-case EFHT of Algorithm 2 with mutation probability $\frac{1}{2}$  for $k$-MAX-SAT problem satisfies}
\begin{align}
	E(T_{0}|Y_{0})\le \frac{\sum_{x=1}^{s}\frac{1}{x}}{(1-e^{\frac{-\lambda N_{opt}}{2^{n}}})}. 	
\end{align}
where $N_{opt}$ denote the number of global optimums.

\emph{Proof:}\quad Assume that $Y_{t}=r$ where $t<T_{0}$. The probability $p$ that there is at least one individual among the $\lambda$ offspring individuals is the global optimum $x_{opt}$ satisfies
