we have
\begin{align*}
	\sum_{i=1}^{q}\frac{r_{i}-r_{i-1}}{r_{i}}\le \sum_{x=r_{0}+1}^{r_{q}}\frac{1}{x} \le \sum_{x=1}^{s}\frac{1}{x}
\end{align*}


This means $E(T_{0}|Y_{0})\le \frac{1}{(1-e^{\frac{-\lambda N_{opt}}{2^{n}}})}\sum_{x=1}^{s}\frac{1}{x}$. $\hfill{\blacksquare}$


Theorem 5 provides an average-case upper bound of EFHT in closed-form expression of ($\mu+\lambda$) EA with mutation probability $\frac{1}{2}$ for any $k$-MAX-SAT instances. A thorough study of this specific class of ($\mu+\lambda$) EA with a special mutation operator will help reveal the dynamic behavior of general ($\mu+\lambda$) EA. Moreover, the conclusion of Theorem 5 can lead to the following Corollary 3.


\textbf{\emph{Corollary 3: }}{Let $Y_{t}=f(x_{opt})-f(x_{t})$ and $T_{0}=min\left\{t\ge 0:Y_{t}=0\right\}$, the EFHT of Algorithm 2 with mutation probability $\frac{1}{2}$ for $k$-MAX-SAT problem satisfies}
\begin{align}
	E(T_{0}|Y_{0}=r_{L})\in O(\frac{2^{n}(lns+1)}{\lambda N_{opt}}). 	
\end{align}
where $N_{opt}$ denote the number of global optimums.


\emph{Proof:}
According to Theorem 5, we have
\begin{align*}
	E(T_{0}|Y_{0})&\le \frac{\sum_{x=1}^{s}\frac{1}{x}}{1-e^{\frac{-\lambda N_{opt}}{2^{n}}}}
\end{align*}


According to $\sum_{x=1}^{n}\frac{1}{x}\le \ln n+1$, we have
\begin{align*}
    E(T_{0}|Y_{0})&\le \frac{lns+1}{1-e^{\frac{-\lambda N_{opt}}{2^{n}}}}
\end{align*}
When $n\rightarrow \infty$,
\begin{align*}
    \lim_{n \to \infty}\frac{lns+1}{1-e^{\frac{-\lambda N_{opt}}{2^{n}}}} &= \lim_{n \to \infty}\frac{lns+1}{1-(1-\frac{\lambda N_{opt}}{2^{n}})}\\
    &=\frac{2^{n}(lns+1)}{\lambda N_{opt}}
\end{align*}
% \begin{align*}
