% 	&=\lim_{n \to \infty}\frac{\sum_{x=1}^{s}\frac{1}{x}}{\lambda}\frac{2^{n}}{(N_{opt})^{2}} 
% \end{align*}
\begin{spacing}{1}
	It means that $E(T_{0}|Y_{0}=r_{L})\in O(\frac{2^{n}(lns+1)}{\lambda N_{opt}})$. $\hfill{\blacksquare}$
\end{spacing}


By Corollary 1 and Theorem 3, we can obtain the worst-case EFHT of $(\mu+\lambda)$ EA for $k$-MAX-SAT problem.


\textbf{\emph{Theorem 6: }}{Let $Y_{t}=f(x_{opt})-f(x_{t})$ and $T_{0}=min\left\{t\ge 0:Y_{t}=0\right\}$, the worst-case EFHT of Algorithm 3 with mutation probability $\frac{1}{2}$  for $k$-MAX-SAT problem satisfies}
\begin{align}
        E(T_{0}|Y_{0})&\le\frac{\beta(Y_{0}-r_{0})}{\alpha(1-e^{\frac{-\lambda N_{opt}}{2^{n}}})}
\end{align}
where $N_{opt}$ denote the number of global optimums.


\emph{Proof: } By the proof of Theorem 5, we have $G(t, 1)\ge h_{2}(r_{p})$. Therefore, to achieve an expected multiple-gain of at least $r_{p}-r_{p-1}$ after $k$ iterations, $k$ must satisfy the condition $k\cdot h_{2}(r_{p})\ge r_{p}-r_{p-1}$. In addition, $\forall r_{i}\in S$, $0<\alpha\le r_{i}-r_{i-1}\le \beta$. By the inequality $k\cdot h_{2}(r_{p})\ge r_{p}-r_{p-1}$, we have 
\begin{align*}
	k\ge \frac{\beta}{h_{2}(r_{p})}
\end{align*}


Therefore,
\begin{align}
    k_{low}=\beta/{(1-e^{\frac{-\lambda N_{opt}}{2^{n}}})}
\end{align} 


By Corollary 1, we can obtain the worst-case EFHT of Algorithm 1 for the $k$-MAX-SAT problem satisfies
\begin{align}
    E(T_{0}|Y_{0}=r_{L})&\le \frac{k_{low}(r_{L}-r_{0})}{\alpha}\\
    &=\frac{\beta(Y_{0}-r_{0})}{\alpha(1-e^{\frac{-\lambda N_{opt}}{2^{n}}})}
\end{align}
$\hfill{\blacksquare}$



