 % \noindent\textbf{\emph{Case Study III: }}\emph{ Running-time Analysis of ($\mu+\lambda$) EA for the TSP problem where the set of cities is a point set in convex position.}
 \subsection{Case Study III: Expected First Hitting Time Analysis of ($\mu+\lambda$) EA for the TSP problem where the finite point set of cities is in convex position}


The traveling salesman problem (TSP) is also a well-known combinatorial optimization problem. Nevertheless, the theoretical studies of EAs for the TSP problem remain relatively limited. Zhou \cite{zhou2009tsp} introduced a
first running time analysis of a basic ant colony optimization (ACO) algorithm on
two specific TSP problem instances. Kötzing et al. \cite{kotzing2012tsp} further proved that the ACO algorithm can obtain an approximation ratio in expected polynomial time for random TSP instances. Sutton et al. \cite{sutton2014tsp}
introduced a parameterized running-time analysis of the EAs for the Euclidean TSP. Peng et al. \cite{peng2016tsp}
showed that two simple ACO algorithms can obtain an approximation ratio in expected polynomial time for the TSP(1,2) problem. Xia et al. \cite{2019tsp} also presented an approximation running-time analysis for the TSP(1,2) problem. 


Let $V=\left\{1,2,\dots,n\right\}$ be a set 
of $n$ points that denotes the cities. Let $E$ be the set of edges where $E\subseteq V\times V$. Let $G=(V,E)$ be an undirected weighted graph. Let $\left\{i,j\right\}$ denote the edge connecting city $i$ and city $j$. A candidate solution to the TSP problem is a permutation $x=\left\{x_{1},x_{2},\dots,x_{n}\right\}$ where $x_{i}=j$ denotes the city $j$ on the $i$-th position of the tour. The
Hamilton cycle in graph $G$ is the set of $n$ edges $\left\{\left\{x_{1},x_{2}\right\},\left\{x_{2},x_{3}\right\},\dots,\left\{x_{n-1},x_{n}\right\},\left\{x_{n},x_{1}\right\}\right\}$. Consequently, the goal of TSP problem is to find a permutation $x$ that forms a Hamiltonian cycle with the minimum weight.


This subsection analyzes the TSP problem where $V$ is finite a point set in convex position. A finite point set $V$ is in convex position when every point in $V$ is a vertex on its convex
hull. Deǐneko et al. \cite{dei2006tsp} noted that the TSP problem is readily solvable when $V$ is
in convex position. The optimal solution to such TSP problems is any tour that follows the boundary of the convex hull. 


Let $x_{n+1}=x_{1}$. Define the function
\begin{align*}
        s(x_{i})=\begin{cases}
0, if\quad 1\le x_{i}\le n-1, |x_{i}-x_{i+1}|=1
 \\
0, if \quad  x_{i}=n,|x_{i}-x_{i+1}|\in \left\{1,n-1\right\}
\\
1, else
\end{cases}
\end{align*}
We say that the point $x_{i}$ is in the correct order if $s(x_{i})=0$. Additionally, $s(x_{i})=0$ implies that $x_{i}$ and $x_{i+1}$ are neighbors. Therefore, the objective of the TSP problem can be transformed into minimizing the number of points that are not in the correct order in the permutation $x$
\begin{align*}
    min\quad f(x)=\sum_{i=1}^{n}s(x_{i})
\end{align*}
where $f(x)\in\left\{0,2,3,\dots,n\right\}$ when $n>5$. Therefore, for $\forall r_{p}\in S$, $1=\alpha\le r_{p}-r_{p-1}\le 2=\beta$.


Since the candidate solutions of the TSP problem are no longer binary strings, mutations can no longer be performed through bit flipping. In this subsection, we consider the 2-opt inversion operation to induce mutations in the candidate solutions.

\textbf{\emph{Definition 7: }}{The 2-opt inversion operation $I_{i,j}$ transforms permutation $x$
into one another $I_{i,j}(x)$ by segment reversal \cite{sutton2014tsp}. For two positions $i$ and $j$ where $1\le i<j\le n$, the new permutation $I_{i,j}(x)$ is generated by inverting the subsequence in $x$ from $x_{i}$ to $x_{j}$.}
\begin{align*}
    x=(x_{1},\dots,x_{i-1},x_{i},x_{i+1},\dots,x_{j-1},x_{j},x_{j+1},\dots,x_{n})\\
    I_{i,j}(x)=(x_{1},\dots,x_{i-1},x_{j},x_{j-1},\dots,x_{i+1},x_{i},x_{j+1},\dots,x_{n})
\end{align*}
$\hfill{\blacksquare}$ 


Detailed operations of ($\mu+\lambda$) EA for the TSP problem are described as Algorithm 3 \cite{sutton2014tsp}. Algorithm 3 rejects any offspring individuals ${x}'$ generated by the non-best individuals if $f({x}')<f(x_{t})$ (lines 9-11).

\begin{algorithm}
	\caption{($\mu+\lambda$) EA for the TSP problem}
	\begin{algorithmic}[1]
		\REQUIRE {Number of cities $n$.}
		\ENSURE {The optimal permutation $x_{opt}$.}
		\STATE {Initialization: set generation $t$=0, generate a population 
			$X_{0}= \left\{x_{1}, \dots,  x_{\mu}\right\}$ with $\mu$ permutations $x_{i}=\left\{x_{i,1}, \dots,  x_{i,n}\right\}$, $1\le i\le \mu$, uniformly at random.}
		\WHILE{an optimal permutation has not been attended}
            \STATE ${X}'=X_{t}$
		\FOR{$i=1$ to $\lambda$}
            \STATE choose a $x$ from $X_{t}$ uniformly at random
            \STATE draw $s$ from Poisson distribution with parameter $\lambda_{p}$
            \STATE $x_{temp}=x$
		\STATE ${x}' \leftarrow$ perform $s+1$ random 2-opt inversion operations on $x$
            \IF{$f({x}')<f(x_{t})$ and $x_{temp}\ne x_{t}$} 
            \STATE ${x}' \leftarrow x_{temp}$
            \ENDIF
            \STATE ${X}'\leftarrow {X}'\cup\left\{{x}'\right\}$
		\ENDFOR
		\STATE delete the $\lambda$ individuals with the highest fitness value of ${X}'$ uniformly at random
            \STATE $X_{t+1} \leftarrow {X}'$
		\STATE $t \leftarrow t+1$
		\ENDWHILE
            \STATE $x_{opt} \leftarrow$ choose a $x$ from $X_{t}$ with the minimum fitness value 
		\RETURN $x_{opt}$
	\end{algorithmic}
\end{algorithm}


% Note that each bit of the individual $x$ in Algorithm 1 is flipped with a probability of $\frac{1}{n}$, and the number of flipped bits can be regarded as following a binomial distribution with parameters $n$ and $p=\frac{1}{n}$. Additionally, it is important to observe that the Poisson distribution with parameter 1 can be considered as the limiting case of the binomial distribution as $n\rightarrow \infty$, $p=\frac{1}{n}\rightarrow0$. Therefore, we implement the mutation operation in Algorithm 2 by performing $s+1$ random 2-opt inversion operations where $s$ is a random variable following the Poisson distribution with parameter 1. 
Theorem 7 gives the upper bound of EFHT of Algorithm 3 for the TSP problem where $V$ is a finite point set in convex position.


\textbf{\emph{Theorem 7: }}{Let $V$ be a finite set of cities in convex position where $|V|>5$. The average-case EFHT of Algorithm 3 for the TSP problem satisfies}
\begin{align}
    E(T_{0}|f(x_{0})=L)\le \frac{2}{1+g}(L+\frac{\mu e^{\lambda_{p}} C_{n}^{2}}{\lambda\lambda_{p}}\sum_{x=1}^{L}\frac{1}{x})
\end{align}
where $g=\frac{-(n-2)(n-5)+2(n-3)(n-4)}{(n-2)^{2}(n-3)}$ and $\lambda_{p}$ is the parameter of Poisson distribution in Algorithm 3.

\emph{Proof:} There are $r$ points that are not in the correct order when $f(x_{t})=r$, $t<T_{0}$. Assume that $x_{t, i}$ is one of the points not in the correct order, and $x_{t, i+1}$ is not the neighbor of $x_{t, i}$. Assume that $x_{t, j}$ is the neighbor of $x_{t, i}$. Let $E_{1}$ denote the event that the mutation operation performs only one random 2-opt inversion operation on $x_{t}$. The probability of $E_{1}$ is $\frac{\lambda_{p}}{e^{\lambda_{p}}}$. If $j>i+1>i$ or $i+1=1<j<i=n$, we say that $x_{t}$ can be improved by a single 2-opt inversion operation $I_{i+1,j}$. 
\begin{align*}
    x_{t}=(\dots,x_{i},x_{i+1},\dots,x_{j},x_{j+1},\dots)\\
    I_{i+1,j}(x_{t})=(\dots,x_{i},x_{j},\dots,x_{i+1},x_{j+1},\dots)
\end{align*}


Note that the edges $\left\{x_{i},x_{i+1}\right\}$ and $\left\{x_{j},x_{j+1}\right\}$ are transformed into $\left\{x_{i},x_{j}\right\}$ and $\left\{x_{i+1},x_{j+1}\right\}$. Therefore, $f(x_{t})$ will decrease 1 because $s(x_{i})$ will decrease from 1 to 0. Let $E_{2}$ denote the event that a random 2-opt inversion operation, which can improve $x_{t}$ is performed on $x_{t}$. The following proof will be discussed in two cases regarding $x_{j+1}$.


\textbf{Case 1}: $x_{j+1}$ is the neighbor of $x_{j}$ with the probability $\frac{1}{n-2}$. In this case, $f(x_{t})$ will increase 1 because the edge $\left\{x_{j},x_{j+1}\right\}$ is transformed into $\left\{x_{i+1},x_{j+1}\right\}$. Additionally, if $x_{i+1}$ is the neighbor of $x_{j+1}$ with the probability $\frac{1}{n-3}$, $f(x_{t})$ will decrease 1. Therefore, the variation of $f(x_{t})$ is
\begin{align*}
    %E(f(x_{t})-f(I(x_{t}))|E_{2} \cap Case 1 )
    \Delta(f(x_{t}))=-1+\frac{1-\frac{1}{n-3}}{(n-2)}
    &=-1+\frac{(n-4)}{(n-2)(n-3)}
\end{align*}


\textbf{Case 2}: $x_{j+1}$ is not the neighbor of $x_{j}$ with the probability $1-\frac{1}{n-2}$. If $x_{j+1}$ is the neighbor of $x_{i}$ and $x_{i+1}$ is the neighbor of $x_{j+1}$ with the probability $\frac{1}{(n-3)^{2}}$, $f(x_{t})$ will decrease 1. Additionally, if $x_{j+1}$ is not the neighbor of $x_{i}$ and $x_{i+1}$ is the neighbor of $x_{j+1}$ with the probability $(1-\frac{1}{n-3})\cdot\frac{2}{(n-2)}$, $f(x_{t})$ will decrease 1. Therefore, the variation of $f(x_{t})$ is
\begin{align*}
    %E(f(x_{t})-f(I(x_{t}))|E_{2} \cap Case 2 )
    \Delta(f(x_{t}))&=-1+\frac{\frac{-1}{(n-3)^{2}}-\frac{2(n-4)}{(n-2)(n-3)}}{\frac{n-2}{n-3}}\\
    &=-1-\frac{(n-2)+2(n-3)(n-4)}{(n-2)^{2}(n-3)}
\end{align*}


Let $g=-\frac{(n-4)}{(n-2)(n-3)}+\frac{(n-2)+2(n-3)(n-4)}{(n-2)^{2}(n-3)}$. Therefore,
\begin{align*}
    E(f(x_{t})-f(I(x_{t}))|E_{1}\cap E_{2})&=1+g
\end{align*}

Since the number of all possible 2-opt inversion operation is $C_{n}^{2}$, we have the probability of $E_{2}$ is at least $\frac{r}{C_{n}^{2}}$. The probability of creating an offspring permutation $x$ by $x_{t}$ where $f(x)<f(x_{t})$ is at least $\frac{b_{t}}{\mu}\frac{\lambda_{p}}{e^{\lambda_{p}}}\frac{r}{C_{n}^{2}}$. The probability that this event occurs at least once during $\lambda$ generations is 
\begin{align*}
    p&=1-(1-\frac{b_{t}}{\mu}\frac{\lambda_{p}}{e^{\lambda_{p}}}\frac{r}{C_{n}^{2}})^{\lambda}\\
    &\ge1-\frac{1}{1+\lambda\frac{b_{t}}{\mu}\frac{\lambda_{p}}{e^{\lambda_{p}}}\frac{r}{C_{n}^{2}}}\\
    &\ge\frac{1}{1+\frac{\mu e^{\lambda_{p}} C_{n}^{2}}{\lambda\lambda_{p} r}}
\end{align*}

Therefore,
\begin{align*}
    E(f(x_{t})-f(x_{t+1})|f(x_{t})=r)&\ge p(1+g)\\
    &\ge \frac{1+g}{1+\frac{\mu e^{\lambda_{p}} C_{n}^{2}}{\lambda\lambda_{p} r}}
\end{align*}

Let $h_{3}(r)=(1+g)/(1+\frac{\mu e^{\lambda_{p}} C_{n}^{2}}{\lambda\lambda_{p} r})$. Note that the range of fitness value $S=\left\{0,1,\dots,n\right\}$. As $h_{3}(r)$ is a monotonically non-decreasing function, by Theorem 2, we have
\begin{align*}
    E(T_{0}|f(x_{0})=L)&\le \frac{1}{1+g}\sum_{i=1}^{L}(r_{i}-r_{i-1})(1+\frac{\mu e^{\lambda_{p}} C_{n}^{2}}{\lambda\lambda_{p} r_{i}})\\
    &\le\frac{2}{1+g}\sum_{i=1}^{L}(1+\frac{\mu e^{\lambda_{p}} C_{n}^{2}}{\lambda\lambda_{p} r_{i}})\\
    &=\frac{2}{1+g}(L+\frac{\mu e^{\lambda_{p}} C_{n}^{2}}{\lambda\lambda_{p}}\sum_{i=1}^{L}\frac{1}{r_{i}})\\
    &=\frac{2}{1+g}(L+\frac{\mu e^{\lambda_{p}} C_{n}^{2}}{\lambda\lambda_{p}}\sum_{x=1}^{L}\frac{1}{x})
\end{align*}
where $g=\frac{-(n-2)(n-5)+2(n-3)(n-4)}{(n-2)^{2}(n-3)}$.
$\hfill{\blacksquare}$

Moreover, the conclusion of Theorem 7 can lead to the following Corollary 4.


\textbf{\emph{Corollary 4: }}{Let $V$ be a finite set of cities in convex position where $|V|>5$. The EFHT of Algorithm 3 for the TSP problem satisfies}
\begin{align}
    E(T_{0}|f(x_{0})=L)\in O(\frac{\mu}{\lambda}n^{2}\ln n+n)
\end{align}
\emph{Proof:}According to Theorem 7, we have
\begin{align*}
    E(T_{0}|f(x_{0})=L)&\le \frac{2}{1+g}(L+\frac{\mu e^{\lambda_{p}} C_{n}^{2}}{\lambda\lambda_{p}}\sum_{x=1}^{L}\frac{1}{x})\\
    &\le \frac{2}{1+g}(n+\frac{\mu e^{\lambda_{p}} C_{n}^{2}}{\lambda\lambda_{p}}\sum_{x=1}^{n}\frac{1}{x})\\
    &\le \frac{2}{1+g}(n+\frac{\mu e^{\lambda_{p}} C_{n}^{2}(\ln n+1)}{\lambda\lambda_{p}})
\end{align*}
When $n\rightarrow \infty$,
\begin{align*}
    \lim_{n \to \infty}1+g&=1+\lim_{n \to \infty}\frac{-(n-2)(n-5)+2(n-3)(n-4)}{(n-2)^{2}(n-3)}\\
    &=1
\end{align*}


Therefore, 
\begin{align*}
    \lim_{n \to \infty}E(T_{0}|f(x_{0})=L)&\le \lim_{n \to \infty}\frac{2(n+\frac{\mu e^{\lambda_{p}} C_{n}^{2}(\ln n+1)}{\lambda\lambda_{p}})}{1+g}\\
    &=2n+\frac{\mu e^{\lambda_{p}}}{\lambda\lambda_{p}}n(n-1)(\ln n+1)
\end{align*}


It means that $E(T_{0}|f(x_{0})=L)\in O(\frac{\mu}{\lambda}n^{2}\ln n+n)$. $\hfill{\blacksquare}$


Corollary 4 presents a tighter upper bound $O(\frac{\mu}{\lambda}n^{2}\ln n+n)$ than the result $O(n\cdot max\left\{(\mu/\lambda)n^{2},1\right\})$ in \cite{sutton2014tsp} by a factor of $n/\ln n$ when $(\mu/\lambda)n^{2}>1$ and $n>5$. 


By Corollary 1 and Theorem 7, we can also obtain the worst-case EFHT of Algorithm 3 for TSP problem.


\textbf{\emph{Theorem 8: }}{Let $V$ be a finite set of cities in convex position where $|V|>5$. The worst-case EFHT of Algorithm 3 for the TSP problem satisfies}
\begin{align}
    E(T_{0}|f(x_{0})=L)&\le \frac{\beta(L-r_{0})(1+\frac{\mu e^{\lambda_{p}} C_{n}^{2}}{\lambda\lambda_{p}})}{\alpha(1+g)}
\end{align}
where $g=\frac{-(n-2)(n-5)+2(n-3)(n-4)}{(n-2)^{2}(n-3)}$ and $\lambda_{p}$ is the parameter of Poisson distribution in Algorithm 3.


\emph{Proof: } By the proof of Theorem 7, we have $G(t, 1)\ge h_{3}(r_{p})$. Therefore, to achieve an expected multiple-gain of at least $r_{p}-r_{p-1}$ after $k$ iterations, $k$ must satisfy the condition $k\cdot h_{3}(r_{p})\ge r_{p}-r_{p-1}$. In addition, $\forall r_{i}\in S$, $0<\alpha\le r_{i}-r_{i-1}\le \beta$. By the inequality $k\cdot h_{3}(r_{p})\ge r_{p}-r_{p-1}$, we have 
\begin{align*}
	k&\ge \frac{\beta}{h_{3}(r_{p})}
    =\frac{\beta(1+\frac{\mu e^{\lambda_{p}} C_{n}^{2}}{\lambda\lambda_{p} r})}{1+g} 
\end{align*}


Therefore,
\begin{align}
    k_{low}=\beta(1+\frac{\mu e^{\lambda_{p}} C_{n}^{2}}{\lambda\lambda_{p}})/(1+g)
\end{align}


By Corollary 1, we can obtain the worst-case EFHT of Algorithm 3 for the TSP problem satisfies
\begin{align}
    E(T_{0}|f(x_{0})=L)&\le \frac{k_{low}(L-r_{0})}{\alpha}\\
    &=\frac{\beta(L-r_{0})(1+\frac{\mu e^{\lambda_{p}} C_{n}^{2}}{\lambda\lambda_{p}})}{\alpha(1+g)}
\end{align}
$\hfill{\blacksquare}$


