\section{Two Conservation Laws: Intralattice Exchange Dynamics}
\label{sec:two}
%-------------------------------
%-------------------------------
%-------------------------------
Next, we focus on intralattice spin-exchange dynamics, as illustrated in Fig.~\ref{Fig1}(c). Since the total magnetization in each of the two lattices is conserved, we expect that the dynamics of the spatially resolved magnetization $m^{\mu}(\mathbf{x},t)$ is governed by a pair of nonreciprocally coupled Cahn-Hilliard equations~\cite{PhysRevX.10.041009, PhysRevE.103.042602,PhysRevLett.131.107201, doi:10.1098/rsta.2022.0087, PhysRevX.14.021014, doi:10.1073/pnas.2010318117, PhysRevLett.131.258302, 10.1093/imamat/hxab026}. The probability $P(\boldsymbol{\sigma};t)$ of finding the system in configuration $\boldsymbol{\sigma}$ at time $t$ evolves according to the master equation
\begin{equation}
\frac{{\rm d}P(\boldsymbol{\sigma};t)}{{\rm d}t} = \sum_{\mu} \sum_{i} \sum_{\langle ij \rangle} \left[ w(\sigma^{\mu}_{j}, \sigma^{\mu}_{i}) P(\boldsymbol{\sigma}^{\mu\mu}_{ij};t) 
- w(\sigma^{\mu}_{i}, \sigma^{\mu}_{j}) P(\boldsymbol{\sigma};t) \right],
\label{masterequation3}
\end{equation}
where $\boldsymbol{\sigma}^{\mu\mu}_{ij}$ denotes the state obtained from $\boldsymbol{\sigma}$ by interchanging the spins $\sigma^{\mu}_{i}$ and $\sigma^{\mu}_{j}$ on lattice $\mu$. Note that these states only differ when $\sigma^{\mu}_{i} = -\sigma^{\mu}_{j}$. Given a fixed initial number of up spins in each lattice, denoted by $\{N^{a}_{+}, N^{b}_{+}\}$, the dynamics is confined to a configuration space of size $\binom{N}{N^{a}_{+}} \binom{N}{N^{b}_{+}}$. As in the case of single spin-flip dynamics, we choose the transition rates to satisfy detailed balance when $K_{a} = K_{b}$, yielding~\cite{PhysRev.145.224}
\begin{equation}
w(\sigma^{\mu}_{i}, \sigma^{\mu}_{j}) = \frac{1}{2\tau} \left[1 - \tanh\left( \frac{\Delta E^{\mu\mu}_{ij}}{2} \right) \right],
\label{Kawasakirate}
\end{equation}
where $\Delta E^{\mu\mu}_{ij}$ is the change in energy after exchanging neighboring spins $\sigma^{\mu}_{i}$ and $\sigma^{\mu}_{j}$ on lattice $\mu \in \{a,b\}$, and $\tau \geq 0$ is the characteristic time scale for an intralattice exchange of spins. To compute $\Delta E^{\mu\mu}_{ij}$, we model the exchange as a sequence of two independent spin flips, where each spin flips in its own local field~\cite{Ducastelle1996}. This approach ensures that the underlying free energy remains consistent with that of single spin-flip dynamics\footnote{Alternatively, one could take into account that the neighboring spin involved in the exchange does not contribute to the energy change during the flip. This leads to a slightly different expression for the underlying free energy w.r.t.~single spin-flip dynamics as shown in \cite{Penrose1991}. However, this does not result in any qualitative changes.}. The local energy $E^{\mu}_{i}$ of spin $\sigma^{\mu}_{i}$ is given by Eq.~\eqref{Eh}, and the corresponding energy change is
\begin{equation*}
\Delta E^{\mu\mu}_{ij} = (\sigma^{\mu}_{i} - \sigma^{\mu}_{j}) (h^{\mu}_{i} - h^{\mu}_{j}),
\end{equation*}
where $h^{\mu}_{i}$ is defined in Eq.~\eqref{h}. Note that upon interchanging two spins the new local fields of both spins also interchange, i.e., $h^{\mu}_{i}\leftrightarrow h^{\mu}_{j}$, and therefore $\Delta E^{\mu\mu}_{ji}=-\Delta E^{\mu\mu}_{ij}$. Using Eqs.~\eqref{masterequation3} and \eqref{Kawasakirate}, we derive the exact dynamical equation for the expectation value of a single spin defined in Eq.~\eqref{m} \cite{Penrose1991, Ducastelle1996}:
\begin{equation}
\tau \frac{{\rm d}m^{\mu}_{i}(t)}{{\rm d}t} = \frac{1}{2} \sum_{\langle ij \rangle} \left[ \langle (1 - \sigma^{\mu}_{i} \sigma^{\mu}_{j}) \tanh(h^{\mu}_{i} - h^{\mu}_{j}) \rangle(t) + m^{\mu}_{j}(t) - m^{\mu}_{i}(t) \right].
\label{Kawasakioutwritten}
\end{equation}
As in Eq.~\eqref{r.h.s.}, this equation is not closed due to the
expectation value of $\tanh(h^{\mu}_{i} - h^{\mu}_{j})$. To resolve
this, we apply the MF approximation. Note that in
\cite{Gouyet01092003} a similar MF approximation has been applied to study spin-exchange dynamics on a single lattice with exponential (Arrhenius-type) transition rates.
%---------------------------------
%---------------------------------
\subsection{Mean-Field Approximation}
%---------------------------------
%---------------------------------
We now evaluate Eq.~\eqref{Kawasakioutwritten} at the MF level, for which we use the approximation given by Eq.~\eqref{hMF}, along with a factorization of the pair correlations:
\begin{equation}
    \langle \sigma^{\mu}_{i}\sigma^{\mu}_{j} \rangle\stackrel{\rm MF}{=}\langle \sigma^{\mu}_{i} \rangle \langle \sigma^{\mu}_{j} \rangle.
    \label{pairmf}
\end{equation}
Inserting these approximations into Eq.~\eqref{Kawasakioutwritten} we obtain
\begin{equation}
    \tau\frac{{\rm d}m^{\mu}_{i}(t)}{{\rm d}t}=\frac{1}{2}\sum_{\langle ij \rangle}\left[(1-m^{\mu}_{i}(t)m^{\mu}_{j}(t))\tanh{(\langle h^{\mu}_{i}\rangle(t)-\langle h^{\mu}_{j} \rangle(t))}-m^{\mu}_{i}(t)+m^{\mu}_{j}(t)\right].
    \label{Kawasakiintermediate}
\end{equation}
Using the identity given by Eq.~\eqref{identity} 
together with the following relation for $\Phi(x)$ given by Eq.~\eqref{phi}
\begin{equation*}
    2\arctanh{\left(\frac{m^{\mu}_{i}-m^{\mu}_{j}}{1-m^{\mu}_{i}m^{\mu}_{j}}\right)}=\frac{{\rm d}\Phi(m^{\mu}_{i})}{{\rm d}m^{\mu}_{i}}-\frac{{\rm d}\Phi(m^{\mu}_{j})}{{\rm d}m^{\mu}_{j}},
\end{equation*}
we can rewrite Eq.~\eqref{Kawasakiintermediate} as (omitting the $t$-dependence)
\begin{align}
    \begin{split}
     \tau\frac{{\rm d}m^{a}_{i}}{{\rm d}t}&=\frac{1}{2}\sum_{\langle ij \rangle}\mathcal{M}^{aa}_{ij}(\textbf{m}^{a},\textbf{m}^{b})\tanh{\left(\frac{\partial \mathcal{F}(\textbf{m}^{a},\textbf{m}^{b})}{\partial m^{a}_{j}}{-}\frac{\partial \mathcal{F}(\textbf{m}^{a},\textbf{m}^{b})}{\partial m^{a}_{i}}{+}\frac{K_{a}{-}K_{b}}{2}(m^{b}_{i}{-}m^{b}_{j})\right)}, \\
     \tau\frac{{\rm d}m^{b}_{i}}{{\rm d}t}&=\frac{1}{2}\sum_{\langle ij \rangle}\mathcal{M}^{bb}_{ij}(\textbf{m}^{a},\textbf{m}^{b})\tanh{\left(\frac{\partial \mathcal{F}(\textbf{m}^{a},\textbf{m}^{b})}{\partial m^{b}_{j}}{-}\frac{\partial \mathcal{F}(\textbf{m}^{a},\textbf{m}^{b})}{\partial m^{b}_{i}}{-}\frac{K_{a}{-}K_{b}}{2}(m^{a}_{i}{-}m^{a}_{j})\right)}, \label{MFb2}
     \end{split}
\end{align}
where the MF free energy $\mathcal{F}(\textbf{m}^{a}, \textbf{m}^{b})$ is defined in Eq.~\eqref{FG}, and the mobility $\mathcal{M}^{\mu\mu}_{ij}(\textbf{m}^{a}, \textbf{m}^{b}) \geq 0$ is given by
\begin{equation*}
    \mathcal{M}^{\mu\mu}_{ij}(\textbf{m}^{a},\textbf{m}^{b})\equiv1-m^{\mu}_{i}m^{\mu}_{j}-(m^{\mu}_{i}-m^{\mu}_{j})\tanh{(\langle h^{\mu}_{i}\rangle-\langle h^{\mu}_{j} \rangle)}.
\end{equation*}
Note that the external magnetic field $H_{\mu}$ cancels out in Eqs.~\eqref{MFb2}, which is expected since the total magnetization in both lattices is conserved. For $N$ spins Eqs.~\eqref{MFb2} comprise a set of $ 2N $ nonlinearly coupled ordinary differential equations which can be solved numerically given suitable initial conditions.
%---------------------------------
%---------------------------------
\subsection{Lyapunov Function for Reciprocal Interactions}
%---------------------------------
%---------------------------------
\noindent When $K_{a}=K_{b}$ (i.e.~for reciprocal interactions) the MF free energy is a Lyapunov function of Eqs.~\eqref{MFb2}. To see this, we compute the time-derivative of $\mathcal{F}(\textbf{m}^{a},\textbf{m}^{b})$, which is given by
\begin{align}
    \tau\frac{{\rm d}\mathcal{F}}{{\rm d}t}&=\tau\sum_{\mu}\sum_{i=1}^{N}\frac{\partial \mathcal{F}}{\partial m^{\mu}_{i}}\frac{{\rm d}m^{\mu}_{i}}{{\rm d}t} \nonumber \\
    &\stackrel{\mathclap{\eqref{MFb2}}}{=}\ \ \ \ -\frac{1}{2}\sum_{\mu}\sum_{i=1}^{N}\sum_{\langle ij \rangle}\mathcal{M}^{\mu\mu}_{ij}\frac{\partial \mathcal{F}}{\partial m^{\mu}_{i}}\tanh{\left(\frac{\partial \mathcal{F}}{\partial m^{\mu}_{i}}-\frac{\partial \mathcal{F}}{\partial m^{\mu}_{j}}\right)} \nonumber \\
    &=-\frac{1}{4}\sum_{\mu}\sum_{i=1}^{N}\sum_{\langle ij \rangle}\mathcal{M}^{\mu\mu}_{ij}\left(\frac{\partial \mathcal{F}}{\partial m^{\mu}_{i}}-\frac{\partial \mathcal{F}}{\partial m^{\mu}_{j}}\right)\tanh{\left(\frac{\partial \mathcal{F}}{\partial m^{\mu}_{i}}-\frac{\partial \mathcal{F}}{\partial m^{\mu}_{j}}\right)}\leq0, \label{Lyapunovintra}
\end{align}
where in the last line we used the symmetry $\mathcal{M}^{\mu\mu}_{ij}=\mathcal{M}^{\mu\mu}_{ji}$ and the last inequality follows from the positive definite mobilities and the fact that $x\tanh{(x)}\geq0$ for $x\in\mathbb{R}$.
%---------------------------------
%---------------------------------
\subsection{Thermodynamic Limit}
%---------------------------------
%---------------------------------
\noindent Next, we determine the thermodynamic limit of Eqs.~\eqref{MFb2} (see Sect.~\ref{sec:continuum}). Taking $ \{N_{x}, N_{y}\} \rightarrow \infty $ while keeping the system size $ \{L_{x}, L_{y}\} = \text{const.} $, the lattice spacing vanishes, $\ell\rightarrow 0 $. By expanding in powers of $\ell$ up to second order and employing the gradient expansion~\eqref{gradientexpansion}, Eqs.~\eqref{MFb2} yield the following partial differential equations (omitting the arguments $(\mathbf{x},t)$):
\begin{align}
\begin{split}
     \tau \frac{\partial m^{a}}{\partial t} &= \nabla \cdot \left( \frac{1 - (m^{a})^2}{2} \nabla \left[ \frac{\delta \mathcal{F}[m^{a}, m^{b}]}{\delta m^{a}} - \frac{K_a - K_b}{2} m^{b} \right] \right), \\
    \tau \frac{\partial m^{b}}{\partial t} &= \nabla \cdot \left( \frac{1 - (m^{b})^2}{2} \nabla \left[ \frac{\delta \mathcal{F}[m^{a}, m^{b}]}{\delta m^{b}} + \frac{K_a - K_b}{2} m^{a} \right] \right), \label{CH2}
    \end{split}
\end{align}
where the MF free-energy functional $ \mathcal{F}[m^{a}, m^{b}] $ is
given by Eq.~\eqref{FG2}. Equations~\eqref{CH2} are immediately
recognizable as nonreciprocally coupled Cahn-Hilliard
equations~\cite{PhysRevX.10.041009, PhysRevLett.131.107201,
  doi:10.1098/rsta.2022.0087, PhysRevX.14.021014,
  doi:10.1073/pnas.2010318117, PhysRevLett.131.258302,
  10.1093/imamat/hxab026}, with mobilities $ (1 - m^{\mu}(\mathbf{x},
t)^2)/2 $. This derivation thus provides a microscopic foundation for
the nonreciprocal Cahn-Hilliard model. It is worth noting that, unlike
in Eq.~\eqref{MFb2}, the hyperbolic tangent function $\tanh(\cdot)$ no
longer explicitly appears in Eq.~\eqref{CH2}. This absence results
from a Taylor expansion of the hyperbolic tangent in Eq.~\eqref{MFb2}
to smallest order in $\ell$, that is warranted by the outer sum, and yields a linear approximation of the arguments. In contrast, for single spin-flip dynamics (see Eq.~\eqref{AC1}), such an expansion is not required  as there is no outer sum, and the hyperbolic tangent therefore remains present. 
\begin{figure}[t!]
    \centering
    \includegraphics[width=0.9\linewidth]{Fig4.pdf}
