%-------------------------------
%-------------------------------
\section{One Conservation Law: Inter- and Intralattice Exchange Dynamics}
\label{sec:one}
%-------------------------------
%-------------------------------
%-------------------------------
Finally, we consider the scenario in which nearest-neighbor spins can interchange both within and between the two lattices, as illustrated in Figs.~\ref{Fig1}(c) and \ref{Fig1}(d), respectively. Under this dynamics, the sum of the total magnetizations, $M^{a}(t) + M^{b}(t)$, is conserved. Consequently, we anticipate that the system is governed by a nonreciprocal reactive CH model with one conservation law. The probability $P(\boldsymbol{\sigma};t)$ for the system to be in spin configuration $\boldsymbol{\sigma}$ at time $t$ evolves according to the master equation
\begin{align}
\frac{{\rm d}P(\boldsymbol{\sigma};t)}{{\rm d}t} &= \sum_{i}\left[w(\sigma^{b}_{i},\sigma^{a}_{i})P(\boldsymbol{\sigma}^{ab}_{ii};t) - w(\sigma^{a}_{i},\sigma^{b}_{i})P(\boldsymbol{\sigma};t)\right] \nonumber \\
& + \sum_{\mu}\sum_{i}\sum_{\langle ij \rangle} \left[w(\sigma^{\mu}_{j},\sigma^{\mu}_{i})P(\boldsymbol{\sigma}^{\mu\mu}_{ij};t) - w(\sigma^{\mu}_{i},\sigma^{\mu}_{j})P(\boldsymbol{\sigma};t)\right],
\label{masterequation4}
\end{align}
where $\boldsymbol{\sigma}^{ab}_{ii}$ denotes the spin configuration obtained from $\boldsymbol{\sigma}$ by exchanging spins $\sigma^{a}_{i}$ and $\sigma^{b}_{i}$. The first term on the right-hand side (r.h.s.)~of~Eq.~\eqref{masterequation4} accounts for interlattice spin exchange, while the second term corresponds to intralattice exchange, as previously introduced in Eq.~\eqref{masterequation3}. For a fixed initial number of up spins in each lattice, denoted by $\{N^{a}_{+},N^{b}_{+}\}$, the dynamics is confined to a configuration space of size $\binom{2N}{N^{a}_{+}+N^{b}_{+}}$. The transition rate for intralattice exchange is given by Eq.~\eqref{Kawasakirate}, whereas the interlattice exchange is governed by
\begin{equation}
w(\sigma^{a}_{i},\sigma^{b}_{i}) = \frac{1}{2\tau} \left[1 - \tanh{\left(\frac{\Delta E^{ab}_{ii}}{2}\right)}\right],
\label{Kawasakirate2}
\end{equation}
where $\Delta E^{ab}_{ii}$ denotes the change in local energy resulting from the exchange of $\sigma^{a}_{i}$ and $\sigma^{b}_{i}$, and $\tau>0$ is an intrinsic timescale for the interlattice exchange of spins. For convenience we keep the intrinsic timescales for inter- and intralattice exchange equal. As in Sect.~\ref{sec:two}, we assume that interlattice spin exchange proceeds via two independent single spin-flip events. Under this assumption, the energy change becomes
\begin{equation*}
\Delta E^{ab}_{ii} = (\sigma^{a}_{i} - \sigma^{b}_{i})(h^{a}_{i} - h^{b}_{i}),
\end{equation*}
which vanishes when $\sigma^{a}_{i}=\sigma^{b}_{i}$, since an exchange of equivalent spins does not change the state. In the case of perfect nonreciprocity with $K_{a}=-K_{b}=K$ we find that the nonreciprocal coupling vanishes in \eqref{Kawasakirate2}, since:
\begin{equation*}
    h^{a}_{i} - h^{b}_{i}=H_{a}-H_{b}+J_{a}\sum_{\langle ij \rangle}\sigma^{a}_{j}-J_{b}\sum_{\langle ij \rangle}\sigma^{b}_{j}+K(\sigma^{b}_{i}+\sigma^{a}_{i}),
\end{equation*}
where the last term cancels because the transition only takes place
when $\sigma^{a}_{i}=-\sigma^{b}_{i}$. Combining
Eqs.~\eqref{masterequation4} and~\eqref{Kawasakirate2}, one can derive
the following exact expression for the time evolution of the
single-spin expectation value (omitting the $t$-dependence in the notation):
\begin{align}
\tau \frac{{\rm d}m^{\mu}_{i}}{{\rm d}t} &= 
\frac{1}{2} \left(\langle (1 - \sigma^{\mu}_{i} \sigma^{\nu}_{i}) \tanh(h^{\mu}_{i} - h^{\nu}_{i})\rangle - m^{\mu}_{i} + m^{\nu}_{i} \right) \nonumber \\
& + \frac{1}{2} \sum_{\langle ij \rangle} \left[\langle (1 - \sigma^{\mu}_{i} \sigma^{\mu}_{j}) \tanh(h^{\mu}_{i} - h^{\mu}_{j}) \rangle - m^{\mu}_{i} + m^{\mu}_{j} \right], \quad \nu \neq \mu.
\label{Kawasakioutwritten2}
\end{align}
Our next task is to close Eq.~\eqref{Kawasakioutwritten2} using the MF approximation.
%-------------------------------
%-------------------------------
\subsection{Mean-Field Approximation}
%-------------------------------
%-------------------------------
\noindent We now evaluate Eq.~\eqref{Kawasakioutwritten2} at the MF level, using the approximations given by Eqs.~\eqref{hMF} and \eqref{pairmf}, followed by the application of the exact identity in Eq.~\eqref{identity}. This yields the following expression (omitting the $t$-dependence in the notation):
\begin{align}
\begin{split}
     \tau\frac{{\rm d}m^{a}_{i}}{{\rm d}t}&{=}\frac{1}{2}\sum_{\langle ij \rangle}\mathcal{M}^{aa}_{ij}\tanh{\left(\!\!\frac{\partial\mathcal{F}(\textbf{m}^{a},\textbf{m}^{b})}{\partial m^{a}_{j}}{-}\frac{\partial \mathcal{F}(\textbf{m}^{a},\textbf{m}^{b})}{\partial m^{a}_{i}}{+}\frac{K_{a}{-}K_{b}}{2}(m^{b}_{i}{-}m^{b}_{j})\!\!\right)}{+}\mathcal{R}_{i}(\mathbf{m}^{a},\mathbf{m}^{b}),\\
     \tau\frac{{\rm d}m^{b}_{i}}{{\rm d}t}&{=}\frac{1}{2}\sum_{\langle ij \rangle}\mathcal{M}^{bb}_{ij}\tanh{\left(\!\!\frac{\partial\mathcal{F}(\textbf{m}^{a},\textbf{m}^{b})}{\partial m^{b}_{j}}{-}\frac{\partial \mathcal{F}(\textbf{m}^{a},\textbf{m}^{b})}{\partial m^{b}_{i}}{-}\frac{K_{a}{-}K_{b}}{2}(m^{a}_{i}{-}m^{a}_{j})\!\!\right)}{-}\mathcal{R}_{i}(\mathbf{m}^{a},\mathbf{m}^{b}), \label{MFb3}
\end{split}
\end{align}
where the first term on the r.h.s.~originates from intralattice spin exchange and corresponds to the r.h.s.~of Eqs.~\eqref{MFb2}. The free energy $\mathcal{F}(\textbf{m}^{a},\textbf{m}^{b})$ with $\textbf{m}^{\mu}=\{m^{\mu}_{1},...,m^{\mu}_{N}\}$ is given by Eq.~\eqref{FG}, and the second term, $\mathcal{R}_{i}(\mathbf{m}^{a},\mathbf{m}^{b})$, arises from interlattice exchange and reads
\begin{equation}
    \mathcal{R}_{i}(\mathbf{m}^{a},\mathbf{m}^{b})\equiv\frac{\mathcal{M}^{ab}_{ii}(\mathbf{m}^{a},\mathbf{m}^{b})}{2}\tanh{\left(\frac{\partial \mathcal{F}(\mathbf{m}^{a},\mathbf{m}^{b})}{\partial m^{b}_{i}}-\frac{\partial \mathcal{F}(\mathbf{m}^{a},\mathbf{m}^{b})}{\partial m^{a}_{i}}+\frac{K_{a}{-}K_{b}}{2}(m^{a}_{i}{+}m^{b}_{i})\right)},
    \label{R}
\end{equation}
with the interlattice exchange mobility given by
\begin{equation}
    \mathcal{M}^{ab}_{ii}(\mathbf{m}^{a},\mathbf{m}^{b})\equiv 1-m^{a}_{i}m^{b}_{i}-(m^{a}_{i}-m^{b}_{i})\tanh{(\langle h^{a}_{i}\rangle-\langle h^{b}_{i}\rangle)},
    \label{Mreaction}
\end{equation}
which is always positive. An interesting consequence of Eq.~\eqref{R} is the breakdown of the aforementioned property related to the nonreciprocal coupling: for perfectly nonreciprocal coupling, Eq.~\eqref{R} is not independent of the nonreciprocal coupling strength, whereas Eq.~\eqref{Kawasakioutwritten2} is. 
This discrepancy arises due to the MF approximation, which replaces discrete spin variables $\sigma^{\mu}_{i}$ with continuous fields $m^{\mu}_{i}$. As a result, the approximation neglects the fact that certain discrete-spin interactions may identically vanish in specific configurations. Finally, note that the external magnetic field $H_{\mu}$, as expected, only enters in the reaction term $\mathcal{R}_{i}(\mathbf{m}^{a},\mathbf{m}^{b})$. For a system of $N$ spins, Eqs.~\eqref{MFb3} form a set of $2N$ nonlinearly coupled ordinary differential equations, which can be solved numerically given appropriate initial conditions.
%---------------------------------
%---------------------------------
\subsection{Lyapunov Function for Reciprocal Interactions}
%---------------------------------
%---------------------------------
\noindent When $K_{a} = K_{b}$ (i.e., in the case of reciprocal interactions), the MF free energy $\mathcal{F}(\mathbf{m}^{a}, \mathbf{m}^{b})$ serves as a Lyapunov function for the dynamics governed by Eqs.~\eqref{MFb3}. To demonstrate this, we evaluate the time derivative of $\mathcal{F}(\mathbf{m}^{a}, \mathbf{m}^{b})$. For the intralattice exchange contribution, we can directly apply the bound given by Eq.~\eqref{Lyapunovintra}, yielding the result
\begin{equation*}
    \tau \frac{{\rm d}\mathcal{F}}{{\rm d}t} = \tau \sum_{\mu} \sum_{i=1}^{N} \frac{\partial \mathcal{F}}{\partial m^{\mu}_{i}} \frac{{\rm d}m^{\mu}_{i}}{{\rm d}t}
    \stackbin[\eqref{Lyapunovintra}]{\eqref{MFb3}}{\leq}
    -\frac{1}{2} \sum_{i=1}^{N} \mathcal{M}^{ab}_{ii} \left( \frac{\partial \mathcal{F}}{\partial m^{a}_{i}} - \frac{\partial \mathcal{F}}{\partial m^{b}_{i}} \right)
    \tanh{\left( \frac{\partial \mathcal{F}}{\partial m^{a}_{i}} - \frac{\partial \mathcal{F}}{\partial m^{b}_{i}} \right)} \leq 0, \nonumber
\end{equation*}
where the final inequality follows from the identity $x\tanh(x) \geq 0$ for all $x \in \mathbb{R}$ and the positive definite mobilities.
%---------------------------------
%---------------------------------
\subsection{Thermodynamic Limit}
%---------------------------------
%---------------------------------
Next, we determine the thermodynamic limit of Eqs.~\eqref{MFb3} (see Sect.~\ref{sec:continuum}). Taking $ \{N_{x}, N_{y}\} \rightarrow \infty $ while keeping the system size $ \{L_{x}, L_{y}\} = \text{const.} $, the lattice spacing vanishes, $\ell\rightarrow 0 $. By expanding in powers of $\ell$ up to second order and employing the gradient expansion~\eqref{gradientexpansion}, Eqs.~\eqref{MFb3} yield the following partial differential equations (omitting $(\mathbf{x},t)$ arguments):
\begin{align}
\begin{split}
    \tau \frac{\partial m^{a}}{\partial t} &= \nabla \cdot \left( \frac{1 - (m^{a})^2}{2} \nabla \left[ \frac{\delta \mathcal{F}[m^{a},m^{b}]}{\delta m^{a}} - \frac{K_a - K_b}{2} m^{b} \right] \right)+\mathcal{R}(m^{a},m^{b}), \label{RD1} \\
    \tau \frac{\partial m^{b}}{\partial t} &= \nabla \cdot \left( \frac{1 - (m^{b})^2}{2} \nabla \left[ \frac{\delta \mathcal{F}[m^{a},m^{b}]}{\delta m^{b}} + \frac{K_a - K_b}{2} m^{a} \right] \right)-\mathcal{R}(m^{a},m^{b}),
\end{split}
\end{align}
where $\mathcal{F}[m^{a},m^{b}]$ is given by Eq.~\eqref{FG2}, the reaction term $\mathcal{R}(m^{a},m^{b})$ is the thermodynamic limit of Eq.~\eqref{R}
\begin{equation}
  \mathcal{R}(m^{a},m^{b})\equiv \frac{\mathcal{M}^{ab}(m^{a},m^{b})}{2}\tanh{\left(\frac{\delta \mathcal{F}[m^{a},m^{b}]}{\delta m^{b}}-\frac{\delta \mathcal{F}[m^{a},m^{b}]}{\delta m^{a}}+\frac{K_{a}-K_{b}}{2}(m^{a}+m^{b})\right)},
  \label{eq:mixed-react}
\end{equation}
and the mobility term $\mathcal{M}^{ab}(m^{a},m^{b})$ is the thermodynamic limit of Eq.~\eqref{Mreaction}
\begin{equation}
        \mathcal{M}^{ab}(m^{a},m^{b})\equiv 1{-}m^{a}m^{b}-(m^{a}{-}m^{b})\tanh{\left(\sum_{\mu}(-1)^{\delta_{\mu,b}}\left[H_{\mu}+J_{\mu}[4+\nabla^{2}]m^{\mu}+K_{\mu}m^{\nu}\right]\right)},
        \label{MRD}
\end{equation}
with $\delta_{\mu,b}=1$ when $\mu=b$ and $0$ otherwise. From the structure of Eqs.~\eqref{RD1}, we identify two nonreciprocally coupled Cahn-Hilliard equations with an additional nonreciprocal reactive coupling that conserves the sum of both total magnetizations, similar to other Cahn-Hilliard models with overall mass-conserving reaction terms \cite{PhysRevE.92.012317,Weber_2019,ZWICKER2022101606} that themselfes extend reaction-diffusion models with mass conservation \cite{IsOM2007pre,PoEs2014jcp,YEMC2015sr,halatek2018rethinking} towards nonideal systems \cite{AAFE2024jcp}. A notable feature of the reaction term \eqref{eq:mixed-react} is its strong dependence on the underlying free energy functional $\mathcal{F}[m^{a}, m^{b}]$, analogous to the role of the underlying free energy in the kinetics of mass action reactions for nonideal systems \cite{AAFE2024jcp} and reactive thin-film hydrodynamics~\cite{voss2024gradient,VoTh2025preprint}.
%---------------------------------
%---------------------------------
\subsection{Linear Stability Analysis}
%---------------------------------
%---------------------------------
To understand the conditions under which small perturbations grow or decay, we analyze the linear stability of uniform solutions to Eqs.~\eqref{RD1}. We consider small perturbations of the form given in Eq.~\eqref{perturbation}, where the uniform state $m^{\mu}_0$ must lie on the reactive nullcline~\cite{PhysRevX.10.041036}, defined by
\begin{equation}
    \mathcal{R}(m^{a}_{0},m^{b}_{0})=0.
    \label{zeroR}
\end{equation}
In Fig.~\ref{Fig5}(a)-(c) we show the reactive nullcline (see the red line) for various parameter values. One specific symmetric solution on the reactive nullcline is given by
\begin{equation}
    m^{a}_{0} = m^{b}_{0} = \frac{H_{a} - H_{b}}{4(J_{b} - J_{a}) + K_{b} - K_{a}}, \quad \text{for} \quad \left|\frac{H_{a} - H_{b}}{4(J_{b} - J_{a}) + K_{b} - K_{a}}\right| \leq 1,
    \label{uniformnullcline}
\end{equation}
which is shown as the red point in Fig.~\ref{Fig5}(a)-(c). Quite surprisingly, this symmetric solution even exists in the presence of two unequal magnetic field $H_{a}\neq H_{b}$.

We denote the growth rate of the perturbations by $\hat{\lambda}$ to distinguish them from those in Eqs.~\eqref{lambdaglauber} and~\eqref{lambdakwasaki}. Linearizing Eqs.~\eqref{RD1} around the uniform steady state leads to the eigenvalue problem:
\begin{equation*}
     \hat{\lambda} \begin{pmatrix}
\delta m^{a} \\
\delta m^{b}
\end{pmatrix} =
\left(\frac{|\mathbf{k}|^{2}}{2} \underline{\mathbf{L}} + \underline{\mathbf{R}} \right) \begin{pmatrix}
\delta m^{a} \\
\delta m^{b}
\end{pmatrix},
\end{equation*}
where $\underline{\mathbf{L}}$ is defined in Eq.~\eqref{l}, and $\underline{\mathbf{R}}$ is the Jacobian of the reaction term, evaluated at the uniform steady state:
\begin{equation*}
\underline{\mathbf{R}} \equiv \frac{1/\tau}{1 - m^{a}_{0} m^{b}_{0}} \begin{pmatrix}
\ \ \ [1 - (m^{b}_{0})^2](\tilde{J}_{a}(4 - |\mathbf{k}|^2) - \tilde{K}_{b} - 1) & -[1 - (m^{a}_{0})^2](\tilde{J}_{b}(4 - |\mathbf{k}|^2) - \tilde{K}_{a} - 1) \\
-[1 - (m^{b}_{0})^2](\tilde{J}_{a}(4 - |\mathbf{k}|^2) - \tilde{K}_{b} - 1) & \ \ \ [1 - (m^{a}_{0})^2](\tilde{J}_{b}(4 - |\mathbf{k}|^2) - \tilde{K}_{a} - 1)
\end{pmatrix},
\end{equation*}
with $\tilde{J}_{\mu}$ and $\tilde{K}_{\mu}$ are as defined in Eq.~\eqref{rescaled}. In contrast to the analysis in Sect.~\ref{sec:lstwo}, the growth $\hat{\lambda}$ is not related in a simple way to the eigenvalues of $\underline{\mathbf{L}}$, as the reaction term introduces a nontrivial contribution.
We therefore focus on the special case of the symmetric uniform steady state, leaving a more detailed and systematic analysis of the complete spectral properties for future work.
%---------------------------------
%---------------------------------
%\subsubsection{Magnetization Redistribution From a Symmetric Uniform State}
%---------------------------------
%---------------------------------
\begin{figure}[t!]
    \centering
    \includegraphics[width=0.95\linewidth]{Fig5.pdf}
    \caption{(a)–(c) Reactive nullcline (red line) defined by Eq.~\eqref{zeroR}, shown for parameter values (a) below, (b) at, and (c) above the critical threshold given in Eq.~\eqref{specialpoint}. The background illustrates the flow field for the uniform state, as governed by Eqs.~\eqref{RD1}. In panel (c), the black dashed segment  marks parts of the nullcline that are linearly unstable with respect to uniform perturbations. The red points indicate the symmetric uniform steady states [Eq.~\eqref{uniformnullcline}], which is unstable in (c) and therefore evolves along the line $m^{a}_{0}+m^{b}_{0}={\rm const.}$ towards one of two stable states (black points). (d)–(f) Dispersion relations corresponding to linear perturbations around the symmetric uniform steady state, as given by Eq.~\eqref{eigenRD}. In panel (d), both eigenvalues are non-positive at $|\mathbf{k}| = 0$, indicating linear stability. In panel (e), both eigenvalues vanish at $|\mathbf{k}| = 0$, marking the instability onset. In panel (f), one eigenvalue is positive at $|\mathbf{k}| = 0$, indicating a stationary instability of a band of harmonic modes. The zero crossing at $k^{+}_{1}$ is given by Eq.~\eqref{kAC}. Parameter values used in each panel are listed in Appendix~\ref{AppI}.}
    \label{Fig5}
\end{figure}
To gain analytic insight, we focus on the symmetric uniform steady state $m^{a}_{0} = m^{b}_{0}$, given by Eq.~\eqref{uniformnullcline}. In this case, the eigenvalues of $|\mathbf{k}|^{2} \underline{\mathbf{L}}/2 + \underline{\mathbf{R}}$ (and therefore the growth rate) read
\begin{equation}
    \hat{\lambda}_{\pm} = \frac{1}{2\tau} \left( \Theta \pm \sqrt{\Theta^{2} - 4\Delta} \right),
    \label{eigenRD}
\end{equation}
where the trace $\Theta$ and determinant $\Delta$ are given by
\begin{align*}
    \Theta &\equiv (2 + |\mathbf{k}|^{2})[(\tilde{J}_{a} + \tilde{J}_{b})(4 - |\mathbf{k}|^{2}) - 2]/2 - \tilde{K}_{a} - \tilde{K}_{b}, \\
    \Delta &\equiv |\mathbf{k}|^{2}(4 + |\mathbf{k}|^{2}) \left( [1 - \tilde{J}_{a}(4 - |\mathbf{k}|^{2})][1 - \tilde{J}_{b}(4 - |\mathbf{k}|^{2})] - \tilde{K}_{a} \tilde{K}_{b} \right).
\end{align*}
Observe that $\Delta = 0$ at $|\mathbf{k}| = 0$, and hence one eigenvalue $\hat{\lambda}_{\pm}$ always vanishes at this point, as expected in the presence of one conservation law. The second eigenvalue can be positive or negative at $|\mathbf{k}| = 0$ depending on the sign of $\Theta$, with associated eigenvector $(-1, 1)^{\rm T}$ corresponding to uniform magnetization redistribution between the two lattices. The second eigenvalue also vanishes at $|\mathbf{k}| = 0$ when $\Theta = 0$, which occurs precisely for
\begin{equation}
    4(\tilde{J}_{a} + \tilde{J}_{b}) = 2 + \tilde{K}_{a} + \tilde{K}_{b}.
    \label{specialpoint}
\end{equation}
The corresponding eigenvectors are degenerate, taking the form $(-1, 1)^{\rm T}$. Equation~\eqref{specialpoint} thus defines the critical threshold between stable and unstable magnetization redistribution modes:
\begin{itemize}
    \item For $4(\tilde{J}_{a} + \tilde{J}_{b}) > 2 + \tilde{K}_{a} + \tilde{K}_{b}$ we have $\lambda_{+}>0$ and $\lambda_{-}=0$ at $|\mathbf{k}|=0$, indicating that uniform magnetization redistribution amplifies over time. This is shown in Fig.~\ref{Fig5}(c), where the symmetric uniform state (red point) is unstable  at $|\mathbf{k}| = 0$ and therefore evolves along the line $m^{a}_{0}+m^{b}_{0}={\rm const.}$ towards one of two stables uniform states indicated with the black points. 
    \item  In contrast, for $4(\tilde{J}_{a} + \tilde{J}_{b}) < 2 + \tilde{K}_{a} + \tilde{K}_{b}$ we have $\lambda_{+}=0$ and $\lambda_{-}<0$ at $|\mathbf{k}|=0$, implying that uniform magnetization redistribution decays. This is shown in Fig.~\ref{Fig5}(a), where the symmetric uniform state (red point) is stable. In Fig.~\ref{Fig5}(b) the symmetric uniform state is at the onset of becoming unstable, as the slope of the reactive nullcline at this point is tangent to the constant magnetization line $m^{a}_{0}+m^{b}_{0}={\rm const}$.
\end{itemize}
Figure~\ref{Fig5}(d)-(f) illustrates the dispersion relations corresponding to values below, at, and above this critical threshold. Note that the parameter threshold defined by Eq.~\eqref{specialpoint} admits a clear physical interpretation. Consider the uniform symmetric steady state where $m^{a}_{0} = m^{b}_{0} = 0$ for $H_{a}=H_{b}$, corresponding to an equal number of up and down spins in each lattice. For positive coupling strengths $J_{a}$ and $J_{b}$, it becomes energetically favorable to segregate the spin states, placing all up spins in one lattice and all down spins in the other. When the values of $J_{a}$ and $J_{b}$ exceed the critical threshold in Eq.~\eqref{specialpoint}, this energetic preference outweighs the entropic cost of demixing. As a result, the system undergoes a spontaneous redistribution of magnetization between the lattices, and each spin species preferentially occupies a distinct lattice. This mechanism underlies the instability of uniform magnetization redistribution and drives the emergence of demixed configurations between the two lattices.
