%-------------------------------
%-------------------------------
\section{Further Combinations of Spin-Flip and Spin-Exchange Dynamics}\label{sec:comb}
%-------------------------------
%-------------------------------
%-------------------------------
In the previous section, we have shown that the combination of inter- and intralattice exchange dynamics leads to additive contributions in the resulting partial differential equations. This additivity holds for all three types of kinetic updates of the considered Ising lattices, namely, single spin-flip dynamics and both intra- and interlattice spin-exchange dynamics. Consequently, partial differential equations corresponding to any combination of conservation laws among the two lattices can be constructed by appropriately combining the following three fundamental terms:
\begin{itemize}
    \item Single spin-flip dynamics: 
    \begin{equation*}
       \tau \frac{\partial m^\mu}{\partial t}= \mathcal{A}^\mu \equiv -\mathcal{M}^{\mu}(m^{a},m^{b})\tanh{\left(\frac{\delta   \mathcal{F}[m^{a},m^{b}]}{\delta m^{\mu}} -(-1)^{\delta_{\mu,b}} \frac{K_{a}-K_{b}}{2}m^{\nu} \right)},
    \end{equation*}
    with $\nu\neq\mu$, the free energy $\mathcal{F}[m^{a},m^{b}]$ given by Eq.~\eqref{FG2}, and mobility $\mathcal{M}^{\mu}(m^{a},m^{b})$ by Eq.~\eqref{MAC}. We abbreviate the r.h.s.~as $\mathcal{A}^\mu$ as the linearization of its reciprocal limit corresponds to a noiseless model-A in the Hohenberg-Halperin classification \cite{HoHa1977rmp}.
    \item Intralattice spin-exchange dynamics:
    \begin{equation*}
      \tau \frac{\partial m^\mu}{\partial t}= \mathcal{B}^\mu\equiv\nabla \cdot \left( \frac{1 - (m^{\mu})^2}{2} \nabla \left[ \frac{\delta \mathcal{F}[m^{a}, m^{b}]}{\delta m^{\mu}}  -(-1)^{\delta_{\mu,b}} \frac{K_a - K_b}{2} m^{\nu} \right] \right),
    \end{equation*}
    again with $\nu\neq\mu$, and the free energy given by Eq.~\eqref{FG2}. We abbreviate the r.h.s.~as $\mathcal{B}^\mu$ as its reciprocal limit corresponds to a noiseless model-B in the classification of \cite{HoHa1977rmp}.
    \item Interlattice spin-exchange dynamics:
    \begin{align*}
      \tau \frac{\partial m^\mu}{\partial t}&=(-1)^{\delta_{\mu,b}}\mathcal{R}\\
      &=(-1)^{\delta_{\mu,b}}\frac{\mathcal{M}^{ab}(m^{a},m^{b})}{2}\tanh{\left(\frac{\delta \mathcal{F}[m^{a},m^{b}]}{\delta m^{b}}{-}\frac{\delta \mathcal{F}[m^{a},m^{b}]}{\delta m^{a}}{+}\frac{K_{a}{-}K_{b}}{2}(m^{a}{+}m^{b})\right)},
    \end{align*}
    where the mobility $\mathcal{M}^{ab}(m^{a},m^{b})$ is given by Eq.~\eqref{MRD}. 
\end{itemize}
As an illustrative example, consider a scenario where single spin-flip dynamics is applied on lattice $a$, while intralattice spin-exchange governs the dynamics on lattice $b$. For such dynamics, the total magnetization in lattice $b$ is conserved, resulting in one conservation law. Combining both rules, we obtain a nonreciprocally coupled Allen-Cahn and Cahn-Hilliard system which takes the form (omitting the arguments $(\mathbf{x},t)$)
\begin{align*}
    \tau \frac{\partial m^a}{\partial t}&=\mathcal{A}^a=-\mathcal{M}^{a}(m^{a},m^{b})\tanh{\left(\frac{\delta   \mathcal{F}[m^{a},m^{b}]}{\delta m^{a}} - \frac{K_{a}-K_{b}}{2}m^{b} \right)}, \\
    \tau \frac{\partial m^b}{\partial t}&=\mathcal{B}^b=\nabla \cdot \left( \frac{1 - (m^{b})^2}{2} \nabla \left[ \frac{\delta \mathcal{F}[m^{a}, m^{b}]}{\delta m^{b}}  + \frac{K_a - K_b}{2} m^{a} \right] \right).
\end{align*}
The reciprocal limit of this coupled model corresponds to a noiseless model-C in the classification of \cite{HoHa1977rmp, PhysRevB.10.139} as introduced in \cite{Cahn1994877} to investigate systems with first-order phase transitions in the presence of a single conservation law. These models have also found application in understanding phase separation and gelation phenomena in cellular fluids \cite{BeBH2018rpp, PhysRevE.47.4615}, and various studies have focused on developing numerical methods to solve such systems \cite{BRUNK202412, doi:10.1137/20M1331160}.

