\section{Stackelberg game closed form solutions}
\subsection{Manager Cost}

\[
\int_0^{t_N} \left( S_0 + \gamma(x + y) + \eta(\dot{x} + \dot{y}) + \epsilon \right) \dot{y}(t) \, dt = \sum_{i=1}^6 \text{Term}_i
\]

Each term is:

\begin{align*}
\text{Term}_1 &= S_0 \left[ C_1 (e^{kt_N} - 1) - C_2 (1 - e^{-kt_N}) - K (1 - e^{-t_N/\tau}) \right] \\
\text{Term}_2 &= \gamma C C_1 k \left[ \frac{1}{k}(e^{kt_N} - 1) - \frac{1}{k - \frac{1}{\tau}} (e^{(k - \frac{1}{\tau}) t_N} - 1) \right] \\
&\quad - \gamma C C_2 k \left[ \frac{1}{k}(1 - e^{-kt_N}) - \frac{1}{k + \frac{1}{\tau}} (1 - e^{-(k + \frac{1}{\tau}) t_N}) \right] \\
&\quad - \gamma C K \left[ (1 - e^{-t_N/\tau}) - \frac{1}{2}(1 - e^{-2t_N/\tau}) \right] \\
\text{Term}_3 &= \frac{\gamma C_1^2}{2}(e^{2kt_N} - 1)  \\
& -\frac{\gamma C_2^2}{2}(1 - e^{-2kt_N}) - \frac{\gamma K^2}{2}(1 - e^{-2t_N/\tau}) \\
&\quad - \gamma C_1 K \frac{k}{\tau(k - \frac{1}{\tau})}(e^{(k - \frac{1}{\tau})t_N} - 1) \\
&\quad - \gamma C_2 K \frac{k}{\tau(k + \frac{1}{\tau})}(1 - e^{-(k + \frac{1}{\tau})t_N}) \\
\text{Term}_4 &= \eta A C_1 k \frac{1}{k - \frac{1}{\tau}}(e^{(k - \frac{1}{\tau})t_N} - 1) \\
& -\eta A C_2 k \frac{1}{k + \frac{1}{\tau}}(1 - e^{-(k + \frac{1}{\tau})t_N}) \\
&\quad - \frac{\eta A K}{2}(1 - e^{-2t_N/\tau}) \\
\text{Term}_5 &= \frac{\eta C_1^2 k}{2}(e^{2kt_N} - 1)  \\
& +\frac{\eta C_2^2 k}{2}(1 - e^{-2kt_N}) + \frac{\eta K^2}{2\tau}(1 - e^{-2t_N/\tau}) \\
&\quad - 2\eta C_1 C_2 k^2 t_N - 2\eta C_1 k K \frac{1}{\tau(k - \frac{1}{\tau})}(e^{(k - \frac{1}{\tau})t_N} - 1) \\
&\quad + 2\eta C_2 k K \frac{1}{\tau(k + \frac{1}{\tau})}(1 - e^{-(k + \frac{1}{\tau})t_N}) \\
\text{Term}_6 &= \epsilon \left[ C_1 (e^{kt_N} - 1) - C_2 (1 - e^{-kt_N}) - K (1 - e^{-t_N/\tau}) \right]
\end{align*}
\subsection{Trader Cost}
\[
\begin{aligned}
\int_0^t \left( S_0 + \gamma(x + y) + \eta(\dot{x} + \dot{y}) + \epsilon \right) \dot{x}(t) \, dt =\;&
A_0 C_x \tau \left(1 - e^{-t/\tau} \right) \\
&+ A_1 C_x \frac{e^{(k - \frac{1}{\tau})t} - 1}{k - \frac{1}{\tau}} \\
&+ A_2 C_x \frac{1 - e^{-(k + \frac{1}{\tau})t}}{k + \frac{1}{\tau}} \\
&+ A_3 C_x \frac{\tau}{2} \left(1 - e^{-2t/\tau} \right)
\end{aligned}
\]

With:
\[
\begin{aligned}
A_0 &= S_0 + \gamma C + \epsilon \\
A_1 &= \gamma C_1 + \eta C_1 k \\
A_2 &= \gamma C_2 - \eta C_2 k \\
A_3 &= (K - C)\left( \gamma - \frac{\eta}{\tau} \right) \\
C_x &= \frac{C}{\tau}, \quad k = \sqrt{\frac{\lambda}{\eta D^2}}, \quad
C = \frac{T}{1 - e^{-t_N/\tau}}
\end{aligned}
\]

