\title[Nodal domains and perturbation]{
On the nodal domain count under metric perturbations, Courant sharpness and boundary intersections
}


\author{Saikat Maji}
\address{Indian Institute of Technology Bombay, Powai, Maharashtra 400076, India}
\email{saikatmaji1997@gmail.com}
\author{Mayukh Mukherjee}
\address{Indian Institute of Technology Bombay, Powai, Maharashtra 400076, India}
\email{mathmukherjee@gmail.com}
