    \centering
    \includegraphics[scale=0.23]{excluded_config.png}
    \caption{Examples of excluded configurations of $L$ for $k=3$}
    \label{fig:excluded_config}
\end{figure}

Then we have the following
\begin{Lemma}\label{lem:loc_nod_in_L_k}
%Suppose $\varphi_0$ vanishes to order $k$ at $p\in M$. 
For a given $r$ small enough,  $\NNN(\varphi_t) \cap \overline{B(p,r)} \in \mathcal{L}_k$ for every $|t|<\epsilon$ where $\epsilon$ depends on $r$, where $k$ is the order of vanishing of $\varphi_0$ at $p\in M$.
\end{Lemma}
\begin{proof}
    We choose $r$ small enough such that Lemma \ref{lem:nod_lin_disc_invariant} hold. %Recall that $r$ is chosen small enough such that $\pa B(p,r)$ contains no critical point of $\varphi_t$ for $t$ small enough. 
    Since $\varphi_0$ intersects $B(p, r)$ at $2k$ points, from Lemma \ref{lem:nod_lin_disc_invariant}, we have that $|\pa B(p,r) \cap  \NNN(\varphi_t)|=2k, \; \forall t<\epsilon(r)$. Let $\pa B(p,r) \cap  \NNN(\varphi_t)=\{q_1,q_2,\cdots,q_{2k}\}.$ The nodal line of $\varphi_t$ starting at some $q_i$ will continue smoothly inside $B(p,r)$ until it reaches another $q_j$ without self-intersecting. Thus we have exactly $k$ nodal lines $\{l_1,,l_2,\cdots,l_k\}$ that satisfy conditions (1) and (2) above.  
   Moreover, due to the Faber-Krahn inequality, we see that $B(p,r)$ does not fully contain any nodal domain of $\varphi_t$ i.e., condition (3) is also satisfied. %Finally, there does not exist an isolated nodal point [CITE] of $\varphi_t$. 
   This implies that $\NNN(\varphi_t) \cap \overline{B(p,r)} \in \mathcal{L}_k$.
\end{proof}



\subsection{Proof of Theorem \ref{thm:loc_nod_est}(c)}
Recall that $F_{t}(p)$ denotes the number of nodal domains of $\varphi_t$ restricted to $B(p,r)$. Note that the number of nodal domains of $\varphi_0$ restricted to $B(p,r)$ i.e., $F_0(p)=2k$. In order to prove that 
$$F_t(p)=F_0(p)-C_t+1,$$  
from Lemma \ref{lem:loc_nod_in_L_k}, it is enough to prove the following

\begin{theorem}\label{thm:loc_nod_est_alt_version}
   For any $L \in \mathcal{L}_k$, the number of sectors $S_k$ corresponding to L is $2k-C_{L}+1$, where $C_L$ is the number of connected components of $L$.
\end{theorem}


\begin{proof}
 For the ease of notation, we rename $L=\bigcup_{j=1}^k l_j\in \mathcal{L}_k$ as $L_k$. Observe that if $\{l_1,l_2,\cdots,l_k\}$ satisfies properties (1)-(3), so does any sub-collection of it. In particular, $\displaystyle \cup_{j=1}^k l_j\in \mathcal{L}_k \implies \cup_{j=1}^i l_{j}\in \mathcal{L}_i \;\forall \; 0\leq i\leq k$. Thus we have a sequence $L_0\subset L_1 \subset L_2 \subset\cdots\subset L_K$ such that each $L_{i}=L_{i-1} \cup l_i \in \mathcal{L}_i$. Here $L_0$ denotes the empty set. We also denote $S_i$ as the number of sectors corresponding to $L_i$ and $C_i$ as the number of connected components of $L_i$. Now we prove our claim via induction on $k$.


For $k=1$, we place the curve $l_1$ in $B(p,r)$ with its endpoints on the boundary $\pa B(p,r)$ to get $L_1$. Clearly, the number of sectors $S_1=2$ and the number of connected components $C_1=1$. Then $S_1=2 \times 1 -C_1 +1$, which proves the base case of the induction process. Let us assume that the statement is true for $L_{i-1}$, that is $S_{i-1}=2(i-1)-C_{i-1}+1$. Now we investigate all possible choices to place $l_i$ inside $ B(p,r)$ such that $L_{i-1}\cup l_i\in \mathcal{L}_i$. We can categorise these possible choices into two cases (see Figure \ref{fig: case I and Case II}).
\begin{figure}[ht]
    \centering
    \includegraphics[scale=0.23]{Induction_step_cases.png}
    \caption{The red curve denotes $l_i$ in Case I and II}
    \label{fig: case I and Case II}
\end{figure}
  \begin{itemize}
      \item[Case I:] $l_i$ is disconnected from $L_{i-1}$. 
      %{\color{blue}need to add a picture}
      \item[Case II:] $l_i$ intersects one or more connected components of $L_{i-1}$.
      %{\color{blue}need to add a picture}
  \end{itemize}

 Considering Case I, observe that $l_i$ is completely contained inside one of the sectors corresponding to $L_{i-1}$. So the number of connected of $L_i$ increases by one, i.e. $C_i=C_{i-1}+1$. Furthermore, $l_i$ divides exactly one sector of $L_{i-1}$ into two more sectors. This in turn implies that $S_{i}=S_{i-1}+1$. Upon quick computation, we have
 $$S_i=S_{i-1}+1=(2(i-1)-C_{i-1}+1)+1=2i-C_{i-1}=2i-C_i+1.$$

Now we look at the slightly more complicated Case II. Note that $l_i$ cannot intersect the same curve $l_j$ of $L_{i-1}$ twice. Otherwise, it will violate one of the two conditions (2) and (3). Let $l_i$ intersect $d\leq C_{i-1}$ components of $ L_{i-1}$. Without loss of generality, we assume that $l_i$ intersects $l_1,l_2,\cdots,l_d \in L_{i-1}$. % each belong to different connected components of $  L_{i-1}$.
Also observe that if $l_i$ intersects each $l_j~(j=1, \cdots, d)$ exactly once, then $l_i$ lies in exactly $d+1$ sectors of $L_{i-1}$  (see Figure \ref{fig:Case II: d=4}.A where each colour denotes an intersecting sector).
%Among $S_{i-1}$ sectors 
We will focus on those $d+1$ sectors containing $l_i$ and delete the remaining sectors (as in Figure \ref{fig:Case II: d=4}.B).
\begin{figure}[ht]
    \centering
    \includegraphics[scale=0.6]{Case_II_d_4.png}
    \caption{An example of Case II with $d=4$}
    \label{fig:Case II: d=4}
\end{figure}

Since $l_i$ reduces the number of connected components of $L_{i-1}$  by $d-1$, we have $C_{i}=C_{i-1}-d+1$. Furthermore, $l_i$ divides each of the $d+1$ sectors into two new sectors. Thus, the number of sectors increases by $d+1$, i.e. $S_i = S_{i-1}+d+1$. Therefore we have
  \begin{align*}
     S_i = S_{i-1}+d+1 = (2(i-1)-C_{i-1}+1)+d+1 = 2i -C_{i-1}+d =2i-C_i+1 .
  \end{align*}
This completes the proof.
\end{proof}


