\section{Proof of Theorem \ref{thm:main_result_A}} \label{Sec: Proofs of main theorem 2}

We begin the proof by investigating how the nodal domains behave inside $\displaystyle M'= M\setminus \bigcup_{p \in S_0} B(p,r)$, where $r>0$ is chosen small enough such that Proposition \ref{prop: stability - general} and Lemma \ref{lem:nod_lin_disc_invariant} hold.

\begin{Lemma}\label{Lem: nodal_set_invariance_M'}
    The number of nodal domains of $\varphi_t$ restricted to $M'$ remains invariant for small $t$ and equal to $\nu(\varphi_0)$.
\end{Lemma}
\begin{proof}
    We observe that the balls $\{B(p,r):\; p\in \mathcal{S}_0\}$ are connected by a finite number of nodal line segments $L:=\{l_i:i \in \Lambda\}$. Consider the tubular neighbourhood $U:=\cup_{i\in \Lambda}U_i$ of $\cup_{i \in L}l_i$ where $U_i$ is a tubular neighbourhood of $l_i$ and $U_i \cap U_j = \emptyset$.  Let $l_i$ connects $B(p,r)$ to $B(q,r)$ for $p,q \in \mathcal{S}_0$. We note that $\pa U_i \cap \left( \pa B(p,r) \cup \pa B(q,r)\right)$ has exactly two disjoint components, say, $B_1$ and $B_2$. We claim that, for sufficiently small $t$, each $U_i$ must contain one nodal line segment of $\varphi_t$ connecting $B_1$ to $B_2$. Let us assume that $U_i \cap \NNN(\varphi_t) = \emptyset$. Then $U_i$ is contained in a nodal domain of $\varphi_t$ and $\varphi_t(x)$ is either strictly positive or strictly negative on $U_i$. Therefore, the limiting function i.e. $\varphi_0$ has to be either nonnegative or nonpositive (respectively) on $U_i$. This contradicts the fact that eigenfunctions change sign at nodal sets. Through a similar argument it can not happen that each of the connected components of $\NNN(\varphi_t) \cap U_i$ is a curve connecting $B_1$ (or, $B_2$) to itself (diagram B). Therefore there must exist a nodal line component connecting $B_1$ to $B_2$.\\
\begin{figure}[ht]
    \centering
    \includegraphics[scale=0.25]{Nodal_lines_on_M-Balls.png}
    \caption{Diagram A is admissible ; Diagrams B,C,D, and E are inadmissible}
    \label{}
\end{figure}

Let $U_i$ contain two nodal lines of $\varphi_t$ connecting the corresponding balls (diagrams C,D). In this case, we have $|\NNN(\varphi_t) \cap \pa B(p,r)| > 2k_p$ where $k_p$ is the order of vanishing of $\varphi_0$ at $p$. Thus we have arrived at a contradiction to  Lemma \ref{lem:nod_lin_disc_invariant}. %Through similar reasoning $U_i$ can not contain a nodal line connecting $B(p,r)$ to itself.  
    Furthermore, there can not exist any nodal line homeomorphic to $\SSS^1$ and completely contained in $U_i$ (diagram E), due to Faber-Krahn inequality. Thus we conclude that, restricted to $M'$, each $\varphi_t$ has nodal set structure identical to $\varphi_0$ (diagram A).
    The proof follows from the simple observation that the number of nodal domains of $\varphi_0$ restricted to $M'$ is $\nu(\varphi_0)$. 
\end{proof}






Now we see how the local picture leads to the following global behaviour of the nodal domains. The following theorem is equivalent to proving the first part of Theorem \ref{thm:main_result_A} and the special case in the latter part of the statement has been addressed in Proposition \ref{prop:nodal_line_no_crossing}. 
\begin{theorem}\label{thm:perturb_nodal_domain_reduction-saikat}
    Perturbing the Riemannian metric on a closed surface lowers or preserves the number of nodal domains. 
\end{theorem}
\begin{proof}
    Let $\{p_i: i=1,2,\cdots,n\}$ be the set of nodal critical points of $\varphi_0$ and $B(p_i, r)$ be as in Proposition \ref{prop: stability - general}. 
     We have seen in Lemma \ref{Lem: nodal_set_invariance_M'} that the number of nodal domains restricted to $M'$ remains invariant under perturbation. On the other hand, by Theorem \ref{thm:loc_nod_est_alt_version}, the number of nodal domains restricted to each $B(p_i,r)$ can only be lowered upon perturbation. 
    Observe that it suffices to prove that number $m_t(l)$ of nodal domains of $\varphi_t$ restricted to $M'_l:=M' \cup (\cup_{i=1}^l B(p_i,r))$ is less than or equal to  $\nu(\varphi_0)$ for $0\leq l\leq n$. For convenience, we call them the restricted nodal domains. The base case trivially holds as $m_t(0) = m_0(0) = \nu(\varphi_0)$. %Let the statement be true for $l$. 
    Thus, it is enough to show that 
    \begin{equation}\label{ineq: Induction_step_main_theorem_1.2}
        m_t(l+1) \leq m_t(l).
    \end{equation}
    Let the nodal critical point $p_{l+1}$ has vanishing order $k$. Then the number of sectors of $\varphi_0$ in $B(p_{l+1},r)$ is $2k$. According to Theorem \ref{thm:loc_nod_est_alt_version}, the number of sectors of $\varphi_t$ in $B(p_{l+1},r)$ is $k':=2k-C_t+1 \leq 2k$. 
    Two cases may arise depending on the number of nodal domains of $\varphi_t|_{M_l'}$ merging with a single sector in $B(p_{l+1},r)$. The equality in \eqref{ineq: Induction_step_main_theorem_1.2} holds iff each of the $k'$ sectors merges with exactly one restricted nodal domain. On the other hand, if there exist a sector which merges with more than one restricted nodal domains, we have strict inequality. Furthermore, a close observation reveals that,
    %after merging all the sectors, we have 
    \begin{equation}\label{ineq: upper_bound_decrement}
        0< m_t(l)-m_t(l+1) \leq 2k-k'=C_t-1.
    \end{equation}
    The upper bound is achieved when there is no restricted nodal domain merging with more than one sector. In either case, we have our desired inequality. 
\end{proof}
%{\color{red}SM:In the above proof, we should use only one of the equivalent terms: `sectors' and `restricted nodal domains'.}\\
As a consequence, %of Theorem \ref{thm:loc_nod_est}(b) and Theorem \ref{thm:perturb_nodal_domain_reduction-saikat}, 
we have the following corollary.


\begin{corollary}
    Let $\mathcal{S}_t$ be the set of all nodal critical points of $\varphi_t$. Then
    %We have that,
    \begin{equation*}
        |\mathcal{S}_t| \leq \min\{\nu(\varphi_0) +2(g-1), \sum_{p\in \mathcal{S}_0}|\ind_p(\nabla\varphi_0)|\}.
    \end{equation*}
    %where $|\nu(\varphi_0)|$ is the number of nodal domain of $\varphi_0$.
\end{corollary}
\begin{proof}
    It follows from part (a) and (b) of Theorem \ref{thm:loc_nod_est} that 
 $$|\mathcal{S}_t| \leq \sum_{p\in \mathcal{S_0}} |\ind_{p}(\nabla \varphi_0)|$$
for small enough $|t|$.
On the other hand, from \cite[Theorem 4.2]{HoffmanTaufer} we have the following estimate
\begin{equation*}
    \sum_{q \in \mathcal{S}_t} \deg (p) \leq 4\nu(\varphi_t) +8(g-1) \quad \forall t.
\end{equation*}
where the degree $\deg(p):=2(1-\ind_q(\nabla \varphi_t))$ denotes the number of nodal lines emanating from $q \in \mathcal{S}_t$.
The desired estimate now follows from Theorem \ref{thm:perturb_nodal_domain_reduction-saikat} and the fact that each vertex $q \in \mathcal{S}_t$ has degree at least four.
\end{proof}



We now provide the following estimate on the decrement of the number of nodal domains.
\begin{corollary}\label{cor:nod_dom_dec_est}
%    Let $\nu(\varphi_t),\mathcal{S}_t$ denote the number of nodal domains and the set of nodal critical points of $\varphi_t$ respectively. 
We have that, 
    $$0\leq \nu(\varphi_0)-\nu(\varphi_t) \leq \sum_{p \in \mathcal{S}_0}|\ind_p(\nabla \varphi_0)| -\sum_{q \in \mathcal{S}_t} |\ind_q(\nabla \varphi_t)|$$
\end{corollary}
\begin{proof}
    From the inequality \eqref{eqn: index_connected_component_relation} we have the following upper bound on the number of components of nodal set restricted to $B(p,r), \;p\in \mathcal{S}_0$:
    \begin{align*}
         &1-\ind_p(\nabla\varphi_0) \geq \sum_{q\in \mathcal{S}_t \cap B(p,r)}|\ind_q(\nabla\varphi_t)| + C_t \\
         \implies &C_t  \leq |\ind_p(\nabla \varphi_0)|- \sum_{q\in \mathcal{S}_t \cap B(p,r)}|\ind_q(\nabla\varphi_t)|+1.
    \end{align*}
    Combining with the lower bound estimate in Theorem \ref{thm:loc_nod_est_alt_version}, we have 
    $$
    F_t(p) \geq 2k-\left(|\ind_p(\nabla \varphi_0)|- \sum_{q\in \mathcal{S}_t \cap B(p,r)}|\ind_q(\nabla\varphi_t)|\right)%=2k+(\ind_p(\nabla \varphi_0)+|\mathcal{S}_t \cap B(p,r)|)
    ,
    $$ 
    where the $k=1-\ind_p(\nabla \varphi_0)$ is the vanishing order of $p$.  

    If we keep track of the decrement of the number of restricted nodal domains in each step in Theorem \ref{thm:perturb_nodal_domain_reduction-saikat}, we find that the decrement is bounded above by $\left(|\ind_p(\nabla \varphi_0)|- \sum_{q\in \mathcal{S}_t \cap B(p,r)}|\ind_q(\nabla\varphi_t)|\right)$. Summing over $p \in \mathcal{S}_0$, we have, the total decrement is bounded above by
    $$\sum_{p \in \mathcal{S}_0} \left(|\ind_p(\nabla \varphi_0)|- \sum_{q\in \mathcal{S}_t \cap B(p,r)}|\ind_q(\nabla\varphi_t)|\right) = \sum_{p \in \mathcal{S}_0} |\ind_p(\nabla \varphi_0)|-\sum_{q \in \mathcal{S}_t} |\ind_q(\nabla \varphi_t)|.$$
    This finishes the proof.
\end{proof}


