\section{Nodal domain count under localised perturbation and  applications}\label{sec:changing_topology}

We now deal with the case of localised perturbations in the sense of \cite{Kom2005, Takahashi2002,MukherjeeSaha2021} et al., where the topology of the perturbed surface is not necessarily the same as the limiting surface. More precisely, we consider the following setup.

Let $M_t$ be a one-parameter family (not necessarily a continuous family) of perturbations of the Riemannian surface $M_0$ where the spectrum of $M_0$ is simple (e.g.   \cite[Theorem D]{KriegenMichorRainer11}). Let $t_i\to 0$ be a sequence such that for all $k = 1, \cdots,$ we have 
\begin{equation}\label{eq:eigenval_conv}
    \lim_{t_i \to 0} \lambda_k(M_{t_i}) = \lambda_k(M_0).
\end{equation}
Define
$${M} := \{ x\in M_0 \; : \; \exists \varepsilon_x > 0 \text{ such that } x \in \bigcap_{t_i}~M_{t} \; \text{where} \; t_i\in (- \varepsilon_x,  \varepsilon_x)\}.$$
Equivalently, let 
$${M}_p:=\bigcap_{i\geq p}M_{t_i} \; \text{and} \; {M}:=\bigcup_{p\to \infty} {M}_p.$$
Heuristically, ${M}$ is the {\em eventually unperturbed} part of $M_0$. 

Let $\varphi_{k,0}$ be the $k$-th eigenfunction of $M_0$ and $\varphi_{k,t}$ denote the corresponding $k$-th eigenfunction of the perturbation $M_t$. 
We additionally assume the following $C^\infty$-convergence of eigenfunctions:
\begin{equation}\label{eq:eigenfunc_conv}
    \lim_{t \to 0} \varphi_{k,t}= \varphi_{k,0} \text{ on } 
    {M}. 
\end{equation}
For ease of notation, we will drop $k$ from our notations and use $(\lambda_t, \varphi_t)$ as our eigenpair corresponding to $M_t$. %, and assume $t_0 = 0$. 
From \cite{MukherjeeSaha2021} we know that the nodal set $\NNN({\varphi_t})$ is contained in $M$ and lies in a $\delta-$neighbourhood of $\NNN(\varphi_0)$ for sufficiently small $t$. First, we record an analogue of Theorem \ref{thm:main_result_A} above. 


\begin{theorem}\label{thm:perturb_nodal_domain_reduction}
    Let $M_0$ be a closed Riemannian surface and $M_t$ be a one-parameter family of perturbations satisfying the conditions as described above, %and for the convergence in \eqref{eq:eigenfunc_conv}, 
    we have that for small enough $t$,
    \beq\label{ineq:4.1_gen}
    \nu(\varphi_t)\leq \nu(\varphi_0).
    \eeq
    In case $\varphi_0$ has no nodal critical point, we have that for small enough $t$, 
    \beq\label{ineq:4.1_no_nod_crit}
    \nu(\varphi_t) = \nu(\varphi_0).
    \eeq
\end{theorem}
%The following is a short proposed line of the proof. 
\begin{proof} 

As in \cite{MukherjeeSaha2021}, in this situation, for small enough $t$, $M$ contains an open tubular neighbourhood of $\NNN(\varphi_t)$. The rest of the argument follows by straightforward modifications to the proof of Theorem \ref{thm:perturb_nodal_domain_reduction-saikat}. We omit the repetition.
\end{proof}

\subsection{Application: nodal data prescriptions}\label{subsec:nod_da_pres}
We record our first observation where we construct closed surfaces which are Courant-sharp up to any finite level. 

\begin{proof}[Proof of  Theorem \ref{thm:Freitas_app}]
    Consider a closed surface $M$ of genus $m$ with any Riemannian metric $g_0$. Let $B(p,r)$ be a geodesic disc inside $M$ centred at $p$ with radius $r$, where $r$ is smaller than the injectivity radius of $(M,g_0)$. In other words, $B(p, r)$ is diffeomorphic to the open planar disc. Now recall the following theorem from \cite{Freitas2002}.

    \begin{theorem}[Freitas]\label{thm:Freitas}
    Given any positive integer $k$ there exists a family $\mathcal{M}$ of $S^1$-invariant metrics on the unit disc with positive curvature and fixed area, for which the first $k$ eigenvalues of the Laplace operator with both Neumann and Dirichlet boundary conditions are simple. In both cases, the eigenfunction corresponding to the $l$-th eigenvalue $l=(2, \cdots, k)$ have $l-1$ nodal lines which are closed disjoint circles dividing the disc into $l$ nodal domains.
    \end{theorem}


    Define a new metric on $M$ as follows:
    \begin{equation}\label{eq:modified_Freitas}
   \Tilde{g_{\epsilon}}= 
\left\{
	\begin{array}{ll}
	r^2g_D & \mbox{on } B(p,r) \\
		\epsilon^2 g_0 & \mbox{on } M\setminus B(p,r),
	\end{array}
\right.
\end{equation}
    where $g_D$ is one of the metrics guaranteed by Freitas' result. Note that the metric $\Tilde{g_{\epsilon}}$ is only piecewise smooth, but one can still define Laplacians etc. via piecewise quadratic forms (for example, see \cite[Definition 2.2-2.4, Lemma 2.5]{Takahashi2002}). As in \cite{EPS2015}, it is known that the Laplace spectrum varies continuously with respect to $C^0$ topology. So, one can perturb $\tilde{g}_\epsilon$ slightly to get a smooth metric $g_\epsilon$ whose spectrum is arbitrarily close to that of $\tilde{g}_\epsilon$ (see also Step 4 of Section 2 of \cite{EPS2015}). So, one can instead work with smooth metrics $g_\epsilon$ such that $g_\epsilon|_{B(p, r)} = r^2g_D$ which are arbitrarily close to $\tilde{g}_\epsilon$ in $C^0$-topology and with arbitrarily close spectrum. 

    Let $\lambda_{l, \epsilon}$ denote the $l$-th eigenvalue of $-\Delta_{g_{\epsilon}}$ on $M$ and $\lambda_{l, 0}$ denote the $l$-th Neumann eigenvalue of $-\Delta_{r^2g_{D}}$ on $B(p,r)$. Also, let $\varphi_{l, \epsilon}, \varphi_{l,0}$ denote the corresponding eigenfunctions. %Using arguments similar to Theorem 1.1 in \cite{Takahashi2002} and Theorem 3.4 in \cite{Kom2005}, we have 
    With obvious modifications to arguments in \cite[Section 2, Step 2 and Step 3]{EPS2015}, we have
    $$
    \lim_{\epsilon\to 0} \lambda_{l, \epsilon} = \lambda_{l, 0},~~~~~\text{and the $C^\infty$-convergence}~~~~ \lim_{\epsilon\to 0}\varphi_{l,\epsilon}|_{B(p,r)}= \varphi_{l,0}.
    $$ 
    Since the first $k$ eigenvalues of $-\Delta_{g_D}$ are simple, we get that $\lambda_{l,\epsilon}$ is simple for $l\leq k$ when $\epsilon$ is small enough. Moreover, recall that $\varphi_{l,0}$ has $l-1$ concentric nodal lines for $l\leq k$. Due to Courant's nodal domain theorem, $\NNN(\varphi_{l, \epsilon})$ can have at most $l-1$ disjoint nodal components, and they are contained inside $B(p, r)$ using Lemma \ref{lem:lim_M_1} and the argument from the particular case in Theorem \ref{thm:perturb_nodal_domain_reduction}. %arguments in Proposition \ref{prop:nodal_line_no_crossing}.

    So, for small enough $\epsilon$, considering $g:=g_\epsilon$, we have that the first $k$ eigenfunctions of $-\Delta_g$ have exactly $k$ nodal domains on $M$.    
\end{proof}


As our next application, we address the problem of prescribing nodal intersections on the boundary of surfaces. Before dealing with the more general Theorem \ref{thm: prescription_nodal_intersection_multiple_bdry}, we look at a simpler case of surfaces with one boundary component. The following result allows us to prescribe the number of nodal intersections at the boundary of a compact ``flask''.

\begin{theorem}\label{thm:prescription_nodal_intersection_boundary}
    Let $M$ be a compact Riemannian surface and the boundary $\pa M$ has exactly one component. Given $n \in \mathbb{N}$, there exists a metric $g$ on $M$ such that for some $k\in \NN$ the nodal set of the corresponding Neumann eigenfunction $\varphi_k$ intersects the boundary $\pa M$ exactly $2n$ times.  
\end{theorem}

\begin{proof}
Note that given $n\in \NN$, there exists some Neumann eigenfunction $u$ of the planar unit disc $\mathbb{D}$ such that $\NNN(u)$ intersects the boundary of the disc at exactly $2n$ points. Recall that a disc has a repeated spectrum with multiplicity at most $2$. Also, the eigenvalues corresponding to radial eigenfunctions of a disc are simple, and the corresponding nodal sets are radial and do not intersect the boundary. %because of its repeated spectrum. 
Moreover, it is important to note that for any eigenfunction $u$ whose nodal set intersects the boundary at $2n$ points, there exists $\Tilde{u}$ (obtained by applying the rotational isometry to the Laplacian) linearly independent to $u$ such that $\NNN(\tilde{u})$ also intersects the boundary at $2n$ points, and so does any linear combination of $u, \tilde{u}$. 

Since we intend to use certain limiting arguments that require a simple spectrum of the limiting domain, we cannot work directly with a disc. Instead, we will consider a generic metric perturbation to the unit disc and use the perturbed surface (topological disc with boundary) as our base domain. 
Denote the Euclidean metric on the unit disc $\mathbb{D}$ by $g_{\text{Euc}}$. Recall that $u = J_n(\sqrt{\lambda}r)\cos n(\theta - \theta_0)$ can be made a Neumann eigenfunction on $\mathbb{D}$ with eigenvalue $\lambda$ by choosing $\lambda$ to be the first positive root of $J_n'$ (here, $J_n$ is a Bessel function of the first kind). 
 We now perturb $(\mathbb{D}, g_{\text{Euc}})$ slightly to $(\mathbb{D}, g_t)$ where %$D$ is still a topological disc and 
$g_t$ is a one-parameter family of Riemannian metrics with simple Neumann spectra. Without loss of generality, let the eigenfunction branch $\varphi_t$ converge to $u = J_n(\sqrt{\lambda}r)\cos n\theta$ in the limit.   %and whose Neumann eigenfunctions are Morse up to the boundary $\pa D$, thanks to results in \cite{Uhlenbeck1976}. Observe that the Morse-ness of Neumann eigenfunctions up to the boundary is not strictly covered by Uhlenbeck's results, but one can extend the Neumann eigenfunction slightly in a tubular neighbourhood across the boundary $\pa D$ and use \cite[p 1, Property C.]{Uhlenbeck1976} to conclude that Neumann eigenfunctions are generically Morse up to the boundary. 
Observe that because of the spectral multiplicity on $(\mathbb{D}, g_{\text{Euc}})$ it is not clear which eigenfunction in the limit  $\varphi_t$ will converge to, but what helps our proof is that all the eigenfunctions $J_n(\sqrt{\lambda}r)\cos n(\theta - \theta_0)$ with varying $\theta_0$ have the same nodal structure.  $u$ has exactly one nodal critical point at the origin with $2n$ equiangular nodal rays emanating from it, and $2n$ points of intersection on $\pa \mathbb{D}$. Additionally, from \cite[p 1, Property B.]{Uhlenbeck1976}, the one-parameter family of metrics $g_t$ can be chosen such that zero is not a critical value of $\varphi_t$. In other words, $\NNN(\varphi_t)$ does not have any nodal critical points. 


Now consider a slightly smaller domain $U$ such that $\pa U \subset \DD \setminus  B(0,1-\rho)$ and $\pa U$ has the properties mentioned in the proof of Lemma \ref{lem:nod_lin_disc_invariant}. Since $|\NNN(u)\cap \pa U|=2n$, using Lemma \ref{lem:nod_lin_disc_invariant} to the above one-parameter family of perturbations $g_t$ we have that $\varphi_t$ also intersects the boundary $\pa U$ at $2n$ points for small enough $|t|$. Now we focus on the region outside $U$, say $V:=\DD\setminus U$ and show that $\varphi_t$ in fact intersects the boundary of the disc $\DD$ at $2n$ points. If not, then we have two possibilities (see Figure \ref{fig:inadmissible_nodal_intersections}):
\begin{figure}[ht]
    \centering
    \includegraphics[scale=0.24]{Nodal_Intersections_Thm5.3.png}
    \caption{Inadmissible nodal configurations near the boundary}
    \label{fig:inadmissible_nodal_intersections}
\end{figure}
\begin{itemize}
    \item[(I)] Two components of nodal line join each other in $V$ after exiting $U$. This decreases the number of intersection on the boundary.
    \item[(II)] As a nodal component exits $U$, it splits open into multiple branches increasing the number of intersection.
\end{itemize}


$\NNN(u)$ divides $V$ into exactly $2n$ components and $\varphi_t\to u$ smoothly in $V$. Let $p_i\in \pa \DD $ denote the points of intersection of $\NNN(u)$ at the boundary $\pa \DD$ and $q_i \in \pa U ~(i=1, \cdots, 2n)$ denote the points of intersection at $\pa U$. For some fixed $\delta_i$, consider the open discs $V_i:=B(p_i, \delta)\cap \DD$ such that $q_i\in \pa V_i$. From the argument in Proposition \ref{prop:nodal_line_no_crossing}, one can see that part of nodal set $\NNN(\varphi_t)\cap V$ is contained completely inside the $\delta$-neighbourhoods $V_i$ of $p_i$ ($i=1, \cdots, 2n$) and each $V_i$ contains at least one component of $\NNN(\varphi_t)\cap V$. So, any nodal line component of $\NNN(\varphi_t)$ exiting from $q_i$ stays within $V_i$ until it reaches $\pa \DD$, for sufficiently small $t$. So, Case I is not possible. If possible, let Case II be true. Note that Case II creates new nodal domains of $\varphi_t$ inside $V$. We can show that when $\delta$ (subsequently $\rho$) is chosen small enough, the first eigenvalue of the newly formed nodal domains can be made large enough. We can appropriately modify Lemma 4.7 and repeat the idea of Proposition 4.8 from \cite{MukherjeeSaha2021_III} to show this. Since the first eigenvalue of any new nodal domain is the same as the eigenvalue $\lambda_t$ corresponding to $\varphi_t$, this contradicts the boundedness of $\lambda_t$ as $\lambda_t\to \lambda$. We now move to the final stage of our proof.


 Let $(M, g_M)$ be any given Riemannian surface with exactly one puncture $\pa M$. From the above discussion, define $D:= (\DD, g_t)$ for which the spectrum is simple and the eigenfunction $\varphi_t$ intersects the boundary $\pa \DD$ at $2n$ points with no nodal critical points in the interior. Connect $D$ to $\pa M$ with the join  in $D$ being away from the nodal set $\NNN(\varphi_{t})$ (as shown in Figure \ref{fig: boundray_prescription}). 
\begin{figure}[h]
    \centering
    \includegraphics[scale=0.25]{boundray_prescription_2.png}
    \caption{Connecting a disc to the boundary of a surface}
    \label{fig: boundray_prescription}
\end{figure}

To be more specific, $M$ is diffeomorphic to 
$$D\#_\epsilon M := D(\epsilon) \cup_{\phi_{\epsilon}} M,$$
where
$$D(\epsilon):= D \setminus B(x_1, \epsilon), \hspace{5pt} \text{ with } x_1\in D\setminus \NNN(\varphi_{t}) ~\text{ and } B(x_1, \epsilon)\cap \NNN(\varphi_t)=\emptyset, $$
%$$M_2(1)= M_2 \setminus B(x_2, 1), \hspace{5pt} x_2\in M_2,$$
and $\phi_{\epsilon}: \pa B(x_1,\epsilon)\to \pa M$ %\hspace{5pt} \text{ defined as } x\mapsto x/\epsilon$$
is a smooth ``attaching map''. Define a new metric on the connected sum as
\begin{equation}\label{eq:conn_sum}
   \Tilde{g_{\epsilon}}= 
\left\{
	\begin{array}{ll}
	 g_{0} & \mbox{on } D(\epsilon) \\
		\epsilon^2 g_M & \mbox{on } M.
	\end{array}
\right.
\end{equation}

Let $g_\epsilon$ be a smooth perturbation of $\tilde{g}_\epsilon$, and $(\lambda_{l, \epsilon}, \varphi_{l, \epsilon})$ denote the $l$-th eigensolution of $-\Delta_{g_{\epsilon}}$ on $(M, g_\epsilon)$. Following a similar argument as in the proof of Theorem \ref{thm:Freitas_app}, for some $k\in \NN$, we have the $C^\infty$-convergence $\lim_{\epsilon\to 0}\varphi_{k,\epsilon}|_{D(\epsilon)}= \varphi_t|_{D(\epsilon)}.$ 
From the argument in Lemma 3.6 of \cite{MukherjeeSaha2022}, we know that for small enough $\epsilon$, the nodal set is completely contained inside $D(\epsilon)$. 
%{\color{blue}
Then the conclusion follows via arguments in Proposition \ref{prop:nodal_line_no_crossing} above. Namely, if $\NNN(\varphi_t)$ has $p$ disjoint components, then so does $\NNN(\varphi_{k,\epsilon})$, and for sufficiently small $\epsilon$ each component of $\NNN(\varphi_{k,\epsilon})$ is arbitrarily close to exactly one component of $\NNN(\varphi_t)$. This implies that $\NNN(\varphi_{k,\epsilon})$ intersects $\pa M$ at exactly $2n$ points. 
 \end{proof}

As our final result, we now generalise the above theorem to surfaces with multiple boundary components. 

\begin{proof}[Proof of Theorem \ref{thm: prescription_nodal_intersection_multiple_bdry}]
   We start with $b$ unit discs $\mathbb{D}_i$ ($i=1, \cdots, b$). Let $u_{k_i}$ be an eigenfunction of $\mathbb{D}_i$ corresponding to eigenvalue $\lambda_{k_i}$ such that $u_{k_i}$ intersects the boundary of $\mathbb{D}_i$ at exactly $2n_i$ different points. Now we rescale each $\mathbb{D}_i$ such that 
    $$\lambda_{k_1}=\lambda_{k_2}=\cdots=\lambda_{k_b}.$$ 
    With slight abuse of notation, we use $\lambda_{k_i}$ to denote the eigenvalues of the rescaled discs in the above equality. 

    We can now generically perturb each (rescaled) disc to $D_i$ ($i=1, \cdots, b$) and denote $(\lambda_{k, i}, \varphi_{k,i})$ as its eigenpair. Then each $D_i$ has a simple spectrum. The perturbations on each disc can be made appropriately small enough such that for some $l_i\in \NN$, $(\lambda_{l_i,  i}, \varphi_{l_i, i})$ is close to $(\lambda_{k_i}, \varphi_{k_i})$. Moreover, we assume without loss of generality that 
    $$\lambda_{l_1, 1}< \lambda_{l_2, 2}<\cdots< \lambda_{l_b, b},$$
    and for each $i\in \{1, \cdots, b\}$, $\dist(\lambda_{l,i}, [\lambda_{l_1, 1}, \lambda_{l_b, b}])>0$ if $l\neq l_i$. The latter criteria is equivalent to saying that if we rearrange the union of the spectra of $D_i$ ($i=1, \cdots, b$) in non-decreasing order and denote the elements of the rearrangement as $\mu_{k}$, there exists some $l\in \NN$ such that 
    $$\mu_{l}\neq\mu_{l+1}=\lambda_{l_1, 1},~~~~~\text{and }~~~~~ \lambda_{l_b,b}=\mu_{l+b}\neq \mu_{l+b+1}.$$

    Similar to the construction in Theorem \ref{thm:prescription_nodal_intersection_boundary}, given $(M, g_M)$ a Riemannian surface with $b$ punctures, we connect each $D_i$ to the boundary component $B_i$ as above and the joining on $D_i$ happens away from the nodal set $\NNN(\varphi_{l+i})$. Define a new metric on the multi-connected sum as
\begin{equation}
   {g_{\epsilon}}= 
\left\{
	\begin{array}{ll}
	 g_{\text{Euc}} & \mbox{on } \Omega(\epsilon) \\
		\epsilon^2 g_M & \mbox{on } M,
	\end{array}
\right.
\end{equation}
    where $\Omega(\epsilon)= \bigcup_{i=1}^b D_i\setminus B(x_i, \epsilon)$ and $B(x_i, \epsilon)$ is a ball in $D_i$ away from $\NNN(\varphi_{l+i})$.
    Denote $(\mu_{k, \epsilon}, \varphi_{k,\epsilon})$ as the eigensolution corresponding to $g_\epsilon$. Then, from the argument in \cite{EPS2015}, one can conclude that the eigenvalue $\mu_{l+i,\epsilon}$ converges to $\mu_{l+i}$ as $\epsilon\to 0$. Moreover, the eigenfunctions $ \varphi_{l+i,\epsilon}$ converges smoothly to $\varphi_{l+i}$. Since $\NNN(\varphi_{l+i})$ intersects the boundary of $D_i$ at $2n_i$ points, using the argument in Theorem \ref{thm:prescription_nodal_intersection_boundary} we conclude that $\NNN(\varphi_{l+i,\epsilon})$ intersects $B_i$ at $2n_i$ points.
\end{proof}



\section{Appendix}
Throughout the paper, we have tacitly used the fact that the inner radius of a nodal domain for $\varphi_\lambda$ is comparable to $1/\sqrt{\lambda}$, and the comparability constants vary in a controlled manner upon metric perturbation, at least in the setups described in the Introduction and Section \ref{sec:changing_topology}. Here we make this claim precise.
\begin{theorem}\label{thm: Inner_radius_perturbation}
    Let $M_t:=(M,g_t), t\in \RR$ be a family of smooth Riemannian manifolds, $C^2$ at $t=0$. Let $R_t %:= \inrad(M_t)
    $ be the minimum inner radius over all the nodal domains corresponding to $\varphi_t$ on $M_t$, with the set up as described in \eqref{eq:eigenf_conv}. Then $t \mapsto R_t$ is uniformly bounded away from zero in a small neighbourhood of $t=0$. In other words, for small enough $a >0$, there exists $m>0$ such that $m \leq R_t$ for all $t\in (-a,a)$.
\end{theorem}


\begin{proof}
    From \cite[(15)]{Mangoubi2008}, we have the following  estimate 
    \begin{equation}\label{ineq: inner radius estimate}
        \inrad(M_t) \geq \frac{C_t}{\sqrt{\lambda_t}},
    \end{equation}
    where $C_t:=C(M_t)$ is a constant, depending only on $t$. From our hypothesis, for $\delta_1>0$ there exists $a_1$ (depending on $\delta_1$) such that 
    \begin{align}\label{ineq: eigenvalue and eigenfucntion convergence}
       &\lambda_0- \delta_1<\lambda_t<\lambda_0+\delta_1, \nonumber \\
       &\|\varphi_0-\varphi_t\|_{L^\infty(M)}<\delta_1, \quad \forall t\in (-a_1,a_1).
    \end{align}
    %The set $D_0$ is defined later. 
    Therefore, it is sufficient to control the constant $C_t$. We repeat the proof of the inner radius estimate $\eqref{ineq: inner radius estimate}$ from \cite{Mangoubi2008} with appropriate adjustments to our setting and look closely at the behaviour of $C_t$. We begin with the natural analogues of \cite[Theorems 9, 10]{Mangoubi2008} for the one-parameter family $M_t$. %of smooth manifold stated in the Lemma \ref{thm: Inner_radius_perturbation}. 
    Let $D_t(p,r)$ denote the disc of radius $r$ with centre at $p$ with respect to the metric $g_t$. We will omit $p$ and $r$ wherever they are assumed to be fixed and independent of $t$. For $c>0$ there exists $a_0>0$ such that for any two points $x,y\in M$, $$\frac{1}{c} \cdot d_0(x,y) < d_t(x,y) < c \cdot d_0(x,y), \quad \forall t\in (-a_0,a_0),$$
        where $d_t$ is the distance function with respect to the metric $g_t$. In other words, 
        $$D_0(p,r) \subset D_t(p,c \cdot r) \; \text{and} \; D_t(p,r) \subset D_0(p,c \cdot r).$$
    Then we have the following generalisations of \cite[Theorems 9, 10]{Mangoubi2008} (see also \cite{NazarovPolterovichSodin, Nadirashvili1991}).
     \begin{Lemma}\label{lem: Mangoubi's lemmas}
     \begin{enumerate}
         \item There exist positive constants $ q_+,q_-,\rho>0$ and $a_2:=a_2(p)>0$ such that for each point $p\in M_t$, there exists a disk $D_t(p,\rho)$ centered at $p$ of radius $\rho$, a conformal map $\Psi_{t,p}:\DD \to D_t(p,\rho)$ with $\Psi_{t,p}(0)=p$, and a positive function $q_t(z)$ on $\DD$ such that $$\Psi^*_{t,p}(g)=q_t(z)|dz|^2, \quad \forall t\in (-a_2,a_2),$$ 
         with $q_-<q_t<q_+$.
         \item There exist $\epsilon,\delta,K_1,K_2>0$ and $a_3< \min \{a_0,a_1\}$ such that for every eigenvalue $\lambda_t$ of $M_t$ and disk $D_t:=D_t(p,r) \subset M_t$ of radius $r$ satisfying $D_t(p,r) \subset D_0(p, \frac{\epsilon}{\sqrt{\lambda_0+\delta_1}}) \subset D_t(p, \frac{c\epsilon}{\sqrt{\lambda_t}}),$
         $\varphi_\lambda|_{D_t}$ is $(K_t,\delta)-$quasiharmonic. In other words, 
         $$\varphi_{\lambda_t}|_{D_t}=(v_t\cdot u_t) \circ h_t, \quad \forall t \in (-a_3,a_3),$$
         for a $K_t-$quasiconformal homeomorphism $h_t:D_t \to \DD$, a harmonic function $u_t$ on $\DD$, a function $v_t$ on $\DD$ such that $1-\delta\leq v_t\leq 1$,  $K_1\leq K_t\leq K_2$ and $$\|u_t-u_0\|_{\DD,\infty} < \delta,$$
         for all $t\in (-a_3,a_3)$.
     \end{enumerate}
    \end{Lemma}
      The first part follows by introducing $t$ dependence to the argument in \cite[Lemma 2.3.3]{JurgenJost2002}. For the second part, an application of the \cite[Lemma 3.3]{NazarovPolterovichSodin} to the one parameter family of elliptic equations $-\Delta_{g_t} \varphi_t = \lambda_t \varphi_t$, combined with the first part, gives us the continuity of $v_t$ along with
    $$1-\delta \leq v_t \leq 1,$$
    where $\delta$ is independent of $t$. For the existence and continuity of $h_t$, we refer the readers to \cite[Theorem 5]{Ahlfors-1966}. Due to \cite[Lemma 3.4.]{NazarovPolterovichSodin}, $u_t$ can be expressed as the composition of the real part of the solution $w_t$ to a continuous one parameter family of Beltrami equations and the inverse of $h_t$. Therefore, the continuity of  $\Re(w_t)=\frac{\varphi_t \circ \Psi_t^{-1}}{v_t}$ leads us to the continuity of $u_t$.




    Intuitively, it becomes apparent using Brownian motion techniques that the centre of the largest inscribed ball in a nodal domain is likely to be found near the hotspots (or coldspots). %Furthermore, we use the fact that the hotspots of $\varphi_t$ lies near the hotspots of $\varphi_0$.
    Let $\Omega$ be a  nodal domain of $\varphi_0:=\varphi_{\lambda_0}$. Without of loss of generality, we assume that $\varphi_0|_\Omega$ is positive. Let $p_0$ be a point of maximum of $\varphi_0$ in $\Omega$, i.e. $\varphi_0(p_0)= \max_{x\in \Omega}\varphi_0(x)$. From \eqref{ineq: eigenvalue and eigenfucntion convergence}, 
    \begin{align*}
        &\varphi_0(p_0)-\delta_1 < \|\varphi_t\|_\infty < \varphi_0(p_0)+\delta_1 \quad \text{and} \quad \varphi_t(p_0)-\delta_1<\varphi_0(p_0)<\varphi_t(p_0)+\delta_1,\\
        \implies& \varphi_t(p_0)+2\delta_1>\varphi_0(p_0)+\delta_1 > \varphi_t(x), \quad \forall x\in \Omega, t\in (-a_2,a_2).
    \end{align*}
     Therefore, we expect $p_0$ to be centre of a  large inscribed ball in a nodal domain of $\varphi_t$, even though $p_0$ may not be a point of maximum of $\varphi_t|_\Omega$. Let $R=\frac{\epsilon}{c\sqrt{(\lambda_0+\delta_1) q_+}}$. Let $D_t(p_0,R\sqrt{q_+}) \subset D_t(p_0,\rho) \subset \Omega$ be a disc of radius $R\sqrt{q_+}=\frac{\epsilon}{c\sqrt{\lambda_0+\delta_1}}$ centred at $p_0$. Since $D_t(p_0,R\sqrt{q_+}) \subset D_0(p_0, \frac{\epsilon}{\sqrt{\lambda_0+\delta}})$, we can apply Lemma \ref{lem: Mangoubi's lemmas}. We have,
    \begin{align*}
        &\varphi_t(p_0)= u_t(0)v_t(0) \geq u_t(z)v_t(z)-2\delta_1 \geq u_t(z)(1-\delta)-2\delta_1, \quad \forall z\in \DD\\
        \implies & u_t(0)\geq (1-\delta) \max_{\DD}u_t(z) -2\delta_1,
    \end{align*}
    for all $t \in (-a_3,a_3)$. 

    We note that the harmonic measure of a set $E$ with respect to a point $x$ can be seen as the hitting distribution of a Brownian motion starting at $x$. Therefore, %a lower bound on the harmonic measure of the compliment of the nodal domain containing $p_0$ is expected to reveal some information about the radius of the inscribed ball centred at $p_0$.
    an intuitive argument is that a Brownian particle starting at a high value (close to max) of $\varphi_t$ cannot hit the nodal set of $\varphi_t$ quickly. In dimension $2$, a lower bound on the hitting time implies a lower bound on the distance to the obstacle (this fact is untrue in higher dimensions because of the possibility of {\em needles} of small {\em capacity}). Though we point out that the harmonic measure argument is not directly applied to a disc around $p_0 \in M$, but to a conformal image of the neighbourhood. Finally, an application of a result of Mori \cite{Mori1957} provides us with the desired estimate. We now make the above mentioned intuitive argument precise by following the argument in \cite{Mangoubi2008}.

    Let $U^0_{t,\lambda} \subset \DD$ be the connected component of ${u_t > 0}$, which contains $0$. Let $\omega_t$ be the harmonic measure of $E_t := \DD \setminus  U^0_{t,\lambda}$ in $\DD$.
    The discussion around \cite[Equations 3-4]{Ahlfors-Conformal_invar} provides us with the following lower bound
    $$\omega_t(0) \geq 1-C_1\sqrt{r_0(t)}, \forall t,$$
    where $r_0(t) = \inf\{|z| : z \in E_t\}$ and $C_1$ is independent of $t$. By the majorization principle
    $$u_t(0)/\max_\DD u_t \leq 1- \omega_t(0), \forall t.$$
    Therefore, we have 
    \begin{align*}
       & 1-C_1 \sqrt{r_0(t)} \leq \omega_t(0)\leq 1-\frac{u_t(0)}{\max_\DD u_t}\leq 1-\frac{(1-\delta)\max_\DD (u_t)-2\delta_1}{\max_\DD u_t}\\
       \implies &  1-C_1 \sqrt{r_0(t)} \leq \max\{\delta,2\delta_1\} \frac{\max_\DD u_t +1}{\max_\DD u_t} \leq  \max\{\delta,2\delta_1\} \frac{\max_{\DD} u_0+ \delta +1}{\max_{\DD} u_0-\delta}\\
       \implies & r_0(t) \geq C_2,
    \end{align*}
    for all $t \in (-a,a)$ where $a=\min\{a_1,a_2,a_3\}.$ In the last inequality, we have used the second part of Lemma \ref{lem: Mangoubi's lemmas}.
    In the final step, we Mori's distortion theorem for quasiconformal maps (we readily use the version in \cite[Chapter III C]{Ahlfors-1966}). Denote by $\DD_r \subset \CC$ the disk $\{|z| < r\}$. Observe that,
    $$\Psi_{t,p_0}(\DD_R) \subset D_t(p_0,R\sqrt{q_+}).$$ 
    Hence, the composition
    $$\tilde{h}_t:=h_t \circ \Psi_{t,p_0}: \DD_R \to \DD$$
    is a $K_t-$quasiconformal map.
    By Mori's theorem it is $\frac{1}{K_t}-$H\"older and thus satisfies
   \begin{equation*}
    |\tilde{h}_t(z_1)-\tilde{h}_t(z_2)| \leq M|\Psi_{t,p_0} \circ S_R\left(\frac{z_1}{R}\right)-\Psi_{t,p_0} \circ  S_R\left(\frac{z_2}{R}\right)|^{\frac{1}{K_t}} \leq M\left(\frac{|z_1-z_2|}{R}\right)^{\frac{1}{K_1}},
    \end{equation*}
    where $S_R:\DD \to \DD_R, \; S_R(z)=R \cdot z$ and $\Psi_{t,p_0} \circ S_R:\DD \to \DD$ is a conformal map with bounded derivative. Therefore one gets
     \begin{equation*}
         \frac{\dist (p_0,\pa(U^0_{t,\lambda} \cap D(p_0,R)))}{R} \geq \left(\frac{C_2}{M}\right)^{K_1} \sqrt{q_-}.
     \end{equation*}
     Hence, 
     \begin{equation*}
         \inrad (U_{t,\lambda}) \geq C^{K_1} \sqrt{q_+}R = \frac{C_3}{\sqrt{\lambda_0+\delta_1}}.
     \end{equation*}
    \end{proof}

\begin{remark}
    If $\{M_t: t\in \RR\}$ is a one-parameter family of surfaces considered in Theorem \ref{thm:prescription_nodal_intersection_boundary}, a similar argument follows through, and we omit the repetition.
\end{remark}




