\subsection{Theoretical Analysis}
%This section analyzes the convergence of the proposed distributed fault-tolerant CKF for multi-robot cooperative localization. 
We establish key assumptions about system dynamics, measurement functions, noise, and adversarial attacks. The analysis aims to show that the CKF's estimation error converges to a bounded value over time, even in adversarial environments. By leveraging Lipschitz continuity in the state dynamics and measurement functions, we demonstrate that the event-triggered communication mechanism mitigates noise and adversarial interference, ensuring robust localization performance.
\begin{assumption} \label{Lipschitz Continuous Dynamics}
The state dynamics for each robot $i$ are governed by a Lipschitz continuous function $f$:
\begin{equation}
\|f(x_{i,k}, u_k) - f(x_{i,k}', u_k)\| \leq L_f \|x_{i,k} - x_{i,k}'\|
\end{equation}
where $L_f$ is the Lipschitz constant.
\end{assumption}
\begin{assumption} \label{Lipschitz Continuous Measurement Function}
 The measurement function $h(x_{i,k}, x_{j,k})$ is Lipschitz continuous:
\begin{equation}
\small
\|h(x_{i,k}, x_{j,k}) - h(x_{i,k}', x_{j,k}')\| \leq L_h \left(\|x_{i,k} - x_{i,k}'\|   + \|x_{j,k} - x_{j,k}'\|\right)
\end{equation}
where $L_h$ is the Lipschitz constant.
\end{assumption}
\begin{assumption} \label{Bounded Process and Measurement Noise}
  The process noise $w_k$ and measurement noise $v_k$ are bounded:
\begin{equation}
\|Q_k\| \leq \sigma_Q, \quad \|R_k\| \leq \eta_R
\end{equation}
\end{assumption}
\begin{assumption} \label{Bounded Adversarial Attacks}
The adversary exploits SDZ and CDZ, where environmental or adversarial factors degrade system performance. The number of attacks per time step on sensing and communication is bounded by $\alpha_s$ and $\alpha_c$.
\end{assumption}
\begin{theorem} \label{Theorem}
Consider the nonlinear dynamic system (1)-(3) along with the event-triggered mechanism (11) and assume that assumptions (1)-(4) are satisfied. The state estimation error of the distributed event-based Cubature Kalman Filter (CKF) for multi-robot cooperative localization, operating in dynamic network topology with adversarial environments, converges to a bounded value as time $k \to \infty$.
\end{theorem}

\begin{proof}
1) \textit{State Prediction Step}: The predicted state for robot $i$ is given by:
\begin{equation}
\hat{x}_{i,k+1|k} = f(\hat{x}_{i,k|k}, u_k) + w_{i,k}, \nonumber
\end{equation}
where $w_{i,k} \sim \mathcal{N}(0, Q_k)$. The prediction error is:
\begin{equation}
e_{i,k+1|k} = x_{i,k+1} - \hat{x}_{i,k+1|k} \nonumber
\end{equation}
Using the Lipschitz continuity of $f$:
\begin{equation}
\|e_{i,k+1|k}\| \leq L_f \|e_{i,k|k}\| + \|w_{i,k}\|. \nonumber
\end{equation}
Taking the expectation:
\begin{equation}
\mathbb{E}[\|e_{i,k+1|k}\|^2] \leq L_f^2 \mathbb{E}[\|e_{i,k|k}\|^2] + \sigma_Q. \nonumber
\end{equation}

2) \textit{Measurement Update Step}: The state estimation update incorporates measurements:
\begin{align}
\scalebox{0.8}{$
\begin{aligned}
\hat{x}_{i,k+1|k+1} = \hat{x}_{i,k+1|k}  + \mathlarger{\mathlarger{\sum}}_{j \in S_i} a_{ij,k+1} \lambda_{ij,k+1} \sigma_{ij,k} K_{ij,k+1}  \left( z_{i,k+1} - \hat{z}_{ij,k+1|k} \right) \nonumber
\end{aligned} 
$}
\end{align}
Considering the first-order expansion of $ h_{ij}(x_{i,k}, x_{j,k}) $ around $(\hat{x}_{i,k+1|k}, \hat{x}_{j,k+1|k})$ be
\begin{align}
\begin{aligned}
h_{ij}(x_{i,k+1}, x_{j,k+1}) \approx h_{ij}(\hat{x}_{i,k+1|k}, \hat{x}_{j,k+1|k})   +  H_{i, k+1}e_{i,k+1|k} \\ + H_{j, k+1}e_{j,k+1|k}
 + O(e_{i,k+1|k}, e_{j,k+1|k})
\end{aligned} \nonumber
\end{align}
where $O(e_{i,k+1|k}, e_{j,k+1|k})$ represents higher order terms. 
The estimation error after the update is:
\begin{align}
\scalebox{0.8}{$
