\begin{definition}
   Given a Hopf algebroid $\cL$ over $B$, a Hopf ideal $\cI$ of $\cL$ is  a  left $B^{e}$-submodule of $\cL$, such that it is
\begin{itemize}
    \item [(1)] $\cI$ is an ideal of $\cL$.
    \item[(2)] $\cI$ is a coideal of $\cL$. Namely, $\Delta(I)\subseteq I\diamond_{B}\cL+\cL\diamond_{B}\cI$.
    \item[(3)] For any $i\in\cI$,
    \[i_{+}\ot_{\overline{B}}i_{-}\in \cI\ot_{\overline{B}}\cL+\cL\ot_{\overline{B}}\cI,\quad  i_{[-]}\ot^{B}i_{[+]}\in \cI\ot^{B}\cL+\cL\ot^{B}\cI. \]
\end{itemize}
\end{definition}
\begin{proposition}\cite{Gho}\label{prop. quotient Hopf algebroids}
    If $\cL$ is a Hopf algebroid over $B$ and $\cI$ is a Hopf ideal of $\cL$ then $\cL/\cI$ is a Hopf algebroid over $B$.
\end{proposition}

