\section{Cotwist construction of Hopf algebroids}\label{seccotwist}

\subsection{Invertible left 2-cocycles on bialgebroids}\label{secBcotwist}

\begin{definition} \label{Lcotwist}
Let $\cL$ be a left $B$-bialgebroid. An \textup{left 2-cocycle} on
$\cL$ is an element $\Gamma\in {}\Hom_{\overline{B}-}(\cL\otimes_{\overline{B}}\cL, B)$, such that
\begin{itemize}
    \item [(1)]$\Gamma(X, \Gamma(Y\o, Z\o)Y\t Z\t)=\Gamma(\Gamma(X\o, Y\o)X\t Y\t, Z),$
    \item[(2)] $\Gamma(1_{\cL}, X)=\varepsilon(X)=\Gamma(X, 1_{\cL}),$
\end{itemize}
for all $X, Y, Z\in \cL$. The collection of such 2-cocycles of $\cL$ over $B$ will be denoted by $Z^{2}(\cL, B)$. A right 2-cocycle is an element $\Sigma\in \Hom_{B-}(\cL\otimes_{B}\cL, B)$, such that
\begin{itemize}
    \item [(1)]$\Sigma(X, \overline{\Sigma(Y\t, Z\t)}Y\o Z\o)=\Sigma(\overline{\Sigma(X\t, Y\t)}X\o Y\o, Z),$
    \item[(2)] $\Sigma(1_{\cL}, X)=\varepsilon(X)=\Sigma(X, 1_{\cL}).$
\end{itemize}
We call $\hat{\varepsilon}:=\varepsilon\circ m_{\cL}:\cL\ot_{\overline{B}}\cL\to B, X\ot Y\mapsto \varepsilon(XY)$ the trivial  left 2-cocycle on $\cL$.
\end{definition}



\begin{proposition}
    Given a left 2-cocycle $\Gamma$ on a left $B$-bialgebroid $\cL$, there is a $\Gamma$-twisted algebra structure on the underlying vector space $B$, with the product
    \[a\cdot_{\Gamma}b=\Gamma(a, b),\]
    for any $a,b\in B$. We denote the new algebra by $B^{\Gamma}$.
\end{proposition}
\begin{proof}
    We can see the twisted algebra is associative. Indeed,
    \begin{align*}
        (a\cdot_{\Gamma} b)\cdot_{\Gamma} c=\Gamma(\Gamma(a,b),c)=\Gamma(a,\Gamma(b,c))=a\cdot_{\Gamma}(b\cdot_{\Gamma}c),
    \end{align*}
    for any $a,b,c\in B$.
\end{proof}

\begin{proposition}\label{prop. twisted bimodule structures}
 If $M\in {}^{\cL}\mathcal{M}$ and $\Gamma$ is a left 2-cocycle on $\cL$ then $M$ is a $B^{\Gamma}$-bimodule with the bimodule structure given by
\begin{align}
a\cdot_{\Gamma}m=\Gamma(a,m\mo)m\z,\qquad m\cdot_{\Gamma}a=\Gamma(m\mo,a)m\z,
\end{align}
for any $a\in B$ and $m\in M$.
\end{proposition}
\begin{proof}
    For any $a,b\in B$ and $m\in M$,
    \begin{align*}
        (a\cdot_{\Gamma} b)\cdot_{\Gamma}m=\Gamma(\Gamma(a,b),m\mo)m\z=\Gamma(a, \Gamma(b, m\mt)m\mo)m\z=a\cdot_{\Gamma}(b\cdot_{\Gamma}m).
    \end{align*}
    As a result, $M$ is a left $B^{\Gamma}$-module. Similarly, $M$ is a right $B^{\Gamma}$-module. Moreover,
    \begin{align*}
        (a\cdot_{\Gamma} m)\cdot_{\Gamma}b=\Gamma(\Gamma(a,m\mt)m\mo,b)m\z=\Gamma(a, \Gamma(m\mt,b)m\mo)m\z= a\cdot_{\Gamma} (m\cdot_{\Gamma}b).
    \end{align*}
\end{proof}
\begin{remark}
     Given a left 2-cocycle $\Gamma$ on a left $B$-bialgebroid $\cL$, we can see
     \[\Gamma(X\cdot_{\Gamma}a, Y)=\Gamma(X,a\cdot_{\Gamma}Y).\]
\end{remark}
For any $N,M\in {}^{\cL}\CM$, we know $N\ot_{B} M$ is a left $\cL$-comodule with the codiagonal coaction
\[\delta(m\ot_{B}n)=m\mo\,n\mo\diamond_{B}m\z\ot_{B}n\z,\]
for any $m\in M$ and $n\in N$.

\begin{lemma}\label{lem. coherent map is BG-bilinear}
    Let $N,M\in {}^{\cL}\CM$. The map $\Gamma^{\#}:M\ot_{B^{\Gamma}}N\to M\ot_{B}N$ given by
    \begin{align*}
        \Gamma^{\#}(m\ot_{B^{\Gamma}}n)=\Gamma(m\mo, n\mo)m\z\ot_{B}n\z,
    \end{align*}
    is well defined. Moreover,
    \begin{align*}
        \Gamma^{\#}(b\cdot_{\Gamma}m\ot_{B^{\Gamma}}n)=b\cdot_{\Gamma}\Gamma^{\#}(m\ot_{B^{\Gamma}}n),\qquad \Gamma^{\#}(m\ot_{B^{\Gamma}}n\CG b)=\Gamma^{\#}(m\ot_{B^{\Gamma}}n)\CG b.
    \end{align*}
\end{lemma}
\begin{proof}
    To see  $\Gamma^{\#}$ is well defined, we only check $\Gamma^{\#}$ factors through $\ot_{B^{\Gamma}}$. On the one hand,
    \begin{align*}
        \Gamma^{\#}(m\cdot_{\Gamma}b\ot n)=\Gamma^{\#}(\Gamma(m\mo,b)\ot n)=\Gamma(\Gamma(m\mt,b)m\mo,n\mo)m\z\ot n\z
    \end{align*}.
    On the other hand,
    \begin{align*}
        \Gamma^{\#}(m\ot b\cdot_{\Gamma} n)=\Gamma^{\#}(m\ot \Gamma(b,n\mo)n\z)=\Gamma(m\mo, \Gamma(b, n\mt)n\mo)m\z\ot n\z,
    \end{align*}
    they are the same by the 2-cocycle condition. By the same method, we can show  $\Gamma^{\#}(b\cdot_{\Gamma}m\ot_{B^{\Gamma}}n)=b\cdot_{\Gamma}\Gamma^{\#}(m\ot_{B^{\Gamma}}n)$ and $\Gamma^{\#}(m\ot_{B^{\Gamma}}n\CG b)=\Gamma^{\#}(m\ot_{B^{\Gamma}}n)\CG b$.
\end{proof}
Sometimes we denote the map by $\GH_{M,N}$ in order to mention explicitly the corresponding modules $M$ and $N$. We say $\Gamma$ is invertible, if $\Gamma^{\#}$ is invertible for any left $\cL$-comodule $M,N$.
\begin{corollary}
    If $\Gamma$ is an invertible left 2-cocycle on a left $B$-bialgebroid then
    \begin{align*}
        \Gamma^{\#-1}(b\cdot_{\Gamma}(m\ot_{B}n ))=b\cdot_{\Gamma} \Gamma^{\#-1}(m\ot_{B}n),
    \end{align*}
    for any $m\in M\in{}^{\cL}\CM$ and $n\in N\in{}^{\cL}\CM$.
\end{corollary}
By the 2-cocycle condition of $\Gamma$, we can show
\begin{proposition}
    Let $N, M, P\in {}^{\cL}\CM$ and $\Gamma$ is a left 2-cocycle on $\cL$. Then
    \begin{align*}
        \GH_{N\ot_{B}M,P}\circ(\GH_{N,M}\ot_{\BG}\id_{P})=\GH_{N, M\ot_{B}P}\circ(\id_{N}\ot_{\BG}\GH_{M,P}):N\ot_{\BG}M\ot_{\BG}P\to N\ot_{B}M\ot_{B}P.
    \end{align*}
\end{proposition}


\subsection{Cotwist of Hopf algebroids}\label{secHcotwist}

\begin{lemma}
      If $\Gamma$ is a left 2-cocycle on a left $B$-Hopf algebroid $\cL$ then the underlying vector space equipped with the product
\begin{align}\label{twistprod}
    X\cdot_{\Gamma} Y:=\Gamma(X\o, Y\o)X\t{}_{+} Y\t{}_{+}\overline{\Gamma(Y\t{}_{-}, X\t{}_{-})},
\end{align}
is a $(B^{\Gamma})^e$-ring.
\end{lemma}
\begin{proof}
    The $B^{\Gamma}$-bimodule structure is given by $b\cdot_\Gamma X \cdot_\Gamma b'$,
    for any $b.b'\in B^\Gamma$ and $X\in \cL$. The $\overline{B^{\Gamma}}$-bimodule structure is given by $\overline{b}\cdot_\Gamma X \cdot_\Gamma \overline{b'}$. The associativity can be shown by the 2-cocycle condition of $\Gamma$ and (\ref{equ. inverse lamda 6}). Moreover, $b\cdot_\Gamma \overline{b'}=\overline{b}\cdot_\Gamma b$.

\end{proof}
It is clear that $\cL$ is a left  $\cL$-comodule of itself by its coproduct. Moreover, there is another left $\cL$-comodule structure given by
 \begin{align}\label{regular left comodule structure}
     \delta:\cL\to \cL\di_{B} \cL,\quad X\mapsto X_{-}\ot X_{+}, \qquad\forall X\in \CL,
 \end{align}
where the $B$-bimodule structure is given by $b.X.b':=\overline{b'}X\overline{b}$. We can see this defines a comodule structure by (\ref{equ. inverse lamda 6}) and (\ref{equ. inverse lamda 7}).

 \begin{lemma}
     If $\Gamma$ is an invertible left 2-cocycle on a left $B$-Hopf algebroid $\cL$ then $\cL^{\Gamma}$ is a $B^\Gamma$-coring, with $B^\Gamma$-bimodule structure:
     \[b.X.b'=b\cdot_\Gamma \overline{b'}\cdot_\Gamma X,\qquad\forall X\in \cL,\quad \forall b,b'\in B^\Gamma\]
     coproduct and counit
     \[\Delta^{\Gamma}(X)=\Gamma^{\#-1}(X\o\di_{B}X\t),\qquad \varepsilon^{\Gamma}(X)=\Gamma(X_{+}, X_{-}),\]
     where $\Gamma^{\#}:\cL^{\Gamma}\di_{B^{\Gamma}} \cL^{\Gamma}\to \cL\di_{B} \cL$  given by \begin{align*}
    \Gamma^{\#}(X\di_{B^\Gamma} Y)=X_{+}\overline{\Gamma(X_{-}, Y\o)}\di_{B}Y\t
\end{align*}
 is invertible as we consider the left term of $\cL\di_{B} \cL$ has the comodule stucture given by (\ref{regular left comodule structure}). We denote the image of $\Delta^\Gamma$ by $X\ro\di X\rt:=\Delta^\Gamma(X)$.
 \end{lemma}
\begin{proof}
    We can see $\varepsilon^{\Gamma}$ is $B^{\Gamma}$-bilinear,
    \begin{align*}
        \varepsilon^{\Gamma}(b\cdot_{\Gamma}X)=&\Gamma(\Gamma(b, X\o)X\t{}_{+}, X\t{}_{-})=\Gamma(\Gamma(b, X{}_{+}\o)X{}_{+}\t, X_{-})\\
        =&\Gamma(b, \Gamma(X_{+}, X_{-}))=b\cdot_{\Gamma} \varepsilon^{\Gamma}(X).
    \end{align*}
    Similarly, $\varepsilon^{\Gamma}$ is right $B^{\Gamma}$-linear. We can see the twisted coproduct is well defined.
    To see $\Delta^{\Gamma}$ is $B^{\Gamma}$-bilinear, we first observe that
    \begin{align*}
       \Gamma^{\#}((b\cdot_{\Gamma} X)\di_{\BG} Y)= b\cdot_{\Gamma}X_{+}\overline{\Gamma(X_{-}, Y\o)}\di_{B}Y\t,
    \end{align*}
    and
    \begin{align*}
        \Gamma^{\#}(X\di_{\BG} (\overline{b}\cdot_{\Gamma} Y))=X_{+}\overline{\Gamma(X_{-}, Y\o)}\di_{B}\overline{b}\cdot_{\Gamma}Y\t.
    \end{align*}
 So $\Delta^\Gamma$ is $B^{\Gamma}$-bilinear. Next, we can see the image of the coproduct belongs to Takeuchi product. Indeed, by denoting $X\ro\di X\rt:=\Delta^\Gamma(X)$, we can see on the one hand
 \begin{align*}
     \Gamma^{\#}(X\ro\CG \overline{b}\di_{\BG}X\rt)=&\Gamma^{\#}(X\ro{}_{+}\overline{\Gamma(b, X\ro{}_{-})}\di_{\BG}X\rt)\\
     =&X\ro{}_{++}\overline{\Gamma(\Gamma(b, X\ro{}_{-})X\ro{}_{+-}, X\rt\o)}\di_{B}X\rt\t\\
     %=&X\ro{}_{+}\overline{\Gamma(\Gamma(b, X\ro{}_{-}\o)X\ro{}_{-}\t, X\rt\o)}\di_{B}X\rt\t\\
     =&X\ro{}_{+}\overline{\Gamma(\Gamma(b, X\ro{}_{-}\o)X\ro{}_{-}\t, X\rt\o)}\di_{B}X\rt\t\\
     =&X\ro{}_{+}\overline{\Gamma(b, \Gamma(X\ro{}_{-}\o, X\rt\o)X\ro{}_{-}\t X\rt\t)}\di_{B}X\rt\th\\
     =&X\ro{}_{++}\overline{\Gamma(b, \Gamma(X\ro{}_{-}, X\rt\o)X\ro{}_{+-} X\rt\t)}\di_{B}X\rt\th\\
     =&X\o{}_{+}\overline{\Gamma(b, X\o{}_{-} X\t)}\di_{B}X\th\\
     =&X\o\overline{b}\di_{B}X\t,
 \end{align*}
 where the 6th step uses the fact that
 \begin{align}\label{equ. relation between old and new coproduct}
     X\o\di_{B}X\t=X\ro{}_{+}\overline{\Gamma(X\ro{}_{-}, X\rt\o)}\di_{\BG}X\rt\t.
 \end{align}
 On the other hand,
 \begin{align*}
      \Gamma^{\#}(X\ro\di_{\BG}X\rt\CG b)=&X\ro{}_{+}\overline{\Gamma(X\ro{}_{-}, \Gamma(X\rt\o,b)X\rt\t)}\di_{\BG}X\rt\th\\
      =&X\ro{}_{++}\overline{\Gamma(\Gamma(X\ro{}_{-}, X\rt\o) X\ro{}_{+-}X\rt\t,b)}\di_{\BG}X\rt\th\\
      =&X\o{}_{+}\overline{\Gamma(X\o{}_{-} X\t, b)}\di_{B}X\th\\
     =&X\o\overline{b}\di_{B}X\t.
 \end{align*}
 So the image of the twisted coproduct belongs to the Takeuchi product. Now, we can check
 \begin{align*}
     (\id\di_{\BG}\varepsilon^{\Gamma})\circ \Delta^{\Gamma}(X)=&\overline{\Gamma(X\rt{}_{+}, X\rt{}_{-})}\CG X\ro\\
     =& X\ro{}_{+}\overline{\Gamma(X\ro{}_{-}, \Gamma(X\rt{}_{+}, X\rt{}_{-}))}\\
     =& X\ro{}_{+}\overline{\Gamma(X\ro{}_{-}, \Gamma(X\rt{}_{+}\o, X\rt{}_{-}\o)X\rt{}_{+}\t X\rt{}_{-}\t)}\\
     =& X\ro{}_{++}\overline{\Gamma(\Gamma(X\ro{}_{-}, X\rt{}_{+}\o)X\ro{}_{+-}X\rt{}_{+}\t, X\rt{}_{-})}\\
     %=& X\ro{}_{++}\overline{\Gamma(\Gamma(X\ro{}_{-}, X\rt\o)X\ro{}_{+-}X\rt\t{}_{+}, X\rt\t{}_{-})}\\
     =& X\ro{}_{++}\overline{\Gamma(\Gamma(X\ro{}_{-}, X\rt\o)X\ro{}_{+-}X\rt\t{}_{+}, X\rt\t{}_{-})}\\
     =& X\o{}_{+}\overline{\Gamma(X\o{}_{-}X\t{}_{+}, X\t{}_{-})}\\
     =& X_{+}\o{}_{+}\overline{\Gamma(X_{+}\o{}_{-}X_{+}\t{}, X{}_{-})}\\
     =& X_{+}\overline{ \varepsilon(X{}_{-})}\\
     =&X.
 \end{align*}
 By the similar method, we can show $(\id\di_{\BG}\varepsilon^{\Gamma})\circ \Delta^{\Gamma}=\id$. In order to show the coassociativity, we first observe that
 \[(\Delta\di_{\BG} \id)\circ \GH^{-1}=(\id\di_{\BG}\GH^{-1})\circ (\Delta\di_{B} \id):\cL\di_{B}\cL\to\cL\di_{B}\cL\di_{\BG}\cL,\]
 as $\Delta$ is $\BG$-bilinear, the formula is well defined. Moreover, to show the above formula, it is equivalent to show
 \[(\Delta\di_{B} \id)\circ \GH=(\id\di_{B}\GH)\circ (\Delta\di_{\BG} \id):\cL\di_{\BG}\cL\to \cL\di_{B}\cL\di_{B}\cL. \]
 We can see,
 \begin{align*}
     (\Delta\di_{B} \id)\circ \GH(X\ot Y)=&X_{+}\o\ot X_{+}\t\overline{\Gamma(X_{-}, Y\o)}\ot Y\t\\
     =&X\o\ot X\t{}_{+}\overline{\Gamma(X\t{}_{-}, Y\o)}\ot Y\t\\
     =&(\id\di_{B}\GH)\circ (\Delta\di_{\BG} \id)(X\ot Y).
 \end{align*}
 Similarly, we can show
  \[(\id\di_{\BG} \Delta)\circ \GH^{-1}=(\GH^{-1}\di_{\BG}\id)\circ (\id\di_{B} \Delta):\cL\di_{B}\cL\to\cL\di_{\BG}\cL\di_{B}\cL.\]
  Moreover, we can show
 \[(\GH\di_{\BG}\id)\circ(\id\di_{\BG}\GH)=(\id\di_{\BG}\GH)\circ(\GH\di_{\BG}\id):\cL\di_{\BG}\cL\di_{\BG}\cL\to \cL\di_{B}\cL\di_{B}\cL.\]
 Indeed,
 \begin{align*}
     (\GH\di_{\BG}\id)\circ(\id\di_{\BG}\GH)(X\ot Y\ot Z)=&(\GH\di_{\BG}\id)(X\ot Y_{+}\overline{\Gamma(Y_{-}, Z\o)}\di_{B}Z\t)\\
     =&X_{+}\overline{\Gamma(X_{-}, Y_{+}\o)}\di_{B}Y_{+}\t\overline{\Gamma(Y_{-}, Z\o)}\di_{B}Z\t\\
     %=&X_{+}\overline{\Gamma(X_{-}, Y\o)}\di_{B}Y\t{}_{+}\overline{\Gamma(Y\t{}_{-}, Z\o)}\di_{B}Z\t\\
     =&X_{+}\overline{\Gamma(X_{-}, Y\o)}\di_{B}Y\t{}_{+}\overline{\Gamma(Y\t{}_{-}, Z\o)}\di_{B}Z\t\\
     =&(\id\di_{\BG}\GH)(X_{+}\overline{\Gamma(X_{-}, Y\o)}\di_{B}Y\t\ot Z)\\
     =&(\id\di_{\BG}\GH)\circ(\GH\di_{\BG}\id)(X\ot Y\ot Z).
 \end{align*}
 Therefore, we can show
 \begin{align*}
      (\DG\ot \id)\circ \DG=&(\GH^{-1}\ot \id)\circ(\Delta\ot\id )\circ \GH^{-1}\circ \Delta\\
      %=&(\GH^{-1}\ot \id)\circ(\Delta\ot\id )\circ \GH^{-1}\circ \Delta\\
      =&(\GH^{-1}\ot \id)\circ(\id\ot \GH^{-1})\circ(\Delta\ot\id )\circ \Delta\\
      =&(\id\ot \GH^{-1})\circ(\GH^{-1}\ot \id)\circ(\id\ot\Delta )\circ \Delta\\
      =&(\id\ot \GH^{-1})\circ(\id\ot\Delta )\circ \GH^{-1}\circ \Delta\\
      =&(\id\ot \DG)\circ \DG.
 \end{align*}
\end{proof}


\begin{theorem}\label{thm. twisted Hopf algebroid}
    Let $\Gamma$ be an invertible left 2-cocycle on a left $B$-Hopf algebroid $\CL$. Then $\cL^\Gamma$ is a left Hopf algebroid over $\BG$ with the $\BG^e$-ring structure and $\BG$-coring structure given above.
\end{theorem}
\begin{proof}
    We first show $\varepsilon^\Gamma$ is a left character.
   \begin{align*}
      \varepsilon^\Gamma(X\CG Y)=&\Gamma(\Gamma(X\o, Y\o)X\t{}_{++}Y\t{}_{++}, \Gamma(Y\t{}_{-}, X\t{}_{-})Y\t{}_{+-}X\t{}_{+-}) \\
      =&\Gamma(\Gamma(X\o, Y\o)X\t{}_{+}Y\t{}_{+}, \Gamma(Y\t{}_{-}\o, X\t{}_{-}\o)Y\t{}_{-}\t X\t{}_{-}\t) \\
      =&\Gamma(\Gamma(\Gamma(X\o, Y\o)X\t{}_{+}\o Y\t{}_{+}\o,Y\t{}_{-}\o) X\t{}_{+}\t Y\t{}_{+}\t Y\t{}_{-}\t, X\t{}_{-}) \\
      =&\Gamma(\Gamma(\Gamma(X\o, Y\o)X\t{}_{+}\o Y\t{}_{+},Y\t{}_{-}) X\t{}_{+}\t , X\t{}_{-}) \\
      =&\Gamma(\Gamma(\Gamma(X\o, Y\o)X\t Y\t{}_{+},Y\t{}_{-}) X\th{}_{+} , X\th{}_{-}) \\
      =&\Gamma(\Gamma(\Gamma(X\o, Y_{+}\o)X\t Y{}_{+}\t,Y{}_{-}) X\th{}_{+} , X\th{}_{-})\\
      =&\Gamma(\Gamma(X\o, \Gamma(Y_{+}\o, Y{}_{-}\o)Y_{+}\t Y{}_{-}\t) X\t{}_{+} , X\t{}_{-})\\
      =&\Gamma(\Gamma(X\o, \Gamma(Y_{+}, Y{}_{-})) X\t{}_{+} , X\t{}_{-})\\
      =&\varepsilon^\Gamma(X\CG \varepsilon^\Gamma(Y)).
   \end{align*}
   We can also see
   \begin{align*}
       \varepsilon^\Gamma(X\CG \overline{b})=&\Gamma(X_{++}, \Gamma(b, X_{-})X_{+-})=\Gamma(X_{+}, \Gamma(b, X_{-}\o)X_{+}\t)=\Gamma(\Gamma(X_{+}\o,b)X_{+}\t, X_{-})\\
       =&\Gamma(\Gamma(X\o,b)X\t{}_{+}, X\t{}_{-})= \varepsilon^\Gamma(X\CG b).
   \end{align*}
   We can also check that the coproduct is an algebra map. Indeed,
   \begin{align*}
       \GH(&X\ro\CG Y\ro\di_{\BG} X\rt\CG Y\rt)\\
       =&\Gamma(X\ro\o, Y\ro\o)X\ro\t{}_{++}Y\ro\t{}_{++}\\
       &\overline{\Gamma(\Gamma(Y\ro\t{}_{-}, X\ro\t{}_{-})Y\ro\t{}_{+-}X\ro\t{}_{+-}, \Gamma(X\rt\o, Y\rt\o)X\rt\t Y\rt\t)}\\
       &\di_{B}X\rt\th{}_{+} Y\rt\th{}_{+}\overline{\Gamma(Y\rt\th{}_{-}, X\rt\th{}_{-})}\\
       =&\Gamma(X\ro\o, Y\ro\o)X\ro\t{}_{+}Y\ro\t{}_{+}\\
       &\overline{\Gamma(\Gamma(Y\ro\t{}_{-}\o, X\ro\t{}_{-}\o)Y\ro\t{}_{-}\t X\ro\t{}_{-}\t, \Gamma(X\rt\o, Y\rt\o)X\rt\t Y\rt\t)}\\
       &\di_{B}X\rt\th{}_{+} Y\rt\th{}_{+}\overline{\Gamma(Y\rt\th{}_{-}, X\rt\th{}_{-})}\\
       =&\Gamma(X\ro\o, Y\ro\o)X\ro\t{}_{+}Y\ro\t{}_{+}\\
       &\overline{\Gamma(\Gamma(\Gamma(Y\ro\t{}_{-}\o, X\ro\t{}_{-}\o)Y\ro\t{}_{-}\t X\ro\t{}_{-}\t, X\rt\o)Y\ro\t{}_{-}\th X\ro\t{}_{-}\th X\rt\t,  Y\rt\o)}\\
          &\di_{B}X\rt\th{}_{+} Y\rt\t{}_{+}\overline{\Gamma(Y\rt\t{}_{-}, X\rt\th{}_{-})}\\
          =&\Gamma(X\ro\o, Y\ro\o)X\ro\t{}_{+}Y\ro\t{}_{+}\\
       &\overline{\Gamma(\Gamma(Y\ro\t{}_{-}\o, \Gamma(X\ro\t{}_{-}\o, X\rt\o) X\ro\t{}_{-}\t X\rt\t)Y\ro\t{}_{-}\t X\ro\t{}_{-}\th X\rt\th,  Y\rt\o)}\\
          &\di_{B}X\rt\fo{}_{+} Y\rt\t{}_{+}\overline{\Gamma(Y\rt\t{}_{-}, X\rt\fo{}_{-})}\\
           =&\Gamma(X\ro\o, Y\ro\o)X\ro\t{}_{++}Y\ro\t{}_{+}\\
       &\overline{\Gamma(\Gamma(Y\ro\t{}_{-}\o, \Gamma(X\ro\t{}_{-}, X\rt\o) X\ro\t{}_{+-}\o X\rt\t)Y\ro\t{}_{-}\t X\ro\t{}_{+-}\t X\rt\th,  Y\rt\o)}\\
          &\di_{B}X\rt\fo{}_{+} Y\rt\t{}_{+}\overline{\Gamma(Y\rt\t{}_{-}, X\rt\fo{}_{-})}\\
          =&\Gamma(X\ro{}_{+}\o, Y\ro\o)X\ro{}_{+}\t{}_{+}Y\ro\t{}_{+}\\
       &\overline{\Gamma(\Gamma(Y\ro\t{}_{-}\o, \Gamma(X\ro{}_{-}, X\rt\o) X\ro{}_{+}\t{}_{-}\o X\rt\t)Y\ro\t{}_{-}\t X\ro{}_{+}\t{}_{-}\t X\rt\th,  Y\rt\o)}\\
          &\di_{B}X\rt\fo{}_{+} Y\rt\t{}_{+}\overline{\Gamma(Y\rt\t{}_{-}, X\rt\fo{}_{-})}\\
           =&\Gamma(X\o\o, Y\ro\o)X\o\t{}_{+}Y\ro\t{}_{+}\\
       &\overline{\Gamma(\Gamma(Y\ro\t{}_{-}\o,  X\o\t{}_{-}\o X\t)Y\ro\t{}_{-}\t X\o\t{}_{-}\t X\th,  Y\rt\o)}\\
          &\di_{B}X\fo{}_{+} Y\rt\t{}_{+}\overline{\Gamma(Y\rt\t{}_{-}, X\fo{}_{-})}\\
           =&\Gamma(X\o, Y\ro\o)X\t Y\ro\t{}_{+}\overline{\Gamma(Y\ro\t{}_{-},  Y\rt\o)}\di_{B}X\th{}_{+} Y\rt\t{}_{+}\overline{\Gamma(Y\rt\t{}_{-}, X\th{}_{-})}\\
           =&\Gamma(X\o, Y\ro{}_{+}\o)X\t Y\ro{}_{+}\t\overline{\Gamma(Y\ro{}_{-},  Y\rt\o)}\di_{B}X\th{}_{+} Y\rt\t{}_{+}\overline{\Gamma(Y\rt\t{}_{-}, X\th{}_{-})}\\
           =&\Gamma(X\o, Y\o)X\t Y\t\di_{B}X\th{}_{+} Y\th{}_{+}\overline{\Gamma(Y\th{}_{-}, X\th{}_{-})}\\
           =&\Delta(X\CG Y)=\GH\circ \Delta^{\Gamma}(X\CG Y).
   \end{align*}
   Finally, we show $\cL^\Gamma$ is a left Hopf algebroid. It is sufficient to show the following diagram commute:
    \[
\begin{tikzcd}
  &\cL^{\Gamma}\ot_{\overline{\BG}}\cL^{\Gamma} \arrow[d, "\GH"] \arrow[r, "\lambda^{\Gamma}"] & \cL^{\Gamma}\di_{\BG}\cL^{\Gamma} \arrow[d, "\GH"] &\\
   & \cL\ot_{\overline{B}}\cL   \arrow[r, "\lambda"] & \cL\di_{B}\cL, &
\end{tikzcd}
\]
where the left $\GH$  given by
\[\GH(X\ot_{\overline{\BG}} Y)=X_{+}\ot_{\overline{B}}Y_{+}\overline{\Gamma(Y_{-}, X_{-})}\]
is invertible as we consider both $\cL$ have the left $\cL$-comodule structure given by (\ref{regular left comodule structure}). We can see on the one hand,
\begin{align*}
    \lambda\circ \GH(X\ot_{\overline{\BG}} Y)=X_{+}\o\di_{B}X_{+}\t Y_{+}\overline{\Gamma(Y_{-}, X_{-})}.
\end{align*}
On the other hand,
\begin{align*}
    \GH\circ& \lambda^{\Gamma}(X\ot_{\overline{\BG}} Y)\\
    =&\GH(X\ro\diamond_{\BG} \Gamma(X\rt\o, Y\o)X\rt\t{}_{+}Y\t{}_{+}\overline{\Gamma(Y\t{}_{-}, X\rt\t{}_{-})}\,)\\
    =&X\ro{}_{+}\overline{\Gamma(X\ro{}_{-}, \Gamma(X\rt\o, Y\o)X\rt\t Y\t)}\di_{B}X\rt\th{}_{+}Y\th{}_{+}\overline{\Gamma(Y\th{}_{-}, X\rt\th{}_{-})}\\
    =&X\ro{}_{+}\overline{\Gamma(\Gamma(X\ro{}_{-}\o, X\rt\o)X\ro{}_{-}\t X\rt\t,  Y\o)}\di_{B}X\rt\th{}_{+}Y\t{}_{+}\overline{\Gamma(Y\t{}_{-}, X\rt\th{}_{-})}\\
    =&X\o{}_{+}\overline{\Gamma(X\o{}_{-} X\t,  Y\o)}\di_{B}X\th{}_{+}Y\t{}_{+}\overline{\Gamma(Y\t{}_{-}, X\th{}_{-})}\\
    =&X\o\di_{B}X\t{}_{+}Y{}_{+}\overline{\Gamma(Y{}_{-}, X\t{}_{-})}.
\end{align*}
\end{proof}
\begin{remark}\label{remHopf}
 For a Hopf algebra $H$ with a convolution invertible left 2-cocycle $\Gamma:H\ot H\to k$ in the usual sense\cite{Ma:book}, we obtain a new Hopf algebra $H^\Gamma$. For any $h\in H$, $h_{+}\ot h_{-}=h\o\ot S(h\t)$, the product is
\[h\CG g=\Gamma(h\o, g\o)h\t g\t \Gamma(S(g\th), S(h\th)),\]
the coproduct and counit are
\[\Delta^{\Gamma}(h)=h\o\Gamma^{-1}(S(h\t), h\th)\ot h\fo,\qquad \varepsilon^{\Gamma}(h)=\Gamma(h\o, S(h\t)).\]
Indeed, we can check that
\begin{align*}
    \GH(h\o\Gamma^{-1}(S(h\t), h\th)\ot h\fo)=&h\o \Gamma^{-1}(S(h\th), h\fo)\Gamma(S(h\t), h\fiv)\ot h\si\\
    =&h\o\ot h\t.
\end{align*}
It is also not hard to see that for any left $H$-comodule $M$ and $N$. $\GH:M\ot N\to M\ot N$ is invertible with inverse given by
\[\GH^{-1}(m\ot n)=\Gamma^{-1}(m\mo, n\mo)m\z\ot n\z,\]
for any $m\in M$ and $n\in N$.


Moreover,   $H^{\Gamma}$ is isomorphic to the usual Drinfeld cotwist of $H$  (denoted here by $H^{\Gamma}_{D}$) by
\[ \psi:H^{\Gamma}\to H^{\Gamma}_{D},\quad \psi(h)=h\o\Gamma(h\t, S(h\th)),\]
    for any $h\in H$. To see this, recall that  $H^{\Gamma}_{D}$ has the same coalgebra structure as $H$ and the product\cite{Ma:book}
    \[h\cdot_{D}g=\Gamma(h\o, g\o)h\t\,g\t\,\Gamma^{-1}(h\th, g\th),\]
    for any $h,g\in H$. We firstly show $\psi$ is a coalgebra map. Indeed,
    \begin{align*}
        \varepsilon_{D}^{\Gamma}\circ \psi(h)=\Gamma(h\o, S(h\t))=\varepsilon^{\Gamma}(h).
    \end{align*}
    Also,
    \begin{align*}
        (\psi\ot \psi)\circ \Delta^{\Gamma}(h)=&(\psi\ot \psi)(h\o\Gamma(h\t, S(h\th)))\\
        =&h\o\Gamma(h\t, S(h\th))\Gamma^{-1}(S(h\fo),h\fiv)\ot h\si \Gamma(h\sev, S(h\eig))\\
        =&h\o\ot h\t \Gamma(h\th, S(h\fo))\\
        =&\Delta_{D}^{\Gamma}\circ \psi(h),
    \end{align*}
    where the 3rd step uses the fact that $\Gamma(h\o, S(h\t))\Gamma^{-1}(S(h\th),h\fo)=\varepsilon(h)$.
    Next, we are going to show $\psi$ is an algebra map.
    \begin{align*}
        \psi(h\CG\,g)=&\psi(\Gamma(h\o,g\o)h\t\,g\t\,\Gamma(S(g\th),S(h\th)))\\
        =&\Gamma(h\o,g\o)h\t\,g\t\,\,\Gamma(h\th\,g\th,S(g\fo)\,S(h\fo))\,\Gamma(S(g\fiv),S(h\fiv))\\
        =&\Gamma(h\o,g\o)h\t\,g\t\,\Gamma^{-1}(h\th,g\th)\Gamma(h\fo, S(h\fiv))\,\Gamma(g\fo, S(g\fiv))\\
        &\qquad\Gamma^{-1}(S(g\si),S(h\si))\Gamma(S(g\sev),S(h\sev))\\
        =&\Gamma(h\o,g\o)h\t\,g\t\,\Gamma^{-1}(h\th,g\th)\Gamma(h\fo, S(h\fiv))\,\Gamma(g\fo, S(g\fiv))\\
        =&(h\o\Gamma(h\t, S(h\th)))\cdot_{D}(g\o\Gamma(g\t, S(g\th)))\\
        =&\psi(h)\cdot_{D}\psi(g),
    \end{align*}
   where the 3rd step uses the fact that
   \[\Gamma(h\o\,g\o, S(h\t)\,S(g\t))=\Gamma^{-1}(h\o,g\o)\Gamma(h\t, S(h\th))\,\Gamma(g\t, S(g\th))\,\Gamma^{-1}(S(g\fo), S(h\fo)),\]
   which is a result of Lemma 2.1 in \cite{HM22}.
    \end{remark}










\begin{lemma}\label{lem. comodule equ}
    Let $\cL$ be a left $B$-Hopf algebroid and $\Gamma$ be an invertible left 2-cocycle on $\cL$. Then $({}^{\cL}\CM,\ot_{B})\cong ({}^{\cL^{\Gamma}}\CM,\ot_{\BG})$ as monoidal categories.
\end{lemma}
\begin{proof}
    Given a left $\cL$-comodule $M$, we know it is a $\BG$-bimodule by Proposition \ref{prop. twisted bimodule structures}. Moreover, $M$ is a left $\cL^{\Gamma}$-comodule with the coaction given by
    \[\delta^{\cL^{\Gamma}}:=\GH{}^{-1}\circ \delta^{\cL}:M\to \cL^{\Gamma}\diamond_{\BG}M.\]
    By a similar proof for $\Delta^{\Gamma}$ and $\varepsilon^{\Gamma}$ we know this is a well defined coaction. Denote $\Gamma(M)$ be the $\cL^{\Gamma}$-comodule with the twisted coaction. We define $m\rmo\ot m\rz:=\delta^{\cL^{\Gamma}}(m)$ for any $m\in M$.
    Let $N$ be any left $\cL$-comodule, we know $\Gamma(M)\ot_{\BG}\Gamma(N)$ is also a left $\cL^{\Gamma}$-comodule with codiaginal $\cL^{\Gamma}$-coaction. We can see
    \[\GH_{M,N}:\Gamma(M)\ot_{\BG}\Gamma(N)\to \Gamma(M\ot_{B}N),\qquad m\ot n\mapsto \Gamma(m\mo, n\mo)m\z\ot n\z,\]
    is the coherent map for any $M, N\in {}^{\cL}\CM$. Indeed, It is $\BG$-bilinear by Lemma \ref{lem. coherent map is BG-bilinear}. By a similar proof of showing the twisted coproduct $\Delta^{\Gamma}$ is an algebra map for the twisted product, we can  check $\GH_{M,N}$ is left $\cL^{\Gamma}$-colinear. Moreover, $\GH$ satisfies the coherent condition and is invertible since $\Gamma$ is an invertible 2-cocycle.
\end{proof}




\begin{remark}
 Similarly, for a right 2-cocycle $\Sigma$ on an anti-left Hopf algebroid $\cL$, we can also cotwist $\cL$ to a new anti-left Hopf algebroid over a deformed base algebra. With the twisted product given by
\[X\cdot_{\Sigma}Y=\overline{\Sigma(X\t, Y\t)}X\o{}_{[+]}Y_{[+]}\Sigma(Y_{[-]}X_{[-]}).\]
\end{remark}




\begin{proposition}\label{prop. cocomute coaction}
     Let $\cL$ be a left $B$-Hopf algebroid and $\Gamma$ be an invertible left 2-cocycle on $\cL$ and denote $X_{\p}\ot X_{\m}=\lambda^{\Gamma}{}^{-1}(X\diamond_{\BG}1)$. Then we have
    \begin{itemize}
        \item [(1)] $\Delta$ is $(\BG)^{e}$-bilinear and $\DG$ is  $B^e$-bilinear. Also, we have
