              &(a\Bar{a'}Xb\Bar{b'})_{\p}\ot_{\BB}(a\Bar{a'}Xb\Bar{b'})_{\m}=aX_{\p}b\ot_{\BB}b'X_{\m}a'.
        \end{align*}
        Moreover, the coproducts  cocommute:
        \[(\id\ot\Delta^{\Gamma})\circ\Delta=(\Delta\ot\id)\circ\Delta^{{\Gamma}},\qquad(\id\ot\Delta)\circ\Delta^{\Gamma}=(\Delta^{\Gamma}\ot\id)\circ\Delta.\]
        \item[(2)] For any $X\in \cL$, we have
