\subsection{Groupoid structure on 2-cocycles of Hopf algebroids}\label{secgroupoid}

Given a Hopf algebra $H$ and an invertible left 2-cocycle $\gamma$ on $H$, by applying the Drinfeld cotwist on $H$, we get another Hopf algebra $H^{\gamma}$ with cotwisted product, see\cite{Ma:book}. We know $\gamma^{-1}$  is a left 2-cocycle on $H^{\gamma}$. By applying the Drinfeld cotwist of $\gamma^{-1}$ on $H^{\gamma}$,  we can cotwist $H^{\gamma}$ back to the original $H$. Moreover, if $\sigma$ is an invertible left 2-cocycle on $H^{\gamma}$, we can cotwist $H^{\gamma}$ to a new Hopf algebra $(H^{\gamma})^{\sigma}$ which is equal to $H^{\sigma\ast \gamma}$, where $\sigma\ast \gamma$ is an invertible left 2-cocycle on $H$ given by
\[\sigma\ast \gamma(h,g)=\sigma(h\o, g\o)\gamma(h\t,g\t),\]
for any $h,g\in H$. Hence,  the collection of 2-cocycles and the cotwisted Hopf algebras can be viewed as a groupoid. The source of $\gamma$ is $H$ and the target of $\gamma$ is $H^{\gamma}$. The product of the 2-cocycles is given by convolution product as above. 

Motivated by this observation for Hopf algebras, is there a groupoid structure on the collections of Hopf algebroids? This is clear if the 2-cocycle is also left $B$-linear as studied in \cite{HM23}, as we can define the convolution product. However, we can't define the convolution product of two 2-cocycles in Definition \ref{Lcotwist} because it is only left $\overline{B}$-linear. In this subsection, we can show that there is an analog groupoid structure on Hopf algebroids and their 2-cocycles, however, the product is no longer the convolution product. We will see if $\Gamma$ is an invertible left 2-cocycle on a left Hopf algebroid $\cL$ then we can twist $\cL^{\Gamma}$ back to $\cL$.

\begin{proposition}\label{prop. left inverse}
      Let $\cL$ be a left Hopf algebroid over $B$ and $\Gamma$ is an invertible left 2-cocycle on $\cL$. Then $\Sigma:\cL^{\Gamma}\ot_{\BG}\cL^{\Gamma}\to \BG$ given by
    \[\Sigma(X, Y)=\Gamma(X_{+}Y_{+}, \Gamma(Y_{-}\o, X_{-}\o)Y_{-}\t\, X_{-}\t)\]
    is a left $\overline{\BG}$-linear map, such that
    \[\Gamma(\Sigma(X\ro, Y\ro), \Gamma(X\rt\o\, ,Y\rt\o)X\rt\t\, Y\rt\t)=\varepsilon(XY),\]
    for any $X, Y\in\cL$.
\end{proposition}
\begin{proof}
     First, it is easy to see $\Sigma$ factors through all the balanced tensor products. We can also see that $\Sigma$ is left $\overline{\BG}$-linear. Indeed,
    \begin{align*}
       \Sigma(\overline{b}\CG X, Y)=&\Sigma(X_{+}\overline{\Gamma(X_{-}, b)}, Y)\\
       =&\Gamma(X_{++}Y_{+}, \Gamma(Y_{-}\o, \Gamma(X_{-}, b)\,X_{+-}\o)Y_{-}\t\, X_{+-}\t)\\
       =&\Gamma(X_{+}Y_{+}, \Gamma(Y_{-}\o, \Gamma(X_{-}\o, b)\,X_{-}\t)Y_{-}\t\, X_{-}\th)\\
       =&\Gamma(X_{+}Y_{+}, \Gamma(\Gamma(Y_{-}\o,X_{-}\o) X_{-}\t\, Y_{-}\t, b)Y_{-}\th\, X_{-}\th)\\
       =&\Gamma(\Gamma(X_{+}Y_{+}, \Gamma(Y_{-}\o, X_{-}\o)Y_{-}\t\, X_{-}\t), b)\\
       =&\Sigma(X, Y)\CG b.
    \end{align*}
    By the similar method, we can also see $\Sigma(X\CG\overline{b}, Y)=\Sigma(X,\overline{b}\CG Y)$.
    Moreover, we can see
    \begin{align*}
        b\CG (\Gamma(X\o, Y\o)X\t\, Y\t)=&\Gamma(b, \Gamma(X\o, Y\o)X\t\, Y\t)X\th\, Y\th\\
        =&\Gamma(b\CG X\o, Y\o)X\t Y\t
    \end{align*}
    for any $b\in B$, $X,Y\in \cL$.
    Therefore, the second equality is also well defined. Now, let's show the second equality:
    \begin{align*}
        \Gamma(&\Sigma(X\ro, Y\ro), \Gamma(X\rt\o\, Y\rt\o)X\rt\t\, Y\rt\t)\\
        =&\Gamma(\Gamma(X\ro{}_{+}Y\ro{}_{+}, \Gamma(Y\ro{}_{-}\o, X\ro{}_{-}\o)Y\ro{}_{-}\t\, X\ro{}_{-}\t), \Gamma(X\rt\o, Y\rt\o)X\rt\t\,Y\rt\t)\\
        =&\Gamma(\Gamma(X\ro{}_{++}\o\,Y\ro{}_{++}\o\,, \Gamma(Y\ro{}_{-}, X\ro{}_{-})Y\ro{}_{+-}\o\, X\ro{}_{+-}\o)X\ro{}_{++}\t\,Y\ro{}_{++}\t\,Y\ro{}_{+-}\t\, X\ro{}_{+-}\t,\\
        \Gamma&(X\rt\o, Y\rt\o)X\rt\t\,Y\rt\t)\\
        =&\Gamma(X\ro{}_{++}\,Y\ro{}_{++}\,,\\
        \Gamma&(\Gamma(Y\ro{}_{-}, X\ro{}_{-})Y\ro{}_{+-}\o\,X\ro{}_{+-}\o,\Gamma(X\rt\o, Y\rt\o)X\rt\t\,Y\rt\t)Y\ro{}_{+-}\t\,X\ro{}_{+-}\t\,X\rt\th\,Y\rt\th),\\
        =&\Gamma(X\ro{}_{+}\,Y\ro{}_{+}\,,\\
        \Gamma&(\Gamma(Y\ro{}_{-}\o, X\ro{}_{-}\o)Y\ro{}_{-}\t\,X\ro{}_{-}\t,\Gamma(X\rt\o, Y\rt\o)X\rt\t\,Y\rt\t)Y\ro{}_{-}\th\,X\ro{}_{-}\th\,X\rt\th\,Y\rt\th),\\
        =&\Gamma(X\ro{}_{+}\,Y\ro{}_{+}\,,\\
        \Gamma&(Y\ro{}_{-}\o,\Gamma( X\ro{}_{-}\o, \Gamma(X\rt\o, Y\rt\o)X\rt\t\,Y\rt\t)\,X\ro{}_{-}\t\,X\rt\th\,Y\rt\th)Y\ro{}_{-}\t\,X\ro{}_{-}\th\,X\rt\fo\,Y\rt\fo)\\
        =&\Gamma(X\ro{}_{+}\,Y\ro{}_{+}\,,\\
        \Gamma&(Y\ro{}_{-}\o,\Gamma( \Gamma(X\ro{}_{-}\o, X\rt\o)X\ro{}_{-}\t\,X\rt\t,Y\rt\o)\,X\ro{}_{-}\th\,X\rt\th\,Y\rt\t)Y\ro{}_{-}\t\,X\ro{}_{-}\fo\,X\rt\fo\,Y\rt\th)\\
        =&\Gamma(X\ro{}_{++}\,Y\ro{}_{+}\,,\\
        \Gamma&(Y\ro{}_{-}\o,\Gamma( \Gamma(X\ro{}_{-}, X\rt\o)X\ro{}_{+-}\o\,X\rt\t,Y\rt\o)\,X\ro{}_{+-}\t\,X\rt\th\,Y\rt\t)Y\ro{}_{-}\t\,X\ro{}_{+-}\th\,X\rt\fo\,Y\rt\th)\\
        =&\Gamma(X\o{}_{+}\,Y\ro{}_{+}\,,
        \Gamma(Y\ro{}_{-}\o,\Gamma( X\o{}_{-}\o\,X\t,Y\rt\o)\,X\o{}_{-}\t\,X\th\,Y\rt\t)Y\ro{}_{-}\t\,X\o{}_{-}\th\,X\fo\,Y\rt\th)\\
        =&\Gamma(X\,Y\ro{}_{+}\,,
        \Gamma(Y\ro{}_{-}\o,\Gamma( 1,Y\rt\o)\,Y\rt\t)Y\ro{}_{-}\t\,Y\rt\th)\\
         =&\Gamma(X\,Y\ro{}_{+}\,,\Gamma(Y\ro{}_{-}\o,\,Y\rt\o)Y\ro{}_{-}\t\,Y\rt\t)\\
        =&\Gamma(X\,Y\o{}_{+}\,,     Y\o{}_{-}\,Y\t)\\
        =&\Gamma(X\,Y\,,     1)\\
        =&\varepsilon(XY).
    \end{align*}
\end{proof}
\begin{corollary}\label{cor. comodule twist back}
    Let $\cL$ be a left Hopf algebroid over $B$, $\Gamma$ is an invertible left 2-cocycle on $\cL$, and $\Sigma$ is defined above. Then for any $M,N\in {}^{\cL}\CM$, we have
    \[\Gamma(\Sigma(m\rmo, n\rmo),\Gamma(m\rz\mt, n\rz\mt)m\rz\mo n\rz\mo)m\rz\z\ot_{B} n\rz\z=m\ot_{B}n,\]
    for any $m\in M$ and $n\in N$. Moreover, we have
    \[\Sigma(X\ro, Y\ro)\CG\,X\rt\CG\,Y\rt =X_{+}Y_{+}\overline{\Gamma(Y_{-},X_{-})},\]
    for any $X, Y\in\CL$. We also have
    \[X_{\p +}\ot Y_{\p +}\,\overline{\Gamma(\Sigma(Y_{\m}, X_{\m}), \Gamma(Y_{\p -}\o, X_{\p -}\o)Y_{\p -}\t\, X_{\p -}\t)}=X\ot Y.\]
\end{corollary}
\begin{proof}
    By Proposition \ref{prop. left inverse}, we have
    \begin{align*}
        \Gamma(\Sigma(&m\rmo, n\rmo),\Gamma(m\rz\mt, n\rz\mt)m\rz\mo n\rz\mo)m\rz\z\ot_{B} n\rz\z\\
        =&\Gamma(\Sigma(m\mo\ro, n\mo\ro),\Gamma(m\mo\rt\o, n\mo\rt\o)m\mo\rt\t n\mo\rt\t)m\z\ot_{B} n\z\\
        =&\varepsilon(m\mo\,n\mo)m\z\ot_{B} n\z\\
        =&m\ot_{B}n.
    \end{align*}
     As a special case, we have
    \[\Gamma(\Sigma(X\ro, Y\ro),\Gamma(X\rt\o, Y\rt\o)X\rt\t\, Y\rt\t)X\rt\th\, Y\rt\th=XY,\]
    for any $X, Y\in\CL$. Therefore,
    \begin{align*}
        \Sigma(&X\ro, Y\ro)\CG\,X\rt\CG\,Y\t=\Sigma(X\ro, Y\ro)\CG\,(X\rt\CG\,Y\rt)\\
        =&\Gamma(\Sigma(X\ro, Y\ro),\Gamma(X\rt\o, Y\rt\o)X\rt\t{}_{+}\o\, Y\rt\t{}_{+}\o)\\
        &X\rt\t{}_{+}\t\, Y\rt\t{}_{+}\t\,\overline{\Gamma(Y\rt\t{}_{-},X\rt\t{}_{-})}\\
         =&\Gamma(\Sigma(X\ro, Y\ro),\Gamma(X\rt\o, Y\rt\o)X\rt\t\, Y\rt\t)
        X\rt\th{}_{+}\, Y\rt\th{}_{+}\,\overline{\Gamma(Y\rt\th{}_{-},X\rt\th{}_{-})}\\
        =&\Gamma(\Sigma(X\ro, Y\ro),\Gamma(X\rt{}_{+}\o, Y\rt{}_{+}\o)X\rt{}_{+}\t\, Y\rt{}_{+}\t)
        X\rt{}_{+}\th\, Y\rt{}_{+}\th\,\overline{\Gamma(Y\rt{}_{-},X\rt{}_{-})}\\
        =&\Gamma(\Sigma(X{}_{+}\ro, Y{}_{+}\ro),\Gamma(X{}_{+}\rt\o, Y{}_{+}\rt\o)X{}_{+}\rt\t\, Y{}_{+}\rt\t)
        X{}_{+}\rt\th\, Y{}_{+}\rt\th\,\overline{\Gamma(Y{}_{-},X{}_{-})}\\
        =&X_{+}Y_{+}\overline{\Gamma(Y{}_{-},X{}_{-})},
    \end{align*}
    where the 5th step use Proposition \ref{prop. cocomute coaction}. For the last equality, recall that $\cL$ is a left $\cL$-comodule in the sense that $X\mo\ot X\z=X_{-}\ot X_{+}$. Since $\Gamma(X_{\p}\ot X_{\m})=X_{+}\ot X_{-}$ by Theorem \ref{thm. twisted Hopf algebroid}, therefore it is not hard to see (by flipping the position of the two terms) $X\rmo\ot X\rz=X_{\m}\ot X_{\p}$, which results in the last equality.
\end{proof}
\begin{lemma}\label{lem. sigma is 2 cocycle}
     Let $\cL$ be a left Hopf algebroid over $B$ and $\Gamma$ is an invertible left 2-cocycle on $\cL$. Then $\Sigma$ defined above is a left 2-cocycle on $\cL^{\Gamma}$.
\end{lemma}
\begin{proof}
    It is not hard to see that $\Sigma(X, 1)=\varepsilon^{\Gamma}(X)=\Sigma(1, X)$. Now, let's show $\Sigma$ is a 2-cocycle. On the one hand,
    \begin{align*}
        \Sigma(&\Sigma(X\ro, Y\ro)\CG\,X\rt\,\CG\, Y\rt, Z)\\
     %=&\Sigma\bigg(\Gamma\Big(\Sigma(X\ro, Y\ro), \Gamma(X\rt\o, Y\rt\o)X\rt\t\,Y\rt\t\Big)
%X\rt\th{}_{+}\,Y\rt\th{}_{+}\overline{\Gamma(Y\rt\th{}_{-},X\rt\th{}_{-})}, Z\bigg)\\
        =&\Sigma(X_{+}Y_{+}\overline{\Gamma(Y_{-}, X_{-})}, Z)\\
        =&\Gamma(X_{++}Y_{++}Z_{+}, \Gamma(Z_{-}\o, \Gamma(Y_{-}, X_{-})\,Y_{+-}\o\,X_{+-}\o)Z_{-}\t\, Y_{+-}\t\,X_{+-}\t)\\
        =&\Gamma(X_{+}Y_{+}Z_{+}, \Gamma(Z_{-}\o, \Gamma(Y_{-}\o, X_{-}\o)\,Y_{-}\t\,X_{-}\t)Z_{-}\t\, Y_{-}\th\,X_{-}\th)
    \end{align*}
    where the 1st step uses Corollary \ref{cor. comodule twist back}. On the other hand,
    \begin{align*}
        \Sigma(&X, \Sigma(Y\ro, Z\ro)\CG Y\rt\CG Z\ro)\\
       %=&\Sigma\bigg(X,\Gamma\Big(\Sigma(Y\ro, Z\ro), \Gamma(Y\rt\o, Z\rt\o)Y\rt\t\,Z\rt\t\Big)
%Y\rt\th{}_{+}\,Z\rt\th{}_{+}\overline{\Gamma(Z\rt\th{}_{-},Y\rt\th{}_{-})}\bigg)\\
=&\Sigma(X,Y_{+}Z_{+}\overline{\Gamma(Z_{-}, Y_{-})})\\
=&\Gamma(X_{+}Y_{++}Z_{++}, \Gamma(\Gamma(Z_{-},Y_{-})Z_{+-}\o\,Y_{+-}\o, X_{-}\o)Z_{+-}\t\,Y_{+-}\t\, X_{-}\t)\\
=&\Gamma(X_{+}Y_{+}Z_{+}, \Gamma(\Gamma(Z_{-}\o,Y_{-}\o)Z_{-}\t\,Y_{-}\t, X_{-}\o)Z_{-}\th\,Y_{-}\th\, X_{-}\t).
    \end{align*}
    As a result, $\Sigma$ is a 2-cocycle.
\end{proof}

In the following, we are going to show $\Sigma$ is an invertible left 2-cocycle, i.e. $\Sigma^{\#}$ is invertible.

\begin{proposition}\label{prop. right inverse}
     Let $\cL$ be a left Hopf algebroid over $B$ and $\Gamma$ is an invertible left 2-cocycle on $\cL$. Then $\Sigma$ defined above satisfies $bX=\Sigma(b, X\ro)\CG X\rt$ and
    \[\Sigma(\Gamma(X\o, Y\o), \Sigma(X\t\ro\,, Y\t\ro)\CG\,X\t\rt\,\CG\, Y\t\rt)=\varepsilon^{\Gamma}(X\CG\,Y),\]
    for any $X, Y\in \cL$.
\end{proposition}
\begin{proof}
First, it is not hard to see
\[\Sigma(Xb, Y)=\Sigma(X, bY),\]
for any $b\in B$, $X, Y\in \cL$. Also, by the 2nd equality of Corollary \ref{cor. comodule twist back}, we can see that $bX=\Sigma(b, X\ro)\CG X\rt$.
% \begin{align*}
%     \Sigma(b, X\ro)\CG X\rt=&\Gamma(b\, X\ro{}_{+}, X\ro{}_{-})\CG X\rt\\
%     =&\Gamma(\Gamma(b\, X\ro{}_{+}, X\ro{}_{-}), X\rt\o)X\rt\t\\
%     =&\Gamma(\Gamma(b\, X\ro{}_{+}\o, X\ro{}_{-}\o)X\ro{}_{+}\t\, X\ro{}_{-}\t, X\rt\o)X\rt\t\\
%     =&\Gamma(b\, X\ro{}_{+}, \Gamma(X\ro{}_{-}\o, X\rt\o) X\ro{}_{-}\t\,X\rt\t)X\rt\th\\
%     =&\Gamma(b\, X\o{}_{+},  X\o{}_{-}\,X\t)X\th\\
%     =&\varepsilon(bX\o)X\t=bX.
% \end{align*}
As a result,
\begin{align*}
    b(&\Sigma(X\ro\,, Y\ro)\CG\,X\rt\,\CG\, Y\rt)\\
    =&\Sigma(b, \Sigma(X\ro\,, Y\ro)\CG\,X\rt\,\CG\, Y\rt)\CG\,X\rth\,\CG\, Y\rth\\
    =&\Sigma(\Sigma(b, X\ro)\CG\,X\rt,  Y\rt)\CG\,X\rth\,\CG\, Y\rth\\
    =&\Sigma(b\,X\ro,  Y\rt)\CG\,X\rt\,\CG\, Y\rth,
\end{align*}
where the 2nd step use Lemma \ref{lem. sigma is 2 cocycle}.
Therefore, the formula is well defined. To show the formula is correct, we can see
\begin{align*}
    \Sigma(&\Gamma(X\o, Y\o), \Sigma(X\t\ro\,, Y\t\ro)\CG\,X\t\rt\,\CG\, Y\t\rt)\\
     =&\Sigma(\Gamma(X\o, Y\o), X\t{}_{+}Y\t{}_{+}\overline{\Gamma(Y\t{}_{-},X\t{}_{-})})\\
    =&\Gamma(\Gamma(X\o, Y\o)\, X\t{}_{++}Y\t{}_{++}\,,\Gamma(Y\t{}_{-},X\t{}_{-})\,Y\t{}_{+-}X\t{}_{+-})\\
   =&\varepsilon^{\Gamma}(X\CG\,Y),
\end{align*}
where the 1st step uses Corollary \ref{cor. comodule twist back}.
\end{proof}

It is similar to Corollary \ref{cor. comodule twist back}, we have

\begin{corollary}\label{cor. comodule twist forward}
    Let $\cL$ be a left Hopf algebroid over $B$, $\Gamma$ is an invertible left 2-cocycle on $\cL$, and $\Sigma$ is defined above. Then for any $M,N\in {}^{\cL}\CM$, we have
    \[\Sigma(\Gamma(m\mo, n\mo),\Sigma(m\z{}_{\scriptscriptstyle{[-2]}}, n\z{}_{\scriptscriptstyle{[-2]}})\CG\,m\z\rmo\CG\, n\z\rmo)\CG\,m\z\rz\ot_{\BG} n\z\rz=m\ot_{\BG}n,\]
    for any $m\in M$ and $n\in N$.
\end{corollary}

\begin{proof}
    The proof is similar to Corollary \ref{cor. comodule twist back} by using Proposition \ref{prop. right inverse}.
\end{proof}

\begin{theorem}\label{thm. invertible 2 cocycle}
     Let $\cL$ be a left Hopf algebroid over $B$, $\Gamma$ is an invertible left 2-cocycle on $\cL$, and $\Sigma$ is defined above. Then $\Sigma$ is an invertible left 2-cocycle on $\cL^{\Gamma}$ with $\Sigma^{\#-1}=\GH$. Moreover, $(\cL^{\Gamma})^{\Sigma}=\cL$. We call $\Sigma$ the inverse of $\Gamma$ and denote it by $\Gamma^{-1}$.
\end{theorem}


\begin{proof}
First, we can see $(B^{\Gamma})^{\Sigma}=B$. Indeed,
\begin{align*}
    a\cdot_{\Sigma}b=\Sigma(a, b)=\Gamma(ab,1)=ab.
\end{align*}
We can check $\Sigma^{\#}$ is invertible with inverse being $\GH$. Indeed, recall that
    \[\Sigma^{\#}(m\ot_{B}n)=\Sigma(m\rmo, n\rmo)\CG m\rz\ot_{\BG}n\rz,\]
    for any $m\in M\in {}^{\cL^{\Gamma}}\CM$ and $n\in N\in {}^{\cL^{\Gamma}}\CM$. Therefore, by corollary \ref{cor. comodule twist forward},
    \begin{align*}
        \Sigma^{\#}&\circ \GH(m\ot_{\BG}n)\\
        =&\Sigma^{\#}(\Gamma(m\mo,n\mo)m\z\ot_{B} n\z)\\
        =&\Sigma(\Gamma(m\mo,n\mo)m\z\ro, n\z\ro)\CG\,m\z\rz\ot_{\BG} n\z\rz\\
        =&\Sigma(\Sigma(\Gamma(m\mo, n\mo),m\z{}_{\scriptscriptstyle{[-2]}})\CG\,m\z{}_{\scriptscriptstyle{[-1]}},  n\z\rmo)\CG\,m\z\rz\ot_{\BG} n\z\rz\\
        =&\Sigma(\Gamma(m\mo, n\mo),\Sigma(m\z{}_{\scriptscriptstyle{[-2]}}, n\z{}_{\scriptscriptstyle{[-2]}})\CG\,m\z\rmo\CG\, n\z\rmo)\CG\,m\z\rz\ot_{\BG} n\z\rz\\
        =&m\ot_{\BG}n,
    \end{align*}
    where the 3rd step uses Proposition \ref{prop. right inverse}. Also, we have
    \begin{align*}
        \GH&\circ \Sigma^{\#}(n\ot_{B}m)\\
        =&\GH(\Sigma(m\rmo, n\rmo)\CG m\rz\ot_{\BG}n\rz)\\
         =&\GH(\Gamma(\Sigma(m\rmo, n\rmo), m\rz\mo)m\rz\z \ot_{\BG}n\rz)\\
         =&\Gamma(\Gamma(\Sigma(m\rmo, n\rmo), m\rz\mt)m\rz\mo,n\rz\mo)m\rz\z\ot_{B}n\rz\z\\
         =&\Gamma(\Sigma(m\rmo, n\rmo),\Gamma(m\rz\mt, n\rz\mt)m\rz\mo n\rz\mo)m\rz\z\ot_{B} n\rz\z\\
         =&n\ot_{B}m,
    \end{align*}
    where the last step uses Corollary \ref{cor. comodule twist back}. By definition, $\Sigma$ is an invertible left 2-cocycle on $\cL^{\Gamma}$. It is similar to Proposition \ref{prop. right inverse}, we can show $Xb=\Sigma(X\ro, b)\CG X\rt$. Moreover, we have $ \overline{b}X=X_{\p}\CG\overline{\Sigma(X_{\m}, b)}$. Indeed,
    \begin{align*}
        X_{\p}\CG\overline{\Sigma(X_{\m}, b)}=&X_{\p +}\overline{\Gamma(\Sigma(X_{\m}, b),X_{\p -})}\\
        =&X_{\p +}\overline{\Gamma(\Gamma(X_{\m +}b,X_{\m -}),X_{\p -})}\\
        =&X_{\p +}\overline{\Gamma(\Gamma(X_{\m +}\o\,b,X_{\m -}\o)X_{\m +}\t\,X_{\m -}\t,X_{\p -})}\\
        =&X_{\p +}\overline{\Gamma(X_{\m +}\,b, \Gamma(X_{\m -}\o, X_{\p -}\o)X_{\m -}\t\,X_{\p -}\t)}\\
        =&X_{\p ++}\overline{\Gamma(X_{\m ++}\,b, \Gamma(X_{\m -}, X_{\p -})X_{\m +-}\,X_{\p +-})}\\
        =&X_{++}\overline{\Gamma(X_{- +}\,b, X_{--}\,X_{+-})}\\
        =&X_{+}\overline{\Gamma(X_{-}\o{}_{+}\,b, X_{-}\o{}_{-}\,X_{-}\t)}\\
        =&X_{+}\overline{\Gamma(X_{-}\,b, 1)}=X_{+}\overline{\varepsilon(X_{-}b)}=\overline{b}X.
    \end{align*}
    Similarly, $ X\overline{b}=X_{\p}\CG\overline{\Sigma(b,X_{\m})}$. Now, let's show the $\Sigma$ twist on $\cL^{\Gamma}$ recover the $B^e$-ring structure on $\cL$.
    \begin{align*}
        \Sigma(&X_{\p}\ro, Y_{\p}\ro)\CG X_{\p}\rt\CG Y_{\p}\rt\CG\, \overline{\Sigma(Y{}_{\m}, X{}_{\m})}\\
        =&(X_{\p +}\,Y_{\p +}\overline{\Gamma(Y_{\p -},\,X_{\p -})})\CG\, \overline{\Sigma(Y{}_{\m}, X{}_{\m})}\\
        =&X_{\p ++}\,Y_{\p ++}\overline{\Gamma(\Sigma(Y{}_{\m}, X{}_{\m}),\Gamma(Y_{\p -},\,X_{\p -})Y_{\p +-}\,X_{\p +-})}\\
        =&X_{\p +}\,Y_{\p +}\overline{\Gamma(\Sigma(Y{}_{\m}, X{}_{\m}),\Gamma(Y_{\p -}\o,\,X_{\p -}\o)Y_{\p -}\t\,X_{\p -}\t)}\\
        =&XY,
        % =&X_{\p ++}\,Y_{\p ++}\overline{\Gamma(\Gamma(Y{}_{\m +}\, X{}_{\m +}, \Gamma(X{}_{\m -}\o\,, Y{}_{\m -}\o)X{}_{\m -}\t\, Y{}_{\m -}\t),\Gamma(Y_{\p -},\,X_{\p -})Y_{\p +-}\,X_{\p +-})}\\
        % =&X_{\p +}\,Y_{\p +}
        % \overline{\Gamma(\Gamma(Y{}_{\m +}\, X{}_{\m +}, \Gamma(X{}_{\m -}\o\,, Y{}_{\m -}\o)X{}_{\m -}\t\, Y{}_{\m -}\t),\Gamma(Y_{\p -}\o,\,X_{\p -}\o)Y_{\p -}\t\,X_{\p -}\t)}\\
        % =&X_{\p +}\,Y_{\p +}
        % \overline{\Gamma(\Gamma(Y{}_{\m +}\o\, X{}_{\m +}\o, \Gamma(X{}_{\m -}\o\,, Y{}_{\m -}\o)X{}_{\m -}\t\, Y{}_{\m -}\t)Y{}_{\m +}\t\, X{}_{\m +}\t\,X{}_{\m -}\th\, Y{}_{\m -}\th\,,}\\
        % &\overline{\Gamma(Y_{\p -}\o,\,X_{\p -}\o)Y_{\p -}\t\,X_{\p -}\t)}\\
        %  =&X_{\p +}\,Y_{\p +}
        % \overline{\Gamma(Y{}_{\m +}\, X{}_{\m +}, }\\
        % &\overline{\Gamma(\Gamma(X{}_{\m -}\o\,, Y{}_{\m -}\o)X{}_{\m -}\t\, Y{}_{\m -}\t, \Gamma(Y_{\p -}\o,\,X_{\p -}\o)Y_{\p -}\t\,X_{\p -}\t)X{}_{\m -}\th\, Y{}_{\m -}\th\,Y_{\p -}\th\,X_{\p -}\th)}\\
        % =&X_{\p +}\,Y_{\p +}
        % \overline{\Gamma(Y{}_{\m +}\, X{}_{\m +}, }\\
        % &\overline{\Gamma(X{}_{\m -}\o, \Gamma(Y{}_{\m -}\o, \Gamma(Y_{\p -}\o,\,X_{\p -}\o)Y_{\p -}\t\,X_{\p -}\t) Y{}_{\m -}\t\,Y_{\p -}\th\,X_{\p -}\th )X{}_{\m -}\t\, Y{}_{\m -}\th\,Y_{\p -}\fo\,X_{\p -}\fo)}\\
        % =&X_{\p +}\,Y_{\p +}
        % \overline{\Gamma(Y{}_{\m +}\, X{}_{\m +}, }\\
        % &\overline{\Gamma(X{}_{\m -}\o, \Gamma(\Gamma(Y{}_{\m -}\o,Y_{\p -}\o)Y{}_{\m -}\t\,Y_{\p -}\t, \,X_{\p -}\o) Y{}_{\m -}\th\,Y_{\p -}\th\,X_{\p -}\t )X{}_{\m -}\t\, Y{}_{\m -}\fo\,Y_{\p -}\fo\,X_{\p -}\th)}\\
        % =&X_{\p ++}\,Y_{\p ++}
        % \overline{\Gamma(Y{}_{\m ++}\, X{}_{\m ++}, }\\
        % &\overline{\Gamma(X{}_{\m -}, \Gamma(\Gamma(Y{}_{\m -},Y_{\p -})Y{}_{\m +-}\o\,Y_{\p +-}\o, \,X_{\p -}) Y{}_{\m +-}\t\,Y_{\p +-}\t\,X_{\p +-}\o )X{}_{\m +-}\, Y{}_{\m +-}\th\,Y_{\p +-}\th\,X_{\p +-}\t)}\\
        % =&X_{\p ++}\,Y_{++}
        % \overline{\Gamma(Y{}_{-+}\, X{}_{\m ++}, }\\
        % &\overline{\Gamma(X{}_{\m -}, \Gamma(Y{}_{--}\o\,Y_{+-}\o, \,X_{\p -}) Y{}_{--}\t\,Y_{ +-}\t\,X_{\p +-}\o )X{}_{\m +-}\, Y{}_{--}\th\,Y_{ +-}\th\,X_{\p +-}\t)}\\
        %  =&X_{\p ++}\,Y_{+}
        % \overline{\Gamma(Y{}_{-}\, X{}_{\m ++}, \Gamma(X{}_{\m -}, \Gamma(1, \,X_{\p -}) \,X_{\p +-}\o )X{}_{\m +-}\, \,X_{\p +-}\t)}\\
        % =&X_{\p +}\,Y_{+}
        % \overline{\Gamma(Y{}_{-}\, X{}_{\m ++}, \Gamma(X{}_{\m -},  \,X_{\p -}\o )X{}_{\m +-}\, \,X_{\p -}\t)}\\
        % =&X_{\p ++}\,Y_{+}
        % \overline{\Gamma(Y{}_{-}\, X{}_{\m ++}, \Gamma(X{}_{\m -},  \,X_{\p -} )X{}_{\m +-}\, \,X_{\p +-})}\\
        % =&X_{++}\,Y_{+}
        % \overline{\Gamma(Y{}_{-}\, X{}_{-+}, X{}_{--}\, \,X_{+ -})}\\
        % =&X_{+}\,Y_{+}
        % \overline{\Gamma(Y{}_{-}\, X{}_{-}, 1)}=X_{+}\,Y_{+}
        % \overline{\varepsilon(Y{}_{-}\, X{}_{-})}=XY,
    \end{align*}
    where the 1st and the last step use Corollary \ref{cor. comodule twist back}. As $\GH$ is the inverse of $\Sigma^{\#}$, we can see the coproduct $(\Delta^{\Gamma})^\Sigma=\Delta$. Also,
    \begin{align*}
        \Sigma(X_{\p}, X_{\m})=&\Gamma(X_{\p +} X_{\m +}, \Gamma(X_{\m -}\o, X_{\p -}\o)X_{\m -}\t X_{\p -}\t)\\
        =&\Gamma(X_{\p ++} X_{\m ++}, \Gamma(X_{\m -}, X_{\p -})X_{\m +-} X_{\p +-})\\
        =&\Gamma(X_{++} X_{-+}, X_{--} X_{+-})=\Gamma(X_{+} X_{-},1)=\varepsilon(X_{+}X_{-})=\varepsilon(X).
    \end{align*}
    So $(\varepsilon^{\Gamma})^{\Sigma}=\varepsilon$.
\end{proof}

Here we also give a property for later use:
\begin{proposition}\label{prop. twist forward}
      Let $\cL$ be a left Hopf algebroid over $B$, $\Gamma$ is an invertible left 2-cocycle on $\cL$. Then $(\Gamma^{-1})^{-1}=\Gamma$,
and
    \[\Gamma(X\o, Y\o)\,X\t\,Y\t =X_{\p}\CG\,Y_{\p}\CG\overline{\Gamma^{-1}(Y_{\m},X_{\m})},\]
    for any $X, Y\in\CL$.
\end{proposition}
\begin{proof}
 As $\Gamma^{-1}$ is an invertible left 2-cocycle on $\cL^{\Gamma}$ by Theorem \ref{thm. invertible 2 cocycle}, we can see for any $X, Y\in \cL$, we have
\begin{align*}
    (&\Gamma^{-1})^{-1}(X, Y)\\
    =&\Gamma^{-1}(X_{\p}\CG Y_{\p}, \Gamma^{-1}(Y_{\m}\ro, X_{\m}\ro)\CG\,Y_{\m}\rt\CG X_{\m}\rt)\\
    =&\Gamma^{-1}(\Gamma(X_{\p +}\o, Y_{\p +}\o)X_{\p +}\t Y_{\p +}\t\,\overline{\Gamma(Y_{\p -},X_{\p -})}, Y_{\m +}\, X_{\m +}\overline{\Gamma(X_{\m -}\,, Y_{\m -})})\\
     =&\Gamma(\Gamma(X_{\p +}\o, Y_{\p +}\o)X_{\p +}\t{}_{+} Y_{\p +}\t{}_{+}\,Y_{\m ++}X_{\m ++},\\
     &\Gamma(\Gamma(X_{\m -}\, ,Y_{\m -})X_{\m +-}\o\,Y_{\m +-}\o, \Gamma(Y_{\p -},X_{\p -})Y_{\p +}\t{}_{-}\o\,X_{\p +}\t{}_{-}\o)\\
     &X_{\m +-}\t\,Y_{\m +-}\t\,Y_{\p +}\t{}_{-}\t\,X_{\p +}\t{}_{-}\t)\\
   =&\Gamma(\Gamma(X_{\p ++}\o, Y_{\p ++}\o)X_{\p ++}\t Y_{\p ++}\t\,Y_{\m ++}X_{\m ++},\\
     &\Gamma(\Gamma(X_{\m -},\, Y_{\m -})X_{\m +-}\o\,Y_{\m +-}\o, \Gamma(Y_{\p -},X_{\p -})Y_{\p +-}\o\,X_{\p +-}\o)\,
     X_{\m +-}\t\,Y_{\m +-}\t\,Y_{\p +-}\t\,X_{\p +-}\t)\\
      =&\Gamma(\Gamma(X_{\p +}\o, Y_{\p +}\o)X_{\p +}\t Y_{\p +}\t\,Y_{\m +}X_{\m +},\\
     &\Gamma(\Gamma(X_{\m -}\o\,, Y_{\m -}\o)X_{\m -}\t\,Y_{\m -}\t, \Gamma(Y_{\p -}\o,X_{\p -}\o)Y_{\p -}\t\,X_{\p -}\t)\,
     X_{\m -}\th\,Y_{\m -}\th\,Y_{\p -}\th\,X_{\p -}\th)\\
        =&\Gamma(\Gamma(X_{\p +}\o,\,Y_{\p +}\o)X_{\p +}\t\,Y_{\p +}\t
\,Y{}_{\m +}\, X{}_{\m +}, \\
        &\Gamma(X{}_{\m -}\o, \Gamma(Y{}_{\m -}\o, \Gamma(Y_{\p -}\o,\,X_{\p -}\o)Y_{\p -}\t\,X_{\p -}\t) Y{}_{\m -}\t\,Y_{\p -}\th\,X_{\p -}\th )X{}_{\m -}\t\, Y{}_{\m -}\th\,Y_{\p -}\fo\,X_{\p -}\fo)\\
        =&\Gamma(\Gamma(X_{\p +}\o,\,Y_{\p +}\o)X_{\p +}\t\,Y_{\p +}\t
\,Y{}_{\m +}\, X{}_{\m +}, \\
        &\Gamma(X{}_{\m -}\o, \Gamma(\Gamma(Y{}_{\m -}\o,Y_{\p -}\o)Y{}_{\m -}\t\,Y_{\p -}\t, \,X_{\p -}\o) Y{}_{\m -}\th\,Y_{\p -}\th\,X_{\p -}\t )X{}_{\m -}\t\, Y{}_{\m -}\fo\,Y_{\p -}\fo\,X_{\p -}\th)\\    =&\Gamma(\Gamma(X_{\p ++}\o,\,Y_{\p ++}\o)X_{\p ++}\t\,Y_{\p ++}\t
\,Y{}_{\m ++}\, X{}_{\m ++}, \\
&\Gamma(X{}_{\m -}, \Gamma(\Gamma(Y{}_{\m -},Y_{\p -})Y{}_{\m +-}\o\,Y_{\p +-}\o, \,X_{\p -}) Y{}_{\m +-}\t\,Y_{\p +-}\t\,X_{\p +-}\o )X{}_{\m +-}\, Y{}_{\m +-}\th\,Y_{\p +-}\th\,X_{\p +-}\t)\\
       =&\Gamma(\Gamma(X_{\p ++}\o,\,Y_{++}\o)X_{\p ++}\t\,Y_{++}\t
\,Y{}_{-+}\, X{}_{\m ++}, \\
        &\Gamma(X{}_{\m -}, \Gamma(Y{}_{--}\o\,Y_{+-}\o, \,X_{\p -}) Y{}_{--}\t\,Y_{ +-}\t\,X_{\p +-}\o )X{}_{\m +-}\, Y{}_{--}\th\,Y_{ +-}\th\,X_{\p +-}\t)\\
        =&\Gamma(\Gamma(X_{\p ++}\o\,,Y_{+}\o)X_{\p ++}\t\,Y_{+}\t
\,Y{}_{-}\, X{}_{\m ++}, \Gamma(X{}_{\m -}, \Gamma(1, \,X_{\p -}) X_{\p +-}\o )X{}_{\m +-}\, X_{\p +-}\t)\\
=&\Gamma(\Gamma(X_{\p ++}\o,\,Y)X_{\p ++}\t\, X{}_{\m ++}, \Gamma(X{}_{\m -},  X_{\p -} )X{}_{\m +-}\, X_{\p +-})\\
=&\Gamma(\Gamma(X_{ ++}\o,\,Y)X_{++}\t\, X{}_{-+}, X{}_{--}\, X_{+-})\\
=&\Gamma(\Gamma(X_{ +}\o,\,Y)X_{+}\t\, X{}_{-}, 1)\\
=&\Gamma(\Gamma(X,Y), 1)\\
=&\Gamma(X,Y),
\end{align*}
    where the 2nd step uses Corollary \ref{cor. comodule twist back}. The formula of this Proposition is a direct result of the second equality in Corollary \ref{cor. comodule twist back} by exchanging $\Sigma$ and $\Gamma$.
\end{proof}

As a conclusion, we can see although there is no convolution inverse of an invertible left 2-cocycle $\Gamma$, there is an invertible left 2-cocycle $\Gamma^{-1}$, such that
\begin{align*}
    \Gamma(\Gamma^{-1}(X\ro, Y\ro), \Gamma(X\rt\o\, ,Y\rt\o)X\rt\t\, Y\rt\t)=&\varepsilon(XY),\\
    \Gamma^{-1}(\Gamma(X\o, Y\o), \Gamma^{-1}(X\t\ro\,, Y\t\ro)\CG\,X\t\rt\,\CG\, Y\t\rt)=&\varepsilon^{\Gamma}(X\CG\,Y),
\end{align*}
    for any $X, Y\in \cL$. This motivate us to define a composition of two 2-cocycle in the following:

\begin{lemma}\label{compos}
    Let $\cL$ be a left $B$-Hopf algebroid, $\Gamma$ is an invertible left 2-cocycle on $\cL$ and $\Sigma$ is an invertible left 2-cocycle on $\cL^{\Gamma}$. Then $\Sigma\circ \Gamma:\cL\ot_{\BB}\cL\to B$ given by
    \begin{align*}
        \Sigma\circ \Gamma(X, Y)=&\Gamma(\Sigma(X\ro, Y\ro)\CG X\rt, Y\rt)
        % =&\Gamma(\Sigma(X\ro, Y\ro), \Gamma(X\rt\o, Y\rt\o)X\rt\t Y\rt\t),
    \end{align*}
    is an invertible left 2-cocycle. Moreover, $(\Sigma\circ \Gamma)^{\#}=\GH\circ \Sigma^{\#}$.
\end{lemma}
\begin{proof}
    It is not hard to see $\Sigma\circ \Gamma$ is well defined and $\Sigma\circ \Gamma$ factors through $\ot_{\overline{B}}$. We can check directly it is left $\overline{B}$-linear. Now, let's show it is a left 2-cocycle. First, we can see that
    \begin{align*}
        \Gamma&(\Sigma(X\o\ro, Y\o\ro)\CG X\o\rt, Y\o\rt)X\t Y\t\\
        =& \Gamma(\Sigma(X\ro, Y\ro)\CG X\rt\o, Y\rt\o)X\rt\t Y\rt\t\\
        =& \Gamma(\Sigma(X\ro, Y\ro), \Gamma( X\rt\o, Y\rt\o)X\rt\t Y\rt\t)X\rt\th Y\rt\th\\
        =&\Sigma(X\ro, Y\ro)\CG (\Gamma( X\rt\o, Y\rt\o)X\rt\t Y\rt\t)\\
        =&\Sigma(X\ro, Y\ro)\CG (X\rt{}_{\p}\CG\,Y\rt{}_{\p}\,\CG\overline{\Gamma^{-1}(Y\rt{}_{\m},X\rt{}_{\m})} ),
    \end{align*}
    where the last step uses Proposition \ref{prop. twist forward}.    On the one hand,
    \begin{align*}
        \Sigma&\circ \Gamma(\Sigma\circ \Gamma(X\o, Y\o)X\t Y\t, Z)\\
        =&\Sigma\circ \Gamma(\Gamma(\Sigma(X\o\ro, Y\o\ro)\CG X\o\rt, Y\o\rt)X\t Y\t, Z)\\
         =&\Sigma\circ \Gamma(\Sigma(X\ro, Y\ro)\CG (X\rt{}_{\p}\CG\,Y\rt{}_{\p}\,\CG\overline{\Gamma^{-1}(Y\rt{}_{\m},X\rt{}_{\m})} ), Z)\\
         =&\Gamma(\Sigma(\big(\Sigma(X\ro, Y\ro)\CG (X\rt{}_{\p}\CG\,Y\rt{}_{\p}\,\CG\overline{\Gamma^{-1}(Y\rt{}_{\m},X\rt{}_{\m})} )\big)\ro, \\
         &\quad Z\ro)\CG \big(\Sigma(X\ro, Y\ro)\CG (X\rt{}_{\p}\CG\,Y\rt{}_{\p}\,\CG\overline{\Gamma^{-1}(Y\rt{}_{\m},X\rt{}_{\m})} )\big)\rt, Z\rt)\\
         =&\Gamma(\Sigma\big(\Sigma(X\ro, Y\ro)\CG X\rt{}_{\p}\ro\CG\,Y\rt{}_{\p}\ro\, ,
         Z\ro\big)\CG \big(X\rt{}_{\p}\rt\CG\,Y\rt{}_{\p}\rt\,\CG\overline{\Gamma^{-1}(Y\rt{}_{\m},X\rt{}_{\m})} \big), Z\rt)\\
         =&\Gamma(\Sigma\big(\Sigma(X\ro, Y\ro)\CG X\rt\CG\,Y\rt\, ,
         Z\ro\big)\CG \big(X\rth{}_{\p}\CG\,Y\rth{}_{\p}\,\CG\overline{\Gamma^{-1}(Y\rth{}_{\m},X\rth{}_{\m})} \big), Z\rt)\\
         =&\Gamma(\Sigma\big(\Sigma(X\ro, Y\ro)\CG X\rt\CG\,Y\rt\, ,
         Z\ro\big)\CG \big(\Gamma(X\rth\o, Y\rth\o)X\rth\t\, Y\rth\t\big), Z\rt)\\
         =&\Gamma(\Sigma(\Sigma(X\ro, Y\ro)\CG X\rt\CG\,Y\rt\, ,
         Z\ro), \Gamma( \Gamma(X\rth\o, Y\rth\o)X\rth\t\, Y\rth\t, Z\rt\o)X\rth\th\, Y\rth\th\,Z\rt\t).
    \end{align*}
   On the other hand, by a similar method, it is not hard to see
    \begin{align*}
         \Sigma&\circ \Gamma(X, \Sigma\circ \Gamma(Y\o, Z\o)Y\t Z\t)\\
         =&\Gamma(\Sigma(         X\ro,\Sigma(Y\ro, Z\ro)\CG Y\rt\CG\,Z\rt\,), \Gamma(X\rt\o, \Gamma(Y\rth\o,Z\rth\o) Y\rth\t\,Z\rth\t)X\rt\t\, Y\rth\th\,Z\rth\th).
    \end{align*}
    They are equal since $\Gamma$ and $\Sigma$ are left 2-cocycles. Finally,
    we can see for any $m\in M\in {}^{\cL}\CM$ and $n\in N\in {}^{\cL}\CM$
    \begin{align*}
         (\Sigma\circ \Gamma)^{\#}(m\ot n)=&\Sigma\circ \Gamma(m\mo, n\mo)m\z\ot n\z\\
         =&\Gamma(\Sigma(m\mo\ro, n\mo\ro)\CG m\mo\rt, n\mo\rt)m\z\ot n\z\\
         =&\Gamma(\Sigma(m\rmo, n\rmo)\CG m\rz\mo, n\rz\mo)m\rz\z\ot n\rz\z\\
         =&\GH(\Sigma(m\rmo, n\rmo)\CG m\rz\ot n\rz)\\
         =&\GH\circ \Sigma^{\#}(m\ot n),
    \end{align*}
    where the 3rd step uses Corollary \ref{cor. cocommute coaction}. As a result, $\Sigma\circ \Gamma$ is an invertible left 2-cocycle since $\Sigma$ and $\Gamma$ are invertible.
    \end{proof}
    \begin{proposition}
        Let $\cL$ be a left $B$-Hopf algebroid, $\Gamma$ is an invertible 2-cocycle on $\cL$ and $\Sigma$ is an invertible 2-cocycle on $\cL^{\Gamma}$. Then $\cL^{\Sigma\circ \Gamma}=(\cL^{\Gamma})^{\Sigma}$.
    \end{proposition}
    \begin{proof}
        We can see $B^{\Sigma\circ \Gamma}=B^{\Sigma}$. Indeed,
        \begin{align*}
          b\cdot_{\Sigma\circ \Gamma}b'=\Gamma(\Sigma(b,b'),1)=\Sigma(b,b').
        \end{align*}
       Let $B^{i}=B, B^{\Gamma}$ or $B^{\Sigma}$, define $\GH_{L}:\cL\ot_{\BG\ot \overline{B^{i}}}\cL\to \cL\ot_{B\ot \overline{B^{i}}}\cL$ by $\GH_{L}(X\ot Y)=\Gamma(X\o, Y\o)X\t\ot Y\t$, and define $\GH_{R}:\cL\ot_{B^{i}\ot \overline{\BG}}\cL\to \cL\ot_{B^i\ot \overline{B}}\cL$ by $\GH_{R}(X\ot Y)=X_{+}\ot Y_{+}\overline{\Gamma(Y_{-},X_{-})}$. It is not hard to see $m_{\cL^{\Gamma}}=m_{\cL}\circ \GH_{L}\circ \GH_{R}=m_{\cL}\circ \GH_{R}\circ \GH_{L}$. Moreover, we can show $\GH{}_{R}\circ \Sigma^{\#}{}_{L}=\Sigma^{\#}{}_{L}\circ \GH{}_{R}:\cL_{B^{\Sigma}\ot\overline{B^{\Gamma}}}\to \cL_{B^{\Gamma}\ot\overline{B}}$. Indeed,
       \begin{align*}
           \Sigma^{\#}{}_{L}\circ \GH{}_{R}(X\ot Y)=& \Sigma^{\#}{}_{L}(X_{+}\ot Y_{+}\overline{\Gamma(Y_{-}, X_{-})})\\
           =&\Sigma(X_{+}\ro, Y_{+}\ro)\CG X_{+}\rt\ot Y_{+}\rt\overline{\Gamma(Y_{-}, X_{-})}\\
           =&\Sigma(X\ro, Y\ro)\CG X\rt{}_{+}\ot Y\rt{}_{+}\overline{\Gamma(Y\rt{}_{-}, X\rt{}_{-})}\\
           =&\Gamma^{\#}{}_{R}(\Sigma(X\ro, Y\ro)\CG X\rt\ot Y\rt)\\
           =&\GH{}_{R}\circ \Sigma^{\#}{}_{L}(X\ot Y),
       \end{align*}
       where the 3rd step uses Proposition \ref{prop. cocomute coaction}. As a result,
\begin{align*}
    m_{(\cL^{\Gamma})^{\Sigma}}=&m_{\cL^{\Gamma}}\circ \Sigma^{\#}{}_{L}\circ \Sigma^{\#}{}_{R}\\
    =&m_{\cL}\circ \Gamma^{\#}{}_{L}\circ \Gamma^{\#}{}_{R}\circ \Sigma^{\#}{}_{L}\circ \Sigma^{\#}{}_{R}\\
    =&m_{\cL}\circ \Gamma^{\#}{}_{L}\circ \Sigma^{\#}{}_{L}\circ \Gamma^{\#}{}_{R}\circ \Sigma^{\#}{}_{R}\\
    =& m_{\cL}\circ (\Sigma\circ\Gamma)^{\#}{}_{L}\circ (\Sigma\circ\Gamma)^{\#}{}_{R}\\
    =&m_{\cL^{(\Sigma\circ\Gamma)}},
\end{align*}
       where the last step uses $(\Sigma\circ\Gamma)^{\#}{}_{L/R}=\Gamma^{\#}{}_{L/R}\circ \Sigma^{\#}{}_{L/R}$ (which is similar to the fact that $(\Sigma\circ\Gamma)^{\#}=\Gamma^{\#}\circ \Sigma^{\#}$). Clearly, $\Delta^{\Sigma\circ \Gamma}=(\Sigma\circ \Gamma)^{\# -1}\circ \Delta=\Sigma^{\# -1}\circ \GH^{-1}\circ \Delta=\Sigma^{\# -1}\circ \Delta^{\Gamma}=(\Delta^{\Gamma})^{\Sigma}$. Finally, we have
       \begin{align*}
           \varepsilon^{\Sigma\circ \Gamma}(X)=&\Sigma\circ \Gamma(X_{+}, X_{-})
           =\Gamma(\Sigma(X_{+}\ro, X_{-}\ro)\CG X_{+}\rt, X_{-}\rt)\\
           =&\Gamma(\Sigma(X_{\p +}\ro, X_{\m})\CG X_{\p +}\rt, X_{\p -})
           =\Gamma(\Sigma(X_{\p}\ro, X_{\m})\CG X_{\p}\rt{}_{+}, X_{\p}\rt{}_{-})\\
           =&\varepsilon^{\Gamma}(\Sigma(X_{\p}\ro, X_{\m})\CG X_{\p}\rt)
           =\Sigma(X_{\p}\ro, X_{\m})\CG\varepsilon^{\Gamma}( X_{\p}\rt)=\Sigma(X_{\p}, X_{\m})\\
           =&(\varepsilon^{\Gamma})^{\Sigma}(X),
       \end{align*}
        where the 3rd and 4th steps use Proposition \ref{prop. cocomute coaction}.
    \end{proof}

\begin{theorem}
    The collection of left Hopf algebroids with invertible 2-cocycles with composition as in Lemma~\ref{compos} form a groupoid.
\end{theorem}

\begin{proof}
     We can see $\hat{\varepsilon^{\Gamma}}\circ \Gamma=\Gamma$ and $\Gamma\circ \hat{\varepsilon}=\Gamma$. It is not hard to see $\Gamma\circ \Gamma^{-1}$ is the trivial 2-cocycle on $\cL^{\Gamma}$ and $\Gamma^{-1}\circ \Gamma$ is the trivial 2-cocycle on $\cL$ by Propositions \ref{prop. left inverse} and \ref{prop. right inverse}. Next, we are going to show the composition is associative. Let $\Pi$ be an invertible left 2-cocycle on $\cL^{(\Sigma\circ \Gamma)}$ (with the coproduct denoted by $\Delta^{(\Sigma\circ \Gamma)}(X)=X_{\<1\>}\ot X_{\<2\>}$).  We have on the one hand,
    \begin{align*}
        \Pi\circ(\Sigma\circ \Gamma)(X,Y)=&\Sigma\circ \Gamma(\Pi(X_{\<1\>}, Y_{\<1\>})\cdot_{\Pi}X_{\<2\>}, Y_{\<2\>})\\
        =&\Gamma(\Sigma(\Pi(X_{\<1\>}, Y_{\<1\>})\cdot_{\Pi}X_{\<2\>}\ro, Y_{\<2\>}\ro)\CG X_{\<2\>}\rt, Y_{\<2\>}\rt)\\
        =&\Gamma(\Sigma(\Pi(X\ro{}_{\<1\>}, Y\ro{}_{\<1\>})\cdot_{\Pi}X\ro{}_{\<2\>}, Y\ro{}_{\<2\>})\CG X\rt, Y\rt)\\
        =&\Gamma((\Pi\circ\Sigma)(X\ro, Y\ro)\CG X\rt, Y\rt)\\
        =&(\Pi\circ\Sigma)\circ \Gamma(X,Y),
    \end{align*}
    where the 3rd step uses Proposition \ref{prop. cocomute coaction}.
\end{proof}

