\subsection{Dualisation of 2-cocycles}\label{secdualcocy}

In this section, we will see that a 2-cocycle in a left bialgebroid induces a 2-cocycle on its dual bialgebroid.

\begin{definition}\cite{schau1}\label{def. dual pairing for left bialgeboids}
    Let $\cL$ and $\CH$ be two left bialgebroids over $B$,  a dual pairing between $\cL$ and $\CH$ is a linear map $\<\bullet |\bullet\> :\cL\ot\CH\to B$ such that:
    \begin{itemize}
        \item [(1)]$\<a\Bar{b}X c\Bar{d}| \alpha\>f=a\<X|c\Bar{f}\alpha d\Bar{b}\>$,
        \item [(2)] $\<X|\alpha\beta\>=\<X\o|\alpha \overline{\<X\t|\beta\>}\>=\<\overline{\<X\t|\beta\>}X\o|\alpha \>$,
        \item [(3)] $\<XY|\alpha\>=\<X \<Y|\alpha\o\>|\alpha\t\>=\<X |\<Y|\alpha\o\>\alpha\t\>$,
        \item [(4)] $\<X|1\>=\varepsilon(X)$,
        \item [(5)]$\<1|\alpha\>=\varepsilon(\alpha)$,
    \end{itemize}
    for all $a, b, c, d, f\in B$, $\alpha, \beta\in \CH$ and $X, Y\in \cL$.
\end{definition}
Let $\cL$ be a left $B$-bialgebroid that is finite generated left $\BB$-module, it is given in \cite{schau1} that its left dual $\cL^{\vee}:=\Hom_{\overline{B}-}(\cL, B)$ is a left bialgebroid. There is a canonical dual pairing between $\cL^{\vee}$ and $\cL$ that is given by
\[\<\alpha|X\>:=\alpha(X),\]
for any $\alpha\in \cL^{\vee}$ and $X\in \cL$. The left $B$-bialgebroid structure on $\cL^{\vee}$ is given by (1)-(5) in Definition \ref{def. dual pairing for left bialgeboids}.

\begin{definition}\cite{Xu}
    Let $\Lambda$ be a left $B$-bialgebroid. $F\in \Lambda\di_{B}\Lambda$ is called a left 2-cocycle in $\Lambda$ if
    \begin{itemize}
        \item [(1)] $(\varepsilon\di_{B}\id)F=1_{\Lambda}$ and $(\id\di_{B}\varepsilon)F=1_{\Lambda}$.
        \item[(2)] $(\Delta\di_{B})FF^{12}=(\id\di_{B}\Delta)FF^{23}$,
    \end{itemize}
    where $F^{12}=F\ot 1\in \Lambda\di_{B}\Lambda\ot \Lambda$ and $F^{23}=1\ot F\in \Lambda\ot\Lambda\di_{B} \Lambda$. In the following, we will always denote $F$ by $F^\alpha \di_{B}F_{\alpha}\in \Lambda\di_{B} \Lambda$. We call $F$ an invertible left 2-cocycle in $\Lambda$, if for any left $\Lambda$-module $M, N$, the map
\[F^{\#}:M\di_{B^F}N\to M\di_{B}N,\qquad m\ot n\mapsto F^{\alpha}\la m\di_{B}F_{\alpha}\la n,\forall m\in M, n\in N,\]
is invertible.
\end{definition}
By \cite{Xu}, given a 2-cocycle in a left $B$-bialgebroid $\Lambda$, we can construct a new left $B^F$-bialgebroid, with a twisted base algebra $B^F$ defined on the underlying vector space $B$ with a twisted product
\[a\cdot_{F}b=\varepsilon(F^\alpha a)\varepsilon(F_{\alpha}b),\]
and source and target maps
\[s^F(b)=\varepsilon(F^\alpha b)F_{\alpha}, \qquad t^{F}(b)=\overline{\varepsilon(F_{\alpha}b)}F^\alpha,\]
and coproduct
\[\Delta^{F}(\alpha)=F^{\#}{}^{-1}(\alpha\o F^{\alpha}\di_{B}\alpha\t F_{\alpha}),\]
for any $\alpha\in \Lambda$. The counit, unit and product of $\Lambda^F$ is the same as $\Lambda$.

\begin{lemma}\label{lem. 2-cocycle dual}
 Suppose we are given a dual pairing  $\<\bullet|\bullet\>$ between two left $B$-bialgebroids $\Lambda$, $\cL$. If $F$ is an  invertible left 2-cocycle in $\Lambda$ then there is an invertible left 2-cocycle on $\cL$ given by
$\Gamma_{F}(X\ot_{\overline{B}} Y)=\<F^{\alpha}|X\overline{\<F_{\alpha}|Y\>}\>$ for any $X, Y\in \cL$.
\end{lemma}
\begin{proof}

It is not hard to see $\Gamma_{F}$ is well defined and left $\BB$-linear. We will can also see it is a left 2-cocycle.
 Indeed, on the one hand,
\begin{align*}
    \Gamma_{F}&(\Gamma_{F}(X\o, Y\o)X\t Y\t, Z)\\
    =&\Gamma_{F}(\<F^{\alpha}|X\o\overline{\<F_{\alpha}|Y\o\>}\>X\t Y\t, Z)\\
    =&\<F^{\beta}|\<F^{\alpha}|X\o\overline{\<F_{\alpha}|Y\o\>}\>X\t Y\t\overline{\<F_{\beta}|Z\>}\>\\
    =&\<F^{\beta}|\<F^{\alpha}|X\o\>X\t \<F_{\alpha}|Y\o\> Y\t\overline{\<F_{\beta}|Z\>}\>\\
    =&\<F^{\beta}\o|\<F^{\alpha}|X\o\>X\t \overline{\<F^{\beta}\t| \<F_{\alpha}|Y\o\> Y\t\overline{\<F_{\beta}|Z\>}\>}\>\\
    =&\<F^{\beta}\o F^{\alpha}|X \overline{\<F^{\beta}\t F_{\alpha}|Y\overline{\<F_{\beta}|Z\>}\>}\>.
\end{align*}
On the other hand, we can similarly get
\begin{align*}
     \Gamma_{F}(X, \Gamma_{F}(Y\o, Z\o)Y\t Z\t)=\<F^{\alpha}|X \overline{\<F_{\alpha}\o F^{\beta}|Y\overline{\<F_{\alpha}\t F_{\beta}|Z\>}\>}\>,
\end{align*}
so they are equal by the 2-cocycle condition of $F$. To see $\Gamma_{F}^{\#}$ is invertible, assume $M, N$ are left $\cL$-comodule. It is given by \cite{schau1} that $M, N$ are also left $\Lambda$-modules with left action
\[\alpha\la m=\<\alpha|m\mo\>m\z,\]
for any $m\in M$. We can see
\begin{align*}
    \Gamma_{F}^{\#}(m\ot_{B}n)=&\Gamma_{F}(m\mo\ot n\mo)m\z\ot n\z=\<F^{\alpha}|m\mo\overline{\<F_{\alpha}|n\mo\>}\>m\z\ot n\z\\
    =&\<F^{\alpha}|m\mo\>m\z\ot \<F_{\alpha}|n\mo\>n\z=F^{\alpha}\la m\ot F_{\alpha}\la n,
\end{align*}
for any $m\in M$ and $n\in N$. Therefore, $\Gamma_{F}^{\#}$ is invertible since $F^{\#}$ is.

\end{proof}

\begin{theorem}\label{thm. twisted dual pairing}
    Suppose we are given a dual pairing $\<\bullet|\bullet\>$ between two left $B$-bialgebroids $\Lambda$, $\cL$ and that $\cL$ is a left Hopf algebroid. If $F$ is an invertible left 2-cocycle in $\Lambda$ then there is a  dual pairing between $\Lambda^{F}$ and $\cL^{\Gamma_{F}}$ which is given by
    \[[\alpha|X]=\<F^{\alpha}\alpha|X_{+}\overline{\<F_{\alpha}|X_{-}\>}\>,\qquad \forall X\in \cL, \alpha\in \Lambda.\]
\end{theorem}
\begin{proof}
 It is not hard to see the twisted dual pairing is well defined. First, we observe that
 \[[\alpha|X]=\Gamma_{F}(\<\alpha|X\o\> X\t{}_{+}, X\t{}_{-})\]
 We denote $\Gamma_{F}$ by $\Gamma$ in the following. We have
 \begin{align*}
     [s^{F}(b)\alpha|X]=&\Gamma(\<\varepsilon(F^{\alpha}b)F_{\alpha}\alpha|X\o\> X\t{}_{+}, X\t{}_{-})\\
     =&\Gamma(\<\<F^{\alpha}|b\>F_{\alpha}|\<\alpha|X\o\>X\t\> X\th{}_{+}, X\th{}_{-})\\
     =&\Gamma(\<F^{\alpha}|b\>\<F_{\alpha}|\<\alpha|X\o\>X\t\> X\th{}_{+}, X\th{}_{-})\\
     =&\Gamma(\<F^{\alpha}|b\overline{\<F_{\alpha}|\<\alpha|X\o\>X\t\>}\> X\th{}_{+}, X\th{}_{-})\\
     =&\Gamma(\Gamma(b, \<\alpha|X\o\>X\t) X\th{}_{+}, X\th{}_{-})\\
     =&\Gamma(b, \Gamma(\<\alpha|X\o\> X\t{}_{+}\o, X\t{}_{-}\o)X\t{}_{+}\t\, X\t{}_{-}\t)\\
     =&\Gamma(b, \Gamma(\<\alpha|X\o\> X\t{}_{+}, X\t{}_{-}))\\
     =&b\CG[\alpha|X]
 \end{align*}
 Also,
\begin{align*}
     [\alpha|\overline{b}\CG X]=&\Gamma(\<\alpha|X_{+}\o\> X_{+}\t{}_{+}, \Gamma(X_{-}, b)X_{+}\t{}_{-})\\
     =&\Gamma(\<\alpha|X\o\> X\t{}_{++}, \Gamma(X\t{}_{-}, b)X\t{}_{+-})\\
     =&\Gamma(\<\alpha|X\o\> X\t{}_{+}, \Gamma(X\t{}_{-}\o, b)X\t{}_{-}\t)\\
     =&\Gamma(\Gamma(\<\alpha|X\o\> X\t{}_{+}\o, X\t{}_{-}\o)X\t{}_{+}\t X\t{}_{-}\t, b)\\
     =&\Gamma(\Gamma(\<\alpha|X\o\> X\t{}_{+}, X\t{}_{-}), b)\\
     =& [\alpha|X]\CG b.
\end{align*}
And
\begin{align*}
