	\noindent \textbf{Notation.} For a Hilbert space $\X$, let $\langle \cdot , \cdot \rangle_{\X}$ denote the inner product and $\| \cdot \|_{\X}$ the norm on $\X$. Throughout this paper, we tacitly identify, \blue{by virtue of Riesz' theorem}, the Hilbert space $\X$ with its dual space $\X^*$. The (unbounded) adjoint of a densely defined linear operator $A \colon \dom (A) \subset \X \to \X$ is denoted by $A^* \colon \dom(A^*) \subset \X\to \X$, see \Cref{app:operators} for a precise definition. The space of bounded, linear operators between two Banach spaces $X$ to $Y$ is denoted by $\mathcal L(X,Y)$ and we abbreviate $\mathcal L(X)\coloneqq \mathcal L(X,X)$. 
	For Lebesgue and Sobolev spaces, we use the standard notation, such as in \cite{adams2003sobolev}. \blue{For example $\LL^2(\Omega)$ denotes the space of square-integrable functions over a domain $\Omega$ in $\mathbb{R}^d$, while $\HH^1(\Omega)$ stands for the subspace of weakly differentiable functions with square integrable first derivatives.  For functions with values in a Banach space $\X$, we understand integration in the Bochner sense, and in notation we indicate this by adding ``$;\X$'' after the domain $\Omega$; for instance, we write $\LL^2(\Omega; \X)$ for the space of square-integrable, $\X$-valued functions.}

	\section{Problem formulation}\label{sec:ProbForm}
	In this section, we state the optimal control problem of interest and provide the main idea of our splitting method. The results are stated for linear-quadratic optimal control problems that occur, e.g., in each step of a sequential quadratic programming (SQP) or active set method for non-linear problems.  %
	\subsection{The optimal control problem}
	Let $\X,\U,\Y$ be Hilbert spaces. In this work, we consider the optimal control problem 
	\begin{subequations}
		\label{eq:ocp}
		\begin{align}
			\label{eq:ocp:cost}
			\blue{\min_{u\in \LL^{2}([0,T];\U)} \int_0^T} &\blue{\| Cx(t) - y_{\rf}(t)\|_{\Y}^{2} + \alpha\|u(t)\|_{\U}^{2}\,\mathrm{d}t}\\
			%
			\text{subject to }\qquad  \dot x(t) &= Ax(t) + Bu(t), \quad x(0)=x_{0}\label{eq:ocp:constraint}
		\end{align}
	\end{subequations}
	with the following standing assumptions:
	\begin{enumerate}[label=\roman*)]
		\item $A\colon \dom(A) \subset \X \to \X $ generates a $C_0$-semigroup $(\sg(t))_{t\ge 0}$ on $\X$, that is,
		\begin{enumerate}
			\item[a)] $\sg(t) \in \mathcal L(\X)$ for all $t\geq 0$;
			\item[b)] $\sg(0)= \id$;
			\item[c)] $\sg(t+s) = \sg(t)\sg(s)$ for all $t,s\geq 0$;
			\item[d)] For every $x_0\in \X$, $\|\sg(t)x_0 - x_0\|_{\X}\to 0$, i.e., $t\mapsto \sg(t)$ is strongly continuous at the origin.
		\end{enumerate}
		\item $B \in \mathcal L(\U,\X)$, $C \in \mathcal L(\X,\Y)$,
		\item $T>0$ is a fixed time horizon,
		\item $y_\rf \in \LL^2([0,T];\Y)$, $\alpha>0$ and $x_0\in \X$.
	\end{enumerate} 
	\blue{For the theory of $C_0$-semigroups we refer, e.g., to the books by Engel, Nagel \cite{EngeNage00} and Pazy \cite{Pazy83}.}
	%


	We briefly \blue{recall} the solution concepts which we will utilize in this work, see also \Cref{app:sols}. Consider a Cauchy problem
	\begin{align}\label{eq:firstcauchy}
		\dot x(t) = Ax(t) + f(t), \qquad x(0)=x_0.
	\end{align}
	We call $x\in \HH^1([0,T];\X)\cap \LL^2([0,T];\dom(A))$ a \emph{weak solution} if it solves \eqref{eq:firstcauchy} pointwise almost everywhere. For general evolution equations, and in particular for problems without a smoothing effect, such as hyperbolic equations,  weak solutions generally only exists for smooth data, that is, when $x_0\in \dom(A)$ and $f\in \HH^1([0,T];\X)$.
	%
	For $f\in \LL^1([0,T];\X)$ and $x_0\in \X$ the \emph{mild solution} $x\in \Ce([0,T];\X)$ is given by the variation of constants formula
	\begin{align*}
		x(t) = \sg(t)x_0 + \int_0^t \sg(t-s)f(s)\,\mathrm{d}s \quad \forall t\geq 0,
	\end{align*}
	which, for smooth data, coincides with the weak solution, see \Cref{app:sols}.
	Hence, in view of the optimal control problem~\eqref{eq:ocp}, the mild and weak solution of \eqref{eq:ocp:constraint} is defined by requiring the validity of the above formulas for $f = Bu$. %
	%
	%
	%
		%
		%

	This abstract setting via $C_0$-semigroups allows for an all-at-once treatment of a variety of PDEs such as wave equations, beam equations, heat equations or (linear) equations from fluid dynamics, such as Oseen equations, see \cite{EngeNage00,Pazy83,BensDaPr07} and the references therein. For a correspondence of semigroups to form methods often used in variational theory, the interested reader is referred to \cite{ArenElst12}. %

	In the following, we will without loss of generality set $\alpha =1 $, which may be achieved by rescaling the norm in $U$, i.e., $\|\cdot\|_{\U} \rightarrow \sqrt{\alpha} \|\cdot\|_{\U}$. Moreover, we note that one can include source terms in the dynamics \eqref{eq:ocp:constraint} straightforwardly, or replace the control penalization with $\alpha\|u-u_\mathrm{ref}\|_{\U}^2$; \blue{these possibilities shall be omitted here for the sake of clarity of presentation.}

	The following result providing necessary and sufficient optimality conditions directly follows from strict convexity of the cost (in the control variable) and the standard approach in calculus of variations, see e.g., \cite[Thm.~2.24]{Schaller2021} or \cite[Chapters 3\&4]{LiYo12}.
	\begin{proposition}\label{prop:optconds}
		The optimal control problem \eqref{eq:ocp} has a unique optimal state-control pair $(x,u) \in \Ce([0,T];\X)\times \LL^2([0,T];\U)$. Further, there is an adjoint state $\lambda \in \Ce([0,T];\X)$ such that for $t\in [0,T]$
		%
			%
				%
				%
				%
				%
				%
				%
			%
		\begin{subequations}
			\label{eq:optcond}
			\begin{align}
				\dot x(t) &= \phantom{-}Ax(t) + Bu(t), &&x(0)=x_0,  \label{eq:optcond:s} \\
				\dot \lambda(t) &= -A^*\lambda(t) + C^* Cx(t) - C^*y_\mathrm{ref}(t), &&\lambda(T)=0, \label{eq:optcond:a}\\
				u(t)&= \phantom{-}B^*\lambda(t), &&  \label{eq:optcond:o}
			\end{align}
		\end{subequations}
		%
		where the state equation \eqref{eq:optcond:s} and the adjoint equation \eqref{eq:optcond:a} are to be understood in mild sense and $\eqref{eq:optcond:o}$ is to be understood \blue{ in $\LL^2$. By continuity of $\lambda$ it follows directly that we can choose $u \in \Ce$, hence equation \eqref{eq:optcond:o} holds  pointwise for $t\in [0,T]$ in $\U$ (identified with $\U^*$).}
		%
	\end{proposition}
	%
		%
		%
	The system \eqref{eq:optcond} provides a coupled forward-backward system of evolution equations which serves as the basis of many numerical optimal control algorithms and which will be the basis for our \blue{method, too.}

	\blue{Next,} we eliminate the control via \eqref{eq:optcond:o} to obtain
	%
		%
			%
			%
		%
			%
			%
		%
			%
			%
		%
	\begin{subequations}
		\label{eq:optcond2}
		\begin{align}
			\dot x(t) &= \phantom{-}Ax(t) + BB^*\lambda(t),   &&x(0)=x_0,\\
			\dot \lambda(t) &= -A^*\lambda(t) + C^* Cx(t) - C^*y_\mathrm{ref}(t),   &&\lambda(T)=0,
		\end{align}
	\end{subequations}
	\blue{which is again to be understood in the mild sense.}

	Before providing in 
	\Cref{sec:backgournd} the operator-theoretic description of our approach, we briefly explain the main idea of the splitting illustrated in \Cref{fig:splitting}.
	The starting point is the necessary and sufficient coupled forward-backward system \eqref{eq:optcond2} on the full time horizon $[0,T]$ with initial data for the state, and terminal data for the adjoint  (see top of \Cref{fig:splitting}).
	Using continuity of the solutions, and similarly to a multiple shooting approach~\cite{bock1984multiple}, we may now split the time horizon into non-overlapping subintervals %
	\begin{align}\label{eq:subintervals}
		[0,T]=\bigcup_{k=1}^{\K} [t_{k-1},t_k],\quad \mathrm{with}\quad 0=t_0 < t_1 < \cdots < t_{K-1} < t_K = T
	\end{align}
	and consider the coupled forward-backward system on the subintervals $[t_{k-1},t_k],\ k \in \{1,\dots ,K\}$ given by 
	%
	%
	\begin{align*}
		\dot x_k(t) &= \phantom{-}Ax_k(t) + BB^*\lambda_k(t), &&x_k(t_{k-1})=x_{k,\ell},\\
		\dot \lambda_k(t) &= -A^*\lambda_k(t) + C^*Cx_k(t)-C^*y_{\mathrm{ref}}(t), &&\lambda_k(t_{k})=\lambda_{k,r}.
	\end{align*}
	%
	To model the continuity conditions, we have to relate the initial value $x_{k,\ell}$ to the value of the state from the left time interval, as well as the terminal value $\lambda_{k,r}$ to the adjoint of the time interval to the right.
	To this end, we pursue a system-theoretic approach and introduce artificial inputs $\vx,\vl$ (setting the initial data for the current time interval) and outputs $\wx, \wl$ (providing the boundary conditions to the neighboring intervals) to the system and get, again for $k\in \{1,\dots,K\}$ and subinterval $[t_{k-1},t_k]$,
	\begin{align*}
		\dot x_k(t) &= \phantom{-}Ax_k(t) + BB^*\lambda_k(t), &&x_k(t_{k-1})=\vx\\
		\dot \lambda_k(t) &= -A^*\lambda_k(t) + C^*Cx_k(t)-C^*y_{\mathrm{ref}}(t), &&\lambda_k(t_{k})=\vl, \\
		\wx &=  x_k(t_{k}),\\
		\wl &=  \lambda_k(t_{k-1}).
	\end{align*}
	%
	By construction, a suitable and continuous interconnection of these systems, where the outputs of system $k$ serve as inputs for system $k-1$ and $k+1$ as depicted in the bottom of \Cref{fig:splitting}, yields a solution of \eqref{eq:optcond2} in the mild sense.

