	\noindent To mathematically formalize this idea, we will provide an operator splitting of the optimality condition: A first operator models the dynamics on \blue{each and every} time interval and a second operator encodes the coupling conditions of the individual parts. In this way, we end up with an algebraic equation in function space that can be solved using a Peaceman-Rachford-type fixed-point iteration. The dissipativity of the involved operators, which is at the very heart of the proposed coupling, enables a succinct convergence analysis in a very general and highly flexible functional analytic framework.

	\section{A Peaceman-Rachford method for optimality systems}\label{sec:backgournd}


	This section is devoted to the precise mathematical and algorithmic description of the method. %
	To this end, as the main contribution of this section, we will introduce suitable operators such that the optimality system \eqref{eq:optcond2} may be equivalently formulated as a system governed by the sum of two operators. Abstractly speaking, we will show in \Cref{prop:main}, that the optimality system \eqref{eq:optcond2} is equivalent to
	\begin{align}\label{eq:PMstart}
		(M+N)z=\g
	\end{align}
	with \blue{certain} dissipative operators $M$ and $N$, \blue{appropriately chosen $g$,} to be introduced later on.
	Based on this algebraic equation, we will briefly recall the Peaceman-Rachford method. %
	\blue{For fixed $\mu>0$ the system  \eqref{eq:PMstart}  is formally equivalent to}
	\begin{align*}
		(\mu \id - M)z = (\mu \id +N)z -\g &\quad \text{ and }\quad 
		(\mu \id - N)z = (\mu \id +M)z-\g,
	\end{align*}
	which, substituting the two lines (and assuming for now that the inverses exist), yields
	\begin{align*}
		z= (\mu \id -M)^{-1}\!\left[(\mu \id +N)(\mu \id -N)^{-1}(\mu \id +M)z \!-\! \left( (\mu \id +N)(\mu \id -N)^{-1} + \id \right)\g\right].
	\end{align*} 
	\blue{Let 
		\[ F(z)\coloneqq (\mu \id -M)^{-1}\!\left[(\mu \id +N)(\mu \id -N)^{-1}(\mu \id +M)z \!-\! \left( (\mu \id +N)(\mu \id -N)^{-1} + \id \right)\g\right],\]
		so in the end we are seeking a fixed-point, i.e., a $z$ with
		\[
		z=F(z).
		\]
		The \emph{Peaceman-Rachford method} (see, \cite{PeacemanRachford,Lions1979}) is then given by the fixed-point iteration 
		\begin{align} \label{eq:PR}
			z^{i+1} = F(z^i)\quad (\text{$i$ non-negative integer)}
		\end{align}
		for a suitably chosen $z^0$.}
	\begin{remark}
		We note that the abstract splitting of the optimality system into a sum of dissipative operators as in \eqref{eq:PMstart}, being the first main contribution of this work, also enables other splitting methods such as the Douglas-Rachford scheme~\cite{DougRach56}. However, we stress that for this method, one may only deduce weak convergence due to the lack of strict convexity of \eqref{eq:ocp:cost} in $(x,u)$, see \cite[Theorem 26.11]{bauschke2011convex}, while we show strong convergence for the Peaceman-Rachford method in our second main result of \cref{thm:convergence}. An in-depth analysis of the Douglas-Rachford scheme will be subject to future work.
	\end{remark}

	%
	\blue{To evaluate $F$, only solutions of systems corresponding separately to $M$ and $N$ are necessary.} 
	%
While $M+N$ models a coupled system, i.e., the forward-backward optimality system \eqref{eq:optcond2}, the decoupled problems corresponding to $M$ and $N$ may be solved fully in parallel in a blockwise fashion, hence allowing for an efficient implementation of this method as showcased in \Cref{sec:implementation}.

%
\medskip
We will now show how to reformulate the optimality system \eqref{eq:optcond2} as the sum of two operators to achieve the splitting \eqref{eq:PMstart}. 
\blue{To this end, for $0\le \ell <r<\infty$, we consider the  vector space $\mathcal A_{[\ell,r]}^\ell
	\coloneqq \LL^2([\ell,r];\X) \times \X$, and for convenience we write
	\begin{equation*}
		\mathcal A_{[\ell,r]}^\ell \coloneqq \{f+ c\delta_\ell\mid f \in \LL^2([\ell,r];\X)\text{ and } c\in \X\}.
\end{equation*}}
\blue{We endow this space with the  inner product 
	\begin{equation*}
		\langle f_1+c_1 \delta_\ell, f_2+c_2 \delta_\ell\rangle_{\mathcal A_{[\ell,r]}^\ell}  \coloneqq \langle f_1, f_2\rangle_{\LL^2([\ell,r];\X)} +\langle c_1,c_2 \rangle_{\X} ,
	\end{equation*}
	leading to a Hilbert space.}
\blue{In an analogous manner, we define the Hilbert space
	\begin{equation*}
		\mathcal A_{[\ell,r]}^r \coloneqq \{f+ c\delta_r\mid f \in \LL^2([\ell,r];\X)\text{ and } c\in \X\}.
	\end{equation*}
	Although both spaces $\mathcal A_{[\ell,r]}^\ell$ and $\mathcal A_{[\ell,r]}^r$ are isomorphic to $\LL^2([\ell,r];\X) \times \X$ and we may think of elements in these spaces as source terms and initial resp.\ terminal conditions in the forward resp.\ backward equation.}

%
%
%
	%
	%
%
%
		%
		%
		%

		%

		Using this notation, and setting $[\ell,r]=[0,T]$, we may rewrite the boundary value problem \eqref{eq:optcond2} on the full \blue{time-horizon} via
		\begin{align*}
			\dot x &= \phantom{-}Ax + BB^*\lambda - x(0)\delta_0 + x_0\delta_0,\\
			\dot \lambda &= -A^*\lambda + C^* Cx +\lambda(T)\delta_T  - 0\delta_T,
		\end{align*}
		where for $x\in \HH^1([0,T];\X)\cap \LL^2([0,T];\dom(A))$ and $\lambda\in \HH^1([0,T];\X)\cap \LL^2([0,T];\dom(A^*))$ these equations are to be understood in $\mathcal A_{[0,T]}^0$ and $\mathcal A_{[0,T]}^T$, respectively.

		%

		To formulate the decomposition method as sketched in \Cref{fig:splitting}, we now consider boundary value problems on the subintervals, where we will write $[\ell,r]$ as a placeholder for $[t_{k-1},t_{k}]$, $k\in \{1,\ldots,K\}$. In the formulation, we want to interpret the initial value of the state at time $\ell$ and the terminal value of the adjoint at time $r$ as an input to the equation, while the terminal value of the state at time $r$ and the initial value of the adjoint at $\ell$ serve as an output (consequently serving as inputs for the neighboring systems). \blue{This will provide an equivalent formulation of the optimal control problem \eqref{eq:ocp}, see \Cref{prop:main}.}
		Thus, we define the unbounded operator 
		\begin{subequations}\label{eq:Mlrdef}
			\begin{align}
				%
				M_{[\ell,r]}\colon \mathcal A_{[\ell,r]}^r\times \mathcal A_{[\ell,r]}^\ell  \times \X^2 \supset \dom (M_{[\ell,r]}) &\rightarrow \mathcal A_{[\ell,r]}^r\times \mathcal A_{[\ell,r]}^\ell  \times \X^2 \nonumber\\
				\left(\begin{smallmatrix}
					x\\ \lambda \\ v_x \\ v_{\lambda} 
				\end{smallmatrix} \right)&\mapsto \left(\begin{smallmatrix}
					-C^{*}Cx +  \dot \lambda +A^{*}\lambda- \lambda(r) \delta_r +v_{\lambda} \delta_r\\
					\dot x-Ax+x(\ell)\delta_{\ell}  -BB^{*}\lambda -v_x \delta_{\ell}\\
					\lambda(\ell) \\
					-x(r) 
				\end{smallmatrix}\right),\label{eq:Mlrdef1}
				%
				\intertext{with domain of definition}
				\begin{split}
					\dom (M_{[\ell,r]}) \coloneqq \left(\HH^1([\ell,r];\X)\,\cap \!\right.&\left.\LL^2([\ell,r];\dom(A))\right) \\& \hspace{-0cm}\times \left(\HH^1([\ell,r];\X)\cap \LL^2([\ell,r];\dom(A^*))\right) \!\times\!  \X^2.
				\end{split}
				\label{eq:Mlrdef2}
			\end{align}
		\end{subequations}


		Here, we use the continuous embeddings $\HH^1([\ell,r];\X)\hookrightarrow A_{[\ell,r]}^\ell$ given by $x\mapsto x+x(\ell)\delta_\ell$ and $\HH^1([\ell,r];\X)\hookrightarrow A_{[\ell,r]}^r$ given by $x\mapsto x+x(r)\delta_r$. 

		While the operator $M_{[\ell,r]}$ models the dynamics of the internal intervals, we require two slightly modified variants 
		that correspond to the first and last time interval\blue{, $[0,t_1]$, $[t_{K-1},T]$}. Define $M_0 \colon \dom (M_{0})\subseteq \mathcal A_{[\ell,r]}^r\times \mathcal A_{[\ell,r]}^\ell  \times \X^2\rightarrow \mathcal A_{[\ell,r]}^r\times \mathcal A_{[\ell,r]}^\ell  \times \X^2$ and $M_T$ analogously by
		\begin{small}
			\begin{align*}
				M_0 \begin{pmatrix}
					x\\ \lambda \\ v_x \\ v_{\lambda} 
				\end{pmatrix}&=  \begin{pmatrix}
					-C^{*}Cx +  \dot \lambda +A^{*}\lambda- \lambda(t_1) \delta_{t_1} +v_\lambda\delta_{t_1}\\
					\dot x-Ax+x(t_0)\delta_{t_0}  -BB^{*}\lambda \\
					0 \\
					-x(t_1) 
				\end{pmatrix},\\
				M_T \begin{pmatrix}
					x\\ \lambda \\ v_x \\ v_{\lambda} 
				\end{pmatrix}&=  \begin{pmatrix}
					-C^{*}Cx +  \dot \lambda +A^{*}\lambda- \lambda(t_K) \delta_{t_K} \\
					\dot x-Ax+x(t_{K-1})\delta_{t_{K-1}}  -BB^{*}\lambda-v_x\delta_{t_{K-1}} \\
					\lambda(t_{K-1}) \\
					0 
				\end{pmatrix}.
			\end{align*}
		\end{small}
		In the definition of $M_0$, as there is no interval to the left \blue{of $[0,t_1]$}, the state has no input corresponding to the initial value. Correspondingly, in $M_T$, the adjoint state has no output corresponding to the terminal value as there is no interval to the right \blue{of $[t_{K-1},T]$.}
