		We now show that the sum of the operators $M$ and $N$ corresponds to the optimality system \eqref{eq:optcond2}. To this end, we first inspect the $k^{\text{th}}$ row of this sum applied to $z=(z_1,\ldots,z_K)\in \dom (M)$, that is 
		\begin{small}
			\begin{align*}
				\bigg[ &(M + N) \left(\begin{smallmatrix}
					z_1\\\vdots\\z_K
				\end{smallmatrix}\right)\bigg]_k = \\
				&=\begin{cases}
					M_0  \left(\begin{smallmatrix}
						x_1\\ \lambda_1 \\ v_{1,x} \\ v_{1,\lambda}
					\end{smallmatrix}\right) + \widetilde N   \left(\begin{smallmatrix}
						x_{2}\\ \lambda_{2} \\ v_{2,x} \\ v_{2,\lambda}
					\end{smallmatrix}\right), &\qquad\text{for $k=1$} \\[2em]
					-\widetilde N^\top   \left(\begin{smallmatrix}
						x_{k-1}\\ \lambda_{k-1} \\ v_{k-1,x} \\ v_{k-1,\lambda}
					\end{smallmatrix}\right) + M_{[t_{k-1},t_k]}  \left(\begin{smallmatrix}
						x_k\\ \lambda_k\\ \vx \\ \vl
					\end{smallmatrix}\right) + \widetilde N   \left(\begin{smallmatrix}
						x_{k+1}\\ \lambda_{k+1} \\ v_{k+1,x} \\ v_{k+1,\lambda}
					\end{smallmatrix}\right), &\qquad\text{for $k= 2, \ldots , K-1$}\\[2em]
					-\widetilde N^\top   \left(\begin{smallmatrix}
						x_{K-1}\\ \lambda_{K-1} \\ v_{K-1,x} \\ v_{K-1,\lambda}
					\end{smallmatrix}\right) + M_T  \left(\begin{smallmatrix}
						x_K\\ \lambda_K \\ v_{K,x} \\ v_{K,\lambda}
					\end{smallmatrix}\right), &\qquad\text{for $k=K$}
				\end{cases} \\ 
				&= \begin{cases}
					\begin{pmatrix}
						-C^{*}Cx_1 +  \dot \lambda_1 +A^{*}\lambda_1- \lambda_1({t_1}) \delta_{t_1} +v_{1,\lambda}\delta_{t_1}\\
						\dot x_1-Ax_1+x_1(t_{0})\delta_{t_{0}}  -BB^{*}\lambda_1 \\
						0 \\
						v_{2,x}-x_1(t_1) 
