					\begin{pmatrix}
						-C^{*}Cx_k +  \dot \lambda_k +A^{*}\lambda_k- \lambda_k({t_k}) \delta_{t_k} +v_{k,\lambda}\delta_{t_k}\\
						\dot x_k-Ax_k+x_k(t_{k-1})\delta_{t_{k-1}}  -BB^{*}\lambda_k -v_{k,x}\delta_{t_{k-1}}\\
