					\begin{pmatrix}
						-C^{*}Cx_K +  \dot \lambda_K +A^{*}\lambda_K- \lambda_K({t_K}) \delta_{t_K} \\
						\dot x_K-Ax_K+x_K(t_{K-1})\delta_{t_{K-1}}  -BB^{*}\lambda_K -v_{K,x}\delta_{t_{K-1}}\\
						\lambda_K(t_{K-1})- v_{K-1,\lambda} \\
