						x_{K}\\ \lambda_{K} \\ v_{K,x} \\ v_{K,\lambda}
					\end{pmatrix}\right) &= \begin{pmatrix}
						x\\
						\lambda
					\end{pmatrix},\\ \text{where} \quad 
					{ \color{black} x(s)\coloneqq  x_k(s) \quad \text{for } k \text{ such that }} &s \in [t_{k-1},t_k[ \text{ and } x(T)= x_K(T) \ (\text{likewise for }\lambda )
					%
