						-C^*y_\mathrm{ref\vert [t_1,t_2]}\\ 0 \\ 0 \\ 0
					\end{matrix}\right),\ldots, \left(\begin{matrix}
						-C^*y_\mathrm{ref\vert [t_{K-1},t_K]}\\ 0 \\ 0 \\ 0
					\end{matrix}\right)\right)^\top %
		\end{equation}\end{small}
		in \blue{the} weak sense.

		Then the concatenation $\begin{pmatrix}
			x\\
			\lambda
		\end{pmatrix}=\mathcal{C}z$ satisfies 
		\begin{align*}
			\begin{pmatrix}
				x,
				\lambda
			\end{pmatrix} \in \HH^1([0,T];\X)\cap \LL^2([0,T];\dom(A))\times \HH^1([0,T];\X))\cap \LL^2([0,T];\dom( A^*))
		\end{align*}
		and solves the optimality system \eqref{eq:optcond2} in \blue{the} weak sense.

		%
			%
			%
			%
			%
			%
		Conversely, if the pair $(x,\lambda)$ solves the optimality system \eqref{eq:optcond2} in \blue{the} weak sense, then there are unique $v_{x,1},\ldots,v_{x,N},v_{\lambda,1},\ldots,v_{\lambda,N}\in \X$ such that 
		\begin{small}
			\begin{align}\label{eq:restriction}
				z = \left( \left(\begin{matrix}
					x_{\vert [t_0,t_1]}\\ \lambda_{\vert [t_0,t_1]} \\ v_{1,x} \\ v_{1,\lambda}
				\end{matrix}\right),\ldots, \left(\begin{matrix}
					x_{\vert [t_{K-1},t_K]}\\ \lambda_{\vert [t_{K-1},t_K]} \\ v_{K,x} \\ v_{K,\lambda}
				\end{matrix}\right)\right) \in \dom (M)
