	\begin{proof}
		Let \eqref{eqn:MN0} hold. 
		%
		By construction, and in view of the continuity conditions at the boundaries, the concatenation $\left(\begin{smallmatrix}
			x\\
			\lambda
		\end{smallmatrix}\right)=\mathcal{C}z$ satisfies
		\[ x(t_{k-1})=x(t_k) \quad  \text{ and } \quad \lambda(t_{k-1})=\lambda(t_k), \quad k= 1,\ldots, K,\]
		i.e., $(x,\lambda) \in \HH^1([0,T];\X)^2$ solves \eqref{eq:optcond2} in \blue{the} weak sense.

		Conversely, let $(x,\lambda)$ solve \eqref{eq:optcond2}. Then, restricting the adjoint and state dynamics to the subintervals $[t_0,t_1] \ldots [t_{K-1},t_K]$, and introducing the artificial variables
		\begin{align*}
			v_{k,x} = x(t_k), \qquad v_{k,\lambda} = \lambda(t_k),
		\end{align*} 
		\blue{we see  that $z$ as defined in \eqref{eq:restriction} solves \eqref{eqn:MN0}.} Uniqueness is verified straightforwardly by eliminating the auxiliary variables $v_{1,x},\ldots,v_{K,x},v_{1,\lambda},\ldots,v_{K,\lambda}\in \X$ in \eqref{eqn:MN0}. %
	\end{proof}

	\blue{We will show later that the analog of \Cref{prop:main} naturally holds for mild solutions. For this purpose the closure of the operator $M$ needs to be discussed, which is done in the next section.}
