For the convergence proof of the Peaceman-Rachford iteration \eqref{eq:PR}, we will require an additional assumption on the $C_0$-semigroup generated by $A$ in \eqref{eq:ocp}, namely we will assume that it is indeed a $C_0$-group.%
\blue{\begin{definition}
		We say that $A$ is the infinitesimal generator of the \emph{$C_0$-group} $(\sg(t))_{t\in \R}$ if $A$ generates $(\sg(t))_{t\geq0 }$ and the properties in a)--d) after \eqref{eq:ocp} are satisfied for all $t\in \R$.
\end{definition}}
If $(\mathcal{T}(t))_{t\in \R}$ is a $C_0$-group, then for all $t\in \R$, $\sg(t)$ is invertible and $\sg(t)^{-1} = \sg(-t)$. Intuitively speaking, this means that the dynamics are time-reversible, and this property is satisfied by many hyperbolic equations such as wave or beam equations, as well as every finite-dimensional system; in applications to partial differential equations, this property may usually be easily verified using Stone's theorem \cite[Ch.~II, Thm.~3.24]{EngeNage00} stating the equivalence of skew-adjointness of the generator $A$ and $(\sg(t))_{t\in \R}$ being a unitary $C_0$-group. However, we stress that this assumption does not hold for heat equations due to their strong smoothing effect. However, we will still illustrate in the numerical results of \Cref{subsec:heat} that our proposed method performs well for a heat equation, motivating future work. %
%

In the following result, to ensure surjectivity of the involved operators, we will utilize the closure of the operator governing the optimality system. %
We will later show that this, at first abstract, operator theoretic concept corresponds to mild solutions being a generalization of the weak solutions considered before. Note that mild solutions, requiring only initial values in $\X$ and integrable source terms, are the natural solution concept for evolution equation without smoothing effect. Again, we refer the reader to~\Cref{app:sols}.

\begin{proposition}\label{prop:diss}
	Let $A$ generate a $C_0$-group on $\X$. Then $\M_{[\ell,r]}$, $\M_0$ and $\M_T$ are densely defined and maximally dissipative. 
\end{proposition}
\begin{proof}
	We verify the claimed properties for $\M_{[\ell,r]}$; the proof for the properties of $\M_0$ and $\M_T$ are completely analogous.

	\textit{\blue{Density of domain}.} Let $f\in \LL^2([\ell,r];\X)$ and $c\in \X$. Then, by a straightforward modification of \cite[Lemma 2.3]{Schiela13}, one may construct a sequence $(f_n)_n\in \HH^1([\ell,r];\X)$ such that $f_n(\ell)=c$ and $f_n\rightarrow f$ in $\LL^2([\ell,r];\X)$, which shows the density.
	%

	For the maximal dissipativity we have to show that $M_{[\ell,r]}$ (and hence also its closure) is dissipative and $\mu \id -\M_{[\ell,r]}$ is surjective for some $\mu >0$ (see \Cref{lem:inv}). 
	%

	\textit{Dissipativity.}  Let $W \coloneqq \mathcal A_{[\ell,r]}^r\times \mathcal A_{[\ell,r]}^\ell  \times \X^2$ with inner product $\langle \cdot , \cdot \rangle_{W} $. For $(x,\lambda,v_x,v_\lambda)\in \mathcal D(M_{[\ell,r]})$, we compute     
	\begin{align} 
		&\re\left\langle \left(\begin{smallmatrix}
			x+ x(r)\delta_r\\ \lambda+ \lambda(\ell)\delta_\ell \\ v_x \\ v_{\lambda} 
		\end{smallmatrix}\right), M_{[\ell,r]} \left(\begin{smallmatrix}
			x+ x(r)\delta_r\\ \lambda+ \lambda(\ell) \delta_\ell \\ v_x \\ v_{\lambda} 
		\end{smallmatrix}\right) \right\rangle_{W} \notag \\
		& = \re\left\langle \left(\begin{smallmatrix}
			x+ x(r)\delta_r\\ \lambda+ \lambda(\ell) \delta_\ell \\ v_x \\ v_{\lambda} 
		\end{smallmatrix}\right), \left(\begin{smallmatrix}
			-C^{*}Cx +  \dot \lambda +A^{*}\lambda - \lambda(r) \delta_r +v_\lambda\delta_r\\
			\dot x-Ax+x(\ell)\delta_{\ell}  -BB^{*}\lambda  -v_x\delta_{\ell}\\
			\lambda(\ell) \\
			-x(r) 
		\end{smallmatrix}\right) \right\rangle_{W} \notag \\
		&= -\| Cx\|^2_{\LL^{2}([\ell,r];\Y)} + \re\langle x, \dot \lambda \rangle_{\LL^{2}([\ell,r];\X)}  + \re\langle x,A^* \lambda \rangle_{\LL^{2}([\ell,r];\X)} - \re \langle x(r),\lambda(r)\rangle \notag \\& \hspace{.5cm} + \re\langle x(r), \vl\rangle 
		- \|B^* \lambda \|^2_{\LL^{2}([\ell,r];\U)}  + \re\left\langle \lambda , \dot x \right\rangle_{\LL^{2}([\ell,r];\X)} - \re\langle \lambda, Ax \rangle_{\LL^{2}([\ell,r];\X)} \notag \\
		&\hspace{.5cm} + \re \langle \lambda(\ell) ,x(\ell)\rangle - \re \langle \lambda(\ell),v_x\rangle +  \re \langle v_x  ,\lambda(\ell)\rangle - \re \langle v_\lambda ,x(r)\rangle \nonumber\\
		&= -\| Cx\|^2_{\LL^{2}([\ell,r];\Y)} - \|B^* \lambda \|^2_{\LL^{2}([\ell,r];\U)} \le 0,\nonumber 
	\end{align}
	where the last equality follows from integration by parts, that is, $\re\langle x, \dot \lambda \rangle_{\LL^{2}([\ell,r];\X)}=\, \re\langle x(r),\lambda(r)\rangle - \re \langle x(\ell),\lambda(\ell)\rangle - \re \langle \lambda ,\dot x \rangle_{\LL^{2}([\ell,r];\X)}$.
	This implies the dissipativity. 
	\smallskip


	\textit{Density of $\ran (\mu \id -M_{[\ell,r]})$ in $\mathcal A_{[\ell,r]}^r \times \mathcal A_{[\ell,r]}^\ell \times \X^2$ for some (hence all) $\mu>0$.}
	Let $\mu=1$ and $b\coloneqq \left(\begin{smallmatrix}
		f+ c\delta_r\\ g+ d \delta_\ell \\ v \\ w
	\end{smallmatrix}\right) \in W \coloneqq \mathcal A_{[\ell,r]}^r\times \mathcal A_{[\ell,r]}^\ell  \times \X^2$ be arbitrary. Due to density of $\HH^1([\ell,r];X)\times \dom(A) \times \HH^1([\ell,r];X)\times \dom(A^*)  \times \dom(A) \times \dom(A^*)$ in $W$, there is 
	\begin{align*}
		\blue{(b_n)_n}\coloneqq 
		\left(\begin{smallmatrix}
			f_n+ c_n\delta_r\\ g_n+ d_n \delta_\ell \\ v_n \\ w_n
		\end{smallmatrix}\right)_n \!\!\!\subset \!\HH^1([\ell,r];X) \!\times\! \dom(A) \!\times\! \HH^1([\ell,r];X)\!\times\! \dom(A^*) \! \times\! \dom(A) \!\times\! \dom(A^*)
	\end{align*}
	such that $b_n \to b$ in $W$. Due to \Cref{lem:exsol} and \Cref{cor:groupinv}, however, for all $n\in \mathbb{N}$, there is \blue{$z_n\coloneqq (x_n,\lambda_n,v_{x,n},v_{\lambda,n})_n \in [\Ce([\ell,r];\dom(A))\cap \Ce^1([\ell,r];\X)] \times [\Ce([\ell,r];\dom(A^*))\cap \Ce^1([\ell,r];\X)] \times X\times X$}
	solving the boundary value problem     
	%
	%
		%
		%
		%
		%
	%
		%
			%
			%
			%
			%
			%
			%
			%
			%
		%
			%
			%
			%
			%
			%
		%
	%
	\begin{align*}
		\dot x_n &=  Ax_n  +(\id+BB^{*})\lambda_n -g_n    &&\text{ on } [\ell,r]\\
		\dot \lambda_n &=   (\id+C^{*}C)x_n -A^{*}\lambda_n -f_n  &&\text{ on } [\ell,r]\\
		2 x_n(r) + \lambda_n(r)  &=c_n +w_n  \\
		2\lambda_n(\ell) -x_n(\ell) &=  d_n -v_n 
		%
		%
		%
		%
	\end{align*} 
	%
	%
		%
	%
	such that, setting $v_{x,n}  = v_n +\lambda_n(\ell)$ and $v_{\lambda,n}  =w_n-x_n(r)$, one may easily check that
	\begin{align*}
		(\id - M_{[\ell,r]}) z_n = b_n.
	\end{align*}
	Thus, $b_n \in \ran( \id - M_{[\ell,r]})$ which shows the claim. 

	\noindent \blue{Finally, by \cite[Ch.~II, Thm.~3.14]{EngeNage00} it follows that $\ran (\mu \id - \overline{M}_{[\ell,r]}) = \mathcal A_{[\ell,r]}^r \times \mathcal A_{[\ell,r]}^\ell \times \X^2$.} 
	%
	%
\end{proof}
We collect the central properties of $M$ and $N$ required for the convergence proof.
\begin{corollary}\label{cor:OpMundN} Let $A$ generate a $C_0$-group on $\X$.
	\begin{enumerate}%
		\item[\emph{(i)}] The operator $\M\colon \dom (\overline{M})\subset \Z \rightarrow \Z$ is maximally dissipative and satisfies, for all $z\in \dom (\M)$, %
		\begin{align*}
			\re\left\langle 
			z
			%
			%
				%
				%
				%
				%
			, \overline{M} 
			z
			%
				%
				%
				%
				%
			\right\rangle_\Z = -\| Cx\|^2_{\LL^{2}([0,T];\Y)} - \|B^* \lambda \|^2_{\LL^{2}([0,T];\U)} \quad \mathrm{with} \quad \begin{pmatrix}
				x\\
				\lambda
			\end{pmatrix}=\mathcal{C}z,
		\end{align*}
		where the concatenation operator $\mathcal{C}$ is defined in \eqref{eq:concatenation}.
		\item[\emph{(ii)}] $N\in \mathcal L(\Z)$ is skew-symmetric.
	\end{enumerate}
\end{corollary}
\begin{proof}
	We first prove (i): The maximal dissipativity of $M$ follows directly from its blockwise definition \eqref{eq:defnM} and the maximal dissipativity of the individual blocks proven in \Cref{prop:diss}.
	The desired equality follows from summing the dissipation inequality from the first part of the proof of \Cref{prop:diss} over all time intervals. %

	The second claim (ii) follows directly from the definition of $N$ in \eqref{eq:defN}.
\end{proof}
We briefly analyze the \blue{\emph{role of the closure}} occurring in \Cref{prop:diss}. While it clearly is necessary to consider the closure for surjectivity of the iteration matrix \blue{$\mu \id - M$} following from surjectivity of the individual blocks $(\mu \id - M_{[\ell,r]})$, it is not immediately \blue{obvious} if this closure again corresponds to a boundary problem that may be approached numerically. The following result provides this relation.
\begin{proposition}\label{prop:closure}
	Consider $M_{[\ell,r]}$ as defined in \eqref{eq:Mlrdef} and its closure $\overline{M}_{[\ell,r]}$. Abbreviate  $W =\mathcal A_{[\ell,r]}^r \times \mathcal A_{[\ell,r]}^\ell \times \X^2$. Then the following hold:
	\begin{itemize}
		\item[\emph{(i)}] $\HH^1([\ell,r];X)\times \dom(A) \times \HH^1([\ell,r];X)\times \dom(A^*)  \times \dom(A) \times \dom(A^*) \subset \ran(M_{[\ell,r]})$; in particular, $\ran(M_{[\ell,r]})$ is dense in $W$.
		\item[\emph{(ii)}] $M_{[\ell,r]}$ is boundedly invertible on its range and for every $(f+c \delta_r,g+d\delta_\ell,v,w)\in \ran(M_{[\ell,r]})$,
		\begin{align*}
			M_{[\ell,r]}^{-1} (f+c \delta_r,g+d\delta_\ell,v,w) = (x,\lambda,v_x,v_\lambda),
		\end{align*}
		where the weak solution $(x,\lambda,v_x,v_\lambda)\in \dom(M_{[\ell,r]})$ is uniquely defined by the variation of constants formulas
		\begin{align}\label{eq:solformula}
			\begin{split}
				x(t) &= \sg(t-\ell)d + \int_\ell^t \sg(t-s)(BB^*\lambda(s) - g(s))\,\mathrm{d}s\\
				\lambda(t) &= \sg^*(r-t)c + \int_t^r \sg(s-t)(C^*Cx(s) - f(s))\,\mathrm{d}s
			\end{split}
		\end{align}
		and $v_x = v-x(r)$ as well as $v_\lambda = w-\lambda(\ell).$
		\item[\emph{(iii)}] Denote by $(M_{[\ell,r]}^{-1})_e \colon \Z \to \Z$ the continuous extension of $M_{[\ell,r]}^{-1}\colon \ran M_{[\ell,r]} \to W$ (which exists due to (i) and (ii)). Then the following hold:
		\begin{itemize}
			\item[\emph{(a)}] For all $(f+c \delta_r,g+d\delta_\ell,v,w)\in W$, 
			\begin{align*}
				(M_{[\ell,r]}^{-1})_e (f+c \delta_r,g+d\delta_\ell,v,w) = (x,\lambda,v_x,v_\lambda)
			\end{align*}
			where $(x,\lambda,v_x,v_\lambda)\in W$ is uniquely defined by \eqref{eq:solformula}, i.e., in particular, $(x,\lambda) \in \Ce([\ell,r];X)^2$ is a pair of mild solutions.
			\item[\emph{(b)}] $(M_{[\ell,r]}^{-1})_e$ is a left inverse of $\overline{M}_{[\ell,r]}$, i.e.,
			\begin{align*}
				(M_{[\ell,r]}^{-1})_e \overline{M}_{[\ell,r]} z = z \quad  \forall z\in \dom(\overline{M}_{[\ell,r]}).
			\end{align*}
			\item[\emph{(c)}] $(M_{[\ell,r]}^{-1})_e$ is a right inverse of $\overline{M}_{[\ell,r]}$, i.e., $\ran \big((M_{[\ell,r]}^{-1})_e\big) \subset \dom(\overline{M}_{[\ell,r]})$ and 
			\begin{align*}
				\overline{M}_{[\ell,r]} (M_{[\ell,r]}^{-1})_e b = b \quad \forall b\in W.
			\end{align*}
			\item[\emph{(d)}] Let $(f+c \delta_r,g+d\delta_\ell,v,w)\in \ran(M_{[\ell,r]})$. Then
			\begin{align*}
				(x,\lambda,v_x,v_\lambda) = (M_{[\ell,r]}^{-1})_e (f+c \delta_r,g+d\delta_\ell,v,w)\
			\end{align*}
			if and only if $(x,B^*\lambda)\in \Ce([\ell,r];X)\times \LL^2([0,T];U)$ %
			is the optimal state-control pair of
			\begin{align}
				\label{eq:ocp:aux}
				\begin{split}
					\min_{u\in \LL^{2}([\ell,r];\U)} \int_\ell^r & \|Cx(t)\|_\Y^2 + \langle x(t),f(t)\rangle_\X + \|u\|_\U^2 \,\mathrm{d}t + \langle {\color{black}\lambda (r)},c\rangle\\
					\text{subject to }\quad  \dot x(t) &= Ax(t) + Bu(t) + g(t), \quad x(\ell)=d %
				\end{split}
			\end{align}
		\end{itemize}
		and $v_x = v-x(r)$, $v_\lambda = w-\lambda(\ell)$.
	\end{itemize}
\end{proposition}
\begin{proof}
	(i): We show that $\HH^1([\ell,r];X)\times \dom(A) \times \HH^1([\ell,r];X)\times \dom(A^*)  \times \dom(A) \times \dom(A^*)\subset \ran(M_{[\ell,r]})$ which implies the density of the latter due to density of the former. To this end, let $(f,d,g,c,v,w)\in \HH^1([\ell,r];X)\times \dom(A) \times \HH^1([\ell,r];X)\times \dom(A^*)  \times \dom(A) \times \dom(A^*)$. By \Cref{lem:exsol}, there is a unique \blue{mild} solution of
	\begin{align*}
		\dot x &=  Ax  +BB^{*}\lambda -g \quad \ \, \mathrm{on}\ [\ell,r],   && x(\ell) = d,\\
		\dot \lambda &=   C^{*}Cx -A^{*}\lambda -f \quad \mathrm{on}\  [\ell,r], &&  \lambda(r) = c.
		%
		%
	\end{align*}   
	If we set $v_{x}=v - x(r)$ and $v_{\lambda} = w {\color{black}-} \lambda(\ell)$ then $z = (x,\lambda,v_{x},v_{\lambda}) \in \dom( M_{[\ell,r]})$ satisfies  $M_{[\ell,r]} z = b$, \blue{so} $b\in \ran(M_{[\ell,r]})$.

	(ii): The fact that $M_{[\ell,r]}$ is boundedly invertible on its range follows from the same argumentation as in \cite[Thm.~2.38]{Schaller2021} by suitably testing of the corresponding optimality system. The fact that the unique solution is given by the variation of constants formula may be directly verified by differentiation, after approximating the data by smooth functions using density of $\HH^1([\ell,r];X)\times \dom(A) \times \HH^1([\ell,r];X)\times \dom(A^*)  \times \dom(A) \times \dom(A^*)$ in $\ran(M_{[\ell,r]})$ as shown in~(i).

	(iii) (a): \blue{By the density proven in (i), we can take} $b_n \in \ran M_{[\ell,r]}$ such that $b_n \to b   = (f+c\delta_r,g+d\delta_\ell,v,w)$ in $W$. Then, by definition of an extension, $z \coloneqq (M^{-1}_{[\ell,r]})_e b \coloneqq  \lim_{n\to \infty} M^{-1}_{[\ell,r]} b_n$. Set $z_n \coloneqq (x_n,\lambda_n,v_{x,n},v_{\lambda,n})\coloneqq  M^{-1}_{[\ell,r]} b_n$ which solves, due to (ii), \eqref{eq:solformula}.  As $z_n \to z$ and $b_n \to b$ in $W$, and by continuity of all involved expressions, for all $t\in [\ell,r]$ the right-hand side in \eqref{eq:solformula} converges such that the left-hand side also converges, implying that $(x,\lambda)\in \Ce([\ell,r];X)^2$ is indeed a mild solution satisfying \eqref{eq:solformula}. Hence, also $v_{x,n} \to v_x$ and $v_{\lambda,n} \to v_\lambda$.

	\noindent (b): Let $z\in \dom(\overline{M}_{[\ell,r]})$. Then by definition of the closure, there is $(z_n) \subset \dom(M_{[\ell,r]})$ such that $M_{[\ell,r]} z_n \to b \eqqcolon  \overline{M}_{[\ell,r]}z \in W$. By continuity of the extension $(M_{[\ell,r]}^{-1})_e$,
	\begin{align*}
		(M_{[\ell,r]}^{-1})_e \overline{M}_{[\ell,r]}z  = (M_{[\ell,r]}^{-1})_e \lim_{n\to \infty} M_{[\ell,r]} z_n = \lim_{n\to \infty} (M_{[\ell,r]}^{-1})_e M_{[\ell,r]} z_n = \lim_{n\to \infty} z_n = z,
	\end{align*}
	where in the second last equality we used that $M_{[\ell,r]} z_n \in \ran(M_{[\ell,r]})$ and the property of being an extension, that is, $(M_{[\ell,r]}^{-1})_e = M_{[\ell,r]}^{-1}$ on $\ran(M_{[\ell,r]})$.

	\noindent (c): We first show $\ran \big((M_{[\ell,r]}^{-1})_e\big) \subset \dom(\overline{M}_{[\ell,r]})$. Let $z \in \ran \big((M_{[\ell,r]}^{-1})_e\big)$, that is, there is $b \in W$ such that $z = (M_{[\ell,r]}^{-1})_e b$. By definition of the extension, there is $(b_n) \subset \ran(M_{[\ell,r]})$ such that $(M_{[\ell,r]}^{-1})_e b = \lim_{n\to \infty} M_{[\ell,r]}^{-1}b_n$. Setting $z_n \coloneqq  M_{[\ell,r]}^{-1}b_n \in \dom(M_{[\ell,r]})$ for $n\in \mathbb{N}$ we thus have that $z_n\to z$ and $M_{[\ell,r]}z_n = b_n \to b\in W$. Hence, $z_n\in \dom(\overline{M}_{[\ell,r]})$. Further, by the definitions above and the definition of the closure,
	\begin{align*}
		\overline{M}_{[\ell,r]} (M_{[\ell,r]}^{-1})_e b = \overline{M}_{[\ell,r]} \lim_{n\to \infty} M_{[\ell,r]}^{-1}b_n = \lim_{n\to \infty}  M_{[\ell,r]} M_{[\ell,r]}^{-1}b_n = \lim_{n\to \infty} b_n = b.
	\end{align*}

	\noindent (d): The optimality conditions of \eqref{eq:ocp:aux} read
	\begin{align*}
		\dot x(t) &= \phantom{-}Ax(t) + Bu(t) + g(t), &&x(\ell)=d,   \\
		\dot \lambda(t) &= -A^*\lambda(t) + C^* Cx(t) + f(t), &&\lambda(r)=c, \\
		u(t)&= \phantom{-}B^*\lambda(t), &&  
	\end{align*}
	in a mild sense on $[\ell,r]$ which follows by a straightforward adaption of \Cref{prop:optconds}. Setting $v_x = v - x(r)$ and $v_\lambda = w-\lambda(\ell)$, we have that $(x,\lambda,v_x,v_\lambda) = (M_{[\ell,r]}^{-1})_e (f+c\delta_r,g+d\delta_\ell,v,w)$ due to (ii). The converse direction follows as the optimality conditions are also sufficient due to the linear-quadratic nature of~\eqref{eq:ocp:aux}.
\end{proof}
%
%

We briefly comment on the previous result.
\begin{remark}\label{rem:gehtauchmild} 
	\Cref{prop:closure} (iii) (a)-(c) states that there is a natural extension to interpret the system \eqref{eqn:MN0} (originally understood in \blue{the} weak sense) also in a mild sense, cf.\ also \Cref{app:sols}. This is done via the variation of constants formulas which is central in semigroup theory. %
	The same applies also to the optimality system \eqref{eq:optcond}.


	\Cref{prop:closure} (iii) (d) yields an interpretation of the blockwise inverse occuring for $(\mu \id - M)$ in terms of localized optimality systems. In this way, the proposed iteration \eqref{eq:PR} may be interpreted as an iterative solution of temporally localized optimal control problems and hence as a distributed optimization algorithm.

	Note that, for general evolutions equations, existence of weak solutions to the optimality system is only guaranteed if the data is smooth enough, that is, $x_0\in \dom(A)$ and $C^*y_\mathrm{ref}\in \HH^1([0,T];\X)$ (see \Cref{app:sols}). In contrast, mild solutions are already given for $x_0\in \X$ and $C^*y_\mathrm{ref}\in \LL^1([0,T];\X)$.
\end{remark}

\noindent We may now prove our convergence result for the Peaceman-Rachford iteration~\eqref{eq:PR}. Note that we formulate it for weak solutions, that is, for $z\in \dom(M)$ corresponding to solutions $(x,\lambda)\in \HH^1([0,T];\X)^2$ of the optimality systems; however in view of the above \cref{rem:gehtauchmild}, it naturally extends also to mild solutions $(x,\lambda)\in \Ce([0,T];\X)^2$ obtained from solving the optimality system involving the closure $\overline{M}$.

%
\begin{theorem}\label{thm:convergence}
	%
	%
	%
	%
		%
		%
		%
		%
		%
		%
	Let $z^0 \in \dom (M)$ and $\mu>0$ and let the iterates $(z^i)_i \in  \dom(M)$ be defined by \eqref{eq:PR}. Let by $z\in \dom (M)$ solve \eqref{eqn:MN0}. %
	%
	%
		%
		%
		%
		%
		%
		%
	%
	Denote the corresponding concatenated state and adjoints of the iterate by $x^i,\lambda^i,x,\lambda \colon [0,T]\rightarrow \X$ defined by
	\begin{align*}
		\begin{pmatrix}
			x^i\\
			\lambda^i
		\end{pmatrix}=\mathcal{C}z^i,\qquad \begin{pmatrix}
			x\\
			\lambda
		\end{pmatrix}=\mathcal{C}z
	\end{align*}
	and assume that the initial guess $(x^0,\lambda^0)$ satisfies the initial resp.\ terminal condition $x^0(0)=x_0$ and $\lambda^0(T)=0$. Then the following hold:
	%
	%
	%
	\begin{enumerate}%
		\item[\emph{(i)}] The sequence $(\|z-z^i\|_\Z)_i$ converges and is bounded by a monotonically decreasing sequence.
		\item[\emph{(ii)}] We have
		\[ \| C(x-x^i)\|_{\LL^2([0,T];\Y)}^2 +\| B^*(\lambda-\lambda^i)\|_{\LL^2([0,T];\U)}^2 \rightarrow 0 \quad \text{as} \quad k \to \infty. \]
		In particular, the cost functional of the iteration converges to the optimal cost and the control iterates $u^i \coloneqq B^*\lambda^i$ converge to the optimal control $u=B^*\lambda$. %
		\item[\emph{(iii)}] The state and adjoint state iterates converge uniformly, i.e., 
		\[\sup_{t\in [0,T]} \| x(t) - x^i(t)\|_\X \rightarrow 0 \quad \text{as}\quad  i \to \infty, \]
		\[\sup_{t\in [0,T]} \| \lambda(t) - \lambda^i(t)\|_\X \rightarrow 0 \quad \text{as}\quad  i \to \infty. \]
	\end{enumerate}
\end{theorem}
\begin{proof}
	We start by proving statement (i).
	Let $f \coloneqq (\mu \id -M)z$ and for $i \in \mathbb N$, set %
	\begin{align*}
		f^i \coloneqq (\mu \id -M)z^i,\quad  \Delta z^i \coloneqq z - z^i, \quad \Delta f^i \coloneqq f-f^i.
	\end{align*}
	In view of the iteration \eqref{eq:PR}, we calculate
	\begin{align}
		\Delta f^{i+1} &= (\mu \id -  M)(\mu \id - M)^{-1}(\mu \id + N)(\mu \id -  N)^{-1} (\mu \id+ M)\Delta z^i\notag\\
		&= (\mu \id + N)(\mu \id - N)^{-1} (\mu \id +M)(\mu \id - M)^{-1}  \Delta f^i\notag\\
		&= (\mu \id +  N)(\mu \id -  N)^{-1} (2\mu \id -(\mu \id - M))(\mu \id -  M)^{-1}  \Delta f^i\notag\\
		&= (\mu \id + N)(\mu \id -  N)^{-1} (2\mu \Delta z^i - \Delta f^i).
	\end{align}
	As shown in \Cref{cor:OpMundN}, this yields the dissipation equality
	\[ \Re \langle \Delta z^i, M \Delta z^i\rangle_\Z = - \|C \Delta x^i\|^2_{\LL^2([0,T];\Y)} - \|B^* \Delta \lambda^i\|^2_{\LL^2([0,T];\U)}. \]
	Thus,
	\begin{align}
		\| \Delta f^{i+1}\|^2_\Z - \| \Delta f^i\|^2_\Z \notag &= \|(\mu \id + N)(\mu \id -  N)^{-1}  (2\mu \Delta z^i - \Delta f^i) \|^2_\Z - \| \Delta f^i\|^2_\Z\notag \\
		&\le \| 2\mu \Delta z^i - \Delta f^i \|^2_\Z - \| \Delta f^i \|^2_\Z \notag\\
		&= 4\mu^2 \| \Delta z^i\|^2_\Z - 4\mu \Re \langle \Delta z^i, \Delta f^i\rangle_{\Z} \notag\\
		&= 4\mu^2 \| \Delta z^i\|^2_\Z - 4\mu \Re \langle \Delta z^i , (\mu I - M)\Delta z^i\rangle_\Z\notag \\
		&= 4\mu \Re \langle \Delta z^i , M \Delta z^i\rangle_\Z\notag \\
		&= -4\mu \left(\| C \Delta x^i\|^2_{\LL^2([0,T];\Y)} + \|B^* \Delta \lambda^i\|^2_{\LL^2([0,T];\U)}\right) \leq 0 
	\end{align}
	Hence, the sequence $(\|\Delta f^i\|)_i$ is monotonically decreasing and therefore convergent. Resubstituting $\Delta z^i = (\mu \id - M)^{-1} \Delta f^i$ yields the first claim (i) due to dissipativity of $M$ and hence contractivity of the resolvent, that is $\|(\mu \id - M)^{-1}\|_{\mathcal L(\Z)}\leq 1.$

	%

	We proceed with (ii). Rearranging the terms in the previous inequality further implies that
	\begin{align*}
		\| C(x-x^i)\|^2_{\LL^2([0,T];\Y)} + \|B^*(\lambda - \lambda^i)\|^2_{\LL^2([0,T];\U)} \le \frac{1}{4\mu}\left(\| \Delta f^i\|^2_Z - \| \Delta f^{i+1}\|^2_Z  \right)
		\to 0.
	\end{align*}
	Substituting $u=B^*\lambda$ and $u^i=B^*\lambda^i$ directly yields convergence of the controls $u^i \to u$ in $\LL^2([0,T];\U)$. Using the converse triangle inequality, we get convergence of the cost
	\begin{align*}
		\left|\| Cx\|^2_{\LL^2([0,T];\Y)} + \|u\|^2_{\LL^2([0,T];\U)} - \left( \| Cx^i\|^2_{\LL^2([0,T];\Y)}  + \|u^i\|^2_{\LL^2([0,T];\U)}\right) \right| \to 0.
	\end{align*}
	We remain to show uniform convergence of state and adjoint state, i.e., (iii). To this end, using the convergence of the control iterates and Cauchy Schwarz inequality, we have on the first time interval $[0,t_1]$ 
	\begin{align*}
		\MoveEqLeft    \| x(t) - x^i(t)\|_\X\\
		&\le \underbrace{\|\sg(t_1)\|_{\mathcal L(\X)}}_{bdd.} \underbrace{\|x_0 - x^i(0) \|_\X}_{=\, 0} + \int_0^{t_1} \|\sg(t_1 -s)B\|_{\mathcal L(\U,\X)} \|u(s)-u^i(s)\|_\U \ds{s}\\
		&\leq \left(\int_0^{t_1} \|\sg(s)B\|_{\mathcal L(\U,\X)}^2 \ds s  \right)^{1/2}  \left( \int_0^{t_1} \|u(s)-u^i(s)\|_{\U}^2 \ds s  \right)^{1/2}\to 0
		%
	\end{align*}
	since every semigroup is bounded on bounded time intervals, $B\in \mathcal L(\U,\X)$ and due to convergence of the control.
	Repeating this step iteratively for the other time intervals $[t_{k-1},t_{k}]$, $k = 2, \dots , K$ we get an additional error in the initial states. Since mild solutions continuously depend on the initial data, we can use the convergence of the state at time $t_i$ that we obtained from the previous step and use the same estimate for the inputs. %
	%

	Analogously we can estimate the adjoints states via a simple time transformation $t \mapsto T-t$ and obtain
	\[ \|\lambda(t) - \lambda^i(t)\|_{\X} \le \|\sg^*(T-t)(\lambda_T - \lambda^i(T))\|_{\X} + \int_t^T \| \sg^*(s-t)C^*C(x(s)-x^i(s))\|_{\X} \ds s \]
	where $(\sg^*(t))_{t\ge 0}$ denotes the dual semigroup, generated by $A^*$.
	Since uniform convergence of $(x^i)_i$ to $x$ implies convergence in $\LL^2$, we can use the same computation as above, now proceeding from the last towards the first interval.
	%
\end{proof}


