\section{Solutions to initial value and boundary value problems}\label{app:sols}

%
%
	%
	%
	%

\noindent Consider the Cauchy problem
\begin{align}\label{eq:cauchydummy}
	\dot x(t) = Ax(t) + f(t) \quad \mathrm{on}\ [0,T], \qquad x(0)=x_0.
\end{align}
where $A\colon \X\supset \dom(A)\to \X$ generates a $C_0$-semigroup $(\sg(t))_{t\ge 0}$ on a Hilbert space $\X$ and $x_0\in \X$.

\begin{definition}
	Let $(x_0,f)\in \X \times \LL^1([0,T];\X)$. We say that $x\in \Ce([0,T];\X)$ satisfying $x(0)=x_0$
	\begin{itemize}
		\item[(i)] is a \emph{mild solution} of \eqref{eq:cauchydummy}, if $x\in \Ce([0,T];\X)$ and
		\begin{align*}
			x(t) - x(0) = A\int_0^t x(s)\,\mathrm{d}s \qquad \forall t \in [0,T].
		\end{align*}
		\item[(ii)] is a \emph{weak solution} of \eqref{eq:cauchydummy}, if $x\in \HH^1([0,T];\X)\cap \LL^2([0,T];\dom(A))$ and the evolution equation in \eqref{eq:cauchydummy} holds in $\LL^2([0,T];\X)\times \X$.
		%
		\item[(iii)] is a \emph{classical solution} of \eqref{eq:cauchydummy} if $x\in \Ce^1([0,T];\X)\cap \Ce([0,T];\dom (A))$ and evolution equation in \eqref{eq:cauchydummy} holds in $\Ce([0,T];\X)\times \dom(A)$.
	\end{itemize}
\end{definition}
The following result ensures existence of solutions as defined above by means of regularity of the data.
\begin{proposition}
	The following hold
	\begin{itemize}
		\item[(i)]  If $(x_0,f)\in \X \times \LL^1([0,T];\X)$, the mild solution is unique and given by the variations of constants formula
		\begin{align*}
			x(t) = \sg (t)x_0 + \int_0^t \sg (t-s)f(s)\,\mathrm{d}s.
		\end{align*}
		\item[(ii)] If $(x_0,f)\in \dom(A) \times \LL^2([0,T];\dom(A))$, then the mild solution is a weak solution.
		\item[(iii)] If $(x_0,f)\in \dom(A) \times \HH^1([0,T];\X)$, then the mild solution is a classical solution.
	\end{itemize}
\end{proposition}
\begin{proof}
	See \cite[p.133, Prop 3.3]{BensDaPr07}.
\end{proof}
Note that for parabolic equations, there is a unique weak solution already for $(x_0,f)\in ((X,\dom(A))_{1/2},\LL^2(0,T;X))$, where $(X,\dom(A))_{1/2}$ denotes an interpolation space between $\X$ and $\dom(A)$. This follows from maximal parabolic regularity, cf.\ \cite[p.130ff]{BensDaPr07}.

We conclude this part with a result for solvability of boundary value problems required for surjectivity.
\begin{lemma} \label{lem:exsol}
	Let $A\colon \dom(A) \subset \X \to \X$ generate a $C_0$-semigroup $(\sg(t))_{t\ge 0}$, let $R_0\in \mathcal L(\X)$, $R_1\in \mathcal L(\X)$. If the operator matrix $\left[\begin{smallmatrix} R_0\\R_1 \sg (r-\ell)\end{smallmatrix}\right]$ is surjective both, as a mapping from $\X$ to $\X\times \X$ and from $\dom(A)$ to $\dom(A)\times \dom(A)$
	%
	then for every $f\in \LL^2([\ell,r];\X)$ and $z_0, z_1\in \X$ the boundary value problem 
	\begin{align}\label{eq:auxbvp}
		\dot x(t)=A x(t)+f(t), \quad  (t\in[\ell,r]), \quad R_0 x(\ell)=z_0,\,  R_1x(r)=z_1,
	\end{align}
	has a continuous (mild) solution. If $f\in \HH^1([\ell,r];\X)$ and $z_0,z_1\in \dom(A)$, then this mild solution is a classical solution.
\end{lemma}
\begin{proof}%
	We first prove the claim for the mild solution. To this end, by the assumed surjectivity, there is $x_0\in \X$ such that
	\[
	\left[\begin{smallmatrix} R_0\\R_1\sg(r-\ell)\end{smallmatrix}\right]x_0=	
	\left[\begin{smallmatrix}z_0\\z_1-R_1\int_{\ell}^r \sg(r-s)f(s)\,\mathrm{d}s\end{smallmatrix}\right].
	\]
	Thus, by construction, for all $s\in [\ell,r]$
	\begin{align}\label{eq:formulasol}
		x(s) = \sg(s-\ell)x_0 + \int_{\ell}^s \sg(s-\tau)f(\tau)\,\mathrm{d}\tau
	\end{align}
	is a mild solution of the dynamics in \eqref{eq:auxbvp} and satisfies the boundary conditions
	\begin{align*}
		R_0 x(\ell) = R_0x_0=z_0,\quad
		R_1x(r) = R_1\sg(r-\ell) x_0 + R_1\int_\ell^r \sg(r-s)f(s) \,\mathrm{d}s =z_1.
	\end{align*}
	The claim for $(x_0,f)\in \dom(A)\times \HH^1([\ell,r];\X)$ follows by the same argumentation using classical solutions. %
\end{proof}





