\section{Operator theoretic auxiliary results} \label{app:operators}
In the following, $X$ is always assumed to be a Hilbert space. 
%

\begin{definition}[Adjoint]
	Let $A\colon \dom(A)\subset X \to X$ be a densely defined, linear operator. Then the adjoint of $A$ is defined by $A^*\colon \dom(A^*)\subset X \to X$ with
	\[ \dom(A^*) \coloneqq \left\{y \in \X \mid \exists z\in \X: \langle y,Ax \rangle_{\X} = \langle z,x\rangle_{\X}\  \forall x \in \dom(A)\right\}.\]
	Due to density of $\dom(A)$ in $\X$, $z$ in the above set is uniquely determined and we set $A^* y \coloneqq z$.
\end{definition}

\begin{definition}[Closure]
	Let $A\colon \dom(A) \subset \X \to \X$ be a linear operator. We say that $A$ is closable if, and only if for every sequence $(x_n)_n \subseteq \dom(A)$, $x_n \to 0$ and $Ax_n \to y$ imply $y=0$. 
	If $A$ is closable, we denote its closure by $\overline{A}:\dom(\overline{A})\subset X\to \Y$.
	\begin{align*}
		\dom(\overline A) &= \{ x \in \X \mid \exists (x_n)_n \subset \dom(A), x_n \to x \text{ s.t. } (Ax_n)_n \text{ converges} \}\\
		\overline Ax &= \lim_{n \to \infty} Ax_n, \text{ where } (x_n)_n \text{ as above.}
	\end{align*}

\end{definition}
Densely defined and dissipative operators are always closable, see \cite[Thm.~4.5]{Pazy83}.

