\section{Oracle Model Selection for CRO}\label{sec:preliminaries}

\subsection{Warm-up: CRO with conformal prediction set}

As a starting point, it is useful to examine how the CRO problem with conformal prediction sets can be efficiently solved. Suppose the collected labeled dataset $\{(X_i,Y_i)\}_{i=1}^n$ and test data $X_{n+1}$ with unknown label $Y_{n+1}$ are i.i.d. 
Let $S:\gX\times\gY \to \sR$ be a pre-trained nonconformity score function. {The $(1-\alpha)$-level conformal prediction set} takes the form
\begin{align}\label{eq:conformal_set_single_model}
    \gU(X_{n+1}) = \LRl{c\in \gY: S(X_{n+1}, c) \leq \hat{q}},
\end{align}
where the calibration threshold $\hat{q} = Q_{(1-\alpha)(1+n^{-1})}(\{S(X_i,Y_i)\}_{i=1}^n)$ is computed from labeled scores. This set enjoys the finite-sample \emph{marginal coverage} property $\sP\{Y_{n+1}\in \gU(X_{n+1})\} \geq 1-\alpha$ \citep{lei2018distribution}.
%Taking the regression setting with $\gY = \sR^p$ as an example, 

\textbf{Regression setting.}
If $\gY = \sR^p$, there are two commonly used score functions: (1) \emph{Box} score $S(x,y) = \|y-\hat{\mu}(x)\|_{\infty}$, where $\hat{\mu}(\cdot): \gX \to \sR^p$ is a multi-output prediction model; (2) \emph{Ellipsoid} score $S(x, y) = \{(y- \hat{\mu}(x))^{\top}\hat{\Sigma}(x)^{-1}(y- \hat{\mu}(x))\}^{1/2}$, where $\hat{\mu}(\cdot):\gX \to \sR^p$ and $\hat{\Sigma}(\cdot): \gX \to \sR^{p\times p}$ are the estimators of conditional mean and covariance, respectively.
Since the conformal prediction sets are convex with both box and ellipsoid scores,
the CRO problem \eqref{eq:CRO} is tractable as long as the loss function $\phi(y,z)$ is concave in $y$ and convex in $z$. To have a direct intuition on the problem \eqref{eq:CRO} under conformal prediction set, we consider the classical portfolio optimization application where $\phi(y,z) = -y^{\top}z$ with $\gZ = \{z\in [0,1]^p: \mathbf{1}^{\top}z=1\}$ and $\gY = \sR^p$ under two prediction sets with different scores.
\begin{itemize}
    \item Under the prediction set with box score, the problem \eqref{eq:CRO} is equivalent to
    \begin{align}
        z(X)=\argmin_{z\in \gZ}&\min_{c\in \sR^p}2\hat{q}\cdot \mathbf{1}^{\top}c - (\hat{\mu}(X) - \hat{q}\cdot \mathbf{1})^{\top}z,\nonumber\\
        &\text{s.t. }c \geq \boldsymbol{0},\ c-z \geq \boldsymbol{0},\nonumber
    \end{align}
    where $\mathbf{1} = (1,\ldots,1)^{\top} \in \sR^p$, $\mathbf{0} = (0,\ldots,0)^{\top} \in \sR^p$, and inequalities in the constraint are coordinate-wise. This linear programming problem can be efficiently solved using the interior-point method \citep{bertsimas1997introduction}.

    \item Under the prediction set with elliptical score, the problem \eqref{eq:CRO} is equivalent to
    \begin{align}
        z(X)&=\argmin_{z\in \gZ}\sqrt{\hat{q}}\sqrt{z^{\top}\hat{\Sigma}(X)z} + \hat{\mu}(X)^{\top}z,\nonumber
    \end{align}
    which is a convex optimization problem if $\gZ$ is convex, and can be solved by the projected gradient descent method \citep{Boyd_Vandenberghe_2004}.
\end{itemize}


\textbf{Classification setting.}
For a discrete and finite label space $\gY$, the nonconformity function can be taken as $S(x,y) = 1 - \hat{f}^y(x)$, where $\hat{f}^y(x)$ is an estimator of $\sP(Y=y\mid X = x)$, such as the softmax output of a neural network. The prediction set is given by $\gU(X_{n+1}) = \{y\in \gY: S(X_{n+1}, y) \leq \hat{q}\}$. The decision space $\gZ$ is typically a finite set. The loss function can be represented by a matrix $M \in \sR^{|\gY| \times |\gZ|}$, where $\phi(y,z) = M_{y,z}$ for $y\in \gY$ and $z\in \gZ$, and the corresponding CRO problem becomes $z(X_{n+1}) = \argmin_{z\in \gZ} \max_{y\in \gU(X_{n+1})} M_{y,z}$, which can be easily solved among a finite set of possible solutions.

In the classical CRO problem, a foundational requirement is the marginal robustness of the decision given a prediction set. Here we state the robustness definition \citep{ben2009robust} in the marginal notion.

\begin{definition}[Marginal robustness]\label{def:robustness}
    For $(X,Y) \sim P$, the prediction set $\gU(X)$ satisfies $1-\alpha$ level of marginal robustness if the CRO decision satisfies
    \begin{align}
        \sP\LRl{\phi(Y, z(X)) \leq \max_{c\in \gU(X)}\phi(c, z(X))} \geq 1-\alpha.\nonumber
    \end{align}
\end{definition}

In the above definition, $\phi(Y, z(X))$ represents the true decision loss, and $\max_{c\in \gU(X)}\phi(c, z(X))$ denotes the observed worst-case loss under the prediction set $\gU(X)$. As defined, the decision $z(X)$ ensures robustness if we use the conformal prediction set in \eqref{eq:conformal_set_single_model} since the marginal robustness can be implied by the marginal coverage.


%if the prediction set $\gU(X)$ can cover the label $Y$ with probability at least $1-\alpha$, that is $\sP\{Y\in \gU(X)\} \geq 1-\alpha$. This marginal coverage property can be guaranteed for arbitrary predictive models in conformal prediction methods \citep{vovk2005algorithmic,lei2018distribution}. 
