\subsection{Oracle model selection to minimize decision risk}

% In this section, we focus on selecting the optimal model from a sequence of {pre-trained models} $\{S_{\lambda}:\lambda\in \Lambda\}$. Suppose the corresponding conformal prediction set of each model is denoted by $\gU_{\lambda}(\cdot)$, and $z_{\lambda}(X) = \argmin_{z\in \gZ} \max_{c\in \gU_{\lambda}(X)} \phi(c,z)$ is the decision by solving CRO problem for model $\lambda$. 
% %Our goal is to select the optimal model $\lambda^*\in\Lambda$ to minimize the decision risk. %whose final decision ensures robustness and achieves decision efficiency. 
% To measure the decision efficiency, we introduce the \emph{decision risk} $\E[\phi(Y, z_{\lambda}(X))]$, where $\phi(Y, z_\lambda(X))$ is the decision loss value regarding to the decision $z_\lambda(X)$ on the true label $Y$. 
Given a sequence of {pre-trained models} $\{S_{\lambda}:\lambda\in \Lambda\}$, we begin with the oracle model selection at the population level. For the data $(X,Y)\sim P$, denote the oracle conformal prediction set of the candidate model $S_{\lambda}$ as
\begin{align}\label{eq:oracle_conformal_US}
    \gU_{\lambda}^{\mathsf{o}}(X) = \LRl{c\in \gY: S_{\lambda}(X, c) \leq q_{\lambda}^{\mathsf{o}}},
\end{align}
where the threshold $q_{\lambda}^{\mathsf{o}} = \inf\{q\in \sR: \sP\{S_{\lambda}(X,Y) \leq q\} \geq 1-\alpha\}$ is the $1-\alpha$ population quantile of score $S_{\lambda}(X,Y)$. Plugging $\gU_{\lambda}^{\mathsf{o}}(X)$ into the CRO problem \eqref{eq:CRO} leads to the decision
\begin{align}\label{eq:oracle_decision}
    z_{\lambda}^{\mathsf{o}}(X) = \argmin_{z\in \gZ}\max_{c\in \gU_{\lambda}^{\mathsf{o}}(X)} \phi(c,z).
\end{align}
By the definition of $q_{\lambda}^{\mathsf{o}}$, the marginal coverage $\sP\{Y\in \gU_{\lambda}^{\mathsf{o}}(X)\} \geq 1-\alpha$ holds naturally, and thus $\gU_{\lambda}^{\mathsf{o}}(X)$ satisfy the robustness requirement in Definition \ref{def:robustness}. To evaluate the efficiency of $z_{\lambda}^{\mathsf{o}}(X)$, we introduce the {\emph{oracle decision risk}} $\E[\phi(Y, z_{\lambda}^{\mathsf{o}}(X))]$. Accordingly, the optimal model is the one that minimizes the downstream decision risk,
\begin{align}\label{eq:oracle_optimal_model}
    \lambda^* = \argmin_{\lambda \in \Lambda}\E[\phi(Y, z_{\lambda}^{\mathsf{o}}(X))].
\end{align}
From another perspective, the oracle model selection process discussed above can be regarded as a bilevel optimization problem \citep{dempe2002foundations}, where the lower-level problem \eqref{eq:oracle_decision} provides robust solutions and the upper-level problem \eqref{eq:oracle_optimal_model} optimizes the efficiency of these solutions. 


By definition \eqref{eq:oracle_decision}, the decision $z_{\lambda^*}^{\mathsf{o}}(X)$ achieves the minimum oracle decision risk among all candidate models. Denote $v_{\Lambda}^* = \E[\phi(Y,z_{\lambda^*}^{\mathsf{o}}(X))]$ as the minimum decision risk value. We define the optimal efficiency of a data-driven decision $\hat{z}(X)$ as follows.

\begin{definition}[Asymptotic optimality ]\label{def:efficiency}
    A data-driven decision $\hat{z}(X)$ is asymptotically optimal if $\lim_{n\to \infty}\E[\phi(Y,\hat{z}(X))] = v_{\Lambda}^*$. %, where $v_{\Lambda}^* = \E[\phi(Y,z_{\lambda^*}^{\mathsf{o}}(X))]$ is the minimum decision risk.
\end{definition}




\section{Conformalized Robust Optimization with Model Selection}\label{sec:CROMS}

Suppose we have collected labeled data $\{(X_i,Y_i)\}_{i=1}^n$ and test data $X_{n+1}$, whose label $Y_{n+1}$ is unknown. In this section, we develop a data-driven framework named CROMS to perform optimal model selection by approximately solving problem \eqref{eq:oracle_optimal_model} while ensuring both marginal robustness (Definition \ref{def:robustness}) and asymptotic optimality of (Definition \ref{def:efficiency}) for the final decision. Specifically, this framework includes two viable algorithms: Efficient CROMS (E-CROMS) and Full CROMS (F-CROMS).

%In this section, we introduce two algorithms in CROMS framework: E-CROMS and F-CROMS, respectively. 

\subsection{E-CROMS: efficient selection with asymptotic efficiency}

%To achieve the target level of robustness in finite samples, CROMS in Algorithm \ref{alg:CROMS} searches over the label space to impute the true label of test data, which leads to a huge computational cost for regression tasks. 
We first propose a computationally efficient model selection approach, which achieves asymptotic optimality but at the cost of an additional $o(1)$ error in marginal robustness.

Recall that {the conformal prediction set} \eqref{eq:conformal_set_single_model} of the model $S_{\lambda}$ with $\lambda \in \Lambda$ takes the form $\gU_{\lambda}(\cdot) = \{c\in \gY: S_{\lambda}(\cdot, c) \leq \hat{q}_{\lambda}\},$ where $\hat{q}_{\lambda} = Q_{(1-\alpha)(1+n^{-1})}\LRs{ \LRl{S_{\lambda}(X_i,Y_i)}_{i=1}^n}$.
Then for the test point $X_{n+1}$, we solve the CRO problem to obtain the decision $z_{\lambda}(X_{n+1}) = \argmin_{z\in \gZ} \max_{c\in \gU_{\lambda}(X_{n+1})} \phi(c,z)$.

Under the i.i.d. assumption on data $\{(X_i,Y_i)\}_{i=1}^{n+1}$, the decision $z_\lambda(X_{n+1})$ satisfies $1-\alpha$ level of robustness due to the marginal coverage property of conformal prediction set $\gU_\lambda(X_{n+1})$ for each $\lambda\in\Lambda$. In addition, the sample quantile $\hat{q}_{\lambda}$ is a consistent estimator of the oracle quantile $q_{\lambda}^{\mathsf{o}}$, and thus the corresponding decision risk can approximate the oracle one, that is
$$
\E[\phi(Y_{n+1},z_{\lambda}(X_{n+1}))] \approx \E[\phi(Y_{n+1},z_{\lambda}^{\mathsf{o}}(X_{n+1}))].
$$
To estimate the expectation $\E[\phi(Y_{n+1},z_{\lambda}(X_{n+1}))]$, it is natural to use the labeled data to compute the \emph{auxiliary decisions}, i.e., $z_{\lambda}(X_i) = \argmin_{z\in \gZ}\max_{c\in \gU_{\lambda}(X_{i})} \phi(c,z)$ for $i\in [n]$.
Since most CRO problems are convex as discussed in Section \ref{sec:preliminaries}, this step is computationally efficient, requiring solving $n$ convex problems. We then regard those labeled decision losses $\{\phi(Y_i,z_{\lambda}(X_i))\}_{i=1}^n$ as nearly random ``copies'' of test decision loss $\phi(Y_{n+1},z_{\lambda}(X_{n+1}))$.

Next, we perform the model selection through the following ERM problem
\begin{align}\label{eq:eff_CROMS_ERM}
    \hat{\lambda}_n = \argmin_{\lambda\in \Lambda} \frac{1}{n}\sum_{i=1}^n \phi(Y_i, z_{\lambda}(X_i)).
\end{align}
Since $\Lambda$ is finite, the optimal model index $\hat{\lambda}_n$ can be easily obtained. After that, we choose the corresponding conformal prediction set as the final prediction set, i.e., $\widehat{\gU}^{\ECROMS}(X_{n+1}) = \gU_{\hat{\lambda}_n}(X_{n+1})$. The \emph{final decision} is defined as $\hat{z}^{\ECROMS}(X_{n+1}) = z_{\hat{\lambda}_n}(X_{n+1})$. We refer to this procedure as Efficient CROMS (E-CROMS) and summarize its detailed implementation in Algorithm \ref{alg:eff_CROMS}. The first theorem is about the marginal robustness of E-CROMS.

\begin{algorithm}[ht]
	\renewcommand{\algorithmicrequire}{\textbf{Input:}}
	\renewcommand{\algorithmicensure}{\textbf{Output:}}
	\caption{Efficient CROMS (E-CROMS)}\label{alg:eff_CROMS}
        \linespread{1.4}\selectfont
	\begin{algorithmic}
	\Require Pre-trained models $\{S_{\lambda}:\lambda\in \Lambda\}$, loss function $\phi$, labeled data $\{(X_{i},Y_i)\}_{i=1}^{n}$, test data $X_{n+1}$, robustness level $1-\alpha \in (0, 1)$.

        \For{$\lambda \in \Lambda$} \Comment{{Compute auxiliary decisions}}

        \State $\gU_{\lambda}(x) \gets \{c\in \gY: S_{\lambda}(x,c)\leq Q_{(1-\alpha)(1+n^{-1})}\LRs{ \LRl{S_{\lambda}(X_i,Y_i)}_{i=1}^n}\}$.

        \State $z_{\lambda}(X_i) \gets \argmin_{z\in \gZ}\max_{c\in \gU_{\lambda}(X_i)}\phi(c,z)$ for $i\in [n]$.

        %\State Compute $\phi(Y_i,z_{\lambda}^y(X_i))$ for $i\in [n]$.

        \EndFor

        \State $\hat{\lambda}_n \gets \argmin_{\lambda \in \Lambda}\frac{1}{n}\sum_{i=1}^{n} \phi(Y_i, z_{\lambda}(X_i))$.  \Comment{{Select model via ERM}}

        \State $\widehat{\gU}^{\ECROMS}(X_{n+1}) \gets \{y\in \gY: S_{\hat{\lambda}_n}(X_{n+1}, y) \leq \hat{q}_{\hat{\lambda}_n}\}$. \Comment{{Construct prediction set}}

        \State $\hat{z}^{\ECROMS}(X_{n+1}) \gets \argmin_{z\in \gZ}\max_{c\in \widehat{\gU}^{\ECROMS}(X_{n+1})}\phi(c,z)$. \Comment{{Make the final decision}}

        \Ensure Prediction set $\widehat{\gU}^{\ECROMS}(X_{n+1})$ and decision $\hat{z}^{\ECROMS}(X_{n+1})$.
	\end{algorithmic}
\end{algorithm}


%\subsection{Theoretical results of E-CROMS}

\begin{theorem}\label{thm:robustness_ECROMS}
    Assuming data $\{(X_i,Y_i)\}_{i=1}^{n+1}$ are i.i.d., the final prediction set of E-CROMS satisfies $\LRs{1+n^{-1}}(1-\alpha) - \frac{\sqrt{\log(2|\Lambda|)/2}+1/3}{\sqrt{n}}$ level of marginal robustness in Definition \ref{def:robustness}.
%  \begin{align}
%     \sP\LRl{Y_{n+1}\in \widehat{\gU}^{\ECROMS}(X_{n+1})} \geq \LRs{1+n^{-1}}(1-\alpha) - \frac{\sqrt{\log(2|\Lambda|)/2}+1/3}{\sqrt{n}}.\nonumber
% \end{align}   
%Further, the prediction set $\widehat{\gU}^{\ECROMS}(X_{n+1})$ satisfies the same level of marginal robustness.
\end{theorem}
Since the selected model $S_{\hat{\lambda}_n}$ is not symmetric to the labeled and test data, there is an $O(\sqrt{\log(|\Lambda|/n)})$ coverage gap for the final prediction set of E-CROMS. 
%In specific,
% \begin{align}
%     \sP\LRl{Y_{n+1}\in \widehat{\gU}^{\ECROMS}(X_{n+1})} \geq \LRs{1+n^{-1}}(1-\alpha) - \frac{\sqrt{\log(2|\Lambda|)/2}+1/3}{\sqrt{n}},\nonumber
% \end{align}
% which implies the robustness level in Theorem \ref{thm:robustness_ECROMS}. 
The logarithmic dependence on the size of the candidate set $\Lambda$ is the same as that of Theorem 1 in \citet{yang2024selection}, which comes from the DKW inequality. Differently, they focused on selecting the model with the minimum width of the prediction set. % has the minimum width.

Before analyzing the asymptotic efficiency of the final decision of E-CROMS, we introduce the following regular conditions on data distribution and loss function.

\begin{assumption}[Quantile estimation]\label{assum:quantile_estimation}
    Let $f_{\lambda}(\cdot)$ and $F_{\lambda}(\cdot)$ be the density function and distribution function of nonconformity score $S_{\lambda}(X,Y)$. There exists a constant $\mu > 0$ such that $f_{\lambda}(s) > \mu$ holds for any $s\in [F_{\lambda}^{-1}(1-\alpha-a_n), F_{\lambda}^{-1}(1-\alpha+a_n)]$ with $a_n = O(\sqrt{\log(n\vee |\Lambda|)/n})$, where $F_{\lambda}^{-1}(\cdot)$ is the quantile function.
\end{assumption}

\begin{assumption}[Bounded loss]\label{assum:loss}
    There exists some constant $B > 0$ such that $\sup_{y\in \gY,z\in \gZ}|\phi(y,z)| \leq B$.
\end{assumption}

\begin{assumption}[Locally Lipchitz continuity of decision loss]\label{assum:Lipschitz_solution_1}  
    Given fixed $\lambda\in \Lambda$ and $q\in \sR$, we denote $z_{\lambda}(x; q) = \argmin_{z\in \gZ}\max_{c\in \gU_{\lambda}(x;q)} \phi(c,z)$ where $\gU_{\lambda}(x;q) = \{y\in \gY: S_{\lambda}(x,y) \leq q\}$. There exists some constant $L > 0$ such that $\sup_{x\in \gX,y\in \gY}\LRabs{\phi(y,z_{\lambda}(x; q)) - \phi(y,z_{\lambda}(x;q^{\prime}))} \leq L |q-q^{\prime}|$ for any $q,q^{\prime}\in [F_{\lambda}^{-1}(1-\alpha-a_n), F_{\lambda}^{-1}(1-\alpha+a_n)]$.
\end{assumption}

Assumption \ref{assum:quantile_estimation} is used to ensure the consistency of quantile estimation, which is common in investigating the width efficiency of conformal prediction sets, e.g., \citet{lei2018distribution} and \citet{yang2024selection}. We impose Assumption \ref{assum:loss} for simplicity of concentration. 
Assumption \ref{assum:Lipschitz_solution_1} is key to safely approximating the oracle decision risk, i.e., the approximation relation $\phi(Y_{n+1}, z_{\lambda}^{\mathsf{o}}(X_{n+1}))\approx \phi(Y_{n+1}, z_{\lambda}(X_{n+1}))$.
For a general convex loss $\phi$, this assumption can be satisfied because most robust optimization problems are cone programming, whose solutions can be {locally Lipschitz continuous} to threshold $q$, see \citet{bolte2021nonsmooth} and \citet{wang2023learning}.

\begin{theorem}\label{thm:optimality_ECROMS}
    Assuming data $\{(X_i,Y_i)\}_{i=1}^{n+1}$ are i.i.d., under Assumptions \ref{assum:quantile_estimation}-\ref{assum:Lipschitz_solution_1}, the decision risk of E-CROMS satisfies
    \begin{align}
        \left|\E[\phi(Y_{n+1}, \hat{z}^{\ECROMS}(X_{n+1}))] - v_{\Lambda}^*\right|\leq O\LRl{\LRs{B+\frac{L}{\mu}}\sqrt{\frac{\log (n\vee |\Lambda|)}{n}} }.%,\nonumber
    \end{align}
   % where $v_{\Lambda}^*$ is the minimum decision risk in Definition \ref{def:efficiency}.
\end{theorem}


%In addition, it is worthwhile noticing that E-CROMS does not require the efficiency gap condition in Theorem \ref{thm:FCROMS_optimality}, i.e., allows $\beta_n = 0$ here. The quantity $\beta_n$ can be seen as a tradeoff between decision efficiency and robustness.

Theorem \ref{thm:optimality_ECROMS} implies that the decision $\hat{z}^{\ECROMS}$ is asymptotically optimal as Definition \ref{def:efficiency}. If $\Lambda$ is a continuous parameter space, \citet{yeh2024end} proposed an end-to-end model training framework named E2E, which requires sample splitting to maintain marginal robustness. However, sample splitting will degrade the decision efficiency of the prediction set, because only part of the data is used in solving CRO problems to make final decisions. In Appendix \ref{appen:split_CROMS}, we provide a detailed procedure for E2E in the model selection setting. Despite the finite-sample marginal robustness, theoretical results show that the decision risk of E2E has a larger gap to the optimal value $v_{\Lambda}^*$ than our methods.

\subsection{F-CROMS: symmetric selection with finite-sample robustness}\label{subsec:FCROMS}

The robustness gap in E-CROMS arises from the asymmetric dependence of the model selection process on $\{(X_i,Y_i)\}_{i=1}^{n+1}$, as the test label $Y_{n+1}$ is unknown. We consider adapting the full conformal technique to address this issue \citep{vovk2005algorithmic}.

Given a hypothesized value $y\in \gY$ intended to impute the test label $Y_{n+1}$, we now design a model selection process that is symmetric to the augmented dataset $\{(X_i,Y_i)\}_{i=1}^n \cup \{(X_{n+1}, y)\}$. First, for any $x\in \gX$, we define the prediction set with a symmetric threshold,
\begin{align}%\label{eq:conformal_FCP}
    \gU_{\lambda}^{y}(x) = \LRl{c\in \gY: S_{\lambda}(x, c) \leq Q_{1-\alpha}\LRs{\{S_{\lambda}(X_i,Y_i)\}_{i=1}^n\cup \{S_{\lambda}(X_{n+1},y)\}}}.\nonumber
\end{align}
%where $\hat{q}_{\lambda}^y = Q_{1-\alpha}\LRs{\{S_{\lambda}(X_i,Y_i)\}_{i=1}^n\cup \{S_{\lambda}(X_{n+1},y)\}}$. 
Next, we introduce auxiliary decisions in the augmented dataset:
\begin{align}
    z_{\lambda}^y(X_i) = \argmin_{z\in \gZ}\max_{c\in \gU_{\lambda}^{y}(X_i)}\phi(c,z),\quad i\in [n+1].\nonumber
\end{align}
Then, we select the model by solving the following augmented ERM problem:
\begin{align}\label{eq:hypothesized_avg_ERM}
    \hat{\lambda}^y = \argmin_{\lambda \in \Lambda}\frac{1}{n+1}\left\{\sum_{i=1}^n \phi(Y_i, z_{\lambda}^y(X_i)) + \phi(y, z_{\lambda}^y(X_{n+1}))\right\}.
\end{align}
By carefully checking the three steps above, we can see that the final model index $\hat{\lambda}^y$ is invariant to the permutation of the augmented data set. The step \eqref{eq:hypothesized_avg_ERM} can be recast as a recalibration of  \eqref{eq:eff_CROMS_ERM} in E-CROMS.
Having the selected model $\hat{\lambda}^y$ for each hypothesized label $y$, the \emph{final prediction set} is given by
\begin{align}
    \widehat{\gU}^{\FCROMS}(X_{n+1}) = \LRl{y\in \gY: S_{\hat{\lambda}^y}(X_{n+1}, y) \leq Q_{1-\alpha}\LRs{\{S_{\hat{\lambda}^y}(X_i,Y_i)\}_{i=1}^n\cup \{S_{\hat{\lambda}^y}(X_{n+1},y)\}}}.\nonumber
\end{align}
By plugging it into the CRO problem, the \emph{final decision} is made by
\begin{align}
    \hat{z}^{\FCROMS}(X_{n+1}) = \argmin_{z\in \gZ}\max_{c\in \widehat{\gU}^{\FCROMS}(X_{n+1})}\phi(c,z).\nonumber
\end{align}
We name this data-driven procedure as Full CROMS (F-CROMS) and summarize its implementation in Algorithm \ref{alg:CROMS}. 

%{\color{red}
F-CROMS is closely related to the full conformal prediction \citep{vovk2005algorithmic}. To avoid sample splitting, the full conformal prediction uses a symmetric algorithm to train the model on the augmented dataset $\{(X_i,Y_i)\}_{i=1}^n \cup \{(X_{n+1},y)\}$ for $y\in \gY$. The training process usually aims to minimize the prediction error over a model class, e.g., least squares error and cross-entropy.
%Given the augmented dataset $\{(X_i,Y_i)\}_{i=1}^n \cup \{(X_{n+1},y)\}$ for $y\in \gY$, we first use  a symmetric algorithm to obtain the fitted model $S_y: \gX \times \gY \to \sR$, which is usually trained by minimizing prediction accuracy (e.g., least squared error and cross-entropy) over a model class, such as linear models, random forests or neural networks. Then the full conformal prediction set is
% \begin{align*}
%     \gU^{\sf Full}(X_{n+1}) = \LRl{y\in \gY: S_{y}(X_{n+1}, y) \leq Q_{1-\alpha}\LRs{\{S_y(X_i,Y_i)\}_{i=1}^n}\cup \{S_y(X_{n+1}, y)\}}.
% \end{align*}
%}
In contrast, F-CROMS directly uses the downstream decision risk to select the model from a finite model class. 
Recently, \citet{liang2024conformal} also applied the full conformal prediction technique to select a prediction set with minimum width. However, optimizing the width of a conformal prediction set is not equivalent to improving decision efficiency. Moreover, \citet{liang2024conformal} required the loss function to be monotonic to the calibration threshold, whereas the loss function in the ERM problem \eqref{eq:hypothesized_avg_ERM} does not meet this requirement.

\begin{algorithm}[ht]
	\renewcommand{\algorithmicrequire}{\textbf{Input:}}
	\renewcommand{\algorithmicensure}{\textbf{Output:}}
	\caption{Full CROMS (F-CROMS)}\label{alg:CROMS}
        \linespread{1.4}\selectfont
	\begin{algorithmic}
	\Require Pre-trained models $\{S_{\lambda}:\lambda\in \Lambda\}$, loss function $\phi$, labeled data $\{(X_{i},Y_i)\}_{i=1}^{n}$, test data $X_{n+1}$, robustness level $1-\alpha \in (0, 1)$.
        \State Initialize $\widehat{\gU}^{\FCROMS}(X_{n+1}) \gets \emptyset$.
        \For{$y\in \gY$}

        \For{$\lambda \in \Lambda$} \Comment{{Compute auxiliary decisions}}
        \State $\gU_{\lambda}^y(\cdot) \gets \{c\in \gY: S_{\lambda}(\cdot,c)\leq Q_{1-\alpha}\LRs{\{S_{\lambda}(X_i,Y_i)\}_{i=1}^n\cup \{S_{\lambda}(X_{n+1},y)\}}\}$.


        \State $z_{\lambda}^y(X_i) \gets \argmin_{z\in \gZ}\max_{c\in \gU_{\lambda}^y(X_i)}\phi(c,z)$ for $i\in [n+1]$.

        \EndFor

        \State $\hat{\lambda}^y \gets \argmin_{\lambda \in \Lambda}\frac{1}{n+1}\left\{\sum_{i=1}^{n} \phi(Y_i, z_{\lambda}^y(X_i)) + \phi(y, z_{\lambda}^y(X_{n+1}))\right\}$. \Comment{{Select model via ERM}}


        \If{$S_{\hat{\lambda}^y}(X_{n+1}, y) \leq Q_{1-\alpha}\LRs{\{S_{\hat{\lambda}^y}(X_i,Y_i)\}_{i=1}^n \cup \{S_{\hat{\lambda}^y}(X_{n+1}, y)\}}$}
        \State $\widehat{\gU}^{\FCROMS}(X_{n+1}) \gets \widehat{\gU}^{\FCROMS}(X_{n+1}) \cup \{y\}$. \Comment{{Construct prediction set}}
        \EndIf
        \EndFor        

        \State $\hat{z}^{\FCROMS}(X_{n+1}) \gets \argmin_{z\in \gZ}\max_{c\in \widehat{\gU}^{\FCROMS}(X_{n+1})}\phi(c,z)$. \Comment{{Make the final decision}}

        \Ensure Prediction set $\widehat{\gU}^{\FCROMS}(X_{n+1})$ and decision $\hat{z}^{\FCROMS}(X_{n+1})$.
	\end{algorithmic}
\end{algorithm}

Note that the prediction set of F-CROMS needs to be searched over the whole label space, which is feasible for classification tasks. For regression tasks, we provide a practical implementation of F-CROMS in Appendix \ref{appen:Discretization}. 
The next theorem demonstrates that F-CROMS achieves finite-sample marginal coverage and robustness, which is also independent of any distributional assumptions.



%\SetKwComment{Comment}{/* }{ */}


\begin{theorem}\label{thm:FCROMS_coverage}
    Assume that $\{(X_i,Y_i)\}_{i=1}^{n+1}$ are i.i.d. (or exchangeable), then the prediction set of F-CROMS satisfies $1-\alpha$ level of marginal robustness in Definition \ref{def:robustness}.
\end{theorem}




Next, we provide the asymptotic optimality of F-CROMS under an efficiency gap condition.

\begin{theorem}\label{thm:FCROMS_optimality}
   Suppose Assumptions \ref{assum:quantile_estimation}-\ref{assum:Lipschitz_solution_1} hold. Assume that data $\{(X_i,Y_i)\}_{i=1}^{n+1}$ are i.i.d. and there exists a sequence $\beta_n \geq O(Bn^{-1}+n^{-\gamma}\sqrt{\log(n\vee |\Lambda|)})$ with $\gamma < 1/2$ such that $\E[\phi(Y, z_{\lambda}^{\mathsf{o}}(X))] \geq \E[\phi(Y, z_{\lambda^*}^{\mathsf{o}}(X))] + \beta_n$ for any $\lambda \neq \lambda^*$, where $\lambda^*$ is defined in \eqref{eq:oracle_optimal_model}. The decision risk of F-CROMS satisfies
    \begin{align}
        \left|\E[\phi(Y_{n+1}, \hat{z}^{\FCROMS}(X_{n+1}))] - v_{\Lambda}^*\right| \leq O\LRs{\frac{L}{\mu}\sqrt{\frac{\log n}{n}}}.\nonumber
    \end{align}
%    where $v_{\Lambda}^*$ is the minimum decision risk in Definition \ref{def:efficiency}.
\end{theorem}

\begin{remark}
    Theorem \ref{thm:FCROMS_optimality} imposes the efficiency gap $\beta_n$ to establish model selection consistency in high probability, i.e., $\sP\{\forall~ y\in\gY,\hat{\lambda}^y = \lambda^*\} \geq 1-n^{-C}$ for $C > 1$. Under this event, $\widehat{\gU}(X_{n+1})$ aligns with the conformal prediction set of the oracle optimal model
    $$
    \gU_{\lambda^*}(X_{n+1}) = \left\{y\in \gY: S_{\lambda^*}(X_{n+1},y)\leq Q_{(1-\alpha)(1+n^{-1})}\LRs{\{S_{\lambda^*}(X_i,Y_i)\}_{i=1}^n}\right\}.
    $$ 
    Consequently, we can bound the difference between the decision risk of F-CROMS and the optimal value $v_{\Lambda}^*$. In addition, it is worthwhile noticing that E-CROMS does not require the efficiency gap condition, meaning it allows $\beta_n = 0$. In this context, $\beta_n$ can be seen as a tradeoff between decision efficiency and robustness.
    %The asymptotic efficiency analysis of the full conformal prediction set in Theorem \ref{thm:FCROMS_optimality} is different from that in \citet{liang2024conformal}. First, the authors focused on width efficiency while we consider decision efficiency; Second, the width of the conformal prediction set is independent of the true label, not the case for the decision loss. Moreover, \citet{liang2024conformal} required the loss function to be monotone to the calibration threshold, whereas the loss in the ERM problem \eqref{eq:hypothesized_avg_ERM} does not meet this requirement.
\end{remark}




\section{Individualized Optimal Model Selection}\label{sec:CROiMS}

In the previous section, we focused on model selection in CRO by minimizing oracle decision risk, optimizing decision efficiency on average. However, in applications like precision medicine, the ideal model may vary greatly depending on the unique characteristics of each patient. %Hence, it is critical to tailor the individualized model selection. %  to the specific context of each individual test point. 
In this section, we introduce individualized model selection, extending the ideas in the CROMS framework to minimize conditional decision risk given the test data $X_{n+1}$.
Instead of marginal robustness in Definition \ref{def:robustness}, individualized model selection needs to guarantee conditional robustness, stated as follows.

\begin{definition}[Asymptotic conditional robustness]\label{def:individual_robustness}
    For $(X,Y) \sim P$, the prediction set $\gU(X)$ satisfies $1-\alpha$ level of conditional robustness if the CRO decision $z(X) = \argmin_{z\in \gZ}\max_{c\in \gU(X)}\phi(c,z)$ almost surely satisfies that
    \begin{align}
        \sP\LRl{\phi(Y, z(X)) \leq \max_{c\in \gU(X)}\phi(c, z(X)) \mid X} \geq 1-\alpha + o(1).\nonumber
    \end{align}
\end{definition}


\subsection{Oracle model selection to minimize conditional decision risk}

Given pre-trained models $\{S_{\lambda}:\lambda \in \Lambda\}$, we denote the conditional quantile function as $q_{\lambda}^{\mathsf{co}}(X) = \inf\{q\in \sR: \sP\{S_{\lambda}(X,Y) \leq q\mid X\}\}$. For data $(X, Y)\sim P$, the conditional oracle prediction set is defined as
\begin{align}
    \gU_{\lambda}^{\mathsf{co}}(X) = \{y\in \gY: S_{\lambda}(X, y) \leq q_{\lambda}^{\mathsf{co}}(X)\},\nonumber
\end{align}
which satisfies the conditional coverage property
\begin{align}\label{eq:cond_coverage}
    \sP\LRl{Y\in \gU_{\lambda}^{\mathsf{co}}(X) \mid X} \geq 1-\alpha.
\end{align}
Let $z_{\lambda}^{\mathsf{co}}(X) = \argmin_{z\in \gZ}\max_{c\in \gU_{\lambda}^{\mathsf{co}}(X)}$ be the decision enjoying the conditional robustness in Definition \ref{def:individual_robustness} due to \eqref{eq:cond_coverage}.
To evaluate the individual efficiency of decisions $\{z_{\lambda}^{\mathsf{co}}(X): \lambda\in \Lambda\}$, we introduce the oracle conditional decision risk $\E[\phi(Y,z_{\lambda}^{\mathsf{co}}(X))\mid X]$. 
Then, the index of the individually optimal model is defined as 
\begin{equation}\label{eq:oracle_individual_optimal_model}
    \begin{aligned}
    \lambda^*(X) = \argmin_{\lambda \in \Lambda}&\  \E\LRm{ \phi(Y, z_{\lambda}^{\mathsf{co}}(X)) \mid X}.
    \end{aligned}
\end{equation}

Denote the the minimum individual decision risk among all candidate models as $v_{\Lambda}^*(X)=\E[\phi(Y, z_{\lambda^*(X)}^{\mathsf{co}}(X))\mid X]$. Similar to Definition \ref{def:efficiency}, we define the asymptotic condition efficiency of one data-driven decision.

\begin{definition}[Asymptotic conditional optimality]\label{def:individual_efficiency}
    A data-driven decision $\hat{z}(X)$ is asymptotically conditional optimal if $\lim_{n\to \infty}\E[\phi(Y,\hat{z}(X)) \mid X] = v_{\Lambda}^*(X)$ almost surely. %, where $v_{\Lambda}^*(X)=\E[\phi(Y, z_{\lambda^*(X)}^{\mathsf{co}}(X))\mid X]$ is the minimum individual decision risk among all candidate models.
\end{definition}

Before proceeding further, it would be beneficial to discuss Eq. \eqref{eq:cond_coverage}, which is also known as \emph{test-conditional coverage} in conformal prediction literature \citep{vovk2005algorithmic}. As showned by \citet{vovk2012conditional} and \citet{lei2013distribution}, that test-conditional coverage is impossible to achieve in a distribution-free regime, except for a noninformative trivial set $\gY$. Extensive research has been dedicated to constructing prediction sets that satisfy asymptotic or approximate conditional coverage under certain distributional assumptions. For a comprehensive overview of recent developments, we refer to Chapter 4 in \citet{angelopoulos2024theoretical}. % for recent developments.

In the next subsection, we will develop a data-driven method that could perform \emph{individualized} model selection with conditional conformal prediction sets.
Since distribution-free conditional coverage \eqref{eq:cond_coverage} is not achievable in finite samples, the decision induced by the selected model aims to asymptotically maintain $1-\alpha$ level of conditional robustness in Definition \ref{def:individual_robustness}, while satisfying asymptotic optimality in Definition \ref{def:individual_efficiency}. %have the following asymptotic efficiency.


%In the subsequent subsections, we develop a data-driven method to construct a prediction set $\widehat{\gU}(X_{n+1})$ for the test data label $Y_{n+1}$, which satisfies the asymptotic conditional robustness and efficiency in Definitions \ref{def:individual_robustness} and \ref{def:individual_efficiency}.

\subsection{CROiMS: individualized model selection and robust decision}

To approximate the conditional decision risk in \eqref{eq:oracle_individual_optimal_model}, we first employ the Nadaraya–Watson kernel method \citep{nadaraya1964estimating,watson1964smooth} to estimate the conditional quantile function $q_{\lambda}^{\mathsf{co}}(X_{n+1})$. A similar localized strategy was used in \citet{guan2023localized} and \citet{hore2024conformal}. Equipped with a kernel function $H(\cdot,\cdot):\gX\times \gX$, the oracle conditional quantile function $q_{\lambda}^{\mathsf{o}}(\cdot)$ can be estimated by the $(1-\alpha)$-th weighted sample quantile,
\begin{align}
    \hat{q}_{\lambda}(\cdot) = Q_{1-\alpha}\LRs{\{S_{\lambda}(X_i,Y_i)\}_{i=1}^n; \{w_i(\cdot)\}_{i=1}^n},\nonumber
\end{align}
where $w_i(\cdot) = H(X_i,\cdot)/\sum_{j=1}^n H(X_j,\cdot)$ for $i\in [n]$ are weights. Then the localized conformal prediction (LCP) set of candidate model $S_{\lambda}$ is defined as
\begin{align}
    \gU_{\lambda}^{\mathsf{LCP}}(X_{n+1}) = \LRl{c\in \gY: S_{\lambda}(X_{n+1},c) \leq \hat{q}_{\lambda}(X_{n+1})}.\nonumber
\end{align}
The decision is given by $z_{\lambda}^{\mathsf{LCP}}(X_{n+1}) = \argmin_{z\in \gZ}\max_{c\in \gU_{\lambda}^{\mathsf{LCP}}(X_{n+1})} \phi(c,z)$. Under mild nonparametric assumptions, $\hat{q}_{\lambda}(X_{n+1})$ is a consistent estimator to the oracle conditional quantile, which indicates that $\phi(Y_{n+1}, z_{\lambda}^{\mathsf{LCP}}(X_{n+1})) \approx \phi(Y_{n+1}, z_{\lambda}^{\mathsf{co}}(X_{n+1}))$. 

%\footnote{The original LCP method in \citet{guan2023localized} employed a recalibration technique to keep the finite-sample marginal coverage. Here, we focus on the conditional coverage property and omit the recalibration step. In Appendix \ref{appen:full-CROiMS}, we developed a new method named Full-CROiMS to recalibrate the threshold for the prediction set constructed in Algorithm \ref{alg:CROiMS}, which satisfies the finite-sample marginal coverage property.}

Next, we proceed with approximating the decision risk $\E[\phi(Y_{n+1}, z_{\lambda}^{\mathsf{LCP}}(X_{n+1})) \mid X_{n+1}]$ through the labeled data. Denote $\gU_{\lambda}^{\mathsf{LCP}}(\cdot) = \{y\in\gY: S_{\lambda}(\cdot,y) \leq \hat{q}_{\lambda}(\cdot)\}$, and define auxiliary decisions as $z_{\lambda}^{\mathsf{LCP}}(X_i) = \argmin_{z\in \gZ}\max_{c\in \gU_{\lambda}^{\mathsf{LCP}}(X_i)}\phi(c,z)$ for $i\in [n]$. The \emph{individualized model selection} is conducted by solving the weighted ERM problem
\begin{align}%\label{eq:individual_ERM}
    \hat{\lambda}(X_{n+1}) = \argmin_{\lambda \in \Lambda}\sum_{i=1}^nw_i(X_{n+1})\cdot \phi(Y_i,z_{\lambda}^{\mathsf{LCP}}(X_i)).\nonumber
\end{align}
After obtaining the model index $\hat{\lambda}(X_{n+1})$, we output \emph{final individualized prediction set} as $\widehat{\gU}^{\mathsf{CROiMS}}(X_{n+1}) = \gU_{\hat{\lambda}(X_{n+1})}^{\mathsf{LCP}}(X_{n+1})$, and then \emph{final decision} is made by
\begin{align}%\label{eq:decision_after_selection}
    \hat{z}^{\mathsf{CROiMS}}(X_{n+1}) = \argmin_{z\in \gZ}\max_{c\in \widehat{\gU}^{\mathsf{CROiMS}}(X_{n+1})} \phi(c,z).\nonumber
\end{align}
The selection procedure above is referred to as \emph{Conformalized Robust Optimization with individualized Model Selection} (CROiMS), whose implementation is in Algorithm \ref{alg:CROiMS}.

\begin{algorithm}[ht]
	\renewcommand{\algorithmicrequire}{\textbf{Input:}}
	\renewcommand{\algorithmicensure}{\textbf{Output:}}
	\caption{CROiMS}
	\label{alg:CROiMS}
        \linespread{1.4}\selectfont
	\begin{algorithmic}
	\Require Pre-trained models $\{S_{\lambda}:\lambda\in \Lambda\}$, loss function $\phi$, labeled data $\{(X_{i},Y_i)\}_{i=1}^{n}$, test data $X_{n+1}$, kernel function $H$, robustness level $1-\alpha \in (0, 1)$.
        \For{$\lambda \in \Lambda$}\Comment{{Compute auxiliary decisions}}
        \State $\hat{q}_{\lambda}(\cdot) \gets Q_{1-\alpha}\LRs{\{S_{\lambda}(X_i,Y_i)\}_{i=1}^n; \{w_i(\cdot)\}_{i=1}^n}$ with $w_i(\cdot) = \frac{H(X_i,\cdot)}{\sum_{j=1}^n H(X_j,\cdot)}$.

        \State $\gU_{\lambda}^{\mathsf{LCP}}(\cdot) \gets \{c\in \gY: S_{\lambda}(\cdot,c)\leq \hat{q}_{\lambda}(\cdot)\}$.

        \State $z_{\lambda}^{\mathsf{LCP}}(X_i) \gets \argmin_{z\in \gZ}\max_{c\in \gU_{\lambda}^{\mathsf{LCP}}(X_i)}\phi(c,z)$ for $i\in [n]$.

        %\State Compute decision loss $\phi(Y_i,\hat{z}_{\lambda}(X_i))$ for $i\in [n]$.

        \EndFor

        \State $\hat{\lambda}(X_{n+1}) \gets \argmin_{\lambda \in \Lambda}\sum_{i=1}^{n} w_i(X_{n+1})\cdot \phi(Y_i, z_{\lambda}^{\mathsf{LCP}}(X_i))$. \Comment{{Select model via weighted ERM}}

        \State $\widehat{\gU}^{\mathsf{CROiMS}}(X_{n+1}) \gets \gU_{\hat{\lambda}(X_{n+1})}^{\mathsf{LCP}}(X_{n+1})$. \Comment{{Conditional prediction set for the selected model}}

        \State $\hat{z}^{\mathsf{CROiMS}}(X_{n+1}) \gets \argmin_{z\in \gZ}\max_{c\in \widehat{\gU}^{\mathsf{CROiMS}}(X_{n+1})} \phi(c,z)$. \Comment{{Make CRO decision}}

        \Ensure Prediction set $\widehat{\gU}^{\mathsf{CROiMS}}(X_{n+1})$ and decision $\hat{z}^{\mathsf{CROiMS}}(X_{n+1})$.
	\end{algorithmic}
\end{algorithm}

\begin{remark}
    The kernel function can be set as $H(x_1,x_2) = K\LRs{\frac{D(x_1,x_2)}{h}}$, where $D(x_1,x_2) \geq 0$ is a distance function that measures the dissimilarity between $x_1$ and $x_2$, $K(\cdot)$ is a normalized one-dimensional kernel function, and $h$ is the bandwidth. In the case where $\gX \subseteq \sR^d$, common choices for the kernel function include the Gaussian kernel is $H(x_1,x_2) = \exp\LRs{-\frac{D(x_1,x_2)}{h}}$ and the box kernel $H(x_1,x_2) = \mathbbm{1}\{D(x_1,x_2)\leq h\}$. The distance function $D$ can be flexibly chosen according to the specific need for localization. For example, the Euclidean distance for low-dimensional cases and the projection distance for high-dimensional cases \citep{guan2023localized,lei2018distribution}.
    %For example, (1) Euclidean distance $D(x_1,x_2) = \|x_1-x_2\|$ in low-dimensional case; (2) Projection distance $D(x_1,x_2) = \|\operatorname{Proj}(x_1) - \operatorname{Proj}(x_2)\|$ in high-dimensional case \citep{guan2023localized,lei2018distribution}, where $\operatorname{Proj}(\cdot): \sR^d \to \sR^{k}$ is a projection operator with $k\ll d$. 
    In Algorithm \ref{alg:CROiMS}, we use the same kernel function for both the weighted quantile and the weighted ERM problem. In practice, one can choose different kernels to estimate the conditional quantile and the conditional risk.
\end{remark}






\subsection{Theoretical results of CROiMS}

In this section, we explore the conditional robustness and efficiency properties of CROiMS. For simplicity, we assume that $\gX \subseteq \sR^d$, and consider the kernel function $H(x_1,x_2) = \exp\LRs{-\frac{\|x_1-x_2\|}{h_n}}$. We start with introducing the basic distributional assumptions required to establish a non-asymptotic bound of conditional coverage.

\begin{assumption}[Conditional quantile estimation]\label{assum:cond_quantile}
    Let $p(x)$ be the density function of $X$. There exists some $\rho > 0$ such that $\inf_{x\in \gX} p(x) \geq \rho > 0$. Let $f_{\lambda}(s|x)$ and $F_{\lambda}(s|x)$ be the conditional density function and distribution function of score $S_{\lambda}(X,Y)$ given $X=x$, respectively. There exist some constants $\tau>0$, $\rho_{\sf c}>0$ such that for any $\lambda\in\Lambda$, $\sup_{s\in \sR}|F_{\lambda}(s|x) - F_{\lambda}(s| x^{\prime})| \leq \tau\|x-x^{\prime}\|$ for any $x,x^{\prime}\in \gX$, and $\inf_{x\in \gX}f_{\lambda}(s|x) \geq \rho_{\sf c}$ for any $s\in [F_{\lambda}^{-1}(1-\alpha-b_n|x),F_{\lambda}^{-1}(1-\alpha+b_n|x)]$ with $b_n = O\LRs{\tau h_n\log(h_n^{-d})+\sqrt{\frac{\log (n \vee |\Lambda|)}{\rho nh_n^d}}}$, where $F_{\lambda}^{-1}(\cdot|x)$ is the conditional quantile function.
\end{assumption}

\begin{assumption}[Conditional expectation estimation]\label{assum:cond_expectation} 
    Suppose Assumption \ref{assum:Lipschitz_solution_1} holds by replacing $a_n$ with $b_n$.
    Let $\Phi_{\lambda}(X,Y) = \phi(Y, z_{\lambda}(X; q_{\lambda}^{\sf o}(X)))$, where $z_{\lambda}(x,q)$ is defined in Assumption \ref{assum:Lipschitz_solution_1}.
    There exists a constant $L_{\sf c} > 0$, for any $\lambda \in \Lambda$ and $x,x^{\prime}\in \gX$, $\left|\E[\Phi_{\lambda}(X,Y)\mid X=x] - \E[\Phi_{\lambda}(X,Y)\mid X=x^{\prime}]\right| \leq L_{\sf c} \twonorm{x - x^{\prime}}$.
\end{assumption}

% \begin{assumption}\label{assum:conditional_score}

% \end{assumption}

The smoothness condition for conditional risk in Assumption \ref{assum:cond_expectation} is common in the nonparametric estimation of conditional expectation \citep{wasserman2006all,tsybakov2008introduction}. %The next theorem characterizes the nonasymptotic gap between the decision risk of CROiMS and that of the optimal decision.
Under the conditions above, we present the bounds of conditional coverage and decision risk for CROiMS in the following two theorems.

\begin{theorem}\label{thm:cond_coverage}
    Suppose data $\{(X_i,Y_i)\}_{i=1}^{n+1}$ are i.i.d. and Assumption \ref{assum:cond_quantile} holds. If $nh_n^d \to \infty$ and $h_n \to 0$, then the selected prediction set of CROiMS almost surely satisfies $1-\alpha - O\LRl{\sqrt{\frac{\log(n\vee |\Lambda|)}{\rho n h_n^d}} + \frac{\tau}{\rho} h_n \log(h_n^{-d})}$ level of conditional robustness in Definition \ref{def:individual_robustness}.
    % \begin{align}
    %     \sP\LRl{Y_{n+1}\in \widehat{\gU}^{\mathsf{CROiMS}}(X_{n+1})\mid X_{n+1}} = 1-\alpha - O\LRl{\sqrt{\frac{\log(n\vee |\Lambda|)}{\rho n h_n^d}} + \frac{\tau}{\rho} h_n \log(h_n^{-d})}.\nonumber
    % \end{align}
    % Further, the prediction set $\widehat{\gU}^{\sf CROiMS}(X_{n+1})$ satisfies the same level of conditional robustness.
%Further, the prediction set $\widehat{\gU}^{\mathsf{CROiMS}}(X_{n+1})$ achieves $1-\alpha$ asymptotic conditional robustness of decision as Definition \ref{def:individual_robustness}.    
\end{theorem}


\begin{theorem}\label{thm:CROIMS_optimality}
    Under Assumptions \ref{assum:loss}, \ref{assum:cond_quantile}, \ref{assum:cond_expectation} and the same setting of Theorem \ref{thm:cond_coverage}, the conditional decision risk of CROiMS almost surely satisfies
        \begin{align}
            &\left|\E\Big[\phi\LRs{Y_{n+1}, \hat{z}^{\mathsf{CROiMS}}(X_{n+1})} \mid X_{n+1}\Big] - v_{\Lambda}^*(X_{n+1})\right|\nonumber\\
            &\qquad\qquad\qquad\qquad\leq O\LRl{\LRs{B+\frac{L}{\rho_{\sf c}}}\sqrt{\frac{\log (n\vee |\Lambda|)}{\rho n h_n^d}} + \LRs{L_{\sf c}+\frac{\tau L}{\rho_{\sf c}}}h_n\log(h_n^{-d})}.\nonumber
        \end{align}
\end{theorem}


By comparing Theorems \ref{thm:cond_coverage} and \ref{thm:CROIMS_optimality} with the convergence rate of classical kernel estimation, we observe that individualized model selection introduces only an additional error factor of $\log|\Lambda|$, regarding the size of the candidate set. 
Assuming $|\Lambda| \leq O(n^{C})$ for constant $C>0$ and choosing the bandwidth $h_n \asymp n^{-\frac{1}{d+2}}$, CROiMS can achieve asymptotic conditional robustness and optimality with nearly optimal rate $O(n^{-\frac{1}{d+2}} \log n)$. 

