%     ) - \sum_{f_j\in\Omega(F_j)}Q^{\tup{F}|\rho}_{\tup{t}|t_0}(\tup{f}, \tup{f}).
% \end{align}
\begin{align}
    \nonumber
    &Q^{
        F_n,\ldots,\cancel{F_j},\ldots,F_1|\rho
    }_{
        t_n,\ldots,\cancel{t_j},\ldots,t_1|t_0
    }(
        f_n,\ldots,\cancel{f_j},\ldots,f_1\,;\,
