	Motivated by such examples and Theorem \ref{bowditch thm}, Lazarovich, Margolis and Mj posed the following question. %We refer the reader to Definitions \ref{defn-metric graph bundle} and \ref{defn-metric bundle} for metric (graph) bundle.
	%For the definition of controlled hyperbolic fibers, we refer the reader to Definition \ref{controlled fibers defn}.

	\begin{question}\textup{(\cite[Question 3.15]{NirMaMj-commen})}\label{main qsn}
Let $k\ge1$, $L\ge0$. Suppose $\pi:X\map [0,\infty)$ is a metric graph bundle  such that: $(1)$ the fibers $F_i,~i\in\N\cup\{0\}$ are $k$-quasiisometric to a fixed one-ended hyperbolic space, and $(2)$ the barycenter maps $\pa^3F_i\map F_i$ are $L$-coarsely surjective. Further, assume that $X$ is hyperbolic.

Is the CT map $\pa\pi^{-1}(0)\map\pa X$ surjective?
	\end{question}

Note that the existence of a CT map in Question \ref{main qsn} follows from a more general result of Mitra (\cite{mitra-trees}). In this article, we give an affirmative answer to Question \ref{main qsn} (Theorem \ref{thm-combo1}). In fact, we prove this result when the fibers are not necessarily one-ended as follows. %To state this, we first introduce the following terminology.\smallskip

%\noindent {\bf Controlled hyperbolic fibers} (Definition \ref{controlled fibers defn}): {\em A metric (graph) bundle $\pi:X\map B$ is said to have {\em controlled hyperbolic fibers} if there are $\dl\ge0$ and $L\ge0$ such that the fibers are $\dl$-hyperbolic and the barycenter maps for the fibers are $L$-coarsely surjective.}


\begin{theorem}\label{thm-combo1}
Suppose $\pi:X\map [0,\infty)$ is a metric graph bundle such that 

\begin{itemize}
	\item the fibers $F_i=\pi^{-1}(i),~i\in\N\cup\{0\}$ are $\dl$-hyperbolic for some $\dl\ge0$,

	\item the barycenter maps $\pa^3F_i\map F_i$ are $L$-coarsely surjective for some $L\ge0$, and %, i.e., there is $N\ge0$ such that $N$-neighborhood of the image is $F_b$, and

	\item the total space $X$ is $\dl$-hyperbolic.
\end{itemize}
Further, we assume one of the following.

$(A)$ Suppose that for each fiber $F_i$ and each vertex $u\in F_i$, the valence at $u$ in $F_i$ is bounded by some constant $D\ge0$.

$(B)$ Suppose that the fibers $F_i$ are one-ended and proper metric spaces.\smallskip

Then the CT map $\pa\pi^{-1}(0)\map\pa X$ is surjective.
\end{theorem}
For convenience, we will refer to Theorem~\ref{thm-combo1} under the assumption $(A)$ as Theorem~\ref{thm-combo1}$(A)$, and under the assumption $(B)$ as Theorem~\ref{thm-combo1}$(B)$.

