	\begin{defn}\label{defn-gromov inner pd}
		Let $X$ be a metric space. Let $x,y,z\in X$. Then the Gromov inner product of $y$ and $z$ with respect to $x$ is defined and denoted as follows. $$(y,z)_x:=\frac{1}{2}\{d(x,y)+d(x,z)-d(y,z)\}$$
	\end{defn}
	%In the following result, we assume that geodesic triangles are thin.

	\begin{lemma}\label{lem-small inner prod}
		Let $\dl\ge0$ and $K\ge1$. Then there is a constant $D_{\ref{lem-small inner prod}}(\dl,K)=K\dl+K^2/2$ such that the following holds. Suppose $X$ is a $\dl$-hyperbolic geodesic metric space, and let $x,y,z,w\in X$. Further, suppose that the arclength parametrization of $[z,y]\cup[y,w]$ is a $K$-quasigeodesic.

		Then $min~\{(x,z)_y,(x,w)_y\}\le D_{\ref{lem-small inner prod}}(\dl,K)$. Moreover, $(z,w)_y\le D_{\ref{lem-small inner prod}}(\dl,K)$.
	\end{lemma}

	\begin{proof}
		Without loss of generality, we assume that the geodesic triangles in $X$ are $\dl$-thin (see \cite[Proposition $2.1$]{abc}). Let $t\in[y,x]$, $t'\in[y,z]$ and $t''\in[y,w]$ such that $d(y,t)=d(y,t')=d(y,t'')$ and $d(t,t')\le\dl$, $d(t,t'')\le\dl$. Thus $d(t',t'')\le2\dl$. Note that the arclength parametrization of $[z,y]\cup[y,w]$ is a $K$-quasigeodesic. Hence $\frac{1}{K}\{d(t',y)+d(y,t'')\}-K\le d(t',t'')\le2\dl$, and so $d(t',y)+d(y,t'')\le 2K\dl+K^2$. Therefore, $d(y,t')=d(y,t'')\le K\dl+K^2/2$. Since $t\in[y,x]$ is arbitrary with chosen property, we have $min\{(x,z)_y,(x,w)_y\}\le K\dl+K^2/2$.

		By a similar argument, we can conclude that $(z,w)_y\le K\dl/2+K^2/2$.

		Therefore, we can take $D_{\ref{lem-small inner prod}}(\dl,K)=K\dl+K^2/2$. This completes the proof.
	\end{proof}
