	For the following result, one is referred to \cite[Theorem $1.4$, Chapter $3$]{CDP}. Recall that given $k\ge1,~\ep\ge0$, $L>0$ and an interval $I\sse\R$, a map $\al:I\map X$ is said to be $(k,\ep,L)$-{\em local quasigeodesic} if $\al$ restricted to any subinterval of length $\le L$ is $(k,\ep)$-quasigeodesic.

	\begin{lemma}[{Local quasigeodesic vs global quasigeodesic}]\label{local vs global}
		For all $\dl\ge0,~k\ge1$ and $\ep\ge0$ there are constants $L_{\ref{local vs global}}=L_{\ref{local vs global}}(\dl,k,\ep)>0$ and $ \lm_{\ref{local vs global}}=\lm_{\ref{local vs global}}(\dl,k,\ep)\ge1$ such that the following holds.

		Suppose $X$ is a $\dl$-hyperbolic geodesic metric space. Then any $(k,\ep,L_{\ref{local vs global}})$-local quasigeodesic in $X$ is a $\lm_{\ref{local vs global}}$-quasigeodesic.
	\end{lemma}

	As an application of Lemma \ref{local vs global}, we have the following.

	\begin{lemma}\label{local to global}
		Let $\dl\ge0$ and $C\ge0$. Then there are constants $D_{\ref{local to global}}(\dl,C)=L_{\ref{local vs global}}(\dl,2C+\dl,2C+\dl)>0$ and $K_{\ref{local to global}}=K_{\ref{local to global}}(\dl,C)\ge1$ depending only on $\dl$ and $C$ such that the following holds.

		Suppose $X$ is a $\dl$-hyperbolic geodesic metric space. Let $x=x_0,x_1,\cdots,x_n=y\in X$ and $\al_i=[x_{i-1},x_i]$ where $i\in\{1,2,\cdots,n\}$.  If $d(x_{i-1},x_i)\ge D_{\ref{local to global}}(\dl,C)$ and the Gromov inner product $(x_{i-1},x_{i+1})_{x_i}\le C$ then the arclength parametrization of the concatenation $\bt=\al_0*\al_1*\cdots*\al_{n-1}$ is $K_{\ref{local to global}}$-quasigeodesic.
	\end{lemma}

	\begin{proof}
		We will show that $\bt$ is a local quasigeodesic. Then we will be done by Lemma \ref{local vs global}.

		Without loss of generality, we assume that the geodesic triangles in $X$ are $\dl$-thin (see \cite[Proposition $2.1$]{abc}). Let $p\in\al_i$ and $q\in\al_{i+1}$ such that $(x_{i-1},x_{i+1})_{x_i}=d(x_i,p)=d(x_i,q)$. Then $d(p,q)\le\dl$, and by our assumption $d(p,x_i)=d(q,x_i)\le C$. %Again we also have $r\in[x_{i-1},x_{i+1}]$ such that $d(p,r)\le\dl$ and $d(q,r)\le\dl$.
		We will show that the arclength parametrization, $\gm:I=[0,d(x_{i-1},x_i)+d(x_i,x_{i+1})]\map X$ say, of the concatenation $\al_i*\al_{i+1}$ is a quasigeodesic where $\gm(0)=x_{i-1}$. Suppose $s,t\in I$. First of all, note that $d(\gm(s),\gm(t))\le|s-t|$ since $\gm$ is arclength parametrization. So we have to prove the other inequality. If $\gm(s),\gm(t)\in\al_i$ or $\gm(s),\gm(t)\in\al_{i+1}$ then we already have $d(\gm(s),\gm(t))=|s-t|$ since $\al_i$'s are geodesics. Now suppose, without loss of generality, $\gm(s)\in\al_i$ and $\gm(t)\in\al_{i+1}$, and so $s\le t$.

		\noindent{\em Case} 1: Suppose $\gm(s)\in[p,x_i]$. Then
		\begin{eqnarray*}
			d(\gm(s),\gm(t))&\ge&d(\gm(s'),\gm(t))-C\\
			&&\text{(by triangle inequality, where }\gm(s')=x_i\text{ and }s'-s=d(\gm(s),x_i)\le C)\\
			&=&(t-s')-C=(t-s)-(s'-s))-C\ge (t-s)-2C\\
			&&\text{(since }\al_i\text{ is geodesic})
		\end{eqnarray*}

		\noindent{\em Case} 2: Suppose $\gm(t)\in[x_i,q]$. By a similar argument as in Case 1, we will have $d(\gm(s),\gm(t))\ge(t-s)-2C$.

%		\begin{figure}[h]
%			\includegraphics[width=15cm]{lotoglo}
%			\centering
%			\caption{Case 3}
%			\label{}
%		\end{figure}

		\noindent{\em Case} 3: Suppose $\gm(s)\in[x_{i-1},p]$ and $\gm(t)\in[q,x_{i+1}]$. Then
		\begin{eqnarray*}
			d(\gm(s),\gm(t))&\ge&d(\gm(s),p)+d(q,\gm(t))-\dl\text{ (by triangle inequality)}\\
			&=&d(\gm(s),x_i)-d(p,x_i)+d(x_i,\gm(t))-d(x_i,q)-\dl\\
			&\ge&d(\gm(s),x_i)+d(x_i,\gm(t))-2C-\dl=(t-s)-2C-\dl\\
			&&\text{(since }d(p,x_i)=d(q,x_i)\le C)
		\end{eqnarray*}

		\noindent This shows that $\gm$ is a $(2C+\dl)$-quasigeodesic. Since $i$ was arbitrary, the restriction of $\bt$ on the concatenation $\al_i*\al_{i+1}$ is $(2C+\dl)$-quasigeodesic for any $i\in\{1,2,\cdots,n-1\}$.

		Again, we have $d(x_i,x_{i+1})\ge D_{\ref{local to global}}(\dl,C)=L_{\ref{local vs global}}(\dl,2C+\dl,2C+\dl)$ for all $i\in\{0,1,\cdots,n-1\}$. So $\bt$ is a $L_{\ref{local vs global}}(\dl,2C+\dl,2C+\dl)$-local quasigeodesic. Therefore, by Lemma \ref{local vs global}, $\bt$ is a $K_{\ref{local to global}}(\dl,C)$-quasigeodesic where $K_{\ref{local to global}}(\dl,C)=\lambda_{\ref{local vs global}}(\dl,2C+\dl,2C+\dl)$. This completes the proof.
	\end{proof}

	We end this subsection by recalling the exponential divergence property -- which is in a specialized form -- of (quasi)geodesics in hyperbolic metric spaces. 


	\begin{lemma}\textup{(\cite[Proposition 1.6, III.H]{bridson-haefliger})}\label{geo line div exp}
		Suppose $X$ is a $\dl$-hyperbolic geodesic metric space for some $\dl\ge0$. Let $p,q\in X$, and let $\al$ be a geodesic segment joining $p$ and $q$. Fix $x\in\al$. Then any path lying outside $n$-radius ball centered at $x$ joining $p$ and $q$ has length at least $b^{n-1}$ where $b=2^{1/\dl+1}$ and $n\in\N$.
	\end{lemma}
