	\subsection{Geodesic boundary and Cannon--Thurston map}\label{subsec-gromov bdry and CT}
	In this subsection, we will see some properties of the {\em geodesic boundary} of hyperbolic spaces and the {\em Cannon--Thurston map} between hyperbolic spaces. We assume that the reader is familiar with the geodesic boundary of hyperbolic spaces (and groups) (see \cite{gromov-hypgps}, \cite[Chapter III.H]{bridson-haefliger} and \cite{GhH}). For a proper hyperbolic geodesic metric space $X$, the {\em geodesic boundary} of $X$ is denoted by $\pa X$ and is defined to be the equivalence classes of geodesic rays. Two geodesic rays $\al$ and $\bt$ are said to be related if $Hd(\al,\bt)<\infty$. For a geodesic ray $\al:[0,\infty)\map X$, its equivalence class is denoted by $\al(\infty)$.

	\begin{lemma}\label{existence of geo ray line}
		Suppose $X$ is a proper $\dl$-hyperbolic geodesic metric space for some $\dl\ge0$. Then:
		\begin{enumerate}
			\item \textup{(\cite[Lemma $3.1$, $III.H$]{bridson-haefliger})} Given $x\in X$ and $\xi\in\pa X$, there is a geodesic ray, say $\al$, such that $\al(0)=x$ and $\al(\infty)=\xi$.

			\item \textup{(\cite[Lemma $3.2$, $III.H$]{bridson-haefliger})} \textup{(Visibility of $\pa X$)} Given two distinct points $\xi_1,\xi_2\in \pa X$ there is a geodesic line, say $\bt$, in $X$ such that $\bt(-\infty)=\xi_1$ and $\bt(\infty)=\xi_2$.
		\end{enumerate}
	\end{lemma}

	\begin{remark}\label{qg boundary}
		Let $\dl\ge0$. Note that for any (unbounded) $\dl$-hyperbolic geodesic metric space (that need not be proper) there is a (continuous) $k$-quasigeodesic ray where $k\ge1$ depends only on $\dl$ (see \cite[Lemma $2.4$]{pranab-mahan}). Equivalence classes of these $k$-quasigeodesic rays are denoted by $\pa_qX$. (Two quasigeodesic rays are related if their Hausdorff distance is finite.) For a quasigeodesic ray $\al:[0,\infty)\map X$, its equivalence class is denoted by $\al(\infty)$. Then Lemma \ref{existence of geo ray line} holds for $\pa_qX$ as well (for instance, see \cite[Lemma 2.4]{pranab-mahan}). Note that if $X$ is a proper, hyperbolic geodesic metric space, then the natural map $\pa X\map \pa_qX$ is a bijection (see \cite[Lemma $3.1$]{bridson-haefliger}).

		The results discussed in this section also apply to hyperbolic geodesic metric spaces that are not necessarily proper; the only modification required is to replace geodesic rays (respectively, lines) with quasigeodesic rays (respectively, lines). However, the properness (of {\em fibers of metric graph bundle}) is crucial in the next section, specifically, in Proposition \ref{mild imp special}.
	\end{remark}

	\begin{lemma}\textup{(Stability of quasigeodesic; \cite[Theorem 1.7, Lemma 3.3, III.H]{bridson-haefliger})}\label{stability of qc}
		Given $\dl\ge0$ and $k\ge1$ there is a constant $D_{\ref{stability of qc}}=D_{\ref{stability of qc}}(\dl,k)\ge0$ such that the following holds.

		Suppose $X$ is a $\dl$-hyperbolic geodesic metric space. Let $\al$ be a geodesic segment $($respectively, ray or line$)$ in $X$, and let $\bt$ be a $k$-quasigeodesic segment $($respectively, ray or line$)$ in $X$ joining endpoints of $\al$. Then $Hd(\al,\bt)\le D_{\ref{stability of qc}}$.
	\end{lemma}
