	\begin{theorem}\textup{(\cite[Theorem $3.9$]{bridson-haefliger})}\label{qi emb gives top emb}
		Suppose $f:X\map Y$ is a qi embedding between two proper hyperbolic geodesic metric spaces. Then $f$ defines a topological embedding $\pa f:\pa X\map\pa Y$ sending $\al(\infty)\mapsto f\circ\al(\infty)$ where $\al$ is a geodesic ray in $X$. Moreover, $\pa f:\pa X\map\pa Y$ is a homeomorphism if $f$ is a quasiisometry.
	\end{theorem}

	While the following results are commonly stated for (quasi)geodesic segments, we will prove them for geodesic lines, as this format will be used in subsequent applications.

	\begin{lemma}\label{lem-geo lying out imply out}
		Suppose $k\ge1$, $\dl\ge0$ and $D_1=D_{\ref{stability of qc}}(\dl,k)$. Then there are constants $$D_{\ref{lem-geo lying out imply out}}=D_{\ref{lem-geo lying out imply out}}(\dl,k)=2D_1+3k+2\dl+1/k,~D'_{\ref{lem-geo lying out imply out}}=D'_{\ref{lem-geo lying out imply out}}(\dl,k)=D_1+4k$$ and $$A_{\ref{lem-geo lying out imply out}}=A_{\ref{lem-geo lying out imply out}}(\dl,k)=~max~\{2k,2D_1+k\}$$ depending only on $\dl$ and $k$ such that the following hold.

Suppose $X$ and $Y$ are $\delta$-hyperbolic geodesic metric spaces, and let $\phi : X \to Y$ be a $k$-qi embedding. Let $\alpha$ be a geodesic line in $X$, and let $\beta$ be a geodesic line in $Y$ such that $\beta(-\infty) = \partial\phi(\alpha(-\infty))$ and $\beta(\infty) = \partial\phi(\alpha(\infty))$. Let $x \in X$ and $n \in \mathbb{N}$. Suppose $\gamma$ is a continuous path in $X$, lying outside the ball of radius $n$ centered at $x$, and joining two points $x_1, x_2 \in \alpha$.

Then there exists a continuous path $\gamma'$ in $Y$ joining two points on $\beta$ such that:

$(a)$ $\gamma'$ lies outside the ball of radius $(n/k - D_{\ref{lem-geo lying out imply out}})$ centered at $\phi(x)$.

$(b)$ $Hd_Y(\phi(\gamma), \gamma') \le D'_{\ref{lem-geo lying out imply out}}$.

$(c)$  $length~(\gm')\le A_{\ref{lem-geo lying out imply out}}~length(\gm)+A_{\ref{lem-geo lying out imply out}}$.
	\end{lemma}

	\begin{proof}
		Let $x_1=z_0,z_1,\cdots,z_l=x_2$ be points on $\gm$ such that $length~(\gm|_{[z_{t-1},z_t]})=1$ for all $1\le t\le l-1$ and $length~(\gm|_{[z_{l-1},z_l]})\le 1$, where $length~(\gm|_{[z_{t-1},z_t]})$ denotes the length of $\gm$ when restricted from $z_{t-1}$ to $z_t$. In particular, $d_X(z_{t-1},z_t)\le 1$ for all $1\le t\le l$. Let $\gm_1=\bigcup_{1\le t\le l}[z_{t-1},z_t]_X$ and $\gm_2=\bigcup_{1\le t\le l}[\phi(z_{t-1}),\phi(z_t)]_Y$. Note that $Hd_X(\gm,\gm_1)\le 1/2<1$, and so $\gm_1$ lies outside the ball of radius $(n-1)$ centered at $x$, i.e., $d_X(x,\gm_1)>n-1$. Since $\phi$ is $k$-qi embedding, we have

		\begin{enumerate}
			\item $length~(\gm_2)\le \sum_{t=1}^{t=l} (d_X(z_{t-1},z_t)k+k)\le2k~length~(\gm)+k$,

			\item $d_Y(\phi(x),\phi(\gm_1))>(n-1)/k-k$,

			\item $Hd_Y(\phi(\gm),\phi(\gm_1))\le2k$, 

			\item $Hd_Y(\phi(\gm_1),\gm_2)\le2k$, and so

			\item $d_Y(\phi(x),\gm_2)>(n-1)/k-3k$ and $Hd_Y(\phi(\gm),\gm_2)\le4k$.
		\end{enumerate}

		\noindent	Suppose $y_1,y_2\in\bt$ such that $d_Y(\phi(x_i),y_i)\le D_1$ where $D_1=D_{\ref{stability of qc}}(\dl,k)$ and $i=1,2$ (by the stability of quasigeodesics, Lemma \ref{stability of qc}). Then by (2) above, we have $d_Y(\phi(x),y_i)>(n-1)/k-k-D_1$ since $\phi(x_i)\in\phi(\gm_1)$ for $i=1,2$. Again, by Lemma \ref{bigger-bigger}, $d_Y(\phi(x),[\phi(x_i),y_i]_Y)>(n-1)/k-k-2D_1-2\dl$ for $i=1,2$. Set $\gm'=[y_1,\phi(x_1)]_Y\cup\gm_2\cup[\phi(x_2),y_2]_Y$.\smallskip

		\noindent	$(a)$ Hence, $d_Y(\phi(x),\gm')>~min~\{(n-1)/k-k-2D_1-2\dl,(n-1)/k-3k\}>(n-1)/k-3k-2D_1-2\dl=n/k-D_{\ref{lem-geo lying out imply out}}(\dl,k)$.\smallskip

		\noindent	$(b)$ Again, $Hd_Y(\gm_2,\gm')\le D_1$ implies $Hd_Y(\phi(\gm),\gm')\le4k+D_1=D'_{\ref{lem-geo lying out imply out}}(\dl,k)$.\smallskip

		\noindent	$(c)$ Finally, $length~(\gm')\le~length~(\gm_2)+2D_1\le2k~length~(\gm)+(k+2D_1)\le A_{\ref{lem-geo lying out imply out}}~length(\gm)+A_{\ref{lem-geo lying out imply out}}$ where $A_{\ref{lem-geo lying out imply out}}(\dl,k)=~max~\{2k,2D_1+k\}$.

		\noindent	This completes the proof.
	\end{proof}

	For a proper hyperbolic space $X$, when we say $\{x_n\}\sse X$ converges to a point $\xi\in\pa X$, we mean that for any $x\in X$, geodesic segments $[x,x_n]$ converges $($uniformly on compact sets$)$ to a geodesic ray representing $\xi$ (see \cite[Definition 3.5]{bridson-haefliger}). In this case, we write $\LMX x_n=\xi$ and sometimes, we say $\LMX x_n$ exists. We frequently encounter hyperbolic spaces $Y\sse X$ and sequence, say $\{y_n\}$, in $Y$, so to differentiate the convergence of $\{y_n\}$ in $\pa Y$ and in $\pa X$ we put a superscript in the limit.


	\begin{defn}\label{CT-map}\textup{({\bf Cannon--Thurston (CT) map})}\textup{(\cite[p. $136$]{mitra-trees})}
		Suppose $f:Y\ri X$ is a map between hyperbolic metric spaces. We say that $f$ admits the Cannon--Thurston map $($in short, CT map$)$ if there is a continuous map $\partial f :\partial Y\ri \partial X$ induced by $f$ in the following sense:

		For all $\xi\in \partial Y$ and for any sequence $\{y_n\}$ in $Y$ with $\LMY y_n=\xi$ one has $\LMX f(y_n)\newline=\partial f(\xi)$.
	\end{defn}

	In this case, $\partial f$ is called the {\em CT map} induced by $f$. When $Y$ is a subspace of $X$ equipped with the induced path metric, a CT map for the inclusion $i_{Y,X}:Y\map X$ is denoted by $\pa i_{Y,X}$. %The notion of CT map was defined by Mahan Mitra (\cite{mitra-trees}). The above definition is an adaptation of that; however, it is very easy to check that these two definitions are equivalent.
	We also note that the CT map is unique if it exists. %; and the existence of the CT map implies  that it is continuous (e.g. \cite[Lemma $2.50$]{ps-krishna}).

	\begin{defn}
		Suppose $A$ is any subset of a hyperbolic space $X$. The limit set of $A$ in $\pa X$ is $\Lambda_X(A):=\{\LMX a_n\in\pa X:\text{ for some sequence }\{a_n\}\sse A\}$.
	\end{defn}
	%The following result is straightforward. One may look at \cite[Lemma 2.55]{ps-krishna}.
	\begin{lemma}\textup{(\cite[Lemma 2.55]{ps-krishna})}\label{CT image is limit set}
		Suppose $Y\sse X$ are proper hyperbolic metric spaces such that the inclusion $i_{Y,X}:Y\map X$ admits a CT map $\pa i_{Y,X}:\pa Y\map\pa X$. Then $\pa i_{Y,X}(\pa Y)=\Lambda_X(Y)$. Note here that $Y$ is equipped with the induced path metric from $X$.
	\end{lemma}

