	The following result (Lemma \ref{require in bary}) provides a geometric criterion for convergence. The proof relies on the fact that the Gromov inner product of two points with respect to a third remains uniformly close to the distance from the third point to a geodesic joining the first two (see \cite[Lemma $17$]{GhH}, for instance). We state it without proof. %For a reference of the following lemma, one is referred to \cite[Proposition 3.21 and Exercise 3.18 (3)]{bridson-haefliger}
	\begin{lemma}\label{require in bary}
	Suppose $X$ is a proper hyperbolic geodesic metric space. Let $\{\xi_n\}$ and $\{\eta_n\}$ be sequences in $X$ (respectively, in $\partial X$), and let $\alpha_n$ be a geodesic segment (respectively, line) in $X$ joining $\xi_n$ and $\eta_n$. Assume that $\lim^X_{n \to \infty} \xi_n$ (respectively, $\lim^{\partial X}_{n \to \infty} \xi_n \in \partial X$) exists. Let $x \in X$ be arbitrary. Then: $$\lim_{n \to \infty} \eta_n\text{ exists in } \partial X\text{ and }\lim_{n\map\infty}\xi_n=\lim_{n\map\infty}\eta_n\in\pa X \text{ if and only if } \lim_{n\map\infty}d(x,\al_n)=\infty.$$
%		
%		Suppose $X$ is a proper hyperbolic geodesic metric space. Let $\{\xi_n\},\{\eta_n\}$ be sequences in $X$ $($respectively, in $\pa X)$. Let $\al_n$ be a geodesic segment $($respectively, line$)$ in $X$ joining $\xi_n$ and $\eta_n$. We also assume that $\LMX \xi_n$ $($respectively, $\lim^{\pa X}_{n\map\infty}\xi_n\in\pa X)$ exists. Let $x\in X$ be arbitrary. Then $\lim_{n\map\infty}\eta_n$ exists in $\pa X$ and $\lim_{n\map\infty}\xi_n=\lim_{n\map\infty}\eta_n\in\pa X$ if and only if $\lim_{n\map\infty}d(x,\al_n)=\infty$.
	\end{lemma}

	As a consequence of Lemma \ref{require in bary} and the stability of quasigeodesic (Lemma \ref{stability of qc}), we have the following results (Lemmas \ref{close give same limit} and \ref{on qc imp same}).

	\begin{lemma}\label{close give same limit}
		Suppose $X$ is a proper hyperbolic geodesic metric space. Let $\{x_n\},\{y_n\}\sse X$ be sequences such that $\LMX x_n\in\pa X$ and $d(x_n,y_n)\le D$ for some $D\ge0$. Then $\lim^X_{n\map\infty}y_n$ exists in $\pa X$ and $\lim^X_{n\map\infty}x_n=\lim^X_{n\map\infty}y_n$.
	\end{lemma}	

	\begin{lemma}\label{on qc imp same}
		Suppose $X$ is a proper hyperbolic geodesic metric space. Let $\{x_n\}\sse X$ be such that $\LMX x_n$ exists in $\pa X$. Fix $x\in X$, and let $k\ge1$. Let $\al_n$ be a $k$-quasigeodesic joining $x$ and $x_n$, and let $y_n\in\al_n$ such that $d(x,y_n)\map\infty$ as $n\map\infty$. Then $\LMX y_n$ exists in $\pa X$ and $\LMX y_n=\LMX x_n$.
	\end{lemma}

