	\subsection{Barycenter of ideal triangle}\label{bary sec}


	\begin{lemma}\textup{(\cite[Lemmas 1.17, 3.3, III.H]{bridson-haefliger})} \textup{(Barycenter for ideal triangles)}\label{barycenter}
		Given $\dl\ge0$, there are constants $D_{\ref{barycenter}}(\dl)\ge0$ and $R_{\ref{barycenter}}(\dl)\ge0$ depending only on $\dl$ such that the following holds.

		Suppose $X$ is a proper $\dl$-hyperbolic geodesic metric space. Let $\pa^3X:=\{(\xi_1,\xi_2,\xi_3)\in\pa X\times\pa X\times \pa X:\xi_1\ne\xi_2\ne\xi_3\ne\xi_1\}$. Given $(\xi_1,\xi_2,\xi_3)\in\pa^3X$ there is a point $x\in X$ which is $D_{\ref{barycenter}}(\dl)$-close to any line joining $\xi_i$ and $\xi_j$ for $i\ne j$ and $i,j\in\{1,2,3\}$. Moreover, for any other such point $x'\in X$, we have $d(x,x')\le R_{\ref{barycenter}}(\dl)$. 
	\end{lemma}


	Let $X$ be a proper hyperbolic geodesic metric space. Let $(\xi_1,\xi_2,\xi_3)\in\pa^3 X$. Then an ideal triangle with vertices $\xi_1,\xi_2,\xi_3$ is a union of choice of three geodesic lines joining $\xi_i$ and $\xi_j$ for all distinct $i,j\in\{1,2,3\}$; and one such triangle is denoted by $\triangle(\xi_1,\xi_2,\xi_3)$. Note that ideal triangles are coarsely well-defined. %(see Remark \ref{rmk-Hd-close} $(1)$). % That is, by Remark \ref{rmk-Hd-close} $(2)$, any two such ideal triangles are $2\dl$-Hausdorff close from each other.

	The following definition is motivated by Lemma \ref{barycenter} (see \cite[p. $1668$]{pranab-mahan}).
	\begin{defn}[Barycenter map]\label{barycenter map}
		Suppose $X$ is a proper $\dl$-hyperbolic geodesic metric space where $\dl\ge0$. For any $\xi=(\xi_1,\xi_2,\xi_3)\in\pa^3X$, a point $x$, as in Lemma \ref{barycenter} corresponding to $\xi$, is called barycenter of the ideal triangle $\triangle(\xi_1,\xi_2,\xi_3)$. Then we have a coarsely well-defined map $\pa^3X\map X$ (by Lemma \ref{barycenter}) sending $\xi$ to a barycenter. One such map is called the barycenter map and is denoted by $Bary_X$.

		For $D \ge 0$, a point $z \in X$ is called a $D$-barycenter of the ideal triangle $\triangle(\xi_1, \xi_2, \xi_3)$ if it $D$-close to each geodesic line joining $\xi_i$ and $\xi_j$ for distinct $i, j \in \{1, 2, 3\}$.
	\end{defn}
	%\begin{remark}
	%Note that in Definition \ref{barycenter map}, $x$ is a barycenter of any triangle $\triangle(\xi_1,\xi_2,\xi_3)$. It follows from by Lemma \ref{barycenter}. From now on, we call such a barycenter as {\em a barycenter of the ideal triangle $\triangle(\xi_1,\xi_2,\xi_3)$}.
	%\end{remark}
	\begin{remark}\label{rmk-bary map coarse surj in gp}
		Let $G$ be a nonelementary hyperbolic group. Fix a finite generating set for $G$. Let $\Gamma_G$ denote the Cayley graph of $G$ with respect to this generating set. Note that $G$ acts transitively on the vertex set $V(\Gamma_G)$, and this action naturally induces an action on the Gromov boundary $\partial G$ by homeomorphism. Consequently, the barycenter map for $\Gamma_G$ is $1$-coarsely surjective.
	\end{remark}


	The following result says that the second part of Lemma \ref{barycenter} is also true for $D$-barycenter where $D\ge0$.
	\begin{lemma}\textup{( \cite[Lemma 2.7]{pranab-mahan})}\label{D-barycenter}
		Given $D\ge0$ and $\dl\ge0$, there is $D_{\ref{D-barycenter}}(\dl,D)\ge0$ depending only on $\dl$ and $D$ such that we have the following. Suppose $X$ is a proper $\dl$-hyperbolic geodesic metric space. Then for any $\xi=(\xi_1,\xi_2,\xi_3)\in\pa^3X$ if $x,x'$ are two $D$-barycenters of the ideal triangle $\triangle(\xi_1,\xi_2,\xi_3)$ then $d(x,x')\le D_{\ref{D-barycenter}}(\dl,D)$.
	\end{lemma}


	As an immediate consequence of Lemma \ref{D-barycenter} and the stability of quasigeodesic (Lemma \ref{stability of qc}) we have the following. This says that barycenter commutes with quasiisometry.

\begin{lemma}\textup{(\cite[Lemma 2.8]{pranab-mahan})}\label{lem-barycenter commuting}
Let $k\ge1$, $\dl\ge0$ and $C\ge0$. Suppose $\phi:X\map Y$ is a $k$-quasiisometry between two (proper) $\dl$-hyperbolic geodesic metric spaces. Further, assume that the barycenter map for $X$ is $C$-coarsely surjective. Then the barycenter map for $Y$ is $C'$-coarsely surjective for some constant $C'\ge0$ depending only on $C$, $k$ and $\dl$.
\end{lemma}
