	\begin{lemma}\label{bdd barycen conv}
		Suppose $X$ is a proper $\dl$-hyperbolic geodesic metric space where $\dl\ge0$. Let $\xi_n=(\xi_{1,n},\xi_{2,n},\xi_{3,n})\in\pa^3X$ be such that $diam~\{Bary_X(\xi_n):n\in\N\}$ is bounded. Moreover, suppose that $\lim^{\pa X}_{n\map\infty}\xi_{i,n}=\xi_i\in\pa X$ for $i\in\{1,2,3\}$. Then

		$(1)$ $\xi=(\xi_1,\xi_2,\xi_3)\in\pa^3X$, and

		$(2)$ for all large $n$, we have $d_X(Bary_X(\xi_{n}),Bary_X(\xi))\le D_{\ref{bdd barycen conv}}(\dl)$ for some constant $D_{\ref{bdd barycen conv}}(\dl)\ge0$ depending only on $\dl$.
	\end{lemma}

	\begin{proof}
		$(1)$ If not, without loss of generality, we assume that $\xi_1=\xi_2$. Suppose $\al_n$ is a geodesic line in $X$ joining $\xi_{1,n}$ and $\xi_{2,n}$. Note that for any $x\in X$, $d(x,Bary_X(\xi_{n}))\ge d(x,\al_n)-D_{\ref{barycenter}}(\dl)$ (by Lemma \ref{barycenter}). Again by Lemma \ref{require in bary}, $d(x,\al_n)\map\infty$ as $n\map\infty$, and so $d(x,Bary_X(\xi_{n}))\map\infty$ as $n\map\infty$. This contradicts to the assumption that $diam~\{Bary_X(\xi_n):n\in\N\}$ is bounded. Hence (1) is proved.\smallskip

		$(2)$ Let $i,j\in\{1,2,3\}$ and $i\ne j$. Suppose $\al^{ij}$ is a geodesic line joining $\xi_i$ and $\xi_j$ such that (after reparametrization if necessary) $\al^{ij}(0)$ is $D_{\ref{barycenter}}(\dl)$-close to $Bary_X(\xi)$. Let $\al^{ij}_n$ be a geodesic line joining $\xi_{i,n}$ and $\xi_{j,n}$ such that $\al^{ij}_n$ converges to $\al^{ij}$. Then for all large $n$, $d_X(\al^{ij}(0),\al^{ij}_n)\le 1$ (say), and so $d_X(Bary_X(\xi),\al^{ij}_n)\le D_{\ref{barycenter}}(\dl)+1$ where $i\ne j$ and $i,j\in\{1,2,3\}$. This says that $Bary_X(\xi)$ is a $(D_{\ref{barycenter}}(\dl)+1)$-barycenter of triangle $\triangle(\xi_{1,n},\xi_{2,n},\xi_{3,n})$ for all large $n\in\N$. Then by Lemma \ref{D-barycenter}, for all large $n$, $d_X(Bary_X(\xi_{n}),Bary_X(\xi))\le D_{\ref{bdd barycen conv}}(\dl)$ where $D_{\ref{bdd barycen conv}}(\dl):=D_{\ref{D-barycenter}}(\dl,D_{\ref{barycenter}}(\dl)+1)$.
	\end{proof}


	\section{Exponential growth of graphs}\label{sec-exponential growth}We define the exponential growth of bounded valence metric graphs generalizing that of groups in Subsection \ref{subsec-expo growth} (see Definition \ref{defn-exponential growth}). This section aims to prove Theorem \ref{thm-bary imp expo growth}, which provides a sufficient condition under which a metric graph possesses exponential growth. Theorem \ref{thm-bary imp expo growth} is obtained by applying Theorem \ref{thm-emb of T3} and Lemma \ref{lem-qi implies exponential growth}.

\subsection{Embedding of trivalent trees in hyperbolic metric spaces}\label{subsec-qi emb of T3}In this subsection, we prove Theorem \ref{thm-emb of T3} and the proof requires following result.

	\begin{lemma}\label{lem-finding ind bary}
		Let $\dl\ge0$, $L\ge0$ and $D\ge0$. Then there exists a constant $C_{\ref{lem-finding ind bary}}=C_{\ref{lem-finding ind bary}}(\dl,L)\ge0$, depending only on $\dl$ and $L$, such that the following hold.

		Let $X$ be a (proper) $\dl$-hyperbolic geodesic metric space. Suppose the barycenter map $Bary_X:\pa^3X\map X$ is $L$-coarsely surjective.  Then:
		\begin{enumerate}
			\item	Let $x,y\in X$. Then we can find distinct points $y_1,y_2\in X$ such that $d(y,y_i)=D$ for $i=1,2$ and $$max\{(y_1,y_2)_y,~(x,y_1)_y,~(x,y_2)_y\}\le C_{\ref{lem-finding ind bary}}.$$

			\item Let $y\in X$. Then we can find distinct points $y_1,y_2,y_3\in X$ such that $d(y,y_i)=D$ for $i=1,2,3$ and $$max\{(y_i,y_j)_y:i\ne j\text{ and }i,j\in\{1,2,3\}\}\le C_{\ref{lem-finding ind bary}}.$$
		\end{enumerate}	
	\end{lemma}

	\begin{proof}
		$(1)$ Let $\xi=(\xi_1,\xi_2,\xi_3)\in\pa^3X$ be such that $d(Bary_X(\xi),y)\le L$. Let $\al_i$ be a geodesic ray joining $y$ and $\xi_i$ for $i\in\{1,2,3\}$. Fix $y_i\in\al_i$ such that $d(y,y_i)=D$ for $i\in\{1,2,3\}$.

		Fix distinct $i,j$ in $\{1,2,3\}$. Let $\bt$ be a geodesic line joining $\xi_i$ and $\xi_j$. Then $d(y,\bt)\le d(y,Bary_X(\xi))+d(Bary_X(\xi),\bt)\le L+D_{\ref{barycenter}}(\dl)$ (see Lemma \ref{barycenter}). Thus by Lemma \ref{lem-ideal tripod to finite}, we have $K=K_{\ref{lem-ideal tripod to finite}}(\dl,L+D_{\ref{barycenter}}(\dl))$ such that the arclength parametrization of $[y_i,y]\cup[y,y_j]$ is a $K$-quasigeodesic. Hence by Lemma \ref{lem-small inner prod}, we have $C=D_{\ref{lem-small inner prod}}(\dl,K)$ such that $$min\{(x,y_i)_y,~(x,y_j)_y\}\le C\hspace{4mm} (*)$$ Note that $i$ and $j$ are distinct in $\{1,2,3\}$. Therefore, at least two of $(x,y_1)_y,~(x,y_2)_y$ and $(x,y_3)_y$ are bounded by $C$. Without loss of generality, we assume that $(x,y_1)_y\le C$ and $(x,y_2)_y\le C$.

		Since the arclength parametrization of $[y_1,y]\cup[y,y_2]$ is a $K$-quasigeodesic, by the moreover part of Lemma \ref{lem-small inner prod}, we have $(y_1,y_2)_y\le C$.

		Therefore, we fix $C_{\ref{lem-finding ind bary}}(\dl,L)=C=D_{\ref{lem-small inner prod}}(\dl,K)$. This completes the proof of $(1)$.

		$(2)$ Replace $x$ in the proof of $(1)$ by $y_l$, where $l \in \{1,2,3\} \setminus \{i,j\}$. The same inequality $(*)$ then holds for $l$. Varying $i, j, l$ over $\{1,2,3\}$ with $i \neq j \neq l\ne i$, we conclude $(2)$.
	\end{proof}
