	\begin{theorem}\label{thm-emb of T3}
		Let $\dl\ge0$ and $L\ge0$. Then there exists a constant $K_{\ref{thm-emb of T3}}=K_{\ref{thm-emb of T3}}(\dl,L)\ge1$, depending only on $\dl$ and $L$, such that the following hold. 

		Suppose $X$ is a proper, $\dl$-hyperbolic geodesic metric space such that the barycenter map $Bary_X:\pa^3 X\map X$ is $L$-coarsely surjective. Then we have the following.

		\begin{enumerate}
			\item Given $x_0\in X$, there is a $K_{\ref{thm-emb of T3}}$-qi embedding $\phi:T_3\map X$ such that $x_0=\phi(v_0)$ for some $v_0\in V(T_3)$ and $\phi(u)\ne\phi(v)$ for all distinct vertices $u,v\in T_3$.

			\item Moreover, for all distinct vertices $u,v\in T_3$, we have $$Bary_X^{-1}(\phi(u))\cap Bary_X^{-1}(\phi(v))=\emptyset.$$ In other words, images of the vertices of $T_3$ can be realized as distinct barycenters in $X$.
		\end{enumerate}
	\end{theorem}


	\begin{proof}
Let us define some constants depending only on $\dl$ and $L$ as follows:

		\begin{itemize}
			\item $C=C_{\ref{lem-finding ind bary}}(\dl,L)$,

			\item $K=K_{\ref{local to global}}(\dl,C)\ge1$,

			\item $D=D_{\ref{local to global}}(\dl,C)+K^2+K.R_{\ref{barycenter}}(\dl)+1$, and

			\item $K_{\ref{thm-emb of T3}}(\dl,L)=D$.
		\end{itemize}
		Note that the constants $C$, $K$, $D$ and $K_{\ref{thm-emb of T3}}(\dl,L)$ depend only on $\delta$ and $L$. (Moreover, if we trace back the definitions of these constants, we observe that $D > L$.)

