			\item Let $[u,v]_{T_3}$ be an edge joining $u,v\in V(B(V_0,n))$. Then $[u,v]_{T_3}$ is mapped linearly onto a geodesic segment $[\phi_n(u),\phi_n(v)]_X$ such that $d_X(\phi_n(u),\phi_n(v))=D$.

			\item For all three distinct vertices $u,v,w\in V(B(v_0,n))$ such that $u$ and $v$ are adjacent to $w$, we have $(\phi_n(u),\phi_n(v))_{\phi_n(w)}\le C$.
		\end{enumerate} 

		%$(2)$ $\phi_n$ is a $K$-qi embedding.

		\noindent\underline{Induction step}: Now we will define a map $\phi_{n+1}:B(v_0,n+1)\map X$. We define $\phi_{n+1}|_{B(v_0,n)}=\phi_{n}$. (Now we apply Lemma \ref{lem-finding ind bary} $(1)$ at the point $x_i$.) By Lemma \ref{lem-finding ind bary} $(1)$, we have $y_i,z_i\in X$ such that $d_X(x_i,y_i)=D$, $d_X(x_i,z_i)=D$ and $$max\{(y_i,z_i)_{x_i},(y_i,x'_i)_{x_i},(z_i,x'_i)_{x_i}\}\le C \text{ for all }i\in\{1,\cdots,l\}.$$

