			\item  $(\phi_n(p_{i-1}),\phi_n(p_{i+1}))_{\phi_n(p_i)}\le C$ for all $i\in\{1,\cdots,m-1\}$.
		\end{itemize}
		Hence by Lemma \ref{local to global}, the arclength parametrization of the concatenation $$[\phi_n(p_0),\phi_n(p_1)]_X*\cdots*[\phi_n(p_{m-1}),\phi_n(m)]_X$$ is a $K$-quasigeodesic. Thus  $$\frac{1}{K}mD-K\le d_X(\phi_n(u),\phi_n(v))\hspace{5mm}(*)$$

