	\subsection{Growth}\label{subsec-expo growth}
	Growth of groups is a well-studied topic in geometric group theory (see \cite{mann-growbook}, \cite{grigor-intermegrowth-intro}). In this subsection, we study the growth of metric graphs with bounded valence (see Definition \ref{defn-valence}), which need not be Cayley graphs of groups. Although groups can exhibit various types of growth, we focus exclusively on exponential growth of metric graphs, as this is the primary focus of the article. We also mention that the definition of exponential growth (Definition \ref{defn-exponential growth}) coincides with that for groups (see \cite[Section $2.2$]{mann-growbook}).

	\begin{defn}\label{defn-valence}
For a metric graph $\Gamma$, the valence at a vertex $u\in V(\Gamma)$ is the number of edges adjacent to $u$. We say that the graph $\Gamma$ has bounded valence if there is a constant $D\ge0$ such that the valence at each vertex of $\Gamma$ is bounded by $D$.

We say that a collection of metric graphs $\{\Gamma_{\lm}:\lm\in\Lambda\}$ have uniformly bounded valence if there is a constant $D\ge0$ such that for every $\lm\in\Lambda$, the graph $\Gamma_{\lm}$ has bounded valence with the constant $D$ mentioned above.
	\end{defn}

\begin{remark}
Suppose $\Gamma$ is a metric graph with bounded valence. Further, assume that $D$ is the constant such that the valence at each vertex of $\Gamma$ is bounded by $D$. Then for every vertex $u$ of $\Gamma$, the number of vertices adjacent to $u$ is bounded by $D$. In what follows, we focus on counting the number of vertices adjacent to a given vertex.
\end{remark}	

%Note that the valence at each vertex is typically defined as the number of edges incident to it. In our context, we adapt the definition above to avoid counting arbitrarily many bigons between the same pair of vertices. This ambiguity can alternatively be resolved by passing to the first barycentric subdivision of the graph.

Let $\Gamma$ be a metric graph $\Gamma$ and $u\in V(\Gamma)$. Let $n\in\N$. We denote the ball of radius $n$ at $u$ by $B(u,n)$ and it is the set $\{v\in\Gamma:~d_{\Gamma}(u,v)\le n\}$. Let $||B(u,n)||$ denote the number of vertices in $B(u,n)$.

	\begin{defn}[Exponential growth]\label{defn-exponential growth}
		Suppose $\Gamma$ is a metric graph with bounded valence. We say that $\Gamma$ has exponential growth if there are constants $a>0$ and $b>1$ such that for every vertex $u\in\Gamma$ and for all $n\in\N$, we have $$||B(u,n)||\ge ab^n.$$These constants $a$ and $b$ are called the parameters of exponential growth of $\Gamma$. In this case, we say that $\Gamma$ has exponential growth with parameters $(a,b)$ where the second coordinate appears in the exponential factor.

		Let $\{\Gamma_{\lm}:\lm\in\Lambda\}$ be a collection of metric graphs having uniformly bounded valence. We say that $\{\Gamma_{\lm}:\lm\in\Lambda\}$ have uniform exponential growth if there are constants $a>0$ and $b>1$ such that $\Gamma_{\lm}$ has exponential growth with parameters $(a,b)$ for all $\lm\in\Lambda$.
	\end{defn}


	\begin{example}\label{exmp-T_3 expo}
		Suppose $T_i$ denotes the (simplicial) metric $m$-valent tree where $m\in\N$ (i.e., the valence at each vertex is exactly $m$). One can easily check that $T_3$ has exponential growth with parameters $(3/2,2)$. That is, the number of vertices in a ball of radius $n\in\N$ in $T_3$ is at least $\frac{3}{2}2^n$.
		%Then it is standard that all $T_i$'s are quasiisometric to each other. Since $T_4$ is the Cayley graph of free group of rank 2. Then by Theorem \ref{thm-exp growth rate hyp grp}, $T_4$ has exponential growth, and hence by Remark \ref{QI imp exp}, $T_3$ has exponential growth.
	\end{example}

	%Let $r\ge0$. Recall that in a metric space $X$ 

	\begin{lemma}\label{lem-qi implies exponential growth}
		Let $a>0,~b>1,~k\ge1$ and $D\ge2$. Then we have constants $a_{\ref{lem-qi implies exponential growth}}=a_{\ref{lem-qi implies exponential growth}}(a,b,k,D)>0$ and $b_{\ref{lem-qi implies exponential growth}}=b_{\ref{lem-qi implies exponential growth}}(k,b)=b^{1/k}>1$ such that the following holds.

	Suppose $(\Gamma_i, d_i)$ is a metric graph for $i = 1, 2$, and let $\phi : \Gamma_1 \to \Gamma_2$ be a $k$-qi embedding that maps vertices to vertices. Assume that the valence at each vertex of $\Gamma_1$ is bounded by $D$, and that $\Gamma_2$ is proper. Further, assume that $\Gamma_1$ has exponential growth with parameters $(a,b)$. Let $v\in V(\Gamma_2)$ be such that $d_2(\phi(u),v)\le k$ for some $u\in V(\Gamma_1)$. Then for all $m\in\N$, we have $$||B_2(v,m)||\ge a_{\ref{lem-qi implies exponential growth}}b_{\ref{lem-qi implies exponential growth}}^m$$where $B_2(v,m)$ denotes the $m$-radius ball centered at $v$ in $\Gamma_2$.
	\end{lemma}

	\begin{proof}
		Let $m\in\N$, $m\ge3k$ and $n=[\frac{m-2k}{k}]\in\N$ where $[r]$ denotes the greatest integer not greater than $r\in\R$. Let $d=[k^2]+1$. Let $B_1(u,n)$ denote the $n$-radius ball centered at $u$ in $\Gamma_1$. Let $A$ be a maximal $d$-separated subset of $V(B_1(u,n))$ (with respect to inclusion). Then for all $p\in B_1(u,n)$, we have $d_1(p,x)\le d+1$ for some $x\in A$.

		By the assumptions we have $||B_1(u,n)||\ge ab^n$ and $||B_1(p,d)||\le D^d$ for any $p\in V(\Gamma_1)$. Again $B_1(u,n)\sse \bigcup_{x\in A}B_1(x,d+1)$ implies $ab^n\le ||B_1(u,n)||\le ||A|| D^{d+1}$. Thus $||A||\ge aD^{-(d+1)}b^n$.

		Note that, as $\phi$ is $k$-qi embedding, $B_1(u,n)$ is mapped under $\phi$ in $B_2(\phi(u),nk+k)$. Since $d_2(\phi(u),v)\le k$, we have $\phi(B_1(u,n))\sse B_2(v,nk+2k)$, and so $\phi(B_1(u,n))\sse B_2(v,m)$ as $m\ge nk+2k$. On the other hand, for all distinct $x,x'\in A$, we have $\phi(x)\ne\phi(x')$. Indeed, suppose $\phi(x) = \phi(x')$. Then, since $d_1(x, x') \ge d$, the $k$-qi embedding condition gives $\frac{1}{k}d-k\le 0$, which implies $d \le k^2$ -- contradicting to the choice of $d$. 

		Hence $||B_2(v,m)||\ge||A||\ge aD^{-(d+1)}b^n\ge aD^{-(d+1)}b^{\frac{m-2k}{k}-1}=(aD^{-([k^2]+2)}b^{-3k})(b^{1/k})^n$  as $d=[k^2]+1$.


		Note that $\Gamma_2$ is connected. Let $t\in\N$ and $t< 3k$. Then $||B_2(v,t)||\ge2t+1\ge (2t+1)b^{t-3k}\ge b^{-3k}b^t\ge b^{-3k}(b^{1/k})^t$ as $k\ge1$ and $b\ge1$. Now we fix $a_{\ref{lem-qi implies exponential growth}}(a,b,k,D)=min\{aD^{-([k^2]+2)}b^{-3k},b^{-3k}\}>0$ and $b_{\ref{lem-qi implies exponential growth}}(b,k)=b^{1/k}>1$. Therefore, combining both the inequalities, for all $m\in\N$, we have $||B_2(v,m)||\ge a_{\ref{lem-qi implies exponential growth}}b_{\ref{lem-qi implies exponential growth}}^n$. This completes the proof.
	\end{proof}
	As a consequence of Lemma \ref{lem-qi implies exponential growth}, we have the following corollary. It says that the exponential growth of metric graphs is quasiisometry invariant.
	\begin{cor}\label{cor-exponential growth QI inv}
		Suppose $(\Gamma_i, d_i)$ is a metric graph for $i = 1, 2$, and let $\phi : \Gamma_1 \to \Gamma_2$ be a quasiisometry that maps vertices to vertices. Assume that each $\Gamma_i$ has bounded valence. Then $\Gamma_1$ has exponential growth if and only if $\Gamma_2$ has exponential growth.

		Moreover, the parameters of exponential growth of $\Gamma_1$ say, depend on that of $\Gamma_2$, quasiisometry constants and the number by which valence at each vertex is bounded.
	\end{cor}

	%As a corollary of Proposition 
	\begin{comment}
		\begin{remark}\label{QI imp exp}
			Suppose $\Gamma$ and $\Gamma'$ are two hyperbolic metric graph such that valence at each vertex is uniformly bounded. Let $\phi:\Gamma\map \Gamma'$ be a quasiisometry sending vertices to vertices. Then $\Gamma$ has exponential growth if and only if $\Gamma'$ has exponential growth. Moreover, note that parameters of exponential growth for, say $\Gamma$, depends on that of $\Gamma'$, hyperbolicity constant of $\Gamma'$, quasiisometry constants and the number by which valence at vertex is bounded.
