	\section{Metric graph bundles}\label{metric graph bundle sec}

In this section, we recall relevant results on metric graph bundles from \cite{pranab-mahan}. Following \cite[Proposition 6.6]{ps-krishna}, we give a detailed description of the boundary of a metric graph bundle over $[0,\infty)$ in Proposition \ref{description of pa X}. We also establish several related results needed in the next section. In particular, the notion of the `flow' of a subset (of a fiber) is introduced in Subsection \ref{subsec-flow}.	

	\begin{defn}\label{defn-proper embedding}
		Suppose $\phi:Y\map X$ is a map between metric spaces and $f:\R_{\ge0}\map\R_{\ge0}$ is a map. We say that $\phi$ is metrically $f$-proper (or simply $f$-proper) if for all $y,y'\in Y$ and $r\in\R_{\ge0}$ with $d_X(f(y),f(y'))\le r$ we have $d_Y(y,y')\le\phi(r)$.
	\end{defn}



	\begin{defn}\textup{(\cite[Definition 1.5]{pranab-mahan})}\label{defn-metric graph bundle}
		Suppose $X$ and $B$ are metric graphs, and $f:\N\map\N$ is a map such that $f(n)\map\infty$ as $n\map\infty$. We say that $X$ is an $f$-metric graph bundle over $B$ if there is a simplicial, surjective (and $1$-Lipschitz) map $\pi:X\map B$ such that the following hold.
		\begin{enumerate}
			\item For all $b\in V(B)$, $F_b:=\pi^{-1}(b)$, called fiber, is a connected subgraph of $X$ with respect to the path metric $d_b$ from $X$. The inclusion maps $(F_b,d_b)\map X$ are $f$-proper embedding.

			\item Let $b_1,b_2\in V(B)$ be adjacent vertices, and let $x\in V(F_{b_1})$. Then  $x$ is connected by an edge in $X$ to a point in $V(F_{b_2})$.
		\end{enumerate}

		Most of the time, we say that $\pi:X\map B$ is an $f$-metric graph bundle. Sometimes, we say that $X$ is a metric graph bundle over $B$ by making $f$ implicit.
	\end{defn}

	\begin{lemma}\textup{(\cite[Proposition 1.7]{pranab-mahan})}\label{lem-natural map QI}
		Suppose $\pi:X\map B$ is an $f$-metric graph bundle. %as in Definition \ref{defn-metric graph bundle}.
		Let $b_1,b_2\in V(B)$ such that $d_B(b_1,b_2)=1$. Let $\phi:F_{b_1}\map F_{b_2}$ be any map that sends $x\in V(F_{b_1})$ to $\phi(x)\in V(F_{b_2})$ such that $x$ and $\phi(x)$ are joined by an edge in $X$. Then $\phi$ is a $k_{\ref{lem-natural map QI}}(f)$-quasiisometry where $k_{\ref{lem-natural map QI}}(f)\ge1$ is a constant depending only on the function $f$.% as in Definition \ref{defn-metric graph bundle}.
	\end{lemma}

	\begin{defn}[Quasiisometric (in short, qi) lift]\label{qi lift}
		Let $k\ge1$. Suppose $\pi:X\map B$ is an $f$-metric graph bundle. Let $\gm:I\sse\R\map B$ be a geodesic joining two vertices in $B$. By a $k$-qi lift of $\gm$ we mean a $k$-qi embedding $\tilde{\gm}:I\map X$ such that $\pi\circ\tilde{\gm}=\gm$ on $I\cap\Z$.

		%When we say $\gm$ is a (quasi)geodesic we always mean its image and forget its domain.
	\end{defn}

In a hyperbolic metric space, (quasi)geodesics diverge exponentially. In an $f$-metric graph bundle $\pi:X\map B$, qi lifts are quasigeodesics. So, they diverge exponentially provided $X$ is hyperbolic. This property is captured in Definition \ref{flaring condition} for special types of quasigeodesics, namely, qi lifts. This definition is a generalization of the Bestvina--Feighn hallway flaring condition (\cite{BF}) in a natural way for metric graph bundles.

	\begin{defn}\textup{(\cite[Definition 1.12]{pranab-mahan})}\label{flaring condition}
		Suppose $\pi:X\map B$ is an $f$-metric graph bundle. Let $k\ge1$. We say that $\pi:X\map B$ satisfies a $k$-flaring condition if there are constants $M_k>0$ and $n_k\in\N$ depending on $k$, and $\lm>1$ such that for any geodesic $\gm:[-n_k,n_k]\map B$ joining two vertices and for any two $k$-qi lifts $\gm_0,~\gm_1$ of $\gm$ with $d_{\gm(0)}(\gm_0(0),\gm_1(0))>M_k$ we have $$\lm~d_{\gm(0)}(\gm_0(0),\gm_1(0))<\text{ max }\{d_{\gm(n_k)}(\gm_0(n_k),\gm_1(n_k)),d_{\gm(-n_k)}(\gm_0(-n_k),\gm_1(-n_k))\}.$$
	\end{defn}



	\begin{defn}\textup{(\cite[Definition $2.4$]{NirMaMj-commen})}\label{controlled fibers defn}
		We say that an $f$-metric graph bundle $\pi:X\map B$ has controlled hyperbolic fibers if there are $\dl\ge0$ and $L\ge0$ such that for all $b\in V(B)$,

		\begin{enumerate}
			\item $F_b$ is $\dl$-hyperbolic geodesic metric graph, and

			\item the barycenter map $\pa^3F_b\map F_b$ is $L$-coarsely surjective $($i.e., $L$-neighbourhood of the image is $F_b)$.
		\end{enumerate} 

		The constants $\dl$ and $L$ are called parameters.
	\end{defn}

	\begin{remark}
		Here in Definition \ref{controlled fibers defn}, one does not require $F_b$ to be a proper metric space. In that case, the barycenter map is defined for an ideal quasigeodesic triangle instead ideal geodesic triangle (see \cite[Lemma $2.7$]{pranab-mahan}).
	\end{remark}



	\begin{theorem}\label{thm-metric bundle comb}
		Suppose $\pi:X\map B$ is an $f$-metric graph bundle. Then we have the following.

		\begin{enumerate}
			\item \textup{(\cite[Proposition $5.8$]{pranab-mahan})} Suppose that the fibers and the total space $X$ are uniformly hyperbolic. Then $\pi:X\map B$ satisfies the $k$-flaring condition for all $k\ge1$.

			\item \textup{(\cite[Theorem $4.3$]{pranab-mahan})} Suppose the metric graph bundle $\pi : X \to B$ has controlled hyperbolic fibers and satisfies the $k$-flaring condition for all $k \ge 1$. Then $X$ is hyperbolic if and only if $B$ is.
		\end{enumerate}
	\end{theorem}

