	\subsubsection{Boundary of metric graph bundle}\label{boundary des sec}
	Let us start by recalling the following result.

	\begin{prop}\textup{(\cite[Proposition 2.3.3]{bowditch-stacks}, see also \cite[Proposition 6.6]{ps-krishna})}\label{des pa X}
		Suppose $\pi:X\map [0,\infty)$ is an $f$-metric graph bundle such that the fibers are uniformly hyperbolic and proper metric spaces. $($Note that $X$ is also proper$.)$ Assume that $X$ is hyperbolic. Then, as a set, $\pa X=\Lambda_X(F_0)\cup\pa_{qi}X$ where $\pa_{qi} X:=\{\Sigma(\infty):\Sigma\text{ is a 1-qi section over }[0,\infty)\}$.
	\end{prop}

	Now we will give a more detailed description of $\pa X$ in the context of controlled hyperbolic fibers (in Proposition \ref{description of pa X}) where the qi sections are replaced by {\em good qi sections}. The idea underlying this description can be traced back to \cite[Proposition 2.3.3]{bowditch-stacks} (see also \cite[Proposition 6.6]{ps-krishna}). While the description in \cite[Proposition 6.6]{ps-krishna} applies to an arbitrary hyperbolic base, we focus on the specific case where the base is $[0,\infty)$, as this is our requirement. Let us first prove the following result that is used in the proof of Proposition \ref{description of pa X}. 

	%The following result is proved in \cite[Lemma 6.5]{ps-krishna}. Here we are proving it a bit stronger version in a different way when the base is $[0,\infty)$, and the same prove works for general base.

	\begin{lemma}\label{unbdd imply in fiber}
		Suppose $\pi:X\map[0,\infty)$ is an $f$-metric graph bundle such that $X$ is hyperbolic. Let $k\ge 1$ and $\{n_i\}\sse\N$. Let $\Sigma_i$ be a $k$-qi lift of $[0,n_i]$. $($We have no condition on (un)boundedness of $\{n_i\}.)$ Let $x\in F_0$ and $\lim_{i\map\infty}d_0(x,\Sigma_i(0))=\infty$. Moreover, suppose that $\lim^X_{i\map\infty}\Sigma_i(n_i)$ exists in $\pa X$. Then $\lim^{X}_{i\map\infty}\Sigma_i(0)$ exists in $\pa X$ and $\lim^X_{i\map\infty}\Sigma_i(0)=\lim^X_{i\map\infty}\Sigma_i(n_i)$ in $\pa X$.
	\end{lemma}	

	\begin{proof}
		First of all $\lim_{i\map\infty}d_X(x,\Sigma_i)=\infty$. Indeed, if not, let $d_X(x,x_i)\le D$ for some $x_i\in\Sigma_i$ and $D\ge0$. Then $d(0,\pi(x_i))\le D$ since $\pi$ is $1$-Lipschitz. Thus $d_X(\Sigma_i(0),x_i)\le kD+k$ since the restriction of $\Sigma_i$ over $[0,\pi(x_i)]$ is a $k$-qi embedding in $X$. Hence $d_X(x,\Sigma_i(0))\le d_X(x,x_i)+d_X(x_i,\Sigma_i(0))\le (k+1)D+k$. Since fibers are $f$-proper embedding in $X$, so $d_0(x,\Sigma_i(0))\le f((k+1)D+k)$. This contradicts to the assumption that $\lim_{i\map\infty} d_0(x,\Sigma_i(0))=\infty$.

		Let $\al_i$ be a geodesic joining $\Sigma_i(0)$ and $\Sigma_i(n_i)$. Then by the stability of quasigeodesic (Lemma \ref{stability of qc}), we have $\lim_{i\map\infty}d_X(x,\al_i)=\infty$. Hence by Lemma \ref{require in bary}, $\lim^X_{i\map\infty}\Sigma_i(0)$ exists in $\pa X$ and $\lim^X_{i\map\infty}\Sigma_i(0)=\lim^X_{i\map\infty}\Sigma_i(n_i)$ in $\pa X$.
	\end{proof}
	The proof of the following result is a bit different from that of \cite[Proposition $6.6$]{ps-krishna} as we want a more detailed description of $\partial X$.
	\begin{prop}\label{mild imp special}
		Suppose $\pi:X\map [0,\infty)$ is an $f$-metric graph bundle such that the fibers are $\dl$-hyperbolic for some $\dl\ge0$. Suppose that $X$ is also $\dl$-hyperbolic. Further, assume that the fibers are proper metric spaces. Suppose $\Sigma_i$ is a good $K$-qi lift of $[0,i]$ for some $K\ge1$ such that $diam~\{\Sigma_i(0):i\in\N\}$ is bounded.

		Then there is a subsequence $\{i_n\}\sse \N$ such that $\LMX \Sigma_{i_n}(i_n)$ exists in $\pa X$. Moreover, there is a good $K_{\ref{for special qi sec}}(\dl,f)$-qi section, say $\Sigma$, over $[0,\infty)$ such that $\Sigma(\infty)=\lim^X_{n\map\infty}\Sigma_{i_n}(i_n)$.
	\end{prop}

	\begin{proof}
		Suppose $\xi^{(i)}_l=(\xi^{(i)}_{1,l},\xi^{(i)}_{2,l},\xi^{(i)}_{3,l})\in\pa^3F_l$ for $0\le l\le i$ such that $\Sigma_i(l)$ is a $K$-barycenter of the ideal triangle $\triangle(\xi^{(i)}_{1,l},\xi^{(i)}_{2,l},\xi^{(i)}_{3,l})$ in $F_l$. %Note that $\Sigma_i(l)$ is a $D_{\ref{barycenter}}(\dl)$-barycenter of the ideal triangle $\triangle(\xi^{(i)}_{1,l},\xi^{(i)}_{2,l},\xi^{(i)}_{3,l})$ in $F_l$ where $0\le l\le i$.
		Note that by Lemma \ref{D-barycenter}, we have $$d_l(Bary_{F_l}(\xi^{(i)}_l),\Sigma_i(l))\le D_{\ref{D-barycenter}}(\dl,max\{K,D_{\ref{barycenter}}(\dl)\})=D \text{ (say)}$$ for all $0\le l\le i$.\smallskip

		\noindent{\em Claim}: {\em Let $l\in\N\cup\{0\}$. Then $diam\{Bary_{F_l}(\xi^{(i)}_l):i\in\N\text{ and }i\ge l\}$ is bounded in $F_l$. (The bound need not be uniform.)}\smallskip

		\noindent{\em Proof of Claim}: Let $diam~\{\Sigma_i(0):i\in\N\}\le D'$ for some $D'\ge0$. Then for all $i,j\ge l$, we have $d_X(\Sigma_i(l),\Sigma_j(l))\le d_X(\Sigma_i(l),\Sigma_i(0))+d_X(\Sigma_i(0),\Sigma_j(0))+d_X(\Sigma_j(0),\Sigma_j(l))\le2Kl+2K+D'$ as $\Sigma_i,~\Sigma_j$ are $K$-qi embeddings. Hence, combining the above inequality, for all $i,j\ge l$, we have $d_X(Bary_{F_l}(\xi^{(i)}_l),Bary_{F_l}(\xi^{(j)}_l))\le 2D+D''$ where $D''=2Kl+2K+D'$. Thus $d_l(Bary_{F_l}(\xi^{(i)}_l),Bary_{F_l}(\xi^{(j)}_l))\le f(2D+D'')$. This completes the proof of claim.\qed\smallskip

		Now we will find a subsequence, say $\{i_n\}_n$, such that the following hold.

		\begin{enumerate}
			\item $\lim^{\pa F_m}_{n\map\infty}\xi^{(i_n)}_{j,m}=\eta_{j,m}\in\pa F_m$ for all $m\in\N\cup\{0\}$ and $j\in\{1,2,3\}$.

			\item Moreover, $\eta_m=(\eta_{1,m},\eta_{2,m},\eta_{3,m})\in\pa^3F_m$ for all $m\in\N\cup\{0\}$.

			\item Finally, barycenters of ideal triangles $\triangle(\eta_{1,m},\eta_{2,m},\eta_{3,m})$ in $F_m$ form the required qi section.
		\end{enumerate}

		First, we construct subsequences in each of the fibers satisfying properties $(1)$ and $(2)$, ensuring that each subsequent subsequence is contained in the preceding one. Then, we apply a diagonal argument to obtain properties $(1)$, $(2)$ and $(3)$ as stated above. The construction is by induction on the distance of the fiber from the initial one.

		%Note that %$F_0$ is a proper $\dl$-hyperbolic metric space. Then by Lemma \ref{bdd barycen conv}
		\noindent\underline{Initial step}: Note that
		\begin{itemize}
			\item $F_0$ is proper hyperbolic metric space, (so $\pa F_0$ is compact metrizable space) and

			\item $diam\{Bary_{F_0}(\xi^{(i)}_0):i\in\N\}$ is bounded. %by Claim above.
		\end{itemize} Then by Lemma \ref{bdd barycen conv}, after passing to a subsequence if necessary, we will have a subsequence, say $\{i_{n,0}\}_n$, such that $\lim^{\pa F_0}_{n\map\infty}\xi^{(i_{n,0})}_{j,0}=\eta_{j,0}$ for $j\in\{1,2,3\}$, and $\eta_0=(\eta_{1,0},\eta_{2,0},\eta_{3,0})\in\pa^3F_0$ and $d_0(Bary_{F_0}(\xi^{(i_{n,0})}_0),Bary_{F_0}(\eta_0))\le D_{\ref{bdd barycen conv}}(\dl)$ for all $n\in\N$.


		\noindent\underline{Induction hypothesis}: Suppose we have constructed the sequence till $m^{\text{th}}$-fiber where  $m\in\N$. That is, we have a subsequence, $\{i_{n,m}\}_n\sse\{i_{n,m-1}\}_n$ say, such that
		\begin{itemize}
			\item $\lim^{\pa F_m}_{n\map\infty}\xi^{(i_{n,m})}_{j,m}=\eta_{j,m}$ for $j\in\{1,2,3\}$,

			\item $\eta_m=(\eta_{1,m},\eta_{2,m},\eta_{3,m})\in\pa^3F_m$ and

			\item $d_m(Bary_{F_m}(\xi^{(i_{n,m})}_m),Bary_{F_m}(\eta_m))\le D_{\ref{bdd barycen conv}}(\dl)$ for all $n\in\N$.
		\end{itemize}

		\noindent\underline{Induction step}: Consider a natural quasiisometry map $\phi_m:F_m\map F_{m+1}$ (see Lemma \ref{lem-natural map QI}). Since $\Sigma_i$'s are good $K$-qi lift, by definition, we have $\pa\phi_m(\xi^{(i_{n,m})}_{j,m})=\xi^{(i_{n,m})}_{j,m+1}$ for all $n\in\N$ and for all $j\in\{1,2,3\}$. Now $F_{m+1}$ is proper hyperbolic metric space and $diam\{Bary_{F_{m+1}}(\xi^{(i_{n,m})}_{m+1}):n\in\N\}$ is bounded by Claim above. So after passing to a subsequence if necessary, (as in the initial step), we have a subsequence, $\{i_{n,m+1}\}_n\sse\{i_{n,m}\}_n$ say, such that $\lim^{\pa F_{m+1}}_{n\map\infty}\xi^{(i_{n,m+1})}_{j,m+1}=\eta_{j,m+1}\in\pa F_{m+1}$ for $j\in\{1,2,3\}$, and $\eta_{m+1}=(\eta_{1,m+1},\eta_{2,m+1},\eta_{3,m+1})\in\pa^3F_{m+1}$ and $$d_{m+1}(Bary_{F_{m+1}}(\xi^{(i_{n,m+1})}_{m+1}),Bary_{F_{m+1}}(\eta_{m+1}))\le D_{\ref{bdd barycen conv}}(\dl)$$ for all $n\in\N$. This completes the induction process.\smallskip

		\noindent Now, we set $i_n=i_{n,n}$. So we get a subsequence $\{i_n\}\sse\N$ satisfying $(1)$ and $(2)$ above. \smallskip Finally, we will define the required qi section $\Sigma$ as mentioned in $(3)$ and complete the proof.

		Since $\phi_n:F_n\map F_{n+1}$ induces a homeomorphism $\pa \phi_n:\pa F_n\map\pa F_{n+1}$, so $\pa \phi_n(\eta_{j,n})=\eta_{j,n+1}$ for all $j\in\{1,2,3\}$. Note that $Bary_{F_n}(\eta_n)$ is a $D_{\ref{barycenter}}(\dl)$-barycenter of the ideal triangle $(\eta_{1,n},\eta_{2,n},\eta_{3,n})$ (see Lemma \ref{barycenter}). Define $\Sigma:[0,\infty)\map X$ such that $\Sigma(n)=Bary_{F_n}(\eta_n)$ for all $n\in\N\cup\{0\}$ and for all $t\in[n,n+1)$, $\Sigma(t)=\Sigma(n)$. %where $\al_l$ is a fixed path in $\pi^{-1}([l,l+1])$ joining $Bary_{F_l}(\eta_l)$ and $\phi_l(Bary_{F_l}(\eta_l))$ of length at most $c$.
		Hence by Lemma \ref{for special qi sec}, $\Sigma$ is a good $K_{\ref{for special qi sec}}(\dl,f)$-qi section (see Definition \ref{good qi section}).

		Note that $i_n\ge n$. Then from the above construction, we have $d_X(\Sigma_{i_n}(n),\Sigma(n))\le d_n(\Sigma_{i_n}(n),Bary_{F_n}(\eta_n))\le d_n(\Sigma_{i_n}(n),Bary_{F_n}(\xi^{(i_n)}_n))+d_n(Bary_{F_n}(\xi^{(i_n)}_n),Bary_{F_n}(\eta_n))\le D+D_{\ref{bdd barycen conv}}(\dl)$. Then by Lemma \ref{close give same limit}, $\LMX\Sigma_{i_n}(n)=\Sigma(\infty)$. Since $\{\Sigma_{i_n}(n):n\in\N\}$ is unbounded, by Lemma \ref{on qc imp same}, $\LMX\Sigma_{i_n}(i_n)=\LMX\Sigma_{i_n}(n)$. Therefore, $\LMX\Sigma_{i_n}(i_n)=\Sigma(\infty)$. This completes the proof of Proposition \ref{mild imp special}.
