	\begin{remark}\label{rmk-comment}
		Note that in Proposition \ref{mild imp special}, the base of $\Sigma_i$ is assumed to be $[0,i]$. Here, $i$ in the interval $[0,i]$ is not important. One can replace the bases of $\{\Sigma_i\}$ by any subsequence $\{n_i\}$ such that $\lim_{i\map\infty}n_i=\infty$. For the ease of notation, we restricted ourselves to the base $[0,i]$.
	\end{remark}
	Now we will prove the main result of this subsection. Suppose $\pa_{good}X:=\{\Sigma(\infty):\Sigma\text{ is a good }K_{\ref{for special qi sec}}(\dl,f) \text{-qi section over }[0,\infty)\}$. With this notation we have the following.

	\begin{prop}\label{description of pa X}
		Suppose $\pi:X\map [0,\infty)$ is an $f$-metric graph bundle with controlled hyperbolic fibers, and suppose that $X$ is hyperbolic. Further, assume that the fibers are proper metric spaces. Then, as a set, $\pa X=\Lambda_X(F_0)\cup\pa_{good}X$.
	\end{prop}

	\begin{proof}
		Suppose the fibers and the total space $X$ are $\dl$-hyperbolic for some $\dl\ge0$. Let the barycenter maps for fibers be $L$-coarsely surjective for some $L\ge0$. Suppose $\al$ is a geodesic ray in $X$. %Suppose $\{i_n\}\sse\N$ is an unbounded sequence such that $\pi(\al(i_n))\in\N\cup\{0\}$.
		Let $n\in\N$. Then by Corollary \ref{cor-existence good qi}, there is a good $K$-qi lift, say $\Sigma_n$, over $[0,\pi(\al(n))]$ through $\al(n)$, where $K=K_{\ref{cor-existence good qi}}(\dl,L,f)$. So $d_X(\Sigma_n(0),\al(n))\le K~d(0,\pi(\al(n)))+K$.\smallskip

		\noindent {\em Case} 1: Suppose $diam~\{\Sigma_n(0):n\in\N\}$ is unbounded. Then by Lemma \ref{unbdd imply in fiber}, $\al(\infty)=\LMX \al(n)=\LMX\Sigma_n(0)\in\Lambda_X(F_0)$.\smallskip

		\noindent {\em Case} 2: Suppose $diam~\{\Sigma_n(0):n\in\N\}$ is bounded. Note that $\{\pi(\al(n)):n\in\N\}$ is unbounded. Indeed, if not, let $d(0,\pi(\al(n)))\le D$ for some $D\ge0$ and for all $n\in\N$. Then $d_X(\Sigma_n(0),\al(n))\le KD+K$ for all $n\in\N$. Since $diam~\{\Sigma_n(0):n\in\N\}$ is bounded, we have that $\{d_X(x,\al(n)):n\in\N\}$ is bounded for any fixed point $x\in F_0$. This contradicts the fact that $\al$ is a geodesic ray. 


		Then by Proposition \ref{mild imp special} (and Remark \ref{rmk-comment}), there is a good $K_{\ref{for special qi sec}}(\dl,f)$-qi section, say $\Sigma$, over $[0,\infty)$ and a subsequence $\{n_i\}\sse\N$ such that $\Sigma(\infty)=\lim^X_{i\map\infty}\Sigma_{n_i}(n_i)$. Again, $\lim^X_{i\map\infty}\al(n_i)=\al(\infty)$ implies that $\Sigma(\infty)=\al(\infty)$ in $\pa X$. This completes the proof of Proposition \ref{description of pa X}.
	\end{proof}

	We end this subsection by proving the following result, which is needed in the proof of Theorems \ref{thm-combo1} $(B)$ and \ref{main thm over ray graph gen}.

	\begin{lemma}\label{need in main thms}
		Suppose $\pi:X\map[0,\infty)$ is an $f$-metric graph bundle such that $X$ is hyperbolic. Let $k\ge1$, and let $\Sigma$ be a $k$-qi section over $[0,\infty)$. For all $n\in\N$, let $\Sigma_n$ be a $k$-qi lift of $[0,i_n]$ such that $d_0(x,\Sigma_n(0))\map\infty$ as $n\map\infty$ for a fixed $x\in F_0$. %$($We have no condition on (un)boundedness of $\{i_n\}.)$
		Moreover, assume that there is $M\ge0$ with $d_{i_n}(\Sigma_n(i_n),\Sigma(i_n))\le M$ for all $n\in\N$. Then we have $\LMX \Sigma_n(0)=\Sigma(\infty)$.
	\end{lemma}

	\begin{proof}
		First, we will prove that $i_n\map\infty$ as $n\map\infty$. If not, after passing through a subsequences, if necessary, we may assume that $i_n\le D$ for all $n\in\N$ and for some $D\ge0$. Now restrict both $\Sigma$ and $\Sigma_n$ on $[0,i_n]$. Thus $d_X(\Sigma(0),\Sigma(i_n))\le kD+k$ and $d_X(\Sigma_n(0),\Sigma_n(i_n))\le kD+k$. Hence by triangle inequality, $d_X(\Sigma(0),\Sigma_n(0))\le d_X(\Sigma(0),\Sigma(i_n))+d_X(\Sigma(i_n),\Sigma_n(i_n))+d_X(\Sigma_n(i_n),\Sigma_n(0))\le2(kD+k)+M=D'$ (say). Since the fibers are $f$-proper embedding in $X$, we have $d_0(\Sigma(0),\Sigma_n(0))\le f(D')$. This contradicts to the assumption that $d_0(x,\Sigma_n(0))\map\infty$ as $n\map\infty$ for a fixed $x\in F_0$.

		Again by Lemma \ref{close give same limit}, $\LMX\Sigma_n(i_n)$ exists in $\pa X$ and $\LMX\Sigma_n(i_n)=\Sigma(\infty)$. Now $\lim_{n\map\infty}d_0(x,\Sigma_n(0))=\infty$ implies, by Lemma \ref{unbdd imply in fiber}, $\lim^X_{n\map\infty}\Sigma_n(0)=\lim^X_{n\map\infty}\Sigma_n(i_n)$. Therefore, $\Sigma(\infty)=\lim^X_{n\map\infty}\Sigma_n(0)$. This completes the proof.
	\end{proof}

	\subsection{Flow}\label{subsec-flow}
	%In this subsection, {\em we assume that $\pi:X\map[0,\infty)$ is an $f$-metric graph bundle. Additionally, valence at each vertex in the fiber is bounded by $D$ where $D\ge2$.}

	%Now we will defined flow of any subset in the fiber. This is bit different from the flow defined in \cite[Chapter 3]{ps-kap} (see also \cite[Section 6]{halder}); but after taking quasiconvex hull in fibers they are same. Since we count the number of vertices in the flow, this will serve our purpose.

	Now we define the notion `flow' of a subset of a fiber. This version of flow differs slightly from the one introduced in \cite[Chapter 3]{ps-kap} (see also \cite[Section $6$]{halder-com}); however, after taking the quasiconvex hull in each fiber, the two definitions coincide. Since our focus is on counting the number of vertices in the flow, the present definition is more suitable for our purposes.
	\begin{defn}[Flow]\label{flow}
		Suppose $\pi:X\map[0,\infty)$ is an $f$-metric graph bundle such that the fibers have uniformly bounded valence.

		Suppose $A\sse V(F_0)$ is a subset. Let $k\ge1$. The $k$-flow of $A$ is denoted by $\F l_k(A)$ and is defined to be the union of all $k$-qi sections through points in $A$ over $[0,\infty)$.
	\end{defn}
	Suppose the number of vertices in any subset $C\sse X$ is denoted by $||C||$. The following result states that the flow of any subset can contain vertices from the fibers at most exponentially in distance.
	\begin{lemma}\label{exponentially bdd}
Let $k\ge1$ and $D\ge2$. Suppose $\pi:X\map[0,\infty)$ is an $f$-metric graph bundle such that the valence at each vertex in the fiber is bounded by $D$.

		Then there is $c=D^{f(4k)+1}>1$ such that for any subset $A\sse V(F_0)$, we have $||\F l_k(A)\cap F_i||\le ||A||c^i$ for all $i\in\N\cup\{0\}$.
	\end{lemma}	
	\begin{proof}
		Note that for any vertex $v\in A$, $diam (\F l_k(v)\cap F_1)\le4k$ in $X$-metric, and so $diam(\F l_k(v)\cap F_1)\le f(4k)$ in $F_1$-metric. Since the valence at each vertex in the fiber is bounded by $D$, we have $||\F l_k(v)\cap F_1||\le D^{f(4k)+1}=c>1$. Then $||\F l_k(A)\cap F_1||\le||A||c$. Inductively, we get $||\F l_k(A)\cap F_i||\le ||A|| c^i$ for all $i\in\N\cup\{0\}$.
	\end{proof}	

