\subsubsection{Hyperbolic plane bundles over hyperbolic planes}\label{hpbohp} Now we mention another source of examples where Theorem \ref{thm-application} $(B)$ can be applied. Based on a work of Leininger and Schleimer (\cite{ls-disk}), Mj and Sardar constructed a metric bundle $\pi:X\map \mathbb H^2$ such that the base and fibers are uniformly quasiisometric to the hyperbolic plane (see \cite[Example 5.4, pp. 1701-1705]{pranab-mahan}). (One is referred to Definition \ref{defn-metric bundle} for metric bundle, otherwise, for the time being, one can think of this as metric graph bundle after discretization.) One can apply Theorem \ref{thm-application} $(B)$ to this example.

	We mention that the surjectivity of a CT map in this example follows from previously known results. Fix $b\in\mathbb H^2$ and a geodesic ray $\al$ in $\mathbb H^2$ starting at $b$. Let $\pi^{-1}(\al)=X_{\al}$. Then by the result of Bowditch (Theorem \ref{bowditch thm}), the CT map $\pa\pi^{-1}(b)\map\pa X_{\al}$ is surjective. Hence by Theorem \ref{all direction surj imply surj}, the CT map $\pa \pi^{-1}(b)\map\pa X$ is surjective (see \cite[Corollary 6.27]{ps-krishna}).\qed

	\begin{remark}
		If one can construct examples analogous to the one above (Subsection \ref{hpbohp}) in the setting of $\operatorname{Out}(F_n)$ and Outer space, then Theorem \ref{thm-application} $(A)$ can be applied to obtain surjective CT maps.
	\end{remark}


	\subsubsection{Examples coming from (combinatorial) horoball}
	We conclude this subsection with Example \ref{exp-combinatorial horoball}, which illustrates that the following conditions:

	\begin{itemize}
		\item the barycenter maps for the fibers are uniformly coarsely surjective, and

		\item the fibers are uniformly quasiisometric to a fixed hyperbolic space
	\end{itemize}

	\noindent as in Theorem \ref{thm-combo1} $(B)$ and Question \ref{main qsn} respectively, are not necessary for surjectivity of the CT map. For the example, we first need the following result (Lemma \ref{lem-uniform hyp}) which in turn relies on Proposition stated below. %I would like to thank Pranab Sardar for helpful discussions related to Example \ref{exp-combinatorial horoball}.

	\begin{prop}\textup{(\cite[Proposition $3.1$]{bowditch-com})}\label{prop-bowditch's version}
		Let $D\ge0$. Suppose $X$ is a (connected) metric graph, and that for each $x,y\in V(X)$, we have associated a connected subgraph $c(x,y)\sse X$ with $x,y\in c(x,y)$ such that:

		\begin{enumerate}
			\item For all $x,y,z\in V(X)$, $c(x,y)\sse N_D(c(y,z)\cup c(z,x))$.

			\item For all $x,y\in V(X)$ with $d_X(x,y)\le1$, the diameter of $c(x,y)$ is bounded by $D$.
		\end{enumerate}
		Then $X$ is $\dl$-hyperbolic for some $\dl\ge0$ depending only on $D$. 
	\end{prop}



	\begin{lemma}\label{lem-uniform hyp}
		Let $i\in\N$. Let $F$ be a $\dl$-hyperbolic metric graph for some $\dl\ge0$.  Suppose $F_i$ is a metric graph obtained by attaching some extra edges to $F$ as follows. For all $u,v\in V(F)$, we attach an edge between $u$ and $v$ if $1<d_F(u,v)\le2^i$. Then $F_i$ is $\dl'$-hyperbolic for some $\dl'\ge0$ depending only on $\dl$. 
	\end{lemma}

	\begin{proof}
		We will use Bowditch's criterion as in Proposition \ref{prop-bowditch's version}. Let $x,y\in V(F_i)=V(F)$. Let $x=a_0,a_1,\cdots,a_l=y$ be vertices on a geodesic $[x,y]_F$ such that $$d_F(a_{k-1},a_k)=2^i \text{ for all }k\in\{1,\cdots,l-2\} \text{ and }d_F(a_{l-1},a_l)\le 2^i.$$ Define $c(x,y)=[a_0,a_1]_{F_i}*[a_1,a_2]_{F_i}*\cdots*[a_{l-1},a_l]_{F_i}$ as the concatenation of edges in $F_i$. Given $x,y\in V(F_i)$, we fix once and for all a connected path $c(x,y)\sse F_i$ as defined above.

		Now we will show that this collection of paths satisfies the Bowditch's criterion. Let $x,y,z\in V(F_i)$. So (without loss of generality) we have vertices $x=a_0,a_1,\cdots,a_l=y$, $y=b_0,b_1,\cdots,b_m=z$ and $z=c_0,c_1,\cdots,c_n=x$ on geodesics $[x,y]_F$, $[y,z]_F$ and $[z,x]_F$ respectively satisfying the following.

		\begin{enumerate}
			\item $d_F(a_{k-1},a_k)=2^i$ for all $k\in\{1,\cdots,l-2\}$ and $d_F(a_{l-1},a_l)\le 2^i$.

			\item $d_F(b_{k-1},b_k)=2^i$ for all $k\in\{1,\cdots,m-2\}$ and $d_F(b_{m-1},b_m)\le 2^i$.

			\item $d_F(c_{k-1},c_k)=2^i$ for all $k\in\{1,\cdots,n-2\}$ and $d_F(c_{n-1},c_n)\le 2^i$.
		\end{enumerate}
		\noindent We also have $c(x,y)$, $c(y,z)$ and $c(z,x)$ as concatenation of edges in $F_i$ as defined above. We will show that $c(x,y)\sse N_{2+\dl}(c(z,x),c(y,z))$ in $F_i$. Let $q\in c(x,y)$ and $p\in V(c(x,y))$ such that $d_{F_i}(p,q)\le1$. Since $F$ is hyperbolic, without loss of generality, we assume that there is $p'\in V([y,z]_F)$ such that $d_F(p,p')\le\dl$. By the definition of $F_i$, we have $k\in\{0,1,\cdots,m\}$ such that $d_{F_i}(p',b_k)=1$. This shows, by triangle inequality, that $d_{F_i}(q,b_k)\le 2+\dl$. In other words, $c(x,y)\sse N_{2+\dl}(c(z,x),c(y,z))$ in $F_i$. This verifies the condition $(1)$ of Proposition \ref{prop-bowditch's version} with $D=2+\dl$. On the other hand, condition $(2)$ is satisfied with $D=1$. Therefore, by Proposition \ref{prop-bowditch's version}, $F_i$ is $\dl'$-hyperbolic for some $\dl'\ge0$ depending only on $\dl$.
	\end{proof}

	For the construction of {\em combinatorial horoball} and related results, we refer the reader to \cite[Section $3.1$]{dehn-filling-GM} (cf. \cite[$8.6$]{gromov-hypgps}).\smallskip

\noindent	{\bf Combinatorial horoball}: Suppose $F$ is a proper, connected metric graph. Now we construct a metric graph $X$ as follows.

	\begin{enumerate}
		\item $V(X)=V(F)\times (\{0\}\cup\N)$

		\item Edges of $X$ are defined as follows. Let $u,v\in V(F)$ and $i\in\{0\}\cup\N$.

		\begin{enumerate}
			\item If $u,v$ are joined by an edge in $F$, then $(u,0)$ and $(v,0)$ are joined by an edge in $X$.

			\item If $i>0$ and $0<d_F(u,v)\le 2^i$ then $(u,i)$ and $(v,i)$ are joined by an edge in $X$. 

			\item $(u,i)$ and $(u,i+1)$ are joined by an edge in $X$.
		\end{enumerate}
	\end{enumerate} 
	Since the edges of $X$ are isometric to the closed unit interval, so $X$ is a geodesic metric space. By \cite[Theorem $3.8$]{dehn-filling-GM}, $X$ is $\dl$-hyperbolic for some universal constant $\dl\ge0$. That is, $\dl$ does not depend on $F$. Note that ($X$ is proper and) $\pa X$ consists of single point (see \cite[Lemma $3.11$]{dehn-filling-GM}).

	\noindent We have a natural projection map $\pi:X\map[0,\infty)$ as follows. Let $u,v \in V(F)$ and $i\in\{0\}\cup\N$. Edges joining $(u,i)$ and $(v,i)$ are mapped to $i$ and edges joining $(u,i)$ and $(u,i+1)$ are isometrically mapped to the interval $[i,i+1]\sse[0,\infty)$. It is easy to see that $\pi:X\map[0,\infty)$ is a metric graph bundle. $($Condition $(2)$ of Definition \ref{defn-metric graph bundle} follows from $(c)$ above whereas condition $(1)$ follows from \textup{\cite[Lemma $3.10$]{dehn-filling-GM}} and the definition of $X.)$ %In particular, fibers are $f$-proper embedding in $X$ where $f:\N\map\N$ sending $n\mapsto2^n$, $n\in\N.)$ 
	Note that $\pi^{-1}(i)=F_i$ as constructed in Lemma \ref{lem-uniform hyp}.

	\begin{example}\label{exp-combinatorial horoball}
		In the above construction of combinatorial horoball, we assume that $F$ is an unbounded $\dl'$-hyperbolic geodesic metric graph for some $\dl'\ge0$. 

		In this case, the fibers are uniformly hyperbolic by Lemma \ref{lem-uniform hyp}, %In fact, the hyperbolicity constant of $\pi^{-1}(i)$ depends on $i$ (for instance, $2^{-i}\dl'$) and it tends to $0$ as $i$ tends to $\infty$. 
		and the inclusion $F_0\map X$ admits a CT map by \textup{\cite{mitra-trees}}. Hence $\pa i_{F_0,X}:\pa F_0\map\pa X$ is surjective as $\pa X$ is singleton.

		If the barycenter map for $F$ were not coarsely surjective, then the metric graph bundle $\pi:X\map[0,\infty)$ would not have uniformly coarsely surjective barycenter maps for its fibers.

		Note that the fibers do not have uniformly bounded valence, even if the original graph $F$ does have bounded valence. $($The valence of a vertex in $F_i$ increases as $i$ increases.$)$
	\end{example}

	\begin{remark}\label{rmk-fibers are not uniformly QI}
		We mention that in Example \ref{exp-combinatorial horoball}, the fibers $F_i$ are uniformly hyperbolic (Lemma \ref{lem-uniform hyp}); however, they are not uniformly quasiisometric to $F$, since a geodesic segment in $F$ of length $2^i$ is mapped to a single edge in $F_i$.
	\end{remark}

	\begin{remark}\label{rmk-Hn can not be fiber}
		We refer the reader to Definition \ref{defn-metric bundle} for metric bundle. In Example \ref{exp-combinatorial horoball}, fiber $F$ can be any hyperbolic metric graph (space), and the base of the metric graph bundle is $[0,\infty)$. By Example \ref{exp-combinatorial horoball}, one should not be confused with the result proved in \cite[p. $93$]{bowditch-stacks}. The result says that $\mathbb H^n$, $n\ge3$ can not appear as fibers of a metric bundle over $\R$. Here author means that the fibers are isometric to $\mathbb H^n$. (We mention that the same result holds if one replaces the isometry by uniform quasiisometry.) Whereas, in Example \ref{exp-combinatorial horoball}, the fibers are not uniformly quasiisometric to a fixed hyperbolic space by Remark \ref{rmk-fibers are not uniformly QI}.
