	\subsection{Cannon--Thurston lamination}\label{subsec-CT lamination} Suppose $W$ is a hyperbolic metric space. Let $\pa^2W:=\{(p,q)\in\pa_s W\times\pa_s W:p\ne q\}$. Following \cite{mitra-endlam}, one can define Cannon--Thurston lamination as follows.

	\begin{defn}[Cannon--Thurston lamination]
		Suppose $X'\sse X$ are hyperbolic metric spaces such that the inclusion $i_{X',X}:X'\map X$ admits a CT map $\pa i_{X',X}:\pa_s X'\map\pa_s X$. The Cannon--Thurston lamination is then defined as $$\L_{CT}(X',X):=\{(p,q)\in\pa^2X':\pa i_{X',X}(p)=\pa i_{X',X}(q)\}.$$
	\end{defn}

	\noindent\underline{{\em Our context}}: Suppose $\pi:X\map B$ is an $f$-metric graph bundle with controlled hyperbolic fibers. Further, suppose that $X$ is hyperbolic. Note that $B$ is also hyperbolic (see Theorem \ref{thm-metric bundle comb} $(1)$). Suppose $B$ is $\dl$-hyperbolic for some $\dl\ge0$. Let $b\in V(B)$ and $F=F_b$, and $\eta\in\pa_sB$. Let $\al:[0,\infty)\map B$ be a $k$-quasigeodesic joining $b$ and $\eta$ for some $k\ge1$ depending on $\dl$ (see Remark \ref{qg boundary}). We also assume that $\al$ is injective and continuous (see \cite[Lemma $1.11$, $III.H$]{bridson-haefliger}). Then $\al$ has a $k$-qi lift in $X$. Define the set $$\pa^{\eta}X:=\{\al'(\infty):\al'\text{ is a }k\text{-qi lift of }\al\}$$ which is determined by $\eta$ (see \cite[Corollary $6.5$]{ps-krishna}). Now define $$\pa^{(2)}_{\eta,X}(F):=\{(p,q)\in\pa^2F:\pa i_{F,X}(p)=\pa i_{F,X}(q)\in\pa^{\eta}X\}.$$

We refer the reader to \cite[Subsection $6.2$]{ps-krishna} (see also \cite{mitra-endlam}) for more on the properties of the Cannon--Thurston lamination in the context of metric graph bundles. The following result provides a criterion for which $\pa^{(2)}_{\eta,X}(F)$ is non-empty. Recall that {\em dendrite} is a compact metric space in which any two distinct points are connected by a unique arc.

	\begin{theorem}\label{thm-lamination}
Suppose $\pi:X\map B$ is an $f$-metric graph bundle with controlled hyperbolic fibers. Further, suppose that $X$ is hyperbolic. Moreover, we assume one of the following.


$(A)$ The fibers have uniformly bounded valence.

$(B)$ The fibers are one-ended and proper metric spaces.

Finally, suppose that one of the following holds.

\begin{enumerate}
\item Let $b\in V(B)$. Suppose that $\pa F_b$ is not homeomorphic to a dendrite.

\item  Fibers are uniformly quasiisometric to a fixed nonelementary hyperbolic group.		
\end{enumerate}		%\smallskip

		Then for all $\eta\in\pa_s B$, we have $\pa^{(2)}_{\eta,X}(F)\ne\emptyset$.
	\end{theorem}

It is standard that the boundary of a nonelementary hyperbolic group is not homeomorphic to a dendrite. Now Theorem \ref{thm-lamination} follows by combining the following result (Theorem \ref{thm-lam-KP}) due to Krishna and Sardar with this fact, along with Theorem \ref{thm-application}.

	\begin{theorem}\textup{(\cite[Theorem $6.30$]{ps-krishna})}\label{thm-lam-KP}
		Suppose $\pi:X\map B$ is an $f$-metric graph bundle with controlled hyperbolic fibers. Further, suppose that the fibers are proper metric spaces. Let $b\in V(B)$ and $F=F_b$. Moreover, assume that $\pa F$ is not homeomorphic to a dendrite. Finally, suppose that $X$ is hyperbolic and the CT map $\pa i_{F,X}:\pa F\map\pa X$ is surjective.

		Then for all $\eta\in\pa_s B$, we have $\pa^{(2)}_{\eta,X}(F)\ne\emptyset$.
	\end{theorem}
