  \label{creg}
\end{figure}

The variance of the smoothed fGn $\xi_{\Delta}(t)$, as follows from Eq.~(\ref{regfGn}), is 
\begin{equation}\label{varfGn}
\text{Var}_{\xi}(H,\Delta) \equiv c_{\Delta}(t,t) = \frac{4^H D \Delta ^{2 H-2} |H| \Gamma\left(H+\frac{1}{2}\right)}{\sqrt{\pi}}\,.
\end{equation}
Comparing it with the variance of the smoothed fBm, Eq.~(\ref{variance}), we obtain a simple relation
\begin{equation}\label{Varratio}
\frac{\text{Var}_{\xi}(H,\Delta)}{\text{Var} (H,\Delta)}=\frac{\Delta^2}{|H|}\,.
\end{equation}
Figure \ref{variancexi} depicts $\text{Var}_{\xi}(H,\Delta)$ as a function of $H$ for three values of $\Delta$.  

