\section{Bootstrap Current Formulation}\label{appA}
The bootstrap current formulation used in this study is follows Eq. \ref{eq:A1} (\cite{sauter1999neoclassical}; \cite{10.1063/1.1517052}) and Eq.\ref{eq:A2} (\cite{redl2021new}). 

\begin{equation}
\langle \boldsymbol{J_x \cdot B}\rangle=\langle j_{\parallel}B\rangle =-F(\psi)\left({pL_{31}\frac{\partial \:\text{ln}\:p}%
  {\partial \psi}+p_eL_{32}\frac{\partial \:\text{ln}\:T_e}%
  {\partial \psi}+p_i\alpha L_{34}\frac{\partial\: \text{ln}\:T_i}%
  {\partial \psi}}\right) \label{eq:A1}
\end{equation}


\begin{equation}
\langle \boldsymbol{J_x \cdot B}\rangle=\langle j_{\parallel}B\rangle =-F(\psi)\left({pL_{31}\frac{\partial\: \text{ln}\:n}%
  {\partial \psi}+p_e(L_{31}+L_{32})\frac{\partial\: \text{ln}\:T_e}%
  {\partial \psi}+p_i(L_{31}+\alpha L_{34})\frac{\partial\: \text{ln}\:T_i}%
  {\partial \psi}}\right) \label{eq:A2}
\end{equation}

where $F(\psi)=RB_\phi$, $\psi$ is poloidal flux per radian i.e. $\Psi_p=2\pi\psi$, $R$ is the major radius and $B_\phi$ the toroidal magnetic field. For details on the definitions of the coefficients in these equations, please refer to the corresponding references.

For convenience, the common terms used to calculate the coefficients in Eq.\ref{eq:A1} and Eq.\ref{eq:A2} and their definitions, as presented in \cite{sauter1999neoclassical} and \cite{redl2021new} are summarized below:

The trapped particle fraction, denoted by $f_t$ is
\begin{equation}
f_{t}=1-\frac{3}{4}\langle B^2\rangle\int_0^{1/B_{max}}\frac{\lambda d\lambda}{\langle \sqrt{1-\lambda B}\rangle}.
\end{equation}
The effective electron and ion collisionalities are
\begin{subequations}
    \begin{equation}
    \nu_e^*=6.921 \times 10^{-18} \frac{qRn_e \:\text{ln} \:\Lambda_e}{T_e^2\varepsilon^{3/2}}, \label{eq:C2a}
    \end{equation}
    \begin{equation}
    \nu_i^*=4.9 \times 10^{-18} \frac{qRZ^4n_e \:\text{ln} \:\Lambda_{ii}}{T_i^2\varepsilon^{3/2}}, \label{eq:C2b}
    \end{equation}
\end{subequations}
The Coulomb logarithms are:
\begin{subequations}
    \begin{equation}
    \Lambda_e=31.3-\text{ln}\left( \frac{\sqrt{n_e}}{T_e} \right). 
    \end{equation}
    \begin{equation}
    \Lambda_{ii}=30-\text{ln}\left( \frac{Z^3\sqrt{n_i}}{T_i^{3/2}} \right). 
    \end{equation}
\end{subequations}
Here, $R$ [m] is the major radius, $q=1/i$ is the safety factor, electron ($T_e$) and ion ($T_i$) temperatures in eV and densities ($n_e$ and $n_i$) in m$^{-3}$.


\section{Isomorphism}\label{appB}
For applicability to quasisymmetric stellarators, the \cite{redl2021new} formula is modified according to the isomorphism as defined in \citet[]{landreman2022optimization}, see Eq. \ref{eq:Landreman}. 

Noting that the rotational transform is defined as $\partial \psi/\partial \psi_t = \iota$, we have 
\[
\frac{\partial}{\partial \psi_t} = \iota \frac{\partial}{\partial \psi}
\]
In case of axisymmetry, $N=0$ and $G=I=RB_\phi$ in Eq. \ref{eq:Landreman} recovers the result of \cite{redl2021new}. For the calculation of the bootstrap coefficients, the factors $qR$ in equations \ref{eq:C2a} and \ref{eq:C2b} and the inverse aspect ratio $\epsilon$ are defined as follows:
\begin{subequations}
    \begin{equation}
    qR=\frac{G+iI}{i-N} \left\langle {\frac{1}{B}}\right \rangle,
    \end{equation}
    \begin{equation}
    \epsilon=\frac{B_{max}-B_{min}}{B_{max}+B_{min}}.
    \end{equation}
\end{subequations}


\section{M3D-C1: Single Fluid Equations}\label{appC}
Summary of the M3D-C1 equations used in this study (reproduced from \cite{jardin2012multiple}). 
\begin{equation}
\frac{\partial n}{\partial t}+\boldsymbol{\nabla} \cdot (n \boldsymbol{v})=0 ,\:\:\:\:\text{continuity},
\end{equation}
\begin{equation}
nm_i\left(\frac{\partial \boldsymbol{v}}{\partial t}+\boldsymbol{v \cdot \nabla v} \right)=\boldsymbol{J} \times \boldsymbol{B}-\nabla p-\boldsymbol{\nabla \cdot \Pi}+\boldsymbol{{F}}, \:\:\:\:\text{momentum},\label{eq:momentum}
\end{equation}
\begin{equation}
    \begin{aligned}
        \frac{\partial p}{\partial t}+\boldsymbol{v} \cdot \nabla p+ \Gamma p\nabla \cdot \boldsymbol{v} &=(\Gamma-1)[\eta J^2-\boldsymbol{\nabla \cdot q} - \boldsymbol{\Pi:\nabla v} +Q],\:\:\:\:\text{energy},\\
        &=(\Gamma-1)[\eta \boldsymbol{J \cdot (J-J_x)}-\boldsymbol{\nabla \cdot q} - \Pi:\nabla \boldsymbol{v} +Q]\label{eq:modifiedenergy}
    \end{aligned}
\end{equation}



\begin{subequations}
    \begin{equation}
        \begin{aligned}
        \frac{\partial \boldsymbol{B} }{\partial t}&=\boldsymbol{\nabla \times (v \times B}-\eta [\boldsymbol{J}])\\
        &=\boldsymbol{\nabla \times (v \times B}-\eta [\boldsymbol{J}-\boldsymbol{J}_x]),\label{eq:modifiedohms}
        \end{aligned}
    \end{equation}
    \begin{equation}
    \boldsymbol{J}=\frac{1}{\mu_0}\boldsymbol{\nabla \times B},\:\:\:\:\text{Maxwell},
    \end{equation}
\end{subequations}

    \begin{equation}
        \begin{aligned}
        \boldsymbol{q}=\kappa_\perp \nabla T_e -\kappa_{\parallel} \frac{\boldsymbol{B}\boldsymbol{B}}{B^2} \cdot \nabla T_e,\label{eq:heat}\:\:\:\:\text{heat transport model}
        \end{aligned}
    \end{equation}



where $n$ is the density, $\boldsymbol{v}$ is the fluid velocity, $m_i$ is ion mass, $\boldsymbol{J}$ is the current density, $\boldsymbol{B}$ is the magnetic field, $p$ is the pressure, $\Pi$ is the viscous stress tensor, $\boldsymbol{F}$ is the external force, $Q$ is external heat source, $\Gamma =$ 5/3, $\eta$ is the resistivity, $\boldsymbol{q}$ is the heat flux, ${\mu_0}$ is the vacuum permeability.



