\section{Preliminaries}

Throughout the paper, we write $0_d$ for the origin of $\setR^d$, we let $\setB_r^d(x)$ stand for the Euclidean ball of radius $r$ centered at $x \in \setR^d$, and we write $\setB_r^d$ and $\setB^d$ instead of $\setB_r^d(0_d)$ and $\setB_1^d(0_d)$ respectively. We let $(e_1,\ldots,e_d)$ denote the canonical basis of $\setR^d$. For $y \in \setR^d$ we will often denote by $y'$ the $d-1$ first coordinates of $y$ in the canonical basis of $\setR^d$, and we let $y_d$ be the last one. We consider the open upper half space $\mathbb{H}^d:=\{y \in \setR^d : y_d > 0\}$ and the Euclidean unit sphere $\mathbb{S}^{d-1}\df \{y \in \setR^d : y_1^2 + \ldots + y_d^2 = 1\}$. We let $\sigma$ be the usual surface measure on $\mathbb{S}^{d-1}$ which coincides with the $(d-1)$-dimensional Hausdorff measure of the Euclidean distance. We also write $\mathcal{L}^d$ for the $d$-dimensional Lebesgue measure in $\mathbb{R}^d$.

For a subset $A$ of the Euclidean space  $\setR^d$, we let $\bar{A}$ be the closure of $A$ and $int(A)$ be its interior. We recall that a rigid motion of $\setR^d$ is a linear map $R : y \mapsto Ay+b$ where $A\in O(d)$ and $b\in \ddim$. The epigraph and strict epigraph of $\gamma : \setR^d \to \setR$ 
are respectively defined as
\[
epi(\gamma) \df \{ y \in \setR^d : y_d \ge \gamma(y')\} \quad \text{and} \quad \mathring{epi}(\gamma) \df \{ y \in \setR^d : y_d > \gamma(y')\}.
\]
When $\gamma$ is continuous, we obviously have
\begin{equation}\label{eq:epi=}
epi(\gamma) = \overline{\mathring{epi}(\gamma)}.
\end{equation}
The directional derivative of $\gamma$ at $x \in \setR^d$ in the direction $v \in \setR^d$ is defined as
\[
\gamma'(x;v) \df \lim_{t \downarrow 0} \frac{\gamma(x+tv)-\gamma(x)}{t}
\]
whenever the limit exists.




\subsection{Boundary points}


For an open set $\Omega \subset \setR^d$ with a non-empty boundary $\partial \Omega$, we will call boundary points of $\Omega$ the elements in $\partial \Omega$. Inspired by \cite[p.626]{Evans}, we define the regularity of boundary points as follows. 

\begin{definition}\label{C0 boundary pt}
    Let $\Omega$ be an open subset of $\ddim$ with a non-empty boundary $\partial \Omega$, and $x \in \partial \Omega$. Consider $k \in \mathbb{N}\cup \{\infty\}$ and $\alpha \in (0,1]$.
    \begin{enumerate}
        \item We say that $x$ is a $\cC^k$ boundary point of $\Omega$ if there exist $\delta>0$ and $\gamma \in \cC^k(\setR^{d-1})$ such that, up to applying a rigid motion,
        \begin{equation}\label{eq:boundary_points}\tag{*}
        \begin{cases}
        \bar{\Omega} \cap  \setB_\delta^d(x)  = epi(\gamma)  \cap \setB_\delta^d(x), \nonumber\\
        \Omega \cap \setB_\delta^d(x)  = \mathring{epi}(\gamma)  \cap \setB_\delta^d(x).
        \end{cases}
        \end{equation}

    \item We say that $x$ is a $\cC^{k,\alpha}$ boundary point of $\Omega$ if it satisfies \eqref{eq:boundary_points} for some $\gamma \in \cC^{k,\alpha}(\setR^{d-1})$, up to a rigid motion.
    \item We say that $x$ is a directionally differentiable (d.d.~for brevity) boundary point if it is a $\cC^0$ boundary point with a function $\gamma$ as above whose directional derivative $\gamma'(x';v')$ exists for any $v' \in \mathbb{R}^{d-1}$, where we identify $x$ with its image $(x',x_d)$ through the rigid motion from (1).
    \item We say that $x$ is a continuously directionally differentiable (CDD for brevity) boundary point if it is a d.d.~point with a function $\gamma$ whose directional derivative $\gamma'(x';\cdot)$ is continuous on $\setR^{d-1}$.
    \end{enumerate}
\end{definition}

As customary, we may write smooth instead of $\cC^\infty$, and Lipschitz instead of $\cC^{0,1}$. We will essentially work with boundary points that are $\cC^0$, $\cC^1$, Lipschitz, or CDD. Lipschit and CDD shall be abreviated to LCDD.

\begin{remark} It should be noted that a boundary point may not be $\cC^0$. For instance, consider $\Om:=\{(x,y) \in (0,+\infty)\times \setR: y < \sin(1/x)\}.$ Then the boundary $\partial \Omega$ is the union of $\{0\} \times (-\infty,1]$ and $\{y = \sin(1/x)\}$, which cannot be written as the graph of a continuous function locally around $0_2$, see Figure \ref{Im1}.

