\begin{remark}
The $\cC^0$ regularity of a boundary point is trivially preserved by local homeomorphisms. More precisely, for any $i \in \{1,2\}$, let $x_i$ be a boundary point of an open set $\Omega_i \subset \setR^d$ with a non-empty boundary. Assume that there exist open neighborhoods $V_1, V_2$ in $\setR^d$ of $x_1,x_2$ respectively, and a homeomorphism $\Phi : V_1 \cap \bar{\Omega}_1 \xrightarrow{\sim} V_2 \cap \bar{\Omega}_2$ such that $x_2 = \Phi(x_1)$. If $x_1$ is $\cC^0$, then the composition of the continuous map $\gamma_1$ such that \eqref{eq:boundary_points} holds around $x_1$ up to rigid motion with the homeomorphism $\Phi$ yields a continuous map $\gamma_2 \df \Phi \circ \gamma_1$ which ensures that $x_2$ is $\cC^0$.
\end{remark}


The next proposition shows that, from a topological point of view, there is no difference between a $\cC^0$ boundary point and a boundary point of the upper half space $\mathbb{H}^d$.


\begin{proposition}\label{Small ball near the border are homeomorphic}

    Let $\Omega$ be an open subset of $\ddim$ admitting a $\cC^0$ boundary point $x \in \partial \Omega$. Then there exists $\delta>0$ such that $\bar{\Omega} \cap  \setB^d_\delta(x)$ is homeomorphic to $\bar{\mathbb{H}}^d\cap \setB^d_\delta.$ 
\end{proposition}


\begin{proof}
    Let $\delta$ and $\gamma$ be such that \eqref{eq:boundary_points} holds up to a rigid motion. Then $\Phi(y) \df  x + (y',\gamma(y')+y_{d})$ defines a homeomorphism $
    \bar{\mathbb{H}}^d\cap \setB^d_\delta \to epi(\gamma) \cap \setB^d_\delta(x)$ with inverse $\Phi^{-1}(\xi) \df (\xi', \xi_d-\gamma(\xi'))-x$. 
%    $(y',\gamma(y')+c)\mapsto (y',c).$ Then the map $\bar{\Omega} \cap  \setB^d_\delta(x) \to \bar{\mathbb{H}^d}\cap \setB^d_\delta$ sending $(y',\gamma(y')+c)$ to $(y'-x,c)$ yields a desired homeomorphism.
\end{proof}

\subsection{Diffeomorphisms and inward sectors}\label{subsec:diffeo_inward}

For $k$ a positive integer, we shall use the following notion of $\cC^k$ diffeomorphism between possibly non-open subsets of $\setR^d$, see e.g.~\cite[Section 1.5]{Melrose} for details.

\begin{definition}\label{Diffeomorphism of sets in ddim}%\textbf{(Diffeomorphism of sets in $\ddim$)}
%\begin{enumerate}
%\item
We say that a map $\varphi:A\to B$ between subsets $A,B\subset \ddim$ is a $\cC^k$ diffeomorphism if there exist open subsets $\tilde{A},\tilde{B} \subset \ddim$ and a $\cC^k$ diffeomorphism $\tilde{\varphi}:\tilde{A}\to \tilde{B}$ such that  such that $A \subset \tilde{A}$, $B \subset \tilde{B}$ and $\tilde{\varphi}|_A=\varphi.$
%\item If $A$ and $B$ are open subsets, a diffeomorphism up to the   between them is a 
%\end{enumerate}
\end{definition}

We will mostly use this definition in the case where $A$ and $B$ are the closures of open subsets of $\setR^d$ with a non-empty boundary. In this regard, let us introduce a useful definition.

\begin{definition}
     Let $\Omega$ be an open subset of $\ddim$ with a non-empty boundary $\partial \Omega$. For any $x \in \bar{\Omega}$, we define the inward sector of $\Omega$ at $x$ as
     \[
     I_x\Omega \df \{c'(0) \in \setR^d : c \in \cC^1(I,\setR^d) \text{ s.t.~$I = (-\epsilon,\epsilon)$ for some $\epsilon>0$, $c(0)=a$ and $c([0,\epsilon)) \subset A$} \}.
     \]
\end{definition}

It is easily seen that the inward tangent sector of a point belonging to an open set is $\setR^d$, and that at a $\cC^1$ boundary point it is a half space. Moreover, the inward tangent sector at the origin of $\setR^d_k$ is $\setR^d_k$ itself. 



