\subsection{Boundary cones of open Euclidean subsets}\label{sec:boundary_cones}

In this section, we provide classical notions from convex analysis, see e.g.~\cite{RW} for more details. We recall that $C\subset \ddim$ is called a cone if it is invariant under multiplication by a positive number, i.e.~if $\lambda v \in C$ for any $v\in C$ and $\lambda > 0.$ 

%Let us recall now the definition of tangent or contingent cone, feasible direction cone, and open feasible direction cone for a subset of the Euclidean space.

\begin{definition}\label{def:open feasible direction cone}
Consider $A \subset \ddim$ and $a \in A$.
\begin{enumerate}
    \item The Bouligand tangent cone of $A$ at $a$ is defined as $$T^B_aA:=\{0_d\}\cup \left\{v\in \ddim \backslash \{0_d\}: \text{there exists $\{a_n\}\subset A$ such that $ a_n \to a$  and }  \frac{a_n-a}{\norm{a_n-a}} \stackrel{}{\to} \frac{v}{\norm{v}} \right\}.$$
    \item The Bouligand tangent sphere of $A$ at $a$ is defined as $S^B_aA:=T^B_aA\cap \mathbb{S}^{d-1}.$
    \item The feasible direction cone of $A$ at $a$ is defined as $$F_a(A):=\{v\in \ddim: \text{there exists $t_v>0$ such that $a+tv \in A$ for any $0 \le t < t_v$}\}.$$

    \item The open feasible direction cone of $A$ at $a$ is defined as
    $$
    \tilde{F}_a(A):= \{v\in \ddim:   \text{there exists $t_v>0$ such that $a+tv \in int(A)$ for any $0 < t < t_v$}\}.
    $$
    \end{enumerate}
\end{definition}

    The Bouligand tangent cone is also known as tangent cone or contingent cone in the literature. It is a closed set. One can easily check that our definition is equivalent to the one given in \cite[Def.~6.1]{RW}. Note also that $$\tilde{F}_a(A) 
 \subset F_a(A) \subset T^B_aA$$ 
 with possibly strict inclusion : for instance, $\tilde{F}_{0_d}(\bar{\mathbb{H}}^d) =  \mathbb{H}^d \varsubsetneq \bar{\mathbb{H}}^d
 = F_{0_d}(\bar{\mathbb{H}}^d)$.
 %Moreover, $0_d$ always lies in the first and second cones, while it lies in the third one if and only if $s\in int(S)$. It is also well-known that if $S$ is convex, then the tangent cone is the closure of the feasible direction cone.
 Moreover, in our setting, the following holds.

\begin{lemma}\label{prop:open feasible direction cone non-empty}%\textbf{(open feasible direction cone is non-empty in our case)}
    Let $x$ be a $\cC^0$ boundary point of an open set $\Omega \subset \setR^d$ with a non-empty boundary. Then $\tilde{F}_x({\bar{\Omega}})\ne \emptyset.$
\end{lemma}

\begin{proof}
    Let $\delta$ and $\gamma$ be such that \eqref{eq:boundary_points} holds up to a rigid motion. Since $x \in \partial \Omega$, we have $x_d = \gamma(x')$ so that $x_d + t > \gamma(x')$ for any $t \in (0,\delta)$. Thus $x+te_d \in \Omega \cap \setB_\delta(x) \subset \Omega$ for any such a $t$, so that $e_d\in \tilde{F}_x(\bar{\Omega})$.
\end{proof}


% \begin{remark}\label{remark:domains are epigraphs} \textbf{(considering cones at $\cC^0$ boundary points \textit{only}, and other assumptions)} We only consider the cones in Definition \ref{def:open feasible direction cone} at $\cC^0$ boundary points, cf. Definition \ref{C0 boundary pt} of an open subset $\Omega \subset \ddim.$ This means that there is a rigid motion or isometry $R$ of $\ddim, R(y):=Ay+b, A\in O(d), b\in \ddim,$ so that $U:=R(\Omega)$ can be written locally as an epigraph/superlevel set of a function $\gamma:\cl^{d-1}\to \cl.$
% Furthermore, we'll assume that $\gamma$ in Definition \ref{C0 boundary pt} is\textit{ directionally differentiable} at $x'\in \cl^{d-1}$ (i.e. the one-sided directional derivative $lim_{t\to 0+}\frac{\gamma(x'+tv')-\gamma(x')}{t}$ exists for each $v'\in \cl^{d-1}$)  where $(x',\gamma(x'))$ is a $\cC^0$ boundary point (cf Definition \ref{C0 boundary pt}) of the interior of the epigraph, given by $U:= \{(x',x_d): x_d > \gamma(x')\}.$ We'll also assume that the directional derivative function $D\gamma_{x'}$ defined by $D\gamma_{x'}: v' \mapsto lim_{t\to 0+}\frac{\gamma(x'+tv')-\gamma(x')}{t}$ is continuous (but not necessarily a linear function of $v'$). Denote by $S$ the epigraph itself, i.e. $S:= \{(x',x_d): x_d \ge \gamma(x')\}.$ Note that $S:=\bar{U}.$
% \end{remark}

% \begin{definition}\label{def:Lipschitz, continuously directionally differentiable boundary point}
 %     Under the setup of the abpve Remark \ref{remark:domains are epigraphs}, we call \textbf{$x$ be a Lipschitz, continuously directionally differentiable boundary point of $\Omega.$} 
 %\end{definition}

%\nd The next few results show that under the setup in Remark \ref{remark:domains are epigraphs}, \textit{many desirable properties hold}, while they don't necessarily hold for sets $S$ that's the closure of an arbitrary open domain $\Omega.$\\

For suitably regular boundary points, the Bouligand tangent cone satisfies the following additional properties.

\begin{proposition}\label{lem:tangent cones as epigraphs}%\textbf{(tangent cones as epigraphs)}
    Let $x=(x',x_d)$ be a LCDD boundary point of an open set $\Omega \subset \setR^d$ with a non-empty boundary, and let $\gamma$ be such that \eqref{eq:boundary_points} holds up to a rigid motion. %as in the setup of Remark \ref{remark:domains are epigraphs} and Definition \ref{def:Lipschitz, continuously directionally differentiable boundary point}.
    Then 
    \begin{equation}\label{eq:epi}
    T^B_x{\bar{\Omega}}=epi(\gamma'(x';\cdot)).
    \end{equation} 
    Moreover, \begin{equation}\label{eq:epi2}  T^B_x{\bar{\Omega}} = \overline{\tilde{F}_x(\bar{\Omega})}, \qquad int(T^B_x{\bar{\Omega}})=int({ \tilde{F}_x(\bar{\Omega})  }), \qquad 
\partial(T^B_x{\bar{\Omega}})=\partial({ \tilde{F}_x(\bar{\Omega})  }).\end{equation}
Lastly,
\begin{equation}\label{eq:epi3}
    \mathcal{L}^n(\partial(T^B_x{\bar{\Omega}})) = 0.
\end{equation}
%where $D\gamma_{x'}$ denotes the directional derivative function of $\gamma$ at $x'.$
%    \item $T^B_x{\bar{\Omega}}= .$
\end{proposition}

\begin{proof}
    With no loss of generality, we assume that $x =0_d$. Set $g(v')\df \gamma'(0_{d-1},v')$ for any $v' \in \setR^{d-1}$.

    Consider $v \in epi(g)$. Then $g(v')<v_d$. For any $\epsilon_n \downarrow 0$,
    \begin{align*}
    \gamma(\epsilon_n v') = g(\epsilon_n v') + o(\epsilon_n \|v'\|) = \epsilon_n g(v') + o(\epsilon_n \|v'\|) & < \epsilon_n v_d + o(\epsilon_n \|v'\|)\\
    & =\epsilon_n(v_d + o(\|v'\|)) ) =: \tau_n,
    \end{align*}
    so that each $x_n \df  (\epsilon_n v', \tau_n)$ belongs to $epi(g)$ and the sequence $(x_n)$ satisfies $x_n \to 0_d$ with $$\frac{x_n}{\|x_n\|} = \frac{(v',v_d+o(\|v'\|))}{\|(v',v_d+o(\|v'\|))\|} \to \frac{v}{\|v\|} \, \cdot $$
    Thus $v \in T_{0_d}^B\bar{\Omega}$. This shows the reverse inclusion in \eqref{eq:epi}.


    Consider $v\in T^B_{0_d}{\bar{\Omega}}$ and $\{x_n\} \subset \bar{\Omega}$ such that $x_n \to 0_d$ and $x_n/\|x_n\| \to v/\|v\|$. By \eqref{eq:boundary_points}, we can assume that $\{x_n\} \subset epi(\gamma)$. Set $\epsilon_n \df \|x_n\|/\|v\|$ for any $n$. Then
    \[
    \gamma(\epsilon_n v') = g(\epsilon_n v') + o(\epsilon_n)
    \]
    by definition of $g$ and
    \[
    |\gamma(x_n') - \gamma(\epsilon_n v')| \le L \|x_n' - \epsilon_n v'\| = L \|x_n\| \left|\frac{x_n'}{\|x_n\|} - \frac{v'}{\|v\|}\right| = o(\epsilon_n)
    \]
    for some $L \ge 1$, because $\gamma$ is Lipschitz. As a consequence,
    \[
    \delta_n \df |g(\epsilon_n v') - \gamma(x_n')| = o(\epsilon_n).
    \]
    Thus $\epsilon_n g(v') = g(\epsilon_n v') \le \gamma(x_n') + \delta_n \le (x_n)_d+ \delta_n$ because $x_n \in epi(\gamma)$. Then
    \[
    g(v') \le \frac{(x_n)_d+ \delta_n}{\epsilon_n} = \frac{\|v\|(x_n)_d}{\|x_n\|} + o(\|v\|)  \to v_d.
    \]
     This shows the direct inclusion in \eqref{eq:epi}. 

      From now on, for clarity of the exposition, we do not assume that $x=0_d$. Let us prove now the first equality in \eqref{eq:epi2}. Using successively \eqref{eq:epi} and \eqref{eq:epi=} (the latter being available because $x$ is c.d.d.), we can write:
\begin{align*}
T^B_x(\bar{\Omega}) &= epi(g) =\overline{\mathring{epi}(g)}.
\end{align*}
But
\begin{align*}
    \mathring{epi}(g) &  = \left\{v \in \setR^d : v_d > \lim_{t \to 0^+} \frac{\gamma(x' + t v') - \gamma(x')}{t} \right\}\\
& \subset \left\{ v \in \setR^d : \exists \, t_v> 0\,  \text{ s.t. } v_d > \frac{\gamma(x' + t v') - \gamma(x')}{t}  \, \forall \,  t \in (0,t_v) \right\}\\
&= \left\{v \in \setR^d : \exists \, t_v> 0\,  \text{ s.t. }  x_d + t v_d > \gamma(x' + t v') \ \forall\, 0 < t < t_v \right\}  \quad  (\text{using that } x_d=\gamma(x')) \\
&= \tilde{F}_x(\bar{\Omega}).
\end{align*}

\nd This shows $T^B_x(\bar{\Omega})  \subset \overline{\tilde{F}_x(\bar{\Omega})}.$ The other inclusion is obvious since the Bouligand tangent cone is closed and contains $\tilde{F}_x(\bar{\Omega})$.

The third equality in \eqref{eq:epi2} is an obvious consequence of the first and second ones. So we are left with proving the second one. Since $\tilde{F}_x(\bar{\Omega}) \subset T^B_x{\bar{\Omega}}$ we clearly have $ int(\tilde{F}_x(\bar{\Omega})) \subset int(T^B_x{\bar{\Omega}}),$ hence it is enough to show the converse inclusion $int(T^B_x{\bar{\Omega}}) \subset int(\tilde{F}_x(\bar{\Omega}))$. By \eqref{eq:epi} and the continuity of $g$, this amounts to showing that $\mathring{epi}(g) \subset int(\tilde{F}_x(\bar{\Omega}))$. Consider $v \in \mathring{epi}(g)$. Then there exists $\eta>0$ such that $g(w')<w_d$ for any $w \in \setB^d_\eta(v)$. By definition of $g$, for any such a $w$, there exists $t_w>0$ such that for any $t \in (0,t_w)$,
\[
\frac{\gamma(x'+tw')-\gamma(x')}{t} < w_d.
\]
Since $\gamma(x') = x_d$ the previous rewrites as
\[
\gamma(x'+tw') < x_d + tw_d.
\]
Thus $w \in \tilde{F}_x(\bar{\Omega})$. This means that $\setB^{d}_\eta(v) \subset \tilde{F}_x(\bar{\Omega})$, hence $v \in int(\tilde{F}_x(\bar{\Omega}))$ as claimed.

To conclude, let us explain why \eqref{eq:epi3} holds. By \eqref{eq:epi}, the set $\partial(T^B_x{\bar{\Omega}})$ coincides with the graph of $g$. Since the latter is continuous, its graph has $n$-dimensional Lebesgue measure equal to $0$.


\end{proof}



\begin{remark}\label{rem:feasible directions don't correspond in general under diffeomorphisms} 
It should be noted that feasible direction cones are not preserved by diffeomorphisms. Indeed, consider the closed subsets $A \df \{1 \le x \le \sqrt{y}\}$ and $B \df \{1\le x/2+1/2\le y\}$ of $(0,+\infty)^2$, and $\Phi : A \to B$  mapping $(x,y)$ to $(x,y^2)$. Then $\Phi$ is a diffeomorphism in the sense of Definition \ref{Diffeomorphism of sets in ddim} since it trivially extends to a diffeomorphism of $(0,+\infty)$ onto itself. Now $F_{(1,1)}A = B \backslash \{x = y\}$ is not closed while $F_{(1,1)}B = B$ is, so the linear isomorphism $\di_{(1,1)}\Phi$ cannot map $F_{(1,1)}A$ to $F_{(1,1)}B$.


