\subsection{Riemannian manifolds with kinks}\label{subsec:metric}

In this section, we develop a suitable notion of Riemannian metric for manifolds with kinks. There is no particular difference compare to the case of manifolds without/with boundary, but we provide details for completeness.


\subsubsection{Tangent bundle} Let us first define the tangent bundle on a smooth manifold with kinks. The definition is basically the same as for manifolds without/with boundary.

\begin{definition}\label{tangent bundle}
   Let $M$ be a smooth manifold with kinks. Then the tangent bundle of $M$ is the vector bundle
   $$TM:=\bigsqcup_{p\in M}T_pM = \{(p,v):v\in T_pM\}.$$
\end{definition}

  Let us check the following natural result.

  \begin{lemma}\label{prop:tangent bundle is a smooth manifold with kinks}
    Let $M$ be a $d$-dimensional smooth manifold with kinks. Then $TM$ is a $2d$-dimensional smooth manifold with kinks.
  \end{lemma}


  \begin{proof}
  Denote by $\pi$ the quotient map 
  $TM \to M$ mapping $(p,v)$ to $p$. We equip $TM$ with a topological/smooth structure by defining smooth charts as follows: for a local chart $(U, \phi)$ around $p\in M$, we define a corresponding $2d$-dimensional chart $(\mathcal{U}\df \pi^{-1}(U),\Phi)$ for $TM$ by setting
\[
\Phi(x,v) := (\phi(x), \di_x\phi(v))
\]
for all $(x,v) \in \mathcal{U}$. It is clear that for two such charts $(\mathcal{U},\Phi), (\mathcal{V}, \Psi)$ the transition map $\Psi \circ \Phi^{-1}$ is smooth on $\Phi(\mathcal{U}\cap \mathcal{V})$, because $\psi \circ \phi^{-1}$ is smooth on $\phi(\mathcal{U}\cap \mathcal{V})$, and $D\psi_x \circ (D\phi_x)^{-1}:\ddim \to \ddim$ is smooth as it is linear. We will show that with respect to these charts, the interior and border of $M$ match up with the interior and border of the tangent bundle $TM$; in this way we will have constructed a maximal smooth atlas with kinks on $TM$. This is obvious for the interior since the local charts are defined as in the case of manifolds without boundary. Let us then consider $p \in \partial M$ and a border chart $(U,\phi)$ centered at $p$. Then $\phi(p)=0_d$ is a $\mathcal{C}^0$ boundary point of $\operatorname{int}(\phi(U))$. Let us show that for any $v \in T_pM$,
\[
\Phi(p,v) = (\phi(p), \di_p \phi(v))
\]
is a $\mathcal{C}^0$ boundary point of $int(\Phi(\mathcal{U}))$, where $\mathcal{U}\df \pi^{-1}(U)$. Shrinking $U$ if necessary, we can identify $\mathcal{U}$ with $U \times \mathbb{R}^d$, so that $\Phi(\mathcal{U})$ is $\phi(U) \times \mathbb{R}^d$. Then $\partial \Phi(\mathcal{U}) = \partial \phi(U) \times \mathbb{R}^d$. Since $\phi(p)$ is a $\mathcal{C}^0$ boundary point of $\phi(U)$, we get that any $(\phi(p), v)$ is a $\mathcal{C}^0$ boundary point of $\phi(U) \times \mathbb{R}^d$.
\end{proof}

\begin{remark}
    We could also define the cotangent bundle on a smooth manifold with kinks as $T^*M \df \bigsqcup_{p\in M}T_p^*M = \{(p,\omega):\omega\in T_p^*M\}$, where each $T_p^*M$ is the dual of $T_pM$. We do not delve on this notion since we don't need it in the rest of the paper.
\end{remark}

\subsubsection{Covariant $k$-tensor bundle}

Let $k$ be a positive integer. Recall that a covariant $k$-tensor on a vector space $V$ is an element of the $k$-fold tensor product $V^* \otimes \dots \otimes V^*$ or, equivalently, a $k$-linear map $V \times V \times \dots \times V \to \cl.$ We denote by $T^k(V^*)$ the space of all covariant $k$-tensors on $V$. Then we can define the covariant $k$-tensor bundle on a smooth manifold with kinks as follows.

\begin{definition}
  Let $M$ be a smooth manifold with kinks. Then the space of covariant $k$-tensors on $M$ is defined as $$T^k(T^*M):=\bigsqcup_{p\in M}T^k(T_p^*M).$$
\end{definition}

Acting like in the previous subsection, one can easily show the following. We omit the proof for brevity.

\begin{lemma}\label{prop:covariant k-tensor bundle is a manifold with kinks}
     Let $M$ be a smooth manifold with kinks. Then $T^k(T^*M)$ is a smooth manifold with kinks too.
\end{lemma}

\begin{remark}
Likewise, we could define $(k,r)$-tensors on smooth manifolds with kinks, but we do not need them in the present paper so we skip them.
\end{remark}

\subsubsection{Riemannian metrics}

Let us define covariant tensor fields on manifold with kinks.

\begin{definition}
    Let $M$ be a smooth manifold with kinks.  A $k$-tensor field on $M$ is a section $g$ of the covariant $k$-tensor bundle ${T}^k(T^*M)$. Such a field is of $\cC^\ell$ regularity if  $g:M\to {T}^k(T^*M)$ is a $\cC^{\ell}$ map w.r.t. the smooth structures introduced in the previous section.
 \end{definition}

We are now in a position to define smooth Riemannian metrics on smooth manifolds with kinks.

 \begin{definition}\label{def:Riemannian metrics on manifolds with Lipschitz kinks}
    Let $M$ be a smooth manifold with kinks. A smooth Riemannian metric on $M$ is a smooth, symmetric, positive definite, section of the covariant $2$-tensor bundle ${T}^2(T^*M)M$.
\end{definition}

\subsubsection{Riemannian distance and volume measure}

The Riemannian distance defined via a length-minimizing problem extends with no change to the context of manifolds with kinks. We recall the definition for completeness and refer to \cite[p.337--341]{Lee}, for instance, for more details.

\begin{definition}
    Let $M$ be a smooth connected manifold with kinks admitting a $\cC^1$ Riemannian metric $g$. The associated Riemannian distance is defined by
    \[
    \di(x,y) \df \inf \left\{\int_0^1 g_{\gamma(t)}(\gamma'(t),\gamma'(t)) \di t : \gamma \in \cC^1([0,1],M) \text{ s.t.~}\gamma(0)=x \text{ and } \gamma(1)=y \right\},
    \]
    for any $x,y \in M$.
\end{definition}

In the same way, the definition of the Riemannian volume measure carry over to manifolds with kinks and behaves like in the case of manifolds without boundary.

\begin{definition}
    Let $M$ be a smooth manifold with kink admitting a $\cC^1$ Riemannian metric $g$. Then the Riemannian volume measure is defined by
    \[
    \mathrm{vol}_g(A) \df \sum_{\alpha} \int_{\phi_\alpha(U_\alpha)} \chi_\alpha \circ \phi_\alpha^{-1}\sqrt{\det g}
    \]
    for any Borel set $A \subset M$, where $\{(U_\alpha, \phi_\alpha\}$ is an atlas of $M$ and $\{\chi_\alpha\}$ a partition of unity subordinate to this atlas.
\end{definition}

\subsection{Extension of Riemannian manifolds with kinks}

For our purposes, we need to extend beyond the border any smooth Riemannian metric on a smooth manifold with kinks $M$. To this aim, we shall flow $M$ into its interior using a suitable semiflow. We adapt an argument for manifolds with corners that goes back to \cite{DouadyHerault} at least, see also \cite[Section 2.7]{Michor}.

\subsubsection{Vector fields and semiflows} Let us begin by defining vector fields and their associated semiflows on smooth manifolds with kinks.

\begin{definition}\label{inner and strictly inner vector fields} Let $M$ be a smooth manifold with kinks. A smooth vector field on $M$ is a smooth section of the tangent bundle $TM.$ Such a vector field $\xi$ is called (resp.~strictly) inward-pointing if $\xi_x\in I_xM$ (resp.~$\tilde{I}_xM$) for any $x\in M.$
\end{definition}

Let us ensure that any smooth manifold with kinks admits a stricly inward-pointing vector field.

\begin{lemma}\label{lem:strictly_inward}
    Let $M$ be a smooth manifold with kinks. Then $M$ admits a strictly inward-pointing vector field.
\end{lemma}

\begin{proof}
    Let $(U,\phi)$ be a border chart centered at some $x \in \partial M$. Up to composing $\phi$ with an isometry, we may assume that there exist $\delta>0$ and $\gamma \in \cC^0(\setR^{n-1})$ such that 
    \[
        \begin{cases}
        \phi(\bar{U}) \cap  \setB_\delta^d  = epi(\gamma)  \cap \setB_\delta^d, \nonumber\\
        int \phi(\bar{U}) \cap \setB_\delta^d  = \mathring{epi}(\gamma)  \cap \setB_\delta^d.
        \end{cases}
     \]
     Then we set $\xi_{(U,\phi)}(y) \df (\di_{y}\phi)^{-1}(e_d)$
     for any $y \in \bar{U} \cap \phi^{-1}(\setB_\delta^d)$. 
     We get from  Proposition \ref{prop:inward sectors correspond to inward sectors via charts} that $\xi_{(U,\phi)}(y) \in \tilde{I}_xM$. Consider now an atlas $\{(U_\alpha, \phi_\alpha\}$ of $M$ and a partition of unity $\{\chi_\alpha\}$ subordinate to this atlas. Define
     \[
     \xi \df \sum_{\substack{(U_\alpha,\phi_\alpha)\\ \text{border charts}}} \chi_\alpha \, \xi_{(U_\alpha,\phi_\alpha)} : M \to TM.
     \]
     Then $\xi$ is a global smooth vector field on $M$, and it is strictly inward-pointing by construction.
\end{proof}


Recall the definition of integral curve.

\begin{definition}
     Let $M$ be a smooth manifold with kinks, and $\xi$ a smooth vector field on it. An integral curve of $\xi$ is a smooth curve $\gamma : I \to M$ such that $\gamma'(t) = \xi(\gamma(t))$ for any $t \in I$.
\end{definition}

Then the following existence result holds.

\begin{theorem}\label{th:semiflow}
     Let $M$ be a smooth manifold with kinks, and $\xi$ an inward pointing vector field on it. Then there exists a smooth function $\delta : \partial M \to (0,+\infty)$ and a smooth embedding $\Phi : \mathcal{P}_\delta \to M$, with $\mathcal{P}_\delta = \{ (t,x) : x \in \partial M, t \in [0,\delta(x)) \} \subset \setR \times \partial M$, such that for any $x \in \partial M$ the map $[0,\delta(x)) \ni t \mapsto \Phi(t,x)$ is an integral curve of $\xi$ starting at $x$.
\end{theorem}

\begin{proof}
    The function $\delta$, the set $\mathcal{P}_\delta$ and the embedding $\Phi$ are first defined locally, and then patched together by means of a partition of unity. To define these objects locally around some point $x \in \partial M$, consider a border chart $(U,\phi)$ centered at $x$. By definition of border chart, there exists $\rho>0$ such that up to a rigid motion, $\phi(U) \cap \mathbb{B}_\rho^d$ writes as the local epigraph of some continuous function $h:\setR^{d-1}\to \setR$ such that $h(0)=0$. Since $\phi(U \cap \partial M)$ is mapped to the local graph of this function, and since $\di \phi(\xi)\equiv e_d$, we can apply the Cauchy--Lipschitz theorem in $\mathbb{R}^d$ to get existence of a smooth function $\delta : \phi(U \cap \partial M) \to \setR_+$ such that for any $y \in U \cap \partial M$ there exists an integral curve $\gamma_{\phi(y)} : [0,\delta(y))] \to \setR^d$ of $\di \phi(\xi)$ starting at $\phi(y)$, so that the map $[0,\delta(y)) \ni t \mapsto \Phi(t,y) \df \phi^{-1}(\gamma_{\phi(y)}(t))$ is an integral curve of $\xi$ starting at $y$.
\end{proof}







\subsubsection{Submanifolds with kinks}

Let us now provide a definition of submanifold adapted to the context with kinks, inspired by \cite[p.19]{Michor} who introduced submanifolds with corners.


\begin{definition}\label{submanifolds with kinks}
    Let $M$ be a $d$-dimensional manifolds with kinks, and $k$ a positive integer at most equal to $d$. We say that $N \subset M$ is a $k$-dimensional submanifold with kinks of $M$ if for every $p\in N,$ there is a chart $(U,\phi)$ of $M$ centered at $p$ so that $\phi(U \cap N) \subset \cl^k \times \{0\}^{d-k} \subset \ddim$ and $\phi(p)=0_d$ is an interior or a $\cC^0$ boundary point of $\phi(U\cap N).$ We call $(U,\phi)$ a slice chart centered at $p$ of $N$
\end{definition}

Our main result now is that any smooth manifold with kinks can be embedded into a manifold with boundary having same dimension. The proof actually embeds a smooth manifold with kinks into its interior.

\begin{theorem}
    \label{lem:Embedding a manifold with kinks into a manifold without boundary}
    Let $M$ be a $d$-dimensional manifolds with kinks. Then there exists a $d$-dimensional manifold with boundary $\tilde{M}$ of which $M \subset \tilde{M}$ is a smooth submanifold with kinks.
\end{theorem}

\begin{proof}

\nd Consider a strictly inward pointing vector field $\xi$ on $M$ as given by Lemma \ref{lem:strictly_inward}. Then the semiflow of $\xi$ given by Theorem \ref{th:semiflow} maps $\partial M$ into $int(M),$ and $int(M)$ into $int(M).$
\end{proof}



\subsubsection{Riemannian extension}


We will next show that under this assumption, any $\cC^2$ Riemannian metric can be extended from $M$ to the manifold $\tilde{M}$ without boundary given by Lemma \ref{lem:Embedding a manifold with kinks into a manifold without boundary}. 

\begin{proposition}\label{lem:extension of Riemannian metrics on a manifolds with kinks}
Let $M$ be a smooth submanifold with Lipschitz kinks of an open smooth manifold $\tilde{M}$. Assume that $M$ admits a $\cC^{2}$ Riemannian metric $g.$ Then there exist a neighborhood $O$ of $M$ in $\tilde{M},$ i.e. an open subset $O\subset \tilde{M}$ containing $M,$ and a $\cC^{2}$ Riemannian metric $\tilde{g}$ on $O$ so that $\tilde{g}$ restricts to $g$ on $M.$
\end{proposition}

\begin{proof}
    As usual in many extension theorems, the idea is to extend the Riemannian metric \textit{locally} to an open subset of $\tilde{M},$ and then use a \textit{smooth partition of unity}. We only need to extend the metric at border points of $M$, since  interior points of $M$ are interior points of $\tilde{M}$

    Let $(U, \phi)$ be a border chart around a Lipschitz kink $x \in M$, with $U \subset \tilde{U}$ open in $\tilde{M}$, and let $\tilde{\phi}$ be an extension of $\phi$ from $U$ to $\tilde{U}$. Let $g$ be a $\mathcal{C}^{2}$ Riemannian metric on $U$. The steps to extend $g$ from $U$ to $\tilde{U}$ are:

\begin{enumerate}
    \item Pull back $g$ to $\phi(U)$ by $\phi^{-1}$, i.e., consider $(\phi^{-1})^*g$ on $\phi(U)$. This is a $\mathcal{C}^2$ Riemannian metric on $\phi(U)$.

    \item Using Whitney's theorem, extend each coordinate of $(\phi^{-1})^*g$ to form a Riemannian metric $h$ on $V$, an open subset of $\mathbb{R}^d$ containing $\phi(x)=0$, such that $\phi^{-1}(V) \subset \tilde{U}$. Note that this extension may not be unique and depends on the choice of the border chart $(U,\phi)$.

    \item Pull back $h$ by $\tilde{\phi}$ to $\tilde{U}$, i.e., consider $\tilde{\phi}^* h$ on $\tilde{U} \supset U$. Since the extension in the previous step is not unique, this pullback may not be unique either. Nevertheless, regardless of the specific extension in Step 2 or the chart used, the tensor $g$ extends to a $\mathcal{C}^{2}$ Riemannian metric $\tilde{g}$ on $\tilde{U}$ such that its restriction to $U$ agrees with $g$, by the contravariant functoriality of pullbacks applied to the composition $\phi \circ \phi^{-1}=Id$.
\end{enumerate}

    \nd Note that the specific extension $\tilde{g}$ can depend on both the chart chosen and the method of extension in $\mathbb{R}^d$ used in Step 2.

    Next use a smooth partition of unity argument to obtain the extended Riemannian metric on $O:=\bigcup_{x \in M} \tilde{U}_x,$ which will be $\cC^2,$ as the product of $\cC^2$ and smooth ($\cC^{\infty}$) (partition of unity) functions are again $\cC^2.$
\end{proof}



\section{Asymptotic behavior of the intrinsic Gaussian Operator}


In this section, we prove Theorem \ref{th:1}.

\subsection{Localisation}

Recall that for a metric measure space $(M,\di,\mu)$, the intrinsic $d$-dimensional Gaussian operator at time $t>0$ is defined by
\[
L_t f(x) \df \frac{1}{t^{d/2+1}}\int_{M}  \exp\left(-\frac{\di^2(x,y)}{t}\right) (f(x)-f(y)) \di \mu(x)
\]
for any $f \in \cC(M)$ and $x \in M$. We are interested in the short-time behavior of this operator. In this regard, the next simple lemma implies that all the information about this behavior is contained in small balls. The proof is immediate so we skip it.


\begin{lemma}\label{lem:localisation}
   Let $(M,\di,\mu)$ be a metric measure space and $\eta \in (0,1/2)$. If $\mu(M)<+\infty$, then 
\[
\left| \frac{1}{t^{d/2+1}} \int_{M\backslash B_{t^\eta }(x)} \exp\left(-\frac{\di^2(x,y)}{t}\right) (f(x)-f(y)) d\mathrm{\mu}(y) \right| 
\leq [|f(x)|\mu(M) + \norm{f}_{1}] \, \frac{1}{t^{d/2 +1}} e^{-t^{2\eta -1}}
\]
for any $f \in \cC(M)\cap L^1(M,\mu)$ and $x \in X$. If $\mu(M) = +\infty$, then the previous holds whenever $f$ is integrable with bounded support, in which case $\mu(M)$ must be replaced by  $\mu(\mathrm{supp} f)$.
\end{lemma}

As a consequence, we get
\[
L_tf(x) = \frac{1}{t^{d/2+1}} \int_{B_{t^\eta }(x)} \exp\left(-\frac{\di^2(x,y)}{t}\right) (f(x)-f(y)) d\mathrm{\mu}(y) + O(t^{-d/2-1}e^{-t^{2 \eta -1}})
\]
and so Theorem \ref{th:1} follows from studying the asymptotic expansion of the first term in the previous right-hand side. Let us give a name to this quantity:
\begin{equation}\label{eq:localized}
\bar{L}_{t,\eta } f (x) \df \frac{1}{t^{d/2+1}} \int_{B_{t^\eta }(x)} \exp\left(-\frac{\di^2(x,y)}{t}\right) (f(x)-f(y)) d\mathrm{\mu}(y)
\end{equation}

\subsection{Change of coordinates} Let us put ourselves in the context of Theorem \ref{th:1}.

We consider a smooth Riemannian manifold with kinks $(M^d,g)$, a density $p \in \cC_{\ge 0}^2(M)$, a function $f \in \cC^3(M)$, a point $x \in M$ that is LCDD border (note that the case were $x$ is interior is covered by \eqref{eq:int}), and we choose $\eta  \in (0,1/2)$. We let $(\tilde{M},\tilde{g})$ be the open Riemannian manifold of which $(M,g)$ is a submanifold, see Lemma \ref{lem:Embedding a manifold with kinks into a manifold without boundary} and Proposition \ref{lem:extension of Riemannian metrics on a manifolds with kinks}. We denote by $\tilde{B}_r(x)$ the $\tilde{g}$-ball of radius $r$ centered at $x$, by $\tilde{\exp}_x$ the $\tilde{g}$-exponential map at $x$, and by $\tilde{\gamma}_{x,v}$ the unique maximal $\tilde{g}$-geodesic with initial point $x$ and initial velocity $v \in T_x \tilde{M}$.  Since $x$ is an interior point for $\tilde{M}$, there exists $R>0$ such that $\tilde{\exp}_x$ is a diffeomorphism from $\mathbb{B}_R^d \subset T_x \tilde{M}$ onto $\tilde{B}_R(x)$. Moreover, since $(\tilde{M},\tilde{g})$ extends $(M,g)$, the set of $\cC^1$ curves joining $x$ to $y \in \tilde{B}_R(x)$ and lying entirely in $M$ is a subset of those curves lying in $\tilde{M}$, so that
\begin{equation}\label{eq:ineq_distance}
\tilde{\di}(x,y) \le \di(x,y).
\end{equation}
As a consequence, for any $r \in (0,R)$,
\[
B_r(x) \subset \tilde{B}_r(x).
\]
This implies, in particular, that $(B_R(x), \tilde{\exp}_x^{-1}|_{B_r(x)})$ is a border chart centered at $x$ of $M$.

As usual, we identify the Euclidean space $(T_x \tilde{M},g(x))$ with $(\setR^d,\cdot)$ by choosing a $g(x)$-orthonormal basis $(w_1,\ldots,w_d)$ of $T_x \tilde{M}$ and mapping each $w_i$ to the $i$-th element of the canonical basis of $\setR^d$. We will freely use this identification in the sequel. Let us also point out that $(T_xM,g(x))$ and $(T_x\tilde{M},\tilde{g}(x))$ coincide as Euclidean spaces. We define $$\Omega \df \tilde{\exp}_x^{-1}(B_R(x)).$$ This is an open subset of $T_x\tilde{M} \simeq \setR^d$ having $0_d$ as a $\cC^0$ boundary point.


\begin{proposition}\label{prop:localized}
Set $\tilde{f}\df f \circ \tilde{\exp}_x$ and $q \df (p \circ \tilde{\exp}_x) \sqrt{\det g}$. Then
    \[
    \bar{L}_{t,\eta} f (x)  = \frac{1}{t} \int_{\mathbb{B}^d_{t^{\eta}}\cap \tilde{F}_{0_d}\Omega} e^{-\frac{\|\xi\|^2}{t}} (\tilde{f}(0_d) - \tilde{f}(\xi))q(\xi)\di \xi + o\left( \frac{1}{\sqrt{t}}\right) \qquad \text{as $t\to 0$.}
    \]
\end{proposition}

\begin{proof}
  Set
 \begin{align*}
    W & \df \{v \in T_x \tilde{M} \simeq \setR^d : \text{ there exists } t_v >0 \text{ s.t.~}\tilde{\gamma}_{x,v}(t) \in M \text{ for all $t \in (0,t_v)$}\}.
\end{align*}
Then
\[
\bar{L}_{t,\eta} f (x) = I(t) + II(t)
\]
where
 \begin{align*}
 I(t) & \df \frac{1}{t^{d/2+1}} \int_{B_{t^\eta}(x)\cap \tilde{\exp}_x(W\cap \mathbb{B}_R^d)} \exp\left(-\frac{\di^2(x,y)}{t}\right) (f(x)-f(y)) \, d\mathrm{\mu}(y),\\
 II(t) & \df \frac{1}{t^{d/2+1}} \int_{B_{t^\eta}(x)\backslash \tilde{\exp}_x(W\cap \mathbb{B}_R^d)} \exp\left(-\frac{\di^2(x,y)}{t}\right) (f(x)-f(y)) d\mathrm{\mu}(y).
 \end{align*}



\textbf{Step 1.}  We show that for any small enough $t>0$,
\begin{align}\label{eq:step1!}
I(t) = \frac{1}{t} \int_{\mathbb{B}^d_{t^{\eta}}\cap \tilde{F}_{0_d}\Omega} e^{-\frac{\|\xi\|^2}{t}} (\tilde{f}(0_d) - \tilde{f}(\xi))q(\xi)\di \xi.
\end{align}


To this purpose, notice that $W$ is a cone : indeed, if $v \in W$ and $\lambda>0$, then $\tilde{\gamma}_{x,\lambda v}(t) = \tilde{\gamma}_{x,v}(\lambda t)$ for any $t \in (0,t_v/\lambda)$, so that $\lambda v \in W$ with $t_{\lambda v}=t_v/\lambda$.

For any $v \in W$, set $s_v \df \sup \{s >0 : \tilde{\gamma}_{x,v}(s') \in M \text{ for any $s' \in [0,s]$}\} \in (0,+\infty]$. Let us show that
\begin{equation}\label{eq:technical}
B_{t^{\eta}}(x) \cap \tilde{\exp}_x(W) = B_{t^{\eta}}(x) \cap  \{\tilde{\exp}_x(sv) : v \in W \text{ with } \|v\|_{g_x} = 1 \text{ and } s \in (0,s_v) \}.
\end{equation}
Since $W$ is a cone,
\[
W = \bigsqcup_{\substack{v \in W\\ \|v\|_{g_x} = 1}} \setR_+ v,
\]
thus
\[
B_{t^{\eta}}(x) \cap \tilde{\exp}_x(W) = \bigsqcup_{\substack{v \in W\\ \|v\|_{g_x} = 1}} B_{t^{\eta}}(x) \cap \tilde{\exp}_x(\setR_+ v).
\]
Now for each $v \in W$ such that $\|v\|_{g_x} = 1$,
\[
 B_{t^{\eta}}(x) \cap \tilde{\exp}_x(\setR_+ v) = \{\tilde{\exp}_x(sv) : s \in (0,s_v) \} \cap B_{t^{\eta}}(x).
 \]
Then 
\[
B_{t^{\eta}}(x) \cap \tilde{\exp}_x(W) = \bigsqcup_{\substack{v \in W\\ \|v\|_{g_x} = 1}} B_{t^{\eta}}(x) \cap \tilde{\exp}_x(\setR_+ v) = \bigsqcup_{\substack{v \in W\\ \|v\|_{g_x} = 1}} \{\tilde{\exp}_x(sv) : s \in (0,s_v) \} \cap B_{t^{\eta}}(x)
\]
hence we get \eqref{eq:technical}.

Let us now prove that for any $y \in B_{t^{\eta}}(x) \cap \tilde{\exp}_x(W)$,
\begin{equation}\label{eq:equal_distance}
    \tilde{\di}(x,y) = \di(x,y).
\end{equation}
Thanks to \eqref{eq:technical}, we know that there exist $v \in W$ with $\|v\|_{g_x}=1$ and $s \in [0,s_v)$ such that $y = \tilde{\exp}_x(sv)$ and $\tilde{\exp}_x(s'v)\in M$ for any $s' \in [0,s]$. Since $g$ and $\tilde{g}$ coincide on $M$, the $g$-geodesic joining $x$ and $y$ coincides with $s' \mapsto \tilde{\exp}_x(s'v)$. This yields \eqref{eq:equal_distance}.
Lastly, we point out that
\begin{equation}\label{eq:step1_1}
    W = \tilde{F}_{0_d} \Omega
\end{equation}
and
\begin{equation}\label{eq:step1_1bis}
   \tilde{\exp}_x^{-1}(B_{t^\eta}(x)) \cap W = \mathbb{B}^d_{t^\eta} \cap W.
\end{equation}
These are directly resulting from the fact that $\tilde{\gamma}_{x,v}(s) = \tilde{\exp}_x (sv)$ and $t\mapsto tv$ is the Euclidean geodesic in $\setR^d$ starting at $0_d$ with initial velocity $v$.

We are now in a position to obtain \eqref{eq:step1!}. First, we use \eqref{eq:equal_distance} and the change of variable $y = \exp_x(\xi)$ to obtain
 \begin{align*}
     I(t) &  = \frac{1}{t^{d/2+1}} \int_{B_{t^\eta}(x)\cap \tilde{\exp}_x(W\cap \mathbb{B}_R^d)} \exp\left(-\frac{\tilde{\di}^2(x,y)}{t}\right) (f(x)-f(y)) \, p(y)d\mathrm{vol}_g(y)\\
     & = \frac{1}{t^{d/2+1}} \int_{\tilde{\exp}_x^{-1}(B_{t^\eta}(x))\cap W} \exp\left(-\frac{\|\xi\|^2}{t}\right) (\tilde{f}(0_d)-\tilde{f}(\xi)) q(\xi)\, d \xi.
 \end{align*}
Then we apply \eqref{eq:step1_1} and \eqref{eq:step1_1bis} to get \eqref{eq:step1} as sought.



 \textbf{Step 2.}
 We show that
 \begin{align}\label{eq:step4}
 II(t) = o\left(\frac{1}{\sqrt{t}}\right)  \qquad \text{as $t \to 0$.}
 \end{align}

To this purpose, let us first establish that as $t \downarrow 0$,
\begin{equation}\label{eq:step2_2}
    1_{\frac{\tilde{\exp_x}^{-1}(B_{t^\eta}(x)) }{\sqrt{t}}\backslash W} \to 0 \qquad \text{a.e.}
\end{equation}
For any $t >0$ such that $t^{\eta} \le R$,
\begin{align*}
    1_{\frac{\tilde{\exp_x}^{-1}(B_{t^\eta}(x)) \backslash W}{\sqrt{t}}} & \le 1_{\frac{\tilde{\exp_x}^{-1}(B_{R}(x)) \backslash W}{\sqrt{t}}} = 1_{\frac{\Omega \backslash W}{\sqrt{t}}}.
\end{align*}
Since $W$ is a cone, the latter characteristic function is equal to
$$
1_{\frac{\Omega}{\sqrt{t}} \backslash W} = 1_{\frac{\Omega}{\sqrt{t}}} - 1_{W} = 1_{\frac{\Omega}{\sqrt{t}}} - 1_{\tilde{F}_{0_d}\Omega}  \stackrel{t \downarrow 0}{\longrightarrow} 1_{\tilde{F}_{0_d}(\Omega)} - 1_{\tilde{F}_{0_d}(\Omega)} = 0 \qquad \text{a.e.}
$$
Here we use \eqref{eq:step1_1} to get the second equality and Proposition \ref{prop:gen} for the convergence a.e. as $t\downarrow 0$.

Let us now estimate
\begin{align*}
     |II(t)| &  \le  \frac{1}{t^{d/2+1}} \int_{B_{t^\eta}(x)\backslash \tilde{\exp}_x(W\cap \mathbb{B}_R^d)} \exp\left(-\frac{\di^2(x,y)}{t}\right) |f(x)-f(y)| p(y)d\mathrm{vol}_g(y) \\
     & \le \frac{1}{t^{d/2+1}}\int_{B_{t^\eta}(x)\backslash \tilde{\exp}_x(W\cap \mathbb{B}_R^d)} \exp\left(-\frac{\tilde{\di}^2(x,y)}{t}\right) |f(x)-f(y)| p(y)d\mathrm{vol}_g(y)\\
     & = \frac{1}{t^{d/2+1}} \int_{\tilde{\exp}_x^{-1}(B_{t^\eta}(x))\backslash W} \exp\left(-\frac{\|\xi\|^2}{t}\right) |\tilde{f}(0_d)-\tilde{f}(\xi)| q(\xi)d\xi \\
     & = \frac{1}{t} \int_{\frac{\tilde{\exp}_x^{-1}(B_{t^\eta}(x))}{\sqrt{t}}\backslash W} \exp\left(-\|\zeta\|^2 \right) |\tilde{f}(0_d)-\tilde{f}(\sqrt{t}\zeta)| q(\sqrt{t}\zeta)d\zeta
 \end{align*}
where we use \eqref{eq:ineq_distance} to get the second inequality, the change of variable $y = \tilde{\exp}_x(\xi)$ to get the penultimate line, and $\zeta = \xi/\sqrt{t}$ to get the last one. Now we use the Taylor theorem with Laplace remainder : for any $\zeta \in \frac{\tilde{\exp}_x^{-1}(B_{t^\eta}(x))}{\sqrt{t}}\backslash W$ there exist $s_1,s_2 \in (0,\sqrt{t})$ such that
\[
\tilde{f}(0_d)-\tilde{f}(\sqrt{t}\zeta) = - \di_{0_d} \tilde{f} (\sqrt{t}\zeta)  -  \frac{1}{2}  \di^{(2)}_{\sqrt{s_1}\zeta} \tilde{f}  ((\sqrt{t}\zeta)^{(2)})  ,
\]
\[
q(\sqrt{t}\zeta) = q(0_d) + \di_{\sqrt{s_2}\zeta} q (\sqrt{t}\zeta),
\]
so that 
\begin{align*}
|\tilde{f}(0_d)-\tilde{f}(\sqrt{t}\zeta)|q(\sqrt{t}\zeta) & \le \sqrt{t} \, q(0_d) |\di_{0_d} \tilde{f} (\zeta)|  +  \frac{t \, q(0_d)}{2}  |\di^{(2)}_{\sqrt{s_1}\zeta} \tilde{f}  (\zeta^{(2)})| \\
& + t \di_{\sqrt{s_2}\zeta} q (\zeta) |\di_{0_d} \tilde{f} (\zeta)|  +  \frac{t^{3/2}}{2}  \di_{\sqrt{s_2}\zeta} q (\zeta) |\di^{(2)}_{\sqrt{s_1}\zeta} \tilde{f}  (\zeta^{(2)})| \\
& \le \sqrt{t} \, q(0_d) \| \di_{0_d} \tilde{f}\|_{op} \|\zeta\|  +  \frac{t \, q(0_d) \|\zeta\|^{2} }{2}  \sup_{z \in \tilde{\exp}_x^{-1}(B_{t^\eta}(x))\backslash W }\|\di^{(2)}_{z} \tilde{f}\|_{op}  \\
& + t \|\zeta\|^{2} \|\di_{0_d} \tilde{f} \|_{op} \sup_{z \in \tilde{\exp}_x^{-1}(B_{t^\eta}(x))\backslash W } \| \di_{z} q \|_{op}\\
& +  \frac{t^{3/2}\| \zeta\|^{3} }{2} \sup_{z \in \tilde{\exp}_x^{-1}(B_{t^\eta}(x))\backslash W } \| \di_{z} q\|_{op}  \|\di^{(2)}_{z} \tilde{f}\|_{op}\\
& \le \sqrt{t} \, q(0_d) \| \di_{0_d} \tilde{f}\|_{op} \|\zeta\|  + t\|\zeta\|^2 C_{x,f,p}(t)
\end{align*}
where we have set
\begin{align*}
C_{x,f,p}(t) & = \frac{q(0_d) }{2}  \sup_{z \in \tilde{\exp}_x^{-1}(B_{t^\eta}(x))\backslash W }\|\di^{(2)}_{z} \tilde{f}\|_{op}  + \|\di_{0_d} \tilde{f} \|_{op} \sup_{z \in \tilde{\exp}_x^{-1}(B_{t^\eta}(x))\backslash W } \| \di_{z} q \|_{op}\\
& + \frac{t^{1+\eta} }{2} \sup_{z \in \tilde{\exp}_x^{-1}(B_{t^\eta}(x))\backslash W } \| \di_{z} q\|_{op}  \|\di^{(2)}_{z} \tilde{f}\|_{op}.
\end{align*}
Note that
\[
C_{x,f,p}(t) \to \frac{q(0_d) }{2}  \|\di^{(2)}_{0_d} \tilde{f}\|_{op}  + \|\di_{0_d} \tilde{f} \|_{op} \| \di_{0_d} q \|_{op}.
\]
Then we get 
\begin{align*}
     |II(t)| &  \le  \frac{q(0_d) \| \di_{0_d} \tilde{f}\|_{op} }{\sqrt{t}} \int_{\frac{\tilde{\exp}_x^{-1}(B_{t^\eta}(x))}{\sqrt{t}}\backslash W} \exp\left(-\|\zeta\|^2 \right) \|\zeta\| d\zeta \\
     & + C_{x,f,p}(t) \int_{\frac{\tilde{\exp}_x^{-1}(B_{t^\eta}(x))}{\sqrt{t}}\backslash W} \exp\left(-\|\zeta\|^2 \right) \|\zeta\|^2 d\zeta.
\end{align*}
It follows from \eqref{eq:step2_2} that the two previous integrals both converge to $0$ as $t \to 0$. This yields \eqref{eq:step4} as desired. 
\end{proof}


\subsection{Euclidean calculation}


The previous change of coordinates allows us to make a calculation in the Euclidean space $\setR^d$. This is what we do in this subsection. We provide a general result which might allow for considering union of intersecting manifolds with kinks in a future work.

Let us recall the notations. For any $y \in \setR^d$ we set $y^{(k)} \df y\otimes \ldots \otimes y \in (\setR^d)^{\otimes^k}$. If $f \in \cC^{\infty}(U)$ for some open subset $U \subset \setR^d$, we let
$\di^{(k)}_xf$ denote the differential of order $k$ of $f$ at $x$, which we see here as a $k$-linear symmetric map from $(\setR^d)^{\otimes^k}$ to $\setR$, and we set
\[
\|\di^{(k)}_xf\|_{op} \df \sup_{y \in \setR^d\backslash \{0_d\}} \frac{\di^{(k)}_xf(y^{(k)})}{|y|^{k}} \, \cdot
\]
We shall also write $\di_x^{(0)}f(y^{(0)})$ for $f(x)$, in which case $\|\di^{(0)}_xf\|_{op}= f(x)$. We consider a cone $\mathcal{C} \subset \setR^d$ and a scalar product $g$ on $\setR^d$, and we set $S^g \mathcal{C} \df \mathcal{C} \cap \{\xi \in \setR^d : g(\xi,\xi)=1\}.$

\begin{proposition}\label{prop:key}
Let $p \in \cC^{2}_{\ge 0}(\setB^d)$ and $f \in \cC^{3}(\setB^d)$ be such that
\begin{equation}\label{eq:p_f}
C_{p,f} \df \left( \max_{0 \le j \le 2 }  \sup_{\xi \in \setB^d}\|\di^{(j)}_{\xi}p \|_{op} + \max_{1 \le i \le 3 }  \sup_{\xi \in \setB^d}\|\di^{(i)}_{\xi}f \|_{op} \right)  < +\infty.
\end{equation}
For $\eta \in (0,1/2)$ and $t \in (0,1)$, define
\[
L_t^{\mathcal{C},\eta}f(0_d)= \frac{1}{t} \int_{ \setB^d_{t^\eta}\cap \mathcal{C}} e^{-\frac{\|y\|^2}{t}} (f(0_d)-f(y))p(y) \di y.
\]
Then as $t \downarrow 0$,
\begin{align}\label{eq:eucl_result}
    L_t^{\mathcal{C},\eta}f(0_d) & = - \frac{c_d}{\sqrt{t}} p(0_d) \partial_{v_{\mathcal{C}}} f(0_d)  - c_{d+1} \bigg( p(0_d) A_\cC f(0_d) +  [p,f]_\cC(0_d)\bigg)  + O(\sqrt{t}),
\end{align}
where 
\[
\partial_{v_{\mathcal{C}}}f(0_d) \df d_{0_d} f(v_\cC) \quad \text{with} \quad v_{\mathcal{C}} \df \int_{S^g \cC} \theta \di \sigma (\theta), 
\]
and
\[
    A_{\cC}f(0_d) \df \int_{S^g\cC} \di_{0_d}^{(2)}f \left( \theta^{(2)} \right) \di \sigma(\theta), \qquad 
    [p,f]_\cC(x) \df \frac{1}{2} \int_{S^g\cC} \di_{0_d}f(\theta)\di_{0_d}p(\theta) \di \sigma(\theta).
\]
\end{proposition}


To prove this proposition, we need a simple preliminary lemma. We provide a proof for completeness.

\begin{lemma}\label{lem:O}
Let $g \in \cC(\setR^d)$ be such that there exists $m \in \mathbb{N}$ for which
\[
C_g \df \sup_{z \in \setR^d \backslash \{0\}} \frac{|g(z)|}{|z|^m} < +\infty.
\]
Then for any cone $\mathcal{C}$ in $\setR^d$ and $a\in(-1/2,0)$,
\[
\left| \int_{\cC \backslash \setB^d_{t^a}}  e^{-|z|^2}   g(z) \, \di z \right| = O ( t^{\frac{1}{2}}) \qquad \text{as $t \downarrow 0$.}
\]
\end{lemma}

\begin{proof}
We have
\begin{align*}
\left| \int_{\cC \backslash \setB^d_{t^a}}  e^{-|z|^2}   g(z) \, \di z \right| & \le  \int_{\cC \backslash \setB^d_{t^a}}  e^{-|z|^2}   | g(z)|  \, \di z \le C_g \int_{\cC \backslash \setB^d_{t^a}}   e^{-|z|^2} |z|^m   \, \di z.
\end{align*}
Using polar coordinates first, then the change of variable $\tau=r^2$, we get
\begin{align*}
\int_{\cC \backslash \setB^d_{t^a}}   e^{-|z|^2}  |z|^m \, \di z & = \haus^{d-1}(\mathcal{S}^g\cC) \int_{t^{a}}^{+\infty} e^{-r^2} r^{m+d-1} \, \di r   \\
& =  \frac{\haus^{d-1}(\mathcal{S}^g\cC)}{2} \int_{t^{2a}}^{+\infty} e^{-\tau} \tau^{\frac{m+d}{2}-1} \, \di \tau \\
& = \frac{\haus^{d-1}(\mathcal{S}^g\cC)}{2} \, \Gamma \left( \frac{m+d}{2} , t^{2a} \right).
\end{align*}
By asymptotic property of the incomplete Gamma function (see e.g.~\cite{Pinelis})
\[
\Gamma \left( \frac{m+d}{2} , t^{2a} \right) \underset{t \downarrow 0}{\sim}  t^{a(m+d-2)} e^{-t^{2a}}.
\]
Therefore, for small enough $t>0$,
\[
\left| \int_{\cC \backslash \setB^d_{t^a}}  e^{-|z|^2}   F(z) \, \di z \right| \le C_g \, \haus^{d-1}(\mathcal{S}^g\cC) \,  t^{a(m+d-2)} e^{-t^{2a}}.
\]
The result follows from the fact that $t^{a(m+d-2)} e^{-t^{2a}} = O(t^{\frac{1}{2}})$ as $t \downarrow 0$.
\end{proof}

\begin{remark}
Our proof yields the more precise estimate:
\[
\left| \int_{\cC \backslash \setB^d_{t^a}}  e^{-|z|^2}   g(z) \, \di z \right| = O \left( t^{a(m+d-2)} e^{-t^{2a}}\right) \qquad \text{as $t \downarrow 0$.}
\]
\end{remark}

We are now in a position to prove Proposition \ref{prop:key}.

\begin{proof}
\textbf{Step 1}. Let us prove that, as $t \downarrow 0$,
\begin{align}\label{eq:step1}
    L_t^{\mathcal{C},\gamma}f(0_d) & = - t^{-\frac{1}{2}} p(0_d) \di_{0_d}f\left(  \int_\cC e^{-|z|^2} z \di z\right) - \int_\cC e^{-|z|^2} \di_{0_d}f(z)\di_{0_d}p(z) \di z \nonumber \\
    & \phantom{=} -  \frac{p(0_d)}{2}\di_{0_d}^{(2)} f \left(\int_\cC e^{-|z|^2} z^{(2)} \di z \right) + O(t^{\frac{1}{2}}).
\end{align}
The Taylor theorem with Laplace remainder implies that for any $y \in \setB^d$ there exist $\xi_y, \zeta_y \in \setB^d$ such that
\[
f(0_d)-f(y) = - \di_{0_d} f (y)  -  \frac{1}{2}  \di^{(2)}_{0_d} f  (y^{(2)})  - \frac{1}{6}  \di^{(3)}_{\xi_y} f (y^{(3)}),
\]
\[
p(y) = p(0_d) + \di_{0_d} p (y) +  \frac{1}{2}  \di ^{(2)}_{\zeta_y} p (y^{(2)}).
\]
Then
\begin{align}\label{eq:key1}
L_t^{\cC,\gamma} f(0_d) & = \sum_{i=1}^{3}\sum_{j=0}^{2} I_{t}(i,j) 
 \end{align}
 where for any $i \in \{1,2,3\}$ and $j \in \{0,1,2\}$,
 \[
 I_{t}(i,j)   \df - \frac{1}{i!j!t^{\frac{d}{2}+1}} \int_{\mathcal{C} \cap \setB^d_{t^\gamma}} e^{-\frac{|y|^2}{t}} g_{i,j}(y) \di y.
 \]
Here we have defined, for any $y \in \setB^d$,
\[
\begin{array}{ll}
  g_{i,j}(y) \df \di_{0_d}^{(i)} f (y^{(i)})   \di_{0_d}^{(j)} p(y^{(j)})   &  \text{for $(i,j)  \in \{1,2\} \times \{0,1\}$}, \\
g_{3,j}(y) \df \di_{\xi_y}^{(3)} f (y^{(3)})   \di_{0_d}^{(j)} p(y^{(j)})  & \text{for $j\in \{1,2\}$},\\ 
g_{i,3}(y) \df \di_{0_d}^{(i)} f (y^{(i)})   \di_{\zeta_y}^{(3)} p(y^{(2)}) & \text{for $i \in \{1,2\}$},\\
g_{3,2}(y) \df \di_{\xi_y}^{(3)} f (y^{(3)})   \di_{\zeta_y}^{(2)} p(y^{(2)}). & 
\end{array}
\]
On one hand, if $i=3$ or $j=2$, we know from \eqref{eq:p_f} that for any $y \in \mathcal{C}$,
\[
|g_{i,j}(y)| \le C_{p,f}|y|^{i+j}
\]
hence 
\begin{align*}
    |I_{t}(i,j)|  & \le\frac{1}{t^{\frac{d}{2}+1}} \int_{\mathcal{C} \cap \setB^d_{t^\gamma}} e^{-\frac{|y|^2}{t}} |g_{i,j}(y)| \di y \le \frac{C_{p,f}}{t^{\frac{d}{2}+1}} \int_{\mathcal{C} \cap \setB^d_{t^\gamma}} e^{-\frac{|y|^2}{t}} |y|^{i+j} \di y \\
    & = C_{p,f} t^{\frac{i+j}{2}-1} \int_{\mathcal{C} \cap \setB^d_{t^{\gamma-1/2}}} e^{-|z|^2} |z|^{i+j} \di z \le C_{p,f} C_{\mathcal{C},i+j} t^{\frac{i+j}{2}-1}
\end{align*}
where we have used the change of variable $z= y/\sqrt{t}$ and we have defined 
\[
 C_{\mathcal{C},k} \df \int_{\mathcal{C}} e^{-|z|^2} |z|^{k} \di z
\]
for any integer $k$. Since $i=3$ or $j=2$ implies $i+j\ge 3$, we have $(i+j)/2-1 \ge 3/2-1 = 1/2$, so that we eventually get
\begin{align}\label{eq:key2}
\sum_{(i,j) \notin \{1,2\} \times  \{0,1\}} I_{t}(i,j) = O(t^{1/2}).
\end{align}

On the other hand, if $(i,j) \in \{1,2\} \times  \{0,1\}$, then for any $z \in \setR^d$ and $t>0$,
\[
g_{i,j}(\sqrt{t}z) = t^{\frac{i+j}{2}} g_{i,j}(z) \quad \text{and} \quad  g_{i,j}(z) \le C_{p,f} |z|^{i+j}.
\]
Then the change of variable $z= y/\sqrt{t}$ yields that
\begin{align*}
    I_{t}(i,j)  & = \frac{1}{t} \int_{\mathcal{C} \cap \setB^d_{t^{\gamma-1/2}}} e^{-|z|^2} g_{i,j}(\sqrt{t}z) \di z = t^{\frac{i+j}{2}-1} \int_{\mathcal{C} \cap \setB^d_{t^{\gamma-1/2}}} e^{-|z|^2} g_{i,j}(z) \di z.
\end{align*}
By Lebesgue dominated convergence theorem,
\[
\int_{\mathcal{C} \cap \setB^d_{t^{\gamma-1/2}}} e^{-|z|^2} g_{i,j}(z) \di z \to \int_{\mathcal{C}} e^{-|z|^2} g_{i,j}(z) \di z.
\]
Moreover, by Lemma \ref{lem:O},
\begin{align*}
\left| \int_{\mathcal{C} \backslash  \setB^d_{t^{\gamma-1/2}}} e^{-|z|^2} g_{i,j}(z) \di z \right| = O( t^{\frac{1}{2}} ).
\end{align*}
Then 
\[
I_{t}(i,j) = t^{\frac{i+j}{2}-1}  \int_{\mathcal{C} } e^{-|z|^2} g_{i,j}(z) \di z + O( t^{\frac{1}{2}} ).
\]
As a consequence,
\begin{align}\label{eq:key3}
I_{t}(1,0) & = t^{-\frac{1}{2}}  \int_{\mathcal{C} } e^{-|z|^2} g_{1,0}(z) \di z  + O( t^{\frac{1}{2}} ),
\end{align}
and
\begin{align}\label{eq:key4}
I_{t}(1,1) + I_{t}(2,0) & =  \int_{\mathcal{C} } e^{-|z|^2} (g_{1,1}(z)+g_{2,0}(z)) \di z  + O( t^{\frac{1}{2}}). 
\end{align}
Now
\begin{align*}
\int_{\mathcal{C} } e^{-|z|^2} g_{1,0}(z) \di z & = p(0_d)  \int_\cC e^{-|z|^2} \di_{0_d}f(z) \di z \\
\int_{\mathcal{C} } e^{-|z|^2} g_{1,1}(z) \di z & =  \int_\cC e^{-|z|^2} \di_{0_d}f(z)\di_{0_d}p(z) \di z \\
\int_{\mathcal{C} } e^{-|z|^2} g_{2,0}(z) \di z & =  p(0_d)\int_\cC e^{-|z|^2} \di_{0_d}^{(2)}f(z^{(2)}) \di z .
\end{align*}
This implies the desired result.

\textbf{Step 2.}
Using polar coordinates, we can write
\begin{align*}  \int_\cC e^{-|z|^2} z \di z =  \int_0^{+\infty} \int_{S^g\cC} e^{-\rho^2} \rho \theta \rho^{d-1} \di \rho \di \sigma(\theta) & = \left(\int_0^{+\infty} e^{-\rho^2} \rho^{d} \di \rho \right)\underbrace{\int_{S^g\cC} \theta \di \sigma(\theta)}_{=v_\cC}.
\end{align*}
The change of variable $\tau = \rho^2$ yields that 
\[
\int_0^{+\infty} e^{-\rho^2} \rho^{d}  \di \rho = \Gamma\left(\frac{d+1}{2}\right) = c_{d}.
\]
In the end, we get
\[
\int_\cC e^{-|z|^2} z \di z = c_{d} v_\cC.
\]
In a similar way,
\begin{align*}
\int_\cC e^{-|z|^2} z^{(2)} \di z & = \int_0^{+\infty} \int_{S^g\cC} e^{-\rho^2} (\rho \theta)^{(2)} \rho^{d-1} \di \rho \di \sigma(\theta)  = \int_0^{+\infty} \int_{S^g\cC} e^{-\rho^2} \theta^{(2)} \rho^{d+1} \di \rho \di \sigma(\theta)\\
 & = \left( \int_0^{+\infty} e^{-\rho^2} \rho^{d+1} \di \rho \right)\underbrace{\int_{S^g\cC} \theta^{(2)} \di \sigma(\theta)}_{=v_\cC^{(2)}} = c_{d+1} v_\cC^{(2)}
\end{align*}
and
\begin{align*}
\int_\cC e^{-|z|^2} \di_{0_d}f(z)\di_{0_d}p(z) \di z & = \int_0^{+\infty} \int_{S^g\cC} e^{-\rho^2} \di_{0_d}f(\rho \theta)\di_{0_d}p(\rho \theta) \rho^{d-1} \di \rho \di \sigma(\theta)\\
& =  \int_0^{+\infty} \int_{S^g\cC} e^{-\rho^2} \di_{0_d}f( \theta)\di_{0_d}p( \theta) \rho^{d+1} \di \rho \di \sigma(\theta)\\
& = \left( \int_0^{+\infty}  e^{-\rho^2} \rho^{d+1} \di \rho  \right) \int_{S^g\cC} \di_{0_d}f( \theta)\di_{0_d}p( \theta) \di \sigma(\theta)\\
& = c_{d+1}  \int_{S^g\cC} \di_{0_d}f( \theta)\di_{0_d}p( \theta) \di \sigma(\theta).
\end{align*}
Combined with \eqref{eq:step1}, these yield \eqref{eq:eucl_result} as desired.
\end{proof}

\begin{remark}\label{rem:further} The previous proof may be easily modified to get the following: for any integer $N \ge 2$,  let $p \in \cC^{N}_{\ge 0}(\setB^d)$ and $f \in \cC^{N+1}(\setB^d)$ be such that
\[
 \max_{0 \le j \le N}  \sup_{\xi \in \setB^d}\|\di^{(j)}_{\xi}p \|_{op} + \max_{1 \le i \le N+1 }  \sup_{\xi \in \setB^d}\|\di^{(i)}_{\xi}f \|_{op}   < +\infty.
\]
Then for any cone $\mathcal{C}$ in $\setR^d$ and $\eta \in (0,1/2)$,
\[
L_t^{\cC,\eta}f(0_d) = \sum_{i=1}^{N+1} \sum_{j=0}^N \frac{t^{\frac{i+j}{2}-1}c_{d+i+j-1}}{i!j!} \int_{S^g\cC} \di_{0_d}^{(i)} f (\theta^{(i)})   \di_{0_d}^{(j)} p(\theta^{(j)}) \di \sigma(\theta) + O(t^{\frac{N-1}{2}}).
\]
\end{remark}

\begin{remark}
If $p(0_d)=0$, then $L_t^{\cC,\eta} f(0_d)$ always converges to $\displaystyle \int_\cC e^{-|z|^2} \di_{0_d}f(z)\di_{0_d}p(z) \di z.$
\end{remark}

\subsection{Conclusion}

Let us now explain how to reach the conclusion of Theorem \ref{th:1}. From Lemma \ref{lem:localisation} and Proposition \ref{prop:localized}, we get
\[
L_tf(x) = \frac{1}{t} \int_{\mathbb{B}^d_{t^{\eta}}\cap \tilde{F}_{0_d}\Omega} e^{-\frac{\|\xi\|^2}{t}} (\tilde{f}(0_d) - \tilde{f}(\xi))q(\xi)\di \xi + o\left( \frac{1}{\sqrt{t}}\right) +  O(t^{-d/2-1}e^{-t^{2 \eta -1}}) \qquad \text{as $t\to 0$.}
\]
From Proposition \ref{lem:tangent cones as epigraphs} and Proposition \ref{prop:at boundary of open sets, inward sector equals tangent cone}, we can replace $\tilde{F}_{0_d}\Omega$ by $I_{0_d}\bar{\Omega}$ in the previous domain of integration. Then we apply Proposition \ref{prop:key} to obtain that
\begin{align*}
    \frac{1}{t} \int_{\mathbb{B}^d_{t^{\eta}}\cap I_{0_d}\bar{\Omega}} e^{-\frac{\|\xi\|^2}{t}} (\tilde{f}(0_d) - \tilde{f}(\xi))q(\xi)\di \xi
\end{align*}
equals 
\[
- \frac{c_d}{\sqrt{t}} q(0_d) \partial_{v_{\mathcal{I}_{0_d}\bar{\Omega}}} \tilde{f}(0_d)  - c_{d+1} \bigg(q(0_d) A_{I_{0_d}\bar{\Omega}} \tilde{f}(0_d) +  [q,\tilde{f}]_{I_{0_d}\bar{\Omega}}(0_d)\bigg)  + O(\sqrt{t})
\]
as $t \downarrow 0$. But
\[
q(0_d) = p(\tilde{\exp}_x(0_x)) \sqrt{\det g(0_d)} = p(x),
\]
\begin{align*}
\partial_{v_{I_{0_d}\bar{\Omega}}} \tilde{f}(0_d) = d_{0_d}\tilde{f}(v_{I_{0_d}\bar{\Omega}}) & = d_xf \left( d_{0_d}\tilde{\exp}_x\left( \int_{S^g I_{0_d}\bar{\Omega}} \theta \di \sigma (\theta)\right)\right)\\
& =
d_xf \left( \int_{S^g I_{0_d}\bar{\Omega}} d_{0_d}\tilde{\exp}_x(\theta) \di \sigma (\theta)\right)\\
& =
d_xf \left( \int_{S^gI_xM} \theta \di \sigma(\theta)\right) = d_xf(v_g(x)) = \partial_{v_g(x)}f(x),
\end{align*}
where we have used Lemma \ref{prop:inward sectors correspond to inward sectors via charts} to perform the change of variable which provides us with the last line. Likewise, we obtain 
\[
A_\cC \tilde{f}(0_d) = A_gf(x),
\]
\begin{align*}
[q,\tilde{f}]_{I_{0_d}\bar{\Omega}}(x) = [p,f]_g(x).
\end{align*}
This concludes the proof of Theorem \ref{th:1}.

\section{Concentration estimates}\label{sec:concentration}

The goal of this section is to establish Theorem \ref{th:2}.


\subsection{\texorpdfstring{$\alpha$}{alpha}-Subexponential Random Variables}

We begin by defining the class of $\alpha$-subexponential random variables introduced by G\"otze, Sambale and Sinulis in \cite{GSS}.

\begin{definition}\label{def:alphasub}
Let $Z$ be a real-valued random variable. We say that $Z$ is $\alpha$-subexponential for some $\alpha > 0$ if there exist constants $K, C > 0$ such that :
\[
\mathbb{P}[|Z|\ge\epsilon] \le K\exp(-C{\epsilon}^{\alpha}) \qquad \forall \epsilon \ge 0.
\]
\end{definition}

\begin{remark}
    When $\alpha = 1$, the previous class coincides with classical subexponential random variables, while for $\alpha = 2$, it coincides with classical subgaussian random variables, see e.g.~\cite{Vershynin} for more details about these cases. Note also that $\alpha > 2$ implies subgaussian (i.e.~$\alpha = 2$). For values $\alpha < 1$, heavier tails are permitted, as in the case for Weibull random variables, for instance.
\end{remark}

The following lemma is useful for our purposes. We provide a quick proof for completeness.

\begin{lemma}\label{lem:alphasub}
    Let $Z$ be $\alpha$-subexponential. Let $W$ be an a.s.~bounded real-valued random variable, and $z\in \mathbb{R}$. Then both the product random variable $WZ$ and the translated random variable $Z-z$ are $\alpha$-subexponential.
\end{lemma}

\begin{proof}
Let $m>0$ be such that $|W|\le m$ a.s. Then for any $\epsilon \ge 0$,
\[
\mathbb{P}(|WZ| \ge \epsilon) = \mathbb{P}(|Z| \ge \epsilon/|W|) \le  \mathbb{P}(|Z| \ge \epsilon/m) \le K\exp(-C{(\epsilon/m)}^{\alpha}).
\]
This shows that $WZ$ is $\alpha$-subexponential. As for $Z-z$, note that $|Z|+|z| \ge |Z-z|$ implies the first inequality in
\[
\mathbb{P}(|Z-z| \ge \epsilon ) \le \mathbb{P}(|Z|+|z| \ge \epsilon ) = \mathbb{P}(|Z| \ge \epsilon - |z|)  \le K\exp(-C{(\epsilon-|z|)}^{\alpha}) \le K\exp(-(C/2^\alpha){\epsilon}^{\alpha}).
\]
\end{proof}



The next statement is taken from \cite[Corollary 1.4 and Theorem 1.5]{GSS}. It is a concentration result for sample means of $\alpha$-subexponential random variables.

\begin{theorem}\label{th:concentration}
    Let $Z_1, \dots, Z_n \sim Z$ be iid and mean-zero real valued random variables that are $\alpha$-subexponential for some $\alpha \in (0,2]$. Then there exist constants $c, C> 0$ such that for every $\epsilon \ge 0$,
    \begin{enumerate}
        \item if $\alpha \in (0,1]$, then
        \[\mathbb{P}\left(\left|\frac{1}{n}\sum_{i=1}^n Z_i\right| \ge \epsilon\right) \le C \exp\left( -c n^{\alpha} \epsilon^{\alpha} \right),\]
        \item if $\alpha \in (1,2]$, then
        \[
        \mathbb{P}\left(\left|\frac{1}{n}\sum_{i=1}^n Z_i\right| \ge \epsilon\right) \le C \exp\left( -c n^{\alpha/2} \epsilon^{\alpha} \right).
        \]
    \end{enumerate}
\end{theorem}

\begin{remark}
     Note that (1) matches up with the subexponential tail decay given by Bernstein's inequality in case $\alpha=1,$ while (2) coincides with the subgaussian tail decay of Hoeffding's inequality when $\alpha=2$. We refer to \cite{Vershynin} for a nice account on these two classical inequalities.
\end{remark}

\subsection{Convergence in probability}

In this section, we fall back onto our original setup, i.e.~we consider $\{X_i\}_{\mathbb{N}} \sim X$, a sequence of iid random variables taking values in a Riemannian manifold with kinks $(M,g)$. Assume the law $\mathbb{P}_X$ has a $\mathcal{C}^2(M)$ density function $p,$ and consider a function $f \in \cC^3(M)$ and a number $t>0$.

We are firstly interested in finding out the concentration of $L_{n,t}f(x)$ around its expected value $L_tf(x)$, for $x \in M$ being either an interior point or an LCDD border point. This is given by the following result.

\begin{proposition}
Assume \( f(X) \) is \(\alpha\)-subexponential for some \(\alpha \in (0,2]\). Then there exist constants \( C_1, C_2 > 0 \)  such that for all \( \epsilon \ge 0 \), 
\begin{enumerate}
        \item if $\alpha \in (0,1]$, then
        \[
        \mathbb{P} \left( \left| L_{n,t} f(x) - L_t f(x) \right| \ge \epsilon \right) 
        \le C_1 \exp \left( - C_2 \left( n\, t^{\frac{d}{2} + 1} \epsilon \right)^{\alpha} \right),
        \]
        \item if $\alpha \in (1,2]$, then
        \[
        \mathbb{P} \left( \left| L_{n,t} f(x) - L_t f(x) \right| \ge \epsilon \right) 
        \le C_1 \exp \left( - C_2 \left( \sqrt{n}\, t^{\frac{d}{2} + 1} \epsilon \right)^{\alpha} \right).
        \]
\end{enumerate}
Moreover, the constants \( C_1 \) and \( C_2 \) depend only on \( X \), \( f \), and \( \alpha \).
\end{proposition}

\begin{proof}
    Let us provide details for the case $\alpha \in (0,1]$ only, the other one being analogous. Consider the zero-mean real-valued random variables
    \[
    Z_i(t) = e^{-d^2(x,X_i)/t} (f(x)-f(X_i)) - t^{d/2+1}L_tf(x), \qquad i \ge 1.  \]
    We know from Lemma \ref{lem:alphasub} that these are $\alpha$-subexponential, hence we can apply Theorem \ref{th:concentration} : for any $\epsilon \ge 0$,
    \[
    \mathbb{P} \left( \left| L_{n,t} f(x) - L_t f(x) \right| \ge \epsilon \right) = \mathbb{P} \left(  \frac{1}{  t^{d/2+1}} \left| \frac{1}{n}\sum_{i=1}^n Z_i(t) \right| \ge \epsilon \right) \le  C_1 \exp \left( - C_2 \left( n\, t^{\frac{d}{2} + 1} \epsilon \right)^{\alpha} \right).
    \]

\end{proof}

Let us recall the operator
\[
\mathcal{L}_tf(x) \df -\frac{c_d}{\sqrt{t}}\left(  p(x) \, \partial_{v(x)}f(x)  + o(1)\right) - c_{d+1} \bigg( p(x) A_gf(x) +  [p,f]_g(x) \bigg)
\]
identified in Theorem \ref{th:1}. Since the latter differ from $L_tf(x)$ of a $o(\sqrt{t})$ term, we immediately deduce the following from the previous proposition.

\begin{corollary}
Assume \( f(X) \) is \(\alpha\)-subexponential for some \(\alpha >0\). Then there exist constants \( C_1, C_2 > 0 \)  such that for all \( \epsilon \ge 0 \), we have :
\begin{enumerate}
        \item if $\alpha \in (0,1]$, then
        \[
        \mathbb{P} \left( \left| L_{n,t} f(x) - \mathcal{L}_t f(x) \right| \ge \epsilon \right) 
        \le C_1 \exp \left( - C_2 \left( n\, t^{\frac{d}{2} + 1} \epsilon \right)^{\alpha} \right),
        \]
        \item if $\alpha \in (1,2]$, then
        \[
        \mathbb{P} \left( \left| L_{n,t} f(x) - \mathcal{L}_t f(x) \right| \ge \epsilon \right) 
        \le C_1 \exp \left( - C_2 \left( \sqrt{n}\, t^{\frac{d}{2} + 1} \epsilon \right)^{\alpha} \right).
        \]
\end{enumerate}
%The constants \( C_1 \) and \( C_2 \) depend only on \( X \), \( f \), and \( \alpha \).\footnote{{\color{red} details about that?}}
\end{corollary}


We are now in a position to prove (1) in Theorem \ref{th:2}. Consider $t_n \to 0$ such that \( \sqrt{n}\, t_n^{\frac{d}{2} + 1} \to \infty \) as \( n \to \infty \). Then
\[
C_1 \exp \left( - C_2 \left( n\, t^{\frac{d}{2} + 1} \epsilon \right)^{\alpha} \right)\to 0 \qquad \text{and} \qquad  C_1 \exp \left( - C_2 \left( \sqrt{n}\, t^{\frac{d}{2} + 1} \epsilon \right)^{\alpha} \right) \to 0 \qquad \text{as $n \to +\infty$}.
\]
This shows that
\[
\mathbb{P} \left( \left| L_{n,t_n} f(x) - \mathcal{L}_{t_n} f(x) \right| \ge \epsilon \right) \to 0 \qquad \text{as $n \to +\infty$}.
\]

\subsection{Almost sure convergence} Let us now prove (2) in Theorem \ref{th:2}. To this aim, recall that a sequence of real-valued random variables $\{Z_n\}$ completely converges to another real-valued random variable $Z$ if for any $\epsilon>0$,
    \[
    \sum_{n} \mathbb{P}(|Z_n - Z| \ge \epsilon) < +\infty.
    \]
It is easily seen from the first Borel--Cantelli lemma that complete convergence implies almost sure convergence. We shall need an elementary lemma.

\begin{lemma}\label{lem:elem}
    Let $\{b_n\}$ be a sequence of positive real numbers such that
    \[
    \frac{b_n}{\ln(n)} \stackrel{n\to +\infty}{\longrightarrow} +\infty \quad \text{and} \quad \sum_{n\ge 1} e^{-b_n} < +\infty.
    \]
    Then for any $\delta \in (0,1)$,
    \[
    \sum_{n\ge 1} e^{-\delta b_n} < +\infty
    \]
\end{lemma}

\begin{proof}
Take $\delta \in (0,1)$. For any $c>0$ there exists $N \in \mathbb{N}$ such that for any $n \ge N$,
\[
\frac{b_n}{\ln(n)} \ge c.
\]
For these integers $n$,
\[
e^{-\delta b_n} \le e^{-\delta c \ln(n)} = \frac{1}{n^{\delta c}} \, \cdot 
\]
Therefore, if $c > 1/\delta$,
\[
\sum e^{-\delta b_n} \le \sum \frac{1}{n^{\delta c}} < +\infty.
\]
\end{proof}

We can now prove (2) in Theorem \ref{th:2}. Consider $t_n \to 0$ such that $\left(\sqrt{n}\, t_n^{\frac{d}{2} + 1} \right)^{\alpha}/\ln(n)\to \infty$ as $n \to \infty$. For any $\epsilon >0$,
\begin{align*}
\sum_{n} \mathbb{P} \left( \left| L_{n,t_n} f(x) - \mathcal{L}_{t_n} f(x) \right| \ge \epsilon \right) & \le  C_1 \sum_{n}  \exp \left( - C_2 \left( n\, t^{\frac{d}{2} + 1} \epsilon \right)^{\alpha} \right)\\
& =  C_1 \sum_{n}  \exp \left( - b_n\epsilon^\alpha \right)
\end{align*}
with $b_n \df C_2 \left( n\, t^{\frac{d}{2} + 1} \right)^{\alpha}$. The assumption on $\{t_n\}$ implies that $b_n/\ln(n) \to \infty$ as $n\to \infty$, hence Lemma \ref{lem:elem} yields that 
\[
\sum_{n} \mathbb{P} \left( \left| L_{n,t_n} f(x) - \mathcal{L}_{t_n} f(x) \right| \ge \epsilon \right) \le \sum_{n}  \exp \left( - b_n\epsilon^\alpha \right) < +\infty.
\]
Thus $|L_{n,t_n}f(x) - \mathcal{L}_{t_n}f(x)|$ completely converges to $0$, thus it converges almost surely.



