\section{Proof of Theorem 1}
\label{app:proof}

The following proof is a direct copy of the proof of \citeauthor{liang_experimental_2024}'s (hereafter referred to as L\&B) Theorem 1 and is lightly adapted for our proposed ATE estimator $(\hat{\bar{\tau}}_t)$.

We begin by refreshing term definitions:
\begin{itemize}
    \item $\hat{S}_t := \sum_{i=1}^t\hat{\sigma}^2_i$
    \item $p_\text{min} := \text{min}(p_i^\text{MAD}(0), p_i^\text{MAD}(1))$
    \item $\delta_t$ is a decreasing, real-valued sequence $\delta_t \in (0, 1]$ s.t. $\delta_t = \omega(\frac{1}{t^{1/4}})$, where $\delta_t = \omega(\frac{1}{t^{1/4}})$ is equivalent to $1/\delta_t = o(t^{1/4})$
    \item $B_t := \sum_{i=1}^t \text{Var}[\hat{\tau}_i|\mathcal{F}_i]$
    \item $\eta$ is a hyper-parameter, the choice of which is discussed in Section 7 of L\&B
    \item $\alpha$ is a significance level; e.g. $\alpha = 0.05$
\end{itemize}
\textbf{Proof of Lemma A.1 (L\&B, Appendix 1)}
\begin{proof}
By Assumption 1 (L\&B) and our Assumption~\ref{ass:bounded_models}, 
\begin{align*}
    |\hat{\tau}_t| &= \left|\hat{\mu}_1(X_t) - \hat{\mu}_0(X_t) + \frac{\mathds{1}\{W_t=1\}(Y_t - \hat{\mu}_1(X_t))}{p_t^\text{MAD}(1)} - \frac{\mathds{1}\{W_t=0\}(Y_t - \hat{\mu}_0(X_t))}{p_t^\text{MAD}(0)}\right| \\
    &\leq 2N + \frac{M + N}{p_{\min}}.
\end{align*}
Next, since $|\tau_t| \leq 2M$, \[|\hat{\tau}_t - \tau_t| \leq 2(M+N) + \frac{M + N}{p_\text{min}},\] and thus
\begin{align*}
    (\hat{\tau}_t - \tau_t)^2 &\leq \left(2(M+N) + \frac{M + N}{p_{\min}}\right)^2 \\
    % &\leq \frac{C}{p_{\min}^2} \quad \text{where } C = (2(M+N) + M + N)^2 = (3M + 3N)^2 = 9(M + N)^2 \\
    &\leq \frac{9(M + N)^2}{p_\text{min}^2}.
\end{align*}

Now, note that for all $w$, $p_t^\text{MAD}(w) \geq \delta_t(1/2)$ and so $\frac{1}{p_t^\text{MAD}(w)}=o(t^{1/4})$, and $(\hat{\tau}_t - \tau_t)^2 = o(t^{1/2})$ a.s..

Finally, as shown by L\&B via their Assumption 2, $B_t = \Omega(t)$. Therefore, $B_t^\kappa = \Omega(t^\kappa)$. Set $\kappa > 1/2$. Then, there exists some $\tilde{t}$ such that for all $t \geq \tilde{t}$, $\mathds{1}\{(\hat{\tau}_t - \tau_t)^2 > (B_t)^\kappa\}=0$, and so, \[\sum_{i=1}^t\frac{\mathrm{E}[(\hat{\tau}_t - \tau_t)^2\mathds{1}\{(\hat{\tau}_t - \tau_t)^2 > (B_t)^\kappa\}]}{(B_t)^\kappa} < \infty \text{ a.s.}\]
\end{proof}

\noindent\textbf{Proof of Theorem~\ref{thm:thm_cs}}

\begin{proof}
    Under Assumptions 1 and 2 (L\&B), and our Assumption 1, Lemma A.1 of L\&B holds. Together, Lemma A.1 and L\&B Assumption 2 satisfy Theorem 2.5 in \citet{waudby-smith_time-uniform_2024}. Let \[V_t^*:=\sqrt{\frac{2(B_t \eta^2 + 1)}{t^2\eta^2}\text{log}\left(\frac{\sqrt{B_t \eta^2 + 1}}{\alpha}\right)}.\] By Steps 1 and 2 of the proof of Theorem 2.5 in \citet{waudby-smith_time-uniform_2024}, $(\hat{\bar{\tau}}_t \pm V_t^*)$ is a valid $(1-\alpha)$ asymptotic CS. As noted in Section~\ref{sec:ate_estimation}, \[\text{Var}[\hat{\tau}_i | \mathcal{F}_i] \leq \sigma_i^2 \quad \text{where} \quad \sigma^2_i:=\frac{(Y_i(1)-\hat{\mu}_1(X_i))^2}{p_i^\text{MAD}(1)}+\frac{(Y_i(0)-\hat{\mu}_0(X_i))^2}{p_i^\text{MAD}(0)}.\] Hence, $(\hat{\bar{\tau}}_t \pm \tilde{V}_t)$ where \[\tilde{V}_t:=\sqrt{\frac{2(S_t \eta^2 + 1)}{t^2\eta^2}\text{log}\left(\frac{\sqrt{S_t \eta^2 + 1}}{\alpha}\right)}\] is still a valid $(1-\alpha)$ asymptotic CS, where $S_t=\sum_{i=1}^t\sigma_i^2$. This holds because replacing $B_t$ with $S_t$ only makes the CS wider since $S_t \geq B_t$.

    As noted in Section~\ref{sec:ate_estimation}, an unbiased estimator for $\sigma_i^2$ is \[\hat{\sigma}^2_i := \frac{\mathds{1}\{W_i=1\}(Y_i - \hat{\mu}_1(X_i))^2}{(p_i^\text{MAD}(1))^2} + \frac{\mathds{1}\{W_i=0\}(Y_i - \hat{\mu}_0(X_i))^2}{(p_i^\text{MAD}(0))^2}.\]

    To establish the validity of the CS in Theorem~\ref{thm:thm_cs}, we must show that $\frac{1}{t}\hat{S}_t - \frac{1}{t}S_t \overset{a.s.}{\to} 0$. Then, Condition L-3 of Theorem 2.5 of \citet{waudby-smith_time-uniform_2024} is satisfied and we can conclude that $(\hat{\bar{\tau}}_t \pm \hat{V}_t)$ where \[\hat{V}_t:=\sqrt{\frac{2(\hat{S}_t \eta^2 + 1)}{t^2\eta^2}\text{log}\left(\frac{\sqrt{\hat{S}_t \eta^2 + 1}}{\alpha}\right)}\] is still a valid $(1-\alpha)$ asymptotic CS. First, note that
    \begin{align*}
        (\hat{\sigma}_i^2)^2 &\leq \left(\frac{(M + N)^2}{p_i^\text{MAD}(1)^2} + \frac{(M + N)^2}{p_i^\text{MAD}(0)^2}\right)^2 \\
        &= \frac{(M + N)^4}{p_i^\text{MAD}(1)^4} + \frac{(M + N)^4}{p_i^\text{MAD}(0)^4} + 2\frac{(M + N)^2}{p_i^\text{MAD}(1)^4} \\
        &\leq \frac{(M + N)^4}{(\delta_i/2)^4} + \frac{(M + N)^4}{(\delta_i/2)^4} + 2\frac{(M + N)^2}{(\delta_i/2)^4} \\
        &\leq (M + N)^4\left(2^4\frac{1}{\delta_i^4} + 2^4\frac{1}{\delta_i^4} + 2^5\frac{1}{\delta_i^4}\right) \\
        &= o(i)
    \end{align*}
    where the last line follows because $\frac{1}{\delta_i}=o(i^{1/4})$. Define $X_i = \hat{\sigma}_i^2 - \sigma_i^2$ and note that $X_i$ is a martingale difference sequence. Hence,
    \begin{align*}
        \mathrm{E}[X_i] &= \mathrm{E}[(\hat{\sigma}_i^2)^2] - (\sigma_i^2)^2 \\
        &\leq \mathrm{E}[(\hat{\sigma}_i^2)^2] \\
        &= o(i).
    \end{align*}
    So, $\frac{\mathrm{E}[X_i^2]}{i^2} = \frac{o(i)}{i^2}$ and thus $\sum_{i=1}^\infty\frac{\mathrm{E}[X_i^2]}{i^2} < \infty$. For instance, if $\delta_i = \frac{1}{i^a}$ for some $0 \leq a < 1/4$, then there exists a constant $C < \infty$ and $i_0 > 0$ such that for all $i > i_0$, $\frac{\mathrm{E}[X_i^2]}{i^2} \leq Ci^{4a-2}$, and since $4a-2 < -1$, $\sum_{i=1}^\infty \frac{\mathrm{E}[X_i^2]}{i^2} \leq C \sum_{i=1}^\infty i^{4a-2} < \infty$ by the p-series test.

    Then, by the SLLN for martingale difference sequences (Theorem 1 of \citep{csorgo_strong_1968}), we can conclude that \[\frac{1}{t}\sum_{i=1}^tX_i \overset{a.s.}{\to} 0.\] Hence, Condition L-3 of \citet{waudby-smith_time-uniform_2024} is satisfied and by Step 3 of the proof for Theorem 2.5 of \citet{waudby-smith_time-uniform_2024}, we can conclude that $(\hat{\bar{\tau}}_t \pm \hat{V}_t)$ is still a valid $(1-\alpha)$ asymptotic CS.

    To show that $\hat{V}_t \overset{a.s.}{\to} 0$, note that
    \begin{align*}
        \hat{\sigma}_i^2 &\leq \frac{(M + N)^2}{p_i^\text{MAD}(1)^2} + \frac{(M + N)^2}{p_i^\text{MAD}(0)^2} \\
        &\leq \frac{(M + N)^2}{(\delta_i/2)^2} + \frac{(M + N)^2}{(\delta_i/2)^2} \\
        &= 8(M+N)^2\frac{1}{\delta_i^2}.
    \end{align*}
    Hence, $\hat{S}_t \leq 8(M+N)^2\sum_{i=1}^t \frac{1}{\delta_i^2} = 8(M+N)^2\sum_{i=1}^t o(i^{1/2})$ a.s.. Therefore, there exists positive real numbers $D$ and $x_0$ such that for all $t \geq x_0$, $\hat{S}_t \leq D\sum_{i=1}^t i^{1/2} < D\sum_{i=1}^t t^{1/2} = Dt^{3/2}$, allowing us to conclude that $\hat{S}_t = O(t^\frac{3}{2})$.

    Next, we show that $\text{log}\left(\hat{S}_t\right) = o(t^{1/2})$ a.s.. For $t \geq x_0$, \[\frac{\text{log}\left(\hat{S}_t\right)}{t^{1/2}} \leq \frac{\text{log}(Dt^{3/2})}{t^{1/2}} = \frac{\text{log}(D) + (3/2)\text{log}(t)}{t^{1/2}}\] and $\frac{\text{log}(D) + (3/2)\text{log}(t)}{t^{1/2}} \to 0$ as $t \to \infty$. Therefore, $\log\left(\hat{S}_t\right) = o(t^{1/2})$ a.s. and we conclude that \[\hat{S}_t\text{log}\left(\hat{S}_t\right) = o(t^2) \; \text{a.s.}\] Hence, $\hat{V}_t = \frac{2(\hat{S}_t \eta^2 + 1)}{t^2 \eta^2}\text{log}\left(\frac{\sqrt{\hat{S}_t \eta^2 + 1}}{\alpha}\right) = o(1)$ a.s..
\end{proof}

As noted by L\&B, if $1/\delta_i$ was increasing at a rate faster than $i^{1/4}$ asymptotically, we are not guaranteed that $\hat{V}_t = o(1)$ a.s..

\section{MADCovar---extensions}
\label{app:mad_covar_extensions}

\subsection{Multiple treatments}

We formalize the results of Theorem~\ref{thm:thm_cs} for the setting with multiple treatment arms ($K\geq2$). We draw heavily from the exposition in Appendix C of \citeauthor{liang_experimental_2024}, and will refer the reader to this material for many of the details so as to avoid redundancy. 

We adopt the problem setting of the Generalized MAD (GMAD) laid out in \citeauthor{liang_experimental_2024}, Appendix C. In particular, $W_t \in \{0, 1, ..., K-1\}$ and GMAD has assignment probabilities $p_t^\text{MAD}(w) := \mathbb{P}_\text{MAD}(W_t=w|\mathcal{H}_{t-1})=\delta_t\left(\frac{1}{K}\right) + (1-\delta_t)p_t^\mathcal{A}(w)$.

For any pair of treatments $w, w' \in \{0, ..., K-1\}$, let $\tau_i(w, w')=Y_i(w)-Y_i(w')$ and define the ATE between $w$ and $w'$ up to unit $t$ as $\bar{\tau}_t:=\frac{1}{t}\sum_{i=1}^t\tau_i(w, w')$. So, under GMAD, our corresponding ATE estimator is \[\hat{\bar{\tau}}_t(w, w')=\frac{1}{t}\sum_{i=1}^t\hat{\tau}_i(w, w')\] where \[\hat{\tau}_i(w, w') := \hat{\mu}_w(X_i) - \hat{\mu}_{w'}(X_i) + \frac{\mathds{1}\{W_i=w\}(Y_i - \hat{\mu}_w(X_i))}{p_i^\text{MAD}(w)} - \frac{\mathds{1}\{W_i=w'\}(Y_i - \hat{\mu}_{w'}(X_i))}{p_i^\text{MAD}(w')}.\] We also have the corresponding upper bound on the variance: \[\mathrm{Var}[\hat{\tau}_i(w, w')|\mathcal{F}_i] \leq \sigma^2_i(w, w'), \text{ where } \sigma^2_i(w, w'):=\frac{(Y_i(w)-\hat{\mu}_w(X_i))^2}{p_i^\text{MAD}(w)}+\frac{(Y_i(w')-\hat{\mu}_{w'}(X_i))^2}{p_i^\text{MAD}(w')},\] and the analogous unbiased estimator of $\sigma_i^2(w, w')$: \[\hat{\sigma}^2_i(w, w') := \frac{\mathds{1}\{W_i=w\}(Y_i - \hat{\mu}_w(X_i))^2}{(p_i^\text{MAD}(w))^2} + \frac{\mathds{1}\{W_i=w'\}(Y_i - \hat{\mu}_{w'}(X_i))^2}{(p_i^\text{MAD}(w'))^2}.\] Finally, we let $S_t(w, w'):= \sum_{i=1}^t\sigma^2_i(w, w')$ and $\hat{S}_t(w, w'):=\sum_{i=1}^t\hat{\sigma}^2_i(w, w')$.

As in \citeauthor{liang_experimental_2024}, an analogous result of Theorem~\ref{thm:thm_cs} follows almost directly. As in the proof of Theorem~\ref{thm:thm_cs}, the only required modification to \citeauthor{liang_experimental_2024}'s proof is the additional constants introduced by our Assumption~\ref{ass:bounded_models} (Bounded Outcome Model Fitted Values). Otherwise, the remaining results and proof are identical; as such, we refer the reader to \citeauthor{liang_experimental_2024}, Appendix C, for a very thorough treatment of the details.

\subsection{Batched assignment setting}

We formalize the results of Theorem~\ref{thm:thm_cs} for the batched assignment setting, where the algorithm can only be updated at pre-defined points. Again, we draw heavily from the exposition in \citeauthor{liang_experimental_2024}, Appendix D, and will refer the reader to this material for many of the details.

We adopt the problem setting of the batched MAD, laid out in \citeauthor{liang_experimental_2024}, Appendix D. Let $\{(Y_i^{(j)}(w))_{w \in \mathcal{W}}\}$ be the set of all potential outcomes for unit $i$ in batch $j$. For any pair of treatments $w, w' \in \{0, ..., K-1\}$, we define the ATE \textit{within} a batch $j$ as: \[\tau_j^\text{batched}(w, w')=\frac{1}{B}\sum_{i=1}^B\left(Y_i^{(j)}(w) - Y_i^{(j)}(w')\right),\] and the corresponding unbiased estimator as \[\hat{\tau}_j^\text{batched}(w, w')=\frac{1}{B}\sum_{i=1}^B\hat{\tau}_i^{(j)}(w, w'),\] where \[\hat{\tau}_i^{(j)}(w, w') := \hat{\mu}_w^{(j)}(X_i) - \hat{\mu}_{w'}^{(j)}(X_i) + \frac{\mathds{1}\{W_i^{(j)}=w\}(Y_i^{(j)} - \hat{\mu}_w^{(j)}(X_i))}{p_j^{\text{MAD}_\text{batched}}(w)} - \frac{\mathds{1}\{W_i^{(j)}=w'\}(Y_i^{(j)} - \hat{\mu}_{w'}^{(j)}(X_i))}{p_j^{\text{MAD}_\text{batched}}(w')}\] and $\hat{\mu}_w^{(j)}$ is an arbitrary estimator of $\mathrm{E}[Y_i^{(j)}(w)|X=X_i,\mathcal{F}_{j}^\text{batched}]$. Then, for each $i=1, ..., B$, $\mathrm{Var}[\hat{\tau}_i^{(j)}(w, w')|\mathcal{F}_j^\text{batched}] \leq \sigma^{(j)2}_i(w, w')$, where \[\sigma^{(j)2}_i(w, w'):=\frac{\left(Y_i^{(j)}(w)-\hat{\mu}_w^{(j)}(X_i)\right)^2}{p_i^{\text{MAD}_\text{batched}}(w)}+\frac{\left(Y_i^{(j)}(w')-\hat{\mu}_{w'}^{(j)}(X_i)\right)^2}{p_i^{\text{MAD}_\text{batched}}(w')}.\] As a result, \[\hat{\sigma}_i^{(j)2}(w, w') := \frac{\mathds{1}\{W_i^{(j)}=w\}(Y_i^{(j)} - \hat{\mu}_w^{(j)}(X_i))^2}{(p_i^{\text{MAD}_\text{batched}}(w))^2} + \frac{\mathds{1}\{W_i^{(j)}=w'\}(Y_i^{(j)} - \hat{\mu}_{w'}^{(j)}(X_i))^2}{(p_i^{\text{MAD}_\text{batched}}(w'))^2}.\] Hence, \[\text{Var}[\hat{\tau}_j^\text{batched}(w, w')|\mathcal{F}_j^\text{batched}] = \frac{1}{B^2}\sum_{i=1}^B\text{Var}[\hat{\tau}_i^{(j)}(w, w')|\mathcal{F}_j^\text{batched}] \leq \frac{1}{B^2}\sum_{i=1}^B\sigma_i^{(j)2}(w, w').\] We define $S_b^\text{batched}(w, w') := \sum_{j=1}^b\frac{1}{B^2}\sum_{i=1}^B\sigma_i^{(j)2(w, w')}$ and $\hat{S}_b^\text{batched}(w, w') := \sum_{j=1}^b\frac{1}{B^2}\sum_{i=1}^B\hat{\sigma}_i^{(j)2}(w, w')$. Finally, we extend Assumption~\ref{ass:bounded_models} for the batched assignment setting.
\begin{assumption}{\textup{(Bounded (Realized) Outcome Model Fitted Values)}.} There exists $N \in \mathbb{R}$ such that \[\left|\hat{\mu}_w^{(j)}(X_t)\right| \leq N < \infty\] for all $j, i \in \mathbb{N}^+,w \in \mathcal{W}.$
\end{assumption}

As before, the remaining results and proof are identical to those in \citeauthor{liang_experimental_2024}; as such, we refer the reader to \citeauthor{liang_experimental_2024}, Appendix D, for a very thorough treatment of the details.

\section{Empirical confidence sequence coverage}

We empirically confirm the theoretical coverage guarantees provided by the $(1-\alpha)$ CSs for MADCovar ATE estimates. 

\subsection{Well-specified outcome model}

We modify the simulations in Section~\ref{sec:mad_covar} to have $K=6$ (five treatment arms), where potential outcomes are generated as i.i.d. draws from $Y_i(w) \sim \mathcal{N}(\mu_i(w), 1)$, where
\[\mu_i(k)
= 0.5
+ \beta_k\,\mathds{1}\{W_i = k\}
+ 0.3\,X_{1,i}
+ X_{2,i}
- 0.5\,X_{3,i},
\quad
k \in \{1,2,3,4,5\},
\]
and
\[
\beta_k =
\begin{cases}
0.1, & k=1,\\
0.2, & k=2,\\
0.3, & k=3,\\
0.4, & k=4,\\
0.5, & k=5.
\end{cases}
\]
We set Thompson sampling as $\mathcal{A}$, define $\delta_t = \frac{1}{t^{0.24}}$, and estimate the following (well-specified) outcome model $Y_i = \alpha + \beta_1 X_{1,i} + \beta_2 X_{2,i} + \beta_3 X_{3,i} + \epsilon_i$ with OLS. We run MADCovar for 10,000 iterations and estimate ATEs and corresponding 95\% CSs. We repeat the simulation 1,000 times and calculate the empirical coverage error (see Table~\ref{tab:coverage_comparison_well_specified}), defined as the proportion of times the nominal 95\% CSs for the MADCovar ATE estimates failed to contain the true ATE, averaged over the simulation runs.

\subsection{Misspecified outcome model}

We now demonstrate the robustness of MADCovar's coverage guarantees to misspecification in the outcome model. We modify the data generating process in the previous simulation to involve non-linear terms and an interaction term:
\[\mu_i(k)
= 0.5
+ \beta_k\,\mathds{1}\{W_i = k\}
+ 0.3\,X_{1,i}^2
+ X_{2,i}*X_{3, i}
- 0.5\,\mathrm{e}^{X_{3,i}}.
\] We estimate the (now misspecified) outcome model $Y_i = \alpha + \beta_1 X_{1,i} + \beta_2 X_{2,i} + \beta_3 X_{3,i} + \epsilon_i$ with OLS. As before, we run 1,000 repeated simulations and calculate the empirical coverage error rate at the chosen significance level, $\alpha = 0.05$ (see Table~\ref{tab:coverage_scenario_misspecified}).

