\title{A Note on Flexion Units}
\author{Hanamichi Kawamura}
\address[Hanamichi Kawamura]{Department of Mathematics, Graduate School of Science, Tokyo University of Science, 1-3 Kagurazaka, Shinjuku-ku, Tokyo, 162-8601, Japan}
