    \dot{Q}^{CS}_t = \frac{\Delta t^{CS}}{\Delta t} (n_c p_{\underline{T}, \underline{I}} - n_cU_{tn}\underline{I}) \hspace{1cm} \forall t \in \setT
    \label{eq:PEM1QCS}
\end{equation}
