  \caption{}
  \label{fig:SOECtempbarscolours}
  \end{subfigure}
  \caption{(a) SOE power and electricity price, and (b) temperature and operational state, for 5th Jan 2019 using 2.5 EUR/kg $\si{H_2}$}
